INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (77, 67, 100057, 'mahasiswa', 'Velda Bellaretta', 'Kakek saya dari ibu membatasi saya bertemu dengan ayah kandung saya, karena kejadian di masa lalu. Ibu kandung saya sudah meninggal pada agustus 2020, saya rasa kejadian di masa lalu yg tidak berhubungan dgn saya tidak perlu disangkut pautkan dengan saya. Padahal saya baru saja bertemu ayah kandung saya di november 2021 setelah perceraian orang tua saya di tahun 2004. Secara nafkah lahir, memang ibu kandung saya dan saya di nafkahi oleh kakek dari ibu saya. Tapi secara nafkah batin, saya juga perlu dari semua 2 belah pihak keluarga. Kalau diizikan saya ingin konseling dgn Bu Ulifa karena konseling saya yg pertama dengan beliau dgn topik yg hampir sama. Terima kasih', '2022-01-13 06:47:49');
