INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (135, 90, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Baik, Kak. Apakah Kak Maharani bersedia melakukan konseling tatap muka secara online melalui Google Meet? Apabila bersedia, jadwal kosong tercepat adalah pada hari Rabu, 19 Januari pukul 09.00. Kami tunggu konfirmasinya ya Kak.</p>', '2022-01-17 09:41:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (136, 34, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Baik, Kak. Untuk pelaksanaan konseling tatap muka saat ini dapat dilakukan secara daring melalui Google Meet. Terdapat jadwal kosong pada hari Selasa (besok) pukul 12.30, Kamis pukul 09.00 dan 10.00. Untuk link Google Meet akan kami kirimkan maksimal satu jam sebelum pelaksanaan konseling sesuai jadwal yang Kak Early pilih.</p>', '2022-01-17 09:46:20');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (137, 18, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Thank you for you message. E-Counseling only serves counseling for students. Information regarding student admissions can be accessed through <u>selma.ub.ac.id.</u> Thank you.</p>', '2022-01-17 10:07:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (138, 38, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Kami telah membaca deskripsi permasalahan Kak Alya. Apakah Kak Alya ingin meneruskan konseling melalui tatap muka daring atau secara online melalui email? Kak Alya bebas memilih jenis konseling yang diinginkan ya. Kami tunggu konfirmasinya 2x24 jam. Terima kasih.</p>', '2022-01-17 10:16:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (139, 43, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Selamat pagi, Kak Mupi. Apakah bisa dijelaskan secara detail permasalahan yang dialami terkait akademisnya? Terima kasih.</p>', '2022-01-17 10:18:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (140, 46, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Kami telah membaca permasalahan yang dialami oleh Kak Dinda. Apakah Kak Dinda ingin melanjutkan konseling tatap muka daring atau konseling melalui email? Sebelum itu tolong untuk melengkapi data diri Kak Dinda seperti nama, fakultas, dan alamat email UB. Kami tunggu konfirmasinya selama 2x24 jam. Terima kasih.</p>', '2022-01-17 10:20:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (141, 57, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Kami telah membaca deskripsi permasalahan Kak Niwa. Akan segera kami arahkan kepada konselor supaya segera mendapat tanggapan. Terima kasih.</p>', '2022-01-17 10:23:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (142, 34, 100026, 'mahasiswa', 'Early Brillianna Nur Laila Wahyudin', '<p>kak kalo di dua hari itu gabisa gimana ya ?</p>', '2022-01-17 10:45:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (143, 34, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Untuk minggu ini hanya tersisa jam tersebut, Kak. Apakah Kak Early mau menunggu untuk minggu depan? Apabila minggu depan, terdapat jadwal kosong pada hari Senin(11.00), Selasa (12.30), Kamis (09.00 dan 10.00), serta Jumat (09.00). Apakah Kak Early dapat melakukan konseling pada jam tersebut? Apabila Kak Early tidak bisa pada salah satu dari jam tersebut, kami sarankan untuk konseling melalui email terlebih dahulu.</p>', '2022-01-17 11:26:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (144, 92, 100066, 'mahasiswa', 'Nikita Khoirunnisa', '<p>215090200111050</p> <p>Saya maba yang merasa salah jurusan sejak awal masuk kuliah. Tapi saya mencoba untuk tetap survive karena saya satu2nya harapan keluarga. </p>', '2022-01-17 11:49:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (145, 34, 100026, 'mahasiswa', 'Early Brillianna Nur Laila Wahyudin', '<p>Sepertinya minggu depan hari senin jam 11 saja untuk konselingnya. Terimakasih </p>', '2022-01-17 11:51:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (146, 92, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Kami telah membaca deskripsi permasalahan Kak Nikita. Saat ini terdapat dua jenis konseling yaitu konseling online (melalui email) dan konseling tatap muka (Google Meet). Kak Nikita bebas untuk memilih jenis konseling yang diinginkan. Apabila menginginkan konseling tatap muka, terdapat jadwal kosong di hari Kamis, 20 Januari pukul 09.00. Kami tunggu konfirmasi dari Kak Nikita.</p>', '2022-01-17 11:55:19');
