INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (152, 95, 100069, 'mahasiswa', 'Devin Mahardhika Kristyawan', '<p>(205080101111014) Saya memiliki kecemasan berlebih dan ketika rasa cemas itu datang badan saya bisa sampai bergetar dan keluar keringat dingin. Saya juga memiliki hubungan percintaan yang saya rasa toxic tapi sangat susah bagi saya untuk lepas dari itu semua. Selain itu, saya juga memiliki adiksi terhadap penggunaan handphone dan juga pornografi, saya sangat ingin sekali untuk keluar dan sembuh dari adiksi tersebut. </p>', '2022-01-17 14:04:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (153, 53, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Kami sudah membaca detail permasalahan dari Kak Rahmadhani. Apakah Kak Rahmadhani ingin melanjutkan konseling online di sini atau tatap muka (Google Meet)? Apabila ingin melanjutkan konseling, mohon untuk melengkapi data diri dengan menyebutkan fakultas dan email UB yang digunakan. Kami tunggu konfirmasi selama 2x24 jam. Terima kasih.</p>', '2022-01-17 14:11:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (154, 53, 100045, 'mahasiswa', 'Rahmadhani Mahvirotul Zulkarnain', '<p>Rahmadhani.M.Z</p> <p>Fakultas MIPA</p> <p>email: unarmd_@student.ub.ac.id</p>', '2022-01-17 14:13:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (155, 58, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Kami telah membaca deskripsi permasalahan Kak Itamar. Akan segera kami arahkan kepada konselor supaya segera mendapat tanggapan. Terima kasih.</p>', '2022-01-17 14:13:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (156, 53, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Apakah Kak Ramadhani bersedia melakukan konseling secara tatap muka (Google Meet)? Apabila bersedia melakukan konseling tatap muka, terdapat jadwal kosong pada hari Selasa (besok) pukul 12.30 WIB. Apabila tidak bersedia, maka konseling konselor akan menanggapi permasalahan Kak Ramadhani di sini secara langsung. Terima kasih.</p>', '2022-01-17 14:15:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (157, 96, 100070, 'mahasiswa', 'Zahrah Puteri Yasmin', '<p>Halo, saya Zahrah Puteri Yasmin dengan NIM 215120201111053 :) Saya memiliki kepribadian yang ceria namun cenderung menyembunyikan semua masalah saya sendirian dan jarang sekali bercerita dengan orang lain. Hal ini sudah saya alami sejak kecil, dan saya sempat mengira saya mengidap distimia (depresi jangka panjang) karena saya merasa entah gejala depresi atau kecemasan berlebih ini berlangsung dari dulu hingga sekarang.</p> <p>Singkatnya, saya sekarang menjabat sbg salah satu ketua pelaksana projek dari radio fakultas fisip. Saya selalu memikirkan kemungkinan terburuk setiap harinya dan memikirkan hal-hal negatif yang akan terjadi. Niatnya hanya sebagai "warning" untuk diri sendiri. Tetapi habit ini malah merusak jam tidur saya. Saya selalu tidur dengan rentang waktu jam 3 sampai 5 pagi. Dan setiap bangun tidur, saya masih merasa lelah. Tidur benar2 tidak membantu sama sekali. Saya muak dengan pemikiran negatif ini, but all of these thoughts never get out of my mind. Terima kasih :)</p>', '2022-01-17 14:31:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (158, 59, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Kami telah membaca deskripsi permasalahan Kak Aisyah. Apakah Kak Aisyah bersedia untuk melakukan konseling secara tatap muka melalui Google Meet bersama konselor kami? Apabila bersedia, terdapat jadwal kosong pada hari Kamis (besok) tanggal 20 Januari pukul 10.00 WIB. Kami tunggu konfirmasi dari Kak Aisyah secepatnya ya. Terima kasih.</p>', '2022-01-17 14:38:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (159, 53, 100045, 'mahasiswa', 'Rahmadhani Mahvirotul Zulkarnain', '<p>halo kak apa boleh ganti jadwal? gapapa menunggu karena besok kebetulan ada workshop untuk mahasiswa akhir</p>', '2022-01-17 14:54:15');
