INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (213, 53, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Selamat siang, Kak Rahmadhani. Karena satu dan berapa hal, jadwal konseling Kak Rahmadhani akan kami pindah pada hari Selasa, 25 Januari pukul 12.30. Apakah Kak Rahmadhani bersedia? Terima kasih.</p>', '2022-01-18 13:53:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (214, 45, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Selamat siang, Kak Nur. Kami ingin memberi kabar bahwa terdapat jadwal kosong yang lebih cepat pada hari Kamis, 20 Januari (besok) pukul 10.00 WIB. Apakah Kak Nur bersedia untuk mengganti jadwal konseling ke hari tersebut?</p>', '2022-01-18 14:04:28');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (215, 55, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Kami telah membaca deskripsi permasalahan Kak Fauzi. Apakah Kak Firdauzi ingin melanjutkan konseling tatap muka daring melalui Google Meet bersama konselor kami? Akan kami carikan jadwal terdekat untuk konseling apabila Kak Firdauzi bersedia. Kami tunggu konfirmasinya. Terima kasih.</p>', '2022-01-18 14:06:52');
