INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (221, 23, 100014, 'mahasiswa', 'Latifah Winda Hamidah', '<p>Baik, akhir-akhir ini saya merasa seperti gampang terkejut padahal biasanya tidak, sering berpikiran macam-macam seperti bagaimana ke depannya serta keinginan untuk mati, terkadang saya juga gampang panik kalau ada sesuatu yang tidak sesuai dengan keinginan sehingga membuat saya terkadang tidak bisa fokus pada apa yang sedang saya kerjakan. Gampang lelah dan sering ingin menangis. Sering bermimpi tentang masa lalu juga.</p>', '2022-01-18 22:07:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (222, 45, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Baik, Kak. Kalau begitu konseling Kak Nur tetap dilaksanakan pada Kamis, 27 Januari ya. Terima kasih atas konfirmasinya.</p>', '2022-01-18 22:50:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (223, 101, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Halo, Kak Tripeny. Kami baru saja mendapat kabar dari konselor kami bahwa terdapat jadwal kosong terdekat di hari Kamis, 20 Januari pukul 10.00 WIB. Apakah Kak Tripeny bersedia untuk mengganti jadwal konseling di hari tersebut? Terima kasih.</p>', '2022-01-18 22:53:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (224, 31, 100023, 'mahasiswa', 'Carissa Farah Fauziah', '<p>Saya Ketergantungan pada 1 orang selama 2 tahun, sampai pada saatnya saya harus melepaskannya karena saya sadar hal ini salah dan harus saya hentikan. Ketika melepasnya, saya merasa panas dingin tidak jelas bahkan menyebutkan "tolong" untuk jangka waktu tertentu. Saya tidak ingin ketergantungan pada orang lain sampai seperti ini, tapi ketika saya mencoba melepasnya saya malah bertingkah aneh seperti yang saya jelaskan.</p>', '2022-01-18 23:09:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (225, 24, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Selamat pagi, Kak Arfad. Apakah kami dapat dibantu dengan melengkapi data diri seperti nama, fakultas, dan email UB, serta apakah ada tambahan untuk penjelasan permasalahan yang sedang Kak Arfad hadapi? Akan segera kami teruskan ke konselor apabila Kak Arfad ingin menambahkan deskripsi permasalahan. Terima kasih.</p>', '2022-01-19 08:49:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (226, 24, 100015, 'mahasiswa', 'Arfad Faddilah', '<p>Nama saya Arfad Faddilah, FHUB, email saya arfad_faddilah@student.ub.ac.id</p> <p>Untuk permasalahan sendiri saat ini yg saya rasakan saya sering merasa takut berlebihan yg berujung kepada depresi, saya sempat k psikiater dan di diagnosis depresi sedang karena saya sering ketakutan terhadap yang tidak jelas. Untuk saat ini saya sudah memilih ketakutan besar saya terhadap skripsi saya, saya punya pikiran takut apabila suatu saat ada kendala dalam pengerjaan skripsi, Walaupun hal tersebut blm terjadi saya sering merasa ketakutan. Lalu perasaan takut untuk balik lagi k Malang, sebelumnya saya memang di malang pernah punya pengalaman traumatis yg sampai saat ini sebenernya masih membekas dipikiran saya, lalu saya juga takut memulai hubungan sosial lgi dengan orang lain yang berhubungan dengan kampus</p>', '2022-01-19 09:24:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (227, 107, 100081, 'mahasiswa', 'Wanda Maytha Sary', '<p>Saya mahasiswa semester akhir yang hanya memiliki 1 semester lagi. Saya belum melakukan kegiatan penelitian dan ada mata kuliah yang belum tuntas. Saya sangat ingin berusaha di kesempatan terakhir ini tapi saya takut. Benar benar takut untuk menghadap dosen maupun akademik. Karena ketakutan saya itu saya selalu menunda nunda dan sampailah di kesempatan terakhir ini. Saya mau mencoba. Tapi takut saya sudah tidak diterima kehadirannya. Tolong.. bantu saya melepaskan ketakutan ini supaya saya bisa semangat berusaha</p>', '2022-01-19 11:02:40');
