INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (243, 107, 1, 'admin', 'ELLEN FLAMBOYAN ANGGIA KINSKY', '<p>konseling tatap muka dilakukan menggunakan google meet nanti akan saya carikan jadwal dan bila konseling online silahkan uraikan deskripsi permasalahannya kemudian akan saya teruskan kepada konselor dan akan mendapat balasan langsung dari konselor kami. </p>', '2022-01-19 11:46:02');
