INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (248, 55, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Baik, Kak untuk melanjutkan konseling mohon melengkapi data diri berupa nama, nim, fakultas, dan email UB. Terima kasih.</p>', '2022-01-19 16:23:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (249, 24, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Baik, terima kasih telah bercerita kepada kami. Deskripsi permasalahan Kak Arfad akan kami sampaikan kepada konselor. Kak Arfad akan mendapat jawaban melalui email dalam dua minggu. Apabila Kak Arfad belum mendapatkan jawaban, dapat menghubungi call centre kami di WhatsApp: 081358321308. Terima kasih.</p>', '2022-01-19 16:29:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (250, 42, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Untuk konseling online dilakukan melalui email. Kak Uswatul dapat mengirimkan deskripsi keadaan Kak Uswatul kepada kami untuk diteruskan kepada konselor dan kemudian mendapat jawaban. Sedangkan konseling tatap muka dilakukan secara daring melalui Google Meet. Apabila Kak Uswatul bersedia melakukan konseling tatap muka, maka akan kami carikan jadwal yang kosong. Konseling tatap muka dilakukan pada jam kerja setiap hari Senin - Jumat mulai pukul 09.00 - 15.00 WIB.</p>', '2022-01-19 16:32:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (251, 55, 100046, 'mahasiswa', 'Firdauzi Ongko Purwanto', '<p>Nama : Firdauzi Ongko Purwanto</p> <p>Nim : 17513107111033</p> <p>Fakultas : FKH</p> <p>E-mail UB :ferdauzy29@student.ub.ac.id</p> <p><br /></p>', '2022-01-19 16:38:29');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (252, 27, 100018, 'mahasiswa', 'Bayu Putra Negara', '<p>Bersedia, mba. Saya ingin dilakukan secara online karena belum di Malang</p>', '2022-01-19 19:35:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (253, 46, 100039, 'mahasiswa', 'Dinda', '<p>Terimakasih telah memberikan tanggapan dan saran kepada saya. Ada beberapa poin yang belum terlalu saya pahami. </p> <p>Saya akan mencoba konsultasi tatap muka minggu depan sesuai arahan. Minggu-minggu ini rasanya saya ingin menangis sepanjang waktu tapi saya tahan karena harus bekerja, saya bingung bagaimana meluapkannya. Saya minta tolong diarahkan bagaimana cara menghilangkan trauma dan ketakutan dari dalam diri saya. Saya agak sering susah tidur sampai harus minum obat agar bisa tidur beberapa hari lalu. </p> <p>Terimakasih telah bersedia menolong saya</p> <p><br /></p>', '2022-01-20 08:32:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (254, 27, 1, 'admin', 'ELLEN FLAMBOYAN ANGGIA KINSKY', '<p>kakak dapat memilih antara konseling tatap muka dilakukan menggunakan google meet nanti akan saya carikan jadwal dan bila konseling online silahkan uraikan deskripsi permasalahannya kemudian akan saya teruskan kepada konselor dan akan mendapat balasan langsung dari konselor kami.</p>', '2022-01-20 10:05:59');
