INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (262, 38, 100030, 'mahasiswa', 'Alya Sekar Medita', '<p>Mohon maaf baru membalas lebih dari batasan waktu yang ditentukan. Saya masih belajar penggunaan jasa konsul ini. Jika masih dapat diterima balasan saya, saya ingin konsul tatap muka daring</p>', '2022-01-20 20:26:24');
