INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (285, 114, 100086, 'mahasiswa', 'Ineke Permatasari', '<p>Nim : 206070400111005</p> <p>Saya gagal menikah bulan depan dg orang yg saya harapkan selama 5 th, sedari kecil tdk mendapatkan kasih sayang orang tua secara utuh, diasuh nenek yg meninggal saat usia saya 5 th, sekarang saya merasa setiap orang yg saya sayang akan pergi dan saya merasa lebih baik tdk hidup.</p>', '2022-01-22 07:52:40');
