INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (287, 116, 100088, 'mahasiswa', 'Ariq Atalla', '<p>205090407111017 , saya suka memikirkan hal yang tidak seharunya dipikirkan seperti hal hal kecil saya suka memikirkan plan terburuk dari hal jelek tersebut dan itu sangat menggangu saya dan membuat otak saya menjadi pusing, dan juga hal hal yang belum sepatutnya saya pikirkan seperti cicilan rumah, mobil, dll yang belum perlu dipikirkan dan itu mengganggu saya dalam berkehidupan sehari sehari</p>', '2022-01-23 02:21:05');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (288, 16, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Mohon maaf atas balasan kami yang terlambat. Apakah Kak Aliffadila bersedia menunggu untuk dua minggu lagi? Karena jadwal konselor di minggu depan sudah penuh. Apabila Kak Aliffadila bersedia, maka akan kami masukkan nama Kakak ke daftar tunggu untuk konseling melalui Google Meet. Terima kasih.</p>', '2022-01-23 17:54:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (289, 55, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Baik, Kak Firdauzi akan kami jadwalkan untuk konseling melalui Google Meet pada hari Kamis, 27 Januari pukul 10.00 WIB. Untuk link Google Meet akan kami berikan menjelang konseling akan dilakukan ya, maka kami mohon Kak Firdauzi untuk mengecek percakapan ini H-1 menjelang konseling. Terima kasih.</p>', '2022-01-23 17:56:30');
