INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (292, 56, 1, 'admin', 'ELLEN FLAMBOYAN ANGGIA KINSKY', '<p>Kami telah membaca deskripsi permasalahan dari Kak Vina. Apakah Kak Vina bersedia melakukan konseling? Saat ini pelaksanaan konseling dilakukan secara online dan tatap muka. Kakak bebas memilih pelaksanaan konseling yang nyaman untuk Kakak ya. Kemudian mohon dibantu untuk email ub, no hp, dan fakultas ya kak terimakasih</p>', '2022-01-24 08:57:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (293, 47, 1, 'admin', 'ELLEN FLAMBOYAN ANGGIA KINSKY', '<p>Kami telah membaca deskripsi permasalahan dari Kak Maulidia. Apakah Kakak bersedia melakukan konseling? Saat ini pelaksanaan konseling dilakukan secara online dan tatap muka. Kakak bebas memilih pelaksanaan konseling yang nyaman untuk Kakak ya. Kemudian mohon dibantu untuk email ub, no hp, dan fakultas ya kak terimakasih</p>', '2022-01-24 08:58:33');
