INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (295, 64, 1, 'admin', 'ELLEN FLAMBOYAN ANGGIA KINSKY', '<p>nanti akan kami carikan jadwal kak bila bersedia melakukan konseling via google meet, terdapat jadwal kosong untuk minggu depan apabila kakak ingin konseling online saja maka kakak bisa mendeskripsikan permasalahan kakak melalui chat ini kemudian akan kami berikan kepada konselor untuk ditanggapi secara langsung</p>', '2022-01-24 10:33:07');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (296, 117, 100089, 'mahasiswa', 'Inez Andriana Regita Cahyani', '<p>Halo, saya Inez Andriana NIM 205010107111073. Saya punya masalah mengenai self esteem saya yang rendah dan saya selalu ketakutan bertemu orang baru dan berada di lingkungan sosial. Saya juga seringkali merasa stress akan hal kecil, dan saya sering melakukan percobaan bunuh diri atau menyakiti diri saya sendiri.</p>', '2022-01-24 11:51:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (297, 118, 100090, 'mahasiswa', 'M. Ridho Alfaridzi', '<p>NIM : 175030207141011</p> <p>bingung dengan diri sendiri</p> <p>bingung dengan perasaan dengan keluarga</p> <p>bingung tentang masa depan</p> <p>bingung dengan akademink</p> <p>bingung seakan kepala mau pecah. terasa hampa tidak tau mau berbuat apa dan selalu bingung dengan kehidupan diri sendiri dan orang lain. punya teman seperti tidak punya teman. kehidupan yang hampa dan kosong</p>', '2022-01-24 12:49:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (298, 119, 100091, 'mahasiswa', 'Salsabila Riszki Anindita', '<p>Malam, saya mahasiswi fakultas hukum dengan NIM 195010101111002, saya 4 bulan terakhir ini mengalami overthinking berlebih terlebih masalah masa depan saya dan masalah pribadi saya dengan pacar saya, seringkali jika kambuh membuat saya deg"an dan memengaruhi pola makan serta tidur saya, hampir tiap hari menangis dan kadang susah untuk beraktivitas<br /></p>', '2022-01-24 19:00:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (299, 120, 100092, 'mahasiswa', 'Afif Muhammady', '<p>215091007111037<br />Apa penyebab adanya tulisan status tidak aktif di SIAM?</p> <p>Bagaimana cara mengaktifkan kemabali keterangan aktif di SIAM?</p> <p>Apakah ada contoh Surat untuk mengajukan permohonan aktif kemabali?</p>', '2022-01-24 23:04:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (300, 121, 100093, 'mahasiswa', 'Syafirra Putri Enrianto', '<p>NIM : 205120300111071</p> <p>Saya selalu merasa takut dan khawatir (namun cenderung lebih banyak rasa takut) pada tanggung jawab dan masalah yang saya hadapi. Saya pikir sebelumnya ini adalah perasaan yang umum bagi semua orang, tetapi saya merasa perasaan takut ini berat untuk saya... alhasil saya selalu mendistract diri dari segala tanggung jawab dan masalah..walapun sebelumnya saya pernah menghadapi tanggung jawab/masalah yang serupa-tetapi tetap saja saya selalu merasa takut berlebih hingga ingin menangis dan merasa berdebar-debar....Maka dari itu saya ingin konsul untuk memastikan apakah perasaan saya ini normal atau bagaimana? Krn saya sangat merasa tidak nyaman dengan diri saya</p>', '2022-01-25 04:33:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (301, 53, 100045, 'mahasiswa', 'IZZUL AL ZUHROTUN ARIZA', '<p>Konselee tidak hadir di konseling tatap muka</p>', '2022-01-25 12:54:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (302, 56, 100047, 'mahasiswa', 'Vina Irma Fitria', '<p>Saya ingin tatap muka</p> <p>email ub : vina_irma@student.ub.ac.id</p> <p>No hp : 089699535930</p> <p>Fakultas : Ilmu Kesehatan</p>', '2022-01-25 17:04:20');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (303, 64, 100055, 'mahasiswa', 'Gunawan dewantoro', '<p>permasalahn saya sedikit susah saya jelaskan. jadi saya sedikit ada problem dengan menjalankan skripsi saya namun saya tidak mengerti kenapa. lalu saat saya mencoba meditasi dan bertanya dengan diri saya, sepertinya saya ada rasa takut menjadi dewasa dan saya tidak mengerti apa yang memicu rasa takut ini karena background saya sedikit banyak cerita. saya lahir di keluarga broken home yang dimana dari kecil saya melihat orangtua berantem, saya bermasalah di sekolah dan di bully sama teman, saya anak terakhir dan anak yang kurang di banggakan/di harapkan karena saudara saya pintar dan tidak bermasalah sedangkan saya sebaliknya, keluarga saya pernah jatuh miskin dan saat smp kelas 3 saya sudah thinking suicidal.</p> <p><br /></p> <p>mungkin saya ada banyak problem namun problem yang ingin saya selesaikan adalah rasa takut akan dewasa. untuk permasalahn lainya nampaknya tidak urgent</p>', '2022-01-26 07:51:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (304, 64, 100055, 'mahasiswa', 'Gunawan dewantoro', '<p>permasalahn saya sedikit susah saya jelaskan. jadi saya sedikit ada problem dengan menjalankan skripsi saya namun saya tidak mengerti kenapa. lalu saat saya mencoba meditasi dan bertanya dengan diri saya, sepertinya saya ada rasa takut menjadi dewasa dan saya tidak mengerti apa yang memicu rasa takut ini karena background saya sedikit banyak cerita. saya lahir di keluarga broken home yang dimana dari kecil saya melihat orangtua berantem, saya bermasalah di sekolah dan di bully sama teman, saya anak terakhir dan anak yang kurang di banggakan/di harapkan karena saudara saya pintar dan tidak bermasalah sedangkan saya sebaliknya, keluarga saya pernah jatuh miskin dan saat smp kelas 3 saya sudah thinking suicidal.</p> <p><br /></p> <p>mungkin saya ada banyak problem namun problem yang ingin saya selesaikan adalah rasa takut akan dewasa. untuk permasalahn lainya nampaknya tidak urgent</p>', '2022-01-26 08:04:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (305, 122, 100095, 'mahasiswa', 'Naomi Hanifah Janitra Utomo', '<p>Nama saya Naomi Hanifah Janitra Utomo dengan NIM 205130100111004.</p> <p>Akhir-akhir ini saya merasa tidak bersemangat dalam beraktivitas dan sering menunda pekerjaan rumah. Hal yang biasanya menyenangkan bagi saya (contoh musik, film) terkadang terasa tidak menyenangkan lagi. Bahkan dalam mempelajari mata kuliah yang seharusnya menarik rasanya tidak bersemangat. Selain itu, jam tidur saya juga berubah (disaat seperti ini saya mudah lelah dan sering tidur). Di saat seperti ini saya juga sering berpikiran negatif mengenai diri sendiri (bahwa saya merasa tidak bisa apa-apa dan tidak berguna), bahkan akhir-akhir ini pikiran untuk bunuh diri sering muncul (saya sempat terpikir untuk membeli tali tambang). Pikiran seperti ini sebenarnya sudah ada sejak SMA, namun sekarang terasa lebih parah dari dulu.<br /></p> <p>Bagaimana caranya agar perasaan ini dapat berkurang? karena hal ini juga mempengaruhi nilai akademis saya. <br /></p>', '2022-01-26 09:07:28');
