INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (330, 104, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Halo, Kak Naura, mohon maaf atas balasan kami yang terlambat. Untuk saat ini terdapat jadwal kosong pada hari Kamis, 3 Februari pukul 09.00 WIB. Apakah Kak Naura bersedia dijadwalkan pada jam tersebut? Terima kasih.</p>', '2022-01-26 18:18:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (331, 123, 100097, 'mahasiswa', 'Gogon Islami', '<p>nim 185020200111076</p> <p>saya beberapa minggu terakhir mengalami masalah yang beruntun. ibu saya meninggal, sahabat saya pergi, pacar saya menghianati saya dengan sangat menyakitkan, ditambah permasalahan ekonomi, tugas akhir dan magang, hingga saya kehilangan semangat untuk beraktivitas. perasaan cemas, jantung deg-degan, tidak bisa tidur, hilang napsu makan, hingga kadang kesusahan bicara (seperti mau nangis terus2an). </p>', '2022-01-27 01:41:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (332, 55, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p><strong>[LINK KONSELING]</strong></p> <p>Selamat pagi, Kak Firdauzi. Berikut link untuk konselingnya nanti pukul 10.00 WIB ya.</p> <p><a href="https://meet.google.com/yen-hcyk-cvg">https://meet.google.com/yen-hcyk-cvg</a></p> <p>*NOTES*:</p> <p>1). Silakan mengakses link tersebut menggunakan *email UB*,</p> <p>2). Mohon menunggu di dalam ruangan 5 - 10 menit sebelum dimulai,</p> <p>3). Apabila dalam 5 menit setelah jam yang ditentukan belum terhubung dengan konselor, segera hubungi kami di call centre ini.</p> <p>Terima kasih, selamat bercerita </p>', '2022-01-27 07:03:56');
