INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (342, 55, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Selamat siang, Kak Firdauzi. Semoga konseling hari ini membantu.</p> <p>Untuk pengembangan layanan kami ke depannya, mohon bantuannya mengisi link evaluasi berikut menggunakan email UB atau email saat mendaftar yaa. Silakan diisi sebelum pukul 18.00 hari ini dan konfirmasi kembali apabila sudah diisi. Terima kasih, semoga sehat selalu </p> <p><a href="http://bit.ly/IKMkonseling">http://bit.ly/IKMkonseling</a></p>', '2022-01-27 11:46:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (343, 124, 100098, 'mahasiswa', 'Salsabila Nindya Armitha', '<p>NIM : 175040207111096</p> <p>Saya merasa cemas dengan skripsi saya, dengan dosen saya. Saya merasa jauh dari dosen saya. Saya takut untuk menghubungi beliau dan takut dengan balasan yg beliau berikan. Hal ini sudah terjadi beberapa bulan belakangan</p>', '2022-01-27 11:50:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (344, 95, 100069, 'mahasiswa', 'Devin Mahardhika Kristyawan', '<p>Nama : Devin Mahardhika Kristyawan<br />No HP : 081297649484<br />Fakultas : Fakultas Perikanan dan Ilmu Kelautan<br />Email UB : devinkristyawan@student.ub.ac.id</p>', '2022-01-27 12:11:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (345, 38, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Selamat siang, Kak Alya. Mohon maaf ternyata pada hari Selasa, 1 Februari sudah penuh. Apakah Kak Alya tidak keberatan apabila jadwal konseling diganti pada hari Kamis, 3 Februari pukul 09.00? Terima kasih.</p>', '2022-01-27 12:27:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (346, 23, 1, 'admin', 'ELLEN FLAMBOYAN ANGGIA KINSKY', '<p><br /></p> <p>Terima kasih atas kepercayaan Anda untuk menggunakan jasa layanan Konseling UB. Kami harap tanggapan yang diberikan oleh psikolog <strong>Ika Fitria, S. Psi., M. Psi., Psikolog</strong> akan bermanfaat untuk Anda ke depannya.</p> <p>Kami mohon kesediaan untuk mengisi link berikut ini sebagai bahan evaluasi:</p> <p><strong>bit.ly/konselingonlineUB</strong></p> <p>Data Anda akan kami rahasiakan.</p> <p><br /></p>', '2022-01-27 12:44:07');
