INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (360, 104, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Apakah Kak Naura tidak keberatan apabila konselornya laki-laki? Ada jadwal kosong pada jam 10.00 WIB di hari yang sama. Apabila tidak bisa, akan kami carikan jadwal lain di minggu kedua bulan Februari.</p>', '2022-01-27 18:48:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (361, 38, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Halo, Kak Alya. Kami mohon maaf lagi sebesar-besarnya karena pada jam tersebut konselor kami ada halangan. Apabila kami ganti menjadi hari Kamis, 10 Februari pukul 09.00 WIB apakah Kak Alya bersedia?</p>', '2022-01-27 18:51:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (362, 97, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Halo, Kak Reqyan. Mohon maaf atas balasan kami yang terlambat. Untuk saat ini terdapat jadwal kosong di dua minggu lagi. Apakah Kak Reqyan bersedia untuk menunggu? Sebelumnya mohon melengkapi data diri berupa nama lengkap, fakultas, dan alamat email UB. Terima kasih.</p>', '2022-01-27 19:01:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (363, 50, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Halo, Kak Rahmadian. Apakah Kak Rahmadian menginginkan konseling lebih lanjut? Untuk saat ini terdapat dua jenis konseling yaitu konseling online (melalui email) dan konseling tatap muka (melalui Google Meet). Kak Rahmadian bebas memilih konseling yang diinginkan ya. Kami tunggu konfirmasinya selama 2x24 jam. Terima kasih.</p>', '2022-01-27 19:03:20');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (364, 51, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Halo, Kak Hawwin. Apakah Kak Hawwin membutuhkan konseling lebih lanjut? Saat ini terdapat dua jenis konseling yaitu konseling online (melalui email) dan konseling tatap muka (melalui Google Meet). Kak Hawwin bebas memilih jenis konseling yang diinginkan ya. Kami tunggu konfirmasinya selama 2x24 jam. Terima kasih.</p>', '2022-01-27 19:05:10');
