INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (426, 134, 100107, 'mahasiswa', 'Ruth Aulia Herawati', '<p>195150607111007 Selamat malam bapak atau ibu yang membaca tiket saya ini sebelumnya saya Ruth Aulia dari Pendidikan Teknologi Informasi FILKOM angkatan 2019 ,Semenjak pandemi 2020 saya mulai merasakan semangat dan rasa ketertarikan saya dalam belajar dan berkuliah mulai kurang dan pada semester 5 saya malah merasa kehilangan semangat dalam belajar bahkan pada hal-hal yang saya sukai sebelumnya dan saya sering merasa hidup saya hampa dan mood saya sering sekali berubah-rubah dalam waktu yang cepat dan hal tersebut mengganggu saya dalam perkuliahan .Terima kasih bapak atau ibu selamat malam</p>', '2022-01-31 20:28:58');
