INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (496, 166, 100137, 'mahasiswa', 'Riza Maulana', '<p>Semester kemarin saya mengalami cukup banyak masalah yang kompleks. Hingga membuat saya bingung dan menyerah. Hal itu membuat saya menghilangkan kabar dari temen-temen saya termasuk kelompok dari tugas beberapa matkul. Akhirnya, saya merasa menyesal melakukan hal yang sudah saya lakukan tadi. Dan sampai sekarang, saya bingung harus berbuat apa untuk mempertanggung jawabkan hal yang sudah saya lakukan. Saya terus dihantui dengan rasa bersalah.</p>', '2022-02-13 15:17:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (497, 167, 100138, 'mahasiswa', 'Vivid Ayu Trihana', 'NIM : 215060400111060 Saya terkadang secara tiba-tiba merasakan cemas, panik, khawatir, takut dan merasa tidak tenang, disertai tubuh yang bergemetar. Beberapa kali saya dapat menahannya dan mereda. Namun, ada saat dimana saya sudah tidak kuat menahan dan apa yang saya rasakan meledak. Jika itu terjadi, saya akan menangis, menjerit, berteriak dan berpotensi untuk menghancurkan barang di sekitar saya. Hal ini ditambah ada keinginan untuk melukai diri sendiri dan bunuh diri. Namun, untuk sekarang saya masih sadar untuk tidak mengambil pilihan itu sekalipun rasa sakit yang saya rasakan sangat menyiksa. Tapi, saya sangat takut apabila hal ini terus terjadi, suatu saat nanti saya benar-benar mengambil pilihan itu.', '2022-02-13 19:01:04');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (498, 168, 100139, 'mahasiswa', 'Eka Yunita Herawati', '<p>Setiap hari saya sedih, saya mudah tersinggung. Saya benci semua orang dan saya lebih benci diri saya. Saya mau kabur dan tidak mau berhubungan dengan siapapun. Saya ingin cepat mati. </p>', '2022-02-13 19:47:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (499, 169, 100140, 'mahasiswa', 'Gandhisa Septry Melanie', '<p>215020200111008, Perselingkuhan yang dilakukan orang tua saya sejak kecil membuat saya cukup tertekan sehingga ada begitu banyak keinginan untuk melakukan hal yang tidak baik kepada yang bersangkutan. Hal tersebut terjadi karena saya merasa tidak adil, dengan adanya hubungan itu keadaan keluarga saya menjadi retak sedangkan pihak yang berselingkuh baik-baik saja. Bahkan keluarganya tidak tahu tentang adanya hubungan perselingkuhan tersebut. Selain itu, ada beberapa masalah lainnya yang membuat saya stres. Maka dari itu, saya tidak memilih kategori konseling masalah keluarga, melainkan pribadi.</p>', '2022-02-13 21:30:01');
