INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (640, 239, 100208, 'mahasiswa', 'Attala Bimo Bagaskoro Subroto', '<p>Jadi saya belakangan ini kebanyakan pikiran, mulai dari keluarga, kuliah, pertemanan, ampe perbucinan. Saya masi ga ketemu jalan kluarnya, selalu muter2 di kepala </p>', '2022-03-05 16:25:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (641, 240, 100209, 'mahasiswa', 'Jasmine Amarta Fitri Prasasti', '<p><br />Permasalahan saya adalah saya sering tiba-tiba sedih &amp; tiba-tiba marah tapi kadang saya juga tiba-tiba drained emotionally. Ketika saya sedang marah dan sedih, saya sering berpikir untuk mengakhiri hidup saya. Saya sudah berkali-kali melakukan selfharm dengan pecahan kaca, gunting, dan tak jarang saya menjambak rambut saya sendiri. Saya pikir semua ini karena mood saya yang sebentar lagi akan datang waktu menstruasi, tapi ternyata tidak. Selain itu, saya juga sering muntah karena panik, sehingga beberapa kali hal tersebut menganggu saya ketika saya sedang belajar di kelas.</p>', '2022-03-05 17:19:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (642, 241, 100210, 'mahasiswa', 'Kevin Handy', '<p>215110407111002</p> <p>Sudah sejak lama mengalami ketidakstabilan mood (mendadak sedih dan "gloomy"). Namun, belakangan ini semakin parah dan mulai mengganggu karena selalu susah fokus ketika mengalami ini</p>', '2022-03-05 21:11:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (643, 124, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Selamat pagi, Kak Salsabila.</p> <p>Kami telah membaca deskripsi yang dikirimkan. Apakah Kak Salsabila ingin melanjutkan konseling bersama kami?</p> <p>Kami tunggu konfirmasinya selama 2x24 jam ya.</p> <p><br /></p> <p>Terima kasih.</p>', '2022-03-06 09:33:50');
