INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (649, 230, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Selamat pagi, Kak Yofy.</p> <p>Kami mohon maaf karena pada hari Senin konselor berhalangan hadir, sehingga jadwal konseling Kak Yofy kami pindah di hari Kamis, 10 Maret pukul 10.00 WIB. Apakah Kak Yofy bersedia melakukan konseling pada jam tersebut?</p> <p>Terima kasih.</p>', '2022-03-06 11:19:25');
