INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (657, 246, 100050, 'mahasiswa', 'Aisyah Pradjna Paramita S', 'Saya kembali kehilangan motivasi dan beberapa solusi yang saya dapatkan di konseling sebelumnya tidak terlalu bisa mendorong saya. Saya mulai menunda pekerjaan hingga telat dari jadwal di kumpulkan dan belum dikerjakan, walaupun ada sedikit tugas yang selesai saya kerjakan. Saya juga tidak terlalu mendengarkan kuliah, hanya hadir saja. Kadang saya tidak ingin bangun dan lebih memilih meninggalkan kelas untuk tidur. Saya juga kadang merasa ingin menangis tanpa sebab tertentu yang spesifik.', '2022-03-07 08:34:17');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (658, 247, 100210, 'mahasiswa', 'Kevin Handy', 'Belakangan ini sering mengalami ketidakstabilan mood yang mengganggu. Hal ini sudah mulai mengganggu keseharian saya', '2022-03-07 10:16:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (659, 230, 1, 'admin', 'IZZUL AL ZUHROTUN ARIZA', '<p>Selamat pagi, Kak Yofy.</p> <p>Kami baru mendapat kabar dari konselor kami bahwa konseling akan dimajukan menjadi jam 08.30 di hari yang sama. Apakah Kak Yofy keberatan apabila waktu konseling dimajukan?</p> <p>Terima kasih.</p>', '2022-03-07 10:31:45');
