INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (964, 436, 100390, 'mahasiswa', 'Ayesha Alifa Anugrahani', '<p>Saya sudah konseling dengan BKM FISIP namun konselor menyarankan saya utk ke psikiater, sedangkan di BKM FISIP tidak ada psikiater. </p>', '2022-06-07 15:00:35');
