INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (981, 445, 100396, 'mahasiswa', 'Octadila Laily Anggraeni', '<p>Saya adalah Dosen Luar Biasa di Departemen Akuntansi FEB UB.<br />Selain mengajar, saya juga diperbantukan di beberapa tim kerja sejak 2020.<br />Alhamdulillah saya dipercaya dan menjadi orang kepercayaan beberapa pihak, terutama departemen akuntansi dalam menghandle data-data.</p> <p>Sejak satu bulan ini, saya merasa saya bekerja sendiri, dan saya merasa tim kerja saya tidak melakukan kerja tim. Saya berjalan sendiri dengan bawaan tugas-tugas yg banyak, sedangkan yang lain masih bisa jalan-jalan, bercanda, scroll sosmed saat bekerja.<br />Saya merasa ditinggal sendiri.<br /></p>', '2022-06-08 14:49:41');
