INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1073, 485, 1, 'admin', 'Isyraq QurratulAini', '<p>Selamat siang. Apakah Kak Amelia masih ingin melanjutkan konseling ini?</p> <p>Kebetulan karena Kak Amelia adalah mahasiswa FISIP, kami ingin memberitahu bahwa FISIP memiliki badan konseling sendiri yaitu Badan Konseling Mahasiswa (BKM). Sehubungan dengan antrian panjang di Layanan Konseling UB, apakah Kak Amelia bersedia kami arahkan untuk konseling di BKM FISIP?</p> <p>Pendaftaran di BKM bisa dilakukan melalui tautan berikut:</p> <p><a href="http://bit.ly/konselingfisip" target="_blank">http://bit.ly/konselingfisip</a></p> <p>Langkah pendaftaran:</p> <p>- Schedule yang tersedia adalah schedule untuk satu bulan. Klien dapat memilih tanggal sesi konseling yang diinginkan dan dapat memilih ingin konseling dengan konselor dosen atau konselor sebaya.</p> <p>- Jika sudah, klien akan menerima notifikasi agenda meeting.</p> <p>- Apabila pilihan sesi disetujui, klien akan dihubungi oleh BKM melalui email dan diarahkan untuk mengisi formulir pendaftaran.</p> <p>- Apabila pilihan sesi tidak disetujui, klien akan dihubungi oleh BKM melalui email dan diarahkan untuk memilih tanggal lain yang tersedia.</p> <p>Terima kasih</p>', '2022-07-04 10:19:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1074, 484, 1, 'admin', 'Isyraq QurratulAini', '<p>Selamat siang. Apakah Kak Amelia masih ingin melanjutkan konseling ini?</p> <p>Kebetulan karena Kak Amelia adalah mahasiswa FISIP, kami ingin memberitahu bahwa FISIP memiliki badan konseling sendiri yaitu Badan Konseling Mahasiswa (BKM). Sehubungan dengan antrian panjang di Layanan Konseling UB, apakah Kak Amelia bersedia kami arahkan untuk konseling di BKM FISIP?</p> <p>Pendaftaran di BKM bisa dilakukan melalui tautan berikut:</p> <p><a href="http://bit.ly/konselingfisip" target="_blank">http://bit.ly/konselingfisip</a></p> <p>Langkah pendaftaran:</p> <p>- Schedule yang tersedia adalah schedule untuk satu bulan. Klien dapat memilih tanggal sesi konseling yang diinginkan dan dapat memilih ingin konseling dengan konselor dosen atau konselor sebaya.</p> <p>- Jika sudah, klien akan menerima notifikasi agenda meeting.</p> <p>- Apabila pilihan sesi disetujui, klien akan dihubungi oleh BKM melalui email dan diarahkan untuk mengisi formulir pendaftaran.</p> <p>- Apabila pilihan sesi tidak disetujui, klien akan dihubungi oleh BKM melalui email dan diarahkan untuk memilih tanggal lain yang tersedia.</p> <p>Terima kasih</p>', '2022-07-04 10:20:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1075, 484, 1, 'admin', 'Isyraq QurratulAini', '<p>Selamat siang. Apakah Kak Regina masih ingin melanjutkan konseling ini?</p> <p>Kebetulan karena Kak Regina adalah mahasiswa FISIP, kami ingin memberitahu bahwa FISIP memiliki badan konseling sendiri yaitu Badan Konseling Mahasiswa (BKM). Sehubungan dengan antrian panjang di Layanan Konseling UB, apakah Kak Regina bersedia kami arahkan untuk konseling di BKM FISIP?</p> <p>Pendaftaran di BKM bisa dilakukan melalui tautan berikut:</p> <p><a href="http://bit.ly/konselingfisip" target="_blank">http://bit.ly/konselingfisip</a></p> <p>Langkah pendaftaran:</p> <p>- Schedule yang tersedia adalah schedule untuk satu bulan. Klien dapat memilih tanggal sesi konseling yang diinginkan dan dapat memilih ingin konseling dengan konselor dosen atau konselor sebaya.</p> <p>- Jika sudah, klien akan menerima notifikasi agenda meeting.</p> <p>- Apabila pilihan sesi disetujui, klien akan dihubungi oleh BKM melalui email dan diarahkan untuk mengisi formulir pendaftaran.</p> <p>- Apabila pilihan sesi tidak disetujui, klien akan dihubungi oleh BKM melalui email dan diarahkan untuk memilih tanggal lain yang tersedia.</p> <p>Terima kasih</p>', '2022-07-04 10:20:12');
