INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1156, 551, 100492, 'mahasiswa', 'Khoerul Umam', '<p>NIM : 225120307111122</p> <p>Jadi aku maba dan aku bener-bener over takut sama ospek offline terutama ospek fakultas, hampir setiap hari nangis 4 sampai 5 kali karena takut ospek. Takut dibentak, takut dimarahin, takut diteriakin, tapi jatuhnya terlalu over takut karena tiap jam kepikiran, tiap malem kepikiran sampe nangis</p>', '2022-08-18 12:57:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1157, 355, 1, 'admin', 'Isyraq QurratulAini', '<p>Terima kasih atas konfirmasinya. Sebelumnya, apakah Kak Janice ada nomor WhatsApp yang dapat kami hubungi untuk mempermudah komunikasi dua arah?</p>', '2022-08-18 13:03:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1158, 551, 100492, 'mahasiswa', 'Khoerul Umam', '<p>dan karena merasa over takut, rasanya ga bisa fokus dan susah untuk belajar dan membiasakan diri. Merasa ga punya energi buat ngapa-ngapain dan pengen pulang/ ga betah. selalu nangis di kamar setiap hari karena selalu kepikiran</p>', '2022-08-18 13:25:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1159, 552, 100493, 'mahasiswa', 'SARI FITRI RAFIQOH', '<p>NIM : 225080307111003</p> <p>Permasalahan terkait dengan metode pembelajaran dan cara mengatur jadwal yang baik</p> <p><br /></p>', '2022-08-18 14:02:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1160, 553, 100494, 'mahasiswa', 'Kautsarratu Athaya Zayyannarantis', '<p>Perkenalkan nama saya Kautsarratu Athaya Z. biasa dipanggil Kosa/Kautsa. Saya adalah mahasiswa Prodi Teknik Informatika, Fakultas Ilmu Komputer dengan NIM 195150200111003. Saya ingin berkonsultasi terkait masalah akademi/keluarga/pribadi saya. Sebenarnya permasalahan saya berangkat dari masalah keuangan keluarga saya. Meskipun saya sudah mendapatkan beasiswa bidikmisi. Tetap saya biaya tersebut belum cukup untuk memenuhi kebutuhan sebagai mahasiswa. Sebelumnya saat pandemi mungkin masih bisa mencukupi karena tidak perlu membayar kos atau biaya makan. tetapi karena mulai semester ini sudah mulai offline maka saya juga harus membayar kos dan juga uang makan. 600 ribu/bulan tentu bisa cukup jika DIPAKSA untuk berhemat. Namun jika dipukul rata KOS an dengan harga 500 ribu/ bulan hanya sisa 100 ribu/ bulan untuk BIAYA MAKAN, masih ada juga kebutuhan lain yang mendesak seperti transportasi (ojol, angkot), kuota, dll. Apalagi saya jarang mendapatkan tambahan uang saku dari orang tau karena orang tua juga masih terbebani hutang. Jika ditanya memang sebelum pandemi bagaimana saya mendapatkan uang saku tambahan? Saya mendapatkan uang saku dari wali yang sekarang sudah meninggal. Saya ingin sekali part time tetapi karena saya tidak memiliki kendaraan pribadi jadi agak susah dan harus mengandalkan transportasi umum (Saya takut malah menganggu kuliah). Selain itu untuk part time di lingkungan kampus juga saya sangat sulit untuk mencari informasinya. Saya juga mencoba mencari-cari internship remote agar saya tetap bisa menjalaninya sambil kuliah namun habisnya nihil. Saya takut malah menjadi beban keluarga jika terus melanjutkan kuliah, kira-kira saya harus bagaimana ya?</p>', '2022-08-18 16:42:41');
