INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1351, 696, 100173, 'mahasiswa', 'Muhamad Ghifari', '<p>Nama : Muhamad Ghifari</p> <p>NIM : 204140314111018</p> <p>Saya seseorang yang mudah mood nya berubah, awalnya senang bisa saja tiba tiba marah karena hal sepele</p> <p>Lalu seseorang yang mudah marah akan hal. Sepele dan susah membendung nya. Apakah ini tidak wajar? </p> <p>Mohon arahannya bapak/ibu</p>', '2022-09-22 06:40:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1352, 697, 100624, 'mahasiswa', 'Razzaqi Hatmawira Rabbani Raharto', '<p>Saya Razzaqi Hatmawira R R, NIM 225050101111028, dari fakultas peternakan angkatan 2022. Saya merasa masalah keluarga saya yang tidak harmonis menghambat motivasi dan kinerja saya dalam hal akademis. Kondisi keluarga saya: Saya dan keluarga saya tinggal di rumah nenek saya yang baru saja meninggal bulan yang lalu. Selama saya hidup, saya belum pernah merasakan rasanya memiliki rumah sendiri karena ayah saya yang terlalu nyaman menumpang tempat tinggal mertuanya. Hubungan ayah dan ibu saya semakin tahun semakin merenggang dan sudah mulai ada pembicaraan mengenai perceraian. Setiap hari saya dihadapi: ibu sehari-hari mengunci diri di kamar dan menghabiskan waktunya hanya menonton drama tanpa berinteraksi dengan keluarga, ayah saya juga sering mengunci diri di kamar untuk menghabiskan waktu "berzikir" tanpa memedulikan kondisi keluarga yang secara finansial terbatas, kakak saya yang harus membagi atensinya untuk membantu saya dan adik saya dalam mengurus rumah sehari-hari sembari berkuliah di UT, tante saya dari pihak ayah saya sekarang membawa berbagai permasalahan personalnya ke rumah dan sekarang menumpang tempat tinggal karena masih menunggu mencari pekerjaan, om saya dari pihak ibu saya juga pindah tinggal di rumah semenjak pandemi dan jaramg akur dengan ibu saya. Saya merasa tidak memiliki support system yang baik dan keluarga saya memiliki beragam masalah, bagaimana sebaiknya saya tetap termotivasi untuk berkuliah?</p>', '2022-09-22 10:35:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1353, 641, 100574, 'mahasiswa', 'Dewa Ayu Putu Tarisha Prima Dewi', '<p>Saya sering merasakan panik ketika mengerjakan skripsi, ketika saya panik saya merasakan brain freeze</p>', '2022-09-22 11:02:15');
