INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1392, 731, 100299, 'mahasiswa', 'Annisa Nuria', '<p>Selamat malam, sebelumnya semoga ada tahap lanjutan setelah saya mengisi pendaftaran ini karena saya sudah mendaftar sejak liburan semester genap namun sampai sekarang belum ada tindak lanjut</p> <p>Sejak tahun lalu saya rutin kontrol ke psikiater karena ada sedikit permasalahan, namun karena sudah luring dan tidak mungkin pulang satu bulan sekali jadi saya hanya mendapatkan obat tambahan. Namun sebenarnya saya juga butuh tempat cerita. Terima kasih </p>', '2022-09-29 18:49:40');
