INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1476, 807, 100724, 'mahasiswa', 'Jennifer Aishah Ratu Bernardy', '<p>saya terkadang jadi keseringan tidur atau saat uts pun saya susah untuk mau belajar, saya juga merasa saya tidak mempunyai kelebihan apa2 tidak ada yang bisa dibanggakan, tidak ada yang suka dengan saya dan saya juga kerap kali takut untuk menghadapi kehidupan selanjutnya jika umur saya bertambah tua, saya takut tidak sanggup, saya juga ingin sering kali bercerita dengan teman tapi ujungnya akan saya pendam jadi saya agak sedikit kelelahan, saya tidak tahu mau bercerita dengan siapa lagi selain ke konseling UB, saya juga butuh masukan untuk hidup saya yang lebih baik, karena selama ini saya hanya mengabaikan tapi tidak tahu bagaimana cara menyembuhkannya</p>', '2022-10-19 23:14:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1477, 807, 100724, 'mahasiswa', 'Jennifer Aishah Ratu Bernardy', '<p>saya terkadang jadi keseringan tidur atau saat uts pun saya susah untuk mau belajar, saya juga merasa saya tidak mempunyai kelebihan apa2 tidak ada yang bisa dibanggakan, tidak ada yang suka dengan saya dan saya juga kerap kali takut untuk menghadapi kehidupan selanjutnya jika umur saya bertambah tua, saya takut tidak sanggup, saya juga ingin sering kali bercerita dengan teman tapi ujungnya akan saya pendam jadi saya agak sedikit kelelahan, saya tidak tahu mau bercerita dengan siapa lagi selain ke konseling UB, saya juga butuh masukan untuk hidup saya yang lebih baik, karena selama ini saya hanya mengabaikan tapi tidak tahu bagaimana cara menyembuhkannya</p>', '2022-10-19 23:15:23');
