INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1479, 808, 100725, 'mahasiswa', 'Maysandra Dwi Sutyaseh', '<p>185030801111013</p> <p>Tidak bisa menangis saat sedang merasa sendiri, tidak bisa tertawa lepas saat sedang bahagia, tidak bisa menjadi diri sendiri selalu terbayang menjadi sosok yg tegar dan ceria </p>', '2022-10-20 10:50:43');
