INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1608, 934, 100829, 'mahasiswa', 'Erika Rahmadea', '<p>215040100111127</p>', '2022-12-01 09:22:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1609, 935, 100830, 'mahasiswa', 'Salsabila Alhaditsa Ferry Putri', '<p>205040201111008. saya gatau mau cerita darimana, ceritanya terlalu panjang. tapi kalo bisa dipersingkat, saya gangerti jg saya knp. saya terlalu emosional, gabisa nahan marah dan emosi, gasuka ngejalanin kehidupan, slalu jd in nyakitin diri sndiri sbg pilihan penyelesaian masalah. saya capek. saya ngerasa jd beban buat semua orang</p>', '2022-12-01 11:48:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1610, 772, 2, 'admin', 'Ulifa Rahma', '<p>Mohon maaf atas lamanya respon karena antrian yang begitu panjang. Anda akan dihubungi oleh admin kami untuk menjadwalkan sesi konseling tatap muka besok pukul 10.00/11.00. Apakah anda bersedia. Terimakasih</p>', '2022-12-01 14:27:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1611, 137, 2, 'admin', 'Ulifa Rahma', '<p>Terimakasih banyak telah mengakses layanan kami. Anda bisa menjelaskan dengan lebih detail ada hal apa yang anda alami mengapa kehilangan semangat. Anda dapat mengidentifikasi penyebabnya dan meminta dukungan sosial dari lingkungan sekitar serta melakukan aktivitas yang menyenangkan dan positif untuk meningkatkan semangat. Semoga hal ini dapat menjawab dan anda dapat meveritakannya lebih detail lagi. Terimakasih</p>', '2022-12-01 14:31:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1612, 832, 2, 'admin', 'Ulifa Rahma', '<p>Terimakasih sudah mengakses layanan konseling, saya memahami yang anda rasakan bukanlah hal yang mudah. JIka dirasa anda memerlukan konsultasi lanjutan pada psikiater sebelumnya dapat diakses kembali ketika anda merasa secara fisik dan psikis sedang dalam kondisi yang tidak baik. </p><ol><li><strong>Identifikasi dan seleksi </strong><strong>situasi yang menimbulkan </strong><strong>permasalahan. </strong></li><li><strong>Rubah pikiran menjadi positif dan biasakan. Anda</strong> memiliki pemikiran pemikiran apa yang menyebabkan anda merasa pesimis dan takut dijurusan saat ini? Misalnya takut tidak mendapat ilmu?tidak tahu manfaat jurusan yang diambil sekarang?<strong>Rubah pikiran  dan atasi</strong>. </li><li>Semuanya tergantung bagaimana cara adriyan merubah pola pikir mengenai apa saja yang menimbulkan ketakutan dan perasaan pesimis</li><li><strong>Rubah Lingkungan. </strong>Lingkungan apa yang membuat anda merasa tidak nyaman, identifikasi dan rubah dengan bentuk tindakan nyata. </li><li><strong>Silahkan buat planning/rencana baik jangka pendek atau jangka Panjang untuk merubah diri anda menjadi lebih baik. </strong>Misalnya: Saya punya tujuan. Tujuan saya adalah…..Cara agar saya bisa mencapai tujuan adalah dengan mengatur jadwal, mengatur aktivitas dan lainnya. <strong>Buatlah sekonkret mungkin, Tulis dan Lakukan dan Hadiahi diri anda sendiri dengan pujian dan hobi yang anda sukai</strong></li><li><strong>Kapan terakhir anda melakukan aktivitas yang anda sukai?apa yang menbuat anda bahagia dan merasa tenang?</strong> Misal saya merasa lebih tenang dan bahagia kalau saya olahraga, kalua saya membaca novel, kalau saya menggambar dan lainnya. Lakukan itu, anda berhak untuk melakukan aktivitas yang mebuat anda bahagia dan <strong>lakukan sengan segera. </strong> Beri kesempatan diri untuk mengembangkan potensi dan fokus untuk membahagiakan diri sendiri. Lakukan aktivitas yang menjadi bakat dan minat anda.Sehingga ketika anda kuliah anda tetap bahagia dan melakukan hobi yang disuka</li> <li><strong>Cari dukungan social dari orang orang yang anda percaya</strong></li><li><strong>Adriyan bisa membuat table dan menuliskannya pada laptop, HP atau media apapun</strong></li></ol> <table><tbody><tr><td valign="top" style="width:116px"><p><strong>Ketakutan atau pemikiran negatif</strong></p> </td> <td valign="top" style="width:108px"><p><strong>Dampaknya untuk saya (banyak positif atau negatifnya)</strong></p> </td> <td valign="top" style="width:102px"><p><strong>Penyebab dan kapan pikiran muncul</strong></p> </td> <td valign="top" style="width:103px"><p><strong>Merubah menjadi pemikiran positif yaitu</strong></p> </td> <td valign="top" style="width:99px"><p><strong>Apa tindakan yang akan saya lakukan untuk merubah situasi</strong></p> </td> <td valign="top" style="width:73px"><p><strong>Hadiah/reward untuk saya ketika berhasil melakukannya</strong></p> </td> </tr> <tr></tr> <tr></tr> <tr></tr> <tr></tr> <tr></tr> <tr></tr> </tbody></table> <p><br /></p> <p>Tetap semangat ini bukanlah hal mudah, tapi saya yakin anda punya potensi, mampu dan sangat bisa untuk sukses dan bahagia, tinggal bagaimana Adriyan memberi kesempatan diri sendiri. Jika ada kendala silahkan melakukan konseling tatap muka. Begitu penjelasan yang bisa saya berikan. Semoga bisa membantu.</p>', '2022-12-01 14:41:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1613, 926, 2, 'admin', 'Ulifa Rahma', '<p>Saya sangat memahami apa yang kamu rasakan dan hal tersebut bukanlah hal yang mudah, Semoga hari saat <strong>Anda</strong> baca tanggapan ini, kondisinya sudah lebih baik ya. <strong>Anda</strong>, pertama mungkin pertanyaan saya apa yang kamu pikirkan? Mendapatkan bayangan itu dari mana informasinya? Apa yg mengawali anda memikirkan hal tesebut?Namun kembalikan lagi pada diri, kapan <strong>Anda</strong> memberi kesempatan pada diri sendiri untuk bahagia dan mengembangkan potensi. Jika <strong>Anda</strong> seperti ini terus menerus siapa yang akan rugi?Ada beberapa hal yang bisa dilakukan:</p> <ol><li><strong>Identifikasi dan seleksi </strong><strong>situasi yang menimbulkan </strong><strong>permasalahan. </strong>Anda sudah memiliki nilai yang agus namun kurang merasa mendapat ilmu. Adakah hal hal yang menyebabkan hal itu terjadi?misalnya tidak nyaman dengan lingkungan teman, dosen, ada keinginan pada jurusan lain?atau lainnya? Identifikasi dan tuliskan</li><li><strong>Rubah pikiran menjadi positif dan biasakan.</strong> <strong>Rubah pikiran anda dan atasi</strong>. </li><li><strong>Rubah Lingkungan. </strong>Lingkungan apa yang membuat anda merasa tidak nyaman, identifikasi dan rubah dengan bentuk tindakan nyata. </li><li><strong>Silahkan buat planning/rencana baik jangka pendek atau jangka Panjang untuk merubah diri anda menjadi lebih baik. </strong>Misalnya: Saya punya tujuan. Tujuan saya adalah…..Cara agar saya bisa mencapai tujuan adalah dengan mengatur jadwal, mengatur aktivitas dan lainnya. <strong>Buatlah sekonkret mungkin, Tulis dan Lakukan dan Hadiahi diri anda sendiri dengan pujian dan hobi yang anda sukai</strong></li><li><strong>Kapan terakhir anda melakukan aktivitas yang anda sukai?apa yang menbuat anda bahagia dan merasa tenang?</strong> Misal saya merasa lebih tenang dan bahagia kalau saya olahraga, kalua saya membaca novel, kalau saya menggambar dan lainnya. Lakukan itu, anda berhak untuk melakukan aktivitas yang mebuat anda bahagia dan <strong>lakukan sengan segera. </strong> Beri kesempatan diri untuk mengembangkan potensi dan fokus untuk membahagiakan diri sendiri. Lakukan aktivitas yang menjadi bakat dan minat anda.Sehingga ketika anda kuliah anda tetap bahagia dan melakukan hobi yang disuka</li><li>Fokus pada hal baik yang anda miliki dan alami serta kelebihan yang anda miliki. Terkadang ketika kita memikirkan masa lampau atau masa yang akan datang membuat kita merasa tidak nyaman. Fokus hal bai kapa yang bisa saya lakukan saat ini dan bagaimana saya harus menghadapinya </li><li><strong>Cari dukungan social dari orang orang yang anda percaya. cari dukungan jika diperlukan dari orang orang yang mengerti. </strong>Yang anda rasakan sekarang bukan hal mudah, namun ketika anda mampu melewati prosesnya dengan baik dan menghadapinya maka anda adalah orang yang hebat.</li><li><strong>Anda bisa membuat table dan menuliskannya pada laptop, HP atau media apapun</strong></li></ol> <table><tbody><tr><td valign="top" style="width:116px"><p><strong>Ketakutan atau pemikiran negatif</strong></p></td> <td valign="top" style="width:108px"><p><strong>Dampaknya untuk saya (banyak positif atau negatifnya)</strong></p></td> <td valign="top" style="width:102px"><p><strong>Penyebab dan kapan pikiran muncul</strong></p></td> <td valign="top" style="width:103px"><p><strong>Merubah menjadi pemikiran positif yaitu</strong></p></td> <td valign="top" style="width:99px"><p><strong>Apa tindakan yang akan saya lakukan untuk merubah situasi</strong></p></td> <td valign="top" style="width:73px"><p><strong>Hadiah/reward untuk saya ketika berhasil melakukannya</strong></p></td> </tr> </tbody></table> <p><br /></p> <p>Tetap semangat ini bukanlah hal mudah, tapi saya yakin Anda punya potensi, mampu dan sangat bisa untuk sukses dan bahagia, tinggal bagaimana Anda memberi kesempatan diri sendiri. Jika ada kendala silahkan melakukan konseling tatap muka. Begitu penjelasan yang bisa saya berikan. Semoga bisa membantu. Jika ingin mengakses layanan konseling tatap muka dapat mengajukan untuk hal tersebut. Semoga dapat menjawab</p>', '2022-12-01 14:52:56');
