INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1734, 472, 2, 'admin', 'Ulifa Rahma', '<p><br /></p><blockquote><p>Perkenalkan, saya Agus Dwi Sulistyono, Dosen di Jurusan Sosial Ekonomi Perikanan dan Kelautan FPIK-UB. Saya memiliki permasalahan beberapa hari ini, ada indikasi self harm. Apakah ada kesempatan konseling untuk dosen? Mohon arahannya. Terima kasih</p></blockquote> <p><br /></p>', '2022-12-05 09:25:59');
