INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1782, 523, 2, 'admin', 'Ulifa Rahma', '<p><strong>Mohon maaf atas balasan yang begitu lama mengingat antrian yang Panjang semoga dimengerti..</strong></p> <p>Semoga hari saat <strong>Anda</strong> baca tanggapan ini, kondisinya sudah lebih baik ya.</p> <p>Jika anda mengambil cuti akademik maka tidak terhitung sebagai masa aktif dalam kaitannya dengan batas waktu studi. Untuk lebih jelasnya anda dapat memperoleh informasi yang lebih akurat pada bagian akademik di Jurusan atau fakultas anda, semoga membantu</p>', '2022-12-05 16:35:34');
