INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (1786, 554, 2, 'admin', 'Ulifa Rahma', '<p><br /></p><blockquote><p>Saya shitny (185020501111018) mahasiswa prodi Ekonomi Islam, orang tua saya pisah sejak saya kecil. Sejak kecil sampai saat ini, seringkali terdapat perbedaan pendapat diantara kedua orang tua saya, bahkan sampai menjatuhkan satu sama lain. Meskipun untuk saat ini saya lebih bisa memilih yang mana saya harus pilih, tetapi yang saya rasakan terdapat emosi yang kurang baik dalam diri saya, terkait kekhawatiran atau ketakutan. </p></blockquote> <p><br /></p>', '2022-12-05 16:44:47');
