INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2069, 804, 2, 'admin', 'Ulifa Rahma', '<p><br /></p><blockquote><p>Mahasiswa a.n Gara Nabillah Amru (FTP-THP- 2022) mengalami masalah perundungan, karena telah melakukan pelecehan seksual secara verbal (ringan) thd Kakak Tingkat, sehingga perlu mendapat konseling.</p> <p>No. Kontak : 085755029410</p></blockquote> <p><br /></p>', '2022-12-09 13:06:35');
