INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2325, 1034, 100918, 'mahasiswa', 'Nidha Permata Fadillah', '<p>Nim 205040207111152. Hallo saya nidha dari fp mau konsultasi sebener nya masalah psikis saya ini udah saya alami dari SMA. Dulu berawal dari permasalahan keluaega saya dimana hubungan bapak dan ibu saya retak di saat itu dan mulai saat itu saya tidak bisa mengontrol emosi saya dimana saya bisa nangis dan marah tanpa terkontrol sama sekali lalu pada saat itu juga bertepatan saya di bully dengan embel embel candaan tentang fisik saya yang gemuk dan saya makin gabisa kontrol emosional saya terutama nangis krna saya jadi suka nangis secara tb tb kalau lagi terdiam hal itu terus berlanjut hingga saat ini terutama jika ada permasalahan yang menyangkut fisik saya maka saya akan sangat tertekan dan saat itu terjadi saya pasti merasakan sesak hingga sulit bernafas , susah tidur,mual dan muntah. Gejala nya semakin parah karna saat ini saya sering memuntahkan makanan saya secara sengaja karena takut gemuk. Karna yang ada di otak saya kalau saya gemuk maka permasalahan akan semakin banyak terjadi. Saya merasa tidak ada yang peduli kepada saya dan tidak ada yang bisa menerima saya apa adanya bahkan orang tua saya. Saya suka cemas dan mual tiba-tiba dan ketika itu terjadi juga saya suka kehilangan kendali emosional marah dan saya bisa nangis lalu dalam beberapa waktu saya merasa seperti tidak ada yang terjadi dan semua baik baik saja. Saya bingung karna belakangan ini apa yang saya rasakan cukup menganggu kehidupan saya sehari hari saya selalu merasa bersalah dan memuntahkan makanan ketika saya makan yang menurut saya terlalu banyak. Saya sering emosi meluap luap terhadap orng lain padahal permasalahan nya hanya permasalahan kecil. Saya bingung menjelaskan nya bagaimana tapi saya merasa butuh untuk cerita karna saya tidak bisa menahan nya sendirian lagi.<br /><br /><br /><br /></p>', '2023-02-09 22:19:04');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2326, 1035, 100917, 'mahasiswa', 'Puspita Ratih Kusumaningrum', '<p>215090200111040. Saya sering merasa stress ketika waktu krs tiba dikarenakan adanya tekanan dari dosen pembimbing. Kepala saya suka berisik memikirkan semuanya sampai ketika saya diajak berbicara dengan lawan bicara tidak fokus karena banyak yang dipikirkan</p>', '2023-02-09 22:37:29');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2327, 1036, 100916, 'mahasiswa', 'Dewi Krisnawati', '<p>195090100111005</p> <p>Saya merasa capek dengan semua kegiatan kuliah. Saya kesulitan dalam menyelesaikan tugas dan lain2. Saya berharap dapat berdiskusi dengan anda. Terimakasih.</p>', '2023-02-10 18:29:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2328, 1037, 100919, 'mahasiswa', 'Indah Larasati', '<p>Saya Indah Larasati dengan NIM 205070207111011 dari FIKES jurusan keperawatan. Kebetulan disini saya sebagai anak rantau dari Jakarta entah kenapa perasaan saya selalu tidak enak jika sudah mulai malam hari &amp; bawaan nya keinget orang rumah terus, ingin nangis terus. Padahal saya sudah semester 6 dan sering bolak balik ke Malang, tapi kenapa hati ini selalu terasa berat jika harus balik ke Malang.. dan setiap sampai Malang, 1-2 hari saya pasti sangat menurun nafsu makan nya. </p>', '2023-02-12 19:36:07');
