INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2430, 1087, 100960, 'mahasiswa', 'Reyhan Akbar Bintang Pramuditya', '<p>215030200111048 - Sejak awal kuliah, saya sering pergi keluar/jalan tanpa arah atau tujuan karena disaat itu saya merasa punya waktu sendiri. pernah pada suatu waktu, saya bahkan keterusan hingga pasuruan. beberapa hari yang lalu, akhirnya saya terbuka ke ortu saya bahwa saya sering melakukan hal tersebut dan beberapa kali jatuh dan kecelakaan akibatnya. karena itu saya mendaftar konseling ini. karena semenjak saya kuliah meskipun ip saya tidak terganggu, saya mengalami kesulitan dalam menemukan tujuan saya, karena pada dasarnya saya merasa bahwa semua tindakan saya tidak penting dan saya tidak bisa mendapat apa yang  saya inginkan itu, meskipun saya tidak yakin dengan apa yang sebenarnya saya inginkan. "tidak punya arah" kata ibu saya. Sekian dari saya Terima Kasih</p>', '2023-03-04 20:13:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2431, 1088, 100961, 'mahasiswa', 'Cagiva Afifah Muyasaroh', '<p>205090300111025</p> <p>Permasalahan pribadi yang sara rasa mengganggu adalah saya merasa tiba-tiba merasa sangat takut untuk menghadapi hal yang tidak saya ingin lakukan atau saya merasa tidak adanya teman pada suatu perkumpulan, sehingga saya selalu merasa ingin menghindari pertemuan dari suatu perkumpulan tersebut. Selain itu saya adalah korban bully dari kecil hingga sekarang meskipun intensitasnya berkurang, namun hal tersebut memengaruhi kepercayaan diri dan pola pikir saya.</p>', '2023-03-05 12:25:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2432, 1083, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan Layanan Konseling. Apakah Anda berkenan untuk melakukan konseling lagi secara tatap muka?</p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2023-03-05 15:45:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2433, 1087, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan Layanan Konseling. Saya mengerti apa yang Anda rasakan. Kalau boleh tahu, alasan Anda masuk ke Fakultas Ilmu Administrasi karena apa? Dari situlah Anda bisa merangkai tujuan yang Anda inginkan.</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-03-05 15:56:48');
