INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2443, 1090, 100963, 'mahasiswa', 'Linda Sanusi', '<p>184140314111005 saya merasa hancur dan merasakan sedih berkelanjutan, cape, emosi, dan butuh untuk merasa tenang butuh untuk bisa melupakan hal hal yang menyakiti saya karena saya sering teringat hal hal yang menyakiti saya</p>', '2023-03-06 17:03:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2444, 1089, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan layanan konseling. Bisa Anda ceritakan lebih banyak mengenai keresahan dan ketakutan tersebut? Adakah penyebabnya? </p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-03-07 10:04:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2445, 1090, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Boleh diceritakan lebih banyak, hal apa yang membuat Anda merasa sedih, lelah, marah, dan butuh ketenangan untuk melupakan hal yang kurang menyenangkan tersebut? Kemudian, aktivitas Anda saat ini apa?</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-03-07 10:10:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2446, 1079, 2, 'admin', 'Ulifa Rahma', '<p>Apakah jawaban ini sudah cukup? Beritahu kami apabila Anda membutuhkan konseling secara langsung.</p> <p><br /></p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2023-03-07 11:14:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2447, 464, 2, 'admin', 'Ulifa Rahma', '<p>Selamat siang</p> <p>Nomor ini merupakan layanan call centre konseling Universitas Brawijaya. Melalui call centre ini, anda dapat bertanya informasi seputar Layanan Konseling Universitas Brawijaya melalui telepon, SMS atau WhatsApp.</p> <p>Halo, kami ingin mengonfirmasi terkait dengan pendaftaran layanan konseling yang anda ajukan pada website kami. Mohon ketersediaannya untuk mengonfirmasi apakah anda berkenan melanjutkan sesi konseling ini?</p> <p>NOTES: Konfirmasi sebelum 2 x 24 jam setelah menerima pesan ini untuk melanjutkan konseling.</p> <p>Terima kasih.</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-03-07 11:14:54');
