INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2463, 1100, 100973, 'mahasiswa', 'Karina Octa Jatmiko', '<p>Nama saya Karina Octa,prodi administrasi pendidikan angkatan 2020.NIM 205030907111011,izin untuk menceritakan permasalahan yang saya hadapi.Sejak kecil saya terbiasa untuk mendengarkan dan mematuhi segala keputusan yang menjadi keputusan kedua orang tua saya,mulai dari masalah akademik sampai urusan pribadi seperti keputusan yang akan saya ambil,sampai pada masa kuliah(awal keterima di UB ini) sebenarnya ini bukan pilihan saya melainkan kedua orang tua,saya tidak sepenuhnya menjalani perkuliahan saya dengan maksimal terlebih saya anak tunggal yang nantinya menjadi tulang punggung keluarga,namun yg menjadi permasalahannya ketetapan orang tua seperti "diumur segini kamu harus punya rumah" dll membuat saya merasa sedikit "tertekan" memang ini mungkin terasa umum karena kebanyakan orang tua mungkin ingin mengarahkan yang terbaik untuk putra putrinya akan tetapi dalam posisi ini saya juga ingin mengambil keputusan saya sendiri dengan berdasar konsekuensi yang sudah saya perhitungkan,pernah suatu ketika saya menetapkan keputusan saya dan menceritakan kepada orang tua (ibu) namun ibu kurang setuju dengan keputusan yang saya buat dan menimbulkan ibu berpikiran panjang hingga akhirnya kadang jatuh sakit karena sering kepikiran dengan keputusan yang saya buat jujur saat ini terkadang saya bingung harus seperti apa menghadapi situasi seperti ini </p>', '2023-03-08 23:08:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2464, 1092, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Bisa Anda ceritakan lebih banyak, hal apa yang membuat Anda overthinking sampai menangis dan sesak? <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-03-08 23:11:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2465, 1097, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan layanan konseling. Untuk persoalan administrasi surat pengunduran diri, bisa langsung ditanyakan ke prodi yaa dan bisa minta informasi melalui himpunan mahasiswa jurusan. Apakah sudah ditanyakan ke prodi? Apakah sudah berkonsultasi dengan DPA (Dosen Pembimbing Akademik) terkait pengunduran diri ini?</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-03-08 23:21:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2466, 1100, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan layanan konseling. Saya paham yang Anda rasakan saat ini tidaklah mudah. Apakah Anda berkenan untuk dijadwalkan konseling tatap muka daring pada hari Kamis, 16 Maret 2023 di jam 09.00 WIB? <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-03-08 23:28:01');
