INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2468, 1101, 100975, 'mahasiswa', 'Mukhammad Alwi Haswanto', '<p>Saya Alwi dari Fakultas MIPA, Departemen Fisika, Prodi Instrumentasi dengan NIM 215090800111004. Saya sering mengalami moodswing, emosi yang gampang sekali berubah, apalagi untuk sisi emosinya, sering sekali saya tersulut amarah hanya dengan hal sepele, sulit untuk menenangkan pikiran yang sering sekali berpikiran aneh dan buruk terhadap diri sendiri</p>', '2023-03-09 10:49:07');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2469, 1102, 100976, 'mahasiswa', 'Reza Adhani Pratama Hayi', '<pre>205110507111001rnrnFeeling depressed/hopeless most of the time, having suicidal thoughts most of the time, intense hate doing something I don''t like and make me depressed. All have been going on since graduated from elementary school,it was minor at first.</pre>', '2023-03-09 14:54:09');
