INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2503, 1103, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Bisa Anda ceritakan, maksud dari "ditinggal dan menanggung beban sendiri" itu bagaimana? <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-03-11 17:23:05');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2504, 1105, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda rasakan tidaklah mudah. Bisa Anda ceritakan maksud dari "Keluarga" menghambat perkuliahan Anda seperti apa?<br /><br />Saya tunggu jawabannya 1x24 jam yaa<br /><br />salam hangat,<br />Tim Konseling UB.</p>', '2023-03-11 17:48:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2505, 1108, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti perasaan Anda saat ini tidaklah mudah. Boleh diceritakan lebih banyak, hal apa yang membuat Anda sedih selama 2 minggu tersebut?<br /><br />Saya tunggu jawabannya 1x24 jam yaa<br /><br />salam hangat,<br />Tim Konseling UB.</p>', '2023-03-11 17:54:44');
