INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2516, 933, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti kenyamanan untuk bercerita setiap orang berbeda. Jika memang Anda ingin konseling secara tatap muka ataupun tertulis, silahkan menuliskan terlebih dahulu permasalahan atau persoalan yang ingin diceritakan. Jika untuk saat ini, Anda merasa lebih baik dan merasa tidak perlu melakukan konseling silahkan mengisi link evaluasi yaa<br />bit.ly/konselingonlineUB<br /><br />Terima kasih</p> <p>Salam hangat,<br />Tim Konseling UB. </p>', '2023-03-11 22:42:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2517, 933, 100828, 'mahasiswa', 'Andini Laily Putri', '<p>Menunggu untuk menceritakan permasalahan atau persoalan yang dialami. </p>', '2023-03-11 22:43:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2518, 1109, 100981, 'mahasiswa', 'YOGA SETYA UTAMA', '<p>225020407111100</p> <p>Awal mula bermain game(judi) menggunakan uang sendiri dan pada akhirnya melakukan pinjaman online,sudah bicara dengan orang tua,sebagian masalah sudah dapat di selesaikan namun terdapat masalah lagi dan lagi.</p>', '2023-03-12 15:40:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2519, 1110, 100972, 'mahasiswa', 'Fadhila Eka Trisnawati', '<p>Saya mahasiswi dengan NIM 225030207111132. Saya ingin konsultasi masalah yang sedang saya hadapi. Kegiatan akademik saya terganggu dikarenakan ikut organisasi di mana di dalam organisasi tersebut saya merasa tertekan mulai dari fisik hingga ke mental. Saya mendapati lingkungan organisasi yang membuat mental saya drop sehingga berimbas ke kegiatan saya yang lain, khususnya kegiatan akademik (kuliah). </p>', '2023-03-12 16:48:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2520, 1110, 1, 'admin', 'Nora Silvana', '<p>Terima kasih sudah menggunakan layanan konseling. Saya paham yang Anda rasakan saat ini tidaklah mudah. Apakah Anda berkenan untuk melaksanakan konseling secara tatap muka?<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-03-12 17:31:44');
