INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2670, 1136, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda rasakan tidaklah mudah. Boleh diceritakan lebih lanjut, permasalahan yang Anda alami?<br /><br />Mohon konfirmasinya dalam 1x24 jam<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-03-26 13:44:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2671, 1137, 101006, 'mahasiswa', 'Valerita Dwi Laksmi', '<p>205120307111004, saya merasa bingung dan hampa akhir akhir ini. saya juga mulai berpikiran untuk melukai diri saya lagi.</p> <p><br /></p>', '2023-03-26 23:04:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2672, 1137, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Saya memberikan informasi bahwasannya di FISIP sudah ada BKM FISIP (Badan Konseling Mahasiswa) FISIP. Anda akan saya refer kepada BKM FISIP yaa. Silahkan, Anda mengubungi melalui email berikut: badankonselingfisip@ub.ac.id <br /><br />Salam hangat,<br />Tim Konseling UB. <br /></p>', '2023-03-27 09:41:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2673, 1138, 101002, 'mahasiswa', 'Mohammad Avil Abianto', '<p>Saya Mohammad Avil Abianto dengan NIM 215110607111010 pendidikan bahasa jepang fakultas ilmu budaya. Ingin berkonsultasi mengenai penyakit saya yakni skizofrenia, Anxiety Disorder, ptsd, dan ADHD.</p>', '2023-03-27 09:44:51');
