INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2675, 1138, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Permasalahan Anda mengenai hal ini sudah tertangani dengan e-ticket sebelumnya. Terima kasih.<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-03-27 11:12:51');
