INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2684, 1141, 101008, 'mahasiswa', 'Aura Bening Embun', '<p>Tugas memberati pikiran, tapi tidak ada tenaga untuk memulai dan meneruskan untuk selesai, namun banyak energi untuk hal selain tugas,  dan ada dugaan memiliki ADHD namun tidak ada diagnosis formal</p>', '2023-03-29 14:04:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2685, 1139, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Apakah Anda berkenan untuk dijadwalkan konseling tatap muka pada Rabu, 5 April 2023 pukul 10.00 WIB? <br /><br />Mohon konfirmasinya 1x24 jam<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-03-29 18:45:28');
