INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2687, 1141, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Apakah Anda berkenan untuk dijadwalkan konseling pada Kamis, 6 April 2023 pukul 13.00 WIB?<br /><br />Mohon konfirmasinya 1x24 jam yaa<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-03-29 19:01:02');
