INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2697, 1142, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Apakah Anda berkenan untuk dijadwalkan konseling tatap muka pada Rabu, 5 April 2023 pukul 09.00 WIB? </p> <p>Mohon konfirmasinya 1x24 jam</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-03-30 18:24:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2698, 1143, 100179, 'mahasiswa', 'Erika Maulidya Putri', '<p>205050100113022</p> <p>Masalah sosial di lingkungan perkuliahan sering merasa ga dihargai ketika berbicara. Intinya dapat kelompok yang ga nyaman. Main circle" an </p>', '2023-03-30 20:53:07');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2699, 1144, 100179, 'mahasiswa', 'Erika Maulidya Putri', '<p>205050100110322</p> <p>Masalah di lingkungan perkuliahan sering ketika berbicara tidak pernah di hargai sering mengajukan pendapat tapi tidak pernah di hargai. Merasa tidak nyaman di lingkungan perkuliahan yang toxic dan main circle" an. </p>', '2023-03-30 20:54:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2700, 1143, 1, 'admin', 'Andini Laily Putri', '<p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Apakah Anda berkenan untuk melakukan konseling pada hari Selasa, 4 April 2023 pukul 10.00 WIB bersama Peer Counselor?<br /><br />Mohon konfirmasinya 1x24 jam<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-03-31 19:23:07');
