INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2722, 1151, 101016, 'mahasiswa', 'Muhammad Atallah Azayaka', '<p>Perkenalkan nama saya Muhammad Atallah Azayaka (215120307111061) dari jurusan Psikologi. Saya merasa selama ini saya memiliki kesulitan untuk fokus dalam belajar, baik itu saat belajar sendiri maupun dalam kelas. Saya juga cukup merasa kesulitan untuk memahami materi.</p>', '2023-04-04 13:59:41');
