INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2757, 1161, 101024, 'mahasiswa', 'Theressa Zaratrusha', '<p>Iya, saya ingin konseling tatap muka bersama konselor</p>', '2023-04-10 15:33:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2758, 1164, 101026, 'mahasiswa', 'A. Aulia Trikayudhi Fikramudyah', '<p>NIM 225150407111066.</p> <p>Dalam 2 hari ke depan saya akan keluar bermain bersama teman-teman prodi saya ke taman bermain sebagai refreshing sebelum libur lebaran. Membayangkan akan keluar ke taman bermain untuk waktu yang lama dari sore hingga malam lalu menginap di rumah teman saya membuat saya merasa cemas sendiri tanpa tahu alasannya, saya merasa deg degan dan gelisah padahal mereka hanya mengajak bersenang-senang dan tidak akan terjadi hal buruk apapun, dari awal direncanakan (kemarin) sampai sekarang saya masih merasa tidak tenang setiap kali membayangkan pergi meninggalkan rumah dalam waktu yang lama terlebih hingga malam hari dan tidak pulang (menginap). Padahal mereka yang akan pergi bersama saya adalah teman-teman baik saya yang selalu membantu saya dan membuat saya nyaman berada di daerah rantau ini. Apakah rasa cemas dan tidak tenang yang saya rasakan itu wajar? Bagaimana cara saya mengatasi setiap kali perasaan tidak tenang ini muncul ketika ada rencana-rencana untuk kegiatan yang melibatkan orang banyak atau membuat saya berada di luar rumah dalam waktu yang lama? Terima kasih, tolong bantu saya. </p>', '2023-04-10 22:04:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2759, 1165, 101027, 'mahasiswa', 'Irfaninda Putri Imroatul Azizah', '<p>195070601111012 Keluarga saya akan bercerai sehingga berpengaruh terhadap akademik saya (skripsi) yang sedang saya kerjakan. Setiap hari saya merasa mental saya down dan tidak bisa fokus mengerjakan sesuatu. Saya cenderung menarik diri dari lingkungan.</p>', '2023-04-11 10:40:13');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2760, 1159, 1, 'admin', 'Nora Silvana', '<p dir="ltr">Saya sangat memahami apa yang Anda rasakan dan hal tersebut bukanlah hal yang mudah, Semoga hari saat <strong>Anda</strong> baca tanggapan ini, kondisinya sudah lebih baik ya. Kita hidup dan berinteraksi dengan berbagai macam karakteristik individu, maka kita tidak dapat mengendalikan lingkungan, sehingga kita perlu melakukan coping yang lebih memadai dalam menghadapi situasi tersebut. Coping adalah strategi individu dalam menghadapi stress yang bisa berasal dari situasi atau stimulus eksternal maupun stimulus internal. Salah satunya dengan mempertimbangkan respon kognitif yang muncul berupa pemikiran/ keyakinan yang negatif mengenai suatu situasi/ diri sendiri/ orang lain maupun situasi yang kan datang dan belum terjadi. Karena pemikiran yang negatif dapat mendorong munculnya emosi negatif dan perilaku-perilaku yang maladaptif, sehingga ketika menghadapi situasi-situasi dalam hidup dapat memberikan efek pada kondisi fisik dan psikologis. Ada beberapa hal yang bisa dilakukan:</p> <p dir="ltr">1. <strong>Identifikasi dan seleksi situasi yang menimbulkan permasalahan. </strong>Adakah hal hal yang menyebabkan anda perlu untuk mengendalikan diri? Identifikasi dan tuliskan</p> <p dir="ltr">kenali diri, kelebihan dan kekurangan anda, apa yang anda sukai, anda baik dibidang apa dan memiliki kesempatan apa</p> <p dir="ltr"><strong>2. Eksplorasi diri. </strong>Apa yg bisa dilakukan untuk kenali? Ikut psikotes? Analisis personal SWOT? konseling Ikut organisasi? magang? Ikut karir day?</p> <figure></figure> <p dir="ltr">3. Refleksi diri. introspeksi diri, apa yg sudah berkembang, apa yg perlu dikembangkan lagi?</p> <figure></figure> <p dir="ltr">4. Asah dan kembangkan soft skill maupun hard skill yang dibutuhkan dalam bekerja</p> <figure></figure> <p dir="ltr">5. RESEARCH, PAHAMI TREND, KEBUTUHAN DAN TUNTUTAN DUNIA KERJA. PADA BIDANG YANG ANDA INGINKAN APA? (INDUSTRY 4.0-5.0)</p> <p dir="ltr">6. MENENTUKAN TARGET/TUJUAN DAN RENCANA</p> <p dir="ltr">7. RANCANG MASA DEPANMU:IMPLEMENTASI, ADAPTASI DAN EVALUASI</p> <figure></figure> <figure></figure> <p dir="ltr">Semoga bisa membantu.</p> <p><strong>Kami Mohon kesediaan untuk mengisi link berikut ini sebagai bahan evaluasi kami setelah mengikuti sesi konseling dan data anda kami rahasiakan: </strong><a href="http://bit.ly/konselingonlineUB"><strong>bit.ly/konselingonlineUB</strong></a></p>', '2023-04-11 12:09:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2761, 1164, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p dir="ltr">Terima kasih telah menggunakan layanan konseling. Saya sangat memahami apa yang Anda rasakan dan hal tersebut bukanlah hal yang mudah. Kita hidup dan berinteraksi dengan berbagai macam karakteristik individu dan kondisi yang tidak dapat dikendalikan sehingga kita perlu melakukan coping yang lebih memadai dalam menghadapi situasi tersebut. <em>Coping</em> adalah strategi individu dalam menghadapi stress yang bisa berasal dari situasi atau stimulus eksternal maupun stimulus internal. Salah satunya dengan mempertimbangkan respons kognitif yang muncul berupa pemikiran/ keyakinan yang negatif mengenai suatu situasi/ diri sendiri/ orang lain maupun situasi yang kan datang dan belum terjadi. Pemikiran yang negatif dapat mendorong munculnya emosi negatif dan perilaku-perilaku yang maladaptif sehingga ketika menghadapi situasi-situasi dalam hidup dapat memberikan efek pada kondisi fisik dan psikologis. Ada beberapa hal yang bisa dilakukan:</p> <ul><li dir="ltr"><p dir="ltr"><strong>Identifikasi dan seleksi situasi yang menimbulkan permasalahan. </strong>Adakah hal-hal yang menyebabkan Anda perlu untuk mengendalikan diri? Identifikasi dan tuliskan</p></li></ul> <ul><li dir="ltr"><p dir="ltr"><strong>Merubah pikiran menjadi positif dan biasakan.</strong> <strong>Rubah pikiran anda dan atasi</strong>. Hindari atau hadapi pola pikir negatif dan aktivitas yang membuat Anda menjadi berpikiran berlebihan dan selalu merasa cemas. Buang pikiran pikiran yang membuat cemas atau takut ganti menjadi pikiran positif agar Anda lebih dapat mengendalikan diri. Identifikasi pikiran negatif dan LAWAN ATAU TANTANG. Buatlah target/goal/timeline apa saja yang perlu Anda lakukan UNTUK MENANTANG PIKIRAN NEGATIF, lalu tulis dan tempel di tempat yang mudah terlihat di kamar Anda (sebagai pendorong dan evaluasi anda). LAKUKAN dan rubah jika pikiran negatif muncul</p></li></ul> <ul><li dir="ltr"><p dir="ltr"><strong>Kenali kapan Anda mulai merasa cemas. Hindari pemicu dan anda bisa menggunakan teknik relaksasi atau mindfulness. Mindfulness merupakan kesadaran yang muncul karena memberikan perhatian terhadap pengalaman yang dirasakan saat ini secara sengaja dan tanpa penilaian.</strong></p></li></ul> <figure><strong></strong></figure><br /> <ul><li dir="ltr"><p dir="ltr"><strong>Silahkan buat planning/rencana baik jangka pendek atau jangka panjang untuk membuat diri Anda menjadi lebih baik. </strong>Misalnya: Saya punya tujuan. Tujuan saya adalah…..Cara agar saya bisa mencapai tujuan adalah dengan mengatur jadwal, mengatur aktivitas dan lainnya. Sebagai contoh, Anda dapat menuliskan tujuan Anda bepergian bersama mereka, mengatur kegiatan yang akan kalian jalani, dan menuliskan risiko dari kemungkinan yang akan terjadi. <strong>Buatlah sekonkret mungkin. Tulis, lakukan dan hadiahi diri Anda sendiri dengan pujian dan hobi yang anda sukai.</strong></p></li></ul> <ul><li dir="ltr"><p dir="ltr">Fokus pada hal baik yang Anda miliki dan alami serta kelebihan yang Anda miliki. Terkadang ketika kita memikirkan masa lampau atau masa yang akan datang membuat kita merasa tidak nyaman. Fokus hal baik yang bisa Anda lakukan saat ini dan bagaimana Anda harus menghadapinya.</p></li></ul> <ul><li dir="ltr"><p dir="ltr"><strong>Cari dukungan sosial dari orang-orang yang Anda percaya. Cari dukungan jika diperlukan dari orang orang yang mengerti.</strong></p></li></ul> <figure></figure> <ul><li dir="ltr"><p dir="ltr"><strong>Anda bisa membuat table dan menuliskannya pada laptop, HP atau media apapun</strong></p></li></ul> <table><tbody><tr><td><p dir="ltr"><strong>pemikiran yang memunculkan rasa cemas</strong></p></td><td><p dir="ltr"><strong>Dampaknya untuk saya (banyak positif atau negatifnya)</strong></p></td><td><p dir="ltr"><strong>Penyebab dan kapan pikiran muncul</strong></p></td><td><p dir="ltr"><strong>Merubah menjadi pemikiran positif yaitu</strong></p></td><td><p dir="ltr"><strong>Apa tindakan yang akan saya lakukan untuk merubah situasi</strong></p></td><td><p dir="ltr"><strong>Hadiah/reward untuk saya ketika berhasil melakukannya</strong></p></td></tr></tbody></table> <p dir="ltr">Saya percaya bahwa Anda merupakan pribadi yang dapat melalui kondisi ini. Tetap semangat dan bahagia dalam keadaan apapun.</p> <p dir="ltr"><strong>Kami mohon kesediaan untuk mengisi link berikut ini sebagai bahan evaluasi kami setelah mengikuti sesi konseling dan data anda kami rahasiakan: </strong><a href="http://bit.ly/konselingonlineUB"><strong>bit.ly/konselingonlineUB</strong></a></p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2023-04-11 12:38:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2762, 1162, 101025, 'mahasiswa', 'Atiti Ilham Widath Pratiwi', '<p>Sudah, cuma jawaban dari dosen bikin saya sakit hati jadi males kuliah</p>', '2023-04-11 13:09:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2763, 1161, 101024, 'mahasiswa', 'Tasya Rahmani Puspa Pertiwi', '<p>Klien sudah dihubungi melalui WhatsApp dan akan dijadwalkan konseling</p>', '2023-04-11 21:33:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2764, 1164, 101026, 'mahasiswa', 'Tasya Rahmani Puspa Pertiwi', '<p>Sudah dihubungi melalui WhatsApp untuk progres respons eticket</p>', '2023-04-11 21:34:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2765, 1166, 101028, 'mahasiswa', 'Hamzah Fauzan', '<p>215110200111026</p> <p>Akibat dari banyak masalah yng dihadapi</p> <p>- hilangnya motivasi (belajar&amp;hidup)</p> <p>- mudah lelah (mental) hanya karena kegiatan ringan</p> <p>- permasalahan keluarga (terkadang saya hanya ingin didengar, bukan diceramahi)</p> <p>- sulit fokus dan sering sakit kepala</p> <p>- saya khawatir juga dengan pekerjaan saya (saya dipecat dari pekerjaan saya)</p> <p>- nilai akademik saya makin turun</p> <p>- menarik diri dari lingkungan sosial</p>', '2023-04-12 01:33:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2766, 1162, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Saya memahami bahwa hal tersebut tidaklah mudah. Akan tetapi, faktor lingkungan termasuk juga orang lain tidak dapat kita kendalikan. Untuk itu, pihak yang dapat kita kendalikan adalah diri kita sendiri. Apakah sebelumnya pernah menerapkan strategi coping di atas? </p>', '2023-04-12 09:37:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2767, 1166, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Terima kasih telah menggunakan layanan konseling. Saya sangat memahami apa yang Anda rasakan dan hal tersebut bukanlah hal yang mudah. Dalam hidup, letak kendali yang kita miliki adalah diri kita sendiri. Lingkungan yang tidak dapat kita kendalikan membuat kita perlu melakukan coping yang lebih memadai dalam menghadapi segala situasi tersebut. <em>Coping</em> adalah strategi individu dalam menghadapi stress yang bisa berasal dari situasi atau stimulus eksternal maupun stimulus internal. Salah satunya dengan mempertimbangkan respons kognitif yang muncul berupa pemikiran/ keyakinan yang negatif mengenai suatu situasi/ diri sendiri/ orang lain maupun situasi yang akan datang dan belum terjadi. Pemikiran yang negatif dapat mendorong munculnya emosi negatif dan perilaku-perilaku yang maladaptif sehingga ketika menghadapi situasi-situasi dalam hidup dapat memberikan efek pada kondisi fisik dan psikologis. Ada beberapa hal yang bisa dilakukan:</p><ul><li><strong>Identifikasi dan seleksi situasi yang menimbulkan permasalahan. </strong>Adakah hal hal yang menyebabkan Anda perlu untuk mengendalikan diri? Identifikasi dan tuliskan. Kenali diri, kelebihan, dan kekurangan Anda, apa yang Anda sukai, Anda baik dibidang apa, dan memiliki kesempatan apa? Anda juga dapat mengidentifikasi situasi apa yang menyebabkan Anda merasa demotivasi, menarik diri, bahkan memiliki kekhawatiran terkait pekerjaan.</li></ul><ul><li><strong>Eksplorasi diri. </strong>Apa yang bisa dilakukan untuk kenali diri Anda agar Anda memiliki potensi dan bertahan di dunia kerja?  Analisis personal SWOT? konseling? Ikut organisasi? magang? Ikut karier day?</li></ul><figure></figure><ul><li>Refleksi diri dan introspeksi diri. Apa yang sudah berkembang dan apa yang perlu dikembangkan lagi agar performa kerja dan akademik tetap terjaga?</li></ul><figure></figure><ul><li>Asah dan kembangkan <em>soft skill</em> maupun <em>hard skill</em> yang dibutuhkan dalam bekerja</li></ul><figure></figure><ul><li dir="ltr"><p dir="ltr"><strong>Merubah pikiran menjadi positif dan biasakan.</strong> <strong>Rubah pikiran Anda dan atasi</strong>. Hindari atau hadapi pola pikir negatif dan aktivitas yang membuat Anda menjadi berpikiran berlebihan dan selalu merasa cemas. Buang pikiran-pikiran yang membuat cemas atau takut ganti menjadi pikiran positif agar Anda lebih dapat mengendalikan diri. Identifikasi pikiran negatif dan LAWAN ATAU TANTANG. Buatlah target/goal/timeline apa saja yang perlu Anda lakukan UNTUK MENANTANG PIKIRAN NEGATIF MENGENAI PEKERJAAN, lalu tulis dan tempel di tempat yang mudah terlihat di kamar Anda (sebagai pendorong dan evaluasi anda). LAKUKAN dan rubah jika pikiran negatif muncul.</p></li></ul><ul><li dir="ltr"><p dir="ltr"><strong>Kenali kapan anda mulai merasa cemas, hindari pemicu dan Anda bisa menggunakan teknik relaksasi atau mindfulness. mindfulness merupakan kesadaran yang muncul karena memberikan perhatian terhadap pengalaman yang dirasakan saat ini secara sengaja dan tanpa penilaian.</strong></p></li></ul><strong><figure></figure></strong><ul><li dir="ltr"><p dir="ltr"><strong>Ubah Lingkungan. </strong>Lingkungan apa yang membuat Anda kesulitan mengendalikan diri? identifikasi, dan rubah dengan bentuk tindakan nyata.</p></li></ul><ul><li dir="ltr"><p dir="ltr"><strong>Silahkan buat planning/rencana baik jangka pendek atau jangka panjang untuk merubah diri anda menjadi lebih baik. </strong>Misalnya: Saya punya tujuan. Tujuan saya adalah…..Cara agar saya bisa mencapai tujuan adalah dengan mengatur jadwal, mengatur aktivitas dan lainnya. <strong>Buatlah sekonkret mungkin. Tulis, lakukan, dan hadiahi diri Anda sendiri dengan pujian dan hobi yang Anda sukai.</strong></p></li></ul><ul><li dir="ltr"><p dir="ltr"><strong>Hadiahi diri anda ketika mampu melewati hal yang mengganggu dan menghambat Anda. Kapan terakhir Anda melakukan aktivitas yang Anda sukai? apa yang membuat Anda bahagia dan merasa tenang?</strong> Misal saya merasa lebih tenang dan bahagia kalau saya olahraga, dan lain sebagainya.</p></li></ul><ul><li dir="ltr"><p dir="ltr">Fokus pada hal baik yang Anda miliki dan alami serta kelebihan yang Anda miliki. Terkadang ketika kita memikirkan masa lampau atau masa yang akan datang membuat kita merasa tidak nyaman. Fokus hal baik yang bisa Anda lakukan saat ini dan bagaimana Anda harus menghadapinya</p></li></ul><ul><li dir="ltr"><p dir="ltr"><strong>Cari dukungan sosial dari orang orang yang anda percaya. cari dukungan jika diperlukan dari orang orang yang mengerti.</strong></p></li></ul><figure></figure><ul><li dir="ltr"><p dir="ltr"><strong>Anda bisa membuat table dan menuliskannya pada laptop, HP atau media apapun</strong></p></li></ul><table><tbody><tr><td><p dir="ltr"><strong>pemikiran yang memunculkan rasa khawatir dan hilangnya motivasi</strong></p></td><td><p dir="ltr"><strong>Dampaknya untuk saya (banyak positif atau negatifnya)</strong></p></td><td><p dir="ltr"><strong>Penyebab dan kapan pikiran muncul</strong></p></td><td><p dir="ltr"><strong>Merubah menjadi pemikiran positif yaitu</strong></p></td><td><p dir="ltr"><strong>Apa tindakan yang akan saya lakukan untuk merubah situasi</strong></p></td><td><p dir="ltr"><strong>Hadiah/reward untuk saya ketika berhasil melakukannya</strong></p></td></tr></tbody></table> <ul><li><strong>Mengevaluasi kembali pola tidur Anda</strong>. Adanya kesulitan fokus dan rasa sakit kepala bisa datang dari kurangnya tidur berkualitas yang Anda miliki. Kualitas tidur pun juga dapat mempengaruhi perasaan dan kemampuan Anda untuk beraktivitas sehari-hari. Adapun kuantitas tidur yang dianjurkan sendiri adalah 8 jam sehari. Silakan seimbangkan produktivitas Anda dengan waktu istirahat yang cukup. Apakah kualitas tidur Anda sudah tercukupi sejauh ini?</li><li><strong>Makan teratur</strong>. Kesulitan fokus dan rasa sakit kepala juga bisa jadi berasal dari kurangnya asupan yang masuk ke dalam tubuh Anda. Makan dengan teratur merupakan kebutuhan yang harus terpenuhi untuk mendapatkan energi yang digunakan dalam kegiatan sehari-hari. </li><li><strong>Memeriksakan diri ke dokter</strong>. Apabila Anda sering merasa kedua hal tersebut datang dan terus berlanjut, silahkan Anda mendatangi dokter ataupun layanan kesehatan untuk mengetahui kondisi fisik Anda.</li></ul> <p dir="ltr">Semoga bisa membantu. Saya yakin Anda mampu melewatinya</p> <p dir="ltr"><strong>Kami mohon kesediaan untuk mengisi tautan berikut ini sebagai bahan evaluasi kami setelah mengikuti sesi konseling dan data anda kami rahasiakan: </strong><a href="http://bit.ly/konselingonlineUB"><strong>bit.ly/konselingonlineUB</strong></a></p><br />Salam Hangat,<br />Tim Konseling UB.', '2023-04-12 09:57:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2768, 1165, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Terimakasih telah menggunakan layanan konseling. Saya sangat memahami apa yang Anda rasakan dan hal tersebut bukanlah hal yang mudah. Kita hidup dan berinteraksi dengan berbagai macam situasi dan individu yang tidak dapat kita kendalikan, salah satunya adalah perceraian orang tua. Oleh karena itu, adanya kontrol kendali yang ada pada diri sendiri memerlukan kita untuk melakukan coping yang lebih memadai dalam menghadapinya. <em>Coping</em> adalah strategi individu dalam menghadapi <em>stress</em> yang bisa berasal dari situasi atau stimulus eksternal maupun stimulus internal. Salah satunya dengan mempertimbangkan respons kognitif yang muncul berupa pemikiran/ keyakinan yang negatif mengenai suatu situasi/ diri sendiri/ orang lain maupun situasi yang akan datang dan belum terjadi. Pemikiran yang negatif dapat mendorong munculnya emosi negatif dan perilaku-perilaku yang maladaptif sehingga ketika menghadapi situasi-situasi dalam hidup dapat memberikan efek pada kondisi fisik dan psikologis. Ada beberapa hal yang bisa dilakukan:</p> <ul><li><strong>Identifikasi dan seleksi situasi yang menimbulkan permasalahan. </strong>Bagian dari permasalahan tersebut apa yang membuat Anda mengalami kesulitan fokus mengerjakan skripsi? Tuliskan.</li></ul><ul><li><br /><img src="cid:roxjqxgghk6q0bvg-sfhb0vhpeg8ai9c" alt="image" data-image="mpzxyuozoavw" /><a href="https://konseling.ub.ac.id/tiket/file.php?key=roxjqxgghk6q0bvg-sfhb0vhpeg8ai9c&amp;expires=1681344000&amp;signature=32609a91ade79e1a7249192d80ff13d8f526d37f&amp;id=711" download="image.png" data-original-title="Download" target="_blank"><br /></a></li></ul><ul><li><strong>Ubah pikiran menjadi positif dan biasakan.</strong> <strong><strong>Ubah</strong> pikiran Anda dan atasi</strong>.Fokuslah kepada hal-hal yang dapat Anda kendalikan, seperti kesehatan, usaha yang dapat Anda lakukan, dan respons Anda dalam menghadapi permasalahan. Dengan mengatur hal-hal yang bisa Anda kendalikan, Anda dapat mengendalikan diri Anda di permasalahan yang Anda miliki dengan pikiran yang lebih jernih.</li></ul> <ul><li><strong>Ingat kembali tujuan Anda dalam menjalani perkuliahan dan buatlah rencana-rencana untuk jangka pendek maupun panjang. </strong>Misalnya: Saya punya tujuan. Tujuan saya adalah…..Cara agar saya bisa mencapai tujuan adalah dengan mengatur jadwal, mengatur aktivitas, dan lainnya. <strong>Buatlah sekonkret mungkin, tulis, lakukan dan hadiahi diri Anda sendiri dengan pujian dan hobi yang Anda sukai</strong></li></ul><ul><li><strong>Berikan afirmasi positif ke diri Anda. </strong>Dukungan dari diri sendiri sangatlah dibutuhkan. Katakanlah kepada diri Anda bahwa Anda mampu melewati segala hal yang Anda lakukan saat ini. Ingatlah perjuangan yang Anda telah korbankan untuk sampai di titik ini.<br /> </li><li><strong><img src="cid:9q7afzaaaqpaq3bkfp0mgyg_zvyzpymc" alt="image" data-image="kubx8xxykbat" /><br /></strong></li><li><strong><img src="cid:7sfot7en6efw0betethfpca1sdwfi604" alt="image" data-image="qjjzmlsw05w8" /><br /></strong></li><li><strong><img src="cid:g9oavgrtw-pvf450pziipegbnbpkt-3s" alt="image" data-image="slsijrqbh5gu" /><br /></strong></li><li><strong><img src="cid:qixle3ytpfayznmio7ctkp2bgxoodxbg" alt="image" data-image="8bg0d5mwynzy" /></strong></li></ul> <ul><li><strong>Kenali lebih diri Anda dengan mencatat kelebihan dan kekurangan, prestasi yang Anda pernah raih, serta cara belajar yang efektif untuk Anda. </strong>Hal ini membantu Anda untuk mengingat kembali sejauh mana Anda pernah berjuang dan membantu Anda untuk kembali memiliki motivasi di bidang akademik.</li></ul><ul><li><strong>Kapan terakhir Anda melakukan aktivitas yang Anda sukai? apa yang menbuat Anda bahagia dan merasa tenang?</strong></li></ul> <ul><li><strong>Cari dukungan sosial dari orang-orang yang Anda percaya, teman/saudara yang memahami Anda, dan saling mengerti antara satu dengan yang lain. Cari dukungan jika diperlukan dari orang orang yang mengerti. </strong>Yang Anda rasakan sekarang bukan hal mudah, namun ketika Anda mampu melewati prosesnya dengan baik dan menghadapinya maka Anda adalah orang yang hebat.</li></ul> <ul><li><strong>Anda bisa membuat tabel dan menuliskannya pada laptop, HP atau media apapun</strong></li></ul> <table><tbody><tr><td valign="top"><p><strong>Ketakutan atau pemikiran negatif</strong></p></td><td valign="top"><p><strong>Dampaknya untuk saya (banyak positif atau negatifnya)</strong></p></td><td valign="top"><p><strong>Penyebab dan kapan pikiran muncul</strong></p></td><td valign="top"><p><strong>Merubah menjadi pemikiran positif yaitu</strong></p></td><td valign="top"><p><strong>Apa tindakan yang akan saya lakukan untuk mengubah situasi</strong></p></td><td valign="top"><p><strong>Hadiah/reward untuk saya ketika berhasil melakukannya</strong></p></td></tr></tbody></table> <p>Tetap semangat ini bukanlah hal mudah, tapi saya yakin Anda punya potensi, mampu dan sangat bisa untuk sukses dan bahagia, tinggal bagaimana Anda memberi kesempatan diri sendiri. Jika ada kendala, silakan melakukan konseling tatap muka. Semoga bisa membantu. </p> <p><strong>Kami memohon kesediaan untuk mengisi link berikut ini sebagai bahan evaluasi kami setelah mengikuti sesi konseling dan data anda kami rahasiakan: </strong><a href="http://bit.ly/konselingonlineUB" target="_blank"><strong>bit.ly/konselingonlineUB</strong></a>.</p> <p><br /></p> <p>Salam Hangat,</p> <p>Tim Konseling UB.<br /> </p>', '2023-04-12 10:23:13');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2769, 1160, 1, 'admin', 'Nora Silvana', '<p>Saya sangat memahami apa yang Anda rasakan dan hal tersebut bukanlah hal yang mudah, Semoga hari saat <strong>Anda</strong> baca tanggapan ini, kondisinya sudah lebih baik ya. Kita hidup dan berinteraksi dengan berbagai macam karakteristik individu, maka kita tidak dapat mengenalikan lingkungan, sehingga kita perlu melakukan coping yang lebih memadai dalam menghadapi situasi tersebut. Coping adalah strategi individu dalam menghadapi stress yang bisa berasal dari situasi atau stimulus eksternal maupun stimulus internal. Salah satunya dengan mempertimbangkan respon kognitif yang muncul berupa pemikiran/ keyakinan yang negative mengenai suatu situasi/ diri sendiri/ orang lain maupun situasi yang kan datang dan belum terjadi. Karena pemikiran yang negative dapat mendorong munculnya emosi negatif dan perilaku-perilaku yang maladaptif, sehingga ketika menghadapi situasi-situasi dalam hidup dapat memberikan efek pada kondisi fisik dan psikologis. Ada beberapa hal yang bisa dilakukan:</p> <ul><li><strong>Identifikasi dan seleksi situasi yang menimbulkan permasalahan. </strong>Adakah hal hal yang menyebabkan anda perlu untuk mengendalikan diri? Identifikasi dan tuliskan</li></ul> <ul><li><strong>Rubah pikiran menjadi positif dan biasakan.</strong> <strong>Rubah pikiran anda dan atasi</strong>. Hindari atau hadapi pola pikir negatif dan aktivitas yang membuat anda menjadi berfikiran berlebihan, ganti menjadi pikiran positif agar anda lebih dapat mengendalikan diri. identifikasi pikiran negative dan LAWAN ATAU TANTANG. Buatlah target/goal/timeline apa saja yang perlu anda lakukan UNTUK MENANTANG PIKIRAN NEGATIF, lalu tulis dan tempel di tempat yang mudah terlihat di kamar anda (sebagai pendorong dan evaluasi anda). LAKUKAN dan rubah jika pikiran negative muncul</li></ul> <ul><li><strong>Kenali kapan anda mulai merasa terpikir untuk membenci diri sendiri atau pemikiran negatif lainnyaa. Hindari pemicu dan anda bisa menggunakan teknik relaksasi atau mindfulness. mindfulness merupakan kesadaran yang muncul karena memberikan perhatian terhadap pengalaman yang dirasakan saat ini secara disengaja dan tanpa penilaian.</strong></li><li><strong><img src="cid:seniwwqaaa3obgy9n4zql8k0mlxsdvus" alt="image" data-image="jtbxlsmsiwsn" /></strong></li><li><strong>Rubah Lingkungan. </strong>Lingkungan apa yang membuat anda kesulitan mengendalikan diri , identifikasi dan rubah dengan bentuk tindakan nyata.</li></ul> <ul><li><strong>Silahkan buat planning/rencana baik jangka pendek atau jangka Panjang untuk merubah diri anda menjadi lebih baik. </strong>Misalnya: Saya punya tujuan. Tujuan saya adalah…..Cara agar saya bisa mencapai tujuan adalah dengan mengatur jadwal, mengatur aktivitas dan lainnya. <strong>Buatlah sekonkret mungkin, Tulis dan Lakukan dan Hadiahi diri anda sendiri dengan pujian dan hobi yang anda sukai</strong></li></ul> <ul><li><strong>Hadiahi diri anda ketika mampu mengelola emosi Kapan terakhir anda melakukan aktivitas yang anda sukai? apa yang menbuat anda bahagia dan merasa tenang?</strong> Misal saya merasa lebih tenang dan bahagia kalau saya olahraga, kalau saya menerapkan teknik mindfullness</li></ul> <ul><li>Fokus pada hal baik yang anda miliki dan alami serta kelebihan yang anda miliki. Terkadang ketika kita memikirkan masa lampau atau masa yang akan datang membuat kita merasa tidak nyaman. Fokus hal baiik yang bisa saya lakukan saat ini dan bagaimana saya harus menghadapinya</li></ul> <ul><li><strong>Cari dukungan sosial dari orang orang yang anda percaya. cari dukungan jika diperlukan dari orang orang yang mengerti.</strong></li><li><strong><img src="cid:tc88fjuyfdgivdt9o9zn7mhrsx98ldzk" alt="image" data-image="iqb5h2jqdsl2" /></strong></li></ul> <ul><li><strong>Anda bisa membuat table dan menuliskannya pada laptop, HP atau media apapun</strong></li></ul> <table><tbody><tr><td valign="top"><p><strong>pemikiran yang memunculkan rasa marah</strong></p></td><td valign="top"><p><strong>Dampaknya untuk saya (banyak positif atau negatifnya)</strong></p></td><td valign="top"><p><strong>Penyebab dan kapan pikiran muncul</strong></p></td><td valign="top"><p><strong>Merubah menjadi pemikiran positif yaitu</strong></p></td><td valign="top"><p><strong>Apa tindakan yang akan saya lakukan untuk merubah situasi</strong></p></td><td valign="top"><p><strong>Hadiah/reward untuk saya ketika berhasil melakukannya</strong></p></td></tr></tbody></table> <p>Tetap semangat ini bukanlah hal mudah, tapi saya yakin Anda punya potensi, mampu dan bisa untuk sukses dan bahagia, tinggal bagaimana Anda memberi kesempatan diri sendiri. Saya sangat senang jika anda bersedia untuk menjadwalkan kembali melalui e ticket untuk melakukan konseling tatap muka dengan saya. Begitu penjelasan yang bisa saya berikan. Semoga bisa membantu.</p> <p><strong>Kami Mohon kesediaan untuk mengisi link berikut ini sebagai bahan evaluasi kami setelah mengikuti sesi konseling dan data anda kami rahasiakan: </strong><a href="http://bit.ly/konselingonlineUB" target="_blank"><strong>bit.ly/konselingonlineUB</strong></a></p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-04-12 18:33:26');
