INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2822, 1178, 101039, 'mahasiswa', 'Mohammad Taqi Fabwaz Nabili', '<p>Untuk jam tersebut, saya masih ada kelas. Apakah ada waktu lain?</p> <p>Apabila tidak, jam tersebut tidak apa-apa. Bisa saya izin kelas terlebih dahulu</p>', '2023-05-02 09:52:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2823, 1176, 101037, 'mahasiswa', 'Dewi Sekar Arum', '<p><span style="vertical-align:inherit"><span style="vertical-align:inherit">Untuk menghubungi dospem saya juga kurang berani karena dospem saya termasuk killer sedangkan DPA saya sulit untuk dihubungi berdasarkan pengalaman anak bimbingan Tugas akhirnya dimana dospem dan DPA tersebut berbeda orang kalau di fakultas saya, seperti apa seharusnya saya bersikap?</span></span></p>', '2023-05-02 09:54:48');
