INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2898, 1200, 1, 'admin', 'Nora Silvana', '<p>Terima kasih sudah menggunakan layanan konseling. Saya yakin situasi yang Anda alami saat ini pastinya tidak mudah. Untuk itu, apakah Anda bersedia untuk melakukan konseling?</p> <p>Saya tunggu konfirmasinya 1x24 jam.</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-05-12 11:18:59');
