INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2900, 1207, 101059, 'mahasiswa', 'Azzahra Aurelia Syafni', '<p>195030900111019<br />Saya merasa hidup saya kosong, hampa. Dan akhir akhir ini, saya kepikiran kalau saya mau dijemput aja. Saya takut bunuh diri, tapi saya mau pulang. Awalnya pemikiran itu gak mengganggu saya. Tapi makin kesini, pemikiran itu jadi gangguan buat saya. Karena saya berpikir sebentar lagi saya akan pulang, saya jadi ninggalin tanggung jawab saya. Salah satunya skripsi saya. Saya bingung, saya harus apa. Dan saya juga kecanduan hal-hal buruk yang merusak diri saya sendiri. Saya jadi makin merasa gak layak buat hidup dan menjalani kehidupan sosial layaknya orang-orang lainnya. Karna saya orang yang buruk.</p>', '2023-05-12 11:21:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2901, 1205, 1, 'admin', 'Nora Silvana', '<p>Terima kasih sudah menggunakan layanan konseling. Saya yakin situasi yang Anda alami pastinya tidak mudah. Berkaitan dengan itu, apakah kakak berkenan untuk dijadwalkan konseling dengan konselor pada hari Rabu, 17 Mei 2023 pukul 10.00 WIB?</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-05-12 11:48:35');
