INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2918, 1208, 100243, 'mahasiswa', 'Nora Silvana', '<p>Sudah dijadwalkan konseling dengan konselor.</p>', '2023-05-14 12:16:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2919, 1212, 100669, 'mahasiswa', 'Faiza Salsabila', '<p>Saya Faiza dari fak. Ilmu Kesehatan NIM 225170207111039. Sebelumnya saya sudah pernah mengajukan tiket e conseling UB pada awal semester 1 TA 2022/2023 sekitar bulan agustus-november namun belum ada respon sampai sekarang. Saya memiliki masalah pribadi (keluarga, overthinking, kesedihan terus menerus) yang kemudian berdampak pada masalah akademik (nilai) dan masalah sosial (hub. pertemanan, organisasi). Sekarang saya merasakan masalah2 tersebut semakin rumit, otak saya berat karena overthinking, saya sudah mencoba menghentikannya namun malah muncul perasaan ingin menyudahi semua ini dengan suicide action, setelah lama tidak memikirkannya. Tolong saya, selama ini saya tidak pernah bisa membicarakan masalah saya dengan orang lain secara leluasa. Saya memiliki rasa tidak enakan yang besar dan tahu orang lain memliki masalahnya sendiri2 maka dari itu saya susah terbuka dengan orang lain terkait masalah pribadi. Saya merasa butuh bantuan profesional dengan harapan saya bisa lebih terbuka dan masalah dalam diri saya bisa selesai. Tolong, saya takut pada akhirnya saya yang membunuh diri saya sendiri.</p>', '2023-05-14 12:31:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2920, 1213, 100669, 'mahasiswa', 'Faiza Salsabila', '<p>Saya Faiza S dari Fak. Ilmu Kesehatan dengan NIM 22517020711039. Saya sebelumnya sudah pernah mengajukan tiket konseling dengan kode #000744 pada bulan oktober 2022 namun belum mendapat respon sampai sekarang. Gambaran permasalahan saya kurang lebih ada di tiket #000744. Sekarang saya merasa permasalahan saya semakin pelik sampai membuat saya terpikir untuk melakukan tindakan bunuh diri. Saya menyimpan banyak masalah saya sendiri karena saya tidak enak menceritakan hal ini kepada orang2 dekat. Rasanya menyesakkan hidup seperti ini, saya mohon respon dari Ibu/Bapak sekalian untuk tindakan lanjut berupa konseling tatap muka. Saya sungguh mengharapkannya dari lama.  Tolong saya, saya butuh bantuan untuk mempertahankan hidup ini. Terima kasih</p>', '2023-05-14 12:39:23');
