INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2968, 1221, 101073, 'mahasiswa', 'Rifdah Tsabita', '<p>Saya sempat mengalami kekerasan saat masih kecil, saat saya sudah mulai beranjak dewasa saya sudah jarang menerima kekerasan dalam bentuk fisik. Namun sekarang berlanjut ke ayah saya yang suka bermain wanita dan kekerasan verbal terhadap ibu saya.</p>', '2023-05-19 11:48:54');
