INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2991, 1231, 101084, 'mahasiswa', 'Bintang Al Rasyid', '<p>205150300111069</p> <p>Akhir-akhir ini saya merasa sedih dan overwhelmed sehingga mudah menjadi marah dan saya adalah orang yang ketika marah menjadi meledak-ledak. Saya rasanya ingin mendapatkan validasi tentang apa yang saya rasakan memang berhak saya rasakan, saya meragukan diri saya sendiri bahwa saya adalah masalah sejati dari yang saya rasakan. Saya harap saya bisa menemukan solusi setelah berkonsultasi. </p>', '2023-05-23 14:07:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2992, 1232, 101084, 'mahasiswa', 'Bintang Al Rasyid', 'Saya akhir-akhir ini merasa sedih dan overwhelmed, saya sulit mendefiniskan perasaan saya. Saya ingin menemui tenaga profesional untuk membantu saya mengenai perasaan yang saya alami.', '2023-05-23 15:01:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2993, 1233, 100380, 'mahasiswa', 'Azriel Akbar Al Fajri', '<p>195020501111029. Sudah lama didiagnosis Moderate Depressive Episode, hanya sudah hampir 1/2 tahun belum konsultasi lagi ke profesional. Selain itu, saya juga merasa terganggu dengan orientasi seksual saya yang cenderung tertarik kepada sesama dan lawan jenis.</p>', '2023-05-23 20:25:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2994, 1234, 101085, 'mahasiswa', 'Aulia Savira Fitri', '<p>Perkenalkan saya Aulia dari FIB angkatan 2022, dengan NIM 225110501111024. Pertama-tama, alasan saya ingin membuat tiket ini sesimpel saya ingin bercerita. Selama ini saya tidak pernah punya tempat untuk bercerita, saya tidak punya ibu, dan ayah saya..sudah lupa. Teman-teman saya, tidak seharusnya mendengar cerita saya, karna mereka tidak pernah tau sisi diri saya yang ini. <span style="font-size:1em">Kehilangan seseorang sudah beberapa kali saya lalui, semuanya orang yang saya sayang, dan perginya mereka tak dapat ditunggu karena mereka tlah pulang ke atas.  Saya hanya merasa hilang arah di tengah hiruk pikuk dunia yang saat ini saya jalani. Segala macam tugas kuliah maupun Canda tawa seakan hampa bagi saya. </span></p>', '2023-05-23 22:13:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2995, 1235, 101086, 'mahasiswa', 'marsha regita', '<p>205110207111003</p> <p>masalah saya ialah saya tidak bisa membedakan apakah yang dikatakan mereka itu sesuai dengan pikiran saya atau saya hanya halusinasi. saya bisa membaca orang dari gerak tubuh mereka. saya bisa tahu orang tersebut marah atau tidaknnya. saya tidak bisa membedakan apakah itu nyata atau hanya kepala saya yang ramai. saya mempunyai trauma oleh ibu saya. saya tidak pernah cerita ke siapapun. saya hanya bisa memendam semuanya sendirian. maaf jika saya terlalu banyak bicara. terima kasih atas perhatiannya.</p>', '2023-05-24 04:23:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (2996, 1230, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote><p>Tidak ada uang</p></blockquote> <p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda alami saat ini tidaklah mudah. Bisa diceritakan lebih lanjut maksud dari tidak ada uang itu seperti apa? Mohon untuk memberikan jawaban 1x24 jam. Terima kasih.<br /><br />Salam hangat,<br />Tim Konseling UB.</p> <p><br /></p>', '2023-05-24 07:01:56');
