INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3077, 1258, 1, 'admin', 'Nora Silvana', '<p>Terima kasih telah menggunakan layanan konseling. Saya yakin situasi yang Anda alami saat ini tentunya tidak mudah apalagi terdapat kerugian akibat penipuan online tersebut. Untuk saat ini, coba kumpulkan dan amankan setiap bukti yang ada yaa. Kemudian, apakah Anda sudah mencoba untuk melaporkan ke pihak berwenang?</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-05-31 13:23:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3078, 1255, 1, 'admin', 'Nora Silvana', '<p>Terima kasih telah menggunakan layanan konseling. Saya yakin situasi yang Anda alami saat ini tentunya tidak mudah dan membuat tidak nyaman. Sebelumnya, boleh tolong diceritakan lebih lanjut mengenai rasa takut dan depresi yang Anda alami?</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-05-31 13:26:05');
