INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3097, 1258, 1, 'admin', 'Nora Silvana', '<p>Baik, kalau begitu bisa dicoba untuk melaporkannya terlebih dahulu yaa karena penipuan tersebut merupakan tindakan melanggar hukum yang bisa diproses oleh kepolisian. Anda juga bisa melaporkannya secara online melalui lapor.go.id. Sekian yang dapat kami sampaikan. Terima kasih.</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-06-01 11:24:45');
