INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3100, 1260, 1, 'admin', 'Nora Silvana', '<p>Terima kasih telah menggunakan layanan konseling. Saya yakin situasi yang Anda alami saat ini tentunya tidak mudah. Sebelumnya, boleh tolong diceritakan lebih lanjut mengenai kondisi Anda saat ini yang membuat Anda berpikir terkait OCD?</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-06-01 11:33:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3101, 1259, 1, 'admin', 'Nora Silvana', '<p>Terima kasih telah menggunakan layanan konseling. Saya yakin situasi yang Anda alami saat ini tentunya tidak mudah. Sebelumnya, boleh tolong diceritakan terkait mengapa Anda merasa selalu diabaikan dan dijauhkan? Apakah pernah ada suatu kejadian yang membuat Anda merasakan hal itu?</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-06-01 11:36:28');
