INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3114, 1264, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Terima kasih telah menggunakan layanan konseling. Bisakah Anda menceritakan lebih lanjut mengenai permasalahan tersebut?</p> <p><br /></p> <p><br /></p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2023-06-03 19:57:55');
