INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3159, 1277, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Terima kasih telah menggunakan layanan konseling. Saya memahami bahwa apa yang Anda miliki tidaklah mudah. Apakah Anda berkenan untuk kami jadwalkan konseling tatap muka?</p>', '2023-06-11 16:03:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3160, 1284, 100355, 'mahasiswa', 'Intan Diyah Kusumawati', '<p>Saya Intan Diyah Kusumawati dengan NIM 215100200111031 dari Fakultas Teknologi Pertanian, prodi Teknik Pertanian dan Biosistem, saya sering tiba-tiba gelisah dan merasa bersalah ketika sedang tidak ada kegiatan, selalu ada perasaan mengganjal bahkan sampai sesak nafas atau sakit kepala, selalu takut mengambil jalan sesuai keinginan saya karena takut kalau saya egois, saya kehilangan sahabat yang saya rasa mengenal saya, bahkan dia tau semua masalah saya begitupun sebaliknya, saya merasa perpisahan itu terlalu tiba-tiba dengan perubahan sifat yang susah saya terima bahkan hingga lostcontact, kejadian dimulai dari bulan Januari 2020. Walaupun saya diblokir tetapi sering di unblok dan berakhir berantem lagi, dan begitu terus siklusnya, hingga terakhir bulan Februari kemarin. Ketika saya sudah ikhlas dia kembali dengan sifatnya yang dulu, dan setelahnya akan kembali berantem. Dan sekarang ketika saya sudah bisa beradaptasi tanpa keberadaan nya, dia kembali mengajak berdamai dan bersifat seolah-olah tidak ada apa-apa sebelumnya. Disamping itu, saya merasa capek menahan pikiran sendiri terlebih ketika merasa capek karena tugas dan laporan praktikum, serta kegiatan organisasi yang cukup padat. Saya awalnya memilih join organisasi karena merasa butuh teman sehingga memiliki pelampiasan untuk melupakan semua hal yang terjadi dalam hidup saya, saya merasa membutuhkan teman cerita namun saya tidak berani cerita ke temen-temen saya karena mereka juga sama merasakan yang saya rasakan, saya tidak bisa bercerita dengan keluarga sebab saya broken home sejak usia 2 tahun dan tinggal bersama nenek, saya juga harus berusaha memenuhi kebutuhan saya dengan mengandalkan KIPK. Kedua orang tua saya sudah memiliki keluarga baru masing-masing dan akhir akhir ini saya mendapatkan kabar bahwa mama saya akan bercerai untuk kedua kalinya, saya ingin hidup sedikit lebih tenang:) tidur tanpa bisikan atau potongan kejadian yang mengakibatkan merasa bersalah, bahkan mimpi tentang sahabat yang sudah lostcontact tersebut:) dan ingin tidur tanpa bantuan minum obat :'') terima kasih</p>', '2023-06-11 17:11:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3161, 1285, 101131, 'mahasiswa', 'Intan Diyah Kusumawati', '<p>Saya Intan Diyah Kusumawati dengan NIM 215100200111031 dari Fakultas Teknologi Pertanian, prodi Teknik Pertanian dan Biosistem, saya sering tiba-tiba gelisah dan merasa bersalah ketika sedang tidak ada kegiatan, selalu ada perasaan mengganjal bahkan sampai sesak nafas atau sakit kepala, selalu takut mengambil jalan sesuai keinginan saya karena takut kalau saya egois, saya kehilangan sahabat yang saya rasa mengenal saya, bahkan dia tau semua masalah saya begitupun sebaliknya, saya merasa perpisahan itu terlalu tiba-tiba dengan perubahan sifat yang susah saya terima bahkan hingga lostcontact, kejadian dimulai dari bulan Januari 2020. Walaupun saya diblokir tetapi sering di unblok dan berakhir berantem lagi, dan begitu terus siklusnya, hingga saat ini beberapa hari yang lalu ia kembali dan mengajak berdamai tanpa merasa bahwa sebelumnya tidak ada apa apa. Ketika saya sudah ikhlas dia kembali dengan sifatnya yang dulu, dan setelahnya akan kembali berantem. Disamping itu, saya merasa capek menahan pikiran sendiri terlebih ketika merasa capek karena tugas dan laporan praktikum, saya membutuhkan teman cerita namun saya tidak berani cerita ke temen-temen saya karena mereka juga sama merasakan yang saya rasakan, saya tidak bisa bercerita dengan keluarga sebab saya broken home sejak usia 2 tahun dan tinggal bersama nenek, saya juga harus berusaha memenuhi kebutuhan saya dengan mengandalkan KIPK. Kedua orang tua saya sudah memiliki keluarga baru masing-masing dan akhir akhir ini saya mendapatkan kabar bahwa mama saya akan bercerai untuk kedua kalinya, saya ingin hidup sedikit lebih tenang:) tidur tanpa bisikan atau potongan kejadian yang mengakibatkan merasa bersalah, bahkan mimpi tentang sahabat yang sudah lostcontact tersebut:) dan ingin tidur tanpa bantuan minum obat :'') terima kasih</p>', '2023-06-11 17:43:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3162, 1278, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Terima kasih telah menggunakan layanan konseling. Berkaitan dengan permasalahan tersebut, apakah Anda bersedia apabila saya jadwalkan dengan peer counselor?</p>', '2023-06-11 20:17:12');
