INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3173, 1282, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Terima kasih telah menggunakan layanan konseling. Apabila menceritakan lebih lanjut mengenai permasalahan Anda dapat meringankan Anda, kami bersedia untuk mendengarkan ya. Apakah Anda menginginkan konseling tatap muka?</p> <p><br /></p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2023-06-11 21:37:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3174, 1283, 101130, 'mahasiswa', 'Alif Ichsan Muttaqin', '<p>Begini saya punya masalah saya ga bisa dekat secara intim dengan teman teman saya dan hal itu mengganggu saya dan membuat saya sedih dan setelah saya cari tau saya sepertinya mempunyai avoidant attachment saya ingin berkonsultasi saja untuk mencari solusi yang terbaik terimakasih </p>', '2023-06-11 21:43:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3175, 1283, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Baik, apakah Anda bersedia untuk kami jadwalkan dengan konselor psikolog kami pada tanggal 22 Juni pukul 09.00-10.00?</p>', '2023-06-11 21:50:35');
