INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3186, 1287, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote><p>226030317111001 saya merasa lelah dengan bimbingan tesis yang saya alami, dalam 1 bulan hanya bisa bimbingan sekali saja dengan dosen 2, respon dosen 2 yang lambat dan sangat sibuk, bahkan ketika tanya “kapan saya bisa bimbingan” beliau malah meminta saya untuk mencari dosen baru saja. Hal ini membuat saya lelah dan merasa frustasi. Sedangkan dosen bimbingan ada 2 pembimbing. sangat melelahkan rasanya dan membuat saya ingin menyerah dan mengakhiri ini semua </p></blockquote> <p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Bagaimana jika Anda saya jadwalkan sesi konseling online dengan konselor pada Rabu, 21 Juni 2023 pukul 09.00 WIB melalui Google Meet? Mohon konfirmasinya 1x24 jam. Terima kasih. <br /><br />Salam hangat,<br />Tim Konseling UB. </p>', '2023-06-12 20:35:43');
