INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3190, 1291, 101133, 'mahasiswa', 'Muhammad Rafi Amrullah', '<p>195060200111025. Saya adalah orang yang ambisius, optimis. Kemudian saya mengikuti beberapa tes kerja salah satunya ada yang lanjut sampai interview user. Akan tetapi saya belum dipanggil di interview usernya, padahal saya kira interviewnya bukanlah suatu hal yang susah. Dan hal tersebut sangat mempengaruhi saya, saya menjadi tidak produktif, selalu berfikir bagaimana hasilnya (karena yang lain sudah ada panggilan mcu). Apa yang harus saya lakukan untuk menjadi semangat lagi, karena saya kira untuk sekarang saya seperti bukan orang "hidup" lagi, tidak mempunyai gairah sama sekali untuk melakukan semua hal. Terima kasih</p>', '2023-06-13 16:34:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3191, 1292, 100919, 'mahasiswa', 'Indah Larasati', '<p>205070207111011, halo saya Indah dari jurusan keperawatan. Saya ingin bercerita sekali karena saya merasa takut tidak berhasil di jurusan yang saya geluti sekarang, saya khawatir tidak bisa menulis tugas akhir dengan baik. Dan saya selalu merasa homesick ketika harus menuliskan tugas akhir. Tidak hanya itu, seperti banyak sekali masalah di pikiran saya yang tidak kunjung selesai. Terima kasih</p>', '2023-06-13 18:36:16');
