INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3197, 1294, 101135, 'mahasiswa', 'Maria Gracesica Immaculata', '<p>185120300111003. Tidak bisa mengerjakan tugas skripsi, selalu kesulitan untuk fokus / selalu terdistraksi / mengantuk saat akan mengerjakan skripsi. Tidak kunjung menghubungi dosen pembimbing. Skripsi stuck di outline (sebelum bab 1)</p>', '2023-06-14 12:16:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3198, 1295, 101136, 'mahasiswa', 'Auliah Lahdhusafirah', '<p>Halo, Perkenalkan nama saya Auliah Lahdhusafirah (NIM 195060500111043) dan dapat dipanggil Safirah. Saya adalah mahasiswi semester 8 di Jurusan Arsitektur Fakultas Teknik UB <br /><br />Tujuan saya menghubungi konseling ini adalah ingin menanyakan hal-hal yang mengganggu saya beberapa bulan terakhir ini. Dari bulan januari akhir kemarin saya di diagnosa dokter terkena penyakit LPR (Laryngopharyngeal Reflux) yang menyebabkan asam lambung saya naik hingga ke tenggorokan dan menyebabkan bengkak hingga sakit. saya sudah menjalani pengobatan dari bulan januari akhir sampai ganti dokter 3 kali dikarenakan tidak adanya perubahan yang signifikan dari sakit yang saya alami, walaupun sudah mengubah pola makan, menjalani diet, dan menjauhi pantang makan, serta minum obat teratur. Hasil diagnosa dokter yang saya dapatkan selalu baik secara organ melalui tes tes yang dilakukan.<br /><br />Dari ketiga dokter tersebut, saya selalu ditanyakan apakah sedang stress? dan saya menjawab sempat stress karena beban semester lalu yang cukup berat, tapi sekarang sudah tidak. Kemudian dua dari ketiga dokter tersebut meresepkan dalam racikannya obat penenang yang sempat saya konsumsi (Proclozam dan Alprazolam) yang saya baca merupakan salah satu obat untuk gangguan kecemasan. Maka dari itu saya menulis summary singkat dengan kecemasan. Jujur saya sendiri juga kurang tahu menahu mengenai obat tersebut.<br /><br />Hal ini membuat saya memutuskan untuk menghubungi konseling untuk mencari tahu apakah sebenarnya saya masih mengalami stress tersebut tanpa saya sadari atau tidak. Jujur saja, saya memang tipe anak yang banyak mikir (overthinking) dikarenakan satu dan lain hal. Mungkin apa itu jadi penyebabnya? saya juga kurang tau <br /><br />Saya harap deskripsi singkat ini dapat menjelaskan kondisi saya yang bingung untuk menghadapi penyakit ini. saya harap saya dapat menemukan jawaban dan bisa menyelesaikan permasalahan saya ini :(<br /><br />Terima kasih :)</p>', '2023-06-15 14:20:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3199, 1282, 101129, 'mahasiswa', 'Andini Laily Putri', '<p>Sudah tertangani melalui whatsapp</p>', '2023-06-15 15:40:12');
