INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3253, 1303, 101143, 'mahasiswa', 'Vianta Mandhalika', '<p>Saya merupakan alumni mahasiswa PSP FPIK sekaligus camaba fakultas pascasarjana jalur beasiswa PMDSU. Saya memiliki masalah yang menganggu aktifitas sehari-hari. Saya tidak mampu berpikir jernih, saya sedih berkepanjangan, saya selalu merasa lelah, saya ingin tidur sepanjang hari, dan saya selalu cemas serta takut. Bulan Agustus, saya sudah akan memulai pendidikan, dan saya diharuskan sudah sembuh dengan permasalahan tersebut. Kiranya bapak/ibu dapat membantu permasalahn saya.</p>', '2023-06-21 13:27:25');
