INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3280, 1312, 101151, 'mahasiswa', 'Salma Hanandifa Aflanda', '<p>Halo ibu/bapak konselor perkenalkan nama saya Salma Hanandifa Aflanda dari Fakultas Teknik prodi Teknik Kimia dengan NIM 225061101111015. izin menyampaikan permasalahan konselling yang akan saya ceritakan ke ibu/bapak. Sebenarnya ini sungguh masalah sepele kalau dilihat dengan kebanyakan orang, tapi semakin saya pikirkan rasanya sangat sakit sekali. saya punya beberapa teman dan sempat kami pergi bersama untuk sekedar bermain atau mengerjakan tugas dari dosen secara bersama. tapi semenjak saya tidak ikut satu kegiatan mereka, ada yang berbeda lalu saya menemui teman" saya membuat grup wa tanpa saya, awalnya saya hanya membiarkan dan bodo amat. tapi semakin hari, saya merasa saya asing bahkan saya dengan mereka satu kelas. saya merasa kesepian, hingga kadang setiap malam saya selalu menangis, saya merasa saya tidak berharga bagi siapapun, saya bertanya-tanya saya salah apa, tapi hasilnya saya sendiri yang lelah dan mental saya selalu lemah soal pertemanan disini. sampai berimbas pada akademik saya, sehingga ipk saya anjlok, rasanya sungguh sakit dah kecewa sekali. mohon solusinya, masalah ini sudah 2 bulan dan setiap hari saya selalu menangis menangis dan menangis. saya harus gimana yaa</p>', '2023-06-29 19:54:06');
