INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3302, 1319, 101154, 'mahasiswa', 'Aufa Nabila Putri Andriani', '<p>203141614111009</p> <p>Adanya perasaan tidak nyaman ketika berada disekitar teman-teman, merasa kurang didengarkan dan tidak mampu menginfluence orang disekitarku untuk mau mendengarkan ceritaku. merasa kurang asik untuk kiranya dapat dihargai oleh mereka <br /></p> <p><br /></p>', '2023-07-02 20:40:12');
