INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3304, 1320, 101155, 'mahasiswa', 'olga maheswari anandya', '<p>195120101111018</p> <p>masalah yang saya hadapi saat ini secara singkat yaitu masalah keluarga, dimana saya merupakan anak satu satunya dan mama papa saya berpisah. saya susah percaya dengan orang lain karena menurut saya keluarga saya pun menyakiti saya. saya pribadi yang sukit melupakan kesalahan orang lain dan sulit percaya karena beberapa trauma yang saya alami</p>', '2023-07-03 12:20:20');
