INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3327, 1326, 101161, 'mahasiswa', 'Alda Meutia Ilyas', '<p>205030700111032 - Saya gak berani membuka diri saya ke orang lain dan membiarkan orang lain masuk ke kehidupan saya. Akhirnya saya bangun tembok yang tinggi yang buat orang lain gak nyaman dan pergi. Tapi akhirnya saya merasa sendirian dan ditinggalkan. Masalah yang lain adalah saya terlalu sering mengkonsumsi obat pereda nyeri. Dan saya merasa bingung apakah sakit yang dirasakan hanya sugesti atau tidak. </p>', '2023-07-07 17:22:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3328, 1327, 101162, 'mahasiswa', 'Nur Zahrah Afifah Hasibuan', '<p>215080507111051 </p> <p>Saya bingung harus apa, saya merasa permasalahan pribadi berpengaruh terhadap akademik saya. Saya bingung harus apa. Saya meminta bantuan ke layanan psikolog ub untuk hal ini</p>', '2023-07-07 21:49:01');
