INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3374, 1338, 101167, 'mahasiswa', 'Dinda Rizki Rahmayanti', '<p>(205070601111015) Akhir-akhir ini, saya sering merasa cemas dan khawatir karena saya merasa bahwa saya tidak mampu, sering kehilangan fokus dalam kegiatan sehari-hari, kepercayaan diri menurun, dan kadang-kadang suka lupa. Saya sudah mencoba untuk meyakinkan diri bahwa saya pasti bisa dan baik-baik saja, tapi ternyata rasa cemas dan khawatir itu muncul lagi. Saya takut kalau saya tidak bisa survive kedepan, mohon bantuannya</p>', '2023-07-17 14:37:33');
