INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3424, 1355, 101179, 'mahasiswa', 'Akhmad Isna', '<p>Terima kasih atas balasan dan empatinya.</p> <p>Izin memaparkan situasi, saya sekarang PPDS Kardiologi stase Cathlab di mana di jam kerja senin-jum''at 07.00-16.00 (bila hari senin dan rabu sampai malam jam 22.00), jam jaga, dan saat ada aktivasi Primary PCI krn ada pasien serangan jantung belum bs hadir offline. Singkatnya, Kamis 10 Agustus 2023 jam 09.00 WIB belum bisa. Mohon arahannya. Bila memang jadwalnya harus di jam kerja, tidak bisa. Apa mungkin harus online? Terima kasih.</p>', '2023-07-30 19:18:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3425, 1356, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote><p>NIM: 195110201111017</p> <p>Pengalaman bertahun-tahun dibully dan sering diejek beramai-ramai membuat saya takut setiap saat mendengar suara tawa atau berinteraksi dengan orang lain. Jadi saya terkadang menjauh dari orang-orang terlebih dari orang-orang yang karakteristiknya mirip dengan pembully saya. Pada akhirnya, saya disalahpahami lagi dan rumor-rumor aneh tentang saya seperti tidak bisa saya hentikan. Saya rasa apapun yang saya lakukan salah dan saya tidak akan pernah punya tempat yang layak sebagai orang baik dan tidak bisa tenang sedikitpun tanpa memikirkan orang-orang akan menertawakan saya atau mengatakan hal buruk tentang saya. Tidak peduli seberapa baik saya mencoba menolong orang lain saat mereka membutuhkan, mereka akan tetap mengejek saya. Apakah saya orang yang sangat buruk hingga harus diperlakukan seperti ini? Apa saya tidak akan pernah bisa tenang? Saya juga tidak memaksa orang-orang untuk menjadi teman saya dan menolong saya, tapi kenapa beberapa orang sangat jahat? Apa saya kurang baik saat menolong mereka? </p></blockquote> <p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Apakah Anda berkenan untuk saya jadwalkan konseling dengan konselor supaya lebih nyaman Anda dalam bercerita? Anda akan saya jadwalkan pada Jumat, 11 Agustus 2023 pukul 09.00 WIB secara offline. Mohon konfirmasinya 1x24 jam. Terima kasih.<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-07-30 19:58:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3426, 1349, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote><p>Boleh pak/bu utk dialihkan ke bkm fisip</p></blockquote> <p>Baik kalau begitu. Anda akan saya hubungi melalui whatsapp untuk memudahkan komunikasi. Terima kasih.<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-07-30 20:00:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3427, 1356, 100925, 'mahasiswa', 'Salsabila rahmah', '<p>Terima kasih atas jawabannya. Saya akan hadir dalam jadwal yang disebutkan tadi. Terima kasih. </p>', '2023-07-30 20:07:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3428, 1355, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote><p>Terima kasih atas balasan dan empatinya.</p> <p>Izin memaparkan situasi, saya sekarang PPDS Kardiologi stase Cathlab di mana di jam kerja senin-jum''at 07.00-16.00 (bila hari senin dan rabu sampai malam jam 22.00), jam jaga, dan saat ada aktivasi Primary PCI krn ada pasien serangan jantung belum bs hadir offline. Singkatnya, Kamis 10 Agustus 2023 jam 09.00 WIB belum bisa. Mohon arahannya. Bila memang jadwalnya harus di jam kerja, tidak bisa. Apa mungkin harus online? Terima kasih.</p></blockquote> <p>Sangat memungkinkan untuk secara online yaa. Kalau begitu, apakah Anda tetap berkenan di tanggal dan jam tersebut secara online? Atau Anda berkenannya kapan? </p>', '2023-07-30 20:26:17');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3429, 1356, 100925, 'mahasiswa', 'Salsabila rahmah', '<p>Mohon maaf saya izin bertanya, untuk lokasi konsulnya persisnya di mana, ya? Terima kasih sebelumnya. </p>', '2023-07-30 20:31:47');
