INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3442, 1361, 1, 'admin', 'Nora Silvana', '<p>Terima kasih telah menggunakan layanan konseling. Saya yakin situasi yang Anda alami saat ini tentunya tidak mudah. Dengan begitu, apakah Anda berkenan untuk dijadwalkan konseling online (via google meet) hari Kamis, 10 Agustus 2023 pukul 14.00 WIB?</p> <p>Mohon konfirmasinya 1x24 jam yaa.</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-08-01 15:12:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3443, 1358, 1, 'admin', 'Nora Silvana', '<p>Terima kasih telah menggunakan layanan konseling. Saya yakin situasi yang Anda alami tentunya tidak mudah. Sebelumnya saya ingin bertanya, apakah Anda sudah pernah berkonsultasi atau berdiskusi dengan DPA sebelumnya? misalnya terkait cuti kuliah dulu atau permasalahan akademik lain yang pernah dihadapi?</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-08-01 15:42:46');
