INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3488, 1372, 101192, 'mahasiswa', 'Izzatul Fikri Al-Ghifani', '<p>205100600111016</p> <p>Saya mendampingi mahasiswa yang mentalnya sedikit terganggu dan menyebabkan kerugian di beberapa kegiatan fakultas maupun universitas </p>', '2023-08-13 21:18:20');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3489, 1373, 101193, 'mahasiswa', 'Hujjatullah', '<p>Perkenalkan, saya Hujja dari FPIK dengan NIM 195080400111030. Saya sedang merasa lelah, bingung dan tertekan dengan apa yang harus saya hadapi saat ini, saya punya tanggungjawab yang cukup berat sebagai seorang kepala sebuah organisasi yang sedang berjalan kurang baik di bawah kepemimpinan saya, saya juga sedang merasa bingung dengan tanggungjawab akademik saya karena belum melaksanakan sidang magang dan skripsi. Di rumah saya juga saat ini terasa tidak begitu bisa menjadi tempat pulang karena ayah saya temperamental dan tidak begitu bisa mengayomi keluarganya, saya hanya punya sosok ibu. Sedangkan saat ini juga saya sedang merasa sulit secara finansial. Kepala saya rasanya hanya berputar-putar dengan masalah-masalah tersebut, dan merasa bingung mau melakukan apa dengan tekanan yang cukup berat. hehe</p>', '2023-08-14 05:55:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3490, 1374, 100989, 'mahasiswa', 'nur hanifa maulidia', '<p>194140314111013</p>', '2023-08-15 02:55:43');
