INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3532, 1390, 1, 'admin', 'Nora Silvana', '<p>Terima kasih telah menggunakan layanan konseling. Saya yakin situasi yang Anda alami saat ini tentunya tidak mudah. Sayangnya, layanan konseling ini hanya dapat diakses oleh mahasiswa aktif Universitas Brawijaya. Untuk itu, Anda dapat menghubungi layanan psikologis lainnya seperti di puskesmas atau rumah sakit terdekat yaa.</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-08-21 22:24:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3533, 1386, 1, 'admin', 'Nora Silvana', '<p>Untuk jadwalnya masih kami carikan jadwal yang kosong yaa. Konselingnya bisa online atau offline. Kalau online via google meet, konseling offline dilaksanakan di Ruang Konseling Lantai 3 Gedung Rektorat. Kalau dari Anda sendiri menginginkan konseling secara online atau offline yaa?</p>', '2023-08-21 22:27:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3534, 1393, 1, 'admin', 'Nora Silvana', '<p>Terima kasih telah menggunakan layanan konseling. Saya yakin situasi yang Anda alami saat ini tentunya tidak mudah. Berhubung Anda berasal dari FISIP, maka saya ingin menginformasikan bahwa di FISIP telah ada Badan Konseling Mahasiswa (BKM FISIP). Maka dari itu, Anda akan saya alihkan ke BKM FISIP yaa, supaya dapat lebih cepat tertangani.</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-08-21 22:32:13');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3535, 1392, 1, 'admin', 'Nora Silvana', '<p>Terima kasih telah menggunakan layanan konseling. Tremor dan detak jantung tak beraturan merupakan reaksi fisiologis yang wajar terjadi apabila kita dihadapkan pada situasi yang membuat takut atau gugup, seperti saat giliran untuk maju sesuai dengan yang Anda sampaikan. Apakah lantas ketika mengalami hal tersebut dapat dikatakan mengalami gangguan mental? Belum tentu yaa, karena indikator gangguan mental tentunya beragam dan ada beberapa hal yang perlu dipertimbangkan dalam menegakkan diagnosis gangguan mental.</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-08-21 22:39:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3536, 1391, 1, 'admin', 'Nora Silvana', '<p>Terima kasih telah menggunakan layanan konseling. Kami akan segera mencarikan jadwal yang tersedia dan menghubungi Anda via WhatsApp yaa.</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-08-21 22:40:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3537, 1386, 101204, 'mahasiswa', 'Indana Ulfa Izzati Buchari', '<p>maunya sih offline, tapi tergantung kapan di kasih jadwalnya. kalo bentrok sama urusan lain palingan pindah ke online </p> <p>tapi diusahain bgt offline ajaa</p>', '2023-08-22 02:33:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3538, 1394, 101210, 'mahasiswa', 'Daniel Arie Nugrahantyo', '<p>195030101111099<br />Daniel Arie Nugrahantyo - FIA UB<br /><br /></p> <p>Saat ini saya sudah di semester 9, saya sudah mulai memasukkan Skripsi ke KRS sejak semester 7, namun saya masih stuck sejak saat itu.<br />Saya bingung dengan diri saya sendiri, sempat ada masalah pribadi dengan teman di perkuliahan, sehingga membuat kondisi mental saya tidak stabil, menjadi lebih murung, dan menarik diri dari hubungan sosial.<br /></p>', '2023-08-22 14:41:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3539, 1386, 1, 'admin', 'Nora Silvana', '<p>Baik kalau begitu. Kami akan carikan peer counselor yang available yaa. Mohon ditunggu informasi selanjutnya.</p>', '2023-08-22 14:48:28');
