INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3541, 1396, 101211, 'mahasiswa', 'Nadia Fauziah', '<p>225020400111034 - Belakangan ini saya sering merasa bahwa saya mengalami masalah empati yang membuat saya sering salah dalam pengambilan keputusan sehingga membuat renggangnya pertemanan bahkan keluarga. Hal itu cukup mengganggu saya beraktivitas sehari-hari karena terlalu sering memikirkan bagaimana cara saya agar dapat memperbaiki semua kesalahan saya. </p>', '2023-08-22 16:44:07');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3542, 1397, 101212, 'mahasiswa', 'Afiyati Yulia Andini', '<p>235080100111010</p> <p>Sulit menerima jurusan dan lingkungan yang sekarang membuat saya tidak pd dan membuat saya kehilangan diri saya yang dulu.</p>', '2023-08-22 17:32:04');
