INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3571, 1406, 101223, 'mahasiswa', 'Aulia Ramadhini Amdika Putri', '<p>233140500111106 saya adalah orang yg sulit untuk membuka diri semua nya bermula saat SMP mereka semua bercircle-cirle dan mereka benci orang yg menurut mereka kurang berisik, kurang berbicara semenjak itu saya dikucilkan oleh mereka dan jadi pribadi yg pendiam tapi di SMA saya bersyukur mempunyai teman dan circle yang baik banget sama saya mungkin karena kita sama-sama cocok kita jadi temenan terus sejak itu saya mulai belajar berkomunikasi dengan orang baru. Tapi hari ini saya seperti berada di masa SMP mereka tampak akrab saya cuma akrab sama 1 atau 2 orang dan lebih nya di luar prodi saya. Today mereka ngobrol bersama rame-rame gak semua ikut ngobrol beberapa di sampingku cuma main HP aja karena aku gatau mau ngapain kalo ngobrol sama mereka yg kayaknya udah bergeng sulit aku memilih diam main hp sambil coba basa basi sama orang di sebelah ku, tapi entah kenapa anak kanan ku ini kayak nyebelin banget aku udah antri gantian dia asal ambil aja alhasil aku nungguin setelah dia. Itu aku gak diam aku bilang "eh bentar lagi pinjem ya" dia cuma diem doang tiba-tiba asal nyomot, lalu waktu pulang tadi aku kaget dong tiba-tiba ada absen kelas tanda tangan di kertas tapi namaku ga ada padahal aku hadir loh aku ngerasa nyesek banget trauma waktu di SMP berasa bangkit lagi setiap trauma di SMP saya selalu merasa tidak ingin hidup. Waktu di SMA masih ada yg membantu saya tapi rasanya gak adil kalo kejadian SMP terulang lagi. Saya ingin bercerita kepada konseling universitas Brawijaya karena saya tidak punya tempat untuk bercerita.</p>', '2023-08-24 11:28:41');
