INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3600, 1423, 101239, 'mahasiswa', 'Savita Dayu Navisa', '<p>235110601111007</p> <p>Selamat Malam,</p> <p>Saya akan menjelaskan tentang permasalahan saya </p> <p>saya merasa masih sangat kaget dengan kehidupan kampus,</p> <p>yang ternyata sangat menguras tenaga entah itu tugas maupun</p> <p>pertemanan ini.namun jika bermalas2an</p> <p>saya takut memperlambat kelulusan.</p> <p>Kemudian saya juga merasa kesulitan mengatur waktu antara tugas </p> <p>istirahat bahkan tidak sempat main karna saya khawatir tertinggal.</p> <p>lantas saya ingin meminta solusi atau saran agar saya bisa kembali</p> <p>menjadi siswa yang aktif seperti diSMA dengan sematan MAHASISWA yang ternyata bebanya pun cukup berat ini</p> <p><br /></p> <p>Terimakasih atas perhatiannya </p> <p>Selamat Malam</p>', '2023-08-28 20:27:07');
