INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3627, 1423, 101239, 'mahasiswa', 'Savita Dayu Navisa', 'Sebenarnya saya sudah sering berkerja lebih alias mengikuti banyak kegiatan di SMA namun tidak se melelahkan ini. dan saya juga sempat berencana bergabung di sebuah organisasi internal Universitas Brawijaya namun saya belum bisa menentukan sebagai mahasiswa baru apa boleh langsung pada organisasi besar seperti EM Ub atau di tingkat fakultas seperti BEM FIB Ub, Mohon sarannya', '2023-08-29 19:20:41');
