INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3638, 1430, 101244, 'mahasiswa', 'Muhammad Udhian Sidqi', '<p>Nama saya Sidqi, NIM. 195060600111051. Saya merupakan mahasiswa semester 9 dan saat ini sedang menempuh tugas akhir.. Saya sudah menjalani 4x presentasi untuk tugas akhir mulai dari sempro, pra semhas, semhas dan semhas mengulang. disaat semhas itu mental saya down sekali, banyak faktor salah satunya adalah masukan dosen dan lain sebagainya, dari situ saya masih belum bisa bangkit dari keterpurukan. Untuk menjalani aktivitas seperti biasa rasanya sangat tidak produktif. Saya paham revisi itu harus segera saya selesaikan, tapi ada luka yang membuat saya enggan untuk bangkit. Entah kenapa perasaan takut untuk mencoba lagi itu selalu menghantui, beberapa kali sampai harus masuk ke mimpi saya. Saya pernah mengadukan hal tersebut ke pembimbing skripsi, tapi infonya malah tersebar luas ke dosen lainnya (penguji) perihal saya yang penakut, lemah dan lainnya. Saya juga diminta untuk meningkatkan ibadah. sudah saya coba, hal tersebut tapi rasa takut itu masih tetap ada. </p> <p>Saya tidak menyalahkan faktor eksternal seluruhnya terkait mental saya yang down ini, entah mengapa tuhan ciptakan saya menjadi pria yang sangat sensitif, penuh perasa dan gampang terpikirkan. Mungkin itu gambaran dari permasalahan saya</p>', '2023-08-30 19:44:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3639, 1431, 101245, 'mahasiswa', 'Jessica Ananda Putri', '<p>215120307111101</p> <p>Saya merasa sedang tidak baik-baik saja secara mental, saya mudah stress dikarenakan dilingkungan yang membuat saya tidak nyaman tetapi saya harus tetap harus baik-baik saja didalamnya, saya suda merasa lelah dengan harus mengontrol diri saya, kadang rasanya saya ingin berteriak ini meluapkan apa yang sebenarnya saya rasakan tetapi tidak bisa, itu membuat saya semakin tertekan. Saya bingung jika harus meluapkan ada yang sedang saya alami sekarang, bahakan sekarangpun saya bingung harus menceritakan permasalahannya seperti apa karna terlalu rumit.<br /></p>', '2023-08-30 21:06:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3640, 1432, 101246, 'mahasiswa', 'Hilmi Fajar Ariq Wisam', '<p>215090107111036, Saya telah melakukan tindakan pelecehan yang dilakukan kepada salah satu anggota di kelompok MMD, dan saya ingin menyelesaikan masalah sesegera mungkin tanpa harus merugikan orang lain lagi</p>', '2023-08-30 22:34:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3641, 1433, 101247, 'mahasiswa', 'Hilmi Fajar Ariq Wisam', '<p>215090107111036, Saya melakukan tindakan kekerasan seksual terhadap anggota kelompok MMD, dan saya ingin segera menyelesaikan masalah ini</p>', '2023-08-31 10:04:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3642, 1414, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Baik. Bagaimana kalau saya jadwalkan konseling dengan konselor kami?</p>', '2023-08-31 11:37:07');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3643, 1423, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Untuk mahasiswa baru bisa ya mengikuti beberapa organisasi yang Anda sebutkan sebagai staf magang. Apakah sudah pernah memeriksa di laman Instagram atau media sosial lainnya?</p> <p>Untuk menentukan organisasi yang bisa Anda ikuti, bisakah Anda menuliskan hobi dan bidang apa yang Anda sukai disini?</p>', '2023-08-31 11:44:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3644, 1427, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Terima kasih telah menggunakan layanan konseling. Apakah Anda bersedia untuk kami jadwalkan konseling langsung dengan konselor kami?</p>', '2023-08-31 11:46:55');
