INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3653, 1434, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Halo, Bayu</p> <p>Terima kasih telah menggunakan layanan konseling. Kami akan mendengarkan cerita Anda dan membantu Anda apabila Anda membutuhkannya. Berkaitan dengan permasalahan tersebut, apakah ada hal yang mendasari rasa ketakutan tersebut?</p> <p><br /></p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2023-09-01 11:43:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3654, 1435, 101241, 'mahasiswa', 'Muaafii fadhlullah', '<p>NIM: 195100500111013</p> <p>- Menyelesaikan masalah gagal percintaan yang berpengaruh ke kepribadian dan hubungan ke orang tua</p> <p>- Mencari motivasi dan tujuan hidup</p> <p>- ingin bisa kembali bersemangat dan berprestasi seperti dahulu</p> <p>- ingin cepat lulus kuliah</p>', '2023-09-01 11:58:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3655, 1434, 100018, 'mahasiswa', 'Bayu Putra Negara', '<p>Asumsi saya trauma di masa lalu, Mba. Di saat saya tidak tinggal bersama orang tua, setiap hari menunggu mereka datang dan suka tiba-tiba ditinggal pulang (kondisinya saya tinggal di rumah nenek). Dan mungkin pengaruh dikucilkan juga saat saya masih SD/SMP/SMA(?) Saya merasa lingkungan saya kuliah sekarang saya merasa sangat nyaman dan dihargai sebagaimana mestinya, saya jadi takut kalau harus ditinggalkan cepat atau lambat</p>', '2023-09-01 14:58:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3656, 1434, 100018, 'mahasiswa', 'Bayu Putra Negara', '<p>Hal ini membuat saya bergantung dengan mereka, saya jadi butuh kehadiran mereka terus-menerus, padahal mereka juga punya kesibukan masing-masing dan saya paham akan hal itu. Tapi saya jadi ''takut'' ditinggalkan aja rasanya</p>', '2023-09-01 14:59:59');
