INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3670, 1425, 101241, 'mahasiswa', 'Muaafii fadhlullah', '<p>Apakah bisa dipercepat lagi waktunya mungkin minggu depan. Harinya mungkin hari rabu tanggal 6 september atau hari lainnya di minggu tersebut. Untuk jam dan tempatnya saya bisa menyesuaikan admin tim konseling UB.</p> <p>Terima kasih</p>', '2023-09-02 11:53:07');
