INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3672, 1413, 101231, 'mahasiswa', 'Yasmin Nur Fadhilah', '<p>Iya saya bersedia untuk dijadwalkan. Mungkin untuk menyesuaikan, jadwal kosong saya ada di</p> <p>Senin : 11.05-13.30</p> <p>Kamis : 15.50 - free</p> <p>Jumat : 12.00 - free</p>', '2023-09-02 12:22:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3673, 1425, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote><p>Apakah bisa dipercepat lagi waktunya mungkin minggu depan. Harinya mungkin hari rabu tanggal 6 september atau hari lainnya di minggu tersebut. Untuk jam dan tempatnya saya bisa menyesuaikan admin tim konseling UB.</p> <p>Terima kasih</p></blockquote> <p>Mohon maaf untuk jadwal konseling bersama konselor memang adanya ditanggal tersebut yang paling cepat karena sudah banyak yang mengantri. Kalau Anda saya jadwalkan terlebih dahulu dengan peer counselor, bisa di minggu depan. Bagaimana? <br /><br /></p>', '2023-09-02 14:17:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3674, 1434, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote><p>Mba, mohon maaf 3 pesan terulang. Sepertinya salah sistem</p></blockquote> <p>Terima kasih Bayu sudah cerita. Supaya lebih nyaman ceritanya, Apakah Bayu bersedia untuk dijadwalkan sesi konseling bersama peer counselor pada Selasa, 5 September 2023? Anda berkenan secara online atau offline jika bersedia? Mohon untuk segera dijawab 1x24 jam yaa. Terima kasih. <br /><br />Salam hangat,<br />Tim Konseling UB. </p>', '2023-09-02 15:18:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3675, 1434, 100018, 'mahasiswa', 'Bayu Putra Negara', '<p>Halo, Mba. Mohon maaf kondisinya saya masih di Jakarta untuk magang. Paling untuk bisa konseling tatap muka itu sekitar pekan ke-3/4 di bulan September. Apa bisa online melalui chat dulu, Mba?</p>', '2023-09-02 15:22:57');
