INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3682, 1431, 101245, 'mahasiswa', 'Jessica Ananda Putri', '<p>saya bingung harus memulai cerita dari mana dan saya susah untuk mengungkapkan apa yang membuat saya merasa stress, jika seperti ini apakah ada cara agar saya bisa mengeluarkan dan bercerita? </p>', '2023-09-02 18:58:22');
