INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3715, 1455, 101008, 'mahasiswa', 'Aura Bening Embun', '<p>225110901111002</p><figure><img src="https://media.discordapp.net/attachments/852031732513505291/1149713855015034960/IMG_5382.png" data-image="2y1bhx4h2ee6" alt="image" /></figure><figure><img src="https://media.discordapp.net/attachments/852031732513505291/1149713855312826398/IMG_5383.png" data-image="te0u56u7cze2" alt="image" /></figure><figure><img src="https://media.discordapp.net/attachments/852031732513505291/1149713855572869140/IMG_5386.png" data-image="j7m21r2tzu1w" alt="image" /></figure><figure><img src="https://media.discordapp.net/attachments/852031732513505291/1149713855916810320/IMG_5387.png" data-image="kqwz5jco9gmv" alt="image" /></figure> <p>Ini dari komplain ke teman, makanya bahasa inggris, maaf</p>', '2023-09-08 21:36:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3716, 1456, 101263, 'mahasiswa', 'LISA AURELLIA NURWANTI', '<p>halo, perkenalkan nama saya Lisa Aurellia Nurwanti (<strong>225110501111021</strong>). Saya dari Prodi pebasis, saya izin cerita mengenai diri saya. Saya sudah beberapa kali atau bahkan sering menyalakan diri saya sendiri, even it wasn’t my fault.. saya tetap merasa bersalah atas suatu kejadian tersebut, bahkan parahnya saya bisa tidak terkendali dan bisa melukai diri saya sendiri, seperti menjambak rambut saya hingga rontok, mengepalkan tangan hingga membiru, mencakar wajah hingga tangan saya sampai merah bahkan lebih parah hingga berdarah dan lukanya berbekas. Perasaan saya juga gampang sekali berubah, saya juga bisa tiba tiba menangis tanpa alasan yang jelas. Sebelum itu saya juga minta maaf jikalau tulisan saya terkesan aneh, karna saya juga sulit dalam memilih dan merangkai kalimat. Terimakasih</p>', '2023-09-10 16:30:34');
