INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3780, 1462, 1, 'admin', 'Nora Silvana', '<p>Mohon maaf sebelumnya, dikarenakan jadwal konseling anda bentrok dengan jadwal konseling klien lain, bagaimana jika sesi konseling yang seharusnya dilakukan jam 12.00 direschedule menjadi jam 14.00?<br />Mohon konfirmasinya</p>', '2023-09-14 02:29:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3781, 1466, 1, 'admin', 'Nora Silvana', '<p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda alami saat ini tidaklah mudah. Apabila Anda saya jadwalkan sesi konseling bersama peer counselour secara offline pada Selasa, 19 September 2023 pukul 10.00 WIB di Ruang Konseling Lantai 3 Gedung Rektorat, apakah bersedia? Mohon untuk segera konfirmasi 1x24 jam. Terima kasih.<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-09-14 02:40:01');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3782, 1455, 101008, 'mahasiswa', 'Aura Bening Embun', '<p>Kelas saya selesai sekitar jam 9, jadi mungkin agak terlambat hadir, tapi memungkinkan.</p> <p><br /></p> <p>Bila perlu hari lain selasa, rabu dan kamis saya rata2 tidak ada jadwal setelah jam 1</p>', '2023-09-14 11:44:38');
