INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3789, 1456, 1, 'admin', 'Nora Silvana', '<p>Mohon maaf<br />karena konseling tersebut akan dilakukan dengan konselor klinis, sehingga untuk jadwalnya tidak bisa diganti.<br />Mungkin anda bisa membuat perizinan kepada dosen pengampu mata kuliah pada hari dan jam tersebut</p>', '2023-09-15 15:07:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3790, 1456, 101263, 'mahasiswa', 'LISA AURELLIA NURWANTI', '<p>sekali lagi mohon maaf, untuk perihal perizinan apakah ada surat sendiri dari konseling nya? karena jika izin kepada dosen pengampu tersebut diharuskan dengan bukti. terimakasiii</p>', '2023-09-15 16:36:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3791, 1456, 101263, 'mahasiswa', 'LISA AURELLIA NURWANTI', '<p>namun jikalau memang tidak ada, akan saya usahakan perihal perizinan kepada dosen pengampu</p>', '2023-09-15 22:01:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3792, 1474, 101279, 'mahasiswa', 'Rifdah Tsabita', '<p>225030407111019</p> <p>Saya merasa selalu cemas dan gelisah yang mengganggu aktivitas sehari-hari. Saya menghindari acara reuni, bertemu orang, acara angkatan, samba, dll sebenarnya saya sudah menghindari dan menimalisir untuk bertemu orang sejak sma karena covid 2 tahun bisa dibilang saya hanya dirumah saja. Saya merasa kalau saya keluar rumah bertemu orang apa saya akan membuat kesalahan? saya terlalu cemas dan gelisah. Apa ada cara untuk menghilangkannya ?</p>', '2023-09-16 05:38:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3793, 1475, 101280, 'mahasiswa', 'Raditya Muhammad Salman', '<p>205150400111031</p> <p>Susah fokus seperti saat di kelas, mengerjakan tugas, membaca buku</p>', '2023-09-16 12:21:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3794, 1425, 101241, 'mahasiswa', 'Muaafii fadhlullah', '<p>Baik kalau begitu saya akan mengikuti jadwal yang sudah ditetapkan tanggal 19 nanti</p>', '2023-09-16 13:53:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3795, 1476, 101281, 'mahasiswa', 'Markus Mario Rolas Patiar Batuara', '<p>235030107111119</p> <p>Saya kadang sulit tidur dan kadang takut jika ke kampus. Kadang saya cemas berlebihan. </p>', '2023-09-16 18:47:29');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3796, 1477, 101281, 'mahasiswa', 'Markus Mario Rolas Patiar Batuara', 'Saya adalah mahasiswa baru, selama masa masa mana ini saya sering cemas berlebih, selama ini sudah saya tahan.', '2023-09-16 18:52:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3797, 1478, 101022, 'mahasiswa', 'Lailatus Sakdiyah', '<p>205040200113038 Saya anak bungsu dari 2 bersaudara. Ibu saya meninggal 5 tahun yang lalu saat saya masih SMA kelas 10, ayah saya menikah lagi dan tinggal bersama istri sekaligus anak tirinya. Kakak laki-laki saya sudah menikah dan dikaruniai 2 orang anak, ipar saya memusuhi saya namun didepan orang lain seolah saya yang memulainya dan semenjak ayah menikah nafkah kepada saya sudah tidak seperti dulu lagi. Contohnya pada saat saya kuliah dan ditetapkan sebagai penerima beasiswa pemerintah, ayah saya mulai jarang bahkan bisa dikatakan berhenti memberi nafkah sehingga saya hanya hidup dari uang beasiswa untuk menyambung hidup diperantauan. Hanya sesekali saja ayah mengirimkan uang itupun dalam jumlah sedikit dan hanya bisa menutupi biaya kebutuhan kuota, dalam 1 semester biasanya hanya 1 kali saya dikirim uang itupun jika saya memintanya. Saya selalu mendapatkan keluhan mengenai kondisi ekonomi keluarga disamping itu padahal mereka tau saya sedang fokus kuliah sehingga mempengaruhi semangat saya belajar hingga nilai saya tidak stabil. Ekspektasi keluarga saya terlalu tinggi yang mendorong saya wajib sukses, hal itu membuat saya merasa terbebani. Disamping bantuan yang datang dari sanak saudara termasuk ibu tiri saya ada maksud lain yang saya rasa mereka akan menjadikan saya ATM berjalan nantinya. Kondisi finansial saya yang buruk mempengaruhi semangat saya untuk menyelesaikan skripsi karena terkendala biaya cetak dan lain semacamnya seperti biaya transport saya pp dari kediri ke malang. Semua masalah tersebut mendorong saya untuk berhenti kuliah bahkan bunuh diri, karena merasa berada pada kondisi tertekan dan harus menghadapinya sendirian.</p>', '2023-09-17 00:03:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3798, 1479, 101281, 'mahasiswa', 'Markus Mario Rolas Patiar Batuara', '<p>235030107111119</p> <p>Saya mengalami cemas yang sulit saya kontrol. Kadang tidur saya menjadi tidak berkualitas. </p>', '2023-09-17 07:30:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3799, 1462, 101268, 'mahasiswa', 'Shilsilia Mega Fitria', '<p>Mohon maaf Ibu, saya baru membuka status tiket. Baik Ibu kalau di reschedule jam 14.00. Saya akan izin ke dosen pengajar saya di jam tersebut. Terima kasih dan mohon maaf sebelumnya Ibu</p>', '2023-09-17 09:24:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3800, 1462, 101268, 'mahasiswa', 'Shilsilia Mega Fitria', '<p>Sekali lagi mohon maaf Ibu, status tiket baru saya cek ulang. Karena saya pikir yang kemarin sudah fiks. Terima kasih Ibu</p>', '2023-09-17 09:25:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3801, 1480, 101283, 'mahasiswa', 'Brantio Andika', '<p>Halo perkenalkan nama saya Brantio, sebenarnya saya tidak ingin berkonsultasi saya hanya ingin bertanya apakah saya bisa enroll kelas di brone, meskipun dosen mata kuliah yang terdapat di brone bukan dosen mata kuliah yang saya ampu? saya bingung harus bertanya ke mana, saya sebelumya sudah mencoba bertanya kepada kakak tingkat tapi saya belum mendapat jawaban yg saya inginkan. Saya menanyakan hal ini sebab saya tipe orang yang lebih paham ketika diterangkan melalui video/kelas secara langsung daripada hanya dengan membaca buku dan mencatat saja. Mungkin bapak/ibu bisa menambahkan sumber belajar/kelas yang disediakan oleh universitas untuk membantu saya dalam belajar selain brone. terima kasih atas kesediaannya menjawab pertanyaan saya.. </p> <p>dengan hormat </p> <p>Brantio </p>', '2023-09-17 13:34:31');
