INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3815, 1452, 1, 'admin', 'Nora Silvana', '<p>Halo, Risma. Terima kasih telah menggunakan layanan konseling. Mengingat Anda berasal dari FISIP, maka Anda dapat melakukan konseling dan bercerita secara langsung dengan BKM FISIP yaa. Untuk penentuan jadwalnya, silahkan Anda mengisi link berikut: <a href="http://bit.ly/konselingfisip" target="_blank">http://bit.ly/konselingfisip</a></p> <p>Apabila Anda telah mengisi, Anda nantinya juga akan dihubungi oleh pihak BKM FISIP UB. Terima kasih.</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2023-09-12 18:31:56');
