INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3882, 1500, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Halo Putri, terima kasih telah menggunakan Layanan Konseling UB</p> <p>Berkaitan dengan permasalahan yang anda alami anda dapat melakukanm konseling dengan konselor, silahkan berikan tanggal danwaktu anda yang kosong untuk dijadwalkan kemudian disesuaikanm dengan jadwal konselor yang tersedia. Terima kasih</p> <p><br /></p>', '2023-09-22 18:07:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3883, 1484, 101288, 'mahasiswa', 'Saffana Fadila', '<p>Karena saya merasa khawatir dan takut ga sesuai dengan description job pada lowongan kerja yang saya daftarkan. Mohon maaf kak sebelumnya saya kan ingin konseling secara tatap muka tapi sampai sekarang belum dikabari untuk dibuatkan jadwal itu gimana ya? Terima kasih</p>', '2023-09-23 05:28:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3884, 1491, 101294, 'mahasiswa', 'Jane Amanda Roulina', '<p>Ya, saya bersedia. Mungkin saya ada waktu senggang pada hari selasa setelah makan siang (dari jam 1 siang keatas). </p> <p>Saya ingin bertanya, apakah konseling bisa melakukan screening adhd? Karena saya sangat ingin mengetahui apakah saya memiliki masalag tersebut atau tidak. </p> <p>Terimakasih pak/bu </p> <p><br /></p>', '2023-09-23 06:29:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3885, 1501, 101301, 'mahasiswa', 'Brigitta Caecilia Putri Noya', '<p>Nama saya Brigitta Caecilia Putri Noya NIM 195010101111046 dari fakultas hukum. Saat ini saya sedang menyusun skripsi. Selama proses mengerjakan skripsi saya berada di fase menyendiri dan stress selama beberapa minggu lalu tiba-tiba menjadi hiperaktif dibeberapa minggu kemudian. Teman-teman saya berkata bahwa saya memiliki energy yg sangat berlebih ketika bertemu namun setelah main bersama akan hilang ditelan bumi. Saya juga memiliki kesulitan berkonsentrasi dan cenderung menunda pekerjaan walaupun otak saya sudah menyuruh untuk bergerak dan mengerjakan skripsi namun badan saya tidak mau kompromi. Jujur ini sangat mengganggu saya dalam mengerjakan skripsi. Mohon bantuannya dokter. </p>', '2023-09-23 07:08:32');
