INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3894, 1503, 101303, 'mahasiswa', 'Olivia Michelle S Panjaitan', '<p>Halo saya Olivia Michelle S Panjaitan dengan NIM 235090401111061, izin menyampaikan permasalahan hati saya. Saya adalah mahasiswa baru di universitas brawijaya. Saya tipe orang yang pemalu dan malu untuk menyampaikan pendapat saya sedangkan di dunia perkuliahan kita harus dituntut lebih aktif dalam menyampaikan pendapat. Saya juga semasa pembelajaran mata kuliah, jarang untuk aktif dan selalu zoning out. Saya ingin fokus ke pembelajaran tetapi otak saya tidak bisa berhenti untuk berfikir hal lain sehingga saya tidak bisa fokus ke pembelajaran yang dosen berikan.</p>', '2023-09-24 02:35:01');
