INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3914, 1481, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote><p>Sampe kadang tuh pandangan kosong dan suka banget nyalahin diri sendiri, suka mikir mulai ga nyaman aja selama kuliah gitu apalagi agak kaget sama kehidupan di luar karena saya juga selama 6 tahun masuk boarding</p></blockquote> <p>Terima kasih sudah bercerita. Saya lanjutkan melalui Whatsapp yaa. </p>', '2023-09-24 21:51:18');
