INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3943, 1492, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote><p>225030100111041</p> <p>Kesulitan menggambarkan/mengekspresikan perasaan dan sering mengalami penurunan semangat hidup</p></blockquote> <p>Terima kasih sudah menggunakan layanan konseling. Mohon maaf baru membalas karena panjangnya antrian. Apabila Anda saya jadwalkan sesi konseling offline bersama peer counselour, Anda bersedia kapan? Mohon konfirmasinya 1x24 jam. Terima kasih. <br /><br />Salam hangat,<br />Tim Konseling UB.  </p>', '2023-09-27 05:48:17');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3944, 1498, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote><p>Saya baru yudisium 2 bulan lalu dan sedang menunggu jadwal wisuda. Saya merasa demotivated untuk mencari pekerjaan dan merasa stuck dengan skill yang saya miliki. </p></blockquote> <p>Terima kasih sudah menggunakan layanan konseling. Mohon maaf baru bisa membalas karena panjangnya antrian. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Apabila Anda saya jadwalkan sesi konseling bersama peer counselour, Anda bersedia kapan? Mohon konfirmasinya 1x24 jam. Terima kasih. <br /><br />Salam hangat,<br />Tim Konseling UB</p>', '2023-09-27 05:51:41');
