INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3952, 1499, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote><p>215010101111093 </p> <p>Permasalahan pribadi </p> <p>Izinkan saya konsul lanjutan dengan bu cici</p></blockquote> <p>Terima kasih sudah menggunakan layanan konseling. Anda sudah saya jadwalkan dengan Ibu Cici pada Jumat, 13 Oktober 2023 pukul 10.00 WIB yaa secara online. Anda akan saya hubungi mendekati hari pelaksanaan. Terima kasih. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-09-27 06:12:13');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3953, 1520, 101311, 'mahasiswa', 'Hanifah Rahmajati', 'Hanifah Rahmajati- 215150700111049 Keluhan: Sering migrain Sering menangis tiba-tiba tanpa sebab Rambut rontok makin parah Semakin mudah panik, cemas Merasa ga berguna Merasa sebagai a big failure Tidak betah sendirian, diem, harus selalu gerak biar sibuk Semua yang dilakuin seperti sia sia Semakin malas kuliah, nugas Sulit berpikir dan fokus Malas melakukan apapun selain tidur, makan (bahkan malas nonton drama yg biasanya aku suka) Agak sulit tidur? Tidur jam 3 bangun jam 7 Paling parah adalah sampai skip tes beasiswa gara-gara ngerasa aku ga berguna, apa yg kulakuin semuanya sia sia, tidak pd, dan merasa kesulitan untuk berpikir', '2023-09-27 07:23:18');
