INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3960, 1522, 101312, 'mahasiswa', 'Dennis Varenza Meidy', 'NIM : 215030100111115 Belakangan ini ada beberapa hal yang membuat pikiran dan perasaan saya merasa terbebani. saya jd sensitif sering menangis, kepala saya sering sakit, dada saya sesak. sepertinya penyebabnya ada di masa lalu dan masa sekarang tapi saya tidak tau secara jelas dan memang butuh bantuan untuk memahami ini semua. saya juga terkadang sering menyalahkan diri sendiri atas beberapa kejadian di hidup saya yang tidak mengenakkan. saya takut apabila ini terus berlangsung akan mempengaruhi nilai saya, kegiatan perkuliahan, dan dengan diri saya sendiri.', '2023-09-28 21:18:35');
