INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3985, 1523, 101314, 'mahasiswa', 'Via Lionthiene', 'Saya Via dengan NIM 215020200111075. Saya sudah 3 hari susah tidur, nangis sendiri, pikiran kosong, gelisah, sampai malas untuk melakukan aktivitas sekalipun untuk makan. Banyak beban yang saya punya dari masalah keluarga, kuliah, percintaan yang menyebabkan saya hilang kendali dan fokus pada diri saya. Saat ini saya tidak tahu apa yang bisa saya lakukan kembali untuk bisa fokus pada hal yang ingin saya capai, setidaknya kesehatan fisik dan psikis saya.', '2023-09-29 09:09:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3986, 1524, 101315, 'mahasiswa', 'Agatha Herma Putra', '233140700111111 Sebelumnya saya sudah gonta ganti universitas saya adalah Lulusan 2021 namun pernah di Keluarkan dai universitas dan juga mengundurkan dari universitas yang berbeda lebih tepatnya sekolah Kedinasan, saya mengalami kekersan fisik dan juga perundungan hingga menyebabkan saya sudah pernan melakukan percobaan bunuh diri di sekolah kedinasan tersebut hingga saya harus mengundrukan diri dari sekolah kedinasan tersebut, akhirnya saya harus kembali menjadi Maba yang ke 4 Kalinya hal ini membuat saya depresi tidak ada semangat kuliah dan juga sering mengalami ingin mengakhiri hidup , trauma akan kuliah dikarenakan dulu pernah sampai keluar dikarenakan nilai , dan juga saya merasa gelisah ,tertekan dan juga ingin melarikan diri ketika harus menulis atau kelas, saya sudah berobat ke psikologi dan psikiater namun obat sudah habis biaya juga mahal dan sekarang saya sangat tertekan karena menghabiskan banyak uang orang tua saya hanya untuk kuliah dan saya malu sangat insecure dan ingin putus asa dalam hidup ,suka gemetar jika di kelas dan juga suka terdengar suara suara ejekan dari telinga saya yang entah siapa itu, demikian terimakasih banyak', '2023-09-29 15:58:23');
