INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3988, 1501, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Selamat malam, saya berkenan untuk melakukan sesi konseling pada jam tersebut. Terimakasih</blockquote> <p>Baik kalau begitu. Saya jadwalkan yaa. Mohon Anda bisa mengisi link ini untuk administrasi,<br /><a href="https://tinyurl.com/identitasklien">https://tinyurl.com/identitasklien</a></p> <p>dan<br /><br /><a href="https://bit.ly/PREKONSELING">https://bit.ly/PREKONSELING</a><br /><br />Jika sudah mengisi mohon untuk konfirmasinya. Terima kasih.</p>', '2023-09-30 15:49:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3989, 1505, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Saya bersedia, sekali lagi terima kasih</blockquote> <p>Baik. Terima kasih yaa. Kalau begitu saya jadwalkan. Silahkan Anda mengisi link administrasi ini, <br /><a href="https://tinyurl.com/identitasklien">https://tinyurl.com/identitasklien</a></p> <p>dan</p> <p><a href="https://bit.ly/PREKONSELING">https://bit.ly/PREKONSELING</a><br /><br />Mohon konfirmasinya jika sudah mengisi. Terima kasih.<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-09-30 15:51:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3990, 1502, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Terima kasih atas tanggapannya, apakah memungkinkan untuk dijadwalkan konseling hari senin, 2 okt sekitar pukul 10.00 ? Mohon konfirmasinya kembali, terima kasih.</blockquote> <p>Terima kasih atas jawabannya. Saya coba carikan dulu yaa. Kalau misalnya tidak ada, Anda bersedia kapan lagi yaa?</p>', '2023-09-30 15:53:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3991, 1502, 1, 'admin', 'Andini Laily Putri', '<p>Selamat sore, Lintang. Saya sudah dapatkan peer counselour yang bersedia di Senin, 2 Oktober 2023 pukul 10.00 WIB untuk memberikan konseling secara online yaa. Nanti Anda akan konseling bersama Kak Yasmin. <br /><br />Mohon Anda mengisi link administrasi ini dulu yaa,<br /><a href="https://tinyurl.com/identitasklien">https://tinyurl.com/identitasklien</a></p> <p>dan</p> <p><a href="https://bit.ly/PREKONSELING">https://bit.ly/PREKONSELING</a><br /><br />Mohon kalau konfirmasinya jika sudah mengisi yaa. <br /></p> <p><br /></p><blockquote><p><br /></p></blockquote> <p><br /></p> <p><br /></p>', '2023-09-30 16:23:52');
