INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3993, 1502, 1, 'admin', 'Andini Laily Putri', '<p>Berikut saya kirimkan LINK GOOGLE MEET yang nantinya digunakan. Mohon bergabung menggunakan AKUN UB dan tepat waktu. Terima kasih. <br />To join the video meeting, click this link: <a href="https://meet.google.com/acj-gstc-hyj">https://meet.google.com/acj-gstc-hyj</a><br />Otherwise, to join by phone, dial +1 202-838-7895 and enter this PIN: 558 361 383#<br /><br />Salam hangat,<br />Tim Konseling UB. </p>', '2023-09-30 16:31:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3994, 1515, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Saya bersedia. Saya bisa di hari rabu, siang setelah kuliah</blockquote> <p>Anda bersedia di jam berapa yaa? Karena di jam 13.00-14.00 sudah ada jadwal konseling lain. Kalau saya jadwalkan jam 12.00 WIB apakah bisa? Misal tidak bisa hari Rabu, Anda bisa hari kapan lagi dan jam berapa?</p>', '2023-09-30 16:34:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3995, 1522, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>kalau langsung dengan psikolognya apakah bisa?</blockquote> <p>Mohon maaf baru membalas. Bisa saya jadwalkan dengan konselor (psikolog) tapi untuk 2 minggu kedepan sudah penuh jadwalnya. Adanya di hari Kamis, 19 Oktober 2023 di jam 08.30 - 09.30 dan 10.00 - 11.00 WIB. Anda berkenan? Kalau berkenan, saya jadwalkan. Anda berkenan yang jam berapa? Mohon untuk segera konfirmasi karena nanti akan semakin panjang antriannya dengan konselor...</p>', '2023-09-30 16:38:07');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3996, 1522, 1, 'admin', 'Andini Laily Putri', '<p>Peer counselour ini memang mahasiswa UB yang telah diberikan pelatihan cara memberikan konseling. Tujuannya supaya antrian tidak semakin panjang jika ingin menggunakan layanan LKM UB. </p><blockquote><br /></blockquote>', '2023-09-30 16:39:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3997, 1520, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Terima kasih atas balasannya. Untuk jadwal konseling apakah ada alternatif lain? Karena di jadwal tersebut bertabrakan dengan kelas saya. Adapun untuk peer counselor saya berkenan. Terima kasih.</blockquote> <p>Terima kasih atas jawabannya. Mohon maaf baru membalas. Bisa saya jadwalkan dulu dengan peer counselour yaa. Anda berkenan hari dan jam berapa yaa? Supaya bisa saya carikan peer counselour yang jadwalknya kosong. </p>', '2023-09-30 16:43:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3998, 1523, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Saya Via dengan NIM 215020200111075. Saya sudah 3 hari susah tidur, nangis sendiri, pikiran kosong, gelisah, sampai malas untuk melakukan aktivitas sekalipun untuk makan. Banyak beban yang saya punya dari masalah keluarga, kuliah, percintaan yang menyebabkan saya hilang kendali dan fokus pada diri saya. Saat ini saya tidak tahu apa yang bisa saya lakukan kembali untuk bisa fokus pada hal yang ingin saya capai, setidaknya kesehatan fisik dan psikis saya.</blockquote> <p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Apabila Anda saya jadwalkan sesi konseling offline bersama peer counselour, Anda bersedia kapan? Mohon jawabannya 1x24 jam. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-09-30 16:49:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (3999, 1523, 101314, 'mahasiswa', 'Via Lionthiene', 'Saya bisa melakukan sesi konseling offline pada hari senin, 2 oktober 2023 setelah selesai kelas jam 12', '2023-09-30 16:54:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4000, 1523, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Saya bisa melakukan sesi konseling offline pada hari senin, 2 oktober 2023 setelah selesai kelas jam 12 </blockquote> <p>Baik, terima kasih. Anda telah saya jadwalkan pada Senin, 2 Oktober 2023 pukul 13.00 WIB secara offline bersama Kak Hana. Untuk tempatnya berada di Ruang Konseling Lantai 3 Gedung Rektorat. Mohon untuk datang tepat waktu.<br />Sebelum Anda memasuki ruangan, mohon untuk menemui Pak Sholeh di lantai 3 Gedung Rektorat supaya bisa diantarkan masuk ke ruangan yaa. <br /><br />Silahkan Anda mengisi link administasi ini,<br /><a href="https://tinyurl.com/identitasklien">https://tinyurl.com/identitasklien</a></p> <p>dan</p> <p><a href="https://bit.ly/PREKONSELING">https://bit.ly/PREKONSELING</a><br />Mohon konfirmasinya jika sudah selesai mengisi. Terima kasih.<br /><br />Salam hangat,<br />Tim Konseling UB.<br /></p>', '2023-09-30 17:32:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4001, 1523, 101314, 'mahasiswa', 'Via Lionthiene', 'Terima kasih atas informasinya, saya akan datang tepat waktu pada jam yang telah ditentukan. Izin konfirmasi bahwa saya telah mengisi link administrasi identitas dan prekonseling.', '2023-09-30 18:00:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4002, 1523, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Terima kasih atas informasinya, saya akan datang tepat waktu pada jam yang telah ditentukan. Izin konfirmasi bahwa saya telah mengisi link administrasi identitas dan prekonseling. </blockquote> <p>Baik, terima kasih banyak yaa sudah mengisi</p>', '2023-09-30 18:59:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4003, 1525, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>saya kristianing yesa dengan NIM 215020300111063 ingin berkonsultasi terkait hubungan saya dengan orang tua yang semakin lama menganggu keseharian saya</blockquote> <p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Bolehkah Anda bercerita lebih banyak terkait hubungan Anda dengan orang tua seperti apa? </p>', '2023-09-30 19:01:27');
