INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4006, 1515, 1, 'admin', 'Andini Laily Putri', '<p>Baik. Saya sudah dapatkan. Anda telah saya jadwalkan sesi konseling offline bersama peer counselour pada Kamis, 5 Oktober 2023 pukul 13.30 WIB di Ruang Konseling Lantai 3 Gedung Rektorat. Mohon datang tepat waktu. <br />Sebelum memasuki ruangan, mohon untuk menemui Pak Sholeh di Lantai 3 Gedung Rektorat supaya bisa diantarkan ke ruangan. <br /><br />Silahkan Anda mengisi link administrasi,<br /><a href="https://tinyurl.com/identitasklien">https://tinyurl.com/identitasklien</a></p> <p>dan </p> <p><a href="https://bit.ly/PREKONSELING">https://bit.ly/PREKONSELING</a><br />Mohon konfirmasinya jika sudah mengisi. Terima kasih.<br /><br />Salam hangat,<br />Tim Konseling UB.</p><blockquote><br /></blockquote> <p><br /></p>', '2023-09-30 19:59:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4007, 1520, 101311, 'mahasiswa', 'Hanifah Rahmajati', 'Jika hari Senin pukul 1 siang apakah bisa? Jika semisal tidak bisa, berikut saya lampirkan jadwal kuliah saya sehingga bisa dicarikan jadwal yang sesuai. Adapun untuk jadwal konselor sekiranya bisa dijadwalkan kapan ya? Terima kasih. Senin 09:30 - 11:59 Pemrograman Integratif 15:30 - 18:09 Data Warehouse Selasa 09:30 - 11:59 Keamanan Jaringan 13:40 - 16:19 Administrasi Basis Data Rabu 10:20 - 11:59 Etika Profesi 12:50 - 14:29 Pemrograman Integratif 16:20 - 18:09 Administrasi Basis Data Kamis 09:30 - 11:59 Metodologi Penelitian dan Penulisan Ilmiah 12:50 - 15:19 High Availability System', '2023-09-30 20:02:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4008, 1520, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Jika hari Senin pukul 1 siang apakah bisa? Jika semisal tidak bisa, berikut saya lampirkan jadwal kuliah saya sehingga bisa dicarikan jadwal yang sesuai. Adapun untuk jadwal konselor sekiranya bisa dijadwalkan kapan ya? Terima kasih. Senin 09:30 - 11:59 Pemrograman Integratif 15:30 - 18:09 Data Warehouse Selasa 09:30 - 11:59 Keamanan Jaringan 13:40 - 16:19 Administrasi Basis Data Rabu 10:20 - 11:59 Etika Profesi 12:50 - 14:29 Pemrograman Integratif 16:20 - 18:09 Administrasi Basis Data Kamis 09:30 - 11:59 Metodologi Penelitian dan Penulisan Ilmiah 12:50 - 15:19 High Availability System</blockquote> <p>Terkait jadwal dengan konselor dengan melihat jadwal Anda. Berarti saya jadwal pada Rabu, 18 Oktober 2023 pukul 08.00  WIB yaa secara offline. Terkait jadwal dengan peer counselornya akan saya jadwalkan pada Jumat, 6 Oktober 2023 dan jamnya menyusul. Kalau dari Anda, berkenan Jumat jam berapa?</p>', '2023-09-30 20:21:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4009, 1520, 101311, 'mahasiswa', 'Hanifah Rahmajati', 'Baik, saya bersedia untuk hari Rabunya. Untuk hari Jumat saya bisa pagi ataupun siang, tetapi jika sore sepertinya tidak bisa. Mungkin jam 9 atau 10 pagi?', '2023-09-30 20:24:20');
