INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4044, 1532, 101329, 'mahasiswa', 'Yustika Trihafsah', '195100901111023 merasa malas, suka menunda pekerjaan, tidak produktif, belum memulai sudah merasa anxious, blame diri sendiri karena merasa tidak capable buat menyelesaikan skripsi, takut gagal dan malah not start doing things. mencoba baca self improvement book tapi masih sama karena ngga bisa memulai, atau sudah mulai namun tidak konsisten', '2023-10-05 20:02:29');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4045, 1533, 101008, 'mahasiswa', 'Aura Bening Embun', '225110901111002, akhir akhir ini mengharapkan bahwa suatu konsultasi untuk diagnosa mental akan membantu kesehatan mental dan kemudahan melaksanakan tugas mahasiswa, nammun tidak tahu bagaimana harus mulai mencari resource, dan ortu ataupun dosen pembimbing tidak terlalu membantu', '2023-10-06 07:51:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4046, 1534, 101330, 'mahasiswa', 'Putri Febriana', '185110500111024 Saya merasa tidak pandai bicara, dari itu saya tidak punya teman, ketika saya berada di titik lemah stress saya ingin bercerita membagikan keluh kesah kepada seseorang tapi tidak ada satupun yg bisa saya datangi. Dan ketika saya punya masalah saya tidak bisa menghadapi selalu tidak tau akan harus bagaimana.', '2023-10-06 08:32:56');
