INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4048, 1534, 1, 'admin', 'Nora Silvana', '<p>Halo Putri. Terima kasih karena telah menggunakan layanan konseling. Saya yakin apa yang Anda alami saat ini tentunya tidak mudah. Untuk itu, apakah Anda bersedia melakukan konseling dengan peer counselor kami? Apabila bersedia, silakan tuliskan jadwal kosong atau waktu Anda bisa melakukan konseling yaa.</p> <p>Mohon konfirmasinya 1x24 jam yaa.</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-10-06 13:32:59');
