INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4066, 1501, 1, 'admin', 'Nora Silvana', '<p>Baik, terima kasih. Mohon hadir tepat waktu yaa untuk konseling Senin, 9 Oktober pukul 09.00 di Ruang Konseling Lantai 3 Gedung Rektorat. Apabila ada kendala atau pertanyaan terkait sesi konseling nanti, Anda dapat mengubungi kami via WhatsApp. Terima kasih.</p>', '2023-10-07 13:25:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4067, 1531, 101327, 'mahasiswa', 'Audyva Irefilevitasari Alifia', 'maaf bapak/ibu, kalau begitu saya akan coba konsul di fakultas saja. terimakasih banyak atas konfirmasinya', '2023-10-07 18:36:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4068, 1537, 101335, 'mahasiswa', 'Reyhan Prasetyo', 'Saya Reyhan Dwi Prasetyo dengan NIM 215150400111062 dari Jurusan Sistem Informasi dengan Fakultas Ilmu Komputer. 1 Bulan Belakangan ini saya merasa tidak memiliki motivasi dalam menjalani hidup, hari hari yang biasanya saya penuhi dengan mempelajari skill melalui kursus online berubah menjadi kegiatan yang tidak produktif. Nafsu makan saya pun menjadi kurang dan saya merasa berat untuk menjalani hidup tiap hari. Saya sudah mengikuti arahan arahan nasihat dari berbagai forum seperti melakukan hobi yang saya suka yaitu bermain game, bepergian dengan teman, makan dan minum jajanan yang saya suka dan mengikuti event. Setiap kali saya melakukan hal tersebut, Saya selalu terpikirkan dengan masa depan saya. Saya berusaha untuk positif tiap hari namun situasi ini terus bermunculan dan menghantui saya tiap hari. Saya sudah berkonsultasi dengan orang tua saya yaitu ibu saya, namun saya tidak menemukan jawaban yang tepat. Tolong saya, saya merasa ini sudah mengganggu hidup saya dan proses saya berkembang.', '2023-10-07 19:36:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4069, 1531, 1, 'admin', 'Nora Silvana', '<p>Baik kalau begitu. Terima kasih atas konfirmasinya.</p>', '2023-10-08 10:12:45');
