INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4135, 1560, 101366, 'mahasiswa', 'Marcella Nurse Wijayanti', '226040200011006 saya merasa tidak mampu menjalani kehidupan Dan kehilangan tujuan', '2023-10-18 12:59:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4136, 1551, 101352, 'mahasiswa', 'Shofiyurrohman Al At Sariy', 'Terima Kasih banyak kak Tasya, saya bersedia dan akan mempersiapkan diri, sekali lagi terima kasih banyak kak', '2023-10-18 14:59:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4137, 1542, 100541, 'mahasiswa', 'Reyvalda Dewi Aditya Putri Prasetyo', 'Selamat malam. Mohon maaf saya baru sempat mengecek dan membalas  Terkait sesi konseling, kemungkinan saya bisa di hari Senin tanggal 23 September pukul 9.45. Tetapi saya juga belum tahu pasti dikarenakan khawatir ada jadwal praktikum mendadak. Bila ada perubahan mungkin akan saya kabari. Apakah dari peer counselor ada yang bersedia di hari dan jam tersebut? Sekian dari saya, terima kasih atas perhatiannya', '2023-10-18 19:16:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4138, 1540, 101341, 'mahasiswa', 'Farah Sajidah', 'Kalo konseling secara zoom saja apakah bisaa ya kak? Kebetulan saya tidak bisa tanggal 23 namun tidak berkenan juga untuk peer counselor', '2023-10-18 19:28:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4139, 1561, 101367, 'mahasiswa', 'Afifah Febriyanti', '215110701111013_Seorang staff menyalahkan saya atas pengelolaan SDM dan pembagian tugas pada sebuah project team untuk lomba. Padahal beliau juga bersalah, tapi tidak ingin disalahkan. Beliau bercerita ke orang-orang seolah beliau adalah korban. Saya trauma dan muncul perasaan takut untuk memimpin project team kembali. Sering perasaan bersalah tiba-tiba muncul secara random. Pada saat keadaan seperti itu, tubuh saya lemas, kepala terasa berat sehingga membuat saya tidak mood melakukan kegiatan apapun. Hal ini sangat mengganggu aktivitas saya.', '2023-10-18 20:35:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4140, 1562, 101368, 'mahasiswa', 'Emerald Yuansaki Fallarta As-Shofah', '225010107111151 saya ingin mengecek terkait kepribadian saya karena saya merasakan hal aneh atas diri saya', '2023-10-18 23:14:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4141, 1563, 101369, 'mahasiswa', 'Saka Adjie Bayuningrat', '195010100111013. Jadi sudah dua bulan ini setelah sempro saya melakukan procrastination dengan skripsi saya, karena kebingungan dengan bagaimana saya harus melanjutkan skripsi saya Dan menindaklanjuti masukan dari dosen. Dalam periode procrastinating ini saya tetap mencoba mengerjakan sesuai dengan masukan dosen saya, namun entah kenapa selalu terasa ada tembok besar disekeliling saya yang membuat seluruh badan saya menjadi tidak kooperatif dengan kemauan saya. Akhir kata, Hal tersebut pun merembet ke hal-hal yang sifatnya personal dimana saya jadi lebih mudah tersinggung, emosian,dan cenderung lebih menutup diri. Di berbagai kesempatan termasuk sekarang, saya juga merasa sedih, hampa, dan merasa ini semua sia².', '2023-10-19 13:41:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4142, 1561, 101367, 'mahasiswa', 'Afifah Febriyanti', 'Seorang staff menyalahkan saya atas pengelolaan SDM dan pembagian tugas pada sebuah project team untuk lomba. Saya menyadari bahwa ada kesalah dalam cara kepemimpinan saya, namun beliau sebetulnya juga bersalah. Sayangny beliau tidak ingin disalahkan dan kami cekcok di chat WA. Beliau bercerita ke orang-orang seolah beliau adalah korban. Saya trauma dan muncul perasaan takut untuk menjadi pemimpin lagi. Sering perasaan bersalah tiba-tiba muncul secara random. Pada saat perasaan itu mumcul, tubuh saya lemas dan kepala terasa berat sehingga membuat saya tidak mood melakukan kegiatan apapun. Hal ini telah terjadi beberapa kali dan sangat mengganggu aktivitas saya', '2023-10-19 19:44:28');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4143, 1543, 101344, 'mahasiswa', 'Pradiptya kahvi', 'Saya merasa kesulitan mengerjakan tesis S2 saya, saya tidak tau mau melakukan penelitian tentang apa dan tidak tau mau mengerjakan penelitian tentang apa. Tentu saja saya sudah melakukan diskusi dengan beberapa dosen terkait hal ini dan disuruh melakukan slr. Tapi saya kurang merasa bersemangat melakukan hal ini. Karena saya merasa sendirian dan merasa bahwa hal ini menjadi beban. Sebelumnya pada pengerjaan skripsi saya semua berjalan lancar, kecuali dosen pembimbing 2 saya yg dipilih scr gacha dari sebuah sistem. Saya mendapati pembimbing 2 yg intimidatif dan sulit ditemui. Alhamdulillah skripsi saya sudah selesai, tpi dari pengalaman tersebut dalam pengerjaan tesis saya kurang bersemangat jika mengingat perngerjaan tugas akhir saya di sarjana bersama dengan dosen tsb. Selain itu, ekpektasi orang tua saya yang terlalu tinggi juga membebani saya, sebenernya hal ini tidak disalahkan karena mereka berjuang dengan membiayai pendidikan saya, biaya saya selama dimalang dan lain2. Akan tetapi, kenyataannya memang tidak semudah itu. Permasalahan lain, saat ini saya memiliki teman yang sedikit dimalang banyak dari mereka yang sudah mendapat kerja dikota lain dan pulang kekampung halaman sehingga saya merasa kesepian. Dengan teman magister saya kurang merasa akrab dengan mereka, sebenernya saya masih berhubungan dengan teman teman saya tapi mereka sudah mempunyai kesibukan masing2 seperti bekerja. Selain itu, saya juga tidak memiliki pacar dan itu menambah rasa kesepian saya. Saya berencana untuk lulus dari program magister ini semester depan akan tetapi melihat progres tesis saya saat ini, saya merasa kurang percaya diri selain itu progres saya juga tertinggal dengan teman2 yang lain sehingga itu membuat rasa merasa overthinking. Saya sudah mencoba untuk menenangkan diri seperti pulang kekampung halaman tapi itu tidak seberapa membantu dan membuat saya homesick setiap saya kembali kemalang. Selain itu saya sudah pernah untuk melupakan masalah ini dengan mencoba merokok dan terkadang menonton bf, akan tetapi ini tidak membantu dan menambah rasa addictive saya terhadap kegiatan negatif tersebut. Masalah ini membuat saya sulit tidur, terkadang saya bisa terjaga semalaman sampai pagi sehingga itu membuat kepala saya sakit. Jujur saya tidak tau harus beebuat apa dan saya tidak mau mengecewakan orang tua saya.', '2023-10-20 23:42:10');
