INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4154, 1560, 1, 'admin', 'Nora Silvana', '<p>Baik kalau begitu, saya jadwalkan yaa. Untuk konselingnya apabila dilaksanakan secara online via google meet apakah tidak apa-apa yaa?</p>', '2023-10-21 14:13:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4155, 1539, 1, 'admin', 'Nora Silvana', '<p>Mohon maaf baru merespons. Kalau begitu kira-kira Anda bersedia untuk konseling tanggal dan jam berapa yaa? Supaya saya carikan peer counselor yang available. Kemudian, untuk layanan konseling ini tidak berbayar yaa.</p>', '2023-10-21 14:39:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4156, 1545, 1, 'admin', 'Nora Silvana', '<p>Mohon maaf baru merespons. Iyaa betul konselor sebaya yaa, jadi mahasiswa yang telah dilatih untuk memberikan konseling pada sesama mahasiswa. Apabila Anda bersedia, silakan tuliskan jadwal kosong Anda untuk melakukan konseling yaa. Nanti kami bantu carikan peer counselor yang available di jadwal tersebut.</p>', '2023-10-21 14:53:04');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4157, 1553, 1, 'admin', 'Nora Silvana', '<p>Halo Alisha.</p> <p>Terima kasih telah menggunakan layanan konseling. Mohon maaf atas respons yang cukup lambat karena panjangnya antrian. Saya yakin situasi yang Anda alami saat ini tentunya tidak mudah. Untuk itu, apakah Anda berkenan untuk dijadwalkan konseling dengan peer counselor kami? Apabila berkenan, mohon tuliskan jadwal kosong Anda untuk melakukan konseling yaa. Nanti kami bantu carikan peer counselor yang available berdasarkan jadwal tersebut.</p> <p>Kami tunggu konfirmasinya.</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2023-10-21 14:56:15');
