INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4206, 1511, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>saya memiliki latar belakang keluarga yang tidak harmonis dan saling tidak akur pak/bu, ayah saya memiliki istri lagi dan tidak terlalu memerhatikan masa depan saya</blockquote> <p>Selamat sore, Enricko. Mohon maaf sebelumnya karena baru bisa membalas karena panjangnya antrian. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Apabila Anda saya jadwalkan sesi konseling offline bersama konselor pada Jumat, 3 November 2023 pukul 10.00 - 11.00 WIB Apakah bersedia? Mohon untuk segera membalas 1x24 jam. Terima kasih. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-10-29 15:09:28');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4207, 1542, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Selamat malam. Mohon maaf saya baru sempat mengecek dan membalas Terkait sesi konseling, kemungkinan saya bisa di hari Senin tanggal 23 September pukul 9.45. Tetapi saya juga belum tahu pasti dikarenakan khawatir ada jadwal praktikum mendadak. Bila ada perubahan mungkin akan saya kabari. Apakah dari peer counselor ada yang bersedia di hari dan jam tersebut? Sekian dari saya, terima kasih atas perhatiannya </blockquote> <p>Selamat sore, Reyvalda. Mohon maaf sebelumnya karena baru bisa membalas karena panjangnya antrian. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Apabila Anda saya jadwalkan sesi konseling offline bersama peer counselor pada hari Selasa, 31 Oktober 2023, Anda bersedia jam berapa? Saya tunggu jawaban Anda sampai besok jam 12.00 WIB. Terima kasih. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-10-29 15:13:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4208, 1540, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Kalo konseling secara zoom saja apakah bisaa ya kak? Kebetulan saya tidak bisa tanggal 23 namun tidak berkenan juga untuk peer counselor </blockquote> <p><br />Selamat sore, Farah. Mohon maaf sebelumnya karena baru bisa membalas karena panjangnya antrian. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Apabila Anda saya jadwalkan sesi konseling offline bersama konselor pada hari Senin, 6 November 2023 pukul 09.00 - 10.00 WIB, Apakah bersedia? Saya tunggu jawaban Anda 1x24 jam. Terima kasih.<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-10-29 15:18:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4209, 1540, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Kalo konseling secara zoom saja apakah bisaa ya kak? Kebetulan saya tidak bisa tanggal 23 namun tidak berkenan juga untuk peer counselor </blockquote> <p>Terkait pelaksanaannya akan dilaksanakan melalui google meet</p>', '2023-10-29 15:19:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4210, 1538, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Sebelumnya mohon maaf baru bisa membalas dan terimakasih sudah membalas pesan saya. Sekarang yang saya rasakan masih sering merasa cemas berlebih dan susah tidur. Saat tidur saya sering terbangun dan susah untuk lanjut tidur kembali. Saya bersedia dijadwalkan Konseling, akan tetapi saya tidak bisa pada tanggal tersebut karena ada praktikum. Mungkin bisa diganti tanggal lain? Terimakasih</blockquote> <p><br />Selamat sore, Ardelia. Mohon maaf sebelumnya karena baru bisa membalas karena panjangnya antrian. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Apabila Anda saya jadwalkan sesi konseling online melalui Google Meet bersama konselor pada Selasa, 7 November 2023 pukul 14.00 - 15.00 WIB, Apakah bersedia? Saya tunggu jawaban Anda 1x24 jam. Terima kasih.<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-10-29 15:22:26');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4211, 1546, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Untuk saat ini sedang mengerjakan skripsi dan memang dituntut untuk cepat selesai, di awal judul telah di acc hingga proposal otw jadi tapi di tengah timeline yg seharusnya menuju sempro saya diminta untuk mengganti judul dan itu membuat saya gelisah karena merasa tertinggal dari yang lain.</blockquote> <p><br />Selamat sore, Fauzul. Mohon maaf sebelumnya karena baru bisa membalas karena panjangnya antrian. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Apabila Anda saya jadwalkan sesi konseling offline bersama peer counselor pada hari Selasa, 31 Oktober 2023, Anda bersedia jam berapa? Saya tunggu jawaban Anda sampai besok jam 12.00 WIB. Terima kasih.<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-10-29 15:23:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4212, 1548, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>tolong saya, 3 hari terakhir banyak bgt pertanyaan yg numpuk di pikiran saya yg ganggu, bikin saya nangis berlarut sampe ngerasa sakit kepala</blockquote> <p><br />Selamat sore, Siti Aisyah. Mohon maaf sebelumnya karena baru bisa membalas karena panjangnya antrian. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Apabila Anda saya jadwalkan sesi konseling offline bersama peer counselor pada hari Rabu, 1 November 2023, Anda bersedia jam berapa? Saya tunggu jawaban Anda sampai besok jam 12.00 WIB. Terima kasih.<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-10-29 15:26:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4213, 1551, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Terima Kasih banyak kak Tasya, saya bersedia dan akan mempersiapkan diri, sekali lagi terima kasih banyak kak </blockquote> <p>Selamat sore, Shofiyurrohman. Mohon maaf sebelumnya karena baru bisa membalas karena panjangnya antrian. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Apabila Anda saya jadwalkan sesi konseling online bersama peer counselor pada hari Selasa, 31 Oktober 2023, Anda bersedia jam berapa? Saya tunggu jawaban Anda sampai besok jam 12.00 WIB. Terima kasih.<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-10-29 15:30:57');
