INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4237, 1574, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Bersedia, terimakasih</blockquote> <p>Baik kalau begitu. Terima kasih. Anda telah saya jadwalkan sesi konseling offline bersama bersama Ibu Ika Fitria. Silahkan untuk melakukan sesi konseling di Ruang Konseling Lantai 3 Gedung Rektorat. Mohon datang tepat waktu. Sebelum memasuki ruangan, mohon untuk menemui Pak Sholeh yang ada di lantai 3 juga untuk dapat diantarkan ke ruang konseling. Sekarang, silahkan Anda mengisi kedua link ini dan saya tunggu Anda untuk mengisinya. Jika sudah selesai mengisi, mohon untuk konfirmasi. <br /><br /><a href="https://tinyurl.com/identitasklien">https://tinyurl.com/identitasklien</a><br /><br /><a href="https://bit.ly/PREKONSELING">https://bit.ly/PREKONSELING</a><br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-10-29 17:10:49');
