INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4285, 1589, 101400, 'mahasiswa', 'Aprillia Tri Syasabella', 'saya Aprillia Tri Syasabella dengan nim 215070307111019 merupakan seorang anak bungsu yang tinggal sendirian di kota malang dengan rumah tinggal dari org tua, kondisi ekonomi sedang kurang bagus dikarenakan dari kakak sedang baru saja lahiran sehingga tidak mendapatkan uang jajan sebagai mana mestinya, kondisi rumah sangat berantakan dan saya sempat mengalami kejdian yang tidak enak akibat ini, setiap hari senin, selasa, rabu, sabtu dan minggu bekerja part time sebagai penjaga kedai, dan aktif sebagai mahasiswa semester 5. Sering merasa tidak mendapatkan dukungan dari orang sekitar dan sering merasa sendiri.', '2023-11-01 12:52:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4286, 1590, 100780, 'mahasiswa', 'Rey Sanjaya', 'NIM 215110100111041 Masalah pribadi saya berhubungan dengan gejala-gejala kondisi psikologis saya yang kemungkinan mengarah pada Borderline Personality Disorder. Kondisi inilah yang saya rasa menjadi penyebab dalam beberapa masalah lain yang saya miliki, terutama masalah intrapersonal dengan orang lain seperti teman dan rekan kerja.', '2023-11-01 15:42:59');
