INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4288, 1591, 101401, 'mahasiswa', 'Muhammad Ewaldo Yudhistira', '175010100111156 Halo Kak, perkenalkan saya Edo Mahasiswa FHUB angkatan 2017 Ini agak aneh dari saya yg udh semester ujung jurang tapi dulu saya seharusnya lulus pada tahun 2021, April 2021 saya sudah Semhas dan saat ingin melangkah maju saya tidak diperbolehkan dosen 2 tahun berlalu dan rasa percaya diri saya hilang dan saya menyianyiakan hidup saya Saya ingin berhenti menjadi pecundang tapi masih takut untuk melangkah Terima kasih sebelumnya', '2023-11-01 22:36:42');
