INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4303, 1568, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Baik saya bersedia, terimakasih </blockquote> <p>Baik, sudah saya jadwalkan yaa. Tempatnya masih sama yaa di Ruang Konseling Lantai 3 Gedung Rektorat. </p>', '2023-11-02 22:06:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4304, 1583, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>iyaa saya bersedia hadir di tanggal tersebut, kalau boleh tau ada di gedung mana untuk layanan psikologi ini?</blockquote> <p>Baik, saya jadwalkan yaa. Nantinya Anda akan konseling bersama Ibu Cici. Untuk tempatnya ada di Ruang Konseling Lantai 3 Gedung Rektorat. Mohon datang tepat waktu dan menemui Pak Sholeh di Lantai 3 untuk dapat diantarkan masuk ke ruangan. Mendekati hari pelaksanaan akan saya ingatkan melalui Whatsapp yaa. Terima kasih. <br /><br />Untuk saat ini, saya mohon Anda untuk mengisi kedua link dibawah ini untuk pelayanan di LKM UB. Saya tunggu respon Anda. Mohon konfirmasinya jika sudah selesai mengisi. Terima kasih. <br /><br /><a href="https://tinyurl.com/identitasklien">https://tinyurl.com/identitasklien</a><br /><br /><a href="https://bit.ly/PREKONSELING">https://bit.ly/PREKONSELING</a></p>', '2023-11-02 22:13:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4305, 1585, 100852, 'mahasiswa', 'Andini Laily Putri', '<p>Dialihkan ke BKM FISIP UB</p>', '2023-11-02 22:15:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4306, 1589, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>saya Aprillia Tri Syasabella dengan nim 215070307111019 merupakan seorang anak bungsu yang tinggal sendirian di kota malang dengan rumah tinggal dari org tua, kondisi ekonomi sedang kurang bagus dikarenakan dari kakak sedang baru saja lahiran sehingga tidak mendapatkan uang jajan sebagai mana mestinya, kondisi rumah sangat berantakan dan saya sempat mengalami kejdian yang tidak enak akibat ini, setiap hari senin, selasa, rabu, sabtu dan minggu bekerja part time sebagai penjaga kedai, dan aktif sebagai mahasiswa semester 5. Sering merasa tidak mendapatkan dukungan dari orang sekitar dan sering merasa sendiri.</blockquote> <p>Terima kasih sudah menggunakan layanan konseling. Saya mengerti yang Anda rasakan saat ini tidaklah mudah dengan menjadi anak bungsu dan harus bekerja parttime ditengah kesibukan kuliah. Apabila saya jadwalkan sesi konseling online bersama peer counselor, apakah bersedia? Kalau bersedia, Anda berkenan kapan dan jam berapa? Mohon konfirmasinya 1x24 jam yaa. Terima kasih. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-11-02 22:23:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4307, 1586, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>215110500111031 Saya kadang ngerasa cape dengan diri saya sendiri yg selalu salah di mata orang lain</blockquote> <p>Terima kasih telah menggunakan layanan konseling. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Kalau boleh saya tanya, bagaimana perasaan Anda saat ini? Anda merasa capai dengan keadaan Anda yang seperti apa? </p>', '2023-11-02 22:25:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4308, 1592, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Sebenarnya saya disini tidak ada masalah disini saya menghubungi e conseling ub untuk tugas projek menanyakan tentang kekerasan seksual apakah boleh ?</blockquote> <p>Terima kasih telah menggunakan layanan konseling. Terkait kekerasan seksual, dapat Anda tanyakan ke SATGAS PPKS di link ini yaa, <br /><a href="https://instagram.com/satgasppks.ub?igshid=MzMyNGUyNmU2YQ==">https://instagram.com/satgasppks.ub?igshid=MzMyNGUyNmU2YQ==</a><br />atau melalui email: satgasppks@ub.ac.id </p>', '2023-11-02 22:59:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4309, 1588, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>195040207111160, gusar terhadap kondiri diri sendiri</blockquote> <p>Terima kasih telah menggunakan layanan konseling. Boleh Anda ceritakan lebih banyak terkait kegusaran Anda? Lalu, bagaimana perasaan Anda saat ini?</p>', '2023-11-02 23:04:56');
