INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4318, 1580, 101390, 'mahasiswa', 'Theola Flowrencia', 'Selamat siang, bu. Saya mau follow up terkait janji konsultasi. Ternyata dosen jurusan saya akan pergi studi banding di minggu depan dan semua kelas ditiadakan. Jadi saya bisa konsultasi di jam berapa saja, bu. Terima kasih.', '2023-11-03 12:45:10');
