INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4320, 1593, 101404, 'mahasiswa', 'Ananti Eka Rachmadani', 'Kak maaf mau tanya tapi boleh ga kalo jadwalnya hari ini atau besok?', '2023-11-03 14:01:26');
