INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4322, 1579, 101389, 'mahasiswa', 'Andini Laily Putri', '<p>Telah dijadwalkan</p>', '2023-11-04 06:09:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4323, 1591, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Boleh kak dengan peer counselor saja Minggu depan bisa asal bukan selasa/jumat kak Untuk jamnya kalau bisa tidak terlalu pagi, mungkin jam 9-11 atau sore saja kak</blockquote> <p>Terima kasih atas konfirmasinya. Baik, akan saya carikan. Saya informasikan bahwa seluruh kegiatan mulai tanggal 6-10 November akan dilakukan secara online mengingat padatnya kegiatan MTQN di lingkungan Universitas Brawijaya. Apabila Anda melakukan sesi konseling online tidak apa-apa?</p>', '2023-11-04 06:16:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4324, 1587, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Terimakasih Tim konseling UB telah merespon permasalahan yang sedang saya alamai. Untuk jadwal sesi konseling, saya berkenan di hari Senin, sekitar pukul 10 pagi. Terimakasih </blockquote> <p>Terima kasih konfirmasinya. Saya carikan yaa. Saya informasikan juga bahwa seluruh kegiatan sejak tanggal 6-10 November akan dilakukan secara daring karena padatnya kegiatan MTQN di lingkungan Universitas Brawijaya. Apabila Anda melakukan sesi konseling online apakah berkenan?</p>', '2023-11-04 06:18:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4325, 1593, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Kak maaf mau tanya tapi boleh ga kalo jadwalnya hari ini atau besok? </blockquote> <p>Terima kasih konfirmasi dan mohon maafbaru membalas. Terkait pelaksanaan konseling tidak bisa mendadak yaa karena juga harus mencari peer counselor yang bisa di hari dan jam tersebut. Maka dari itu, saya tawarkan pada senin. Saya informasikan juga bahwa seluruh kegiatan mulai tanggal 6-10 November 2023 dilaksanakan secara daring karena padatnya kegiatan MTQN di lingkungan kampus. Apabila saya jadwalkan sesi konseling online pada Senin, 6 November 2023 pukul 10.00 WIB, apakah bisa yaa? Mohon untuk segera konfirmasi agar segera saya carikan peer counselor yang bisa. </p>', '2023-11-04 06:25:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4326, 1587, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Terimakasih Tim konseling UB telah merespon permasalahan yang sedang saya alamai. Untuk jadwal sesi konseling, saya berkenan di hari Senin, sekitar pukul 10 pagi. Terimakasih </blockquote> <p>Kalau Anda berkenan, misal jamnya diubah menjadi sore atau malam, apakah bisa?</p>', '2023-11-04 06:30:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4327, 1593, 101404, 'mahasiswa', 'Ananti Eka Rachmadani', 'Boleh kak kalau begitu senin saja  terima kasih', '2023-11-04 06:54:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4328, 1591, 101401, 'mahasiswa', 'Muhammad Ewaldo Yudhistira', 'Jika online nanti menggunakan apa ya kak ? Sebenarnya saya prpribadi lebih nyaman berbicara langsung tetapi jika tidak memungkinkan ya online saja tidak apa-apa', '2023-11-04 09:00:38');
