INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4332, 1597, 101405, 'mahasiswa', 'Nafisa Habybul Qolby Klp 3 Bahasa Indonesia', 'Nama saya Nafisa Habybul Qolby dengan NIM 235010101111078 dari fakultas hukum angkatan 2023 ingin melakukan konseling mengenai kasus mahasiswa UNNES yang bunuh diri dari atas Mall Paragon pada bulan Oktober lalu sebagai bentuk penyelesaian tugas Bahasa Indonesia yang berjudul "Analisis Kasus Mahasiswa Bunuh Diri di Tahun 2023 dalam Perspektif Civitas Akademika dan e-Counseling UB sebagai Layanan Konseling Mahasiswa di Universitas Brawijaya" dengan dosen pengampu Pak Moch. Ighfir Sukardi, S. Pd., M.Li Kami ingin menanyakan beberapa tanggapan dan melakukan wawancara singkat bersama konselor e-Conseuling UB mengenai kasus mahasiswa bunuh diri secara tatap muka. Mengenai surat izin observasi yang kami lakukan akan kami berikan secara langsung kepada pihak konselor pada hari Rabu, 8 November 2023', '2023-11-05 11:25:20');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4333, 1587, 101398, 'mahasiswa', 'Andhika Cahya Ramadhani', 'Mohon maaf atas keterlambatan respon dari saya. Saya sangat bersedia untuk jamnya diubah, mungkin dari saya bersedia hadir setelah maghrib.', '2023-11-05 15:09:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4334, 1598, 101409, 'mahasiswa', 'Putrianti Adinda Salsabila', '235030107111013. Bullying verbal mulai didapatkan setelah saya terlihat aktif di kelas. Pelaku berjumlah 4 orang pria dan 1 orang perempuan. Mereka seolah membangun presepsi tentang saya dan menyakiti hati saya secara verbal baik pada pertemuan ataupun media digital. Pelaku tidak menyukai saya yang aktif di kelas. Namun setelah saya mencoba untuk tidak aktif lagi, pelaku semakin sering menyerang secara verbal mengenai kesibukan saya. Detailnya akan diceritakan secara tatap muka oleh saya karena terlalu kompleks. Hal ini mengganggu kehidupan perkuliahan saya dan kepercayaan diri saya.', '2023-11-05 18:24:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4335, 1599, 101382, 'mahasiswa', 'Jisca Ayu Setya Putri', 'Ada beberapa hal yang mengganggu pikiran saya belakangan ini dan di titik tertentu saya tidak tahu harus pergi ke siapa hingga ingin melukai diri sendiri.', '2023-11-05 18:31:52');
