INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4360, 1597, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>baik bapak/ibu, saya berkenan untuk wawancara bersama peer counselor. terima kasih</blockquote> <p>Baik, kalau begitu untuk memudahkan komunikasi, silahkan Anda langsung menghubungi peer counselor yang bersangkutan yaitu Kak Ivanditie +62 812-3073-9670 (Whatsapp)<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-11-06 21:08:05');
