INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4381, 1574, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Selamat siang izin bertanya, jadwal konsultasi saya akan di laksanakan hari apa ya bu?</blockquote> <p>Mohon maaf baru membalas, Akan dilaksanakan pada Kamis, 9 November 2023 pukul 08.30 - 09.30 WIB melalui Google Meet bersama Ibu Ika Fitria. Nanti akan dihubungi melalui Whatsapp yaa</p>', '2023-11-08 11:40:29');
