INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4383, 1600, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Selamat siang. Terimakasih atas balasannya. Apabila hari Rabu besok di jam yang sama apakah bisa? Jika tidak memungkinkan, apakah bisa di hari Selasa 14 November 2023 pukul 10.30? Dikarenakan hari Rabu tanggal 15 November 2023 di jam tersebut saya ada kelas praktikum. Terimakasih atas perhatiannya bapak/ibu konselor.</blockquote> <p>Mohon maaf baru membalas. Untuk tanggal 14 November adanya di jam 14.00 itupun secara online. Kalau Anda berkenan, Kamis, 16 November 2023 pukul 10.00 WIB secara offline, bagaimana?</p>', '2023-11-08 11:46:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4384, 1601, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Bagaimana jika rabu tanggal 8, di sore hari sekitar jam set 4</blockquote> <p>Mohon maaf baru membalas. Kalau hari Jumat, apakah berkenan yaa? Anda kalau hari Jumat, 10 November 2023 bisanya jam berapa yaa?</p>', '2023-11-08 11:48:07');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4385, 1602, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Bersedia, saya bersedia untuk bertemu konselor pada hari jumat 10 november 2023</blockquote> <p>Baik kalau begitu, saya coba carikan dulu yaa. Kalau sudah dapat, akan saya hubungi kembali. Kalau boleh tahu, Anda berkenan jam berapa? </p>', '2023-11-08 11:54:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4386, 1600, 100665, 'mahasiswa', 'Aulia Sekarningrum W', 'Mohon maaf, bu hari kamis di jam tersebut saya juga ada kelas. Di hari jumat 17 November jam 10 WIB apakah bisa bu? Atau mungkin ibu bisa kasih opsi hari dan jamnya di minggu ini dan minggu depan untuk saya bisa menyesuaikan? Terimakasih atas maklumnya', '2023-11-08 12:02:59');
