INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4398, 1600, 100665, 'mahasiswa', 'Aulia Sekarningrum W', 'Mohon maaf baru membalas. Hari selasa tgl 14 November saja bu, tidak apa-apa online dahulu. Terimakasih atas bantuannya', '2023-11-08 21:11:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4399, 1609, 101419, 'mahasiswa', 'Yohana Sekar', 'NIM: 215010101111022 Permasalahan ini tidak saya temukan di rekan-rekan saya. Setiap kali saya melakukan presentasi atau sekadar menjawab pertanyaan dosen yang membutuhkan elaborasi lebih jauh, entah kenapa saya selalu merasa sooner or later suara saya akan jadi pecah dan bergetar, nafas saya menjadi sulit untuk dikontrol, fokus saya pecah sehingga hal yang seharusnya dapat dilakukan dengan mudah menjadi perkara besar bagi saya, menjadi momok bahkan seminggu sebelum pelaksanaan, sekalipun dalam beberapa case sebenarnya saya menguasai materi yang dipresentasikan atau yang ditanyakan. Saya merasa malu karena tidak bisa menguasai diri saat presentasi, sedangkan semester ini menuntut kami untuk banyak bicara di depan banyak orang.', '2023-11-09 08:49:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4400, 1610, 101421, 'mahasiswa', 'Ahmad Rasyid', 'Assalamualaikum Wr. Wb. Saya Ahmad Rasyid mahasiswa Teknik Elektro UB semester 3 dengan NIM. 225060307111098 Saya ingin menceritakan kesalahan saya semester 2 dan 3. Pada semester 2 saya hanya lulus 3 matkul dengan ip 1.450, lalu semester 3 ini saya mengambil 18 sks namun banyak melewati kelas dan saya tidak masuk pada saat UTS sehingga ada kemungkinan saya tidak lulus. Ini dikarenakan ibu saya cerai yang kedua kalinya dan banyak permasalahan fisik di dalam keluarga yang mempengaruhi kuliah motivasi saya saat semester 2 dan 3, sehingga saya selama semester 3 saya jarang keluar kos sehingga titik saya saat ini, Saya sangat merasa sangat malu terhadap ibu. Saya ingin meminta bantuan kepada pihak universitas atau terminal, saya juga ingin bertanya apakah ada kemungkinan semester 3 ini saya di-cutikan atau pihak universitas bisa membatalkan beberapa mata kuliah saya agar bisa IPK terjaga sehingga semester berikutnya saya bisa mulai maksimalkan dengan mengambil sks lebih banyak. Untuk bantuannya saya sangat sangat berterima kasih.', '2023-11-09 09:53:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4401, 1611, 101422, 'mahasiswa', 'siti amalia sari', '205040201111984 saya memiliki permasalahan dengan teman saya dimana sikap yang teman saya miliki terus menerus mengganggu saya', '2023-11-09 13:15:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4402, 1612, 101423, 'mahasiswa', 'Syilvia Fajriati', '205040200111095 Akhir akhir ini saya merasa lelah dan linglung jika bertemu banyak orang dan tidak suka jika berada dikeramaian. Karena saya merasa energi saya terserap sehingga saya mulai mengurangi aktivitas bertemu banyak orang dan hanya berdiam diri dikamar kosan', '2023-11-09 13:23:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4403, 1613, 101425, 'mahasiswa', 'Amellia Regina Putri', 'Sebelumnya saya Amellia Regina dengan NIM 205030200111034. Saya Regina saya memiliki permasalahan dengan diri saya sendiri, dikarenakan saya memiliki kecenderungan untuk melakukan procrastination, kecenderungan pesimis ketika menghadapi tantangan, susah berkomitmen, mudah bosan, sulit memfokuskan diri pada satu subject, dan pikiran/kemauan saya tidak cukup untuk mengendalikan tubuh saya. Dalam satu kasus, saya berencana mandi 2kali sehari, saya sudah menjadwalkan mandi jam 8 pagi, saya terus menunda kegiatan tersebut, sampai keesokan pagi nya, dan dalam 1 hari itu saya hanya berada di dalam kamar tanpa melakukan kegiatan lainnya. Saya sekarang berapa di tahun terakhir saya, dan sedang menyusun laporan magang dan skripsi, jadwal yg bebas membuat saya kebingungan untuk memulai mengerjakan tugas akhir saya karena terus menunda-nunda, bahkan saya memiliki ketakutan untuk membuka laptop, karena saya berpikir bahwa membuka laptop sama dengan kita harus mengerjakan skripsi dan harus ada progress.', '2023-11-09 15:39:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4404, 1600, 100665, 'mahasiswa', 'Aulia Sekarningrum W', 'Mohon maaf bu saya izin mengkonfirmasi lagi. Apakah di hari selasa tgl 14 November masih bisa bu? Terimakasih atas bantuannya', '2023-11-09 18:53:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4405, 1614, 101426, 'mahasiswa', 'Laili Sarifatu Rikhmah', 'Nama : Laili Sarifatu Rikhmah NIM : 215050101111135 Akhir-akhir ini saya sedang konflik dengan diri saya sendiri. Awal mula saya mengikuti sebuah UKM A, dimana UKM ini saya rasa cocok dengan kepribadian saya. Tetapi pada akhirnya saya kurang nyaman, karena mungkin belum sefrekuensi dengan teman-tema saya yang notabenenya anak pondok, dan saya anak umum. Di divisi saya, adalah salah satu kating saya, beliau sangat menganggap saya sebagai adik, tetapi satu lain hal saya juga merasa tertekan setiap melakukan tugas, karena selalu dapat teguran dan kesalahannya di kembalikan ke saya (saya terlalu mengiyakan semua, tanpa inisiatif ide baru). Akhirnya saya merasa berat menjalankan amanah di UKM tersebut, dan memilih untuk mencoba mendaftar pertukaran pelajar. Alhamdulillah saya keterima dan saya sangat senang di tempat baru ini karena tidak ada tanggungan kewajiban yang harus saya jalankan dengan sibuk seperti pada saat saya mengikuti UKM. Akhir akhir ini saya merasa jauh dari teman-teman UKM saya, saya merasa semakin jauh. Dan setiap saya membuat postingan jika sedang bersenang-senang/ belajar dengan enjoy di PMM ini, saya merasa bersalah, ketakutan, takut di salahkan, takut dianggap tidak amanah menjalankan tugas UKM. Padahal sepertinya itu hanya pikiran saya. Bahkan saya takut untuk melihat story, berita UKM saya yang sekarang lagi sibuk untuk acara besar. Saya merasa paling menjadi manusia berdosa diantara teman-teman saya. Perasaan ini sangat menyiksa diri saya, padahal saya tau ini hanya overthinking saya saja. Mungkin setelah kembali ke UB saya takut untuk bertemu mereka, saya sungkan karena lebih memilih PMM daripada amanah yang diberikan dari UKM di semester ini. Seharusnya saya harus bagaimana, apakah saya sebaiknya tidak melihat pemberitaan mereka? Apakah hidup private lebih baik? Persoalan kedua yaitu, saya anak tunggal di keluarga, dimana tuntutan menjadi berprestasi seakan sudah menempel di telinga saya. Ibu saya dulu mengharuskan untuk berprestasi dari SD hingga SMA. Tetapi mungkin karena di perkuliahan, tingkat kesuksesan tiap orang berbeda, ibu saya legowo untuk saya melakukan apapun. Pada saat kuliah saya dibiayai dari orang tua karena tidak mendapatkan beasiswa, sehingga hal ini seringkali membuat saya merasa bersalah sekali, baik ketika berperilaku jelek atau mendapatkan nilai turun. Saya takut salah, saya takut kalah, saya takut tidak dianggap, dan seringkali saya ingin menutup keras telinga saya dengan semua tuntutan itu. Kalau bahasa kasarnya, kalau bukan kamu siapa lagi yang jadi harapan keluarga. Kalo kamu berbuat jelek satu kali, pasti bakal berimpact pada cara pandang orang lain ke kamu. Saya sangat patuh akan aturan itu, sehingga sebisa mungkin jangan sampai saya menyakiti hati orang 1 pun dan berbuat salah ke mereka, lebih baik saya kesal pada diri saya sendiri daripada menyalahkan orang lain. Tiap kali saya mengeluh, ibu saya seringkali menyuruh saya bersyukur,padahal saya tau tanpa disuruh pun saya pasti akan berkaca dengan mensyukuri semua nikmat. Saya juga tau yang dilakukan ibuk saya semua untuk kebaikan, tapi keharusan untuk berbuat baik, mempertimbangkan semua risiko, peka terhadap orang lain dan menjaga, membuat syas tidak bisa menentukan pilihan apapun. Ketika saya capek kuliah, ibu saya membahas mengenai pengeluaran untuk saya kuliah, disaat itu saya langsung stress. Andai kalau bisa saya cari uang sendiri, pasti saya akan berusaha membiayai diri saya sendiri. Sejauh ini yang reward saya, saya gunakan untuk self reward seperti membeli pakaian, membayar kos 1 bulan, skincare dan belum ada apa apanya jika di bandingkan dengan pengeluaran saya setiap 1 semester. Saya merasa bersalah untuk pengeluaran itu, padahal orang tua saya mencari uang juga untuk membiayai saya karena saya anak satu satunya. Apakah jika punya anak itu merupakan bentuk investasi dan pemenuhan mimpi orang tua? Apakah saya harus mengikuti semua peraturan yang ada? saya harus bungkam dan mengiyakan aturan untuk berbuat baik? Atau sebaiknya saya harus bagaimana. Ibuk selalu bilang, kalo ibuk bapak itu cari uang untuk kebutuhan saya, karena siapa lagi yang di biayain kalo bukan untuk saya. Tapi disisi lain saya merasa bersalah untuk semua pengeluaran, dan kalau di tanya tentangga saya gitu, ibuk jawab kalo saya yahg menghabiskan uang. Mungkin itu jokes ibuk ibuk ya, tapi saya merasa gagal jadi anak. Teman-teman desa saya sudah kerja dan memberikan uang ke orang tua mereka, ada teman saya yang kuliah dan mendapatkan beasiswa, sehingga ibunya seringkali adu nasib anaknya yang sering bantu biaya rumah tangga, sedangkan saya hanya menghabiskan. Saya capek dengan ekonomi ini. Alhamdulillah saya middle class dengan background kehidupan pedesaan. Lalu selanjutnya yaitu masalah lanjut study, seringkali saya ditanya kapan lulus, kapan kamu selesai kuliah, ibuk masih 1 tahun setengah ya ngebiayain kamu, berapa uang lagi yang harus di keluarkan. Kamu harus lanjut S2 setelah lulus ini. Saya bilang, saya bakal lanjut jika mendapatkan LPDP, tapi ibu saya menyuruh untuk langsung meskipun tidak mendapatkan beasiswa, Krn bapak saya siap untuk membiayai. Saya menolak statement itu, saya ingin bekerja saja dan mendapatkan uang untuk menunggu seleksi beasiswa. Kalo saumpama saya mengiyakan biaya pribadi semua, apakah saya akan kuat mental dengan semua statement yang habis untuk kuliah? tentu saya cape dengan kata kata itu. (Sebenarnya Alhamdulillah tidak habis, malah rezekinya semakin bertambah, tapi kata-kata ibuk saya terkadang membuat saya tertekan, padahal tujuannya untuk menyadarkan saya bahwa dalam menuntut ilmu, sebaiknya tidak boros). Seharusnya bersyukur yang benar itu seperti apa, saya lagi stress melihat pencapaian teman-teman saya di sosial media, saya merasa tertinggal, saya merasa bodoh. Tetapi disisi lain prestasi saya juga sudah lebih dari cukup, tetapi saya fomo melihat kesuksesan mereka. Apakah saya lagi jauh dari agama? Terimakasih telah mendengarkan cerita saya. Mohon maaf jika saya sering stress karena masalah sepele. Terimakasih', '2023-11-09 23:39:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4406, 1615, 101428, 'mahasiswa', 'Kayana Gita Safira', 'Saya Kayana, NIM 205030107111005. Sudah beberapa minggu ini saya merasa susah tidur setiap hari dan kehilangan motivasi untuk melakukan kegiatan sehari hari termasuk kegiatan akademik mengerjakan skripsi saya. Saya tidak tahu apakah saya hanya demotivasi atau stress karena merasa beban skripsi sebagai pressure, atau ada sesuatu yang salah pada diri saya. Karena keinginan untuk hilang saja, kembali lagi setelah sebelumnya tidak merasa seperti itu. Kegiatan saya terbatas di rumah, saya merasa tidak nyaman menceritakan kondisi saya pada keluarga saya.', '2023-11-10 02:19:26');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4407, 1601, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Mohon maaf Davina. Untuk konseling di hari Jumat besok tidak tersedia. Kami alihkan minggu depan. Bisakah Anda memberitahukan kami waktu Anda yang tersedia?</p>', '2023-11-10 06:37:23');
