INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4434, 1622, 101289, 'mahasiswa', 'Zeeges Mollic', 'NIM: 235100500111039 Dulu saya pernah menjalin hubungan yang tidak sehat (penuh dengan manipulasi) dengan seorang laki-laki yang lebih tua umurnya dari saya. Sudah 1 tahun sejak saya mengakhiri hubungan saya, tetapi sampai saat ini saya masih sering tertrigger dan menangis sendiri.', '2023-11-13 15:59:54');
