INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4469, 1627, 101441, 'mahasiswa', 'Mohammad Firman Syah', 'Terima kasih telah merespons tiket saya. Memang benar, masalah pribadi ini merupakan penyebab kecemasan saya yang belum sepenuhnya teratasi. Saya berharap, dengan melakukan konsultasi langsung dengan seorang psikolog atau psikiater, saya dapat menemukan jalan untuk memperbaiki keadaan saya.', '2023-11-18 18:58:54');
