INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4527, 1635, 101454, 'mahasiswa', 'Herdina Candra Setyorahayu', 'Saya berkenan untuk sesi konseling offline bersama peer konselor. Saat ini saya masih merasakan kondisi seperti yang sebelumnya sudah saya ceritakan, kecemasan yang muncul dari pikiran-pikiran berlebih pada diri saya. Sering melamun dan kehilangan konsentrasi. Beberapa kali kondisi mood/perasaan saya juga tidak menentu. Kira kira seperti itulah yang saat ini saya rasakan.', '2023-11-24 06:31:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4528, 1644, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Maaf wa nya ke nomor ini ya 085225729406 karena saya sampai sekarang belum berani buka wa saya</blockquote> <p>Terima kasih telah menggunakan layanan konseling. Saya mengerti yang Anda rasakan saat ini tidaklah mudah. Apabila Anda saya jadwalkan sesi konseling offline bersama konselor pada Rabu, 29 November 2023 pukul 10.30 di Ruang Konseling Gedung Rektorat Lantai 1, apakah berkenan? Mohon konfirmasinya yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-11-24 12:12:48');
