INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4561, 1643, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Senin sekitar jam 2 apakah bisa?. Apakah orang luar ub bisa konsul juga. Karena teman saya ingin konsultasi juga.</blockquote> <p>Baik, jam 14.00 WIB yaa. Tapi saya coba carikan dulu peer conselour yang bisa yaa. Apabila sudah mendapatkan, akan saya kabari. </p>', '2023-11-25 10:57:41');
