INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4609, 1663, 101478, 'mahasiswa', 'Puspa Kamilah Setiatika', '225010100111071 Jadi saya baru saja putus dari pacar saya, tapi hal ini membuat saya susah fokus, menyimpan emosi yang dalam dan sempat self harm', '2023-11-30 08:09:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4610, 1664, 101479, 'mahasiswa', 'Meta Febriana', 'NIM : 235050100111005 Terlalu mudah memikirkan hal-hal kecil, takut melakukan sesuatu, belum bisa mencintai diri sendiri, dan merasa tidak punya pendirian.', '2023-11-30 13:35:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4611, 1665, 101481, 'mahasiswa', 'Adita Putri Maharani', 'NIM: 205090207111001 Saya terbebani dengan tugas yang tidak pernah berhenti, tapi memang salah saya yang menyanggupi semuanya. Hanya saja saat ini saya jadi mudah letih, suka tunda makan, kurang fokus, mudah sakit, sangat sensitif, ada perasaan ingin menjauh dari orang lain, dan pelupa. Ada juga saat saya mencari objek lain, misal pulpen, saya cari tidak ada di mana-mana padahal sudah jelas ada di hadapan saya. Kondisi ini terjadi secara berulang sehingga saya khawatir jika merambat kemana-mana. Saya ingin healing, tetapi tidak tau manajemen coping yang baik.', '2023-11-30 16:21:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4612, 1666, 101483, 'mahasiswa', 'Naufal Rafi Taufiqurrahman', 'Jadi sebelum saya disini, sebenarnya saya itu pernah kuliah di UNEJ jurusan kedokteran dan sewaktu disana saya mengalami skizofrenia dan membuat saya harus mengundurkan diri karena sudah gakuat mengalami kegilaan kegilaan (maksudnya ini itu bayangan bayangan) disana. Dan sewaktu saya pindah ke UB saya mengalami kekacauan akademik yg dikarenakan trauma masa lalu dan rasa bersalah akan diriku di masa lalu', '2023-11-30 21:04:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4613, 1667, 101484, 'mahasiswa', 'Putri Ayu Sukma Djati', '025110200111008. Saya merasa tidak memiliki tujuan hidup sehingga saya tidak memiliki semangat hidup.', '2023-11-30 21:05:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4614, 1668, 101485, 'mahasiswa', 'Najma Aufi Zayyana', '215080607111053. Sebetulnya ini masalah akademik dan kepanitiaan, hanya butuh teman cerita untuk meluapkan karena merasa sudah tidak bisa ditahan sendiri.', '2023-11-30 21:39:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4615, 1669, 101486, 'mahasiswa', 'Hikmatun azizah', 'Halo, aku mempunyai masalah pribadi sampai hal ini mengganggu aktivitas saya sehari hari karena setiap harinya dada saya selalu sakit, tidur saya gelisah, bahkan sering kali kepala saya berat dan pikiran saya kadang2 kosong tanpa alasan', '2023-12-01 00:03:14');
