INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4646, 1672, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>NIM: 225110800111001 Konseling lanjutan dengan Ibu Bona, berkaitan dengan hypomania dan anxiety.</blockquote> <p>Terima kasih Amalia telah menggunakan layanan konseling. Terkait jadwal Ibu Bona saat ini sudah penuh sampai minggu depan. Kemudian, saya informasikan juga bahwa Layanan Konseling akan libur dulu mulai 18 Desember 2023 - 14 Januari 2024. Mohon maaf atas ketidaknyamanan ini, Amalia mau bagaimana yaa? Atau berkenan tidak yaa saya jadwalkan dengan konselor lain? Atau bagaimana?</p>', '2023-12-01 17:24:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4647, 1669, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Berkenan kak, sekitar jam 9 an apakah bisa?</blockquote> <p>Baik, saya hubungi melalui whatsapp saja yaa</p>', '2023-12-01 17:25:26');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4648, 1672, 101256, 'mahasiswa', 'Amalia Ramadhaniyah Adhie Dwi Putri', 'Kalau begitu, apa memungkinkan membuat jadwal konseling daring dgn ibu bona untuk januari? Atau apakah saya harus membuat tiket baru lagi nanti? Terima kasih', '2023-12-01 17:28:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4649, 1672, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Kalau begitu, apa memungkinkan membuat jadwal konseling daring dgn ibu bona untuk januari? Atau apakah saya harus membuat tiket baru lagi nanti? Terima kasih</blockquote> <p>Baik, kalau begitu saya jadwalkan di Januari 2024 yaa. Untuk jadwalnya tentu masih belum bisa diberikan kapan sebab pasti ada perubahan. Amalia tidak perlu membuat e-ticket lagi, nanti akan saya data yang telah booking dari lama. Terima kasih atas pengertiannya. Kalau Amalia butuh sekedar cerita, boleh nanti saya jadwalkan dengan peer counselor yaa. Terima kasih. Sampai jumpa di tahun 2024. <br /><br />Salam hangat,<br />Tim Konseling UB</p>', '2023-12-01 17:41:29');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4650, 1673, 101490, 'mahasiswa', 'Jihan Tsabitah Yumna', 'Saya punya masalah saya maba diterima di UB jalur snbp. Saya punya kecanduan dengan game online tapi bukan game seperti mobile legend, dan juga saya sangat boros. Sedangkan saya jika ada tekanan melampiaskan nya itu harus membeli makanan dan juga bermain game. Dan juga apakah benar mahasiswa jalur snbp tidak bisa mengikut kerja part time di luar jam kuliah?? Saya ingin mengajukan KIP tapi ketakutan akan ditolak karena rumah masih layak ditempati gimana solusinya??? Saya juga lelah jika harus pulang pergi kuliah menggunakan sepeda. Apakah ada solusi untuk masalah ini? Saya nyerah, saya capek.', '2023-12-01 18:16:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4651, 1673, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Saya punya masalah saya maba diterima di UB jalur snbp. Saya punya kecanduan dengan game online tapi bukan game seperti mobile legend, dan juga saya sangat boros. Sedangkan saya jika ada tekanan melampiaskan nya itu harus membeli makanan dan juga bermain game. Dan juga apakah benar mahasiswa jalur snbp tidak bisa mengikut kerja part time di luar jam kuliah?? Saya ingin mengajukan KIP tapi ketakutan akan ditolak karena rumah masih layak ditempati gimana solusinya??? Saya juga lelah jika harus pulang pergi kuliah menggunakan sepeda. Apakah ada solusi untuk masalah ini? Saya nyerah, saya capek.</blockquote> <p>Terima kasih Jihan telah menggunakan layanan konseling. Saya mengerti yaa pasti capek kemana-mana naik sepeda. Terkait pernyataan bahwa mahasiswa SNBP tidak boleh kerja parttime itu tergantung. Apabila Jihan mendapatkan beasiswa dari salah satu instansi, tentu ada syarat yang harus dipenuhi, salah satunya harus menjaga nilai IPK supaya tetap diatas ambang batas. Namun, jika Jihan belum terikat beasiswa dengan instansi manapun, sangat diperbolehkan untuk kerja parttime. Asalkan Jihan dapat mengatur waktu dengan baik dan tetap mengikuti perkuliahan sesuai dengan jadwal. Kemudian terkait KIP. Saya kurang mengerti mekanisme KIP seperti apa, Jihan dapat tanyakan hal ini kebagian kemahasiswaan/akademik di FIB atau Jihan dapat mencari informasi lebih detail di website resmi. Bisa juga jika Jihan bertanya kepada teman jihan yang mendapatkan beasiswa KIP. Menurut saya, alangkah baiknya Jihan mencari informasi beasiswa selain KIP seperti Tanoto Foundation, Beasiswa Unggulan, Bakti BCA, Beasiswa Djarum, dan masih banyak lainnya yang lebih cocok untuk mahasiswa berprestasi yang berada pada level menengah perekonomiannya, tanpa harus mengada-ngada terkait kondisi rumah. Kalau Jihan butuh teman cerita, boleh nanti saya jadwalkan sesi konseling bersama peer counselor. Bagaimana?<br /><br />Salam hangat,<br />Tim Konseling UB.<br /></p>', '2023-12-02 09:34:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4652, 1674, 101491, 'mahasiswa', 'Aulia Sara Dewi', '205030800111024 Karena adanya masalah keluarga, membuat saya kehilangan rasa percaya diri dan lebih mudah panik karena takut sesuatu yang buruk akan terjadi.', '2023-12-02 10:16:11');
