INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4654, 1675, 101492, 'mahasiswa', 'Urfi Tazkia Nada', 'NIM: 215110400111016 Permasalahan pribadi, aku khawatir akan lulus sangat terlambat karena aku sangat bodoh di akademik. Perlakuan tidak adil dan tidak baik yg dilakukan dosen kepadaku, serta permasalahan lain yg membuatku merasa mungkin aku punya penyakit mental. Ketakutan akan kesendirian, kesepian, tidak punya teman. Anak ub jahat jahat', '2023-12-02 10:43:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4655, 1674, 101491, 'mahasiswa', 'Aulia Sara Dewi', 'untuk konseling offline dilakukan dimana ya? Hari jumat pagi sekitar jam 9 atau jam 10 saya bisa', '2023-12-02 10:45:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4656, 1674, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>untuk konseling offline dilakukan dimana ya? Hari jumat pagi sekitar jam 9 atau jam 10 saya bisa</blockquote> <p>Dikedua jam tersebut sudah ada sesi konseling lain. Kalau jam 12.00 WIB bagaimana yaa?</p>', '2023-12-02 17:43:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4657, 1675, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>NIM: 215110400111016 Permasalahan pribadi, aku khawatir akan lulus sangat terlambat karena aku sangat bodoh di akademik. Perlakuan tidak adil dan tidak baik yg dilakukan dosen kepadaku, serta permasalahan lain yg membuatku merasa mungkin aku punya penyakit mental. Ketakutan akan kesendirian, kesepian, tidak punya teman. Anak ub jahat jahat</blockquote> <p>Terima kasih Urfi telah menggunakan layanan konseling dan bercerita perasaan Urfi saat ini. Tentu tidak mudah yaa berada di lingkungan yang toxic, sekalipun dosen. Apabila saya jadwalkan sesi konseling offline bersama konselor (Ibu Selly) pada Senin, 11 Desember 2023 pukul 09.00 WIB, bagaimana yaa? </p>', '2023-12-02 17:46:26');
