INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4674, 1677, 101494, 'mahasiswa', 'Amelia Nur Hamida', 'NIM: 215110407111032 saya punya masalah pribadi soal asmara. ini sudah mengganggu saya efek sampingnya saya suka minum obat2 an yg suka buat tidur dan alkohol. sudah pernah konsul online lewat halodoc tp kurang memuaskan.', '2023-12-03 13:56:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4675, 1678, 101495, 'mahasiswa', 'Nisrina Adnin Naqiyya', 'NIM: 205110700111041. Saya mengalami insomnia beberapa hari ke belakang. Saya tidak bisa tidur hingga pagi menjelang. Pikiran saya rasanya tidak mau berhenti. Hal ini terjadi pertama kali saat saya terlibat konflik dengan teman saya beberapa bulan lalu. Kemudian beberapa hari ini kambuh, karena banyak deadline tugas &amp; skripsi. Insomnia ini sangat mengganggu, terutama pada kesehatan tubuh saya.', '2023-12-04 03:38:28');
