INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4679, 1679, 101497, 'mahasiswa', 'AKHMAD MUDZAKIR AL FAARUQ', 'NIM: 205060300111046 saya merasa susah mengatur waktu untuk mengerjakan tugas, belajar dan hiburan karena mudah teralihkan perhatian saya', '2023-12-04 15:57:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4680, 1680, 101498, 'mahasiswa', 'Siti Hilmaya Dewantari', '205090507111011 Saya merasa tidak bisa lepas dari seseorang dan jikapun bisa lepas, rasa ketergantungan ini akan dialihkan ke orang lain. Hal ini membuat saya merasa stres, demotivasi, hingga membuat saya tidak bahagia', '2023-12-04 19:14:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4681, 1681, 101443, 'mahasiswa', 'Haidar Arif Al Mohdor', '(235080307111025) Sesuai konteks yang terdapat di issue summary, perundungan dilakukan secara anonim dengan melakukan penyalahgunaan identitas. Saya yang menulis ini sebagai kakak dari korban. Pada awal perkuliahan, tepatnya pada masa ospek dalam lingkup fakultas (FPIK) adik saya tidak mengikuti kerja kelompok yang dinauingi oleh program ini. Dari sana adik saya dibuntuti oleh teror menggunakan aplikasi get contact yang menamai nomornya dengan nama yang kurang sopan seperti "beban kelompok; benalu kelompok; dsb" dan adik saya mencoba menghiraukan teror tersebut, tetapi setelah beberapa lama teror tersebut semakin membesar menjadi mencoba menyudutkan adik saya melalui pendekatan dengan teman teman dari adik saya, tidak hanya di lingkup universitas, bahkan teman adik saya yang berasal dari kota kelahirannya juga beberapa kali diteror bahkan diancam untuk tidak lagi berteman dengan adik saya. Teror juga berlangsung pada teman adik saya menggunakan nama adik saya untuk semakin menyudutkan adik saya. Perundungan tersebut masih berlangsung hingga sekarang dan harapan saya agar adik saya mendapatkan pendampingan psikologis untuk membantu adik saya semakin kuat untuk menghadapi proses yang telah berlangsung hingga ke polisi. Lebih lanjut lagi nantinya, mungkin bisa ditanyakan kepada adik saya secara langsung.', '2023-12-04 20:40:25');
