INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4689, 1684, 101500, 'mahasiswa', 'Muhammad Thoriq Farizi', '215100500111026 Saya memiliki fetish yang tidak wajar. Saya juga sering melihat video dan mengobrol dengan orang-orang yang baru saya kenal di media sosial hanya demi memuaskan fetish saya. Menurut saya ini sudah akut karena sampai mengganggu perkuliahan dan aktivitas di kehidupan sehari-hari. Saya juga merasa sulit fokus karena terus-terusan terpikir hal mengenai fetish saya. Selain itu, saya juga memiliki kecenderungan menyukai sesama jenis. Saya sepenuhnya sadar kalau itu sangat-sangat salah dan saya ingin sekali mengatasi masalah tersebut. Namun, dalam prosesnya saya membutuhkan bimbingan dari orang-orang yang memang berkompeten di bidangnya.', '2023-12-06 07:30:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4690, 1685, 100886, 'mahasiswa', 'Amelia Nanda Puspita', 'nim saya 215110700111043, saya dulu merupakan seorang yang aktif di bidang akademik, namun setelah ibu saya meninggal, saya menjadi seorang yang hilang arah, tidak punya tujuan hidup, sering kehilangan motivasi, saya juga takut untuk masuk rumah sakit karena trauma yang saya miliki', '2023-12-06 09:04:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4691, 1686, 101502, 'mahasiswa', 'Ahmad Sofyan Sauri Alfarisi', '185090300111001. Saya tidak tahu masalah utama saya. Tapi saya merasa malas tidak ingin melakukan apa-apa. Merasa seperti tidak perlu untuk berjuang, mungkin karena trauma? Saya disebutkan punya kebiasaan buruk dan saya juga punya kebiasaan aneh. Maaf saya kurang dapat menjelaskan.', '2023-12-06 13:02:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4692, 1687, 101504, 'mahasiswa', 'Nashrul Ummah', '215110701111005 Saya adalah pengidap OCD sejak 2 tahun terakhir mulai menyadarinya. Itu diketahui sejak mengisi kuesioner salah satu mahasiswa yang bersangkutan dengan topi ocd dari bidang psikologi. Lalu untuk dugaan bipolar itu belum saya ketahui secara jelas apakah benar itu yang terjadi pada saya. Karena ada masalah pribadi yang menimpa saya dan membuat saya tidak nyaman ada di kampus dan menjalani kehidupan seperti biasanya.', '2023-12-07 00:34:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4693, 1688, 101503, 'mahasiswa', 'Muslim Farel Irsanto', '195120407111042 I self diagnose my self having a depersonalization/derealization for 2 years now, and I feel it affecting my personal life and I think at some point it''s affecting my phsyical health like seizures . I need a clear diagnose from professional, so that I can recover for whatever condition I''m having.', '2023-12-07 00:40:04');
