INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4703, 1692, 101508, 'mahasiswa', 'Meutia Irdina Khairunnisa', '205100107111007 Sudah lebih dari seminggu setelah seminar proposal malah semakin stress dan bisa tiap hari nangis. Ketika seminar proposal sempat di cecer sama dosen pembimbing. Gak tau kenapa malah bikin stress dan tertekan padahal semua org udh bilang kalau gapapa dan udh terjadi. Sebenernya tau.. tapi ttp aja stress banget dan gatau cara ngatasinnya gmn', '2023-12-08 07:58:12');
