INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4743, 1697, 101515, 'mahasiswa', 'Keira Latifa Virgie', 'Saya merasa telah dilecehkan dengan photo editing AI yang melibatkan wajah saya serta pengambilan video tanpa seizin saya', '2023-12-11 18:27:01');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4744, 1690, 101506, 'mahasiswa', 'Rosyida Ariani', '1. Saya tidak mengingat dengan jelas kapan hal ini mulai muncul, mungkin pada awal/ pertengahan tahun ini 2. Saya masih bimbang dengan rencana kedepan, namun untuk jangka pendek tujuan yg ingin saya capai adalah menyelesaikan studi dengan baik dan tepat waktu 3. Saya rasa tidak ada, saya selalu tidur diatas jam 12 malam. Hal ini sudah menjadi kebiasaan. Sehari-hari saya sering kali merasa mengantuk dan terkadang dapat tidur pada siang sampai sore hari. 4. Saya rasa tidak ada, hanya merasa kebingungan dengan tujuan hidup saya dan merasa kehilangan diri sendiri.', '2023-12-11 18:57:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4745, 1687, 101504, 'mahasiswa', 'Nashrul Ummah', 'Saya sempat diberikan rujukan oleh dokter namun saya enggan untuk berangkat karena saya takut dan belum menemukan seseorang yang bisa saya percaya untuk menemani saya. Saya menyadari adanya OCD setelah mengisi kuesioner dari salah satu mahasiswa psikologi yang sedang menempuh skripsi. Disitu setelah saya menjadi salah satu respon, beberapa minggu kemudian mahasiswa tersebut menghubungi saya dan bertanya apakah saya mau menjadi salah satu subjek dari penelitiannya. Karena saya juga ingin tahu lebih dalam akhirnya saya mau. Dan setelah itu, saya kembali diberikan pertanyaan-pertanyaan lewat kuesioner lagi. Hal ini semakin membuat saya yakin bahwa saya adalah OCD. Setelah mengisi kakaknya bertanya kembali di WhatsApp untuk memastikan kondisi saya, kemudian saya bilang, setiap mau tidur saya harus mencuci tangan di dekat tempat tidur, kadang di kasur, kadang di lantai, ini adalah kegiatan jorok tapi saya tidak bisa tidak melakukannya. Kakaknya bilang saya OCD jenis cleaning karena jika dilihat saya tidak bisa kotor, melihat sesuatu yang menjijikan atau sesuatu yang tidak saya suka, saya harus mencuci tangan saya, meskipun dengan setetes air saja. Selanjutnya, lambat laun saya yang menghubungi kakaknya. Saya bertanya, kenapa ketika saya melihat benda berkarat atau berair seperti engsel pintu di kamar mandi, tempat nasi yang direndam dengan sisa-sisa nasi yang ada, membuat saya muntah-muntah. Itu spontan dari beberapa hal yang saya lakukan dan membuat pikiran saya terasa penuh, dada sesak, dan membuat saya tidak bisa mengontrol pikiran saya dan cenderung harus melakukan kecemasan-kecemasan yang ada. Selanjutnya untuk Bipolar, ini menyangkut masalah pribadi saya dengan percintaan di perkuliahan, saya ditinggalkan pacar saya dan ditonjok pipi kiri saya disuatu malam. Dicaci maki dan ditunjuk-tunjuk. Saya sangat trauma dan ketika saya benar-benar lelah dengan segalanya saya hanya menangis dan mengurung diri hampir 2 harian. Itu terus berlanjut dari bulan juni- saat ini. Semester 5 saya begitu berat, hal-hal di perkuliahan banyak yang saya acuhkan karena trauma itu memenuhi pikiran saya dan membuat saya tidak nyaman belajar di kampus. Saya bingung apakah hal ini terus berlanjut atau saya yang memang tidak bisa mengontrol diri saya. Saya ingin menyerah tapi saya juga tidak mau kalah. Saya lelah.', '2023-12-12 15:10:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4746, 1688, 101503, 'mahasiswa', 'Muslim Farel Irsanto', 'Yes I''d love to, thank you', '2023-12-12 18:22:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4747, 1696, 101513, 'mahasiswa', 'Yazid Zidane Ahdiat', 'Pada tahun 2023 saya cuti karena ada kendala dalam ekonomi yang mengharuskan saya bekerja di Jakarta, untuk melanjutkan kuliah di Malang sudah tidak memungkinkan lagi oleh karena itu saya perlu pindah ke universitas di jakarta untuk melanjutkan pendidikan saya sambil bekerja', '2023-12-13 02:59:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4748, 1698, 101516, 'mahasiswa', 'Nur Laili Amalia', '195150207111017 saya melakukan pengerjaan skripsi sejak semester 7, dan sekarang saya berada di semester 9. Saya berharap ini menjadi semester terakhir dan lulus. Saya juga sudah berusaha untuk mengerjakan skripsi ini setiap hari selama 1 tahun kebelakang. Tetapi tidak kunjung selesai. Kemarin saya melakukan bimbingan skripsi yang saya harap menjadi satu langkah lagi menuju seminar hasil. Tetapi justru saya mendapatkan masalah disana, kata pembimbing saya apa yang telah saya kerjakan ternyata salah semua, dan secara eksplisit mengaju pertanyaan-pertanyaan yang menyuruh saya mengulang di semester depan. Sekarang saya bingung untuk membenarkan yang salah, karena belum terlalu paham untuk mengerjakannya, di sisi lain saya sudah merasa panik karena takut tidak bisa menyelesaikannya pada semester ini.', '2023-12-14 10:14:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4749, 1699, 101517, 'mahasiswa', 'Nicholas Surya Putra', 'NIM 235020407111022 Saya terkendala dengan perasaan selalu tidak puas dengan hidup saya, serta terkendala dengan kecemasan berlebih saya terhadap permasalahan permasalahan yang sebenarnya belum tentu terjadi, terkadang saya selalu mencari jalan keluar pintas untuk merasa senang atau merasakan sesuatu secara sesaat saja Hal ini yang membuat kehidupan saya baik secara sosial maupun akademik tergganggu Saya bingung dengan alasan saya seperti ini, dan saya ingin menemukan solusi atas permasalahan saya', '2023-12-14 13:09:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4750, 1700, 101520, 'mahasiswa', 'Muhammad Arkoun', 'Nama: Muhammad Arkoun NIM: 205060100111020 Persiapan Koas, Nilai Mandek, Kesulitan Belajar', '2023-12-14 13:39:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4751, 1701, 101518, 'mahasiswa', 'Ryaminto arbi', '233141507111004 Saya manusia biasa yang sehat, ceria, positif, aktif di kelas. Setelah saya gagal dalam hubungan saya sebelumnya karena saya merasa dicurangi, saya berusaha bangkit di hubungan yang baru. Trauma dan trust issue muncul setelah saya memulai hubungan baru. Saya bingung, saya takut, saya harus bagaimana, Sikap pasangan saya membuat saya bingung dalam bertindak, sehingga tak jarang membuat saya merasa kebingungan dalam keseharian. Saya tidak yakin dia masih menginginkan saya atau tidak, tapi saya merasa tidak berharga dan kecewa. Saya sangat menyayangi pasangan saya, apapun rela saya lakukan, tapi untuk saat ini saya hanya menangisi apa yang saya terima Saya menangis berlarut larut dalam perasaan saya sendiri. Saya kehilangan diri saya, saya kehilangan kewarasan saya, Itu semua mengganggu produktivitas sehari hari saya, saya sekarang menjadi pribadi yang murung cenderung pendiam dan pasif . Bukan keinginan saya, tapi kepala saya terlalu berisik', '2023-12-14 13:40:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4752, 1702, 101521, 'mahasiswa', 'Pinkhan Azarin Rahmawaty', '205120200111021 suicidal thoughts yang kencang', '2023-12-14 14:13:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4753, 1703, 101523, 'mahasiswa', 'Kharisma Nuria Fitri', 'NIM: 236080117111003, saya merupakan mahasiswa fast track yang saat ini sedang penelitian tesis, permasalahan yang saya hadapi sekarang dimulai pertengahan bulan November dimana saya dikeluarkan secara tiba-tiba dari tim penelitian dosen pembimbing saya, dimaki-maki oleh beliau di depan umum, dan saya harus melakukan penelitian dengan biaya sendiri sedangkan kondisi keuangan keluarga saya sedang kurang baik. Saya takut kalau saya gugur fast track', '2023-12-14 14:33:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4754, 1704, 101524, 'mahasiswa', 'Nisrina Arintia Maghfiroh', '216150100111001. Di semester akhir ini semakin merasa banyak tekanan apalagi dari orang tua yang selalu menyuruh cepat lulus tanpa mengetahui bagaimana anaknya berusaha. Merasa tidak ada yang membantu mengerjakan tesis termasuk dosen pembimbing karena segala halnya harus mencari tahu sendiri sehingga hilang arah untuk mengerjakan tesis ditambah lagi merasa takut kepada orang tua dikarenakan uang yang digunakan untuk mengikuti presentasi jurnal internasional ditolak ketika saya mengajukan pengembalian dana. Dikarenakan bingung harus bagaimana sehingga sering sekali dan hampir setiap hari selalu emosi, marah besar dengan memukul kepala sendiri, menggigit tangan, memukulkan benda-benda ke tubuh sendiri. Sering sekali merasa ingin bunuh diri tapi sadar kalau belum punya bekal untuk di akhirat dan saya pobia darah serta takut ketinggian.', '2023-12-14 14:33:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4755, 1705, 101527, 'mahasiswa', 'Trulli Oka Demayanti', 'NIM : 21511030711107 Masalahnya saya tuh punya pengalaman buruk di dunia atlet saya sama pas dikampus.', '2023-12-14 14:42:01');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4756, 1706, 101525, 'mahasiswa', 'Salsabila Nur Firdausi', 'saya Salsabila, dengan NIM 225110101111005 fakultas ilmu budaya, sastra inggris 2022. semenjak memasuki semester 3, entah kenapa saya seringkali merasa stres dan kehilangan alasan saya untuk hidup. seperti banyak sekali hal-hal yang bersarang di otak saya, tapi saya sendiri tidak tau hal-hal yang membuat penuh otak itu apa saja. saya hanya merasa stres, tertekan, sakit, tidak ada semangat bahkan untuk mengikuti kelas, yang kadang sering saya takutkan akan berdampak pada nilai akademik saya. terlebih saya anak beasiswa kipk, sudah menjadi tanggung jawab saya untuk terus meningkatkan prestasi akademik yang saya miliki. tapi untuk bisa di titik itu, saya yang tidak sanggup. rasanya seperti sudah tidak kuat, tapi tetap saya jalani. saya tidak punya alasan bertahan, tapi saya hanya melanjutkan hidup, seperti itu rasanya.', '2023-12-14 14:42:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4757, 1707, 101528, 'mahasiswa', 'nur alifia sashi kirana', '205030900111020, semenjak saya berhenti minum obat tidur saya seperti terkena sleep paralyze dan hampir tiap hari sangat menganggu saya', '2023-12-14 14:51:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4758, 1708, 101529, 'mahasiswa', 'Emerita Maya', '225110707111011 saya lelah dengan hidup, saya ingin hidup serba berkecukupan dan meninggalkan hal hal buruk yang bisa merugikan saya.', '2023-12-14 14:53:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4759, 1709, 101530, 'mahasiswa', 'Nadira Rizka Syahra Tanjung', '165060707111008 Saya sempat cuti 1 taun diperkuliahan dan baru aktif kuliah kembali semester ini yang dimana saya harus menyelesaikan beberapa matkul yang tersisa bersamaan dengan skripsi + magang, namun saya tidak bisa fokus untuk mengerjakan semuanya sekaligus jadi saya untuk saat ini cuma bisa fokus ke kuliah dan mengabaikan dua lagi. Berbarengan dengan kuliah ini, saya juga bekerja freelance karena diumur yang tidak lagi muda ini untuk menghasilkan penghasilan tambahan. Alasan saya cuti kuliah dahulu adalah karena trauma yang pernah saya alami saat saya pernah menjalani hubungan dengan mantan pacar saya yang dimana dia melakukan pelecehan pada saya dan bertempat di kampus, saya tidak pernah cerita ke siapa siapa karena takut dan merasa diri saya rendah, bahkan sampai saat ini rasa trauma tsb belum hilang dan menyebabkan fokus saya pecah dan rasa sangat takut ke kampus dan lebih memilih menghindar dan mengabaikan semuanya. Disisi lain, saya juga ingin cepat lulus tapi waktu yang ada tinggal sedikit lagi, apakah kira - kira solusi yang bisa saya lakukan untuk ini?', '2023-12-14 15:03:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4760, 1710, 101533, 'mahasiswa', 'Muhammad Fian Al Fanani', 'Mungkin bisa langsung aja ke poinnya, jadi aku akhir-akhir ini lagi ada masalah, dan seringkali hal itu membuat aku tiba-tiba badmood, jadi aku sebelumnya deket sama perempuan, yang mana dia udah janji buat ketemu, udah ngerencanain buat healing dll, tapi tiba2 dia hilang tanpa kabar udah seminggu dari sekarang, dan waktunya ga tepat banget, karena pas ada uas, aku takut masalah ini jadi berimbas ke akademik aku huhu, tiap hari aku juga ga mood ngelakuin apapun sampe nunda belajar, kadang juga ngerasa kesepian, apakah ada saran terkait masalah ini? Terima kasih sebelumnya, mungkin untuk lebih detailnya, bisa aku jelaskan lewat chat nantinya.', '2023-12-14 15:14:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4761, 1711, 101534, 'mahasiswa', 'Deeadra Aisha Putri', 'NIM: 235010100111093 Permasalahan saya tidak separah mungkin kasus teman-teman yang lain, tapi saya selalu menutupi kepribadian asli saya agar orang lain tidak menggaggap saya nyebelin, dan kadang saya tidak enakan jika menolak teman dan memberi batasan yang jelas, jujur saya sangat capek namun susah sekali untuk merubah hal ini. Karena masalah ini pun saya merasa bahwa saya tidak punya teman yang benar benar kenal saya dan itu membuat saya cukup terpukul…', '2023-12-14 15:32:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4762, 1712, 101535, 'mahasiswa', 'cassandra', '205010107111039 Tidak fokus dalam satu hal dan cenderung meninggalkan semua pekerjaan saat di bawah tekanan', '2023-12-14 15:32:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4763, 1713, 101536, 'mahasiswa', 'ALDINA WISIK RIANI', '225020407111030 permasalahan saya adalah ipk saya kecil grgr saya sibuk magang, bukan magang kampus merdeka melainkan magang sendiri, saya sangat suka di bidang yang saya geluti (diluar jurusan saya) dan saya lebih suka praktek &gt; teori, tapi grgr itu ipk saya jadi kecil, saya bingung, saya berpikir ingin cari kerja full time sebelum skripsi atau pas sudah lulus ya, tapi kalau cuma pikiran kerja kapan akademiknya selesai, saya ngerasa gapernah beruntung soal akademik punya ipk 2 rasanya di cap bodoh dan memunculkan pikiran di orang "kok bisa?" sebenernya itu keteledoran saya yang sebenernya saya gak seperti itu, saya ga pernah menyalahkan dosen atau magang saya krn keputusan yang saya ambil cukup baik krn di semester 2 sy udh punya pengalaman real dlm dunia praktikal dan ini sudah ditetapkan tuhan, sekarang bagaimana carany saya perbaiki ini semua yaa, terima kasih', '2023-12-14 15:56:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4764, 1714, 101537, 'mahasiswa', 'Aburizal Sulthon Hakim', '193140414111028 Saya merasa bahwa diri saya tidak pernah di sayang oleh kedua orang tua, keluarga besar dan pasangan semenjak orang tua saya bercerai, bahkan yang terbaru jika kelak suatu saat saya lulus dari UB bapak saya tidak mau hadir di acara wisuda dengan alasan malas.', '2023-12-14 15:57:17');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4765, 1715, 101538, 'mahasiswa', 'Natan Parasila', 'akhir-akhir ini saya merasa tidak punya semangat hidup, selalu overthinking dan tidak punya tenaga untuk melakukan apapun, saya merasa kesepian setiap hari (nim 226030100111006)', '2023-12-14 16:26:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4766, 1716, 101539, 'mahasiswa', 'Dwita Aulia Wardoyo', '235070601111012 saya sangat stress nilai saya jelek jelek dan belum menemukan solusi atas permasalahan tersebut', '2023-12-14 16:32:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4767, 1717, 100973, 'mahasiswa', 'Karina Octa Jatmiko', '205030907111011,saat ini saya sedang menempuh semester 7 tepatnya menempuh skripsi,perasaan cemas takut dan gelisah dimulai ketika bulan november hingga saat ini.Sejak SMA saya mulai bisa melihat hal-hal tak kasat mata hingga pada waktu itu karena tidak kuat(gangguan sering datang mulai dari perasaan cemas dan takut) saya putuskan untuk ditutup mata batinnya.sejauh itu saya kembali hidup dengan normal hingga menjelang semester 7 ini gangguan tersebut datang kembali saya sering merasa takut dan gelisah hingga akhirnya saya memutuskan untuk meruqyah diri saya.Setelah itu saya merasa tenang kembali akan tetapi untuk beberapa minggu ini pikiran saya terpenuhi oleh beberapa problem seperti halnya desakan keluarga yang menuntut saya untuk segera menuntaskan kuliah,masalah percintaan dan pengaruh lingkungan yang menyebabkan saya merasa tertekan saya sering gelisah tengah malam dan sering merasa sendiri ditengah keramaian dan merasa minder dengan orang lain.Saya berharap saya bisa mengatasi masalah yang berkaitan dengan diri saya ini Sebelumnya terimakasih dokter  Mohon solusi dan', '2023-12-14 17:34:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4768, 1718, 101541, 'mahasiswa', 'Keisha Shofina Salsabila', 'NIM : 235020101111023 Permasalan : Selamat sore bapak/ibu, jadi saya adalah mahasiswa baru dan mengalami permasalahan akademik yaitu di salah satu mata kuliah saya sempat tidak mengikuti UTS di matkul tersebut karena ada kepenting tes di surabaya dan tidak bisa ditinggalkan. Setelah negoisasi ke dosen, dosen tetap tidak mau melayani susulan atau bentuk lainnya sebagai pengganti. Setelah saya konsul ke akademik juga, akademik mengembalikan hal tersebut kepada keputusan dosen. Saya jadi bingung dan takut akan nilai mata kuliah saya di bidang tersebut jelek karena saya masih mahasiswa baru, dan saya selalu berusaha optimal kuliah dengan sungguh-sungguh karena tahu keadaan finansial keluarga. Alasan saya kemarin memang terdesak tes di surabaya dan tidak bisa ditinggal, terlebih lagi uts tersebut dialaksanakannya sudah diluar jadwal uts jadi 2 - 3 minggu setelah jadwal uts yg seharusnya. Untuk semua tugas di mata kuliah tersebut sangatlah banyak dan saya selalu mengerjaknnya dengan tepat waktu dan selalu mengerjakan. Apakah nanti nilai saya bakal terancam gara" hal terkait? Dan apa solusinya? Karena saya merasa agak kurang adil karena tugasnya selalu sangat banyak dan saya berusaha terus mengerjakan selain itu disaat itu saya juga terdesak untuk tidak bisa ikut ujian. Tapi dari pihak dosen tidak ada toleransi sedikitpun. Terima kasih', '2023-12-14 17:34:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4769, 1719, 100644, 'mahasiswa', 'Luhtitisari Lituhayu', 'Masih beberapa kali ke trigger untuk melakukan self harm sejak tahun 2020 hingga sekarang.', '2023-12-14 18:15:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4770, 1720, 101543, 'mahasiswa', 'Iqmal Irkham Kusworo', '235100107111013 masalah disini lebih condong terhadap ke masalah pribadi saya', '2023-12-14 18:22:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4771, 1721, 101544, 'mahasiswa', 'Rahmat Yoga Pratama', '195040100111068 Saya Mahasiswa Agribisnis angkatan 2019. Untuk masalah akademk selain TA nilai saya selalu bagus (IPK Semester 1-7 = 3.71) saya juga menjadi asisten Praktikum dari semester 2 hingga 7 dan menjadi asisten Dosen di semester 8-9. Saya telah juga menerbitkan Jurnal artikel Shinta 4 sebanyak 3 Judul. Tapi saya masih kesulitan memulai mengerjakan tugas akhir, dan tidak adanya motivasi. Saya ada kecanduan terhadap HP (social media, nonton, porn) sehingga saya mudah terdistraksi.', '2023-12-14 18:43:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4772, 1722, 101545, 'mahasiswa', 'Angelita Nanda Safira', '225110101111010 semenjak masuk perkuliahan selama kurang lebih satu tahun ini saya merasa banyak perubahan dalam diri saya menjadi sering cemas, mudah panik dan merasa perilaku saya sangat aneh. saya tidak bisa menjelaskan melalui kata-kata. mungkin ini semua terjadi karena banyaknya pikiran kesibukan dan tanggung jawab saya. ada banyak hal yang saya pendam sendiri selama ini, mulai dari masalah akademik, kegiatan organisasi /kepanitiaan, perekonomian serta kejadian masa lalu. saya tidak bisa merangkumnya disini. saya sangat bingung harus mulai bercerita darimana, mungkin jika dengan bertemu anda akan dapat melihat perilaku saya secara langsung. saya capek, saya ingin kembali tenang seperti dulu. saya menjadi susah fokus dan mengalami gangguan tidur. hidup saya sangat berantakan, saya rasa ini juga berpengaruh pada kesehatan fisik saya. karena saya menjadi sering pusing, tangan dan kaki berkeringat dingin, jantung berdebar dan perubahan yang paling saya sadari adalah sekarang kedipan mata saya sangat cepat saat saya panik seperti saat mengetik ini, ada banyak juga lainnya yang susah untuk saya jelaskan disini. mungkin sekian yang dapat saya sampaikan, semoga ada hasil yang baik dari ini. terimakasih.', '2023-12-14 19:00:07');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4773, 1723, 100600, 'mahasiswa', 'Felicitia Aulia Rahma', 'NIM = 205110200111023 Saya memiliki gangguan mental dan akhir-akhir lumayan buruk bagi saya karena mempengaruhi keseharian. Saya tidak dapat menentukan jalan kedepan saya dan hanya terus kebingungan.', '2023-12-14 19:02:35');
