INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4814, 1755, 101589, 'mahasiswa', 'Eka Indah Suprapti Ningsih', 'Adik saya menjadi pribadi yg kasar dan suka berbicara tidak baik.. saya ingin sekali membantu mendidiknya tetapi saya udah di tahap cape dan nyerah:( bukan cuma sekali bahkan benerapa kali dia melakukan kekerasan sbnrnya saya sedih cuma gatau hrs melakukan apalagi?', '2023-12-18 16:26:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4815, 1762, 101526, 'mahasiswa', 'Fathiya Rizki Ramadhani', '215030107111056, dari kecil sebenernya sering ngomong sm diri sendiri, tapi dari 2020-2023 sering merasa takut dan cemas untuk sendiri dan tinggalkan, ngerasa unworthy juga, apalagi beberapa lama ini ngerasa didalam diri ada anak kecil yang suka ngomong dan reminder kalo aku itu sendiri, dan sebenernya aku itu capek kesepian, anak kecil di dalam diriku rasanya pengen dikasihani dan dia nujukin perasaan yang sebenernya dari kecil aku rasain tapi aku abain dan pernah memuncak di 2020 dan sempat konsul dengan psikolog juga dan katanya pada saat itu memang terlalu lama memendam luka yang aku simpan sendiri, tapi gatau kenapa sekarang si anak kecil ini sering dateng dan reminder kalo aku itu capek dan sendiri, dia juga kayak ngasih tau kalo aku itu penuh luka yang belum sembuh', '2023-12-18 16:42:11');
