INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4865, 1780, 101613, 'mahasiswa', 'Amirah Zulfa Musyaffa', 'NIM: 195100607111003 Permasalahan: saya pernah mengalami perundungan selama setahun lebih di SMP seperti ujaran kebencian, ancaman, gaslighting, dan dikucilkan. Semenjak itu saya jadi rendah diri, bingung dengan sifat diri sendiri, apatis terhadap lingkungan sekitar, mudah emosional hingga kepala bisa pusing, mudah merasa bersalah, cemas, paranoid dengan orang di sekitar hanya karena hal kecil. Hal ini diperparah setelah bimbingan kuliah dengan dosen yang dikenal killer. Terkadang entah darimana muncul bayangan orang-orang mencemooh saya atau berusaha menjahati saya, sehingga terkadang saya jadi mudah takut dengan orang tanpa alasan yang jelas, dan lebih suka menarik diri dari lingkungan. Saya juga mudah merasa bersalah dan merasa harus mempertahankan situasi sosial agar tidak disalahkan. Hal tsb sangat menghabisan energi saya.', '2023-12-22 12:49:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4866, 1781, 101614, 'mahasiswa', 'Siti Nurhaliza', '205020500111037', '2023-12-22 18:22:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4867, 1782, 101615, 'mahasiswa', 'Ivas salsabilla', '225030219111001 Sering merasa pusing dan sedih saat sedang sendiri, kalau di tempat ramai juga mudah lelah, terkadang hal kecil jadi emosi yang cukup besar', '2023-12-22 18:40:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4868, 1766, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>NIM: 225020107111001, yang saya rasakan sejauh merasa cukup lelah terkait pikiran mental dan hal apa saja, sehingga saya memiliki pemikiran untuk bunuh diri dan saya takut gagal dalam perkuliahan semester ini…</blockquote> <p>Terima kasih Daffa telah menggunakan layanan konseling dan bercerita kondisi saat ini. Apabila saya jadwalkan sesi konseling bersama peer counselor secara online pada Selasa, 26 Desember 2023, apakah berkenan? Jika berkenan, Daffa bersedia jam berapa? Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-22 20:03:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4869, 1745, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>jarak dari daerah saya terlalu jauh dan poli tersebut masih jarang ada. apabila pindah faskes apakah nanti bisa dikembalikan di alamat domisili sebelumnya?</blockquote> <p>Mohon maaf baru membalas. Terkait pindah faskes, biasanya harus mengurus lagi jika ingin pindah lagi ke alamat asal. Seperti itu. Nanti bisa dipertimbangkan lagi saja yaa Alifatus terkait mau pindah faskes atau tidak. Sambil mempertimbangkan hal tersebut, jika saya jadwalkan Alifatus sesi konseling bersama psikolog dosen pada Rabu, 27 Desember 2023 pukul 14.00 WIB secara online melalui Google Meet, apakah bersedia yaa? Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-22 20:21:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4870, 1763, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>saya memerlukan orang asing untuk bercerita, yang mana saya perlu pandangan lain dari orang tersebut. tolong tinjau segera, saya sangat memerlukan. demi tidak terjadi sesuatu yg tidak di inginkan</blockquote> <p>Terima kasih Izzazaki telah menggunakan layanan konseling. Mohon maaf baru membalas karena panjangnya antrian. Jika saya jadwalkan sesi konseling online bersama peer counselor pada Selasa, 26 Desember 2023, apakah berkenan? Jika berkenan, Izzazaki bersedia di jam berapa? Mohon untuk konfirmasinya yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-22 20:26:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4871, 1763, 101596, 'mahasiswa', 'Izzazaki Ilman Albana', 'sebelumnya terimakasih karena telah merespon. Ya, berkenan pada hari selasa, 26 Desember 2023. mungkin pada pukul sekitar 13.30 WIB bagaimana? Terimakasih, Best Regards. Izzazaki Ilman - 085156492928', '2023-12-22 20:36:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4872, 1693, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>205040300111033 Saya kelelahan. Saya sebenarnya mengidap anxiety disorder, depresi dan bipolar. Tapi saya berhenti melakukan pengobatan sejak satu tahun yang lalu. saya pikir saya bisa handle sendiri, tapi lama-lama saya benar-benar hampir menyerah.</blockquote> <p>Terima kasih Syafa telah menggunakan layanan konseling dan bercerita kondisi Syafa saat ini. Mohon maaf baru membalas karena panjangnya antrian. Untuk saat ini jadwal dengan psikiater masih dalam proses. Apabila saya jadwalkan dulu dengan konselor dosen (psikolog) pada Rabu, 27 Desember 2023 pukul 08.00 WIB secara online melalui Google Meet, apakah berkenan? Mohon konfirmasinya yaa.<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-22 20:56:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4873, 1763, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>sebelumnya terimakasih karena telah merespon. Ya, berkenan pada hari selasa, 26 Desember 2023. mungkin pada pukul sekitar 13.30 WIB bagaimana? Terimakasih, Best Regards. Izzazaki Ilman - 085156492928</blockquote> <p>Baik, saya carikan dulu yaa dan segera saya hubungi jika sudah dapat</p>', '2023-12-22 20:57:21');
