INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4884, 1693, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Boleh kak/bu</blockquote> <p>Baik, saya hubungi nanti yaa terkait link google meetnya. Silahkan diisi kedua link yang telah saya kirimkan melalui whatsapp yaa. Terima kasih. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-22 21:42:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4885, 1694, 101216, 'mahasiswa', 'Ahmad Kenzie Aryasatya', 'Untuk Selasa, tanggal 26 Dec 2023 insyaallah fleksibel. Kira-kira kalau dari pihak peer conselour-nya bisa jam berapa?', '2023-12-22 21:44:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4886, 1723, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>NIM = 205110200111023 Saya memiliki gangguan mental dan akhir-akhir lumayan buruk bagi saya karena mempengaruhi keseharian. Saya tidak dapat menentukan jalan kedepan saya dan hanya terus kebingungan.</blockquote> <p>Terima kasih Felicitia telah menggunakan layanan konseling. Mohon maaf baru membalas karena panjangnya antrian. Saya mengerti yang Felicitia rasakan saat ini tidaklah mudah. Jika saya jadwalkan sesi konseling bersama peer counselor pada Rabu, 27 Desember 2023 secara online melalui Google Meet, apakah berkenan? Jika berkenan, Felicitia bersedia jam berapa? Saya jadwalkan dengan peer counselor karena jadwal konselor dosen telah penuh. Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.<br /></p>', '2023-12-22 21:45:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4887, 1696, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Pada tahun 2023 saya cuti karena ada kendala dalam ekonomi yang mengharuskan saya bekerja di Jakarta, untuk melanjutkan kuliah di Malang sudah tidak memungkinkan lagi oleh karena itu saya perlu pindah ke universitas di jakarta untuk melanjutkan pendidikan saya sambil bekerja</blockquote> <p>Terima kasih Yazid telah menggunakan layanan konseling. Mohon maaf baru membalas karena panjangnya antrian. Terkait dengan cara melakukan pindah universitas, bisa Yazid tanyakan dulu mekanismenya di pihak fakultas karena biasanya kebijakan setiap fakultas akan berbeda. Bisa ditanyakan kepada pihak akademik. Terima kasih. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-22 21:51:46');
