INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4889, 1783, 101388, 'mahasiswa', 'Laksmita Chandrawardhani', 'Masih permasalahan yang sama tentang perundungan, ingin bertemu konselor lagi, karena atas saran dari konselor (kak jihan) untuk bertanya terkait masalah perundungan yang saya alami, setelah saya memberikan kuisioner hasilnya bagus semua, sehingga saya tetap tidak mendapatkan jawaban atas masalah saya.', '2023-12-22 22:24:37');
