INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4891, 1745, 101577, 'mahasiswa', 'Alifatus Sholikhah', 'mohon maaf saya tidak bersedia. sepertinya saya akan mencari konsultasi ditempat lain saja. terima kasih atas bantuannya', '2023-12-22 23:01:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4892, 1697, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Saya merasa telah dilecehkan dengan photo editing AI yang melibatkan wajah saya serta pengambilan video tanpa seizin saya</blockquote> <p>Terima kasih telah menggunakan layanan konseling dan bercerita keresahan Keira saat ini. Mohon maaf baru membalas karena panjangnya antrian. Terkait kejadian yang kurang mengenakkan ini, apa yang Keira butuhkan saat ini? <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-23 07:04:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4893, 1754, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>216150100111012 hallo, mungkin permasalahan saya tidak terlalu berat tapi hal yg sering saya alami adalah selalu pengen menghilang, bukan melarikan diri dari kewajiban tapi saya punya pikiran yang auto think ketika permasalahan datang , ataupun kekhawatiran dengan hal yg belum tentu terjadi :) kerap merasa down dan ini akan mendukung pikiran untuk segera menghilang</blockquote> <p>Terima kasih Fachrizal telah menggunakan layanan konseling dan bercerita kondisi saat ini. Mohon maaf baru membalas karena panjangnya antrian. Saya mengerti posisi Fachrizal saat ini sulit untuk mengendalikan pikiran untuk menghilang disaat ada kewajiban. Supaya lebih nyaman ceritanya, kalau saja jadwalkan sesi konseling online bersama peer counselor melalui Google Meet pada Rabu, 27 Desember 2023, apakah berkenan? Jika berkenan, bersedia di jam berapa yaa? Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-23 07:08:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4894, 1698, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>195150207111017 saya melakukan pengerjaan skripsi sejak semester 7, dan sekarang saya berada di semester 9. Saya berharap ini menjadi semester terakhir dan lulus. Saya juga sudah berusaha untuk mengerjakan skripsi ini setiap hari selama 1 tahun kebelakang. Tetapi tidak kunjung selesai. Kemarin saya melakukan bimbingan skripsi yang saya harap menjadi satu langkah lagi menuju seminar hasil. Tetapi justru saya mendapatkan masalah disana, kata pembimbing saya apa yang telah saya kerjakan ternyata salah semua, dan secara eksplisit mengaju pertanyaan-pertanyaan yang menyuruh saya mengulang di semester depan. Sekarang saya bingung untuk membenarkan yang salah, karena belum terlalu paham untuk mengerjakannya, di sisi lain saya sudah merasa panik karena takut tidak bisa menyelesaikannya pada semester ini.</blockquote> <p>Terima kasih Nur Laili telah menggunakan layanan konseling dan bercerita kondisi saat ini. Mohon maaf baru membalas karena panjangnya antrian. Saya mengerti yang Nur rasakan saat ini tidaklah mudah, ketika ingin maju semhas dan sudah selesai, ternyata dosen pembimbing tidak menyetujui. Supaya lebih nyaman ceritanya, apabila saya jadwalkan sesi konseling online Rabu, 27 Desember 2023 bersama peer counselor melalui Google Meet, apakah berkenan? Jika berkenan, Nur Laili bersedia jam berapa? Mohon segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-23 07:21:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4895, 1699, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>NIM 235020407111022 Saya terkendala dengan perasaan selalu tidak puas dengan hidup saya, serta terkendala dengan kecemasan berlebih saya terhadap permasalahan permasalahan yang sebenarnya belum tentu terjadi, terkadang saya selalu mencari jalan keluar pintas untuk merasa senang atau merasakan sesuatu secara sesaat saja Hal ini yang membuat kehidupan saya baik secara sosial maupun akademik tergganggu Saya bingung dengan alasan saya seperti ini, dan saya ingin menemukan solusi atas permasalahan saya</blockquote> <p>Terima kasih Nicholas telah menggunakan layanan konseling dan bercerita kondisi saat ini. Mohon maaf baru membalas karena panjangnya antrian. Saya mengerti yang dirasakan Nicholas saat ini tidak mudah karena memiliki kecemasan atas hal yang belum terjadi. Supaya lebih nyaman ceritanya, kalau saya jadwalkan sesi konseling online bersama peer counselor pada Kamis, 28 Desember 2023 melalui Google Meet, apakah berkenan? Jika berkenan, bersedia di jam berapa yaa? Mohon untuk segera konfirmasi. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-23 07:26:01');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4896, 1700, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Nama: Muhammad Arkoun NIM: 205060100111020 Persiapan Koas, Nilai Mandek, Kesulitan Belajar</blockquote> <p>Terima kasih Arkoun telah menggunakan layanan konseling. Mohon maaf baru membalas karena panjangnya antrian. Boleh diceritakan lebih banyak kondisi saat ini Arkoun seperti apa? Lalu, kegiatan apa saja yang telah Arkoun lakukan untuk mengatasi kesulitan belajar ataupun nilai mandek tersebut? <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-23 07:28:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4897, 1784, 101616, 'mahasiswa', 'Alfa Rizky', '185010119111001', '2023-12-23 07:31:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4898, 1701, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>233141507111004 Saya manusia biasa yang sehat, ceria, positif, aktif di kelas. Setelah saya gagal dalam hubungan saya sebelumnya karena saya merasa dicurangi, saya berusaha bangkit di hubungan yang baru. Trauma dan trust issue muncul setelah saya memulai hubungan baru. Saya bingung, saya takut, saya harus bagaimana, Sikap pasangan saya membuat saya bingung dalam bertindak, sehingga tak jarang membuat saya merasa kebingungan dalam keseharian. Saya tidak yakin dia masih menginginkan saya atau tidak, tapi saya merasa tidak berharga dan kecewa. Saya sangat menyayangi pasangan saya, apapun rela saya lakukan, tapi untuk saat ini saya hanya menangisi apa yang saya terima Saya menangis berlarut larut dalam perasaan saya sendiri. Saya kehilangan diri saya, saya kehilangan kewarasan saya, Itu semua mengganggu produktivitas sehari hari saya, saya sekarang menjadi pribadi yang murung cenderung pendiam dan pasif . Bukan keinginan saya, tapi kepala saya terlalu berisik</blockquote> <p>Terima kasih Arbi telah menggunakan layanan konseling dan bercerita kondisi saat ini. Mohon maaf baru membalas karena panjangnya antrian. Saya mengerti yang Arbi rasakan saat ini tidaklah mudah karena pengalaman masa lalu yang masih terbawa hingga saat ini. Supaya lebih nyaman ceritanya, jika saya jadwalkan sesi konseling online bersama peer counselor melalui Google Meet pada Kamis, 28 Desember 2023, apakah berkenan? Jika berkenan, Arbi bersedia di jam berapa? Mohon untuk segera konfirmasi yaa.<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-23 07:32:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4899, 1697, 101515, 'mahasiswa', 'Keira Latifa Virgie', 'sejauh ini saya merasa self-esteem saya drop dan kurang pede untuk menunjukkan foto saya di sosial media manapun. Saya merasa seperti objek di mata orang-orang. saya juga bingung apa yang saya butuhkan untuk menangani hal ini', '2023-12-23 09:43:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4900, 1785, 101618, 'mahasiswa', 'Shafira Azzahra Shafa', '205030107111004. Sebagai mahasiswa semester akhir dengan diagnosa seperti ini saya ingin hendak ke psikiater untuk bertanya mengenai mental health saya selama di malang nanti', '2023-12-23 10:47:01');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4901, 1786, 101619, 'mahasiswa', 'Azka Faris Fadhilah', '225901001111020, saya merasa bahwa hidup yang saya jalani cukup keras dan capek. Sehingga, sayapun berperilaku keras ke pada siapapun yang akhirnya malah menghancurkan seluruh yang ingin saya kasihani', '2023-12-23 11:56:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4902, 1787, 101620, 'mahasiswa', 'Dian Ayu Rahmawati', 'Assalamualaikum wr.wb Perkenalkan saya Dian Ayu Rahmawati dengan nim 205150201111042. Saya mahasiswa tingkat akhir dari prodi teknik informatika fakultas ilmu komputer. disini saya mengharapkan kesediaan Bapak/Ibu untuk saya wawancari terkait topik skripsi saya yaitu mengenai gangguan kecemasan yang menimpa mahasiswa. besar harapan saya Bapak/Ibu bersedia. terima kasih', '2023-12-23 12:44:24');
