INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4904, 1745, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>mohon maaf saya tidak bersedia. sepertinya saya akan mencari konsultasi ditempat lain saja. terima kasih atas bantuannya</blockquote> <p>Baik kalau begitu. Terima kasih atas konfirmasinya. Semoga bisa segera mendapatkan bantuan yaa.<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-23 17:17:08');
