INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4906, 1719, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Masih beberapa kali ke trigger untuk melakukan self harm sejak tahun 2020 hingga sekarang.</blockquote> <p>Terima kasih Luhtitisari telah menggunakan layanan konseling. Mohon maaf baru membalas karena panjangnya antrian. Saya mengerti yang dirasakan Luhtitisari saat ini tidaklah mudah. Apabila saya jadwalkan sesi konseling online pada Rabu, 27 Desember 2023 pukul 14.00 WIB bersama Ibu Wira melalui Google Meet, apakah berkenan? Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-23 17:20:07');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4907, 1708, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>225110707111011 saya lelah dengan hidup, saya ingin hidup serba berkecukupan dan meninggalkan hal hal buruk yang bisa merugikan saya.</blockquote> <p>Terima kasih Emerita telah menggunakan layanan konseling. Mohon maaf baru membalas karena panjangnya antrian. Saya mengerti yang sedang dialami Emerita saat ini tentu tidak mudah yaa. Kalau boleh saya tanya, bagaimana perasaan Emerita saat ini? Supaya lebih nyaman ngobrolnya, jika saya jadwalkan sesi konseling online bersama peer counselor pada Selasa, 26 Desember 2023 melalui Google Meet, apakah berkenan? Jika berkenan, bersedia di jam berapa? Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-23 17:24:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4908, 1719, 100644, 'mahasiswa', 'Luhtitisari Lituhayu', 'Baik, saya berkenan untuk mengikuti sesi konseling online pada Rabu, 27 Desember 2023 pukul 14.00 bersama Ibu Wira.', '2023-12-23 17:46:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4909, 1719, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Baik, saya berkenan untuk mengikuti sesi konseling online pada Rabu, 27 Desember 2023 pukul 14.00 bersama Ibu Wira. </blockquote> <p>Baik, terima kasih atas jawabannya. Senin nanti saya kirim link Google Meetnya yaa. Kita lanjutkan di whatsapp</p>', '2023-12-23 18:30:26');
