INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4916, 1534, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Baik jika begitu, ditunggu informasi selanjutnya. Terima kasih</blockquote> <p>Sama-sama. Informasi selanjutnya akan dikabarkan melalui whatsapp yaa. </p>', '2023-12-23 19:05:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4917, 1732, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>205050101111012. saya rasa bahwa saya bukan tipe pengambil keputusan, justru saya lebih memiliki sudut pandang netral yang melihat suatu hal dari berbagai sudut pandang. Hal ini membuat saya lelah mental karena saya tidak tau harus berbuat apa dalam hal mengekspresikan diri. saya khawatir akan kehilangan identitas jati diri saya apabila saya terus seperti ini.</blockquote> <p>Terima kasih Izdihar telah menggunakan layanan konseling dan bercerita kondisi saat ini. Mohon maaf baru membalas karena panjanganya antrian. Saya mengerti keresahan yang dialami oleh Izdihar saat ini tidaklah mudah. Izdihar berada dalam situasi, yang Izdihar sendiri tidak tahu keputusan yang tepat jika diharuskan mengambil keputusan sampai menguras energi. Apabila saya jadwalkan sesi konseling online bersama peer counselor pada Kamis, 28 Desember 2023 melalui Google Meet, apakah berkenan? Jika berkenan, Izdihar bersedia di jam berapa? Nanti saya coba carikan peer counselor yang available. Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-23 19:10:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4918, 1708, 101529, 'mahasiswa', 'Emerita Maya', 'Terimakasih atas informasinya. Apabila konseling online dilakukan pada hari selasa saya bisa, apabila jam 10.00 bagaimana yaa? Ditunggu konfirmasinya, terimakasih.', '2023-12-23 19:11:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4919, 1731, 101559, 'mahasiswa', 'Andini Laily Putri', '<p>Telah terjawab di  e-ticket sebelumnya</p>', '2023-12-23 19:11:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4920, 1708, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Terimakasih atas informasinya. Apabila konseling online dilakukan pada hari selasa saya bisa, apabila jam 10.00 bagaimana yaa? Ditunggu konfirmasinya, terimakasih. </blockquote> <p>Baik, saya usahakan dulu yaa dan segera saya kabari jika sudah dapat peer counselornya. Nanti akan saya hubungi melalui Whatsapp. Terima kasih. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-23 19:13:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4921, 1703, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>NIM: 236080117111003, saya merupakan mahasiswa fast track yang saat ini sedang penelitian tesis, permasalahan yang saya hadapi sekarang dimulai pertengahan bulan November dimana saya dikeluarkan secara tiba-tiba dari tim penelitian dosen pembimbing saya, dimaki-maki oleh beliau di depan umum, dan saya harus melakukan penelitian dengan biaya sendiri sedangkan kondisi keuangan keluarga saya sedang kurang baik. Saya takut kalau saya gugur fast track</blockquote> <p>Terima kasih Kharisma telah menggunakan layanan konseling dan bercerita kondisi saat ini. Mohon maaf baru membalas karena panjangnya antrian. Saya mengerti yang Kharisma alami saat ini tidaklah mudah. Takut gugur fasttrack, kemudian dicaci maki oleh dosen pembimbing, kondisi ekonomi juga sedang kurang baik. Kalau boleh saya tanya beberapa hal,<br />1. Hal apa yang telah terjadi sebelumnya sampai dosen pembimbing mengeluarkan Kharisma dari tim penelitian?<br />2. Sudah pernah dikomunikasikan masalah ini dengan dosen pembimbing akademik? Atau DPA dengan DP penelitian adalah orang yang sama?<br />3. Bagaimana perasaan Kharisma saat ini? Sudah pernah cerita masalah ini dengan orang terdekat? <br />4. Apa yang Kharisma butuhkan saat ini?<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-23 19:45:29');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4922, 1704, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>216150100111001. Di semester akhir ini semakin merasa banyak tekanan apalagi dari orang tua yang selalu menyuruh cepat lulus tanpa mengetahui bagaimana anaknya berusaha. Merasa tidak ada yang membantu mengerjakan tesis termasuk dosen pembimbing karena segala halnya harus mencari tahu sendiri sehingga hilang arah untuk mengerjakan tesis ditambah lagi merasa takut kepada orang tua dikarenakan uang yang digunakan untuk mengikuti presentasi jurnal internasional ditolak ketika saya mengajukan pengembalian dana. Dikarenakan bingung harus bagaimana sehingga sering sekali dan hampir setiap hari selalu emosi, marah besar dengan memukul kepala sendiri, menggigit tangan, memukulkan benda-benda ke tubuh sendiri. Sering sekali merasa ingin bunuh diri tapi sadar kalau belum punya bekal untuk di akhirat dan saya pobia darah serta takut ketinggian.</blockquote> <p>Terima kasih Nisrina telah menggunakan layanan konseling. Mohon maaf baru membalas karena panjangnya antrian. Saya mengerti yang dialami oleh Nisrina saat ini tidaklah mudah. Berbagai tekanan datang dari banyak pihak, mulai dari orang tua, dosen dan pihak penyelenggara conference. Supaya lebih nyaman ceritanya, kalau saya jadwalkan sesi konseling online bersama peer counselor melalui Google Meet pada Selasa, 26 Desember 2023, apakah berkenan? Jika berkenan, Nisrina bersedia di jam berapa yaa? Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-23 19:50:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4923, 1705, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>NIM : 21511030711107 Masalahnya saya tuh punya pengalaman buruk di dunia atlet saya sama pas dikampus.</blockquote> <p>Terima kasih Trulli telah menggunakan layanan konseling. Mohon maaf baru membalas karena panjangnya antrian. Boleh diceritakan lebih banyak pengalaman buruk yang dimaksud seperti apa yaa? <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-23 19:53:05');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4924, 1704, 101524, 'mahasiswa', 'Nisrina Arintia Maghfiroh', 'Terima kasih bu, untuk sesi konseling diawal bulan Januari apakah bisa bu? Kebetulan saya tanggal 26 sedang perjalanan ke luar kota', '2023-12-23 19:56:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4925, 1706, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>saya Salsabila, dengan NIM 225110101111005 fakultas ilmu budaya, sastra inggris 2022. semenjak memasuki semester 3, entah kenapa saya seringkali merasa stres dan kehilangan alasan saya untuk hidup. seperti banyak sekali hal-hal yang bersarang di otak saya, tapi saya sendiri tidak tau hal-hal yang membuat penuh otak itu apa saja. saya hanya merasa stres, tertekan, sakit, tidak ada semangat bahkan untuk mengikuti kelas, yang kadang sering saya takutkan akan berdampak pada nilai akademik saya. terlebih saya anak beasiswa kipk, sudah menjadi tanggung jawab saya untuk terus meningkatkan prestasi akademik yang saya miliki. tapi untuk bisa di titik itu, saya yang tidak sanggup. rasanya seperti sudah tidak kuat, tapi tetap saya jalani. saya tidak punya alasan bertahan, tapi saya hanya melanjutkan hidup, seperti itu rasanya.</blockquote> <p>Terima kasih Salsabila telah menggunakan layanan konseling dan bercerita kondisi saat ini. Mohon maaf baru membalas karena panjangnya antrian. Saya mengerti yang Salsabila alami saat ini tidaklah mudah. Berada pada situasi yang tidak tahu apa yang menjadi alasannya, banyak hal yang ada di dalam otak, kalau boleh dibilang berisik gitu yaa otaknya. Tapi Salsabila sadar harus tetap melanjutkan kuliah karena tanggung jawab sebagai mahasiswa dan penerima KIPK. Supaya lebih nyaman ceritanya, jika saya jadwalkan sesi konseling online bersama peer counselor melalui Google Meet pada Kamis, 28 Desember 2023, apakah berkenan? Jika berkenan, Salsabila bersedia di jam berapa? Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-23 19:57:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4926, 1704, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Terima kasih bu, untuk sesi konseling diawal bulan Januari apakah bisa bu? Kebetulan saya tanggal 26 sedang perjalanan ke luar kota</blockquote> <p>Baik, kalau begitu awal januari tanggal berapa yaa berkenannya?</p>', '2023-12-23 19:59:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4927, 1709, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>165060707111008 Saya sempat cuti 1 taun diperkuliahan dan baru aktif kuliah kembali semester ini yang dimana saya harus menyelesaikan beberapa matkul yang tersisa bersamaan dengan skripsi + magang, namun saya tidak bisa fokus untuk mengerjakan semuanya sekaligus jadi saya untuk saat ini cuma bisa fokus ke kuliah dan mengabaikan dua lagi. Berbarengan dengan kuliah ini, saya juga bekerja freelance karena diumur yang tidak lagi muda ini untuk menghasilkan penghasilan tambahan. Alasan saya cuti kuliah dahulu adalah karena trauma yang pernah saya alami saat saya pernah menjalani hubungan dengan mantan pacar saya yang dimana dia melakukan pelecehan pada saya dan bertempat di kampus, saya tidak pernah cerita ke siapa siapa karena takut dan merasa diri saya rendah, bahkan sampai saat ini rasa trauma tsb belum hilang dan menyebabkan fokus saya pecah dan rasa sangat takut ke kampus dan lebih memilih menghindar dan mengabaikan semuanya. Disisi lain, saya juga ingin cepat lulus tapi waktu yang ada tinggal sedikit lagi, apakah kira - kira solusi yang bisa saya lakukan untuk ini?</blockquote> <p>Terima kasih Nadira telah menggunakan layanan konseling dan bercerita apa yang telah terjadi. Mohon maaf baru membalas karena panjangnya antrian. Saya mengerti yang Nadira alami saat ini tidaklah mudah. Nadira harus segera menyelesaikan kuliah, tapi tidak bisa fokus karena adanya trauma masa lalu yang terjadi di area kampus. Nadira juga akhirnya takut untuk ke kampus karena trauma tersebut. Ada satu hal yang ingin saya tanyakan, Nadira pernah tidak cerita terkait permasalahan lain (selain trauma dengan mantan) dengan orang terdekat? Kalau pernah, setelah cerita perasaannya bagaimana? Kalau misalnya Nadira belum pernah cerita ke siapa-siapa, lalu bagaimana cara Nadira bisa melepaskan emosi yang dipendam Nadira selama ini terkait dengan trauma tersebut?<br /><br />Hal tersebut kemungkinan akan memberikan efek yang berbeda pada Nadira jika bersedia membagi keresahan atau trauma yang dialami dengan orang lain. Sedikit demi sedikit diri Nadira akan merasa "oh orang-orang peduli ke aku ternyata" dan tidak merasa takut lagi ketika berada di kampus. Kalau tidak diceritakan, emosi atau pengalaman trauma tersebut akan terus memenuhi Nadira. Bisa juga tidak dengan cerita, misalnya dengan menggambar abstrak atau menulis. Tergantung dari cara masing-masing individu dalam mengeluarkan emosi negatif yang dirasakan. <br /><br />Salam hangat,<br />Tim Konseling UB.<br /></p>', '2023-12-23 20:10:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4928, 1706, 101525, 'mahasiswa', 'Salsabila Nur Firdausi', 'Haloo kak, selamat malam. Terima kasih atas balasannyaa. Begini kak, sebenarnya saya berkenan. Tapi sekarang saya sudah pulang kampung, yang otomatis ada ayah di sini. Jujur, saya nggak sanggup kalau harus nangis atau ketahuan sedih di depan ayah. Karena saya sendiri juga tau, ayah pasti akan bereaksi negatif dan berbalik mengatakan saya terlalu lemah. Sekiranya jika dibolehkan, saya ingin sesi konseling secara chat terlebih dahulu. Saya lebih bisa terbuka lewat chat, daripada tatap muka atau video call, dan saya sendiri nggak tau kenapa seperti itu. Sekali lagi terima kasih, karena sudah menampung keluh kesah saya yang tidak bisa saya sampaikan ke orang-orang sekitar saya. May you always be happy everyday!', '2023-12-23 20:11:26');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4929, 1741, 101572, 'mahasiswa', 'Andini Laily Putri', '<p>Mengirimkan 2x</p>', '2023-12-23 20:11:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4930, 1706, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Haloo kak, selamat malam. Terima kasih atas balasannyaa. Begini kak, sebenarnya saya berkenan. Tapi sekarang saya sudah pulang kampung, yang otomatis ada ayah di sini. Jujur, saya nggak sanggup kalau harus nangis atau ketahuan sedih di depan ayah. Karena saya sendiri juga tau, ayah pasti akan bereaksi negatif dan berbalik mengatakan saya terlalu lemah. Sekiranya jika dibolehkan, saya ingin sesi konseling secara chat terlebih dahulu. Saya lebih bisa terbuka lewat chat, daripada tatap muka atau video call, dan saya sendiri nggak tau kenapa seperti itu. Sekali lagi terima kasih, karena sudah menampung keluh kesah saya yang tidak bisa saya sampaikan ke orang-orang sekitar saya. May you always be happy everyday!</blockquote> <p>Baik, terima atas jawabannya. Saya mengerti yaa kalau ada sosok dekat (ayah) yang tahu titik terlemah kita dan kurang paham posisi kita akan susah menerimanya. Baik, secara chat yaa, nanti saya izin membagikan nomor Salsabila ke peer counselor yang bersedia yaa. Kemudian, komunikasi kita akan dilanjut melalui whatsapp call center yaa supaya lebih mudah. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-23 20:21:17');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4931, 1706, 101525, 'mahasiswa', 'Salsabila Nur Firdausi', 'Baik, kak. Sekali lagi terima kasih banyak atas bantuannya. Semoga dengan ini saya bisa lebih mengerti kondisi saya sendiri dan jadi lebih baik ke depannya. Terima kasiiih', '2023-12-23 20:24:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4932, 1710, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Mungkin bisa langsung aja ke poinnya, jadi aku akhir-akhir ini lagi ada masalah, dan seringkali hal itu membuat aku tiba-tiba badmood, jadi aku sebelumnya deket sama perempuan, yang mana dia udah janji buat ketemu, udah ngerencanain buat healing dll, tapi tiba2 dia hilang tanpa kabar udah seminggu dari sekarang, dan waktunya ga tepat banget, karena pas ada uas, aku takut masalah ini jadi berimbas ke akademik aku huhu, tiap hari aku juga ga mood ngelakuin apapun sampe nunda belajar, kadang juga ngerasa kesepian, apakah ada saran terkait masalah ini? Terima kasih sebelumnya, mungkin untuk lebih detailnya, bisa aku jelaskan lewat chat nantinya.</blockquote> <p>Terima kasih Fian telah menggunakan layanan konseling dan bercerita kondisi Fian. Mohon maaf baru membalas karena panjangnya antrian. Saya mengerti kondisi Fian tidaklah mudah karena badmood yang diakibatkan oleh teman perempuan, jadinya berpengaruh ke akademik (UAS). Meskipun ini sudah lewat pekan UAS, kalau saya jadwalkan sesi konseling online bersama peer counselor pada Jumat, 29 Desember 2023 melalui Google Meet, apakah berkenan? Jika berkenan, Fian bersedia jam berapa? Nanti saya carikan yang available. Mohon segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB. </p>', '2023-12-23 20:26:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4933, 1711, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>NIM: 235010100111093 Permasalahan saya tidak separah mungkin kasus teman-teman yang lain, tapi saya selalu menutupi kepribadian asli saya agar orang lain tidak menggaggap saya nyebelin, dan kadang saya tidak enakan jika menolak teman dan memberi batasan yang jelas, jujur saya sangat capek namun susah sekali untuk merubah hal ini. Karena masalah ini pun saya merasa bahwa saya tidak punya teman yang benar benar kenal saya dan itu membuat saya cukup terpukul…</blockquote> <p>Terima kasih Deeadra telah menggunakan layanan konseling dan bercerita kondisi saat ini. Mohon maaf baru membalas karena panjangnya antrian. Saya mengerti posisi Deeadra sebagai people pleaser kepada orang-orang sekitar membuat kesulitan sendiri tapi kalau tidak seperti itu, malah tidak punya teman. Supaya lebih nyaman ceritanya, kalau saya jadwalkan sesi konseling online bersama peer counselor pada Jumat, 29 Desember 2023 melalui Google Meet, apakah berkenan? Jika berkenan, Deeadra bersedia jam berapa? Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-23 20:31:26');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4934, 1704, 101524, 'mahasiswa', 'Nisrina Arintia Maghfiroh', 'Bagaimana jika tanggal 3 Januari bu?', '2023-12-24 06:57:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4935, 1788, 101151, 'mahasiswa', 'Salma Hanandifa Aflanda', 'NIM : 225061101111015 Halo ibu bapak konselor, perkenalkan nama saya Salma Hanandifa Aflanda, baru-baru ini saya sempat ada masalah terkait akademik saya sehingga membuat saya depresi. Awalnya dimulai dari semester 2, dimana saya pada waktu itu mulai keteteran terhadap akademik, dikarenakan dengan jadwal yang super padat, ditambah dengan kepanitiaan serta organisasi juga, serta terdapat forum-forum dari fakultas maupun departmen dari siang sampe malam. Saya tidak menyalahkan itu namun sepertinya dulu time management saya cukup buruk. disitu jujur, saya jarang belajar, tugas apapun itu saya hanya menyalin pekerjaan dari teman, pokonya cukup buruk waktu semester 2 itu. Sehingga waktu ujian, saya tidak percaya diri meskipun saya sudah belajar, dan saya rasa kurang maksimal. Waktu itu ada di salah satu matkul yang dimana ketentuan Ujiannya Close Book, saya dengan sengaja membawa catatan saya dan saya taruh dibelakang kertas ujian saya sembari saya mengerjakan, saat pengawas ujian keliling, beliau mengambil kertas saya, dan kalau boleh jujur sekali saya belum sempat melihat catatan saya saat saya mengerjakan ujian, saat beliau mengambil, jujur perasaan saya sangat cemas sekali, saya lakukan aju banding dengan dosen dan minta ujian lagi dan usaha saya tidak digubris, tak lama buka gapura nilai saya E, itu memang resiko yang saya dapatkan, rasanya sakit sekali. Bertahun-tahun saya sekolah, selalu mendapat image baik dari orang” lalu mendapatkan masalah seperti itu. Waktu itu saya sangat depresi sampai seminggu lebih mengurung di kamar. Setelah itu saya punya keputusan kalo saya mau berubah. Saya mulai bangkit dari keterpurukan itu, saya mulai belajar pada saat liburan semester sebelum semester 3, tiba waktunya saat pengambilan KRS. saya tidak bisa ambil full sks 24, dikarenakan ip saya yang sangat turun drastis dari semester 1. dari 3,86 sampai ke kepala 2, saya cuma bisa ambil 18 sks untuk semester 3, sangat berat buat menerima keputusan itu. Saya belajar, hingga di semester 3 ini saya memaksimalkan sebaik mungkin, saya juga tidak menyontek sama sekali, tapi rasa trauma itu masih muncul, hingga kadang membuat rasa cemas yang berkepanjangan ketika saya mau membuka nilai pada gapura, karena kecemasan berlebihan itu membuat saya melupakan makan dan aktivitas yang lain. Saya sangat takut sekali nilai saya jelek dan tidak bisa ambil full sks. Taruhan antara saya lulus tepat waktu atau tidak, dan semester kedepannya yang membutuhkan persyaratan IPK, sks dan lain sebagainya yang membuat saya khawatir di nilai semester ini. Sebenernya banyak juga, seperti nilai uts yang sudah beberapa dibagikan dan nilainya masih jelek, saya takut, sudah seminggu lebih saya seperti ini. Tolong kasih saya advice saya harus gimana :(', '2023-12-24 07:49:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4936, 1746, 101578, 'mahasiswa', 'Diah Kartika Wulandari', 'Saya bersedia kak. Apakah bisa antara tgl 25-26. Jam nya saya mengikuti konselor', '2023-12-24 14:43:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4937, 1704, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Bagaimana jika tanggal 3 Januari bu? </blockquote> <p>Baik kalau begitu, tanggal 3 Januari yaa. Untuk jam dan dengan siapa, mendekati hari pelaksanaan akan saya hubungi lagi yaa melalui Whatsapp. Terima kasih. Hati-hati selama perjalanan yaa. Selamat liburan natal dan tahun baru 2024. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-24 16:22:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4938, 1712, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>205010107111039 Tidak fokus dalam satu hal dan cenderung meninggalkan semua pekerjaan saat di bawah tekanan</blockquote> <p>Terima kasih Cassandra telah menggunakan layanan konseling. Mohon maaf baru membalas karena panjanganya antrian. Saya mengerti posisi Cassandra saat ini tidak mudah karena banyaknya tekanan membuat tidak fokus. Kalau boleh saya ingin menanyakan beberapa hal,<br />1. Bagaimana perasaan Cassandra saat ini?<br />2. Tekanan yang dimaksud seperti apa?<br />3. Apakah Cassandra sudah pernah menceritakan hal ini kepada orang terdekat? <br />4. Apa saja yang telah dilakukan Cassandra selama ini untuk mengatasi ketidakfokusan tersebut?<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-24 16:27:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4939, 1713, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>225020407111030 permasalahan saya adalah ipk saya kecil grgr saya sibuk magang, bukan magang kampus merdeka melainkan magang sendiri, saya sangat suka di bidang yang saya geluti (diluar jurusan saya) dan saya lebih suka praktek &gt; teori, tapi grgr itu ipk saya jadi kecil, saya bingung, saya berpikir ingin cari kerja full time sebelum skripsi atau pas sudah lulus ya, tapi kalau cuma pikiran kerja kapan akademiknya selesai, saya ngerasa gapernah beruntung soal akademik punya ipk 2 rasanya di cap bodoh dan memunculkan pikiran di orang "kok bisa?" sebenernya itu keteledoran saya yang sebenernya saya gak seperti itu, saya ga pernah menyalahkan dosen atau magang saya krn keputusan yang saya ambil cukup baik krn di semester 2 sy udh punya pengalaman real dlm dunia praktikal dan ini sudah ditetapkan tuhan, sekarang bagaimana carany saya perbaiki ini semua yaa, terima kasih </blockquote> <p>Terima kasih Aldina telah menggunakan layanan konseling dan bercerita kondisi saat ini. Mohon maaf baru membalas karena panjanganya antrian. Saya paham, bahwa memang dunia kerja atau after life campus akan sangat berbeda ketika kita berada di kampus, apalagi mencari kerja. Saya ikut senang kalau Aldina sudah mempersiapkan diri untuk menghadapi dunia nyata setelah lulus. Namun, adakalanya memang kita harus benar-benar mempertimbangkan segala keputusan dan konsekuensi dari keputusan tersebut, yaitu magang sambil kuliah. Saya mau tanya beberapa hal,<br />1. Aldina ngerasa gk pernah beruntung soal akademik dengan IPK 2 itu karena diri Aldina sendiri atau karena pandangan orang lain?<br />2. Apa ketakutan terbesar Aldina saat ini jika dikaitkan dengan status Aldina sebagai mahasiswa?<br />3. Pernah membuat skala prioritas? Kalau pernah, kuliah masuk prioritas keberapa dan magang masuk ke prioritas berapa?<br />Kemudian, cara memperbaikinya tentu di semester selanjutnya yaa dengan memiliki manajemen waktu yang baik. Ada banyak cara manajemen waktu, salah satunya menggunakan tools seperti google calender atau apk pendukung lainnya.<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-24 16:36:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4940, 1756, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>225120201111009 - saya lelah, lelah sekali. malam ini rasanya ingin menangis sudah tidak bisa. padahal pelarian saya ketika lelah ya menangis dan self harm. malam ini menangis pun sudah tidak bisa, dan berujung self harm. tangan kiri saya sudah penuh bekas luka padahal sebenarnya saya tidak ingin menambahnya lagi. tapi keadaan memaksakan saya untuk melakukan itu terus menerus. belum ada sebulan ini saya sudah melukai tangan saya sebanyak 3 kali, yang terakhir malam ini. saya merasa tidak ada yang mengerti, peduli dan bahkan sayang kepada saya, saya pun demikian. lalu buat apa saya hidup? saya hidup untuk siapa? saya sampe saat ini masih mencari jawabanya. saya lelah tapi saya takut jika ingin mengakhiri hidup. kadang terlintas ingin melakukan tapi saya belum cukup siap untuk menerima siksa neraka, terlalu takut untuk menghilangkan nyawa diri saya sendiri dan terutama orang tua saya adalah alasan saya bertahan. tapi saya lelah sekali, ternyata berat menjadi saya yang harus memaksakan diri untuk tetap bertahan melalui berbagai masalah yang ada padahal sebenarnya saya tidak cukup kuat untuk menghadapi semuanya. tidak ada yang paham keadaan saya, saya pun binggung dengan saya sendiri. saya seperti kehilangan arah untuk hidup. tapi upaya bertahan hanya menjadi sebuah formalitas bagi saya.</blockquote> <p>Terima kasih Rosita telah menggunakan layanan konseling dan bercerita kondisi saat ini. Mohon maaf sekali baru membalas karena panjangnya antrian. Saya mengerti pasti yang telah dilalui Rosita selama ini berat dan orang sekitar tidak ada yang peka. Jika saya jadwalkan sesi konseling online besok bersama peer counselor melalui Google Meet, apakah berkenan? Jika berkenan, Rosita bersedia di jam berapa? Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.<br /></p>', '2023-12-24 16:40:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4941, 1736, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Nim saya 205150300111037 Saya didiagnonisi Bipolar dan BPD, sehingga perlu terapi obat Quetvell. Mood saya sering berantakan, dan saya sangat mudah marah, sehingga hal tersebut menganggu hubungan sosial saya dengan pasangan saya. Hubungan saya dengan pasangan sudah di ujung tanduk, saya sering bertengkar krn hal sepele, saya bertengkar dengan dia karena overthinking keterlibatan pihak ke-3 dalam hubungan kami. Dari kejadian pertengkaran itu (14/12) hingga sekarang, otak saya selalu memikirkan itu dan selalu overthinking hingga sakit kepala dan vertigo ringan. Saya ingin tidak memikirkan itu. Dosis quetvell saya adalah 200mg sekali minum di malam hari untuk membantu saya tidur juga, saya ingin meminumnya siang ini agar saya tidur kembali dan tidak memikirkan apapun, namun itu akan melebihi dosis dari dokter. Apa yang harus saya lakukan sekarang, saya sangat butuh bantuan agar tidak seperti ini, karena ketika saya overthinking, saya akan self harm seperti menyayat tangan namun tidak berniat bunuh diri.</blockquote> <p>Terima kasih Winy telah menggunakan layanan konseling dan bercerita kondisi saat ini. Mohon maaf baru membalas karena panjangnya antrian. Saya mengerti posisi Winy saat ini tidak mudah dengan adanya permasalahan bersama pasangan yang akhirnya mengganggu kehidupan Winy yang lainnya. Kalau boleh saya ingi bertanya beberapa hal,<br />1. Winy sudah mengonsulkan hal ini dengan psikiater yang menangani Winy? Sebab kemungkinan akan diberikan treatment yang berbeda<br />2. Sudah pernah menceritakan masalah ini dengan orang terdekat Winy (orang tua/sahabaat)?<br />3. Kalau saya jadwalkan sesi konseling online bersama peer counselor untuk tempat cerita melalui Google Meet, apakah berkenan? Jika berkenan, Winy bersedia kapan dan jam berapa? <br /><br />Salam hangat,<br />Tim Konseling UB.  </p>', '2023-12-24 17:02:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4942, 1714, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>193140414111028 Saya merasa bahwa diri saya tidak pernah di sayang oleh kedua orang tua, keluarga besar dan pasangan semenjak orang tua saya bercerai, bahkan yang terbaru jika kelak suatu saat saya lulus dari UB bapak saya tidak mau hadir di acara wisuda dengan alasan malas.</blockquote> <p>Terima kasih Aburizal telah menggunakan layanan konseling. Mohon maaf baru membalas karena panjanganya antrian. Saya mengerti yang dirasakan Aburizal saat ini tidak mudah, orang terdekat seperti orang tua yang harusnya bisa memberikan kasih sayang dan perhatian pada anaknya. Ada beberapa hal yang ingin saya tanyakan,<br />1. Aburizal merasa tidak pernah disayang orang tua sejak kapan? Sudah pernah cerita ke orang tua perasaan atau keinginan Aburizal seperti apa?<br />2. Bagaimana perasaan Aburizal saat ini?<br />3. Tidak pernah disayang oleh pasangan itu yang dimaksud Aburizal seperti apa? <br />4. Aburizal punya teman dekat selain pasangan (sahabat)? Pernah menceritakan permasalahan ini ke dia?<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-24 17:25:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4943, 1707, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><br /><blockquote>205030900111020, semenjak saya berhenti minum obat tidur saya seperti terkena sleep paralyze dan hampir tiap hari sangat menganggu saya</blockquote> <p>Terima kasih Alifia telah menggunakan layanan konseling. Mohon maaf baru membalas karena panjangnya antrian. Saya informasikan bahwa untuk saat ini jadwal psikiater kami saat ini masih penuh dan untuk ada laginya kapan, kami masih belum berkoordinasi lagi dengan pihak terkait. Gejala yang dialami oleh Alifia baiknya diperiksakan ke psikiater, kalau Alifia mendatangi faskes terdekat seperti RSSA, apakah berkenan? Jika kesulitan, nanti kami bantu dampingi. Kemudian, supaya biaya yang dikeluarkan bisa lebih sedikit, apakah Alifia punya BPJS? Itu bisa digunakan tapi memang harus pindah faskes dulu di Malang. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-24 17:31:07');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4944, 1715, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>akhir-akhir ini saya merasa tidak punya semangat hidup, selalu overthinking dan tidak punya tenaga untuk melakukan apapun, saya merasa kesepian setiap hari (nim 226030100111006)</blockquote> <p>Terima kasih Natan telah menggunakan layanan konseling. Mohon maaf baru membalas karena panjangnya antrian. Saya mengerti yang Natan rasakan saat ini tidak mudah. Kalau boleh saya ingin bertanya beberapa hal,<br />1. Bagaimana perasaan Natan saat ini?<br />2. Apa yang telah mentrigger atau memicu Natan sampai bisa dititik saat ini? Sebab Natan bilang, "akhir-akhir ini"<br />3. Natan pernah cerita masalah ini ke orang terdekat (contoh: orang tua atau sahabat)?<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-24 17:34:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4945, 1715, 101538, 'mahasiswa', 'Natan Parasila', '1. perasaan saya kacau, bingung dan gak tau lakuin apapun, 2. perkuliahan, masalah keluarga, percintaan 3. aku pendam sendiri', '2023-12-24 17:36:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4946, 1716, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>235070601111012 saya sangat stress nilai saya jelek jelek dan belum menemukan solusi atas permasalahan tersebut</blockquote> <p>Terima kasih Dwita telah menggunakan layanan konseling. Mohon maaf baru membalas karena panjangnya antrian. Saya paham, posisi Dwita saat ini tidak mudah, padahal sudah bekerja keras untuk belajar tapi hasilnya tidak sesuai yang diharapkan. Supaya lebih nyaman ceritanya, kalau saya jadwalkan sesi konseling online bersama peer counselor melalui Google Meet pada Jumat, 29 Desember 2023, apakah berkenan? Jika berkenan, bersedia di jam berapa? Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-24 17:37:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4947, 1715, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>1. perasaan saya kacau, bingung dan gak tau lakuin apapun, 2. perkuliahan, masalah keluarga, percintaan 3. aku pendam sendiri</blockquote> <p>Baik, terima kasih sudah menjawab pertanyaan saya. Supaya lebih nyaman ngobrolnya, kalau saya jadwalkan sesi konseling online bersama peer counselor pada Jumat, 29 Desember 2023, apakah berkenan? Jika berkenan, Natan bersedia jam berapa? Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-24 17:40:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4948, 1733, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>235010101111042. Assalamu''alaikum, saya M. Dhiyaa Habarkal Latief dari FH 23''. Saya ditinggalkan oleh ibu saya pada 23 Oktober 2023 lalu. Sejak saat itu, saya jujur kehilangan arah dan kekurangan motivasi. Rasa rindu yang berat akan ibu juga terkadang membuat saya terdiam dan malas untuk melakukan apapun. Rasanya hampa dan kesepian.</blockquote> <p>Terima kasih Dhiyaa telah menggunakan layanan konseling dan bercerita kondisi saat ini. Mohon maaf baru membalas karena panjanganya antrian. Saya turu berduka cita atas meninggalnya Ibunda tercinta dari Dhiyaa. Saya mengerti, pasti berat ditinggal oleh sosok yang sangat kita sayangi dan dekat dengan diri kita. Supaya lebih nyaman ngobrolnya, jika saya jadwalkan sesi konseling online bersama peer counselor pada Kamis, 28 Desember 2023 melalui Google Meet, apakah berkenan? Jika berkenan, Dhiyaa bersedia di jam berapa? Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-24 17:44:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4949, 1730, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>205010101111036 ( saya mahasiswa semester 7 yang saat ini tengah mengerjakan skripsi. Salah satu masalah yg menghantui saya adalah, setelah saya lulus kuliah apakah saya bisa mendapatkan pekerjaan yang sesuai dengan gelar saya. Saya berfikir, sulit untuk fresh graduate mendapatkan pekerjaan, akan tetapi saya setelah lulus berorientasi segera mendapatkan pekerjaan yang layak karena saya anak pertama dari 4 bersaudara. Adik adik saya masih sekolah dan kuliah, sedangkan kondisi keuangan keluarga saya tidak stabil. Kecemasan itu selalu menghantui saya, ketakutan menjadi sarjana yg gagal selalu muncul di pikiran saya. Akhir akhir ini saya selalu merasa takut, kesepian, dan cemas memikirkan masa depan saya. Saya tidak bisa menceritakan masalah ini kepada keluarga saya, karena saya anak broken home dan apapun masalah yang saya hadapi selama ini tidak pernah melakukan konsultasi dan curhat kepada orang tua saya. Saya takut kecemasan saya ini akan menganggu skripsi saya dan mengganggu mental saya kedepannya.</blockquote> <p>Terima kasih Aura telah menggunakan layanan konseling dan bercerita kondisi saat ini. Mohon maaf baru membalas karena panjangnya antrian. Saya mengerti ketakutan Aura sebagai mahasiswa akhir yang memikirkan nasib setelah lulus dengan kondisi keluarga yang kurang pas untuk dijadikan tempat cerita. Supaya lebih nyaman ceritanya, apabila saya jadwalkan sesi konseling online bersama peer counselor pada Selasa, 2 Januari 2024 melalui Google Meet, apakah berkenan? Jika berkenan, Aura bersedia jam berapa? Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-24 18:09:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4950, 1701, 101518, 'mahasiswa', 'Ryaminto arbi', 'Hi kak, terimakasih sudah membalas pesan saya, untuk hari kamis, tanggal 28 Desember saya kebetulan ada free time antara sore - malam hari, karena konseling dilakukan by google meet apakah bisa kalau dimulai pukul 19.00 ?', '2023-12-24 18:50:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4951, 1701, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Hi kak, terimakasih sudah membalas pesan saya, untuk hari kamis, tanggal 28 Desember saya kebetulan ada free time antara sore - malam hari, karena konseling dilakukan by google meet apakah bisa kalau dimulai pukul 19.00 ?</blockquote> <p>Baik, terima kasih atas jawabannya. Saya carikan dulu yaa di jam 19.00 WIB. Silahkan diisi dulu 2 link yang telah saya kirimkan melalui Whatsapp yaa dan segera saya hubungi jika sudah dapat peer counselor yang available. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2023-12-24 18:52:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4952, 1701, 101518, 'mahasiswa', 'Ryaminto arbi', 'Hi kak, terimakasih sudah membalas pesan saya, untuk hari kamis, tanggal 28 Desember saya kebetulan ada free time antara sore - malam hari, karena konseling dilakukan by google meet apakah bisa kalau dimulai pukul 19.00 ?', '2023-12-24 18:53:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4953, 1736, 101567, 'mahasiswa', 'Winy Ainia', 'Terima kasih, saya ijin menjawab Sebenarnya masalah saya juga sampe mengganggu akademik saya 2 semester (6 dan 7 ini) hingga membuat nilai saya merosot jauh bahkan ada mata kuliah yang tidak lulus. 1. Saya belum mengonsultasikan masalah pasangan dengan psiliater saya, saya telat kontrol. 2. Saya sudah menceritakan ke teman dekat dan kakak kandung, saran dari mereka memang saya harus mendatangi psikolog dan psikiater 3. Saya berkenan, untuk kapan dan jam berapa saya mengikuti saya tidak apa apa. Kalau bisa diambilkan jadwal tercepat karena saya benar2 membutuhkan konsultasi ini. Terima kasih banyak', '2023-12-24 21:00:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4954, 1786, 1, 'admin', 'Andini Laily Putri', '<p>Bisakah Azka Ceritakan pengalaman-pengalaman yang menyebabkan Azka menjadi pribadi yang keras sehingga Azka berperilaku keras juga kapada orang yang Azka kasihi?</p>', '2023-12-24 22:06:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4955, 1779, 1, 'admin', 'Andini Laily Putri', '<p>Halo Nurul, terkait dengan permasalahan yang Nurul alami. Apakah bisa diceritakan lebih lanjut mengenai perasaan ketakutan yang nurul alami. Nurul dapat menceritakan terkait penyebab, perasaan ketakutan seperti apa yang nurul alami dan dampak dari perasaan tersebut kepada nurul secara pribadi ataupun (jika ada) dampak pada orang disekitar Nurul. </p> <p><br /></p> <p>Salam hangat,<br /></p> <p>Tim Konseling UB</p>', '2023-12-24 22:11:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4956, 1778, 1, 'admin', 'Andini Laily Putri', '<p>Halo Fitri<br />Sebelumnya mengapa Fitri merasa tidak cukup pintar? apakah Fitri bisa menceritakan bagaimana kemampuan Fitri secara akademik dan bagaimana standar dari dosen pembimbing Fitri?</p> <p>Lalu seberapa sering juga Fitri melakukan bimbingan skripsi dengan dosen pembimbing?</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2023-12-24 22:26:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4957, 1773, 1, 'admin', 'Andini Laily Putri', '<p>Halo Wari,<br />Sebelumnya apakah bisa diceritakan, saat ini Wari menjadi ketua di organisasi/kepanitiaan/kegiatan apa?<br />Selain itu, apakah Wari mengetahui apa yang menyebabkan orang-orang disekitar memberikan stigma negatif tersebut kepada Wari?</p> <p>Kemudian gangguan di kehidupan sehari-hari seperti apa yang terjadi akibat stigma tersebut?</p> <p><br />Salam hangat,</p> <p>Tim Konseling UB</p>', '2023-12-24 22:32:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4958, 1771, 1, 'admin', 'Andini Laily Putri', '<p>Halo Ananda<br />Apakah bisa diceritakan lebih lanjut mengenai perasaan insecure yang menyebabkan kecemasan tersebut?<br />Ananda bisa menceritakan kepada kamu mengenai penyebab timbulnya insecurity, perasaan yang Ananda rasakan dan dampak akibat perasaan Ananda tersebut </p> <p><br /></p> <p>Salam Hangat</p> <p>Tim Konseling UB</p>', '2023-12-24 22:36:07');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4959, 1694, 101216, 'mahasiswa', 'Ahmad Kenzie Aryasatya', 'okayy', '2023-12-25 10:31:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4960, 1782, 1, 'admin', 'Andini Laily Putri', '<p>Halo Ivas</p> <p>Apakah bisa Ivas ceritakan lebih lanjut rasa pusing seperti apa yang Ivas rasakan?<br />Kemudian apakah bisa dideskripsikan mengapa Ivas merasa sedih saat sendiri, sementara merasa lelah apabila berada di keramaian?<br />Tolong juga ceritakan contoh kejadian kecil yang membuat Ivas merasa emosi.<br /><br />Salam Hangat,</p> <p><br /></p> <p>Tim Konseling UB</p>', '2023-12-25 13:17:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4961, 1788, 1, 'admin', 'Andini Laily Putri', '<p>Halo Salma,<br />Saya mengerti apa yang Salma rasakan dan alami tidaklah mudah. Namun, sebelumnya apakah Salma sudah pernah membicarakan terkait masalah ini dengan Dosen pembimbing akademik? <br />Karena ini terkait dengan masalah akademik, ada baiknya untuk dibicarakan dengan dosen pembimbing akademik selaku orang tua Salma di Kampus. Apabila sudah dibicarakan dan Salma tetap merasakan cemas, maka nanti akan kami jadwalkan untuk melakukan konseling secara Online dengan konselor atau peer counselor kami.<br /><br />Salam hangat,</p> <p>Tim Konseling UB</p>', '2023-12-25 13:24:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4962, 1775, 1, 'admin', 'Andini Laily Putri', '<p>Halo Achmad,</p> <p>Apakah bisa diceritakan pressure dari lingkungan mana saja yang Achmad rasakan? misal dari lingkungan pertemanan, organisasi, keluarga atau yang lainnya?</p> <p>Perasaan tidak ada yang membantu apakah hanya perasaan Achmad saja atau memang seperti itu yang terjadi? Jika memang tidak ada yang membantu ahmad, bisa diceritakan contoh kejadiannya seperti apa<br />Perasaan kesendirian yang Achmad rasakan ketika menghadapi masalah apakah disebabkan karena tidak ada yang membantu?<br />atau karena Achmad tidak meminta bantuan orang lain ketika sedang menghadapi masalah?</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2023-12-25 13:32:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4963, 1777, 1, 'admin', 'Andini Laily Putri', '<p>Halo Gema,<br />Mohon maaf baru membalas karena panjangnya antrian.<br />Terkait dengan permasalahan Gema, apakah bisa diceritakan apakah penyebab Gema menjadi kurang termotivasi.<br />Selain itu, adakah sesuatu hal yang menyebabkan Gema sering menghidari memikirkan masalah-masalah yang dialami?</p> <p>Lalu bisakah Gema ceritakan apa dampak dari demotivasi dan penghindaran memikirkan masalah yang Gema alami (dampak pada diri sendiri dan orang lain)</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB<br /></p>', '2023-12-25 13:47:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (4964, 1788, 101151, 'mahasiswa', 'Salma Hanandifa Aflanda', 'Saya akan berkonsultasi dengan dosen PA sewaktu itu, tapi tetap sama saja, masih ada rasa cemas sampai sekarang. apakah bisa dijadwalkan untuk konsultasi langsung secara online?', '2023-12-25 14:40:41');
