INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5073, 1739, 1, 'admin', 'Nora Silvana', '<p>Baik kalau begitu. Berhubung saat ini sedang dalam periode libur semester, jika konselingnya diadakan secara online via gmeet apakah tidak apa-apa yaa? Kemudian, Anda bersedia konseling di tanggal dan jam berapa?</p>', '2023-12-31 13:44:43');
