INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5085, 1761, 1, 'admin', 'Nora Silvana', '<p>Berhubung saat ini libur semester, maka semua konseling akan dilaksanakan secara online (gmeet) saja yaa. Untuk konseling offline baru bisa dilaksanakan saat periode kuliah semester genap nanti dimulai. Kira-kira apakah Anda ingin konseling secara online atau nanti menunggu saat sudah dibuka kembali secara offline yaa?</p>', '2023-12-31 19:26:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5086, 1748, 1, 'admin', 'Nora Silvana', '<p>Berhubung saat ini libur semester, maka semua konseling akan dilaksanakan secara online (gmeet) saja yaa. Untuk konseling offline baru bisa dilaksanakan saat periode kuliah semester genap nanti dimulai. Kira-kira apakah Anda ingin konseling secara online atau nanti menunggu saat sudah dibuka kembali secara offline yaa?</p>', '2023-12-31 19:26:48');
