INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5114, 1803, 101351, 'mahasiswa', 'Laila Lilik Puspitasari', '185090307111002 Tidak ada perkembangan diri, tidak ada motivasi, selalu menunda-nunda, takut akan masa depan, takut untuk maju, bingung terhadap diri sendiri, karena masalah eksternal diri selalu melakukan pelarian yang malah menghambat proses untuk masa depan.', '2024-01-03 12:37:09');
