INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5142, 1811, 101648, 'mahasiswa', 'Nova Ismi Faricha', 'NIM saya 175040207111073 Masalah yg saya alami cukup kompleks ya, mulai dari pendemo yg menyebabkan saya pulkam, kakek nenek yg sakit yg menyebabkan skripsi saya ketinggalan, akhir" ini masalah ibu bapak yg tidak akur. Semua jadi satu yg membuat mental saya hancur. Skripsi saya ga kelar", rasanya cape banget,, Ngerasa tertinggal, ngerasa gapunya temen, ngerasa hidup ga berpihak sama sekali sama saya. Ada perasaan ingin mengakhiri hidup karena cape, cape banget. Gaada temen cerita, ortu gada yg peduli bahkan saudara sendiri.', '2024-01-06 05:07:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5143, 1762, 1, 'admin', 'Nora Silvana', '<p>Mohon maaf baru merespons. Setelah ditanyakan, peer counselornya berhalangan konseling hari ini jam 10. Kalau konselingnya dilaksanakan besok Minggu, 7 Januari pukul 13.00 WIB bagaimana yaa?</p>', '2024-01-06 09:41:27');
