INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5225, 1806, 101644, 'mahasiswa', 'Sjariefah Jasmine Hidajat', 'Apa tidak bisa dilakukan secara offline ya? karena situasi didalam rumah tidak mendukung, tetapi jika memang harus online apa bisa dijadwalkan terlebih dahulu?', '2024-01-11 15:15:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5226, 1803, 1, 'admin', 'Nora Silvana', '<p>Saya izin konfirmasi kembali, apakah Anda bersedia untuk melakukan konseling online (gmeet) dengan peer counselor kami? Kalau bersedia, Anda bisa konseling tanggal dan jam berapa yaa?</p>', '2024-01-11 17:37:55');
