INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5244, 1825, 101659, 'mahasiswa', 'Zaidan Fadhal Arifin', 'Berikut saya lampirkan link docs kronologi peristiwa pelecehan seksual yang saya alami : https://docs.google.com/document/d/1adBtS9Xi9CzUn0bWSMU0mZPHOpmTQkZLUNVN9VW8wFE/edit?usp=sharing', '2024-01-12 12:12:05');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5245, 1826, 101659, 'mahasiswa', 'Zaidan Fadhal Arifin', 'Mahasiswa luar UB, yang pelaku kekerasan nya adalah pacarnya anak FH UB. Pihak laki-laki tidak bertanggung jawab soal kehamilan dan justru memanipulasi pihak perempuan secara psikologis.', '2024-01-12 12:14:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5246, 1827, 101660, 'mahasiswa', 'Nining Pambudi Astuti// reff satgas ppks', 'Nining Pambudi Astuti, FTP, teror online dari mantan pacar dan mantannya mantan pacar dengan pengancaman memviralkan nama penyintas. Sudah pernah konseling dengan Satgas PPKS, sehingga sesi2 berikutnya merupakan konseling lanjutan', '2024-01-12 16:12:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5247, 1828, 101661, 'mahasiswa', 'Dianny Andhira', 'Halo, saya Dianny Andhira mahasiswa Sosiologi angkatan 2020 yang beberapa waktu lalu menjalani sidang komprehensif. Setelah sidang, pikiran dan mental saya cukup terganggu karena merasa kurang puas atas hasil kerja saya sendiri.', '2024-01-13 01:58:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5248, 1829, 101662, 'mahasiswa', 'Noval kurnia saputra', '235050100111119 setiap hari keluarga saya brantem masalah ekonomi dan saya bingung mau cari uang buat kuliah bagaimana saya punya kip dan kemarin di tolak waktu pendaftaran saya sudah mencari freelance sana sini akan tetapi tidak cukup buat biaya kuliah saya, terkadang saya inging menyerah dan memilih untuk bekerja karena tidak sanggup untuk membayar kuliah meski saya dapet golongan ukt 1 saya merasa membebani org tua saya karena keadaan ekonomi keluarga saya yg sangat kurang akan tetapi saya juga masih ingin melanjutkan pendidikan ini hingga lulus agar bisa mengangkat derajat kedua orang tua saya', '2024-01-13 11:36:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5249, 1806, 1, 'admin', 'Nora Silvana', '<p>Baik, kira-kira Anda bisa konseling di tanggal dan jam berapa yaa (hari kerja)? Supaya kami carikan peer counselor yang available.</p>', '2024-01-13 15:17:19');
