INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5329, 1783, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Baik, akan kami jadwalkan setelah kuliah kembali dimulai ya. Kami akan informasikan kembali mengenai penjadwalan ini</p>', '2024-01-22 18:05:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5330, 1785, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Mohon maaf atas keterlambatan dalam menjawab. Apabila kami jadwalkan terlebih dahulu dengan psikolog kami, apakah Anda bersedia? Untuk konseling dengan psikolog klinis kami paling dekat ada pada tanggal 31 Februari secara online. </p>', '2024-01-22 18:08:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5331, 1789, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Mohon maaf atas keterlambatan dalam menjawab. Oleh karena pendampingan yang dapat kami berikan hanyalah pendampingan psikologis, apakah sebelumnya pernah mencari bantuan hukum?</p>', '2024-01-22 18:09:52');
