INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5333, 1798, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Mohon maaf atas keterlambatan dalam menjawab. Apakah Anda bersedia saya jadwalkan secara luring dengan konselor kami pada tanggal 2 Februari?</p>', '2024-01-22 18:12:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5334, 1785, 101618, 'mahasiswa', 'Shafira Azzahra Shafa', 'Baik Bu Tasya. Mengenai mekanisme nya nanti apakah by WA atau google meet ya Bu? Apakah konseling ub dikenakan biaya?', '2024-01-22 18:13:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5335, 1823, 101658, 'mahasiswa', 'Tasya Rahmani Puspa Pertiwi', '<p>Sudah dijadwalkan konseling</p>', '2024-01-22 18:14:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5336, 1828, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Mohon maaf atas keterlambatan dalam menjawab. Bagaimana kondisi Anda saat ini? </p> <p>Berdasarkan apa yang Anda ceritakan, hal tersebut sangatlah wajar. Adanya berbagai emosi yang Anda rasakan di saat yang bersamaan membuat Anda merasa gelisah. Satu hal yang perlu kita pahami adalah tidak semua hal bisa kita kendalikan, salah satunya respons orang lain. Untuk memudahkan Anda menghadapi kondisi saat ini, pastikan hal tersebut tidak terjadi hingga terus menerus dan memberhentikan Anda untuk berfungsi secara normal ya. Berikut beberapa hal yang dapat saya sarankan:</p> <p>1. Fokus untuk mengendalikan apa yang dapat dikendalikan saat ini. Saya memahami bahwa rasanya tidak menyenangkan sekali menghadapi kondisi kemarin. Akan tetapi, hal tersebut cukup dijadikan pembelajaran dan penguatan untuk menikmati hidup di hari ini.</p> <p>2. Lakukan hobi dan hal-hal yang disukai. Apakah Anda memiliki hal yang Anda sukai? Sudah berapa lama Anda tidak melakukan kegiatan tersebut? Melakukan hobi bisa membantu Anda keluar dari perasaan gelisah terus menerus yang Anda rasakan.</p> <p>3. Kelilingi diri Anda dengan orang-orang dan lingkungan yang positif sehingga dapat membantu Anda untuk mengalihkan perasaan dan pengalaman yang tidak menyenangkan, serta menggantikannya dengan hal-hal positif.</p>', '2024-01-22 18:22:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5337, 1830, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Oleh karena belum adanya respons yang Anda berikan, silakan ceritakan apapun yang ingin Anda ceritakan kapanpun Anda bersedia ya. Kami akan berusaha untuk membantu Anda :)</p>', '2024-01-22 18:24:06');
