INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5349, 1844, 101679, 'mahasiswa', 'Novitri Putri Teriza', '235090501111014 Saya memiliki keluhan jika memiliki pikiran mengenai suatu hal (bukan hal berat saja contohnya memikirkan mengenai biaya kuliah, teman kuliah, dan apakah saya bisa menyelesaikan kuliah dengan baik ) saya langsung merasa cemas dan gelisah serta ingin menangis, kadang juga tidak ada masalah muncul rasa cemas dan seperti banyak yg dipikirkan. Sampai kadang pusing dan dada berdebar². Selain itu sering merasa sendiri padahal banyak org di sekitar, waktu sedang ngobrol dengan orang lain tidak berani untuk lihat matanya, dan mudah tertidur padahal tidak terlalu lelah. Kira² itu kenapa dan bagaimana cara mengatasinya? Terima kasih', '2024-01-23 12:19:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5350, 1844, 101679, 'mahasiswa', 'Novitri Putri Teriza', 'Saya memiliki keluhan jika memiliki pikiran mengenai suatu hal (bukan hal berat saja contohnya memikirkan mengenai biaya kuliah, teman kuliah, dan apakah saya bisa menyelesaikan kuliah dengan baik ) saya langsung merasa cemas dan gelisah serta ingin menangis, kadang juga tidak ada masalah muncul rasa cemas dan seperti banyak yg dipikirkan. Sampai kadang pusing dan dada berdebar². Selain itu sering merasa sendiri padahal banyak org di sekitar, waktu sedang ngobrol dengan orang lain tidak berani untuk lihat matanya, dan mudah tertidur padahal tidak terlalu lelah. Kira² itu kenapa dan bagaimana cara mengatasinya? Terima kasih', '2024-01-23 12:22:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5351, 1845, 101680, 'mahasiswa', 'Haura Fatmah Arikah', '(235120500111001) saya merasa trauma saat di SMP pernah di bully dan di rumah ortu saya termasuk yg sulit untuk diajak bercerita tanpa menjudge, saya sering di kekang dan secara tidak langsung selalu di dorong untuk berprestasi tp mereka tdk pernah mengapresiasi proses saya, hanya hasilnya saja. saat saya mencoba mengekspresikan diri mama saya sering tidak sadar menyepelekan &amp; masih kuno dalam menilai, saat saya salah akan di kurung tidak boleh keluar rumah. saya sering menyakiti diri untuk melampiaskan kecewa yang saya rasa, sesak &amp; tercekat', '2024-01-23 19:06:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5352, 1846, 101681, 'mahasiswa', 'MUHAMMAD KHAFIDUL FIKRI', 'memang awalnya saya menemaninya karena merasa kasihan tidak ada yang dekat dengan dia tapi makin kesini dia sering bergantung informasi bahkan menyepam wa dan sosmed saya sehingga asaya merasa terganggu dan risih selain itu saat bertemu langsung dia juga suka membuat saya tidak nyaman dia sering mengeluh dan it membuat saya terdistract karena energi negatifnya. saya sudah berkali-kali mengingatkan agar tidak melakukan hal yanng mebuat saya tidak nyaman namun dia malah playingvictim mengalihkan topik dan idak pernah berubah. agar takhir-akhir ini saya sudah mencoba membatasi diri dengan hanya menjawab singkat chatnya dan membalas jika ada pertanyaan saja kalau tidak ada yang penting untuk dijawab saya tidak mebalasanya tetapi dia malah menyepam lagi', '2024-01-24 10:47:17');
