INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5411, 1873, 101709, 'mahasiswa', 'Lia Rizka Pratiwi', 'NIM saya 175010107111183. Saya sejak pandemi menarik diri dari kegiatan akademik dan memilih cuti atau menghilang sehingga saya sangat telat lulus. Saya berpikir apakah bisa saya menyelesaikan studi saya atau apakah saya lebih baik mengundurkan diri saja? Terimakasih.', '2024-02-06 14:35:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5412, 1874, 101710, 'mahasiswa', 'Violeta Naurah Zafira Saeladifa', 'Saya Violeta Naurah (235120300111007) , Saya kerap kali kesulitan mengatasi permasalahan yang saya hadapi, seringkali melakukan hal yang sebaliknya dari yang ingin saya lakukan, sehingga perlahan saya merasa sendirian dan kurang percaya diri untuk menghadapi masalah', '2024-02-06 20:41:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5413, 1875, 101711, 'mahasiswa', 'Nada Nazihah Hanif', '195090207111030 Kehilangan minat untuk melakukan sesuatu , perasaan tidak ingin menjadi orang yang berguna agar orang berharap pada ku. Merasa ingin kabur dan tidak terlihat. Terkadang merasa cemas untuk hal yang belum terjadi kecemasan yang tidak perlu tapi membuat perut mual kadang otot pugung tegang atau kadang pusing. Aku tidak percaya diri dan merasa kehadiranku tidak perlu. Penyakitku dermatitis atopik akut hal yang paling aku benci sangat benci. Banyak pemicu membuat penyakitku kambuh, terutama saat mood turun pasti tubuh ku gatal... Aku nggak suka dengan suara orang yang berbicara dengan nada yang tinggi atau nada marah rasanya berisik dan sumpek. Aku ingin tidur nyenyak dimalam hari aku mau malam yang tenang tanpa rasa gatal ,sakit dan tegang . aku mau mandi tanpa rasa perih dan sakit dan nggak mau mengalami ketakutan setiap mau mandi. Rasanya aku mau mati rasa saja.. Aku merasa canggung dengan orang tua ku... Aku tau kalau mereka peduli dan juga apa yang mereka katakan benar.. tapi aku merasa mereka hanya bisa memaksakan nya tanpa tau perasaan pada posisiku , agar untuk sembuh harus menahan semuanya gak perlu takut.. tapi rasa takut ku juga besar ayah ibu ..', '2024-02-07 01:12:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5414, 1876, 101698, 'mahasiswa', 'Jaka rahman', '- Terjadi penolakan dalam melakukan sesuatu dengan cara menunda-nunda seolah-olah ada halangan besar sehingga progress pengerjaan skripsi tidak berjalan lancar. - Tidak bisa tidur di waktu malam meskipun sudah ngantuk, kecuali waktu siang - Kecemasan mendadak ketika melakukan sesuatu sehingga mengurungkan niat dalam melakukan kegiatan', '2024-02-07 12:20:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5415, 1877, 101712, 'mahasiswa', 'Muchamad Rizky Caesar', '165010101111231 Saya adalah alumni fh ub angkatan 2016 Masalah yg saya alami awalnya terkait dgn keluarga, saya berasa keluarga saya ini sangat2 disfungsional, tidak kondusif, dan berantakan Saya ga memiliki tempat utk pulang lgi Skrng saya bingung, hidup saya berasa udh hancur krna keluarga ini Saya blm dpt kerja, utang dimana2, keluarga tidak ada yg bantu sdikitpun, dan mereka memaksa saya utk hrus cepat dpt kerja Saya sudah berusaha lamar kemana2 tp blm dpt juga Kehidupan kuliah saya juga ancur berantakan, saya lulus 7 tahun dgn sia2 Skrng saya ga tau hidup mengarah kemana Andaikan mati itu ga dosa, mngkin sudah saya lakuin Saya sudah capek hidup Tidak ada yg pduli dgn saya juga', '2024-02-07 18:34:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5416, 1878, 101256, 'mahasiswa', 'Amalia Ramadhaniyah Adhie Dwi Putri', '225110800111001 Akhir-akhir ini sering merasa cemas karena dihantui ketakutan akan kematian. Cemasnya sudah sampai panic attack dan insomnia. Saya juga ingin melanjutkan konseling lanjutan dengan Ibu Bona.', '2024-02-08 10:48:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5417, 1879, 101713, 'mahasiswa', 'sheila nur sakha', '215060607111026, saya susah tidur karena terlalu banyak yang saya pikirkan dan saya menangis terus, saya memiliki masalah keluarga dan sosial dsn itu sangat menganggu saya, saya merasa sendirian dan tidak ada siapapun yang mau menolong saya dan mendengarkan cerita saya, saya benar benar tidak tahu lagi harus meminta bantuan kepada siapa', '2024-02-08 18:30:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5418, 1880, 101714, 'mahasiswa', 'Ahmad Dani Saputra', '205060200111017 saya ingin konsultasi tentang kepribadain buruk saya seperti berbohong yang selalu merugikan saya dan bagaimana cara mengatasinya', '2024-02-09 02:41:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5419, 1881, 101715, 'mahasiswa', 'Ja''far Umar', '236090100111011 Saya seringkali tidak bisa menerima suatu kegagalan, dan itu membuat rutinitas saya kacau dan berantakan. Saya jatuhnya bermalas2an dan memanjakan kegagalan itu, padahal ada hal yg harus saya kejar. ditambah overthinking memikirkan tekanan dosen pembimbing dan tuntutan beasiswa membuat saya hilang asa dan takut merakit kembali rencana dan harapan.', '2024-02-10 06:36:04');
