INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5422, 1884, 101315, 'mahasiswa', 'Agatha Herma Putra', 'NIM : 23314070011111, Permasalahan yang saya hadapi yaitu saya dengan panik membuat orang tua susah dengan saya tertipu oleh oknum mengatasnamakan BRI dan saya membuat uang orang tua saya Hilang 2jt disini saya merasa bersalah karena tertipu dan saya tidak berani untuk pulang kerumah dan rasa ingin bunuh diri karena malu dan juga takut dengan orang tua saya juga tidak bisa belajar karena ini', '2024-02-12 04:50:00');
