INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5505, 1866, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>216010100141006 Saya sudah semester 6 pada jenjang Magister ilmu hukum, pada semester 4 bahkan saya tidak pernah bimbingan penyebabnya berasal dari diri saya sendiri, saya sering menunda-nunda mengerjakan tesis dan sering ter trigger hal-hal yang sebenarnya saya sadari bukan sebuah prioritas. Pembimbing akademik saya sudah sangat baik dan membimbing dengan baik tapi karena hal ini saya sudah terlambat dan sering kali merasa takut memulai karena sering berpikir hal tersebut terlalu sulit dan banyak memikirkan kemungkinan-kemungkinan buruk hingga saya tidak punya progress, dan sering kali menyalakan diri sendiri karena hal tersebut.</blockquote> <p>Terima kasih Faisyah telah menggunakan layanan konseling. Mohon maaf baru membalas karena libur semester. Saya mengerti perasaan Faisyah saat ini merasa bersalah karena tidak ada progres terkait thesis. Supaya lebih nyaman ceritanya, apabila saya jadwalkan sesi konseling online bersama peer counselor, apakah berkenan? Jika berkenan, Faisyah bersedia kapan dan jam berapa? Nantinya akan saya carikan peer counselor yang available. Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2024-02-18 19:09:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5506, 1866, 101700, 'mahasiswa', 'Nur Faisyah', 'Saya sangat berkenan untuk waktunya saya mengikut pada kesediaan counselor', '2024-02-18 19:13:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5507, 1863, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>225030201111032, permasalahan kekurangan yang ada pada diri saya yang mempengaruhi keseharian saya</blockquote> <p>Terima kasih Wafidzin telah menggunakan layanan konseling. Mohon maaf baru membalas karena libur semester. Boleh saya tahu, kekurangan yang dimaksud oleh Wafidzin seperti apa?<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2024-02-18 19:17:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5508, 1874, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Saya Violeta Naurah (235120300111007) , Saya kerap kali kesulitan mengatasi permasalahan yang saya hadapi, seringkali melakukan hal yang sebaliknya dari yang ingin saya lakukan, sehingga perlahan saya merasa sendirian dan kurang percaya diri untuk menghadapi masalah</blockquote> <p>Terima kasih Violeta telah menggunakan layanan konseling. Mohon maaf baru membalas karena libur semester. Saya mengerti kesulitan yang Violeta alami tidak mudah. Supaya lebih nyaman, apabila saya jadwalkan sesi konseling offline bersama peer counselor antara tanggal 26-29 Februari, apakah berkenan? Jika berkenan, Violeta bersedia kapan dan jam berapa? Nantinya akan saya carikan peer counselor yang available. Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2024-02-18 19:24:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5509, 1863, 101695, 'mahasiswa', 'Muhammad Wafidzin', 'Saat berbicara sering gagap kak yang membuat saya tidak pede berbicara dengan orang baru maupun teman saya', '2024-02-18 19:43:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5510, 1874, 101710, 'mahasiswa', 'Violeta Naurah Zafira Saeladifa', 'Maaf sebelumnya, saya mengurungkan niat untuk konseling karena setelah beberapa pertimbangan, terimakasih atas responnya, selamat malam', '2024-02-18 19:48:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5511, 1863, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Saat berbicara sering gagap kak yang membuat saya tidak pede berbicara dengan orang baru maupun teman saya</blockquote> <p>Berbicara gagap yaa. Baik, dari masalah tersebut, apa yang Wafidzin harapkan dari LKM ini? Wafidzin mau dijadwalkan sesi konseling bersama peer counselor? Sebagai teman cerita untuk sedikit mengurangi rasa ketidakpercayaan diri? </p>', '2024-02-18 21:00:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5512, 1874, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Maaf sebelumnya, saya mengurungkan niat untuk konseling karena setelah beberapa pertimbangan, terimakasih atas responnya, selamat malam </blockquote> <p>Baik kalau begitu Violeta. Semoga keadaan Violeta semakin lebih baik yaa. Kalau butuh konseling atau teman cerita, jangan segan menghubungi kami. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2024-02-18 21:01:42');
