INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5523, 1907, 101741, 'mahasiswa', 'Serly Nur Isnaini', '235150407111056 sedih terus menerus, susah bertemu dengan orang banyak, merasa cemas dan sedih berkepanjangan, tidak bisa berfikir positif', '2024-02-20 06:49:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5524, 1908, 101742, 'mahasiswa', 'Almira Fidella Nurhemina', '225080100111057, saya merasa tidak adanya tujuan hidup dan masa depan. Saya tertekan dibawah tekanan kedua orang tua saya. Keluarga saya tidak miskin, tapi bukan juga orang mampu. Saya juga stress terkait masalah keuangan.', '2024-02-20 11:31:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5525, 1909, 100644, 'mahasiswa', 'Luhtitisari Lituhayu', 'Nama : Luhtitisari Lituhayu NIM : 215010101111109 Susah fokus sehari-hari. Stres. Post break up phase.', '2024-02-20 13:18:05');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5526, 1910, 101161, 'mahasiswa', 'Alda Meutia Ilyas', 'Saya Alda Meutia Ilyas dengam NIM 205030700111032. Saya mahasiswa akhir yang sedang dalam proses pengerjaan skripsi. Beberapa bulan terakhir saya bermasalah dengan fokus dan kantuk. Setiap kali saya membuka laptop untuk mengerjakan skripsi saya selalu merasa mengantuk, walau malam sebelumnya sudah tidur cukup. Bahkan saat saya bangun tidur dan membuka laptop, saya tetap mengantuk dan tidur lagi. Namun di kegiatan yang lain saya biasa saja. Seperti bermain handphone, membaca buku, dll. Tapi jika berhubungan dengan ''mengerjakan tugas akhir'' pasti mengantuk. Sedikit banyak ini menjadi masalah karena tugas akhir saya yang lambat prosesnya. Jadi, mendaftarnya saya disini, karena saya ingin menggali, apa ada sesuatu yang harus saya selesaikan di diri saya sendiri? Terima kasih sebelumnya.', '2024-02-20 15:05:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5527, 1900, 101737, 'mahasiswa', 'Benazier Uzma', 'saya nangis tiap malam. seperti hampir gila. saya juga ada masalah psikologi aneh di diri sendiri, saya gabisa percaya diri saya sendiri itu bisa. saya merasa saya selalu clumsy dan melakukan kesalahan sehingga akhirnya saya benar” melakukan kesalahan', '2024-02-20 16:32:51');
