INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5545, 1915, 101134, 'mahasiswa', 'Maria Rafelina Raya Boro', 'NIM: 195010101111171 Saya sekarang rasanya lagi kehilangan arah, mau ngapa-ngapain males, gak punya tujuan hidup gak punya motivasi, rasanya ingin menghilang aja.', '2024-02-22 15:30:01');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5546, 1873, 101709, 'mahasiswa', 'Lia Rizka Pratiwi', 'Saya kurang bersedia menggunakan peer counselor tapi saya bersedia untuk konsultasi online. Ketidak sediaan saya dikarenakan saya terdiagnosis oleh psikiater memiliki gangguan jiwa tertentu dan saya kurang yakin peer counselor dapat memberikan wadah aman untuk saya bercerita dan memberikan solusi konkret atad permasalahan yang saya hadapi. Jikapun konseling ub hanya menyediakan peer counselor dan tidak menyediakan tenaga professional untuk kounseling, saya akan membatalkan sesi konseling yang saya ajukan. Terimakasih.', '2024-02-23 09:41:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5547, 1876, 101698, 'mahasiswa', 'Jaka rahman', 'Selamat siang kak, saya bersedia untuk melakukan konseling offline dan saya ada luang waktu pada hari senin pukul 9.00 Terima kasih kak', '2024-02-23 14:29:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5548, 1863, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>225030201111032, permasalahan kekurangan yang ada pada diri saya yang mempengaruhi keseharian saya</blockquote> <p>Saya lanjutkan di Whatsapp yaa.<br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2024-02-23 17:02:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5549, 1871, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Selamat sore, terima kasih atas balasannya yang luar biasa baik di tengah-tengah perkuliahan saya yang cukup melelahkan. Menjawab pertanyaan terlampir, saya bisa melakukan sesi konseling minggu depan pada hari kamis sebelum pukul 15.30. Apakah jam tersebut memungkinkan? Terima kasih banyak, semoga tim konseling senantiasa sehat selalu</blockquote> <p>Baik, saya carikan dulu yaa. Nantinya akan saya hubungi melalui Whatsapp.<br /><br />Salam hangat,<br />Tim Konseling UB.<br /></p>', '2024-02-23 17:02:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5550, 1873, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Saya kurang bersedia menggunakan peer counselor tapi saya bersedia untuk konsultasi online. Ketidak sediaan saya dikarenakan saya terdiagnosis oleh psikiater memiliki gangguan jiwa tertentu dan saya kurang yakin peer counselor dapat memberikan wadah aman untuk saya bercerita dan memberikan solusi konkret atad permasalahan yang saya hadapi. Jikapun konseling ub hanya menyediakan peer counselor dan tidak menyediakan tenaga professional untuk kounseling, saya akan membatalkan sesi konseling yang saya ajukan. Terimakasih.</blockquote> <p>Terima kasih atas jawabannya Lia. Mohon maaf saya tidak tahu kalau Lia pernah mendapatkan diagnosis dari psikiater. Kami ada layanan konseling bersama psikolog. Kalau saya jadwalkan sesi konseling offline bersama Ibu Ika Fitria pada Kamis, 7 Maret 2024 pukul 08.30 WIB, apakah bersedia? Mohon untuk segera konfirmasi yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2024-02-23 17:07:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5551, 1872, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Selamat pagi Sebelumya saya menyampaikan terima kasih atas responsenya. Berkenaan dengan perihal yang sudah saya sampaikan, sudah hampir 3 minggu saya kesulitan menghubungi anak saya, wa dan telp tidak dibalas, sementara saya hanya bisa kontak melalui dosen pembimbingnya dan Dosen pembimbingnya sangat baik supportnya untuk membantu masalah anak saya, namun saya masih kuatir karena baik istri, kakak dan adiknya tidak pernah direspon jika kirim WA, sehingga saya kesulitan untuk meminta datang ke bagian konseling di Kampus. 1 bulan lalu kami pernah menyarankan untuk konsultasi ke psikolog, namun penerimaannya berbeda dan sepertinya tidak suka. Saat ini kami kesulitan berkomunikasi dan sangat mengharapkan support dari Kampus untuk mengetahui apa yang sedang dialami oleh anak saya sehingga kami sebagai orang tua bisa mengantisipasi. Saya berharap bisa bertemu dengan bagian konseling kampus untuk menceritakan secara detail kondisi saat ini. Demikian informasi dari saya, terima kasih atas perhatiannya. Hormat kami Hendro W </blockquote> <p>Baik bapak. Saya dan tim sudah dihubungi oleh Ibu Ulifa. Saat ini sedang proses menghubungi anak bapak. Info lebih lanjut, akan dihubungi oleh Ibu Ulifa. Terima kasih. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2024-02-23 17:19:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5552, 1878, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>225110800111001 Akhir-akhir ini sering merasa cemas karena dihantui ketakutan akan kematian. Cemasnya sudah sampai panic attack dan insomnia. Saya juga ingin melanjutkan konseling lanjutan dengan Ibu Bona.</blockquote> <p>Terima kasih Amalia telah menggunakan layanan konseling UB. Mohon maaf baru membalas karena libur semester. Sudah saya jadwalkan dengan Ibu Bona pada Rabu, 28 Februari 2024 pukul 10.30 WIB di Ruang Konseling Lantai 1 Gedung Rektorat. Mendekati hari pelaksanaan, akan dihubungi dan diingatkan melalui Whatsapp. Terima kasih. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2024-02-23 17:22:07');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5553, 1876, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Selamat siang kak, saya bersedia untuk melakukan konseling offline dan saya ada luang waktu pada hari senin pukul 9.00 Terima kasih kak</blockquote> <p>Baik, Jaka. Saya lanjutkan melalui Whatsapp yaa. Saya carikan dulu juga yaa. <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2024-02-23 17:24:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5554, 1912, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Nama saya Salsa Elsa Adi Artha dengan NIM 225030807111041. Beberapa saat terakhir ini, saya merasa sangat tertinggal dan tidak aman untuk melakukan berbagai kegiatan dengan bebas terutama di area kampus karena dugaan terhadap beberapa oknum yang secara tidak langsung memojokkan sampai melanggar privasi.</blockquote> <p>Terima kasih Salsa telah menggunakan layanan konseling. Mohon maaf baru membalas. Terkait hal yang tengah Salsa alami, apakah sebelumnya sudah pernah dilaporkan ke Satgas PPKS? Kalau belum, saya izin refferal ke Satgas PPKS yaa dan membagikan nomor Salsa untuk dihubungi oleh Satgas PPKS. Jika Salsa ingin melakukan konseling, baru nanti bersama saya dan tim karena kami berbeda tugas dengan Satgas PPKS. <br /><br />Salam hangat,<br />Tim Konseling UB. </p>', '2024-02-23 17:29:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5555, 1914, 101749, 'mahasiswa', 'Andini Laily Putri', '<p>Telah dihubungi melalui Whatsapp</p>', '2024-02-23 17:32:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5556, 1861, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Terima kasih atas balasannya , kalau kamis pagi bagaimana atau jumat pagi, terima kasih </blockquote> <p>Saya coba carikan dulu yaa dan dilanjutkan melalui Whatsapp yaa. <br /><br />Salam hangat, <br />Tim Konseling UB.</p>', '2024-02-24 21:32:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5557, 1887, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>205110501111015 Sejak kecil saya selalu diajari untuk mengucapkan maaf, tolong, dan terima kasih. Hanya saja setelah mengetahui kalau saya memiliki masalah mental dan beberapa waktu sering kambuh, saya merasa seperti lupa caranya mengekspresikan 3 hal tersebut. Saya ingin mengetahui lebih lanjut alasan kenapa seperti ini dan solusinya</blockquote> <p>Terima kasih Fairuz telah menggunakan layanan konseling. Mohon maaf baru membalas. Saya mengerti yang Fairuz alami saat ini tidaklah mudah. Oleh karena itu, telah saya jadwalkan sesi konseling offline bersama Ibu Bona pada 6 Maret 2024 pukul 10.30 WIB. Sambil menunggu sesi tersebut, jika Fairuz berkenan, bisa saya jadwalkan dulu dengan peer counselor. Bagaimana? <br /><br />Salam hangat,<br />Tim Konseling UB.</p>', '2024-02-24 22:03:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5558, 1861, 101379, 'mahasiswa', 'Alula putri sofia', 'Baik terima kasih', '2024-02-25 01:30:05');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5559, 1916, 101754, 'mahasiswa', 'Michael', '215150201111067 Masalah yang saya alami terkait permasalahan mental pribadi. Saya membutuhkan konseling untuk menangani masalah ini.', '2024-02-25 11:49:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5560, 1917, 101755, 'mahasiswa', 'Hilyatul Mathhuma', '215020501111008 Dalam cerita ini, ada tiga peran seseorang. Kebetulan semua berinisial H. H saya. Dan dua lagi Sebut saja Hai dan Has. Kami kenal pada saat mtqmn UB 2023 kemarin, UB menjadi tuan rumah. Dan saya posisi sebagai LO univ nya Hai dan Has. Sepertinya saya cinlok, dengan Hai. Saya suka dia. Bingung harus bagaimana, karena mtqmn cuma seminggu. Dan mereka harus balik lagi ke Jbg. Saya beranikan diri untuk mengungkapkan perasaan saya kpd Hai. Tapi dengan bahasa yg tersirat. Bukan kalimat yang "aku suka kamu, dll". Hehe pada akhirnya Hai ini enggak mau. Saya sulit untuk melupakan itu, terngiang ngiang dan terasa dihantui perasaan itu. Hal ini sangat mengganggu bagi saya. Karena dapat membuat saya tiba tiba menangis. Beralih pada di Has, dia malah suka sama saya. Saya enggak mau. Tapi Has ini keknya ngotot bgt, tiap hari masih chat saya. Saya balas ala kadarnya. Dan saya juga sudah pernah bilang kalau intinya saya masih belum bisa move on dari si Hai. Dan saya juga berusaha keras untuk melupakan orang orang itu. Alhasil nihil, yang tadinya saya gakmau sama Has, kok tiba tiba Mak sliwer itu muncul perasaan hampir mauini juga sangat mengganggu saya. Saya harus bagaimana saya enggak mau sama Has itu karena dia ceweknya banyak', '2024-02-25 17:54:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5561, 1852, 101688, 'mahasiswa', 'Andini Laily Putri', '<p>Telah dijadwalkan konseling</p>', '2024-02-25 19:44:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5562, 1918, 101756, 'mahasiswa', 'Verdian Pratama Putra', '225010100111081.. Permasalahan Keluarga yang tak kunjung berhenti, Kepercayaan yang tak ada lagi, Demotivasi hidup, Terlilit masalah kanan kiri, Haus akan validasi, Merasa tak pernah bahagia', '2024-02-26 00:45:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5563, 1919, 101757, 'mahasiswa', 'Alifah Nur Anggrainy', '225060500111050 Sebelumnya perkenalkan nama saya Alifah Nur Anggrainy, saat ini kesibukan saya selain berkuliah namun juga bekerja. Saya bekerja secara part-time di salah satu cafe, sehingga jadwal saya akhir akhir ini selain kuliah diisi dengan kegiatan saya di cafe. Saya merasa lelah batin akhir akhir ini, selain karna permasalahan keluarga, tetapi permasalahan pekerjaan dan juga akademik. Saya merasa, permasalahan saya terlalu kompleks sehingga saya sendiri sulit mengatasinya sendiri. Saya merasa sangat tidak maksimal dalam melakukan banyak hal, seperti kehilangan abbility untuk melakukan sesuatu dengan benar, saya sangat perlu media komunikasi dengan diri saya sendiri, sehingga saya merasa bahwa mungkin dengan mengikuti kegiatan konseling setidaknya bisa membantu saya mengenali, memahami dan mengatasi permasalahan saya sendiri.', '2024-02-26 01:56:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5564, 1920, 101722, 'mahasiswa', 'Ony Wulandari', '220160100011057 Hampir satu tahun ini saya menjalani koas gigi, sebelumnya juga sudah banyak fase fase terpuruknya, tapi kali ini lagi lagi ngerasa stuck sampai takut berinteraksi sama orang lain, penuh kebencian sama diri sendiri, sama sekali ga punya motivasi untuk melakukan hal lain', '2024-02-26 06:43:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5565, 1878, 101256, 'mahasiswa', 'Amalia Ramadhaniyah Adhie Dwi Putri', 'Halo, terima kasih atas responnya. Apakah memungkinkan untuk mengganti jadwal monseling karena pada hari tersebut saya ada urusan yang tidak bisa ditinggalkan. Terima kasih', '2024-02-26 07:15:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5566, 1921, 101738, 'mahasiswa', 'Zulian Teukum Syah', 'Saya Zulian Teukum Syah (205090407111032) mahasiswa Program Studi Matematika (FMIPA UB) Angkatan 2020. Sejauh ini saya mengalami permasalahan kepercayaan diri dan terasa cukup sulit untuk merasa tenang sejauh ini. Puncaknya setelah saya menghabiskan waktu beberapa saat lalu di negara tetangga dan menghadapi beberapa permasalahan yang berkaitan dengan keluarga dan merasa merembet ke beberapa teman serta kenalan yang mana saya sempat merasakan seperti gejala panik pada beberapa waktu. Hal ini cukup membuat saya khawatir dan mengganggu kegiatan akademik terutama berkaitan dengan skripsi. Saya berharap yang terbaik sehabis ini.', '2024-02-26 10:13:15');
