INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5568, 1923, 101758, 'mahasiswa', 'Benedicta Ika Ermadela', '226120200011004 Sebelumnya saya telah menerima pengobatan gangguan cemas di tahun 2023 dari psikiater, namun berhenti di bulan Desember krn rujukannya habis. Belakangan ini gangguan cemas yang ada mulai menjadi gejala psikosomatis, sulit tidur, dan ketakutan berlebihan akan terkena penyakit berat', '2024-02-27 15:16:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5569, 1878, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Halo, terima kasih atas responnya. Apakah memungkinkan untuk mengganti jadwal monseling karena pada hari tersebut saya ada urusan yang tidak bisa ditinggalkan. Terima kasih</blockquote> <p>Baik. Kalau begitu tanggal 13 Maret 2024 pukul 10.30 yaa. Bagaimana?</p> <p><br /></p>', '2024-02-27 15:48:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5570, 1878, 101256, 'mahasiswa', 'Amalia Ramadhaniyah Adhie Dwi Putri', 'Mohon maaf tapi juga di tanggal tersebut terkendala juga. Baik kalau begitu tolong tetap besok saja. Terima kasih. Oh iya, untuk ruangan konseling di gd rektorat itu pindah ke lt 1 ya berarti sekarang? Terima kasih', '2024-02-27 16:00:08');
