INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5572, 1861, 1, 'admin', 'Andini Laily Putri', '<p><br /></p><blockquote>Baik terima kasih </blockquote> <p><br />Selamat sore, Alula. Saya ingin menanyakan, jika saya jadwalkan sesi konseling Kamis, 29 Februari 2024 pukul 09.00 WIB dengan Kak Nasywa secara online, apakah bersedia?</p>', '2024-02-27 16:40:42');
