INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5574, 1925, 101760, 'mahasiswa', 'Vira Nathania Dika Azzahra', 'NIM :205030901111003 Permasalahan: orang tua selalu tidak setuju sama yang saya lakukan terutama terhadap karir , keinginan, serta kriteria pasangan hidup saya. Orang tua selalu ingin yang terbaik untuk anaknya tapi anak juga berhak untuk menentukan pilihannya sendiri dan sesuai keinginan sendiri dan saya sering kali down atas larangan” orang tua terhadap keinginan dan pilihan saya jadi bagaimana cara saya harus meyakinkan orang tua saya dan tidak down serta tidak gampang menangis saat dilarang oleh orang tua saya?', '2024-02-28 08:11:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5575, 1911, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Terima kasih telah menggunakan layanan konseling. Silakan menceritakan apapun yang ingin Anda ceritakan disini ya, kami akan mendengarkan Anda.</p> <p><br /></p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-02-29 11:14:26');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5576, 1906, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Halo, Shella. <br /></p> <p>Terima kasih telah menggunakan layanan konseling ya. Untuk memudahkan kami membantu Anda, silakan ceritakan terlebih dahulu secara lebih lanjut apa yang Anda alami :)<br /></p> <p><br /></p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-02-29 11:16:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5577, 1909, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Terima kasih telah menggunakan layanan konseling. Apakah Anda bersedia untuk kami jadwalkan dengan peer counselor kami?</p> <p><br /></p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-02-29 11:18:04');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5578, 1907, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Halo, Serly</p> <p>Terima kasih telah menggunakan layanan konseling. Untuk memudahkan kami membantu Anda, silakan terlebih dahulu menceritakan beberapa hal berikut ini ya :)</p> <p>1. Bisakah Anda menceritakan mengenai penyebab kesedihan yang Anda alami?</p> <p>2. Apakah belakangan ini Anda mengalami suatu kejadian yang membuat Anda cemas?</p> <p>3. Selain kesulitan untuk bertemu dengan orang banyak, apa dampak dari apa yang Anda alami saat ini?</p> <p>Dengan jawaban yang Anda berikan, apabila Anda menginginkan konseling langsung bersama peer/konselor kami, silakan kabari kami ya.</p> <p><br /></p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-02-29 11:21:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5579, 1908, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Terima kasih telah menggunakan layanan konseling. Saya memahami bahwa apa yang Anda alami tidaklah mudah. Untuk membantu Anda lebih lanjut, bisakah Anda menceritakan lebih lanjut mengenai tekanan yang Anda rasakan dari orang tua?</p> <p><br /></p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-02-29 11:22:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5580, 1910, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Terima kasih telah menggunakan layanan konseling. Untuk membantu Anda lebih lanjut, saya izin menanyakan beberapa hal berikut ini:</p> <p>1. Apakah sebelumnya pernah mencoba mengerjakan skripsi di tempat umum seperti cafe, perpustakaan, dll? Apakah tetap merasa mengantuk?</p> <p>2. Apakah sebelumnya memiliki target yang ingin dicapai untuk skripsi ini? Bagaimana dengan teman Anda? Apakah Anda memiliki teman yang sedang berada di fase mengerjakan skripsi dengan Anda?</p> <p>3. Apakah asupan hidrasi dan makan Anda teratur?</p> <p>4. Apakah Anda yakin kondisi ini disebabkan oleh rasa kantuk dan gagal fokus? Apakah setiap mengerjakan skripsi, Anda memiliki bayangan apa yang ingin Anda tulis?</p> <p><br /></p> <p>Salam Hangat,</p> <p>Tim Konseling UB.<br /></p>', '2024-02-29 11:28:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5581, 1916, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Terima kasih telah menggunakan layanan konseling. Untuk memudahkan kami untuk membantu Anda lebih lanjut, bisakah Anda menceritakan sedikit permasalahan mental tersebut? Hal ini juga akan digunakan untuk diserahkan kepada konselor kami :)</p> <p><br /></p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-02-29 11:29:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5582, 1917, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Terima kasih telah menggunakan layanan konseling. Berkaitan dengan permasalahan yang Anda alami, saya memiliki beberapa hal yang ingin saya tanyakan berikut ini:</p> <p>1. Untuk menghindari perasaan kepada orang yang tidak Anda suka, apakah sebelumnya pernah mengidentifikasi beberapa hal yang tidak Anda sukai kepada orang tersebut? Kebiasaan buruknya? Value yang tidak sejalan? Selain itu, Anda juga bisa menanyakan kepada diri Anda, apa yang membuat Anda tertarik dengan orang tersebut?</p> <p>2. Apabila Anda sadar bahwa orang tersebut memiliki banyak wanita, tanyakan kepada diri Anda, mengapa Anda masih memiliki perasaan yang tumbuh meskipun sedikit? Apakah Anda yakin hal tersebut bukan karena Anda yang menyukai perhatian yang diberikannya saja?</p> <p>3. Apabila hal tersebut disebabkan oleh adanya perhatian yang diberikan atau rasa kesepian yang terpenuhi, banyak sekali cara untuk mengisinya. Anda dapat menyibukkan diri Anda dengan hal-hal yang bermanfaat seperti melakukan hobi, mencapai target yang Anda buat, dan masih banyak lagi. Perhatian tersebut juga dapat digantikan dengan hadirnya teman, keluarga, dan sumber eksternal lainnya.</p> <p>4. Untuk menghindari Anda jatuh kepada orang lain dengan begitu cepat, pernahkah Anda bertanya kepada diri Anda mengenai kebutuhan apa yang Anda cari di pasangan? Apakah hanya kesenangan? Apakah hiburan? Apakah pemenuhan afeksi? Atau hubungan jangka panjang? Dengan menanyakan kepada diri Anda hal-hal seperti ini, Anda memiliki kontrol karena Anda tahu yang datang tidak sesuai dengan kebutuhan yang Anda cari.</p> <p><br /></p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-02-29 11:53:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5583, 1917, 101755, 'mahasiswa', 'Hilyatul Mathhuma', 'Terimakasih atas responnya Bu, mohon maaf sebelumnya kalau ceritanya agak konyol huhuhu Saya izin menjawab poin dari yang ibu sampaikan 1. Saya tahu perilaku dia dari teman temannya yang telah menspill kelakuan dia kepada wanita. Saya nggak langsung menelan informasinya. Tapi sudah ada lebih dari lima orang yang bilang begitu. 2. Sepertinya dia memang pintar merangkai kata Bu, tapi saya tidak termakan kok Bu huhuhu 3. Terimakasih Bu 4. Benar Bu, sepertinya hanya perasaan saya sebagai cegil yang labil huhu. Saya belum memiliki rencana untuk menikah. Terimakasih Bu', '2024-02-29 12:11:46');
