INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5603, 1886, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Terima kasih telah menggunakan layanan konseling. Apabila Anda memiliki sesuatu yang ingin diceritakan, silakan ceritakan kepada kami ya:)</p> <p><br /></p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-03-01 17:01:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5604, 1931, 101770, 'mahasiswa', 'Alinia Bunga Mirawan', '233140500111020 | Saya merasakan tekanan batin terhadap diri saya sendiri karena saya takut akan kesalahan dan juga selalu cemas terhadap hal yang telah saya lakukan saya selalu merasa melakukan kesalahan dan itu sangat mengganggu hari hari saya', '2024-03-01 18:32:49');
