INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5617, 1936, 101774, 'mahasiswa', 'Muhammad Fathan Alghifary', '215050107111003/ nama saya fathan, saya memiliki masalah mempengaruhi prubahan karakter dalam diri saya dan selalu merasa sendiri karena saya sudah tidak memiliki siapapun yang ingin saya ajak bicara karena saya sudah tidak percaya dengan orang lain. Saya sangat membutuhkan orang untuk membicarakan hal hal yang akan saya jelaskan secara detail.', '2024-03-03 00:07:49');
