INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5623, 1937, 101776, 'mahasiswa', 'Julia Rahma Gani', 'NIM 225170207111001 terlalu banyak mengalami masalah hingga hidup terasa flat saja dan emosi jadi meledak ledak', '2024-03-03 14:53:28');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5624, 1902, 1, 'admin', 'Nora Silvana', '<p>Halo, Tiffani!</p> <p>Bagaimana kabarnya saat ini?</p> <p>Sebelumnya, terima kasih yaa karena telah menggunakan layanan konseling. Mohon maaf juga atas keterlambatan respons akibat panjangnya antrian.</p> <p>Setelah membaca cerita Tiffani, saya merasa bahwa ternyata selama ini Tiffani sudah melalui banyak hal sulit yaa. Kewajiban untuk mengerjakan skripsi saja sudah cukup sulit, namun, Tiffani ternyata harus mengemban tanggung jawab untuk merawat ayah Tiffani pada saat itu. Saya juga ingin mengungkapkan turut berbelasungkawa atas kepulangan ayah Tiffani. </p> <p>Saya sangat mengapresiasi bagaimana Tiffani tetap berusaha untuk menyelesaikan studinya. Dalam cerita, Tiffani mengatakan bahwa sudah menentukan target terkait skripsinya yaa, kira-kira boleh dijelaskan lebih lanjut target yang sudah Tiffani buat ini seperti apa yaa? Kemudian, Tiffani merasa cemas setiap harus menghubungi dosen pembimbing yaa. Nah, kalau boleh tahu pengalaman apa saja yang Tiffani rasa menjadi penyebab perasaan cemas tersebut? Saat merasa cemas, pikiran-pikiran seperti apa yang Tiffani pikirkan?</p> <p>Untuk saat ini, itu dulu yang bisa saya sampaikan. Saya harap Tiffani berkenan untuk menjawab beberapa pertanyaan tadi yaa, supaya kita bisa sama-sama memetakan permasalahannya dan harapannya bisa juga mendiskusikan langkah yang perlu dilakukan untuk mengatasi permasalahan Tiffani.</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2024-03-03 17:03:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5626, 1902, 1, 'admin', 'Nora Silvana', '<p>Halo, Tiffani!</p> <p>Bagaimana kabarnya saat ini?</p> <p>Sebelumnya, terima kasih yaa karena telah menggunakan layanan konseling. Mohon maaf juga atas keterlambatan respons akibat panjangnya antrian.</p> <p>Setelah membaca cerita Tiffani, saya merasa bahwa ternyata selama ini Tiffani sudah melalui banyak hal sulit yaa. Kewajiban untuk mengerjakan skripsi saja sudah cukup sulit, namun, Tiffani ternyata harus mengemban tanggung jawab untuk merawat ayah Tiffani pada saat itu. Saya juga ingin mengungkapkan turut berbelasungkawa atas kepulangan ayah Tiffani. Saya sangat mengapresiasi bagaimana Tiffani tetap berusaha untuk menyelesaikan studinya. </p> <p>Sebelumnya, Tiffani sudah pernah melakukan konseling dengan konselor kami yaa. Boleh tolong diceritakan dulu update atau apa saja yang sudah Tiffani lakukan semenjak konseling tersebut? Dalam cerita, Tiffani mengatakan bahwa sudah menentukan target terkait skripsinya yaa, kira-kira boleh dijelaskan lebih lanjut target yang sudah Tiffani buat ini seperti apa yaa? Kemudian, Tiffani merasa cemas setiap harus menghubungi dosen pembimbing yaa. Nah, kalau boleh tahu pengalaman apa saja yang Tiffani rasa menjadi penyebab perasaan cemas tersebut? Saat merasa cemas, pikiran-pikiran seperti apa yang Tiffani pikirkan?</p> <p>Untuk saat ini, itu dulu yang bisa disampaikan. Saya harap Tiffani berkenan untuk menjawab beberapa pertanyaan tadi yaa, supaya kita bisa sama-sama memetakan permasalahannya dan harapannya bisa juga mendiskusikan langkah yang perlu dilakukan untuk mengatasi permasalahan Tiffani.</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2024-03-03 17:03:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5627, 1938, 101289, 'mahasiswa', 'Zeeges Mollic', 'NIM: 235100500111039 Akhir-akhir ini saya merasa sendirian, jauh dari teman-teman, tidak memiliki perasaan akrab dengan teman-teman seakan mereka juga jenuh dan tidak mau berteman dengan saya. Saya juga kesulitan untuk bisa mengatur diri saya sendiri, memiliki kebiasaan hoarding dan tidak bisa membereskan kamar sendiri. Jika boleh, saya ingin untuk dibantu oleh psikolog/psikiater karena sebelumnya oleh konselor sebaya, saya sudah disarankan untuk bertemu dengan yang lebih profesional.', '2024-03-03 19:04:02');
