INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5663, 1933, 101710, 'mahasiswa', 'Violeta Naurah Zafira Saeladifa', 'Beberapa kali penyebab menangis tidak saya ketahui. Di beberapa keadaan saya merasa baik baik saja, tetapi dibeberapa waktu hal tersebut membebani sehingga saya merasa sedih dan berakhir menangis. Hal tersbeut terkadang terjadi hingga berlarut larut sehingga mengganggu saya denagn aktivitas sehari-hari.', '2024-03-04 18:02:26');
