INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5666, 1942, 100600, 'mahasiswa', 'Felicitia Aulia Rahma', 'Nim = 205110200111023 Saya memiliki gangguan kepribadian ambang dan bipolar, saat ini saya berada dalam suatu permasalahan ketika menjalin hubungan dengan seseorang yang berharga bagi saya. Saya tidak ingin kehilangan orang tersebut, begitu pula saya tidak ingin kehilangan diri saya sendiri.', '2024-03-04 20:29:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5667, 1936, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Oke sudah dijadwalkan ya dengan peer counselor kami pada hari kamis, 7 maret 2024 pukul 11.00-12.00. Informasi lebih lanjut akan disampaikan melalui WhatsApp.</p> <p>Terima kasih.</p> <p>Salam Hangat,</p> <p>Layanan Konseling UB.</p>', '2024-03-04 20:49:12');
