INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5773, 1913, 1, 'admin', 'Nora Silvana', '<p>Baik, kami jadwalkan dengan peer counselor terlebih dahulu yaa. Namun apakah Anda berkenan memberikan jadwal konseling selain hari Rabu 6 Maret pukul 14.00? Hal tersebut diperlukan untuk mengantisipasi ketidaktersediaan peer counselor kami</p>', '2024-03-06 11:08:33');
