INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5783, 1946, 1, 'admin', 'Nora Silvana', '<p>Baik, terima kasih ya sudah menceritakan kondisi permasalahan Anda pada saya. Berkaitan dengan permasalahan tersebut, apakah Anda bersedia dijadwalkan sesi konseling dengan peer counselor kami? Jika bersedia, Anda bisa menyebutkan 2 opsi jadwal dari hari senin-jumat (07.30-21.00). </p> <p>Terima kasih.</p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-03-06 15:54:02');
