INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5799, 1947, 101780, 'mahasiswa', 'Ardisatya Harnanda', 'Saya ngerasa down, depresi, stres, dan demotivasi. Saya sejujurnya agak sulit jika menjelaskan melalui ketikan. Saya harap bisa dijadwalkan tatap muka biar lebih puas karena saya merasa ada yg tidak beres dalam hidup saya', '2024-03-07 14:00:14');
