INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5824, 1953, 101789, 'mahasiswa', 'Nurwahyuni', '195080600111005 Sejak bulan November lalu, saya merasa saya mudah menangis dan sensitif ketika orang lain bertanya kabar teman terdekat saya kepada saya, padahal si penanya juga dekat dengan ia. Belakangan ini ketika berada di kelompok pertemuan saya merasa baik-baik saja, namun setelah beranjak dari sana saya merasa ingin menangis tanpa alasan yang jelas', '2024-03-08 23:15:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5825, 1947, 101780, 'mahasiswa', 'Ardisatya Harnanda', 'Terima Kasih telah membalas pesan saya. Saya bersedia untuk melakukan konseling dengan konselor sejawat, saya harap dapat berjalan secara lancar. Saya mengajukan jadwal pada hari Senin pukul 12.30 dan Rabu pukul 13.00', '2024-03-09 02:24:26');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5826, 1947, 101780, 'mahasiswa', 'Ardisatya Harnanda', 'Sebelumnya mohon maaf kak, apakah layanan konseling ini ada biayanya?', '2024-03-09 02:49:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5827, 1949, 101785, 'mahasiswa', 'Raina Safa Vania Nova', 'Mohon maaf baru bisa membalas, saya kurang berkenan untuk membalas secara tertulis, apakah bisa dijadwalkan sesinya ya? dan jika sesi konseling nanti sudah berlangsung apakah dipungut biaya? Terimakasih', '2024-03-09 10:19:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5828, 1954, 101791, 'mahasiswa', 'Zaura Iffatutsalatsa', 'nim 215050107111067 baru-baru saja merasa gampang sekali lupa dengan segala hal. lupa yang walaupun diingatkan kembali memorinya, tidak ada ingatan tentang hal tersebut. padahal kejadian/hal tersebur tidak lama/masih baru2 saja', '2024-03-09 22:48:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5829, 1943, 1, 'admin', 'Nora Silvana', '<p>Selamat sore Auliya Vihansya Nisaprilina, sebelumnya maaaf atas keterlambatan respon dikarenakan banyaknya pesan yang masuk.</p> <p>Baik terimakasih atas laporannya, akan kami bantu untuk melakukan penjadwalan melalui WhatsApp Auliya. Mungkin setelah ini bisa di cek kemai ya pesan yang dikirimkan oleh Admin layanan konseling UB.</p>', '2024-03-11 16:48:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5830, 1943, 1, 'admin', 'Nora Silvana', '<p>Kami sudah melakukan penjadwalan dengan peer counselor dari layanan konseling UB, untuk penyesuaian jadwal, apakah komunikasi bisa dilanjutkan melalui WA? terimakasih.</p>', '2024-03-11 17:02:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5831, 1901, 101676, 'mahasiswa', 'Nora Silvana', '<p>E-tiket ini bermasalah, sehingga dilanjut pada E-tiket yang baru</p>', '2024-03-11 17:04:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5832, 1904, 1, 'admin', 'Nora Silvana', '<p>Terimakasih atas pesan serta pengajuan jadwal yang diberikan. Kami akan memantu penjadwalan sesi konseling bersama peer counselor dari layanan konseling UB. Mohon ditunggu pesan lanjutan yang akan dikirimkan oleh admin kami melalui WA terlampir.</p>', '2024-03-11 17:09:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5833, 1922, 1, 'admin', 'Nora Silvana', '<p>Terimakasih karena Anda telah memiliki keberanian untuk menceritakan kondisi yang sedang Anda alami. Sebelumnya mohon maaf atas keterlambatan respon dikarenakan antrian yang cukup banyak.</p> <p>Saya sangat memahami apa yang Anda rasakan dan hal tersebut bukanlah hal yang mudah, Semoga hari saat Anda baca tanggapan ini, kondisinya sudah lebih baik ya. Kita hidup dan berinteraksi dengan berbagai macam karakteristik individu, maka kita tidak dapat mengendalikan lingkungan, sehingga kita perlu melakukan coping yang lebih memadai dalam menghadapi situasi tersebut. Coping adalah strategi individu dalam menghadapi stress yang bisa berasal dari situasi atau stimulus eksternal maupun stimulus internal. Salah satunya dengan mempertimbangkan respon kognitif yang muncul berupa pemikiran/ keyakinan yang negatif mengenai suatu situasi/ diri sendiri/ orang lain maupun situasi yang kan datang dan belum terjadi. Karena pemikiran yang negatif dapat mendorong munculnya emosi negatif dan perilaku-perilaku yang maladaptif, sehingga ketika menghadapi situasi-situasi dalam hidup dapat memberikan efek pada kondisi fisik dan psikologis. Tetap semangat ini bukanlah hal mudah, tapi saya yakin Anda punya potensi, mampu dan bisa untuk sukses dan bahagia, tinggal bagaimana Anda memberi kesempatan diri sendiri.<br /></p>', '2024-03-11 17:40:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5834, 1922, 1, 'admin', 'Nora Silvana', '<p>Terimakasih karena Anda telah memiliki keberanian untuk menceritakan kondisi yang sedang Anda alami. Sebelumnya mohon maaf atas keterlambatan respon dikarenakan antrian yang cukup banyak.</p> <p>Saya sangat memahami apa yang Anda rasakan dan hal tersebut bukanlah hal yang mudah, Semoga hari saat Anda baca tanggapan ini, kondisinya sudah lebih baik ya. Kita hidup dan berinteraksi dengan berbagai macam karakteristik individu, maka kita tidak dapat mengendalikan lingkungan, sehingga kita perlu melakukan coping yang lebih memadai dalam menghadapi situasi tersebut. Coping adalah strategi individu dalam menghadapi stress yang bisa berasal dari situasi atau stimulus eksternal maupun stimulus internal. Salah satunya dengan mempertimbangkan respon kognitif yang muncul berupa pemikiran/ keyakinan yang negatif mengenai suatu situasi/ diri sendiri/ orang lain maupun situasi yang kan datang dan belum terjadi. Karena pemikiran yang negatif dapat mendorong munculnya emosi negatif dan perilaku-perilaku yang maladaptif, sehingga ketika menghadapi situasi-situasi dalam hidup dapat memberikan efek pada kondisi fisik dan psikologis. Tetap semangat ini bukanlah hal mudah, tapi saya yakin Anda punya potensi, mampu dan bisa untuk sukses dan bahagia, tinggal bagaimana Anda memberi kesempatan diri sendiri.<br /></p> <p>Salam hangat,</p> <p>Layanan Konseling UB.</p>', '2024-03-11 17:40:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5835, 1885, 1, 'admin', 'Nora Silvana', '<p>Baik, terimakasih atas responnya. Kami akan membantu proses penjadwalan dengan Konselor. Untuk komunikasi selanjutnya akan dilakukan melalui WhatsApp dari Admin layanan Konseling UB.</p> <p>Salam hangat,</p> <p>Layanan Konseling UB.</p>', '2024-03-11 18:00:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5836, 1917, 1, 'admin', 'Nora Silvana', '<p>Sebelumnya saya sampaikan permohonan maaf atas keterlambatan respon yang dikirimkan karena banyaknya antrian yang masuk.</p> <p>Tidak masalah, setiap cerita memiliki nilai pentingnya sendiri. Terima kasih telah berbagi dengan saya. Seperti yang Anda sampaikan, penting untuk tidak terburu-buru dalam menanggapi informasi dan untuk mempertimbangkan berbagai sumber informasi. Juga, sangat baik bahwa Anda menyadari kekuatan kata-kata dan tidak terpengaruh olehnya. Selalu ingat untuk tetap kuat dalam menghadapi situasi yang mungkin menantang. Saya menghargai kejujuran dan keberanian Anda dalam mengeksplorasi perasaan dan situasi Anda. Apakah ada hal lain yang ingin Anda bicarakan atau diskusikan lebih lanjut?</p> <p>Salam hangat,</p> <p>Tim Layanan Konseling UB</p>', '2024-03-11 18:08:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5837, 1921, 1, 'admin', 'Nora Silvana', '<p>Sebelumnya moon maaf atas keterlambatan respon yang dikirimkan karena banyaknya antrian. </p> <p>Terima kasih telah berbagi pengalaman Anda dengan saya. Saya ingin menyatakan bahwa perasaan kesepian, ketidakpastian, dan kekhawatiran yang Anda rasakan adalah hal yang wajar, dan saya menghargai keberanian Anda dalam berbicara mengenai hal-hal tersebut.</p> <p>Mengenai konsultasi tatap muka apakah Anda bersedia untuk dijadwalkan bersama peer counselor kami terlebih dahulu? Karena untuk jadwal Konselor dari Layanan Konseling UB baru kosong pada Bulan April Awal. Jika bersedia Anda bisa mengirimkan hari,tanggal dan jam, antara Senin-Jumat, dipukul 08.00-15.00.</p> <p>Salam hangat,</p> <p>Tim Layanan Konseling UB</p>', '2024-03-11 18:17:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5838, 1923, 1, 'admin', 'Nora Silvana', '<p>Selamat sore,</p> <p>Terima kasih telah menggunakan layanan konseling dan mau berbagi perasaaan yang Anda miliki. Sebelumnya mohon maaf atas keterlambatan jawaban karena banyaknya antrian. Saya memahami bahwa Anda menghadapi tantangan dalam mengelola perasaan cemas dan ketakutan terkait kesehatan. Apakah Anda bersedia untuk melakukan penjadwalan konseling tatap muka dengan peer counselor kami terlebih dahulu? Karena untuk para Konselor dari Layanan Konseling UB sendiri baru memiliki jadwal kosong di awal Bulan April.</p> <p>Salam hangat,</p> <p>Tim Layanan Konseling UB.</p>', '2024-03-11 18:34:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5839, 1924, 1, 'admin', 'Nora Silvana', '<p>Selamat malam,</p> <p>Baik, kami akan mencoba membantu proses penjadwalan konseling tatap muka. Sebelumnya mohon maaf atas keterlambatan respon dikarenakan banyaknya antrian pesan. Untuk proses penjadwalan akan dilanjutkan melalui WhatsApp dari admin Layanan Konseling. Mohon ditunggu ya.</p>', '2024-03-11 18:39:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5840, 1921, 101738, 'mahasiswa', 'Zulian Teukum Syah', 'Hai ka! Sebelumnya terima kasih atas responnya. Untuk hari Rabu, 13 Maret 2024, pukul 13.00 apakah bisa? Terima kasih sebelumnya', '2024-03-11 19:18:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5841, 1942, 1, 'admin', 'Nora Silvana', '<p>Selamat malam, mohon maaf atas keterlambatan respon dikarenakan banyaknya antrian pesan yang masuk.</p> <p>Terimakasih telah mengunakan layanan konseling UB. Saya memahami bahwa Anda mengalami tantangan yang kompleks dalam hubungan dan perjuangan dengan gangguan mental. Pertama-tama, saya ingin mengapresiasi keberanian Anda untuk berbicara terbuka tentang pengalaman yang Anda rasakan.</p> <p>Apakah Anda bersedia untuk melakukan konseling dengan konselor kami, di hari Selasa, 19 Maret 2024? Jika bersedia kami akan membantu proses penjadwalan konseling secara online.</p> <p>Salam hangat,</p> <p>Tim Layanan Konseling UB.</p>', '2024-03-11 19:21:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5842, 1921, 1, 'admin', 'Nora Silvana', '<p>Baik, akan saya bantu melakukan penjadwalan. Proses selanjutnya akan dibantu oleh Admin kami melalui WhatsApp. Terimakasih</p>', '2024-03-11 19:23:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5843, 1921, 101738, 'mahasiswa', 'Zulian Teukum Syah', 'Terima kasih ka', '2024-03-11 19:32:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5844, 1952, 1, 'admin', 'Nora Silvana', '<p>Selamat malam,</p> <p>Terima kasih atas keberanian Anda untuk berbagi pengalaman dan laporan mengenai gangguan emosi yang sedang Anda hadapi. Kami sangat memahami betapa pentingnya dukungan dan perhatian dalam situasi seperti ini.</p> <p>Kami ingin memberikan apresiasi atas langkah Anda untuk mencari bantuan dan berbagi pengalaman sebelumnya dengan profesional kesehatan mental. Mengetahui bahwa Anda sudah memiliki pengalaman positif dengan psikolog dan psikiater dalam mengatasi gangguan serupa di masa lalu, merupakan langkah awal yang sangat baik.</p> <p>Untuk mengetahui langkah lebih lanjut mengenai ini, kami ingin mengajukan beberapa pertanyaan terkait:</p> <p>1. Untuk pengalaman pergi ke Psikolog/Psikiater sebelumnya apa yang Anda dapatkan dari sana? Apakah ada diagnosis yang berarti?</p> <p>2. Apakah bisa dideskripsikan kondisi ''ramai'' yang Anda maksud dalam kepala Anda?</p> <p>Salam hangat,</p> <p>Tim Layanan Konseling UB.</p>', '2024-03-11 19:42:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5845, 1954, 1, 'admin', 'Nora Silvana', '<p>Selamat malam,</p> <p>Terimakasih telah menggunakan layanan konseling UB. Semoga ketika balasan ini diterima Anda dalam kondisi yang lebih baik. Saya dapat memahami kondisi Anda, pasti muncul kebingungan dalam diri Anda karena kondisi ini baru dalam kehidupan Anda. Untuk mengetahui langkah lebih lanjut dari pesan yang Anda kirimkan, saya ingin mengajukan beberapa pertanyaan mengenai:</p> <p>1. Apakah bisa diceritakan dengan lebih detail mengenai kondisi ''lupa'' ini? </p> <p>2. Bagaimana awal mula Anda menyadari hal ini muncul/terjadi? </p> <p>3. Apakah ada kejadian yang terjadi sebelumnya menjadi memicu hal tersebut?</p> <p>Salam hangat,</p> <p>Tim Layanan Konseling UB.</p>', '2024-03-11 19:49:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5846, 1953, 1, 'admin', 'Nora Silvana', '<p>Selamat malam,</p> <p>Terimakasih telah menggunakan layanan konseling UB. Saya mengapresiasi keputusan Anda untuk memberanikan diri menggunakan layanan kami. Apakah bisa diceritakan dengan lebih detail kondisi/kejadiannya? Mengapa perasaan/pikiran itu bisa muncul? Apakah lingkungan Anda mempengaruhi hal ini?</p> <p>Salam hangat,</p> <p>Tim Layananan Konseling UB. </p>', '2024-03-11 19:54:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5847, 1926, 100693, 'mahasiswa', 'Nora Silvana', '<p>Sesi konseling telah dilangsungkan</p>', '2024-03-11 20:02:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5848, 1949, 1, 'admin', 'Nora Silvana', '<p>Selamat malam, </p> <p>Bisa dijadwalkan sesi konseling, akan tetapi karena konselor kami memiliki jadwal sampai pada awal bulan April, apakah Anda berkenan untuk dijadwalkan dengan peer counselor kami? Jika berkenan silahkan mengajukan 2 jadwal pilihan antara hari Senin-Jumat di pukul 08.00-15.00. Terimakasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2024-03-11 20:04:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5849, 1938, 1, 'admin', 'Nora Silvana', '<p>Selamat malam, Zeegas. </p> <p>Menginformasikan lebih lanjut mengenai sesi konseling yang ditawarkan melalui E-tiket, yaitu pada hari Selasa 12 Maret 2024. Dikarenakan bertepatan dengan tanggal merah, maka akan dilakukan reschedule pada hari Selasa minngu depan. Apakah berkenan? terimakasih</p>', '2024-03-11 20:09:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5850, 1953, 101789, 'mahasiswa', 'Nurwahyuni', 'Saat kejadian tersebut dalam kondisi belajar kelompok, ketika usai belajar kelompok, ada salah satu teman bertanya apakah benar saya adalah seseorang yang dulu memutuskan keluar dari organisasi di tengah periode. Saya tidak keberatan untuk menjawabnya, kemudian kami pulang satu per satu, dan tiba-tiba saya merasa ingin menangis namun tertahan hingga terasa bagian tenggorokan saya penuh. Setelah sampai di kos saya memutuskan menangis. Setelah beberapa hari berpikir dan mencari detail kejadian, saya merasa kejadian ini berawal dari adanya seseorang yang baru saya kenal selalu menawarkan bantuan dan benar² membantu saya, namun terkadang saya merasa belum percaya dengannya hingga saya bersikap seakan-akan menolak, hingga pada akhirnya saya menyadari orang tersebut memilih menyatakan suka kepada org lain, dan ketika ia tertolak, ia kembali kepada saya, hingga pada akhirnya saya memutuskan untuk tidak berinteraksi kembali dengannya. Namun ternyata saya masih bergantung kepadanya, berharap dia akan mengajukan bantuan kembali kepada saya, karena ia adalah orang yang memberi semangat tanpa dipinta. Namun saya merasa memilih pergi, karena saya memahami ada yg lebih baik untuknya. Kemudian saya berpikir, saya terlalu sering mendahulukan orang lain, dan menahan perasaan saya dalam hal apa pun. Saya rasa iya, karena saya merasa kehilangan keluarga saya satu per satu, dari mulai meninggalnya ayah, dan kakak yang sudah menikah satu per satu mulai berubah sikap, begitupun dengan kakak laki-laki saya yang awalnya senantiasa bertanya kabar saya sudah tidak pernah mengechatt kembali. Kembali lagi saya mencoba memahami kondisi semua orang, tanpa tahu bagaimana menyampaikan perasaan ini. Dan menjadikan saya beberapa hari ini lebih menjaga privasi kepada siapa pun, termasuk apa yang saya rasakan. Oleh karena itu saya ingin berkonsultasi, untuk bercerita tentang apa yg ada di dalam hati saya dan menemukan apa yang mengawali ini semua untuk bisa dipahami di perbaiki Terima kasih', '2024-03-11 20:14:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5851, 1951, 1, 'admin', 'Nora Silvana', '<p>Halo, Anggit Mardi Karim!</p> <p>Terima kasih telah menggunakan layanan konseling. Saya yakin apa yang Anda alami saat ini tentunya tidak mudah. Saya mengapresiasi keberanian Anggit karena telah memutuskan untuk mencari bantuan kepada Layanan Konseling UB. Dari uraian yang Anggit telah jelaskan sebelumnya, apakah Anggit mengetahui bahwa benar teman Anggit ini telah didiagnosa oleh profesional? Anggit bisa jelaskan sedikit seperti apa treatment yang Anggit maksud tidak seperti teman? atau contoh perlakuannya? Dan apakah Anggit sudah pernah mencoba untuk mengomunikasikan ini kepada teman Anggit?</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2024-03-11 20:16:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5852, 1949, 101785, 'mahasiswa', 'Raina Safa Vania Nova', 'Saya kurang berkenan dengan peer konselor, tp saya mau menunggu untuk dengan konselor sampai bulan april. Terimakasih', '2024-03-11 20:35:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5853, 1955, 101792, 'mahasiswa', 'Zahra Alisha Nur Saadiya', '225080207111003 Dulu saya pernah memiliki trauma yang sangat dalam namun bukan tentang percintaan dan sekarang saya lagi mengalami putus cinta dan saya merasakan rasa trauma itu kembali lagi seperti rasa tidak tenang sepanjang hari, tidak nafsu makan, tidak fokus dalam melakukan hal apapun dll', '2024-03-11 20:52:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5854, 1954, 101791, 'mahasiswa', 'Zaura Iffatutsalatsa', '1. biasanya saat sedang cerita2 dengan teman2, dan cerita tersebut masih bersangkutan dengan saya. saya benar2 lupa kejadian tersebut, padahal kejadiannya masih bisa dibilang minggu kemarinnya. lupa dengan tidak berbekas sama sekali memori kejadian tersebut. padahal bukan juga kejadian buruk/tidak mengenakkan. lalu merembet kelupaan jam2 kuliah maupun tugas. atau juga kadang ingat ceritanya, namun lupa siapa yg menceritakan tersebut ke saya 2. saat sedang berkumpul dengan teman2 dan disaat sedang saling bercerita. sudah berkali2 lupa dengan cerita2 tersebut. sampai2 saya bercanda dengan bilang "ingatan ikan dori". untuk bercandaan saja, agar teman2 saya tidak mengganggap saya bodoh. dan juga baru mulai terjadi di tahun ini di bulan februari awal 3. seingat saya tidak ada kejadian yang sangat berpengaruh kepada saya', '2024-03-11 21:43:07');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5855, 1924, 101759, 'mahasiswa', 'Laila Yelia Habib', 'Baik, terima kasih', '2024-03-11 22:53:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5856, 1947, 1, 'admin', 'Nora Silvana', '<p>Selamat sore,</p> <p>Sebelumnya mohon maaf atas keterlambatan respon dikarenakan banyaknya atrian pesan yang masuk. Baik akan saya coba bantu buatkan jadwal bersama peer counselor kami. Untuk konseling sendiri tidak dipungut biaya ya kak.</p> <p>Salam hangat,</p> <p><br /></p> <p>Tim Konseling UB</p>', '2024-03-12 16:32:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5857, 1949, 1, 'admin', 'Nora Silvana', '<p>Selamat sore,</p> <p>Baik kak, akan saya jadwalkan dengan konselor kami, dan selanjutnya akan dikonfirmasi melalui WhatsApp Admin layanan konseling UB ya kak.</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2024-03-12 16:42:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5858, 1911, 1, 'admin', 'Nora Silvana', '<p>Selamat sore,</p> <p>Baik akan saya coba bantu untuk melakukan penjadwalan koneling bersama peer counselor kami. Untuk konfirmasi selanjunya akan dilakukan melalui WhatsApp Admin layanan konseling UB.</p> <p>Salam hangat, </p> <p>Tim Konseling UB.<br /></p> <p><br /></p>', '2024-03-12 17:39:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5859, 1921, 1, 'admin', 'Nora Silvana', '<p>Sama-sama</p>', '2024-03-12 17:40:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5860, 1924, 1, 'admin', 'Nora Silvana', '<p>Selamat sore, Laila Yelia Habib!</p> <p>Mohon maaf mengganggu waktunya. Perkenalkan saya dari Layanan Konseling Mahasiswa UB.</p> <p>Terima kasih telah menggunakan layanan konseling. Silakan periksa kembali perkembangan e-ticket Anda untuk mengetahui respons dari pengajuan e-ticket yang Anda ajukan melalui cek status Ticket #001923 pada tautan <a href="https://konseling.ub.ac.id/tiket/view.php">https://konseling.ub.ac.id/tiket/view.php</a></p> <p>Silakan mengisi identitas terlebih dahulu untuk keperluan administrasi dan tautan Pre Konseling. Data akan kami rahasiakan dan digunakan hanya untuk kepentingan konseling.</p> <p><a href="https://tinyurl.com/identitasklien">https://tinyurl.com/identitasklien</a></p> <p><a href="https://bit.ly/PREKONSELING">https://bit.ly/PREKONSELING</a></p> <p>Terima kasih. Apabila ada kendala, silahkan menghubungi saya melalui pesan ini yaa. Saya tunggu jawabannya di e-ticket 1x24 jam yaa.</p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-03-12 17:41:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5861, 1954, 1, 'admin', 'Nora Silvana', '<p>Saya sangat mengerti perasaan bingung yang Anda rasakan. Terimakasih telah menjawab beberapa pertanyaan yang saya ajukan.</p> <p>Namun, dikarenakan jadwal konselor kami yang masih penuh sampai dengan awal Bulan April, apakah Anda brkenan untuk melakukan sesi konseling dengan peer counselor dari Layanan Konselin UB? Jika bersedia, mohon untuk mengirimkan 2 opsi hari dan jam, diantara hari Senin-Jumat pukul 08.00-15.00.</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2024-03-12 17:46:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5862, 1953, 1, 'admin', 'Nora Silvana', '<p>Saya sangat mengerti perasaan Anda. Terimakasih telah menjawab beberapa pertanyaan yang saya ajukan. Saya mengapresiasi Anda, karena saya tahu untuk memutuskan menggunakan layanan konseling dan berbagi cerita/kersahan Anda membutuhkan keberanian yang besar</p> <p>Namun, dikarenakan jadwal konselor kami yang masih penuh sampai dengan awal Bulan April, apakah Anda berkenan untuk melakukan sesi konseling dengan peer counselor dari Layanan Konselin UB? Jika bersedia, mohon untuk mengirimkan 2 opsi hari dan jam, diantara hari Senin-Jumat pukul 08.00-15.00.</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2024-03-12 17:52:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5863, 1955, 1, 'admin', 'Nora Silvana', '<p>Selamat sore,</p> <p>Terimakasih telah menggunakan layanan konseling UB. Saya tahu butuh keberanian yang besar untuk pada akhirnya memutuskan mengirimkan E-tiket ini. Untuk itu agar saya bisa mengerti dengan lebih baik ulasan yang Anda kirimkan, bolehkah saya meminta bantuan untuk menjawab beberapa pertanyyan berikut:</p> <p>1. Apakah trauma yang dialami sebelumnya ada keterkaitan dengan kejadian yang sekarang? misal memang memicu munculnya trauma lagi?</p> <p>2. Seperti apa perasaan tidak tenang yang dirasakan? Apakah bisa diceritakan detailnya?</p> <p>3. Apakah Anda merasa kondisi ini cukup atau bahkan sudah mengganggu aktivitas yang Anda lakukan sehari-hari? Jika iya, sejak kapan?</p> <p>Saya berharap semoga ketika balasan ini diterima, perasaan dan kondisi Anda sudah sedikit lebih baik dari sebelumnya.</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2024-03-12 18:01:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5864, 1923, 101758, 'mahasiswa', 'Benedicta Ika Ermadela', 'Baik saya bersedia konseling dengan peer counselor terlebih dahulu', '2024-03-13 07:13:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5865, 1949, 101785, 'mahasiswa', 'Raina Safa Vania Nova', 'Baik kak, terimakasih atas bantuannya', '2024-03-13 09:51:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5866, 1942, 100600, 'mahasiswa', 'Felicitia Aulia Rahma', 'Saya bersedia melakukan konseling pada Selasa, 19 Maret 2024', '2024-03-13 10:53:29');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5867, 1952, 101787, 'mahasiswa', 'Satriyo Wibowo', 'Mohon maaf baru bisa merespon, mohon izin untuk menjawab sekaligus menjelaskan, bahwasanya pada pengalaman sebelumnya, dari psikolog dan psikiater menjelaskan bahwa saya mengalami Social Anxiety Disorder. Pada saat tersebut, gejala yang saya alami cenderung berbeda dengan apa yang saya alami terakhir, dahulu saya sering mengalami black out pada situasi situasi tertentu dimana saya tidak bisa mengenali diri saya sendiri, orang disekitar saya, atau bahkan dimana saya berada pada saat itu. Dahulu emosi yang sering saya rasakan hanyalah sedih dan takut yang berkepanjangan tanpa henti, disertai dengan kondisi yang mirip dengan saat ini yaitu kepala terasa ramai. Saya sering sekali merasakan bahkan ketika saya sendiri atau saat kuliah seolah banyak suara yang bergema di dalam kepala saya. Suara tersebut bisa bermacam macam, bisa berupa suara dengungan, suara orang saling bercakap yang seolah saya mendengar seperti suara keluarga/teman dekat/dosen/orang yang saya kenali, terkadang juga suara tersebut terasa seperti suara saya sendiri. Saat suara berbicara tersebut terkadang saya merasa mendengar bahwa percakapan yang terjadi itu tidak ada hubungannya dengan saya, namun terkadang juga seolah percakapan tersebut berusaha melibatkan saya di dalamnya, sementara saya tau itu semua tidak nyata. Biasanya setelah munculnya suasana "ramai" tersebut kemudian akan disusul perasaan emosional yang meluap luap tadi. Mungkin hal itu yang bisa saya sampaikan ibuk, terimakasih banyak sebelumnya....', '2024-03-13 14:02:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5868, 1923, 1, 'admin', 'Nora Silvana', '<p>Baik, boleh tahu nggak kira-kita Anda bisa melakukan konseling di Hari dan jam berapa? Mohon memberikan 2 opsi antara hari Senin-jumat pukul 08.00-15.00 WIB.</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2024-03-13 14:05:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5869, 1942, 1, 'admin', 'Nora Silvana', '<p>Kak mohon maaf karena adanya jadwal lain dari konselor kami, apakah tidak papa jika diundur di tanggal 20 Maret pukul 14.00 WIB?</p>', '2024-03-13 14:10:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5870, 1952, 1, 'admin', 'Nora Silvana', '<p>Selamat siang,</p> <p>Saya mengerti kondisi Anda, hal tersebut pasti membuat Anda tidak nyaman. Saya tahu bukan hal yang mudah bagi Anda sampai pada akhirnya memutuskan untuk mengunakan layanan konseling UB. Terimakasih telah aware dan mengerti kebutuhan dari diri Anda.</p> <p>Kami akan coba untuk melakukan penjadwalan dengan Konselor dari layanan konseling UB. Akan tetapi apakah tidak papa jika baru bisa dilaksanakan di 27 Maret 2024? Hal ini dikarenakan antrian dan padatnya jadwal dari konselor kami.</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2024-03-13 14:20:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5871, 1952, 101787, 'mahasiswa', 'Satriyo Wibowo', 'Untuk tanggal 27 maret sendiri jadwal perkuliahan saya tidak memungkinkan apabila untuk dilaksanakan konsultasi, apabila mungkin dilaksanakan pada 28 maret apakah diperkenankan ibu? Terimakasih dan mohon maaf sekali lagi', '2024-03-13 15:03:05');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5872, 1956, 101794, 'mahasiswa', 'Hidayatus syifa', 'Nim : 225150707111045 Saya didiagnosis depresi dengan gejala psikis, gangguan kecemasan dan anoreksia nervosa. Dokter bilang harus minum obat dan konsul setiap minggu, tapi karena sebelumnya saya merasa sudah sembuh jadi tidak saya lanjutkan. Sekarang saya kambuh lagi, terkadang saya tidak bisa mendengar, jadi halusinasi, delusi dan ketakutan tanpa sebab , hal itu membuat saya tidak bisa mengerjakan tugas kuliah. Saya merasa sangat bersalah tidak mengerjakan tugas kelompok, saya sedih jadi beban kelompok, kalau saya ambil cuti atau mengundurkan diri saya juga sangat merasa bersalah kepada orangtua saya. Saya sangat takut dengan manusia, dari kecil saya sering melakukan percobaan bunuh diri tetapi tidak pernah berhasil, jika saya melakukannya lagi saya ragu akan berhasil. Saya tidak tahu harus bagaimana lagi, saya takut hidup.', '2024-03-13 19:45:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5873, 1924, 101759, 'mahasiswa', 'Laila Yelia Habib', 'Saya sudah mengisi link yang diberikan', '2024-03-14 10:10:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5874, 1919, 101757, 'mahasiswa', 'Alifah Nur Anggrainy', 'Pertama saya berterima kasih karena pihak konseling UB sudah menerima dan mencoba memahami permasalahan saya. Izinkan saya untuk menjawab pertanyaan pertama. Permasalahan keluarga saya sejujurnya cukup kompleks, dari tahun 2021 adalah awal mula perekonomian keluarga saya mulai menurun. Berlanjut hingga saat ini, dengan kondisi ekonomi yang kian tidak pasti. Ayah saya tidak bekerja, ditambah bunda saya meninggal setahun lalu tepatnya di bulan Agustus. Selama bunda masih hidup, bunda adalah tulang punggung keluarga kami. Semenjak kematiannya, ekonomi kami mulai tidak terlihat solusi pernasalahannya, semuanya terlihat buntu ditambah usia ayah saya tidak lagi usia produktif semakin mempersempit peluang kerja ayah saya. Sejujurnya, tingkat stress saya paling tinggi semenjak bunda saya meninggal, rasanya hidup saya sangat hampa. Saya tidak tau langkah apa yang saya ambil untuk kedepannya, rasanya dunia gelap gulita semenjak bunda meninggalkan saya. Motivasi saya untuk hidup terutama untuk kuliah semakin menurun, saya benar benar berada di titik terendah, saya sudah tidak tau lagi bagaimana cara saya mengatasi permasalahan saya sendiri, sehingga hal ini membuat saya sulit berpikir secara rasional dan logis. Berlanjut di tahun 2024, saya mulai mencoba beberapa hal baru. Saya sempat mengikuti kepanitiaan saat liburan, jujur saja sejenak saya merasa lebih hidup dan sedikit bersemangat. Akhirnya saya coba untuk apply pekerjaan part-time barista di salah satu cafe di kota malang. Awalnya cukup berjalan mulus, hal ini karena saya masih dalam fase trial berlanjut saya masuk ke fase training. Saya mulai kehilangan fokus dan ketelitian hal ini dikarenakan permasalahan keluarga saya merembet hingga sering ada pertengkaran di rumah, bahkan sempat uang bulanan saya terhambat hal ini menyebabkan saya sering menunda makan bahkan tidak makan sama sekali dalam sehari. sedangkan di tempat kerja, saya berusaha memaksakan diri untuk bisa bekerja dengan baik. Alhasil, saya sering melakukan kesalahan saat bekerja, saya masih belum terbiasa dengan lingkungan pekerjaan saya. Saya dikatain bodoh, dikatain tidak becus, saya merugikan teman shift saya, saya melakukan banyak kesalahan. Saya merasa tidak berguna dan merasa sangat stress, tidak ada hal yang bisa saya lakukan dengan baik. Saya juga masih belum bonding dengan teman kerja saya, hal ini menambah rasa stress saya karena saya merasa sangat kesepian di tempat kerja bahkan di tempat ramai sekalipun. Bahkan orang orang di sekitar saya mengatakan, saya terlihat sangat lelah dan terlihat banyak beban pikiran, saya merasa sudah tidak baik baik saja semenjak beberapa orang memberikan penilaian tersebut. Sehingga saya berpikir untuk mencari media yang bisa membuat saya menjadi lebih tenang, ub konseling adalah pilihan saya. Sejujurnya saya bingung menceritakan kondisi saya, karena semua hal terlalu kompleks, semua hal sangat rumit saya sulit menguraikan permasalahan sendiri. Namun, saya merasa ada permasalahan psikologis dalam diri saya, saya memiliki krcemasan yang cukup mengganggu. Kecemasan ini menggangu performa kerja saya, serta mengganggu konsentrasi saya. Saya sering tremor dan sulit fokus untuk melakukan satu pekerjaan dengan baik. Terima kasih, semoga penjelasan saya bisa membantu Anda untuk memahami kondisi saya. Saya tunggu diskusi lebih lanjut dengan pihak konseling UB, Terima kasih.', '2024-03-14 13:50:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5875, 1957, 101795, 'mahasiswa', 'Afifah Nida Ul-Haq', 'NIM: 205100300111071 Setelah melakukan seminar proposal pada 11 Januadi 2024, hingga saat ini saya belum mengumpulkan draft revisi. sejak semester 1 hingga skrg saya selalu terlibat dalam berbagai aktivitas organisasi. Di bulan Januari- 13 Februari saya terlibat sebagai Project Leader dalam perlombaan studi kasus nasional Case-A-Thon 2024. Setelah caseathon selesai, saya masih kehilangan semangat dan fokus. Saya selalu hanya berhasil duduk maximal 15 menit sehari untuk merevisi laporan saya, setelah itu buyar', '2024-03-14 18:08:05');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5876, 1958, 101795, 'mahasiswa', 'Afifah Nida Ul-Haq', 'NIM: 205100300111071 Setelah melakukan seminar proposal pada 11 Januadi 2024, hingga saat ini saya belum mengumpulkan draft revisi. sejak semester 1 hingga skrg saya selalu terlibat dalam berbagai aktivitas organisasi. Di bulan Januari- 13 Februari saya terlibat sebagai Project Leader dalam perlombaan studi kasus nasional Case-A-Thon 2024. Setelah caseathon selesai, saya masih kehilangan semangat dan fokus. Saya selalu hanya berhasil duduk maximal 15 menit sehari untuk merevisi laporan saya, setelah itu buyar', '2024-03-14 18:08:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5877, 1959, 100554, 'mahasiswa', 'Annika K Lestari', 'NIM : 215110207111004 Semua teman-teman saya yang mengenyam Ilmu Psikologi memiliki banyak kekhawatiran karena sama memenuhi semua simptom yang terjadi karena Conduct Disorder &amp; ASPD sehingga mereka meminta saya untuk melakukan konseling.', '2024-03-15 00:35:01');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5878, 1924, 1, 'admin', 'Nora Silvana', '<p>Baik, konseling akan dilaksanakan secara offline, pada hari Senin, 18 Maret 2024 pukul 10.30 WIB.  </p> <p>Berikut panduan rute menuju ruangannya:<br /><a href="https://drive.google.com/file/d/1Q6Bb9VxEfiFPOiqTQ1kIHLhQl5SFo4dx/view?usp=sharing">https://drive.google.com/file/d/1Q6Bb9VxEfiFPOiqTQ1kIHLhQl5SFo4dx/view?usp=sharing</a></p>', '2024-03-15 10:42:20');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5879, 1960, 101028, 'mahasiswa', 'Hamzah Fauzan', '215110200111026 Mohon maaf tapi ini bukan untuk saya. sama seperti sebelumnya, Deandra memiliki diagnosis depresi berat yang membuat ia harus dibawa ke RSSA untuk dirawat selama 5 hari. Waktu itu kondisinya udah parah. Namun, sekarang kondisinya yang saya lihat tidak separah dulu, jika tidak segera ditangani oleh pihak profesional, saya takutnya dia akan kembali ke fase berat seperti dulu', '2024-03-16 10:40:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5880, 1961, 101576, 'mahasiswa', 'Ade Harvey Filemon', '205090201111044 Desember lalu saya sudah sempat membuat tiket konseling seperti ini, tetapi tidak berlanjut ke pelaksanaan konseling karena saya hanya merasa nyaman apabila konseling dilaksanakan langsung secara luring di UB, tetapi pada saat itu sudah memasuki waktu libur antar semester sehingga pihak Konseling UB hanya dapat melaksanakan konseling via daring. Jika memungkinkan saya ingin melakukan konseling secara luring di UB dalam waktu dekat, saya hanya sekedar ingin curhat atau sharing secara langsung sehingga saya dapat merasa lebih lega dan tidak terus menerus memendam perasaan saya. Permasalahan saya masih sama dan saya tidak yakin ada solusi yang dapat menyelesaikannya. Salinan dari tiket saya beberapa bulan lalu: "Saya selalu merasa sendiri dimanapun saya berada. Saya ingin mendapat support dari keluarga, tetapi hal ini tidak dapat terwujud. Sejak kecil saya tinggal bersama dengan kakek dan nenek saya dari pihak Ibu karena kedua orang tua saya sudah bercerai saat saya masih kecil. Sejak kecil saya hampir tidak pernah bertemu dengan Ibu saya hingga saat ini. Setelah bercerai, Ibu dan adik saya pergi meninggalkan keluarga besar di Malang untuk hidup sendiri di Bali. Dari kedua orang tua saya, Ayah saya adalah yang lebih peduli (daripada Ibu) dan masih dapat menyempatkan diri untuk mengunjungi saya di kediaman saya dengan kakek-nenek saya. Namun, pada Mei tahun 2022 lalu Ayah saya terlebih dahulu dipanggil oleh Tuhan. Sebagain besar anggota keluarga saya sudah meninggal, saya selalu merasa sendiri dan selalu merasa ditinggal oleh keluarga. Nenek dari pihak Ayah saya sudah lama meninggal pada saat saya masih kecil. Kakek dari pihak Ayah meninggal pada saat semester awal saya kuliah di UB pada tahun 2021. Ayah saya meninggal pada tahun 2022. Dan yang baru beberapa waktu ini Kakek dari pihak Ibu saya, yang telah membesarkan saya sejak kecil, meninggal pada Oktober 2023 tahun ini. Saya anak ketiga dari empat bersaudara, tetapi kedua kakak saya telah meninggal saat masih kecil sebelum saya lahir. Walaupun Ibu dan adik saya masih hidup, saya tidak dapat berjumpa dengan mereka. Yang saya punya sekarang hanya Nenek saya dari pihak Ibu, saya sering kali merasa cemas dan khawatir jika suatu waktu akan ditinggal dari dunia ini oleh Nenek saya. Saat ini saya sering kali merasa kehilangan motivasi untuk melakukan apapun dalam hidup. Saya selalu memiliki pikiran bahwa "Lebih banyak anggota keluargaku yang menungguku di atas sana dibandingkan dengan yang mendampingiku di dunia ini.". Saya selalu merasa sendiri di dunia ini dan sering kali memiliki keinginan untuk menyusul mereka di sana." Untuk sekarang kondisi mental saya sudah agak membaik. Pada bulan Desember itu saya sempat tidak memiliki motivasi hidup (saya membuat tiket di bulan Desember itu beberapa hari setelah ada yang melakukan bunuh diri di FILKOM sehingga saya merasa terdorong dan sering terpikir "kalau dia bisa kenapa aku enggak ngelakuin juga"). Untuk sekarang saya sudah setidaknya memiliki sedikit motivasi dan tujuan untuk kedepannya yang ingin saya ceritakan ke konselor apabila saya bisa melaksanakan konseling secara luring di UB.', '2024-03-16 19:27:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5881, 1894, 101730, 'mahasiswa', 'Naurah Nadzifah Azizi', 'malam kak, mohon maaf baru membalas. saya bersedia, tapi saya menjadi tidak yakin bisa menceritakan dengan baik secara lisan. apa bisa jika hanya melalui chat saja? terimakasih', '2024-03-16 20:42:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5882, 1962, 100844, 'mahasiswa', 'Jessica Tjondro Suharto', '215130101111039 saya mengalami masalah akademik terutama tugas dan tidak dapat menyelesaikan tugas tepat waktu dan tidak bisa membagi waktu', '2024-03-17 15:06:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5883, 1942, 100600, 'mahasiswa', 'Felicitia Aulia Rahma', 'Oh iya tidak masalah kak tanggal 20 Maret jam 14.00 WIB', '2024-03-17 15:36:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5884, 1963, 101022, 'mahasiswa', 'Lailatus Sakdiyah', '205040200113038 Saya sangat kesulitan menyelesaikan skripsi', '2024-03-17 18:52:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5885, 1910, 101161, 'mahasiswa', 'Alda Meutia Ilyas', 'Sebelumnya terima kasih untul Tim Konseling UB yang sudah membalas pendaftaran konseling saya. Mohon maaf karena membutuhkan waktu untuk membalas pesan ini. 1. Apakah sebelumnya pernah mencoba mengerjakan skripsi di tempat umum seperti cafe, perpustakaan, dll? Apakah tetap merasa mengantuk? Sebelumnya saya hanya beberapa kali mengerjakan tugas akhir diluar, dan tetap mengantuk namun masih bisa ditahan. Setelah membaca respon tim konseling UB, saya mencoba untuk lebih sering mengerjakan tugas akhir di luar seperti di perpustakaan/gazebo kampus atau tempat lain. Namun, sejauh ini tidak merasakan kantuk. 2. Apakah sebelumnya memiliki target yang ingin dicapai untuk skripsi ini? Bagaimana dengan teman Anda? Apakah Anda memiliki teman yang sedang berada di fase mengerjakan skripsi dengan Anda? Saya tidak memiliki target atau timeline pengerjakaan tugas akhir. Saya memiliki teman yang juga dalam pengerjaan tugas akhir, namun tidak pernah mengerjakan tugas akhir bersama. 3. Apakah asupan hidrasi dan makan Anda teratur? Saya makan 1-2 kali sehari di jam yang tidak menentu. Asupan minum saya terbilang kurang karena satu botol air mineral ukuran 600ml bisa dihabiskan dua hari. Sebagai tambahan, jam tidur saya tidak teratur, namun durasi tidur saya rata-rata 6-8 jam. 4. Apakah Anda yakin kondisi ini disebabkan oleh rasa kantuk dan gagal fokus? Apakah setiap mengerjakan skripsi, Anda memiliki bayangan apa yang ingin Anda tulis? Saya membuat alur untuk apa yang saya akan tulis di tugas akhir dengan bantuan dosen pembimbing.', '2024-03-18 02:20:01');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5886, 1964, 101798, 'mahasiswa', 'Elisabet Pruistyn Sibarani', '235020300111088 Permasalahan keluarga, akademik, kejadian memalukan di masa lalu, perasaan tertinggal, kesepian, dan banyak faktor lainnya yang mempengaruhi pola pikir dan pola hidup saya menjadi kacau. Saya tidak mau mendiagnosa diri saya sendiri, tapi ini sudah terjadi dalam kurun 4 tahun terakhir. Saya rasa ini tidak normal. Keseharian saya selalu dikelilingi pikiran2 buruk yang menyebabkan terganggunya aktivitas keseharian saya, bidang akademik saya, dan lainnya.', '2024-03-18 03:04:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5887, 1965, 101797, 'mahasiswa', 'Nikita Carolina', '205070307111012 aku anak kesehatan dan kebetulan lagi magang di RS sekarang, aku belom bisa manage stres dan akhirnya ngaruh ke kehidupan pribadi, sama diri aku sendiri, pasangan, dan keluarga. aku jadi lebih gampang marah, nangis, sensi bgt sama pacar, dan gampang bgt ovt hal yang ga perlu dipikirin. tiap hari gada semangat buat jalanin magang dan bawaannya cape.', '2024-03-18 10:50:07');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5888, 1911, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Selamat siang, Rizki Maulana!</p> <p>Setelah saya melakukan konfimasi mohon maaf tidak ada peer counselor yang jadwalnya kosong di hari senin dan selasa minggu ini. Apakah dari Anda bisa memberikan 2 pilihan jadwal lagi kepada saya dari senin-jumat (07.30-21.00)?</p> <p>Terima kasih.</p> <p>Salam hormat,</p> <p>Tim Konseling UB</p>', '2024-03-18 15:58:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5889, 1966, 101800, 'mahasiswa', 'Aida Kireina Nadhifah', 'NIM : 235170207111046 Saya merasa pacar saya sudah bosan dengan saya? Karena sikapnya sudah tidak seperti dulu, banyak sekali pertikaian yang kami alami hanya karena temannya dan sikapnya. Terkadang dia membentak saya padahal saya hanya bercanda dan berbicara dengan perlahan. Saya benci dengan peraturan di hubungan kami yaitu "Kalo kamu berani gini, aku juga bakal lakuin hal itu". Karena ada peraturan tersebut saya mulai bersikap sebagaimana pasangan yang baik, seperti menghargai keberadaannya, berinteraksi sewajarnya dengan lawan jenis baik saat dia ada dan dia tidak ada, dan lain sebagainya. Hal tersebut sebenarnya sudah saya lakukan sebelum adanya peraturan tersebut. Saya sepertinya mulai menyesal telah mengadakan peraturan tersebut. Akhir-akhir ini kami jarang berkomunikasi, dia mulai slow respon, dan tidak menanggapi beberapa chat saya. Saya selalu berpikir, apakah saya kurang dalam hal fisik?', '2024-03-18 19:09:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5890, 1967, 101801, 'mahasiswa', 'Tedja Mukti Nugraha', '225120307111124, nyadar se lonely itu. Pernah diajak sama temen buat main keluar, tapi udah lumayan gak percaya kalo ke sananya saya hanya dijadiin cemoohan ataupun gak diajak ngobrol. Sekalinya aktif, saya yang kena cemoohan. Selain masa sekarang, masa lalu juga masih gantung, di mana saya mungkin terjerat di ketergantungan hubungan serius apa gak (di sini konteksnya nikah , tapi udah banyak red flag), hal itu bikin saya suka ragu akademik saya turun gegara hanya ngurusin masa lalu aja', '2024-03-18 20:02:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5891, 1968, 101802, 'mahasiswa', 'Muhammad Gading Budiman', 'Selamat malam. Perkenalkan saya Muhammad Gading Budiman, dengan NIM 235090707111019. Saya ingin meminta bantuannya dari bapak/ibu/kakak tingkat sekalian supaya bisa membantu atau minimal mengajak dan mencari tau permasalahan teman saya. Saya punya teman bernama Izzudin Arrifky biasa dipanggil izudin atau rifky. yang sekarang selalu mengurung diri dikamar, tidak pernah keluar rumah dan tidak pernah mengabari ibunya. Begini ceritanya, Izudin ini sudah lama tidak masuk kuliah, dari saat UTS semester satu kemarin dia sudah tidak pernah ada, dichat tidak dibalas dan kami tidak ada yang tau kos nya dimana. tiba - tiba sekitar bulan november atau desember awal, tante dari Izudin ini menanyakan kabar si izudinini ke ketua kelas kami. lalu si ketua kelas ini memberitahu ke grup angkatan dan semua kaget, karena pada awalnya kami mengira kalau dia sudah balik atau pindah ke tempat lain. Tante dari teman saya ini memberi alamat kos si Izudin. Malam itu saya beserta 4 orang teman langsung pergi ke kosnya. kami ketok dia ga keluar, kondisi kamarnya disitu gelap, lampu tidak menyala(kamarnya dipinggir jalan perumahan). inisiatif, saya lalu mengintip lewat ventilasi dengan senter juga, disitu saya melihat dia baru bangun tidur, dan dia langsung kabur ke kamar mandi begitu tau ada yang datang. selang sekian lama, akhirnya dia membalas chat salah satu teman saya yang datang kesana. isi chatnya itu memberitahu kalau dia tidak ingin keluar malam itu, namun dia berjanji kalau besok dia akan keluar. Keesokan harinya dia keluar, dan kami ajak untuk makan siang bersama teman teman lainnya. disitu yang lain semua menanyakan bagaimana kabarnya dan makan siang berlangsung asik asik saja. dia juga bisa mengikuti UAS(karena sebelumnya dia sudah mmengurus semuanya supaya bisa ikut UAS). Saat libur semester 1, saya dan izudin tidak balik ke kampung halaman. namun izudin dikunjungi oleh ibunya selama seminggu. saat ibunya pergi saya sering menemani dia, ngajak makan malam, dan mengajak dia untuk ngopi bersama teman teman yang orang asli malang. Bahkan saat itu kami menginap dirumah salah satu teman saya yang orang malang. semua baik" saja bahkan saat acara bounding angkatan 23 prodi saya di batu kemarin, si izudin ini ikut dan disana dia aman aman saja. sampai akhir" ini dia mengurung diri lagi dikamar, tidak masuk kuliah dan tidak mengabari ibunya. sekitar 2 minggu lalu, karena dia tidak pernah menjawab chat dan tidak pernah mau keluar dari kost, saya dan teman saya inisiatif untuk membuka kamarnya dengan bantuan ahli kunci dan juga sudah disetujui oleh ibunya. ketika dibuka paksa disitu dia sedang tidur dengan earphone ditelinga dan mata yang bengkak seperti habis nangis. disitu saya tanya ada apa dengan dia, dia tidak mau jawab. tapi keesokan harinya saya kesana lagi dan dia mau membuka pintu bahkan mau untuk saya ajak makan bakso. tapi beberapa hari yang lalu dia kembali mengurung diri dan tidak mengabari ibunya. saya tidak tau apa yang dia rasakan, dan bagaimana supaya dia mau bercerita, makanya saya meminta bantuan bapa atau ibu yang membaca teks ini. saya takut dia depresi dan terjadi hal yang tidak diinginkan, sekian terimakasih.', '2024-03-18 21:05:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5892, 1947, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Selamat pagi, <strong>Ardisatya Harnanda</strong>!</p> <p>Mohon maaf, untuk di kedua hari tersebut tidak ada jadwal peer counselor yang kosong. Apakah Anda bersedia di jadwal lain? Jika iya, bisa sebutkan 2 opsi jadwal kembali dari senin-jumat (07.30-21.00).</p> <p>Terima kasih.</p> <p>Salam hangat,</p> <p>Layanan Konseling UB</p>', '2024-03-19 08:58:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5893, 1894, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Boleh melalui chat, tetapi mohon maaf jika dari kami tidak bisa fast respon. Namun, kami akan mengusahakan yang terbaik untuk menemani Anda. Apakah Anda lebih nyaman melalui chat WhatsApp atau disini saja?</p> <p>Terima kasih.</p> <p>Salam hangat,</p> <p>Layanan Konseling UB.</p>', '2024-03-19 09:00:50');
