INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5895, 1969, 101804, 'mahasiswa', 'Kayra Nelvina Lilihata', 'NIM 235100500111024 Saya merasa terlalu mudah burnout saat mengerjakan tugas. Saya tidak tau apa yang harus saya lakukan agar kembali mengerjakan tugas dengan semangat. Burnout membuat saya mudah menangis dalam segala hal dan sering menangis di tempat umum. Saya merasa pasrah dengan jurusan yang saya tempuh dan memikirkan untuk mengganti jurusan lain karena saya merasa stress level di jurusan saya terlalu tinggi untuk saya', '2024-03-19 10:41:35');
