INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5911, 1947, 1, 'admin', 'Tasya Rahmani Puspa Pertiwi', '<p>Selamat siang,</p> <p>saya izin bertanya, apakah terdapat hari lain? karena sampai saat ini saya belum bisa menemukan jadwal yang cocok. Adapun untuk hari senin, apakah Anda bisa pukul 10.00 atau 15.00? karena terdapat jadwal konselor yang kosong, sedangkan hari jumat merupakan tanggal merah. Terima kasih.</p> <p>Salam hangat,</p> <p>Tim konseling UB</p>', '2024-03-20 11:13:45');
