INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5978, 1974, 101810, 'mahasiswa', 'Anisah Fa''iq Yudaisnani', '195010100111201 saya baru seminar hasil, dan saya merasa saya tidak akan bisa melewati semester ini. saya tidak yakin bahwa saya bisa menyelesaikan revisi dari dosen saya. dan satu-satunya cara untuk saya bisa lepas dari masalah ini adalah dengan saya tidak hidup. saya merasa trauma dengan dosen saya dan saya ingin membalas trauma saya ini dengan bunuh diri di depan dosen pembimbing saya.', '2024-03-21 16:56:28');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (5979, 1973, 101809, 'mahasiswa', 'Muhammad Roihan Barier', 'Saya memikirkan masa lalu. Kesalahan, trauma dan hal-hal negatif di masa lalu. Selain itu, saya juga sering terlaly mengkhawatirkan keadaan saya di masa depan.', '2024-03-21 19:54:36');
