INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6160, 1991, 101828, 'mahasiswa', 'Vincent Andrian Halim', '215130100111070 Pencemaran nama baik dan ancaman yang terjadi berulang tanpa sebab yang dilakukan oleh teman MMD dari FTP (BRAM YOS AGUSTINUS/205100507111029)', '2024-03-31 22:01:04');
