INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6195, 1967, 1, 'admin', 'Andini Laily Putri', '<p>Selamat sore, mohon maaf atas keterlambatan dalam membalas pesan. </p> <p>Baik kalau begitu, sesi konseling akan kami bantu agendakan secara online bersama dengan konselor psikolog kami yang akan dilaksanakan pasca libur lebaran. </p> <p>informasi selanjutnya akan kami sampaikan melalui Whatsapp. </p> <p>Terimakasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2024-04-04 14:14:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6196, 1995, 101832, 'mahasiswa', 'Fahdynia Karnira Gunawan', '216000101011002 sedang dalam fase ketakutan akan segala sesuatu yang dihadapi dan merasakan kesedihan yang berlebihan. hal tersebut cukup mengganggu konsentrasi dalam melakukan aktivitas akademik, tidak produktif dan waktu istirahat yang terganggu.', '2024-04-04 15:39:12');
