INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6199, 1996, 101639, 'mahasiswa', 'Ellen Oktaviona Yurianto', '225100501111006, orang tua saya (ibu) meninggal dunia dan terkadang ada hari hari dimana saya depresi berat dan mengalami kesedihan yang berlarut-larut', '2024-04-07 07:26:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6200, 1997, 101058, 'mahasiswa', 'Hanifah Insanul Mumtazah', '225090400111035 Akhir² ini merasa belum bisa maksimal di akademik dan non akademik. Terlebih sedang menjalani amanah di organisasi. Ternyata cukup sulit untuk beradaptasinya. Karena selama ini terbiasa dipimpin bukan memimpin. Selain itu partner saya juga sedang mengalami masalah yg berhubungan dengan kesehatan mental jadi saya ngerasa sering sekali membackup semuanya sendirian. Alhamdulillah banyak yg membantu namun tetap cukup berat menjalaninya. Saya mengakui bahwa saya sering overthingking, baik memikirkan ipk semester ini dengan MK yg cukup sulit menurut saya sembari memegang amanah dan juga mengikuti 2 buah perlombaan. Dan kadang masih ke-triger dengan trauma pasca op saya dan lagi² menghawatirkan masa depan walaupun sudah mulai berkurang. Jika diperbolehkan, saya ingin konsul dengan bu cici.', '2024-04-13 15:50:28');
