INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6203, 1998, 101686, 'mahasiswa', 'Islamaya Shafira', 'NIM 195020207111073 sudah lama tidak bimbingan skripsi dan minder juga bingung untuk memulai dengan dospem. bagaimana cara mencari topik skripsi dengan waktu yang terbatas? bagaimana cara menghadapi segala kemungkinan feedback dari dospem?', '2024-04-19 05:18:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6204, 1999, 101838, 'mahasiswa', 'Oklini Dwi S.', '185130101111001 Dahulu pemukulan, sekarang cara bersosialisasi dengan lingkungan seperti apa. Dengan kepercayaan dan membangun hubungan sebagai makhluk sosial kepada teman kampus, dan yang terkait laiinnya.', '2024-04-19 06:21:04');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6205, 2000, 101839, 'mahasiswa', 'Novita Angelina Carmelita', '205100501111024 Beberapa minggu ini saya tidak menyentuh skripsi, bahkan saya takut membuka filenya. Namun saya juga merasa bersalah. Saya merasa khawatir dan mulai ada tendensi untuk menyakiti diri sendiri (seperti memukul diri sendiri).', '2024-04-19 21:41:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6206, 2001, 101840, 'mahasiswa', 'Mohammad Ramadhani Dzaky Alifiansyah', '235070507111032, jatuh di akademik membuat saya berpikir ulang untuk mengikuti organisasi. Namun jika saya tidak mengikuti sebuah organisasi maupun proker lainnya juga akan berpengaruh terhadap SKK saya.', '2024-04-19 22:04:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6207, 2002, 101842, 'mahasiswa', 'Wulan Dwi Apriliani', '215120400111019 Permasalahan pribadi saya membuat saya tidak ingin hidup dan melakukan apapun lagi', '2024-04-20 12:56:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6208, 2003, 101843, 'mahasiswa', 'Zabwa Alifiah Putri Nur Aryta', '225030107111023, permasalahan saya terjadi saat saya mulai kuliah, ketika saya masuk kelas internasional, ternyata saya mudah merasa stress dan sering menangis. Dikarenakan saya selalu merasa rendah dibawah teman-teman. Saya juga mengikuti organisasi, baru-baru ini agar saya menjadi mahasiswa aktif, saya bisa membagi waktu akan tetapi ketika saya sedang stress, semuanya jadi berantakan. Saya juga memiliki masalah dengan keluarga dan itu membuat saya sering menangis.', '2024-04-20 16:31:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6209, 2004, 101844, 'mahasiswa', 'Sabrina Zainita', 'Saya sering merasa cemas berlebihan, dan kecemasan saya ini kadanv tidak beralasan. Saya sering sekali kepikiran hal-hal kecil dan banyak hal lain. Saya sering sekali merasa sangat takut. Sumber ketakutan ini kadang tidak jelas. Akan lebih parah lagi kalau saya sedang banyak kegiatan atau masalah yang menurut saya sukar untuk diselesaikan.', '2024-04-21 13:39:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6210, 1990, 101826, 'mahasiswa', 'Nabila Mauliana Anandira', 'Selamat siang, mohon maaf saya baru melihat balasan hari ini. Saya mau dijadwalkan sesi konseling dengan konselor psikolog saja apa bisa kak? Terima kasih Mohon maaf atas keterlambatan responnya', '2024-04-21 13:47:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6211, 1967, 1, 'admin', 'Nora Silvana', '<p>Selamat pagi, Tedja Mukti Nugraha!</p> <p>Mohon maaf atas keterlambatan respon, karena banyaknya antrian. Berkaitan dengan jadwal konseling, kami akan menjadwalkan konseling dengan counselor kami. Kamu bisa memberikan 2 pilihan jadwal lagi kepada kami dari senin-jumat (08.00-16.00) untuk konseling offline (08.00 - 21.00) untuk konseling online</p> <p>Terima kasih.</p> <p>Salam Hangat,</p> <p>Layanan Konseling UB.</p>', '2024-04-22 09:51:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6212, 1977, 1, 'admin', 'Nora Silvana', '<p>Benar, apakah kamu akan menjadwalkan konseling dalam waktu dekat ini? Jika iya, kamu bisa memberikan 2 pilihan jadwal kepada kami dari senin-jumat (08.00-16.00) untuk konseling offline (08.00 - 21.00) untuk konseling online<br /><br />Terima kasih.<br />Salam Hangat,<br />Layanan Konseling UB.<strong><strong><strong> </strong></strong></strong></p>', '2024-04-22 09:53:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6213, 1982, 1, 'admin', 'Nora Silvana', '<p>Selamat pagi, Dzakiyah Ufairoh!</p> <p>Mohon maaf atas keterlambatan merespon, karena banyaknya antrian. Untuk jadwal reschedule konseling, kamu bisa memberikan 2 pilihan jadwal kepada kami dari senin-jumat (08.00-16.00) untuk konseling offline (08.00 - 21.00) untuk konseling online<br /><br />Terima kasih.<br />Salam Hangat,<br />Layanan Konseling UB.</p>', '2024-04-22 09:55:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6214, 1990, 1, 'admin', 'Nora Silvana', '<p>Selamat pagi, Nabila Mauliana Anandira!</p> <p>Mohon maaf atas keterlambatan merespon, karena banyaknya antrian. Baik, kami akan jadwalkan konseling dengan konselor psikolog kami. Oleh karena itu, kamu bisa memberikan 2 pilihan jadwal kepada kami dari senin-jumat (08.00-16.00) untuk konseling offline atau (08.00 - 21.00) untuk konseling online.<br /><br />Terima kasih.<br />Salam Hangat,<br />Layanan Konseling UB.</p>', '2024-04-22 09:57:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6215, 1995, 1, 'admin', 'Nora Silvana', '<p>Selamat pagi, Fahdynia Karnira Gunawan!<br /><br />Mohon maaf atas keterlambatan merespon, karena banyaknya antrian. </p> <p>Terima kasih telah menggunakan layanan konseling. Terima kasih yaa sudah mau berbagi cerita mengenai permasalahan Anda kepada saya karena pasti segala hal yang sudah Anda rasakan dan lalui sampai saat ini tidaklah mudah. Untuk lebih memahami kondisi yang sedang Anda rasakan saat ini, bisakah Anda menceritakan lebih lanjut mengapa Anda fase ketakutan yang seperti apa yang Anda rasakan dan apa yang membuat Anda merasakan kesedihan yang berlebihan?<br /><br /></p> <p>Terima kasih.<br /><br />Salam Hangat,<br /><br />Tim Konseling UB.</p>', '2024-04-22 10:00:49');
