INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6217, 1996, 1, 'admin', 'Nora Silvana', '<p>Selamat pagi, Ellen Oktaviona Yurianto!</p> <p>Mohon maaf atas keterlambatan merespon, karena banyaknya antrian. Berkaitan dengan permasalahan yang Anda rasakan, apakah kamu membutuhkan tempat untuk bercerita terlebih dahulu? Jika iya, kami menyarankan untuk melakukan konseling dengan <em>peer counselor</em> kami terlebih dahulu. Mohon untuk konfirmasinya yaa, kami tunggu.</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2024-04-22 10:04:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6218, 1977, 1, 'admin', 'Nora Silvana', '<p>Setelah kami cek, tidak ada jadwal untuk jadwal konseling konselor pada jadwal yang kamu sebutkan. Namun, terdapat jadwal konseling konselor kami pada Rabu pukul 08.30, 10.30, dan 14.00. Apakah kamu berkenan untuk di salah satu jadwal tersebut?</p>', '2024-04-22 10:08:01');
