INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6225, 2005, 101845, 'mahasiswa', 'Kevin Aditya Prathama', 'selamat siang bapak/ ibu. saya Kevin Aditya, NIM 236060700111005. saya izin bertanya mengenai hubungan saya dengan pacar/ pasangan saya. kami tidak memiliki problem apapun selama berpacaran, tetapi saya sedang was-was dengan sifat pacar saya yang konsumtif seperti contoh ingin dibelikan ini dan itu serta memohon waktu saya dengan sangat banyak. jika tidak saya iyakan, maka pasangan saya akan berubah “mood” menjadi tidak baik. pada akhirnya ini berdampak berlahan ke mental, keuangan, penyelesaian tugas, serta hubungan antara saya dan keluarga (bapak, ibu dan adik saya). apa yang harus saya lakukan? saya tidak mau menyudahi hubungan saya dengan pacar saya, mohon arahannya. Terima kasih Pak/Bu.', '2024-04-22 12:36:54');
