INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6247, 1995, 101832, 'mahasiswa', 'Fahdynia Karnira Gunawan', 'apakah bisa di infokan dari pihak konseling pada hari Rabu, 24 April 2024 yang kosong pada jam berapa saja? atau di infokan saja minggu ini yang belum ada jadwalnya kapan, sehingga saya yang menyesuaikan.', '2024-04-22 17:58:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6248, 1995, 1, 'admin', 'Nora Silvana', '<p>Untuk jadwal konseling hari Rabu, 24 April 2024 dengan <em>peer counselor</em>, available pada pukul 08.00 atau 09.00. Apakah kamu berkenan disalah satu jadwal tersebut?</p>', '2024-04-22 18:07:59');
