INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6250, 2006, 101846, 'mahasiswa', 'Nur Indah Setiani Ningseh', '225010101111025, saya merasa tertekan di perkuliahan, tidak bisa mengikuti pelajaran dengan baik, dan kesulitan untuk bergaul, saya pernah berfikir untuk bunuh diri, saya takut tidak dapat memenuhi ekspektasi keluarga, setiap hari saya mimpi buruk.', '2024-04-23 09:19:10');
