INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6290, 2008, 101848, 'mahasiswa', 'Yericho A', 'Untuk offline senin besok pada pukul 10.00 apakah bisa ya kak?', '2024-04-25 15:41:29');
