INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6292, 2008, 21, 'admin', 'Fita Diana', '<p>Mohon maaf untuk konseling minggu depan bisa dilakukan secara online. Karena Layanan Konseling UB menyesuaikan surat edaran dari universitas, dimana minggu depan perkuliahan dilakukan secara daring karena UTBK. Apakah kamu berkenan untuk melakukan konseling onlien?</p>', '2024-04-25 16:02:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6293, 2009, 21, 'admin', 'Fita Diana', '<p>Apakah kamu berkenan untuk menjadwalkan sesi konseling dengan konselor atau <em>peer counselor</em> <em> </em>kami? Jika berkenan, kamu bisa memberikan 2 pilihan jadwal kepada kami dari senin-jumat (08.00-16.00) untuk konseling offline atau (08.00-21.00) untuk konseling online. Namun untuk konseling minggu depan, hanya bisa dilakukan secara online karena Layanan Konseling UB menyesuaikan surat edaran dari universitas dimana minggu depan perkuliahan dilakukan daring karena UTBK.<br /></p>', '2024-04-25 16:05:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6294, 2009, 101850, 'mahasiswa', 'Cahyaning Hanukarti', 'Apakah untuk besok jumat tanggal 26 April 2024 pukul 12.00 bisa?', '2024-04-25 16:28:49');
