INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6302, 2009, 21, 'admin', 'Fita Diana', '<p>Untuk hari senin, jadwal konseling available pada pukul 10.00 dan 15.00. Apakah kamu berkenan pada salah satu jadwal tersebut?</p>', '2024-04-26 10:16:11');
