INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6322, 1967, 22, 'admin', 'Nasywa Lathifa', '<p>Selamat Pagi, terimakasih telah menghubungi Layanan Konseling dan mohon maaf atas keterlambatan dalam merespon pesan. Untuk jadwal konselor kami di minggu ini sudah penuh dan tersisa pada hari Kamis, 2 April 2024 pukul 08.30 WIB secara online. Apakah Anda bersedia untuk dijadwalkan sesi pada waktu tersebut?<br /><br />Kami tunggu konfirmasinya, </p> <p>Terimakasih, </p> <p>Salam Hangat, </p> <p>Tim Konseling UB.</p>', '2024-04-29 08:42:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6323, 2016, 22, 'admin', 'Nasywa Lathifa', '<p>Selamat Pagi, Isya Rizqi!<br />Terimakasih telah menghubungi Layanan Konseling UB. Saya mengerti bahwa apa yang Anda rasakan saat ini pasti tidak mudah. Namun, untuk dapat membantu saya lebih memahami permasalahan Anda, bolehkah diceritakan sedikit apa yang sedang terjadi? atau bagaimana yang sedang Anda rasakan saat ini?<br /><br />Kami tunggu jawabannya, Terimakasih.</p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-04-29 08:45:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6324, 2017, 101861, 'mahasiswa', 'Zai Farisa', 'saya mahasiswa S2 angkatan 2020 dan semester ini sedang cuti. semester depan adalah semester terakhir saya, jika tidak lulus saya akan di-DO (jatah cuti saya sudah habis). semester 5-6 yang lalu, saya membantu penelitian dosen (hibah professor) dengan menggunakan objek penelitian saya. penelitian hibah professor tsb 80%nya saya kerjakan sendiri.. kesalahan saya adalah memakai proposal tesis saya untuk isi penelitian tsb, sehingga tesis saya dianggap plagiat penelitian hibah professor yang saya kerjakan. saya jadi stress karena harus merombak isi tesis agar tidak sama persis dengan output hibah professor yang sudah terpublish (yang atas namanya adalah dosen-dosen saya, bukan saya sendiri—padahal yang membuat adalah saya). dua semester ke belakang saya mengambil cuti. saya ada rasa ketakutan untuk asistensi tesis, karena hibah professor tsb ternyata belum selesai, sedangkan dosen pembimbing dan penguji saya adalah anggota penelitian hibah professor tsb. satu tahun ini saya menutup diri, tidak mau bertemu teman-teman, terutama teman S1/S2 karena stuck di tesis dan tidak lulus-lulus. saya butuh konseling agar semester depan saya bisa menyelesaikan studi saya.. *sebelumnya aaya ada riwayat konseling ke psikolog &amp; psikiater, dan didiagnosa depresi ringan', '2024-04-29 10:15:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6325, 2017, 22, 'admin', 'Nasywa Lathifa', '<p>Selamat Siang, <strong>Zai Farisa!</strong></p> <p>Terimakasih telah menghubungi Layanan Konseling UB. Saya dapat memahami kondisi yang Anda alami saat ini bukanlah hal yang mudah.  untuk membantu saya memetakan permasalahan Anda, kami membutuhkan kerjasama untuk menjawab beberapa pertanyaan berikut : </p> <p>1. Untuk saat ini, apa hal yang Anda rasa paling sulit dihadapi untuk kembali melanjutkan pengerjaan tesis?</p> <p>2. Apakah Anda telah melakukan konsultasi kepada dosen pembimbing mengenai permasalahan tesis yang Anda alami tersebut?</p> <p>3. Harapan apa yang Anda inginkan setelah melakukan konseling dengan Layanan Konseling UB. </p> <p>4. Tadi Anda menyebutkan pernah berkonsultasi dengan psikolog, kapan waktu terakhir Anda mengunjungi psikolog tersebut?</p> <p>Kami tunggu responnya, </p> <p>Terimakasih, </p> <p>Salam Hangat, </p> <p>Tim Konseling UB.</p>', '2024-04-29 12:11:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6326, 1982, 22, 'admin', 'Nasywa Lathifa', '<p>sudah selesai</p>', '2024-04-29 12:12:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6327, 1987, 22, 'admin', 'Nasywa Lathifa', '<p>Klien telah berhasil menyelesaikan masalahnya sendiri. </p>', '2024-04-29 12:13:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6328, 2005, 22, 'admin', 'Nasywa Lathifa', '<p>tidak terdapat balasan</p>', '2024-04-29 12:13:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6329, 2018, 101862, 'mahasiswa', 'Faris Wafiq', 'Waktu covid dapat diagnosa bipolar 2 akan tetapi sepertinya hanya depresi berat saja, sekarang sudah dapat kuliah seperti biasa hingga mulai skripsi (semester ini) tanpa terasa stress berat seperti dulu. Akhir-akhir mulai magang di salah satu Non-profit di Malang dan sudah berjalan hampir 3 bulan. Akhir-akhir ini saya merasa kalau saya cukup kesusahan untuk mengontrol emosi jika sesuatu tidak berjalan seperti seharusnya dan emosi saya tetap berada di tubuh saya cukup lama (1minggu+) saya ingin belajar cara kontrol diri yang bagus agar ketika saya kerja nanti saya dapat bekerja tanpa merasa kehilangan kendali atas diri sendiri. Selain kontrol mungkin saya ingin belajar bagamaina cara agar emosi yang ada di diri sendiri dapat cepat dihilangkan atau diselesaikan. Faris Saifuddin Wafiq (185120307111008)', '2024-04-29 13:36:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6330, 2019, 100179, 'mahasiswa', 'Erika', 'Merasa putus asa karena skripsi dan sudah banget untuk ketemu dosen sedangkan teman teman sudah berada di titik terjauh dan merasa tertinggal.', '2024-04-29 18:24:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6331, 2018, 22, 'admin', 'Nasywa Lathifa', '<p>Selamat Malam, <strong>Faris Wafiq!<br /><br /></strong>Terimakasih telah menghubungi Layanan Konseling UB. saya sangat mengapresiasi bagaimana Anda telah cukup memperhatikan kondisi emosi yang Anda miliki. Anda juga sudah selangkah lebih maju karena memiliki dorongan untuk belajar kontrol emosi yang baik guna keberlangsungan hidup Anda selanjutnya. Kalau begitu apakah Anda hendak melakukan konseling bersama dengan Peer Konselor kami? Jika iya, silahkan ajukan dua opsi jadwal pada rentang hari Rabu-jumat (08.00-21.00) secara online dikarenakan masih pekan UTBK. <br /><br />Kami tunggu tanggapan Anda,</p> <p>Terimakasih, </p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-04-29 18:33:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6332, 2019, 22, 'admin', 'Nasywa Lathifa', '<p>Selamat Malam, <strong>Erika</strong>!</p> <p>Terimakasih telah menghubungi Layanan Konseling UB. Saya mengerti bagaimana urusan akademik bukanlah hal yang mudah untuk dijalani utamanya berhubungan dengan tugas akhir perkuliahan. Jika Anda berkenan, bolehkan Anda ceritakan lebih lanjut bagaimana kendala yang Anda hadapi mengenai permasalahan Anda tersebut? Apa yang membuat Anda merasa putus asa terkait tugas akhir perkuliahan ini? <br /><br />Kami tunggu jawabannya 1x24 jam yaa</p> <p>Terimakasih,</p> <p>Salam Hangat, </p> <p>Tim Konseling UB.<br /></p>', '2024-04-29 18:38:07');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6333, 2019, 100179, 'mahasiswa', 'Erika', 'Saya merasa putus asa karena memang dosen pembimbing kedua saya sangat susah sekali untuk ditemui dan sangat sulit membalas pesan. Sedangkan waktu terus berjalan bahkan tinggal 2 bulan lagi semester ini selesai dan bahkan saya belum semhas sama sekali dari bulan Maret setelah penelitian. Saya merasa tertinggal dengan teman teman saya yang saya lihat di sosial media sudah semhas, kompre, bahkan sudah yudisium. Saya juga bukan orang yang dengan latar belakang mampu. Bahkan di semester ini saya telah berjanji dengan orang tua saya untuk bisa menyelesaikan semua di semester ini dan kenyataan nya tidak seperti yang saya pikirkan', '2024-04-29 18:41:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6334, 1967, 101801, 'mahasiswa', 'Tedja Nugraha', '2 mei kah kak itu maksudnya?, iya 2 mei boleh kak online', '2024-04-29 21:01:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6335, 2020, 101865, 'mahasiswa', 'Ratri Mufidah', 'Sering sulit tidur, jam tidur malam tertukar dgn tidur siang, tidur malam kebangun tidak bisa lanjut tidur lagi, selalu ngigau dan tersadar sendiri Tapi saya merasa ini akibat dari beberapa masalah yg tidak bisa saya pahami sendiri karena sering tiba-tiba menangis padahal tidak ada yg mengganggu di waktu tersebut Sudah bertahun-tahun saya merasa ada yg salah dari diri saya tapi tidak pernah berani untuk bilang ke siapapun karena pernah sekali membahas sedikit, justru disuruh untuk diam hingga saya memendam semua sendiri sejak SD/SMP Saya hanya ingin tahu sebenarnya saya kenapa, apa yg salah dari diri saya', '2024-04-30 09:20:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6336, 1967, 22, 'admin', 'Nasywa Lathifa', '<p>Selamat Siang, </p> <p>Mohon maaf atas kekeliruan saya, benar 2 Mei 2024. Baik, jika Anda bersedia. Selanjutnya akan saya hubungi melalui Whatsapp yaa. Mohon ditunggu.</p> <p>Terimakasih, </p> <p>Tim Konseling UB.<br /></p>', '2024-04-30 11:11:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6337, 2020, 22, 'admin', 'Nasywa Lathifa', '<p>Selamat siang, Ratri Mufidah!</p> <p>Terimakasih telah menghubungi Layanan Konseling UB. Saya mengerti apa yang Anda rasakan pasti bukanlah hal yang mudah. Untuk memudahkan saya memahami apa yang sedang terjadi, bolehkan diceritakan lebih lanjut apa hal yang sedang mengganggu pikiran Anda akhir ini yang menyebabkan Anda kesulitan untuk tidur? <br /><br />Kami tunggu jawabannya 1x24 jam yaa.</p> <p>Salam Hangat, </p> <p>Terimakasih,</p> <p>Tim Konseling UB.</p>', '2024-04-30 11:25:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6338, 2019, 22, 'admin', 'Nasywa Lathifa', '<p>Terimakasih Erika atas respon mengenai pertanyaan yang saya ajukan sebelumnya. Dari penjelasan Erika, saya lihat banyak faktor eksternal yang terjadi sehingga menghambat proses skripsi mu yaa? Saya paham jika Anda merasa bingung dan cemas akan hal ini. Kalau begitu apakah Anda ingin saya bantu untuk melakukan konseling online bersama Peer Konselor kami pada rentang waktu Kamis atau Jumat minggu ini? kalau iya, silahkan ajukan 2 opsi waktu (08.00-20.00) pada kedua hari tersebut. <br /><br />Terimakasih,</p> <p>Salam Hangat, </p> <p>Tim Konseling UB.</p>', '2024-04-30 11:29:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6339, 1967, 22, 'admin', 'Nasywa Lathifa', '<p>sudah dihubungi melalui whatsapp dan dijadwalkan dengan konselor psikolog pada kamis minggu ini</p>', '2024-04-30 11:30:54');
