INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6461, 2050, 23, 'admin', 'Shafa Fatin Ahmad', '<p dir="ltr">Selamat malam, Samuel Wilson!</p> <p dir="ltr">Terima kasih telah menggunakan layanan konseling. Mohon maaf atas keterlambatan respons akibat panjangnya antrian. Saya yakin apa yang Anda alami saat ini tentunya tidak mudah, tetapi saya mengapresiasi Anda karena sudah berani menceritakan apa yang Anda rasakan di layanan konseling UB ini karena artinya Anda <em>aware</em> dengan kondisi diri Anda sendiri. Saya izin bertanya mengenai beberapa hal untuk membantu memetakan permasalahan Anda dan mendiskusikan cara yang bisa dilakukan untuk mengatasi hal tersebut:</p> <p dir="ltr">1. Hal apa yang paling membuat Anda merasa <em>overthinking</em>?</p> <p dir="ltr">2. Permasalahan apa yang terdapat di keluarga dan asmara yang membuat Anda <em>overthinking</em>?</p> <p dir="ltr">3. Apa yang Anda pikirkan mengenai karier Anda sebagai mahasiswa? Apakah jurusan dan kegiatan yang Anda lakukan saat ini di perkuliahan sesuai dengan minat dan rencana Anda?</p> <p dir="ltr">Terima kasih.<br /></p> <p dir="ltr">Salam Hangat,</p> <p dir="ltr">Tim Konseling UB.<br /></p>', '2024-05-14 02:43:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6462, 1898, 23, 'admin', 'Shafa Fatin Ahmad', '<p>Oke baik terima kasih atas informasinya. Saya akan jadwalkan terlebih dahulu ya dengan peer counselor kami.</p> <p>Terima kasih.</p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-05-14 02:45:14');
