INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6497, 2054, 101903, 'mahasiswa', 'Almira Nurhemina', 'Hmmmm btw btw kalo saya stress" gini biasanya hobinya menghabiskan uang. Kalo ga chekout shopee yaa jajann. Iyaa syress nya ilang sekilas. Tapi abistuh stress lagi karena uangnya habisss. Huwaaaaaaa capeeeee bangetttt', '2024-05-15 21:49:20');
