INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6571, 2070, 101445, 'mahasiswa', 'Sevilla Karimia', 'Halo pak/bu, sebenernya aku ngga ada permasalahan yang begitu serius. Tapi aku cuma pengen cerita krn gada tempat buat cerita &amp; aku pengen nangis lagi. Akhir2 ini rasanya bener2 berat banget, semuanya dipendem sendirian dan makin hari makin berat banget. Aku gamau ini terus2an, aku pengen ngeluarin semuanya dan cari cara gimana biar aku bisa nangis lagi.... Rasanya sesek banget saking capenya tapi gak bisa nangis, malah berefek ke yg lain', '2024-05-18 10:16:12');
