INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6573, 2054, 101903, 'mahasiswa', 'Almira Nurhemina', 'Sayaa takut kesepiannn, saya sangat sangat takutt. Saya pengen bertemu seseorang, tapi saya orangnya nyusahinnn. Tolongin sayaaaaa. Saya nulis ini sambil nangiss. Saya cuma pengen sembuh.', '2024-05-18 13:15:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6574, 2054, 101903, 'mahasiswa', 'Almira Nurhemina', 'Semua orang jahat kali ini. Tidak, tidak mereka tidak jahat. Harusnya saya yang jahat. Saya yang memaksakan keadaan dan lain sebagainya. Saya hanya ingin bertemu, bermain, dan bercerita bersama mereka. Tapi mereka pasti cape, mereka butuh me time. SAYA GATAU. SAYA GA BUTUH ME TIME. SAYA STRESS SENDIRIAN, SAYA GILAAA HUWAA. SAYA NANGIS. SAYA KESEPIAN, SAYA INGIN MEMAKSA SESEORANG UNTUK 24 JAM BERSAMA SAYAA. TOLONGGGG!', '2024-05-18 13:43:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6575, 2054, 101903, 'mahasiswa', 'Almira Nurhemina', 'Saya aneh, saya gabisa sendirian. Saya orangnya nyusahin. Hehehe', '2024-05-18 13:43:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6576, 2071, 101920, 'mahasiswa', 'Valentina Wahyudi', 'Saya telah hampir 2 minggu lebih ini merasa bahwa saya tidak memiliki seseorang untuk saya dapat bercerita dan memahami kondisi saya setiap harinya apabila setelah seharian melakukan aktivitas. Sebenarnya perasaan tersebut telah sering terjadi beberapa kali sebelumnya dengan siklus 2-4 minggu sekali saya merasa energi saya sedang tinggi seperti bisa melakukan apa pun sendiri (saya merasa tidak perlu bercerita ke siapa pun tidak apa-apa), namun kemudian saya merasa seperti yang saya sebutkan pada kalimat pertama selama 2-4 minggu juga. Namun, pada kondisi saat ini, saya merasa sangat ''sendiri'' hingga selalu berpikiran "kapan ya punya orang? masa sudah hampir 5 tahun siklusnya seperti ini?" terlebih lagi jika mendengarkan cerita teman-teman saya yang setiap hari dapat berkomunikasi dengan pasangannya masing-masing. Mengetahui hal tersebut semakin membuat saya hilang kendali seperti menangis dengan jantung berdebar, seluruh ujung jari dingin, tremor, merinding, hingga menyakiti diri sendiri.', '2024-05-18 15:49:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6577, 2049, 101897, 'mahasiswa', 'Gregorius Banu', 'Maaf saya baru sempat membalas Bu/Pak. Izin untuk menjawab beberapa pertanyaan yang sudah diberikan 1. Saya masih berkomunikasi dengan dia, tetapi sudah mengurangi intensitasnya secara drastis (sekarang seperlunya saja) &amp; memblokir account WA. Jadi, untuk reach out pas ada perlu hanya via DM instagram aja 2. Hmmm hal yang pernah saya lakukan dulu itu coba ngedeketin dia sih, sekitar ±10 bulan yang lalu. Itupun juga dgn cara yang baik &amp; sopan 3. Untuk di lingkungan perkuliahan, saya sudah tidak punya lagi karena teman2 saya sudah lulus. Untuk diluar lingkup kuliah, ada &amp; saya cukup sering cerita kepada mereka apabila ada masalah. Tetapi saya tidak terlalu ingin membebankan kepada mereka juga. Terima kasih sebelumnya Pak/Bu', '2024-05-18 15:52:17');
