INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6579, 2072, 101281, 'mahasiswa', 'Markus Batuara', 'Nim saya 235030107111119. Baru-baru ini saya merasa kehilangan fokus dan semangat pada semua hal yang bahkan biasanya saya suka melakukannya seperti bermain gitar yang saya biasanya jika bermain gitar merasa jadi semangat lagi ini malah tidak. Kadang perasaan tadi juga disertai kegelisahan dan kecemasan yang tidak bisa saya kontrol.', '2024-05-19 06:31:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6580, 2031, 21, 'admin', 'Fita Diana', '<p>sudah dihubungi melalui WhatsApp dan dijadwalkan konseling</p>', '2024-05-19 11:49:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6581, 2042, 21, 'admin', 'Fita Diana', '<p>Mohon maaf atas keterlambatan respon, karena banyaknya antrian. Baik, terima kasih ya sudah mau berbagi cerita mengenai permasalahan yang sedang kamu rasakan. Apakah kamu berkenan untuk menjadwalkan sesi konseling dengan <em>peer counselor </em>kami? Jika berkenan, kamu bisa memberikan 2 pilihan jadwal kepada kami dari senin-jumat (08.00-16.00) untuk konseling offline atau (08.00-21.00) untuk konseling online. </p> <p>Kami tunggu konfirmasinya yaa..<br /><br />Terima kasih,<br />Salam Hangat,<br />Layanan Konseling UB.</p>', '2024-05-19 11:55:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6582, 2048, 21, 'admin', 'Fita Diana', '<p>Saya paham apa yang kamu rasakan saat ini, memang tidak mudah untuk bisa mengatasi permasalahan tersebut secara bersamaan. Oleh karena itu, saat ini kamu bisa mulai memperbaiki permasalahan yang kamu alami secara bertahap. Dimana kamu bisa mencoba melakukan hal-hal berikut untuk bisa mengatasi permasalahan yang kamu alami saat ini</p> <p>1. Saat ini orang disekitar yang suka JKT48 masih bisa memanusiakan kamu dan berbeda dengan mantan atau masa lalu kamu, sehingga kamu hanya tidak nyaman saat orang tersebut memposting hal apapun mengenai JKT48. Kamu bisa untuk membatasi postingan teman kamu yang suka JKT48 agar postingannya tidak terlalu sering muncul di media sosial kamu. Misalnya, membatasi munculnya story ig atau whatsapp dengan meng-hide. Hal tersebut bisa kamu coba untuk lakukan dan kamu dapat merasakan bagaimana efeknya. Jika memiliki efek yang baik bagi kamu, maka kamu bisa melanjutkan melakukannya yaa.</p> <p>2. Kamu hebat karena sudah tetap berusaha semaksimal mungkin meningkatkan kualitas diri kamu dan berdamai dengan masa lalu. Kamu harus tetap bisa berperilaku seperti itu untuk bisa membuktikan pada orang-orang yang pernah membully kamu, bahwa kamu bisa menjadi orang yang mempunyai potensi yang tinggi. Hal tersebut bisa berdampak positif bagi kamu, orang disekitarmu, dan pastinya keluargamu.</p> <p>3. Karena kamu lebih nyaman di panggil "Nana", mungkin akan banyak orang baru yang akan memanggil kamu dengan nama lengkap kamu. Sehingga kamu bisa untuk menjelaskan pada orang tersebut untuk bisa memanggil kamu dengan "Nana" agar orang-orang mengetahui secara jelas. Meskipun nantinya orang baru (orang yang belum tau panggilan nama kamu "Nana"), kamu harus bisa tetap untuk menerima karena identitas awal kamu adalah nama lengkap kamu. Nama lengkap yang diberikan oleh orang tua kamu sebagai doa. </p> <p>Semoga dapat membantu ya Nana, kamu bisa bercerita lagi semau kamu. tetap semangaatt^^</p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-05-19 12:36:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6583, 2052, 21, 'admin', 'Fita Diana', '<p>Mohon maaf atas keterlambatan respon, karena banyaknya antrian. Kamu berkenan untuk melakukan konseling secara offline atau online?</p>', '2024-05-19 12:39:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6584, 2054, 21, 'admin', 'Fita Diana', '<p>Mohon maaf atas keterlambatan respon, karena banyaknya antrian. Baik, apakah kamu berkenan untuk melakukan konseling dengan <em>peer counselor </em>kami? Dan untuk konselingnya kamu berkenan secara offline atau online?</p>', '2024-05-19 12:43:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6585, 2060, 21, 'admin', 'Fita Diana', '<p>Mohon maaf atas keterlambatan respon, karena banyaknya antrian. Baik, terima kasih ya sudah mau berbagi cerita mengenai permasalahan yang sedang kamu rasakan. Kamu berkenan untuk menjadwalkan sesi konseling dengan <em>peer counselor</em> atau konselor kami? <br /><br />Terima kasih,<br />Salam Hangat,<br />Layanan Konseling UB.</p>', '2024-05-19 12:46:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6586, 2063, 21, 'admin', 'Fita Diana', '<p>Mohon maaf atas keterlambatan respon, karena banyaknya antrian.</p> <p>Saya paham apa kamu kamu rasakan, pasti tidak mudah mengalami permasalahan tersebut. Pada saat kamu merasakan hal tersebut, biasanya apa yang kamu lakukan? Kemudian kamu menjelaskan bahwa ada yang salah dari diri kamu, apakah informasi tersebut kamu ketahui dari teman-teman kamu yang mengatakan bahwa kamu salah atau kamu hanya mengira-ngira bahwa kamu yang salah?</p>', '2024-05-19 12:56:46');
