INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6658, 2076, 101923, 'mahasiswa', 'Syahnaya R', 'terimakasih banyak, tim konseling! untuk menceritakan lebih lanjut, aku mulai merasakan masalah ini kurang lebih sekitar satu tahun yang lalu, tapi entah kenapa akhir akhir ini aku merasa kalau hal itu menjadi lebih buruk di semester ini. aku selalu merasa kalau terkadang seperti ada tembok yang menghalangi aku dan teman-temanku, dan jika memikirkan itu aku seperti merasa anxious, takut, dan tidak jarang juga ada rasa seperti sakit di dada', '2024-05-23 18:00:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6659, 2082, 101932, 'mahasiswa', 'Ignatius wijaya', 'Saya menyadari bahwa saya orang yang pemalas, sulit untuk berubah, jadi banyak pekerjaan yang tertunda dan terus tertunda yang membuat saya tidak produktif', '2024-05-24 00:25:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6660, 2083, 101933, 'mahasiswa', 'Putri Dewi', 'Semester ini saya merasa bahwa mengalami penurunan minat dalam akademik. Seperti jadi sering membolos ke kampus.', '2024-05-24 10:54:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6661, 2076, 21, 'admin', 'Fita Diana', '<p>Saya paham apa yang kamu rasakan saat ini, pastinya tidak mudah berada pada kondisi seperti ini. Apakah sebelumnya sudah pernah membicarakan mengenai permasalahan ini dengan teman kamu? Atau setidaknya teman-teman kamu tau dan peka jika kamu menarik diri dari lingkup pertemanan?</p>', '2024-05-24 13:38:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6662, 2078, 21, 'admin', 'Fita Diana', '<p>Mohon maaf sebelumnya, karena hari jumat merupakan cuti bersama maka Layanan Konseling UB juga menyesuaikan hari libur nasional tersebut. Sehingga kamu bisa menjadwalkan sesi konseling untuk minggu depan, nantinya akan saya bantu untuk mencari jadwal yang cocok. Sekedar mengkonfirmasi, kamu bersedia untuk melakukan konseling dengan konselor atau <em>peer counselor</em> kami?<br /></p>', '2024-05-24 13:40:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6663, 2082, 21, 'admin', 'Fita Diana', '<p>Selamat siang, Ignatius rajendra wijaya!</p> <p>Terima kasih telah menggunakan layanan konseling. Terima kasih yaa sudah mau berbagi cerita mengenai permasalahan Anda kepada saya karena pasti segala hal yang sudah Anda rasakan dan lalui sampai saat ini tidaklah mudah. Untuk lebih memahami kondisi yang sedang Anda rasakan saat ini, bisakah Anda menceritakan lebih lanjut permasalahan apa yang terjadi pada diri Anda mengenai penyebab kemalasan yang kamu rasakan? Sejak kapan kamu merasa bahwa permasalahan ini mulai terjadi? Hal ini digunakan untuk memetakan permasalahan Anda untuk dilakukannya konseling bersama konselor atau <em>peer counselor</em> jika kamu menginginkan ^^</p> <p><br /></p> <p>Terima kasih,<br />Salam Hangat,<br />Tim Konseling UB.</p>', '2024-05-24 13:42:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6664, 2083, 21, 'admin', 'Fita Diana', '<p>Selamat siang, Putri Kumala Dewi!</p> <p>Terima kasih telah menggunakan layanan konseling. Terima kasih yaa sudah mau berbagi cerita mengenai permasalahan Anda kepada saya karena pasti segala hal yang sudah Anda rasakan dan lalui sampai saat ini tidaklah mudah. Untuk lebih memahami kondisi yang sedang Anda rasakan saat ini, bisakah Anda menceritakan lebih lanjut permasalahan apa yang terjadi pada diri Anda mengenai penyebab Anda sering membolos ke kampus? Apakah karena pertemanan/keluarga/lainnya? Sejak kapan kamu merasa bahwa permasalahan ini mulai terjadi? Hal ini digunakan untuk memetakan permasalahan Anda untuk dilakukannya konseling bersama konselor atau <em>peer counselor</em> jika kamu menginginkan ^^</p> <p><br /></p> <p>Terima kasih,<br />Salam Hangat,<br />Tim Konseling UB.</p>', '2024-05-24 13:44:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6665, 2078, 101928, 'mahasiswa', 'Muhammad Zuhdi', 'baiklah jika hari ini sedang libur saya mengajukan jadwal konseling pada hari senin di jam 08.00 apakah bisa? serta saya belum mengetahui perbedaan dari konselor dengan peer counselor, bisa dijelaskan terlebih dahulu apa perbedaan dari kedua istilah tersebut?', '2024-05-24 13:51:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6666, 2078, 21, 'admin', 'Fita Diana', '<p>Jika dengan konselor nanti akan dilakukan konseling bersama dosen, namun jika dengan <em>peer counselor</em> nanti akan dilakukan konseling dengan mahasiswa</p>', '2024-05-24 13:53:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6667, 2078, 101928, 'mahasiswa', 'Muhammad Zuhdi', 'apakah mahasiswa atau dosen ini sangat kompeten dalam bidang konseling? maksud saya apa latar belakang dari mahasiswa atau dosen ini sesuai dengan bidang konseling?', '2024-05-24 13:56:29');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6668, 2078, 21, 'admin', 'Fita Diana', '<p>Betul, untuk konselor sendiri sudah ahli dibidangnya dan konselor merupakan psikolog dalam masing-masing bidangnya. Kemudian jika mahasiswa juga sudah mendapatkan pelatihan dari Layanan Konseling UB untuk bisa melakukan konseling </p>', '2024-05-24 13:58:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6669, 2078, 101928, 'mahasiswa', 'Muhammad Zuhdi', 'Owhh baik kalau begitu saya memilih konselor saja untuk kegiatan konseling nanti, apakah bisa?', '2024-05-24 14:03:38');
