INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6789, 2091, 101940, 'mahasiswa', 'Eirene', '<p>Halo, harapan saya dari konseling ini mungkin lebih ke arah rekomendasi cara meregulasi emosi yang baik dilakukan. Ya, saya berkenan untuk dijadwalkan sesi konseling dengan peer counselor.</p>', '2024-06-03 16:08:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6790, 2071, 24, 'admin', 'Agnes Damarela', '<p>Berikut RUTE menuju ruangan konseling </p> <p><a href="https://drive.google.com/file/d/1Q6Bb9VxEfiFPOiqTQ1kIHLhQl5SFo4dx/view?usp=sharing">https://drive.google.com/file/d/1Q6Bb9VxEfiFPOiqTQ1kIHLhQl5SFo4dx/view?usp=sharing</a></p>', '2024-06-03 19:35:52');
