INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6836, 2046, 21, 'admin', 'Fita Diana', '<p>Selamat sore, mohon maaf atas keterlambatan merespon karena banyaknya antrian.</p> <p>Semoga sekarang kamu dalam keadaan baik yaaa^^ apabila kamu merasa membutuhkan konseling, saya akan membantu untuk menjadwalkan sesi konselingnya</p>', '2024-06-15 16:42:36');
