INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6904, 2125, 101967, 'mahasiswa', 'Kurnia', '<p>Saya sejak awal mau berenti kuliah di jurusan ini. Tapi karna masalah keuangan dan masalah tanggung jawab saya terpaksa harus lanjut. Saya juga hanya anak kip kuliah. Saya takut nanti gimana2. Saya takut lulus nggak tepat waktu karna kalau nambah semester bayar ukt sendiri. Kalau lanjut keluargaku nggak mampu membiayai. Aku takut. Tiap hari ku dipenuhi oleh rasa khawatir yang berlarut larut. Membuatku sangat sakit kepala. Mau kabur tapi nggak bisa rasanya. Ya Allah, kapan penderitaan ku ini selesai???<br /></p>', '2024-06-16 15:14:12');
