INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6917, 2121, 101927, 'mahasiswa', 'Farhan Rosyadi', '<p>Saya mungkin memilih jadwal konseling pada hari Kamis jam 13.00 secara luring (offline) berkenaan dengan selesainya ujian akhir saya. Apakah boleh?</p>', '2024-06-18 18:44:49');
