INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (6993, 2133, 24, 'admin', 'Agnes Damarela', '<p>Baik, saya akan coba bantu buatkan jadwal dengan konselor kami ya kak. Nanti akan diinformasikan lebih lanjut melalui WA admin.</p> <p>Terimakasih</p>', '2024-06-25 12:14:06');
