INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7014, 2141, 100041, 'mahasiswa', 'Alya Salma', '<p>Selamat sore, Ibu/Bapak.</p> <p>Terima kasih atas kesempatannya. Saya akan mengikuti jadwal konsultasi pada hari Rabu sesi 10.30-11.30 dan Kamis 08.30-09.30.</p> <p>Hormat saya,</p> <p>Alya Sonia Salma</p>', '2024-06-26 15:50:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7015, 2140, 101978, 'mahasiswa', 'Brilian trismienantha', '<p>Halo, terima kasih atas responnya. Betul, saya masih mahasiswa aktif brawijaya namun masa studi saya sudah hampir selesai dan dalam proses yudisium-wisuda<br /></p> <p><br />untuk jadwal apakah berkenan di hari kamis atau senin? Saya cukup fleksibel dengan jadwal untuk saat ini dan preferensi saya adalah secepatnya. Thank you!<br /></p>', '2024-06-26 19:40:01');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7016, 2142, 101980, 'mahasiswa', 'Tiffania', '<p>saat ini saya sedang merasa sangat capek atas semua hal yang membuat saya sering marah sampai tidak terkontrol, terkadang tiba-tiba merasa senang, tiba-tiba sedih. Saya adalah tipe orang yang apapun keinginan saya harus berjalan sesuai kehendak saya tetapi tetap atas usaha saya sendiri, apabila tidak sesuai maka saya akan menuntut penjelasan dan marah, saya tahu hal tersebut buruk, tapi saya sangat sulit mengendalikannya. Saya tipe orang yang suka memendam perasaan, sulit terbuka kepada orang lain karena banyak orang yang mengandalkan saya sehingga saya tidak boleh lemah. Saya merasa tidak bisa menyampaikan apa yang saya rasakan kepada orang lain, kemudian saya menyampaikan apapun itu tutur katanya selalu berantakan, saya kurang percaya diri, maka dari itu saya lebih suka menjadi pendengar. Pada orang lain yang tidak terlalu mengenal saya mungkin merasa saya baik-baik saja, diam, dan cukup sabar. Tetapi pada orang yang dekat dengan saya tidak sering mereka terkena imbas ketika emosi saya tidak stabil seperti itu, setelah saya marah-marah biasanya saya menyesal, tapi saya sulit mengendalikan keadaan tersebut. Saya bingung harus bagaimana..</p>', '2024-06-26 19:54:46');
