INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7076, 2154, 101986, 'mahasiswa', 'Sayyidatu Alkubro', '<p>Setelah hasil diskusi ternyata program PKM tidak dapat dibuka lagi, sebenarnya besar harapan saya apabila bisa mengikuti susulan PKM, walaupun saya harus berangkat sendiri tanpa difasilitasi kampus pun tak apa.</p>', '2024-07-04 13:41:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7077, 2154, 23, 'admin', 'Shafa Fatin Ahmad', '<p>Halo, Sayyidatu!</p> <p>Sayyidatu, setelah mendengar kabar tersebut apa yang Sayyidatu rasakan saat ini? Apakah Sayyidatu ingin melakukan sesi konseling terlebih dahulu?</p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-07-04 13:57:32');
