INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7160, 2164, 22, 'admin', 'Nasywa Lathifa', '<p>Selamat sore, </p> <p>Mohon maaf, untuk tanggal dan waktu yang Anda ajukan sudah termasuk H-1 pelaksanaan konseling sehingga kami belum bisa bantu untuk jadwalkan. Apakah Anda berkenan jika sesi konseling dilaksanakan pada pekan depan? </p> <p>Terimakasih,</p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-07-11 17:43:12');
