INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7167, 2160, 22, 'admin', 'Nasywa Lathifa', '<p>Selamat siang, Alula!</p> <p>Baik, akan saya bantu carikan konselor yang tersedia pada waktu yang Anda ajukan ya. Kemudian, apakah Anda berkenan melakukan konseling secara online/offline?</p> <p>Kami tunggu konfirmasi Anda.</p> <p>Terimakasih,</p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-07-12 12:09:29');
