INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7169, 2163, 22, 'admin', 'Nasywa Lathifa', '<p>Selamat siang, Ellen!</p> <p>Mengenai pertanyaan Anda tersebut, batas akhir konfirmasi adalah H-2 pelaksanaan sesi konseling. Sehingga, Anda dapat menghubungi kami kembali apabila Anda telah memiliki waktu fix yang tersedia.</p> <p>Terimakasih.</p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-07-12 12:19:02');
