INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7171, 2164, 100360, 'mahasiswa', 'Zuhrotul', '<p><span><span><span><span>Selamat siang, Kak. Mohon maaf sebelumnya, saya baru ingat jika besok tanggal 15 Juli 2024 ada agenda rapat madif tuli pukul 07.30-10.00. Bagaimana jika saya ingin konseling diundur pukul 10.00 saja? Jika berkenan, saya ingin konseling dilakukan secara offline </span></span></span></span></p> <p><span><span>Atas perhatiannya saya ucapkan terima kasih, </span></span><span><span><br /></span></span></p>', '2024-07-12 12:27:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7172, 2164, 100360, 'mahasiswa', 'Zuhrotul', '<p><span><span>Selamat siang, Kak. Mohon maaf sebelumnya, saya baru ingat jika besok tanggal 15 Juli 2024 ada agenda mendampingi madif tuli pukul 07.30-10.00. Bagaimana jika saya ingin konseling diundur pukul 10.00 saja? Jika berkenan, saya ingin konseling dilakukan secara offline </span></span></p> <p><span><span>Atas perhatiannya saya ucapkan terima kasih, </span></span><br /></p>', '2024-07-12 12:28:07');
