INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7179, 2162, 22, 'admin', 'Nasywa Lathifa', '<p>Selamat Malam, Nabila Hamidah!</p> <p>Mohon maaf izin menginformasikan, setelah kami melakukan cek ulang pada jadwal kami, untuk sesi konseling di hari Senin, 15 Juli 2024 pukul 10.00 WIB sudah terisi. Apakah Anda berkenan menjadwalkan sesi di waktu yang lain? </p> <p>Kami tunggu konfirmasinya.</p> <p>Terimakasih,</p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-07-12 19:24:43');
