INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7184, 2162, 22, 'admin', 'Nasywa Lathifa', '<p>Selamat pagi, Nabila!</p> <p>Saya menawarkan opsi pada hari Senin, 15 Juli 2024 pukul 13.00 WIB secara offline. Apakah Anda berkenan?</p> <p>Terimakasih,</p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-07-13 11:04:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7185, 2164, 22, 'admin', 'Nasywa Lathifa', '<p>Selamat pagi, Zuhrotul!</p> <p>Baik, informasi selanjutnya akan saya hubungi melalui Whatsapp. Mohon ditunggu ya.</p> <p>Terimakasih,</p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-07-13 11:06:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7186, 2164, 22, 'admin', 'Nasywa Lathifa', '<p>Mohon maaf apakah terdapat nomor yang bisa kami hubungi? dikarenakan setelah kami coba, nomor telfon yang Anda daftarkan tidak tersedia di Whatsapp.</p> <p>Kami tunggu konfirmasinya.</p> <p>Terimakasih,</p> <p>Salam  Hangat,</p> <p>Tim Konseling UB.</p>', '2024-07-13 11:11:01');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7187, 2164, 100360, 'mahasiswa', 'Zuhrotul', '<p><span><span><span><span>Selamat siang, memang nomor saya yang sebenarnya sudah diganti, saya juga kaget mengapa nomor lama saya masih terdaftar, padahal saya sudah menyertakan nomor baru ketika regist tiket konsultasi pertama saya. Ini nomor saya 082229842613</span></span></span></span></p> <p><span style="vertical-align:inherit"><span style="vertical-align:inherit">Saya mohon maaf atas ketidaknyamanan nya. Terimakasih atas pengertiannya </span></span><span><span><br /></span></span><span><span><br /></span></span></p>', '2024-07-13 11:21:52');
