INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7192, 2166, 101999, 'mahasiswa', 'Faizah', '<p>Saya mendapat luka mendalam selama masa kuliah yang membuat saya merasa menjadi pribadi yang sangat jahat. Selama ini sudah berusaha mengatasi, mencoba konsultasi online, curhat ke sahabat yang jurusan BK, &amp; pergi ke poli jiwa di puskesmas. Namun masih seringkali menangis tidak terkendali karena mengingat hal-hal yang menyakitkan.</p>', '2024-07-14 04:07:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7193, 2165, 101998, 'mahasiswa', 'Amillia Kartika', '<p>sebelumnya terima kasih atas responnya ibu, sebenarnya untuk diri saya sendiri selama semester 2 ini sudah mengusahakan semaksimal mungkin, namun memang terkadang dosen yang mengasih nilai tidak sesuai dengan usaha saya</p>', '2024-07-14 05:48:28');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7194, 2167, 102000, 'mahasiswa', 'Chandra', '<p>My low self esteem been ruining everything for me, from uni to relationships. Been procrastinating on my skripsi. Being too toxic in a relationship</p>', '2024-07-14 09:06:14');
