INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7355, 2170, 21, 'admin', 'Fita Diana', '<p>Iya betul, bisa dilakukan konseling dengan konselor lain. Baik, kami bantu untuk jadwalkan konseling di hari Selasa minggu depan yaa. Berkenan untuk konseling offline atau online?</p>', '2024-07-31 11:38:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7356, 2187, 21, 'admin', 'Fita Diana', '<p>Mohon maaf untuk hari jumat ternyata belum ada konselor yang available, kemudian pada hari Kamis besok juga sudah penuh untuk jadwal konselingnya. Apakah berkenan menjadwalkan konseling untuk minggu depan? Jika berkenan, kamu bisa memberikan kami 2 jadwal konseling lagi yaa</p>', '2024-07-31 13:26:23');
