INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7358, 2191, 102019, 'mahasiswa', 'Adhil Setyawan', '<p>Pada awalnya, saya ketika Semester 1 tidak dapat menyelesaikan perkuliahan dikarenakan alasan seperti sakit dan mengurus Pramuka di sekolah SMP saya. Ketika beranjak ke semester 2, saya bimbang antara harus melanjutkan atau tidak. Yang dimana waktu itu saya sudah ingin melanjutkan namun untuk tanggal pembayaran sudah melewati batas sehingga saya tidak dapat mendaftar. Mohon petunjuk bapak ibu konseling, saya betul" butuh bantuan</p>', '2024-07-31 16:34:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7359, 2190, 101790, 'mahasiswa', 'Rikza Zakia', '<p>kak.. aku capek banget. aku bingung mau cerita gimana. cuma, kemarin ketrigger gara-gara gagal beasiswa untuk ketiga kalinya. jadi sampe sekarang beneran sedih banget. aku merasa gagal mulu dimanapun aku berada. i feel so worthless. </p>', '2024-07-31 23:56:40');
