INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7378, 2193, 102021, 'mahasiswa', 'Putri Ningrum', '<p>Saya mahasiswa s2 kimia UB, Saya merasa tidak ingin dan tidak termotivasi untuk mengerjakan tesis Saya, Saya tidak tahu apa permasalahannya, Saya ingin mencari jalan keluar yang terbaik bagaimana mengatasi permasalahan tsb sehingga Saya bisa menyelesaikan studi Saya. Saya ingin meminta pendapat profesional terkait keadaan Saya ini. Terimakasih, Saya harap Saya mampu berkonsultasi dengan petugas</p>', '2024-08-01 19:17:45');
