INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7381, 2187, 21, 'admin', 'Fita Diana', '<p>Baik, kami jadwalkan dengan konselor kami terlebih dahulu yaa. Untuk informasi lebih lanjut akan kami informasikan melalui WhatsApp</p>', '2024-08-02 10:37:24');
