INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7389, 2194, 102022, 'mahasiswa', 'jihan ismiyati', '<p>merasa tertekan dengan ortu therhadap sya sebagai anak pertama dan akademik hingga depresi saya balik lagi dan saya nggak bisa pergi ke psikiater saya untuk lanjut berobat krn saya dilarang keras balik berobat oleh ortu saya. saya juga nggak bisa ngomong langsung masalah saya ke ortu saya krn ya ortu saya masalah utamanya. dari dokter, saya di diagnosis depresi akut krn banyak hal terutama self harm, cemas akut, dan halusinasi sering dipantau orang di sekitar kalau keluar</p>', '2024-08-02 21:25:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7390, 2192, 102020, 'mahasiswa', 'Andini Rahmadhani', '<p>Selamat malam, mohon maaf sekali baru membalas pesan ini</p> <p>Berikut ini adalah opsi jadwal yang saya berikan yaitu di hari Senin atau Selasa (untuk jamnya saya bersedia kapanpun yaitu yang ditentukan oleh konseling UB) serta konseling yang dipilih secara offline</p> <p>Terima kasih</p>', '2024-08-02 21:53:32');
