INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7396, 2194, 21, 'admin', 'Fita Diana', '<p>Selamat siang, jihan nur fitria ismiyati!</p> <p>Terima kasih telah menggunakan layanan konseling. Mohon maaf atas keterlambatan merespon karena banyaknya antrian. Terima kasih yaa sudah mau berbagi cerita mengenai permasalahan Anda kepada saya karena pasti segala hal yang sudah Anda rasakan dan lalui sampai saat ini tidaklah mudah. Untuk lebih memahami kondisi yang sedang Anda rasakan saat ini, bisakah Anda menceritakan lebih lanjut permasalahan apa yang terjadi pada diri Anda mengenai alasan dan penyebab orang tua Anda melarang Anda untuk ke psikiater lagi? Dan mulai sejak kapan permasalahan ini Anda alami? Hal ini digunakan untuk memetakan permasalahan Anda untuk dilakukannya konseling bersama konselor atau <em>peer counselor </em>yang Anda inginkan ^^</p> <p><br /></p> <p>Terima kasih,<br />Salam Hangat,<br />Tim Konseling UB.</p>', '2024-08-03 14:23:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7397, 2195, 102023, 'mahasiswa', 'Salsabilla Ikhtiara', '<p>Trauma masa lalu, saya adalah seorang anxiety attachment yang berhadapan dengan seseorang avoidant attachmant, membuat saya anxiety sampai migrain jantung berdetak kencang gabisa apa" cuma duduk diam atur nafas. Saya ingin memilih karyn untuk mendampingi saya atas rekomendasi teman saya.</p>', '2024-08-03 16:10:17');
