INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7404, 2196, 101134, 'mahasiswa', 'Maria Boro', '<p>Saat ini sudah lebih dari setahun semenjak saya sidang proposal skripsi, dan saya tidak punya keberanian untuk bertemu dengan dosen pembimbing saya. Saya merasa sangat stuck dan tidak tau apa lagi yang harus saya lakukan terhadap skripsi saya, namun disaat saya sangat membutuhkan bimbingan dari dosen pembimbing saya, saya malah tidak mempunyai keberanian untuk menemui mereka, karena saya merasa saya tidak mempunyai progress untuk skripsi saya.</p>', '2024-08-05 13:09:15');
