INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7536, 2221, 100648, 'mahasiswa', 'Muhammad', '<p>Saya berkenan Kak. Untuk sesi online hari Rabu, Kamis, atau Jumat sekitar jam 16.00 ke atas. Terimakasih banyak Kak.</p>', '2024-08-21 09:16:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7537, 2218, 21, 'admin', 'Fita Diana', '<p>Untuk jadwal konseling kamis pukul 10.00 tersedia konseling secara online saja, apakah berkenan?</p>', '2024-08-21 12:22:57');
