INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7541, 2222, 102044, 'mahasiswa', 'Ahmad Ramadhan', '<p>Jadi permasalahannua dimulai karena saya merasa memiliki tanggung jawab, karena tidak sengaja menyenggol kepala perempuan dengan bahu saya ketika dikelas, terus karena merasa tidak enak, saya mengelus bagian kerudungnya karema merasa ga enak, terus udah kan, nah permasalahannya gini bu, pas saya sm tmn2 cowo saya ngumpul, ada salah satu orang yang tiba tiba ngebahas itu, terus dijadiin bahan buat maluin aku, terus di videoin dan dikirim di grup kelas, dan saya malu bu, kalok ibu mau tau ceritanya panjang, ibu hubungin aku ya bu please</p>', '2024-08-21 15:46:49');
