INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7549, 2207, 102032, 'mahasiswa', 'Nadya Siregar', '<p>Untuk jadwal konseling saya bisa di hari selasa dan rabu pada jam 09.00 - 11.00</p>', '2024-08-22 14:59:13');
