INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7591, 2229, 102049, 'mahasiswa', 'Israa Salama', '<p>Jadi kemarin saya baru saja jadi korban penipuan. semua sudah saya lakukan, datang ke polres terdekat dan ke bank. dari bank hanya menyatakan dana saya tidak bisa kembali karena pelaku dalam waktu dekat juga sudah melakukan penarikan, sedangkan dari kepolisian tidak ada kabar lagi. saya sendiri lelah menangis tidak mengubah apapun dan saat saya sudah berusaha melaporkan ke kepolisian maupun ke bank..rasanya sama saja. tidak ada yang berubah uang saya hilang, nominalnya cukup besar dan sebenarnya buat tabungan saya untuk S2. tidak ada bisa yang saya ajak cerita maupun berbagi keluh kesah. kalau saya cerita ke keluarga mungkin respond mereka saya dimarahi karena tidak berhati hati dan saya terlalu malu untuk cerita ke teman atau sahabat saya. saya tidak membaik, lebih mencoba untuk tidak nangis lagi ataupun stress karena kemarin saya tidak tau pasti kayaknya karena stress badan saya jadi gatal2 dan jari telunjuk saya ada bintik2 seperti eksim, saya coba cari tau sendiri katanya iya karena stress. untuk masalah ini saya sudah cukup capek menghadapinya jadi saya mencoba tidak terlalu memikirkan meskipun masih kedistract.</p>', '2024-08-29 12:41:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7592, 2239, 102058, 'mahasiswa', 'Shiva Ariangga', '<p>these last few days or even weeks i feel like i always tired, sad, lonely even when im with my friends and didn''t have energy for literally everything to the point where i can''t get myself together and do things that should''ve been done, i have so much to do but i just cant get things done like how i usually does. i started to distance myself from everyone and shutting myself down like when i was in 12th grade, and i dont even want to go out and get out of bed. i dont know what cause this so maybe i think i could use a little help, thankyou.</p>', '2024-08-29 16:35:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7593, 2217, 102041, 'mahasiswa', 'Maylinda Fadhilah', '<p>Sebenarnya saya ada kelas dalam rentang waktu tersebut, apakah bisa mengajukan waktu? jika tidak bisa mengajukan di jam tertentu saya tidak keberatan di hari selasa. terima kasih</p> <p><br /></p>', '2024-08-29 18:30:27');
