INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7647, 2246, 21, 'admin', 'Fita Diana', '<p>Baik, terima kasih atas konfirmasinya. Akan kami jadwalkan konseling pada pekan depan hari Kamis, 12 September 2024 pukul 13.00 WIB yaa. Untuk informasi lebih lengkap akan kami berikan melalui WhatsApp</p> <p><br /></p> <p>Terima kasih,<br />Salam Hangat,<br />Tim Konseling UB.</p>', '2024-09-01 11:28:18');
