INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7654, 2242, 21, 'admin', 'Fita Diana', '<p>Baik, kami bantu jadwalkan konseling di hari tersebut dengan <em>peer counselor </em>kami terlebih dahulu yaa. Untuk informasi lebih lengkap, akan kami berikan melalui WhatsApp ^^</p>', '2024-09-01 11:44:49');
