INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7770, 2237, 22, 'admin', 'Nasywa Lathifa', '<p>Baik, terimakasih atas konfirmasinya.</p> <p>Selanjutnya akan kami hubungi melalui Whatsapp mendekati hari H pelaksanaan. Terimakasih.</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2024-09-08 12:08:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7771, 2253, 22, 'admin', 'Nasywa Lathifa', '<p>Baik, kalau begitu apakah berkenan untuk di hari selasa pada pukul 15.00 WIB secara offline atau diatas jam tersebut secara online?</p> <p>Terimakasih,<br />Salam hangat,</p> <p>Tim Konseling UB.</p>', '2024-09-08 12:09:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7772, 2248, 22, 'admin', 'Nasywa Lathifa', '<p>Baik, terimakasih atas konfirmasinya. Untuk lokasi terletak di Ruang Layanan Konseling, lantai 1 Gedung Rektorat UB ya.</p> <p>Informasi selengkapnya akan kami hubungi melalui whatsapp menjelang waktu pelaksanaann konseling. Mohon ditunggu. <br />Terimakasih,<br />Salam hangat,<br />Tim Konseling UB.</p>', '2024-09-08 12:11:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7773, 2257, 22, 'admin', 'Nasywa Lathifa', '<p>Baik, terimakasih atas konfirmasinya. Informasi lengkap mengenai link dan lain sebagainya akan kami hubungi melalui whatsapp menjelang hari pelaksanaan yaa. <br />Terimakasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2024-09-08 12:13:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7774, 2261, 22, 'admin', 'Nasywa Lathifa', '<p>Baik, terimakasih atas konfirmasinya. Kalau begitu kami jadwalkan sesi di hari Kamis, 12 September 2024 bersama peer konselor kami pada pukul 10.00 WIB ya. Informasi lebih lanjut akan segera kami hubungi melalui whatsapp. Terimakasih.</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2024-09-08 12:14:49');
