INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7877, 2279, 102097, 'mahasiswa', 'Erika Putri', '<p>Alasan dan penyebabnya karena di lingkungan saya kebanyakan sudah pada sukses dan sudah meraih mimpinya masing masing sedangkan saya masih stuck di sini saja. Mungkin lebih lanjut akan saya ceritakan saat konseling.<br />Terima kasih</p>', '2024-09-20 18:52:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7878, 2286, 21, 'admin', 'Fita Diana', '<p>Selamat malam, Yasmin Nawawi!<br /><br />Terima kasih telah menggunakan layanan konseling. Mohon maaf atas keterlambatan merespon karena banyaknya antrian. Terima kasih yaa sudah mau berbagi cerita mengenai permasalahan Anda kepada saya karena pasti segala hal yang sudah Anda rasakan dan lalui sampai saat ini tidaklah mudah. Apakah kamu berkenan untuk menjadwalkan sesi konseling dengan <em>peer counselor</em> kami? Jika berkenan, kamu bisa memberikan 2 pilihan jadwal kepada kami dari senin-jumat (08.00-16.00) untuk konseling offline atau senin-jumat (08.00-21.00) untuk konseling online<br /><br />Terima kasih,<br />Salam Hangat,<br />Layanan Konseling UB.</p>', '2024-09-20 18:55:32');
