INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (7958, 2292, 21, 'admin', 'Fita Diana', '<p>Bisa, untuk konseling senin-rabu pekan ini available dengan <em>peer counselor </em>yaa. Kamu bisa memberikan pilihan jadwal kepada kami dari senin-jumat (08.00-16.00) untuk konseling offline</p>', '2024-09-22 12:24:49');
