INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8035, 2298, 102113, 'mahasiswa', 'Anak Hapsari', '<p>Mohon maaf tidak sengaja mengirim hal yang sama tiga kali, saya menekan tombol berulang ulang ketika koneksinya kurang baik. </p>', '2024-09-25 14:54:11');
