INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8041, 2307, 101979, 'mahasiswa', 'Bintang Soburany', '<p>Mungkin ajar masalah saya dr keluarga yang kurang memperhatikan kebutuhan emosional saya, sehingga saya mencarinya dari orang lain, sekarang saya sudah dapat 2 orang teman yang saya anggap keluarga sendiri, tetapi belakangan ini mereka ber2 sering memiliki kesibukan sendiri sehingga saya merasa kurang diperhatikan, belum lagi ditumpuk tugas-tugas kuliah saya jadi lumayan tertekan. Saya tidak menyalahkan kedua teman saya, hanya saja saya sepertinya sangat2 ingin ada orang yang memperhatikan saya</p>', '2024-09-25 18:20:02');
