INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8078, 2307, 101979, 'mahasiswa', 'Bintang Soburany', '<p>Saya lebih senang offline, jika bisa besok jam 8, atau setelah jumatan sekitar jam 12 atau jam 1</p>', '2024-09-26 12:06:07');
