INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8082, 2303, 101511, 'mahasiswa', 'Hanadia Prastiwi', '<p>Baik, tidak masalah. Saya punya beberapa pilihan jadwal. Selasa jam 13.00-16.00. Rabu jam 12.00 -16.00, dan Jumat jam 08.00-12.00. Sejauh ini available dalam jadwal-jadwal tersebut. Jika ada perubahan jadwal karena bimbingan atau lainnya, akan segera saya kabari. Terima kasih banyakk</p>', '2024-09-26 15:23:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8083, 2311, 102120, 'mahasiswa', 'Saffanatul', '<p>saya bingung dan merasa demotivated, bangun siang, perasaan ingin tidur terus padahal banyak deadline, kamar berantakan</p>', '2024-09-26 19:30:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8084, 2297, 21, 'admin', 'Fita Diana', '<p>Untuk kamis pekan depan yaa</p>', '2024-09-26 21:42:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8085, 2303, 21, 'admin', 'Fita Diana', '<p>Baik, terdapat konselor kami available di hari senin pukul 13.00. Berkenan konseling secara offline atau online?</p>', '2024-09-26 21:43:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8086, 2307, 21, 'admin', 'Fita Diana', '<p>Mohon maaf atas ketidaknyamannya dan keterlambatan merespon karena banyaknya antrian sehingga belum bisa menjadwalkan konseling pada hari besok karena mendadak. Kamu bisa memberikan pilihan jadwal untuk melakukan konseling pada pekan depan</p>', '2024-09-26 21:47:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8087, 2310, 21, 'admin', 'Fita Diana', '<p>Layanan Konseling UB tidak dipungut biaya karena merupakan fasilitas layanan yang diberikan UB kepada mahasiswanya</p>', '2024-09-26 21:49:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8088, 2312, 102121, 'mahasiswa', 'Sheila Sakha', '<p>permasalahan yang saya hadapi adaalah saha samgat kurang percaya diri dan menyalahkan diri sendiri karena saya ditinggal oleh teman teman saya, saya dari keluarga broken home sehingga dari kecil teman merupakan save place bagi saya namun ketika kuliah san saya dikhianati teman teman saya itu sangat berdampak kepada saya hingga saat inj</p>', '2024-09-27 01:28:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8089, 2303, 101511, 'mahasiswa', 'Hanadia Prastiwi', '<p>Mohoh maaf senin jam 13.00-17.00 saya masih ada kelas. Apakah ada pilihan jadwal lain?</p>', '2024-09-27 06:05:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8090, 2313, 102122, 'mahasiswa', 'Safina Azeeza', '<p>terjadinya mood swings dengan mood yang sangat berbeda dalam sehari, dan minimal terjadi sekali dalam seminggu. ada kalanya pernah terjadi beberapa hari dalam seminggu</p>', '2024-09-27 06:42:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8091, 2314, 102122, 'mahasiswa', 'Safina Azeeza', '<p>terjadinya mood swing yang terkadang sangat berbeda di hari yang sama, minimal terjadi sekali seminggu. terkadang pernah beberapa hari dalam seminggu</p>', '2024-09-27 06:46:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8092, 2307, 101979, 'mahasiswa', 'Bintang Soburany', '<p>Bauklah tidak mengapa, untuk jadwal kosong saya offline dalam seminggu adalah sebagai berikut:</p> <p>Senin 10.20-12.30, 14.30-16.00</p> <p>Selasa 8.40-10.00, 12.00-14.10</p> <p>Rabu 12.00-16.00</p> <p>Kamis 10.20-14.10</p> <p>Jumat 08.00-10.00, 12.00-16.00</p>', '2024-09-27 07:06:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8093, 2315, 102046, 'mahasiswa', 'Aisha Rus’an', '<p>konseling masalah absensi</p>', '2024-09-27 07:43:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8094, 2316, 102124, 'mahasiswa', 'Alvina Hutasuhut', '<p>Saya merasa sangat malu dan sedih jika mengutarakan perasaan saya ke orang lain dan terkadang membuat saya jijik dengan diri sendiri. Saya merasa lemah jika saya terbuka ke orang lain dan terkadang, saya melihat diri saya sendiri sebagai orang yang tidak pantas mendapatkan cinta. Saat orang lain mengatakan sesuatu, saya terbiasa langsung negative thinking dan merasa mereka membenci saya sehingga saya memiliki keinginan untuk cut off mereka, apalagi di masalah percintaan. Terkadang, rasa malunya ingin membuat saya benci melihat badan saya, tetapi hanya berlangsung beberapa hari dan saya akan kembali senang. Mood saya secepat itu naik turun dan membuat saya stres</p>', '2024-09-27 07:45:05');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8095, 2303, 21, 'admin', 'Fita Diana', '<p>Baik, terdapat jadwal konselor kami pada Selasa pukul 13.00. Sesuai dengan pilihan jadwal yang kamu berikan</p>', '2024-09-27 08:18:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8096, 2303, 21, 'admin', 'Fita Diana', '<p>Baik, terdapat jadwal konselor kami pada Selasa pukul 14.00. Sesuai dengan pilihan jadwal yang kamu berikan</p>', '2024-09-27 08:18:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8097, 2307, 21, 'admin', 'Fita Diana', '<p>Baik, kami coba jadwalkan pada hari Rabu pukul 12.00 yaa. Akan kami carikan jadwal yang cocok dengan <em>peer counselor </em>kami. Mohon ditunggu, untuk informasi lebih lanjut akan kami berikan melalui WhatsApp</p>', '2024-09-27 08:20:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8098, 2314, 21, 'admin', 'Fita Diana', '<p>Selamat pagi, Safina Azeeza!</p> <p>Terima kasih telah menggunakan layanan konseling. Mohon maaf atas keterlambatan merespon karena banyaknya antrian. Terima kasih yaa sudah mau berbagi cerita mengenai permasalahan Anda kepada saya karena pasti segala hal yang sudah Anda rasakan dan lalui sampai saat ini tidaklah mudah. Untuk lebih memahami kondisi yang sedang Anda rasakan saat ini, bisakah Anda menceritakan lebih lanjut permasalahan apa yang terjadi pada diri Anda mengenai alasan dan penyebab permasalahan tersebut? Atau pemicu awal dari permasalahan yang Anda rasakan? Dan sejak kapan permasalahan ini Anda rasakan? Hal ini digunakan untuk memetakan permasalahan Anda untuk dilakukannya konseling bersama konselor atau <em>peer counselor </em>yang Anda inginkan ^^</p> <p><br /></p> <p>Terima kasih,<br />Salam Hangat,<br />Tim Konseling UB.</p>', '2024-09-27 08:25:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8099, 2313, 21, 'admin', 'Fita Diana', '<p>udah dibales di etiket sebelah</p>', '2024-09-27 08:28:49');
