INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8103, 2316, 21, 'admin', 'Fita Diana', '<p>Selamat pagi, Alvina Zahra Hutasuhut!</p> <p>Terima kasih telah menggunakan layanan konseling. Terima kasih yaa sudah mau berbagi cerita mengenai permasalahan Anda kepada saya karena pasti segala hal yang sudah Anda rasakan dan lalui sampai saat ini tidaklah mudah. Untuk lebih memahami kondisi yang sedang Anda rasakan saat ini, bisakah Anda menceritakan lebih lanjut permasalahan apa yang terjadi pada diri Anda mengenai alasan dan penyebab permasalahan tersebut? Atau pemicu awal dari permasalahan yang Anda rasakan? Dan sejak kapan permasalahan ini Anda rasakan? Hal ini digunakan untuk memetakan permasalahan Anda untuk dilakukannya konseling bersama konselor atau <em>peer counselor </em>yang Anda inginkan ^^</p> <p><br /></p> <p>Terima kasih,<br />Salam Hangat,<br />Tim Konseling UB.</p>', '2024-09-27 08:31:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8104, 2317, 102125, 'mahasiswa', 'Shafira Darmawan', '<p>saya merasa burnout karena sedang menjalani kuliah, skripsi, dan menjadi student employee di fakultas. keluarga saya selalu menganggap saya pintar, namun saya tidak merasa seperti itu. saya merasa harus mewujudkan anggapan mereka untuk menjadi anak yg pintar. </p> <p>saya lelah, tidak ada waktu untuk diri saya sendiri. namun ketika saya berusaha istirahat, saya tidak tenang. saya merasa ada hal yang harus saya lakukan dan saya tidak deserve untuk istirahat</p>', '2024-09-27 09:02:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8105, 2316, 102124, 'mahasiswa', 'Alvina Hutasuhut', '<p>Terima kasih sebelumnya. Saya rasa hal itu disebabkan masa lalu saya. Dulu saya pernah dikucilkan dari SD hingga SMP karena saya kurang fasih berbahasa Indonesia dan saya secara fisik berbeda dari yang lain. Dulu rambut saya lebih pirang dan kulit saya putih. Satu-satunya teman saya saat SD meninggalkan saya karena dia tidak tahan dikucilkan dan saat SMP, saya tidak memiliki teman dekat. Selain itu, dulu saya sempat ketinggalan pelajaran karena guru saya selalu bilang saya bodoh daripada berusaha membuat saya paham. Saya rasa itu kenapa saya merasa takut vulnerable di depan orang lain. Tetapi saya baru merasakan ingin ngecutoff orang lain dan negative thinking ketika saya mulai berpacaran yaitu saat kuliah.</p>', '2024-09-27 10:08:04');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8106, 2316, 102124, 'mahasiswa', 'Alvina Hutasuhut', '<p>Terima kasih sebelumnya. Saya rasa hal itu disebabkan masa lalu saya. Dulu saya pernah dikucilkan dari SD hingga SMP karena saya kurang fasih berbahasa Indonesia dan saya secara fisik berbeda dari yang lain. Dulu rambut saya lebih pirang dan kulit saya putih. Satu-satunya teman saya saat SD meninggalkan saya karena dia tidak tahan dikucilkan dan saat SMP, saya tidak memiliki teman dekat. Selain itu, dulu saya sempat ketinggalan pelajaran karena guru saya selalu bilang saya bodoh daripada berusaha membuat saya paham. Saya rasa itu kenapa saya merasa takut vulnerable di depan orang lain. Tetapi saya baru merasakan ingin ngecutoff orang lain dan negative thinking ketika saya mulai berpacaran yaitu saat kuliah.</p>', '2024-09-27 10:25:19');
