INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8110, 2314, 102122, 'mahasiswa', 'Safina Azeeza', '<p>mood swing ini kayaknya udah lama, mungkin udh beberapa bulan tapi sadarnya kalo ini mood swings baru sekarang-sekarang. pemicu dari mood swing ini bisa macem-macem banget, mulai dari overthinking, stress, anxiety, dll. mood bisa dari seneng banget sampai sedih banget dalam sehari. </p>', '2024-09-27 15:21:17');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8111, 2318, 102126, 'mahasiswa', 'Devi', '<p>Diagnosa bipolar dan bpd. Mood naik turun tapi mostly depresi. Sangat tidak memungkinkan untuk stabil dan mengikuti kelas setiap hari, pasti ada beberapa hati khusus emosi dan mood saya kacau, dan bila izin memerlukan surat dokter sedangkan sata tidak setiap hari ke psikiater. Saya belum mau mengundurkan diri (sepertinya). Jadi bagaimana kira kira solusinya dengan absensi dan masalah surat menyurat saya?</p>', '2024-09-27 18:06:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8112, 2303, 21, 'admin', 'Fita Diana', '<p>Baik, kami jadwalkan pada hari Selasa pukul 14.00 secara offline yaa. Untuk informasi lebih lengkap akan kami berikan melalui WhatsApp</p>', '2024-09-28 07:03:18');
