INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8114, 2314, 21, 'admin', 'Fita Diana', '<p>Bisakah kamu menceritakan lebih lanjut permasalahan apa yang terjadi pada diri kamu mengenai alasan dan penyebab permasalahan tersebut?</p>', '2024-09-28 07:05:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8115, 2316, 21, 'admin', 'Fita Diana', '<p>Bisakah kamu menceritakan lebih lanjut permasalahan mengenai alasan dan penyebab permasalahan tersebut kembali terjadi saat kuliah?</p>', '2024-09-28 07:07:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8116, 2317, 21, 'admin', 'Fita Diana', '<p>Selamat pagi, Shafira Dinar!</p> <p>Terima kasih telah menggunakan layanan konseling. Mohon maaf atas keterlambatan merespon karena banyaknya antrian. Terima kasih yaa sudah mau berbagi cerita mengenai permasalahan Anda kepada saya karena pasti segala hal yang sudah Anda rasakan dan lalui sampai saat ini tidaklah mudah. Untuk lebih memahami kondisi yang sedang Anda rasakan saat ini, bisakah Anda menceritakan lebih lanjut permasalahan apa yang terjadi pada diri Anda mengenai alasan dan penyebab permasalahan tersebut? Atau pemicu awal dari permasalahan yang Anda rasakan? Dan sejak kapan permasalahan ini Anda rasakan? Hal ini digunakan untuk memetakan permasalahan Anda untuk dilakukannya konseling bersama konselor atau <em>peer counselor </em>yang Anda inginkan ^^</p> <p><br /></p> <p>Terima kasih,<br />Salam Hangat,<br />Tim Konseling UB.</p>', '2024-09-28 07:10:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8117, 2318, 21, 'admin', 'Fita Diana', '<p>Selamat pagi, Devi Kurnia!</p> <p>Terima kasih telah menggunakan layanan konseling. Mohon maaf atas keterlambatan merespon karena banyaknya antrian. Terima kasih yaa sudah mau berbagi cerita mengenai permasalahan Anda kepada saya karena pasti segala hal yang sudah Anda rasakan dan lalui sampai saat ini tidaklah mudah. Untuk lebih memahami kondisi yang sedang Anda rasakan saat ini, bisakah Anda menceritakan lebih lanjut permasalahan apa yang terjadi pada diri Anda mengenai alasan dan penyebab permasalahan tersebut? Sejak kapan permasalahan ini Anda rasakan? Hal ini digunakan untuk memetakan permasalahan Anda untuk dilakukannya konseling bersama konselor atau <em>peer counselor </em>yang Anda inginkan ^^</p> <p><br /></p> <p>Terima kasih,<br />Salam Hangat,<br />Tim Konseling UB.</p>', '2024-09-28 07:12:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8118, 2314, 102122, 'mahasiswa', 'Safina Azeeza', '<p>kalo yang belakangan ini pemicunya stres dari workload kerja, berita duka yang terus ada, terlalu khawatirin orang lain, atau bisa aja tiba-tiba semangat buat beraktivitas ilang</p>', '2024-09-28 08:02:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8119, 2296, 102112, 'mahasiswa', 'Faradita Irawan', '<p>Selamat pagi, mohon maaf saya kemarin tidak teliti membaca balasan dari kak Fita, tetapi saya menyampaikan kalau bersedia melakukan sesi konseling online di hari rabu pada pukul 19.00 </p>', '2024-09-28 09:55:26');
