INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8142, 2314, 22, 'admin', 'Nasywa Lathifa', '<p>Baik. untuk Selasa, 1 Oktober kami tersedia pada pukul 12.00 WIB yaaa. akan saya coba bantu jadwalkan bersama peer konselor yang tersedia pada waktu tersebut dan akan kami follow up melalui whatsapp.</p> <p>Terimakasih.</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2024-09-30 15:17:36');
