INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8304, 2357, 102155, 'mahasiswa', 'Andika Wirayudha', '<p>Ayah saya melakukan kekerasan dan penghinaan selama bertahun-tahun sejak kecil berujung saya mengalami trauma. Dia juga melakukan kekerasan ke ibu dan kakak juga adik kandung saya. Namun, kedua orang tua saya belum bercerai sehingga membuat saya memutuskan untuk berkuliah di luar kota salah satunya untuk menghindari bertemu ayah saya di rumah. Belakangan ini, saya sudah 3 kali mengalami mimpi karena bertengkar dengan ayah saya dan bangun tidur dengan kondisi menangis dan jantung berdebar</p>', '2024-10-12 10:18:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8305, 2341, 102144, 'mahasiswa', 'Aurora Almira', '<p>Terimakasih telah membalas. Saya ingin mengajukan jadwal pada Hari Senin pukul 10.00 atau Selasa pukul 13.00.</p>', '2024-10-12 13:03:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8306, 2339, 102028, 'mahasiswa', 'Nadya Azizah', '<p>Halo, kira-kira untuk sesi konselingnya berapa jam ya? Kebetulan di hari Rabu, ada ujian di jam 15.00. Atau ada pilihan hari lain tidak ya? Terima kasih banyak sebelumnya</p>', '2024-10-12 15:32:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8307, 2358, 100375, 'mahasiswa', 'Bintang Aditya', '<p>Pada saat duduk di bangku SMA, saya mengalami pelecehan pleh mantan kekasih yang membuat trauma yang sangat mendalam. </p>', '2024-10-12 15:56:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8308, 2349, 102145, 'mahasiswa', 'Naila Fiqhia', '<p>okee baik, akan sedikit saya ceritakan.</p> <p>dari masa saya kecil mungkin sering merasakan tidak diterima dari lingkungan keluarga, saya merasa diantara cucu-cucu nenek  saya...saya yang paling tomboy, saya yang paling tidak menojol dari segi prestasi akademik, diluar lingkup itupun jarang sekali saya diperlikukan selayaknya anak diluaran sana yang sering saya lihat bagaimana lingkungannya memperilakukan anak tersebut. dampak sampai sekarang dititik sekarang saya layak dibilang people please, yang benar-benar sedang saya rasakan, sulit membuat keputusan sendiri, gagal mengembangkan kepribadian, sulit memahami kebutuhan dan keinginan sendiri,merasa tidak berharga, mudah cemas dan stres, merasa terbebani hidup, merasa memiliki harga diri yang rendah, merasa terjebak dalam hubungan toxic, merasa dimanfaatkan orang lain. dan saya sedang proses skripsi dan difase sekarang itu semua berat untuk saya.</p>', '2024-10-13 01:19:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8309, 2349, 102145, 'mahasiswa', 'Naila Fiqhia', '<p>sejauh ini semua yang sedang saya rasakan menjadi merasa selalu trust issue dengan lingkungan saya, saya dengan siapa dan apa yang sedang saya lakukan membuat saya tidak yakin. dalam mengatasi ini semua baru ini yang saya lakukan untuk konseling, saya sudah mencoba mencari cara dan mencari jawaban ke rekan-rekan terdekat saya.</p>', '2024-10-13 01:23:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8310, 2349, 102145, 'mahasiswa', 'Naila Fiqhia', '<p>saya merasa belum bisa mengikhlaskan suatu hal yang membuat saya sakit hati sampai dititik sekarang. terima kasih, saya rasa sangat membutuhkan konseling</p>', '2024-10-13 01:25:29');
