INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8350, 2368, 102162, 'mahasiswa', 'Rysha Syafna', '<p>Saya mau cerita dengan orang tua tentang kesulitan saya selama ini dengan jurusan yang saya pilih, tapi saya takut cerita ke orang tua, saya takut mereka kecewa, saya ga punya siapa-siapa di sini untuk cerita, saya takut </p>', '2024-10-15 18:03:55');
