INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8356, 2355, 23, 'admin', 'Shafa Fatin Ahmad', '<p dir="ltr">Selamat siang, Errika!</p> <p dir="ltr">Terima kasih telah menggunakan layanan konseling. Mohon maaf atas keterlambatan respons karena panjangnya antrian. Saya yakin apa yang Anda alami saat ini tentunya tidak mudah, tetapi saya mengapresiasi Anda karena sudah berani menceritakan apa yang Anda rasakan di layanan konseling UB ini karena artinya Anda <em>aware</em> dengan kondisi diri Anda sendiri.</p> <p dir="ltr">Berkaitan dengan permasalahan Anda, saya izin bertanya mengenai beberapa hal untuk membantu menemukan solusi yang tepat atas permasalahan Anda.</p> <p>1. Apa yang sedang selalu Anda pikirkan belakangan ini?</p> <p>2. Apakah terdapat permasalahan keluarga, akademik, pertemanan, atau lainnya yang membuat Anda stress?</p> <p>3. Ketika Anda tiba-tiba merasa sedih, apa yang sedang Anda pikirkan saat itu?</p> <p>Terima kasih.</p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-10-17 13:12:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8357, 2356, 23, 'admin', 'Shafa Fatin Ahmad', '<p dir="ltr">Selamat siang, Budiman!</p> <p dir="ltr">Terima kasih telah menggunakan layanan konseling. Mohon maaf atas keterlambatan respons karena panjangnya antrian. Saya yakin apa yang Anda alami saat ini tentunya tidak mudah, tetapi saya mengapresiasi Anda karena sudah berani menceritakan apa yang Anda rasakan di layanan konseling UB ini karena artinya Anda <em>aware</em> dengan kondisi diri Anda sendiri.</p> <p dir="ltr">Berkaitan dengan permasalahan Anda, saya izin bertanya mengenai beberapa hal untuk membantu menemukan solusi yang tepat atas permasalahan Anda.</p> <p>1. Bisakah, diceritakan lebih lanjut apa hal yang membuat Anda bingung?</p> <p>2. Apakah jurusan dan kegiatan yang Anda lakukan saat ini di perkuliahan sesuai dengan minat dan rencana Anda?</p> <p>3. Apa yang paling ingin Anda lakukan di masa depan?</p> <p>Terima kasih.</p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-10-17 13:14:48');
