INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8374, 2363, 102157, 'mahasiswa', 'Selfi Fatikasari', '<p>selamat siang pak/bu, terima kasih sebelumnya telah membalas pesan saya. mohon izin menjawab, saya bisa melakukan konseling pada hari tersebut, namun mohon maaf pak/bu dikarenakan kelas saya berakhir pukul 12.40, apakah bapak/ibu berkenan jika sesi konseling nya setelah saya selesai kelas tersebut? atau mungkin bapak/ibu berkenan pada jeda kelas pukul 08.30?</p> <p>terima kasih</p>', '2024-10-17 14:32:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8375, 2362, 101360, 'mahasiswa', 'Satria', '<p>Saya rasa saya masih bisa menunggu untuk konseling bersama Bu Ulifa 28 Oktober nanti. Karena untuk jadwal minggu depan saat hari rabu pukul 14.00 saya ada kelas. Jadi tidak apa-apa untuk menunggu terlebih dahulu. Terima kasih</p>', '2024-10-17 15:03:59');
