INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8377, 2363, 23, 'admin', 'Shafa Fatin Ahmad', '<p>Halo, Selfi!</p> <p>Mohon maaf saya lupa menyebutkan untuk tanggal 21 Oktober sendiri sesinya mulai dari pukul 11.30 yaa sesuai dengan jadwal psikolog kami apakah bersedia?</p> <p>Terimakasih,</p> <p>Salam Hangat,</p> <p>Tim Konseling UB.</p>', '2024-10-17 15:42:55');
