INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8417, 2375, 21, 'admin', 'Fita Diana', '<p>Mohon maaf untuk jadwal konseling tidak bisa dilakukan mendadak karena kami perlu mencarikan jadwal <em>peer counselor </em>yang available. Mungkin bisa menentukan jadwal konseling di hari lain</p>', '2024-10-21 10:44:23');
