INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8435, 2374, 21, 'admin', 'Fita Diana', '<p>Bisa kami bantu carikan jadwal yang cocok dengan psikolog dosen kami. Namun untuk minggu ini, jadwal konseling di pekan depan</p>', '2024-10-22 11:15:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8436, 2364, 21, 'admin', 'Fita Diana', '<p>Baik, terima kasih ya sudah berbagi cerita mengenai permasalahan yang sedang kamu hadapi. Apakah sejauh ini kamu memiliki orang terdekat untuk berbagi cerita mengenai permasalahan yang sedang kamu hadapi?</p>', '2024-10-22 11:17:20');
