INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8663, 2427, 102203, 'mahasiswa', 'Hably', '<p>Saya sering merasa sakit, stress, dan lelah, tanpa tahu apa penyebab pastinya. Semakin saya pikir, semakin saya tidak tahu </p>', '2024-11-09 11:49:52');
