INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8765, 2450, 102219, 'mahasiswa', 'Violina Adha', '<p>Merasa tidak semangat akhir akhir ini dan sering cape meski sudah istirahat, merasa semua hal yang disukai sekarang terasa kosong</p>', '2024-11-17 22:12:05');
