INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8790, 2449, 21, 'admin', 'Fita Diana', '<p>Selamat siang, Fairuz Daffa!<br /><br />Baik, terima kasih ya sudah mau berbagi cerita mengenai permasalahan yang sedang kamu rasakan. Apakah kamu berkenan untuk menjadwalkan sesi konseling dengan peer counselor kami? Jika berkenan, kamu bisa memberikan 2 pilihan jadwal kepada kami dari senin-jumat (08.00-16.00) untuk konseling offline atau (08.00-21.00) untuk konseling online<br /><br />Terima kasih,<br />Salam Hangat,<br />Layanan Konseling UB.</p>', '2024-11-18 14:06:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8791, 2430, 21, 'admin', 'Fita Diana', '<p>Baik, terima kasih ya sudah mau berbagi cerita mengenai permasalahan yang sedang kamu rasakan. Apakah kamu berkenan untuk menjadwalkan sesi konseling dengan peer counselor atau konselor kami? Kamu berkenan untuk konseling dengan psikolog atau <em>peer </em><em>counselor </em>kami? Jika berkenan, kamu bisa memberikan 2 pilihan jadwal kepada kami dari senin-jumat (08.00-16.00) untuk konseling offline atau (08.00-21.00) untuk konseling online<br /><br /></p>', '2024-11-18 14:07:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8792, 2435, 102210, 'mahasiswa', 'Siti Yuniar', '<p>Baik</p>', '2024-11-18 14:10:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8793, 2452, 102221, 'mahasiswa', 'Ayesha Annur', '<p>sebelumnya terimakasih banyak atas kesempatan dan perhatiannya, Tim Konseling UB. kejadian ini saya alami sudah 2 minggu tepat setelah putus dari hubungan saya yang berjalan 2 tahun. per hari ini, saya sering merasa kesulitan untuk bisa tidur nyenyak. hampir setiap malam, pikiran saya tidak bisa tenang dan itu sangat mengganggu. bahkan beberapa kali saya baru bisa tidur jam 2/3 pagi padahal sebenarnya saya sudah ngantuk dan lelah setelah berkegiatan seharian. saya merasa stages of grief saya masih di tahap denial, belum bisa sampai tahap acceptance padahal sudah 2 minggu berlalu. saya sudah coba untuk mendistraksi pikiran saya tentang dia tapi semakin saya sengaja mencoba untuk mendistraksi, semakin saya teringat di setiap momen yang ada.</p>', '2024-11-18 14:15:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8794, 2452, 21, 'admin', 'Fita Diana', '<p>Apakah sejauh ini kamu memiliki teman cerita untuk berbagi cerita mengenai permasalahan yang sedang kamu alami?</p>', '2024-11-18 14:23:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8795, 2402, 21, 'admin', 'Fita Diana', '<p>Apakah boleh dituliskan nomor WhatsApp yang aktif, karena nomor kontak yang ada di eticket tidak terdeteksi di WhatsApp admin kami</p>', '2024-11-18 14:27:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8796, 2452, 102221, 'mahasiswa', 'Ayesha Annur', '<p>ada tapi tidak intens, karena saya merasa menambah beban teman saya untuk mendengarkan cerita tentang hal yang sama berulang kali setiap harinya. saya ada 1 teman cerita yang biasanya saya sharing soal permasalahan ini, tapi kebetulan dia beberapa waktu belakangan memiliki kesibukan tersendiri sehingga sudah sulit untuk berinteraksi dan sudah jarang membalas pesan saya lagi</p>', '2024-11-18 14:28:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8797, 2430, 102205, 'mahasiswa', 'Maria Ayuningtyas', '<p>Untuk saat ini apakah saya bisa konseling secara online terlebih dahulu?</p>', '2024-11-18 14:36:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8798, 2430, 21, 'admin', 'Fita Diana', '<p>Bisa, nanti akan kami bantu carikan jadwal <em>peer counselor </em>yang available terlebih dahulu yaaa. Kamu bisa menuliskan jadwal yang kamu bisa untuk melakukan konseling</p>', '2024-11-18 14:41:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8799, 2452, 21, 'admin', 'Fita Diana', '<p>Apakah kamu berkenan untuk melakukan konseling dengan <em>peer counselor </em>kami?</p>', '2024-11-18 14:42:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8800, 2435, 21, 'admin', 'Fita Diana', '<p>Kasus dialihkan ke Satgas PPKS UB</p>', '2024-11-18 14:42:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8801, 2452, 102221, 'mahasiswa', 'Ayesha Annur', '<p>saya berkenan kak</p>', '2024-11-18 14:44:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8802, 2432, 102207, 'mahasiswa', 'Mayang Astrini', '<p>Apakah memungkinkan untuk konsul offline besok pagi jam 10?</p>', '2024-11-18 14:51:01');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8803, 2430, 102205, 'mahasiswa', 'Maria Ayuningtyas', '<p>Untuk konseling online ini apakah melalui chat atau tatap muka daring ya kak? Jadwal saya Senin-Jumat (bisa di jam berapa saja, kecuali ada jadwal bimbingan skripsi)</p>', '2024-11-18 15:02:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8804, 2453, 102222, 'mahasiswa', 'Sylvia Kurnia', '<p>saya sempat melakukan kesalahan buruk sekali, dengan hamil di luar nikah dengan suami saya ini. dan akhirnya menikah. pernikahan kami tidak berjalan lancar. dan banyak sekali konflik dengan mertua juga. dan saya saat ini akan diceraikan dengan suami saya. namun banyak sekali kesalahan dia yang dia katakan bahwa saya yang salah. banyak yang seharusnya sebab, menjadi akibat dan akibat menjadi sebab. yang membingungkan sekali bagi saya sekarang untuk menilai diri saya. dan menghadapi perceraian yang akan datang. lumayan sulit memaafkan semua yang membuat saya sakit hati dan realita perceraian ini. serta dia ingin cerai karena kesalahan kesalahan saya yang sebab nya adalah diri nya sendiri menurut saya, namun dia berkata bahwa saya selalu nyalahin dia. dan saya juga jadi bingung. apa karena saya hanya mendengarkan pov saya? tapi bagi saya pov dia juga ga make sense. dan saya juga jadi khawatir saya NPD. karena beberapa alasan lainnya. saya juga ingin menganalisa apa betul saya NPD. dan saya sudah berulang kali ingin bunuh diri karena depresi berat meski saya ditahap belum punya nyali tersebut. namun dapat reda dan ketika ada masalah lagi rasanya kembali ke tahap tadi lagi. saya juga takut tidak mendapatkan hak anak saya. karena mereka sudah biasa membayar orang orang sana untuk yg mereka inginkan. keluarganya juga lumayan manipulatif. saya juga pernah melihat chat selingkuh suami saya. namun dia berdalih dan memanipulasi saya. namun saya baru menyadari itu sebuah manipulasi selalu setelah jauh lama terjadinya. </p>', '2024-11-18 16:23:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8805, 2454, 101360, 'mahasiswa', 'Satria', '<p>Akhir-akhir ini saya sering merasa tertinggal jauh dari teman-teman saya. Akibat perasaan tersebut saya sering ketakutan dan cemas untuk membayangkan bagaimana saya di masa depan. Hal ini semakin terasa karena saat ini sudah memasuki akhir semester 5 dimana sebentar lagi akan menghadapi skripsi. Saya sangat bingung mau mengambil apa di skripsi karena saya merasa tidak bisa apa-apa. Ketika saya memikirkan hal tersebut, saya merasa cemas. Perasaan cemas tersebut terkadang mengganggu saya untuk jam tidur saya karena saat memejamkan mata selalu terbayang-bayang. Sebenarnya saya memiliki obat untuk dikonsumsi malam hari yang diberikan oleh psikiater, tetapi saya masih merasa belum terlalu membutuhkan. Jadi saya mencoba untuk konseling agar saya bisa merasa sedikit lebih nyaman tanpa harus mengkonsumsi obat</p>', '2024-11-18 17:18:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8806, 2402, 101999, 'mahasiswa', 'Faizah', '<p>085706018224</p>', '2024-11-18 17:49:17');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8807, 2455, 101283, 'mahasiswa', 'Brantio', '<p>saya merupakan mahasiswa akuntansi tingkat kedua yang sepertinya akan mengalami penurunan ipk di semester ini, permasalahan yang saya alami cukup banyak, sehingga yang awalnya saya mahasiswa yang suka bersosialisasi, bercerita dan aktif di kelas kini saya cenderung diam, sebenarnya saya bingung apa yang menjadikan diri saya tidak seperti yang sebelumnya, saya biasa konseling rutin tiap bulan, tetapi karena saya berhalangan untuk pulang jadi saya tidak bisa berkonsultasi dengan psikolog yang biasa saya konsultasi. mohon kesediaan waktunya untuk dapat berkonsutasi, terima kasih</p>', '2024-11-18 18:35:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8808, 2449, 102218, 'mahasiswa', 'Fairuz', '<p>Peer counselor bisa request perempuan ya kak, untuk jadwal konseling offline saya pilih di tanggal 20 pukul 10 atau tanggal 21 pukul 10</p>', '2024-11-18 18:42:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8809, 2432, 102207, 'mahasiswa', 'Mayang Astrini', '<p>apabila besok tidak memungkinkan, saya bisa di hari rabu dan kamis, jam 11.00-13.00. Setelah jam 13.00 saya harus menjemput anak saya.</p>', '2024-11-18 20:46:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8810, 2456, 102223, 'mahasiswa', 'Erliana Armiliati', '<p>Saya merasa jatuh setiap kali mengingat peristiwa 3-4 tahun lalu yang juga mempengaruhi kuliah karena setiap teringat saya membutuhkan banyak waktu untuk menangis sendiri, belakang ini menjadi lebih sering daripada sebelumnya sampai mungkin berimbas pada agama? </p>', '2024-11-19 05:40:29');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8811, 2438, 102211, 'mahasiswa', 'Ilham', '<p>Sekiranya hari jumat tanggal 22 November 2024 apakah bisa, sekitar jam 14.00 WIB, pak/buk</p>', '2024-11-19 08:27:29');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8812, 2402, 21, 'admin', 'Fita Diana', '<p>Sudah dihubungi melalui WhatsApp dan dijadwalkan konseling</p>', '2024-11-19 11:01:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8813, 2430, 21, 'admin', 'Fita Diana', '<p>Kamu bisa memilih konseling daring/luring tatap muka. Kamu bisa menyebutkan hari dan pukul berapa yaa untuk konselingnya. Nanti akan kami bantu untuk carikan jadwalkan dengan peer counselor yang available</p>', '2024-11-19 11:02:32');
