INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8851, 2455, 101283, 'mahasiswa', 'Brantio', '<p>saya merasa baik baik saja di awal semester, di semester satu dan dua saya hanya aktif berkuliah hanya aktif di satu organisasi, lalu di semester tiga ini saya banyak job untuk menjadi mc dan saya bergabung dengan organisasi eksternal kampus. Awalnya saya tidak mau membuang kesempatan tawaran mc di berbagai acara karena itu merupakan hal yang saya sukai juga untuk mengembangkan bakat saya, akhirnya saya ketinggalan banyak hal dan waktu yang harusnya saya alokasikan untuk belajar jadi berkurang. Hal ini membuat saya tidak aktif di kelas seperti semester semester sebelumnya. Banyak juga faktor lain yang tidak bisa saya ketik karena saya tipikal orang verbal, saya ingin langsung berkonsultasi... tks!</p>', '2024-11-19 21:36:45');
