INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (8857, 2439, 21, 'admin', 'Fita Diana', '<p>Mohon maaf atas ketidaknyamannya, untuk jadwal konseling kami memerlukan beberapa waktu untuk mencari jadwal <em>peer counselor </em>yang available. Apakah berkenan untuk menjadwalkan konseling besok pukul 11.00 atau mungkin di hari dan jam lainnya? Hari ini akan kami bantu untuk carikan jadwal yang available</p>', '2024-11-20 08:23:48');
