INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9026, 2463, 24, 'admin', 'Agnes Damarela', '<p>mohon maaf kak sebelumnya, akan tetapi jam operasional offline hanya sampai dengan pukul 16.00 WIB. Adapun jadwal sebelum itu, mungkin di mulai pukul 15.30. di hari Rabu minggu depan, apakah tidak masalah?</p>', '2024-12-04 11:43:45');
