INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9054, 2477, 24, 'admin', 'Agnes Damarela', '<p>Terimakasih sudah berbagi keluh kesah yang Anda rasakan. Saya mengerti dan paham betul pasti sangat membingungkan di posisi ini dan seperti hilang arah. Apakah sebelumnya kamu sudah mencoba alternatif solusi? Mungkin bisa dijelaskan sejak kapan intensif hal-hal ini menjadi parah dan sejauh mana mengganggu aktivitas Anda sehari-hari?</p>', '2024-12-05 13:30:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9055, 2481, 24, 'admin', 'Agnes Damarela', '<p>Saya akan coba bantu jadwalkan ya kak, apakah available pada Selasa, 10 Desember 2024 pukul 08.30 WIB atau 13.00 WIB?</p>', '2024-12-05 13:33:16');
