INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9061, 2477, 102239, 'mahasiswa', 'Salma Naifah', '<p>Terimakasih kak, izin jawab yaa</p> <p>hal yang saya lakukan akhir-akhir ini main sama temen aja sih kak, saya gatau itu sebuah alternatif solusi apa engga.</p> <p>saya gatau parahnya kapan tapi awal november itu berat-beratnya semakin kesini tuh agak mereda sedihnya cuman ya itu kayak linglung aja gitu :)</p> <p>menurut saya, menganggu kak, saya mau fokus skripsi tanpa distraksi pikiran negatif, mau ngerjain skripsi tp kalo malem tiba tiba nangis terus ketiduran gajadi ngerjain :( terus menganggu juga tiap ketemu sama temen bawaannya kurang enjoy dan sering kesel karena ya itu dibercandain dikit langsung kesel padahal dulu engga, itu menurut saya amenganggu karena kayak "kenapa aku jadi kayak gini" :)</p>', '2024-12-05 14:28:16');
