INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9063, 2489, 102247, 'mahasiswa', 'Davianda Febrian', '<p>Saya merasa punya masalah terhadap diri saya yang berkaitan dengan masa lalu yang dimana membuat saya kurang beradaptasi menjalankan kehidupan merantau di dunia perkuliahan</p>', '2024-12-05 14:56:37');
