INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9352, 2539, 101256, 'mahasiswa', 'Amalia Putri', '<p>Baik, terima kasih banyak</p>', '2025-01-13 14:52:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9353, 2514, 101927, 'mahasiswa', 'Farhan', '<p>Permisi, selamat malam. Mohon maaf sebelumnya karena tidak kunjung memberikan informasi terkait apa yang saya sampaikan sebelumnya karena masih ada keraguan terhadap apakah saya membutuhkan konseling atau tidak. Walau begitu, saya tetap ingin melanjutkan. </p> <p>Terkait ketersediaannya, saya tidak cukup sibuk pekan ini. Kalau bisa menyesuaikan, jadwal saya cukup kosong per hari ini hingga tanggal 24. Mungkin di antara hari Jumat atau hari Minggu pekan ini. Apakah tersedia?</p>', '2025-01-13 18:06:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9354, 2514, 21, 'admin', 'Fita Diana', '<p>Untuk hari Jumat dan Minggu kami tidak ada jadwal konseling yang available, jika berkenan akan dijadwalkan untuk pekan depan di hari Senin atau Selasa begitu?</p>', '2025-01-13 19:15:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9355, 2539, 21, 'admin', 'Fita Diana', '<p>sama-samaa, dengan senang hati ^^</p>', '2025-01-13 19:15:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9356, 2540, 21, 'admin', 'Fita Diana', '<p>Selamat malam, Imaduddin Al-Fata!</p> <p>Terima kasih telah menggunakan layanan konseling. Mohon maaf atas keterlambatan merespon karena banyaknya antrian. Terima kasih yaa sudah mau berbagi cerita mengenai permasalahan Anda kepada saya karena pasti segala hal yang sudah Anda rasakan dan lalui sampai saat ini tidaklah mudah. Untuk lebih memahami kondisi yang sedang Anda rasakan saat ini, bisakah Anda menceritakan lebih lanjut permasalahan apa yang terjadi pada diri Anda mengenai alasan dan penyebab permasalahan tersebut? Atau pemicu awal dari permasalahan yang Anda rasakan? Dan sejak kapan permasalahan ini Anda rasakan? Hal ini digunakan untuk memetakan permasalahan Anda untuk dilakukannya konseling bersama konselor atau <em>peer counselor </em>yang Anda inginkan ^^</p> <p><br /></p> <p>Terima kasih,<br />Salam Hangat,<br />Tim Konseling UB.</p>', '2025-01-13 19:16:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9357, 2514, 101927, 'mahasiswa', 'Farhan', '<p>Boleh. Untuk waktunya tersedia pukul berapa ya? </p>', '2025-01-13 19:17:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9358, 2514, 21, 'admin', 'Fita Diana', '<p>Di hari senin available pukul 11.00 - 12.00</p> <p>Selasa available pukul 08.30 dan 14.00</p>', '2025-01-13 19:18:41');
