INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9363, 2514, 21, 'admin', 'Fita Diana', '<p>Baik, kami jadwalkan konseling hari Selasa, 21 Januari 2025 pukul 14.00 WIB yaa. Untuk informasi lebih lengkap akan kami berikan melalui WhatsApp mendekati hari H. Mohon ditunggu ^^</p> <p>Terima kasih,<br />Tim Konseling UB.</p>', '2025-01-14 06:39:57');
