INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9489, 2563, 102239, 'mahasiswa', 'Salma Naifah', '<p>hai buat ini</p> <p>kak sepertinya aku butuh bantuin lagi deh :(</p> <p>akhir akhir ini aku ngerasa kosong, ga tenang, bingung sendiri, sedih mulu</p> <p>kondisi aku sedih terus kyk ngerasa kasih makan rasa sedih terus tapi kalo dibuat ketawa ketiwi itu gabisaa</p> <p>terus rasanya marah marah terus sama orang terdekat, gamau diajak keluar sama orang kayak rasanya gamau komunikasi sama orang lain maunya sendiri mulu</p> <p>rasanya itu ngejalanin hari rasanya kayak mau tiduran aja, padahal banyak tuntutan skripsi terutama</p> <p>terus ketakutan buat ditinggal sama orang itu besar banget, gimana kalo nanti temen temen aku ninggal aku karena aku ga seru dll<br /></p> <p><br /></p> <p>hal yang akhir akhir ini terjadi di saya gaada si kak, tapi saya masih belajar buat ikhlasin orang-orang yang ngebuang aku yang ninggalin aku</p> <p>juga deadline skripsi yang gatau bisa kekejar apa engga</p> <p>lagi mikir keras nanti kalo abis lulus gadapet kerjaan gimana</p> <p>lagi banyak mikir kalopun nanti dapet kerjaan kalo gajinya kecil gabisa hidupin keluarga gimana sementara saya anak tunggal yang nantinya jadi tumpuan keluarga</p> <p>terus ya masih dikit dikit nangis kalo inget si orang yang ninggal aku ternyata sudah bahagia <br />dikit dikit nangis juga kalo lagi mikir kedepannya gimana huehuehue</p> <p>tapi aku gatau gimana ceritanya dan kesiapa ceritanya kalau ketemen mereka udah banyak pikiran dan cerita aku itu itu aja kalau ke orang tua ga didengerin hehe, tapi selepas itu aku gatau apa yang harus aku ceritakan</p> <p>itu kak aku ngerasa butuh bantuan lagi karena kok hari hari rasanya gini mulu sedih mulu gaada semangat buat ngapa ngapain</p> <p>maaf ya kak aku balik lagi, makasih kakk</p>', '2025-02-05 16:20:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9490, 2563, 27, 'admin', 'Shafhah Raisha', '<p>Selamat sore, Salma! Terima kasih ya telah menghubungi Layanan Konseling UB dan mau berbagi serta menceritakan permasalahan yang sedang kamu rasakan. Kami sangat memahami bahwa hal tersebut tidaklah mudah dan kamu adalah orang yang hebat karena kamu mengenal diri kamu dan mampu untuk mengutarakan apa yang kamu rasakan :)</p> <p>Apakah kamu berkenan untuk melakukan konseling dengan konselor kami? Jika berkenan kami memiliki jadwal konseling yang available pada pekan depan di hari Senin tanggal 10 Februari pukul 11.00 - 12.00 secara offline. Atau jika di luar hari itu, kamu juga bisa melakukan konseling sesuai hari yang kamu inginkan dengan peer counselor (konselor sebaya) kami. </p> <p><br /></p> <p>Mohon konfirmasinya, yaa :) Terima kasih!</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-02-05 16:39:27');
