INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9503, 2564, 27, 'admin', 'Shafhah Raisha', '<p>Okay baik kami bantu jadwalkan di jam tersebut ya, Kak. Informasi selanjutnya akan kami sampaikan melalui WhatsApp mendekati hari pelaksanaan konseling :)</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-02-06 11:31:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9504, 2557, 102304, 'mahasiswa', 'Muhammad Raditya', '<p>Mungkin sebelum perkuliahan dimulai, antara hari ini sampai tanggal 9? Karena saya kebetulan sudah di Malang dan untuk waktu saya rasa bisa menyesuaikan karena masih libur, terima kasih:)</p>', '2025-02-06 11:48:46');
