INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9538, 2553, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Akan kami bantu jadwalkan konselingnya ya kak. Untuk informasi lanjutan mengenai konselingnya akan kami informasikan melalui WA ketika sudah mendekati jadwal konseling.</p> <p>Terima kasih, </p> <p>Salam hangat,</p> <p>Tim Konseling UB.<br /><br /></p>', '2025-02-10 08:59:49');
