INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9547, 2569, 28, 'admin', 'Ishida Ayumi', '<p>Bisa kak, namun untuk menjadwalkan dengan konselor dengan ranah yang cocok, kami memerlukan pemahaman mengenai permasalahan yang anda alami, apakah kakak berkenan untuk menjawab pertanyaan-pertanyaan sebelumnya? Jika tidak berkenan juga tidak apa-apa kak, akan kami coba carikan jadwal dengan konselor kami.</p> <p dir="ltr">Terimakasih, </p> <p dir="ltr">Salam Hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2025-02-10 11:47:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9548, 2568, 101953, 'mahasiswa', 'Ali Akbar', 'Selamat Siang, saya mengalami permasalahan di lingkungan teknik khususnya dengan teman saya yaitu seperti pembullyan verbal dan pengasingan salah satunya. Hal - hal tersebut menganggu kegiatan keseharian khususnya di perkuliahan saya yang menyebabkan saya stress. Harapannya saya dapat mengetahui akar permasalahan dan bisa mengendalikan diri setelahnya. Kira2 kapan saya bisa bertemu?', '2025-02-10 13:10:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9549, 2568, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas kesediaan anda untuk bercerita.  </p> <p>Apakah Anda berkenan untuk konseling pada hari Jumat tanggal 14 Februari pukul 09.00 secara tatap muka?</p> <p>Kami tunggu konfirmasinya ya..</p> <p><br /></p> <p>Terimakasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-02-10 13:29:26');
