INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9563, 2568, 28, 'admin', 'Ishida Ayumi', '<p>Jika di minggu depan bisa di hari senin pukul 08.30 atau di hari selasa pukul 13.00 kak. Bagaimana kak? Apakah tidak apa-apa jika di hari jumat saja?<br /><br />Dan izin mengonfirmasi, mengenai nomor WAnya apakah benar ini kak: 08560606418<br />Karena kami tidak bisa mengakses nomor tersebut di WA.</p> <p><br /></p> <p>Ditunggu konfirmasinya ya kak..</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-02-10 15:13:18');
