INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9567, 2569, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih karena telah bersedia untuk bercerita mengenai hal tersebut. Pasti tidak mudah bagi kakak. Untuk psikolog klinis kami baru available di minggu depan kak. Pada hari Jumat, 21 Februari 2025 pukul 12.30. Jika konseling dilakukan pada waktu tersebut, apakah kakak berkenan? </p> <p><br /></p> <p dir="ltr">Terimakasih, </p> <p dir="ltr">Salam Hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2025-02-11 08:38:31');
