INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9574, 2571, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat pagi, Markus M.!</p> <p dir="ltr">Terima kasih telah menghubungi layanan konseling UB. Kami mengerti apa yang Anda rasakan saat ini bukanlah hal yang mudah. Untuk membantu kami lebih memahami mengenai permasalahan Anda, silahkan bantu kami untuk menjawab beberapa pertanyaan dibawah ini terlebih dahulu yaa :</p> <p dir="ltr"><br /></p> <p>1. Apakah boleh diceritakan lebih lanjut mengenai rasa gelisah yang menggangu anda?<br /></p> <p>2. Bagaimana hal tersebut mengganggu kegiatan keseharian Anda?</p> <p>3. Apa harapan yang ingin Anda peroleh setelah menghubungi layanan konseling kami?</p> <p><br /></p> <p dir="ltr">Apapun respon Anda akan sangat membantu kami untuk memetakan permasalahan lebih lanjut.</p> <p dir="ltr">Terimakasih,</p> <p dir="ltr">Salam Hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2025-02-12 18:50:42');
