INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9673, 2574, 102319, 'mahasiswa', 'Dwi Agustini', '<p>saya sudah coba banyak hal buat lupain masalah ini dan fokus ke kegiatan lain tetapi tidak bisa, saya selalu merasa kesepian dan terus memaksa berkomunikasi dengannya meskipun omongannya buat saya sakit. untuk sekarang saya hanya pengen nyerah saja</p>', '2025-02-16 17:03:11');
