INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9675, 2559, 28, 'admin', 'Ishida Ayumi', '<p>Baik, akan kami bantu jadwalkan ya kak. Untuk koordinasi selanjutnya akan kami hubungi melalui WA. </p> <p><br /></p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-02-16 18:28:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9676, 2574, 28, 'admin', 'Ishida Ayumi', '<p>Saya paham ini bukanlah suatu yang mudah untuk anda. Mungkin menyerah adalah satu-satunya solusi untuk anda sekarang, namun sebenarnya menyerah bukanlah sebuah solusi, banyak kemungkinan lain yang mungkin Anda dapatkan di kemudian hari. Semoga konseling yang dilakukan besok dapat membuat anda menjadi lebih baik. Kami tunggu kehadiran anda besok pada pukul 08.30. Selalu kabari jika anda memiliki pikiran untuk menyakiti diri sendiri. Kami akan coba bantu sebisa mungkin. </p> <p><br /></p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB. </p>', '2025-02-16 18:58:05');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9677, 2574, 102319, 'mahasiswa', 'Dwi Agustini', '<p>saya sekarang mencoba fokus mengerjakan tugas namun yang saya alami adalah perasaan takut, dada sangat sakit, dan kepala sangat berat, saya selalu ingin muntah padahal belum makan dan terus batuk lalu mengalami menggigil</p>', '2025-02-16 19:02:39');
