INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9680, 2576, 28, 'admin', 'Ishida Ayumi', '<p>Baik, akan kami bantu jadwalkan pada tanggal tersebut. Untuk informasi selanjutnya akan kami hubungi melalui WA. </p> <p><br /></p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-02-16 19:09:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9681, 2578, 102201, 'mahasiswa', 'Riska', '<p>Halo kak, mohon maaf untuk di jadwal kamis dan jumat saya full kelas kak, saya kosong di hari senin dan selasa, untuk hari senin saya hanya ada 1 kelas di jam 9.15, sedangkan selasa saya libur. tetapi apabila tidak bisa memungkinkan di hari senin dan selasa, saya akan mengusahakan untuk hari kamis ataupun jumat.</p> <p>Sekali lagi mohon maaf kak, terimakasih.<br /><br /></p>', '2025-02-17 06:02:21');
