INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9807, 2603, 28, 'admin', 'Ishida Ayumi', '<p>Untuk jadwal dengan Bu Ikaf hanya ada di hari Senin pukul 08.30. Namun untuk jadwal Bu Ikaf di minggu depan sudah terisi. Dan baru tersedia di tanggal 10 Maret 2025. Untuk jadwal tersebut apakah Anda bersedia? </p> <p><br /></p> <p>Ditunggu konfirmasinya yaa..</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-02-26 20:10:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9808, 2603, 28, 'admin', 'Ishida Ayumi', '<p>Untuk jadwal dengan Bu Ikaf hanya ada di hari Senin pukul 08.30. Namun untuk jadwal Bu Ikaf di minggu depan sudah terisi. Dan baru tersedia di tanggal 10 Maret 2025. Untuk jadwal tersebut apakah Anda bersedia? </p> <p><br /></p> <p>Ditunggu konfirmasinya yaa..</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-02-26 20:10:07');
