INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9873, 2635, 100852, 'mahasiswa', 'Luh Panitisan', '<p>Selamat malam, perkenalkan saya Luh Gading Panitisan.</p> <p>Pada saat SD saya menjadi korban bullying dan hal tersebut masih membekas pada diri saya hingga sekarang. Saya sering merasa insecrue dan rendah diri yang membuat saya tidak dapat menunjukkan potensi saya secara maksimal dan merasa takut pada berbagai hal. Saya sering menangis apabila mengingat hal tersebut dan beberapa kali terpikir untuk melakukan bunuh diri. Karena tidak ingin hal ini terjadi berulang kali, maka saya memutuskan untuk mendaftar di konseling ini. </p>', '2025-03-04 18:46:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9874, 2604, 102371, 'mahasiswa', 'Alliya Rahayu', '<p>Halo kak Aisyah!</p> <p>Baik kak saya bersedia konsultasi di hari jumat siang kak.</p> <p>Please contact me untuk kelanjutannya!</p> <p>089669263347</p> <p>alliyarahayu@student.ub.ac.id</p>', '2025-03-04 19:13:38');
