INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (9908, 2645, 26, 'admin', 'Nadia Aura', '<p dir="ltr">Selamat pagi, Mahika!</p> <p dir="ltr">Terima kasih telah menghubungi layanan konseling UB. Kami mengerti apa yang Anda rasakan saat ini bukanlah hal yang mudah. Untuk membantu kami lebih memahami mengenai permasalahan Anda, bisakah Anda menjawab pertanyaan kami berikut.</p> <p dir="ltr">1. Apakah ada teman terdekat Anda yang mengetahui cerita ini?<br />2. Kondisi-kondisi seperti apa yang membuat Anda teringat dengan dia?<br /><br />Apapun respon Anda akan sangat membantu kami untuk memetakan permasalahan lebih lanjut.</p> <p dir="ltr">Terima kasih, </p> <p dir="ltr">Salam hangat, </p> <p dir="ltr">Tim Konseling UB.</p>', '2025-03-07 06:19:24');
