INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10037, 2677, 102403, 'mahasiswa', 'PUTRI SYAIFUL', '<p>Saya memiliki waktu luang diantara: </p> <p>1. Selasa 10.00 - 15.00</p> <p>2. Kamis 12.00 - 15.00</p>', '2025-03-12 00:10:12');
