INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10039, 2597, 102367, 'mahasiswa', 'Giannina Aini', '<p>Baik kak, berdasarkan jadwal konseling yang saya lihat di sorotan instagram, saya bisa datang konseling pada waktu-waktu di bawah ini.</p> <p>Selasa: 13.00-14.00</p> <p>Jumat: 12.30-13.30</p> <p>Jumat: 14.00-15.00</p> <p>Terima kasih.</p>', '2025-03-12 00:28:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10040, 2597, 27, 'admin', 'Shafhah Raisha', '<p>Baik, terima kasih atas konfirmasinya, yaaa. Untuk informasi selanjutnya akan kami sampaikan melalui WhatsApp.</p> <p><br /></p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-03-12 08:34:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10041, 2678, 101256, 'mahasiswa', 'Amalia', '<p>Halo, Kak. Terima kasih atas responnya. Saya ingin melakukan konseling lanjutan dengan Ibu Bona. Sejauh ini, saran yang diberikan oleh Ibu Bona berdampak baik pada kondisi mental saya karena saya bisa lebih memahami diri sendiri. Maka dari itu, saya rasa, untuk hal ini, saya masih akan tetap melakukan konseling dengan Ibu Bona agar beliau juga mengetahui perkembangan saya. Terima kasih</p>', '2025-03-12 09:45:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10042, 2674, 102385, 'mahasiswa', 'Nisrina Hanifah', '<p>1. senin 14.30</p> <p>2. selasa 10.00</p>', '2025-03-12 10:28:31');
