INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10119, 2691, 102412, 'mahasiswa', 'Nadya', '<p>Kalau begitu setelah libur lebaran saja tidak apa melalui tatap muka, tidak masalah. Sebelumnya mohon maaf karena saya tidak bisa di Jum''at ini :(</p>', '2025-03-17 20:10:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10120, 2693, 26, 'admin', 'Nadia Aura', '<p>Baik, untuk ruangan konseling sendiri ada di Gedung Rektorat lantai 1. Detailnya akan kami kirimkan besok pagi melalui WhatsApp ya. Terima kasih!</p>', '2025-03-17 21:53:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10121, 2691, 26, 'admin', 'Nadia Aura', '<p>Baik, jika begitu apakah Nadya berkenan untuk melaksanakan konseling di hari Kamis, 10 April pukul 11.00 secara offline?</p> <p>Apabila jadwal yang kami tawarkan tersebut tidak sesuai dengan jadwal kosong Nadya, Nadya bisa kirimkan opsi jadwal kosongnya ya antara Senin-Jumat pukul 9.00-15.00.</p>', '2025-03-17 21:58:07');
