INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10123, 2692, 102392, 'mahasiswa', 'Nailil Falah', '<p>1. sudah setahun lebih</p> <p>2. karena pasangan sy menganggap kita sudah tidak cocok lagi dan dia merasa kalo dilanjutkan akan memperburuk keadaan</p> <p>3. sy biasanya nonton, dengerin kajian, ngaji dan melakukan apapun kegiatan positif, tapi terkadang pikiran pikiran itu suka tbtb datang dan membuat saya gelisah dan tidak tenang lagi</p>', '2025-03-17 23:30:55');
