INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10365, 2742, 102449, 'mahasiswa', 'Vania Utami', '<p>Selalu merasa katakutan berlebih dan sangat takut mengecewakan orang lain. Sudah mrncoba untuk ga memikirkan tetapi selalu ada dan sering nangis tanpa sebab. Hal ini sangat mengganggu kegiatan akademik. Dulu pernah juga seperti ini dan sempat ke psikiater juga.</p>', '2025-04-13 15:23:58');
