INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10368, 2739, 27, 'admin', 'Shafhah Raisha', '<p>Mohon maaf, Ghinaa. Namun, untuk jadwal konseling di hari Selasa tanggal 15 April 2025 sudah tidak tersedia. Jika kami jadwalkan ulang untuk melakukan konseling di hari Kamis, 17 April 2025 pukul 13.30 secara offline apakah Anda bersedia? Mohon konfirmasinya, yaa :)</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-04-14 04:14:58');
