INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10370, 2732, 102440, 'mahasiswa', 'Ana', '<p>terima kasih atas tawarannya, tetapi mohon maaf sebelumnya mungkin untuk kali ini saya tidak jadi berkonsultasi <br /></p>', '2025-04-14 07:37:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10371, 2719, 102432, 'mahasiswa', 'Annisa Vitramardi', '<p>Sebelumnya mohon maaf atas keterlambatan dalam konfirmasi, untuk dua tanggal tersebut saya berhalangan hadir kira kira bagaimana kah, apakah ada jadwal lain yg bisa saya ikuti?</p>', '2025-04-14 07:51:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10372, 2743, 102083, 'mahasiswa', 'Zaidan Wicaksana', '<p>sulit rasanya untuk disiplin sehari2 mengikuti kehadiran kelas dan pengerjaan tugas, terlebih saya adalah mahasiswa mengulang</p>', '2025-04-14 08:52:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10373, 2744, 102450, 'mahasiswa', 'Muhammad Fedayeen', '<p>Aku sekarang dalam beberapa minggu terakhir gatau kenapa sering punya rasa ingin menabrakan diri dan itu aku masih gapaham karna apa dan harus bagaimana? Kegiatanku sehari hari organisasi dan aku ngrasa terkadang banyak hal yang aku semangat untuk mengurus sendiri, aku sering dapat cacian sebagai orang NPD tapi aku bersikap bodoamat karna bagiku semakin tinggi apa yang akan kita gapai artinya semakin kencang hembusan anginnya tapi terkadang itu juga mengganggu. Aku akhir tahun 2024 juga gagal nikah dan akhirnya putus dari pacarku yang sudah 5 tahun dan menurutku itu juga bagian terbesar dari permasalahanku mungkin yang sedang aku alamin, karakteristik orang yang ingin maju terus namun setiap malam selalu merasa ada ketidak pastian hati, banyak berfikir, ada cacian, ada ingata ingatan lama, banyak hal yang tiba tiba muncul sehingga terkadang kalau malam sering keluar sendiri untuk motoran tengah malem muter2 malang disitu sering banget terselip rasa ingin menabrakkan diri terus namun mencoba ku kontrol. Hal yang kupikirkan hingga saat ini adalah terkadang aku sampai ingin untuk akhirnya mencoba kecelakaan dan lupa ingatan sehingga aku merasa diriku memulai hidup yang baru tanpa ada cacian, tanpa ada kenangan masa lalu, tanpa ada apapun. Aku memulai karir dari awal kembali. Mencapai pencapaian pencapaian baru lagi dari awal. Namun aku bingung hal ini harus bagaimana dan caraku mengatasinya seperti apa? </p>', '2025-04-14 09:26:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10374, 2739, 27, 'admin', 'Shafhah Raisha', '<p>Baik, terima kasih atas konfirmasinya. Untuk informasi selanjutnya akan kami sampaikan melalui WhatsApp yaa :)</p>', '2025-04-14 09:30:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10375, 2744, 27, 'admin', 'Shafhah Raisha', '<p>Selamat pagi, Muhammad! </p> <p>Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami apa yang Anda lalui tidaklah mudah dan terima kasih karena sudah mau untuk tetap bertahan sampai saat ini. Apakah Anda berkenan jika kami bantu jadwalkan untuk melakukan konseling di hari Kamis, 17 April 2025 pukul 11.00 WIB secara offline? Mohon konfirmasinya, yaa.</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB </p>', '2025-04-14 10:01:30');
