INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10421, 2751, 102456, 'mahasiswa', 'Muthiasyach Farzis', '<p>ka buat 2 minggu kedepan aku bisa kok setiap hari dari senin-jumat karena lagi kuliah daring, tpi yang pasti mau nya hari rabu jam 10.00-15.00 wib. sama palingan hari jumat dari jam 08.00-15.00 WIB</p> <p>Kenapa harus rabu karena matkul nya cuman satu dan itu di pagi hari doang. </p> <p>Jumat karena emg kosong gada mata kuliah. </p>', '2025-04-16 17:49:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10422, 2749, 102455, 'mahasiswa', 'Yanida Julianinda', '<p>Sejujurnya awalnya saya tidak merasakan hal aneh apapun, saya cukup enjoy menempuh jenjang perkuliahan, karena walaupun saya kurang suka belajar, tapi saya selalu penasaran akan banyak hal. Sampai ada dimana saya ditawari beasiswa percepatan untuk bisa lulus program magister dan jenjang doktor dalam waktu 4 tahun. Awalnya saya merasa saya mampu, dan bisa melaksanakan perkuliahan dengan normal. Tapi setelah 1 tahun berkuliah S2 saya mulai merasa ada yang janggal. Saya itu tipe orang yang lebih suka bepergian atau lebih banyak aktivitas luar dibandingkan harus menetap dalam ruangan. Dimasa-masa itu saya pernah berada di fase mengurung diri didalam kamar kos selama 1 minggu penuh tanpa keluar kamar dan berinteraksi dengan orang. Padahal saya itu paling suka bicara apalagi komunikasi dengan orang. Saya juga sudah sempat coba ke klinik UB untuk konsultasi dan mendapatkan rujukan. Tapi saya takut untuk pergi konsultasi dengan rujukan psikiater. Disamping dari mengurung diri itu, saya juga susah tidur, padahal kantuk sudah menyerang tapi tidak bisa tidur, padahal tidak ada yang dipikirkan ataupun dilakukan, hanya merenung dan diam. Tapi difase itu akhirnya saya bisa coba untuk selesaikan tesis saya walaupun harus terseok2. Diposisi itu saya sudah merasa saya kembali normal kepada diri saya yang lama. Tapi ternyata 2 minggu terakhir saat sudah mulai masuk perkuliahan S3 saya kembali mengalami gejala yang sama ditambah saya selalu merasa apakah saya pantas melanjutkan pendidikan sampai sejauh ini? Saya merasa saya tidak terlalu pintar, saya hanya beruntung bisa diberi kesempatan, saya takut akan banyak omongan negatif tentang saya yang menempuh pendidikan sampai jenjang ini. Dari pemikiran ini saya jadi mengurung diri lagi di dalam kamar, walaupun perkuliahan saya tetap berjalan, selepas kuliah saya benar-benar mengurung diri tanpa keluar kalau memang tidak ada jadwal kelas normal. Padahal banyak hal yang harus saya lakukan, entah mengerjakan tugas kuliah, menjalankan penelitian dan lain sebagainya. Saya juga sudah berusaha menghubungi banyak orang untuk menanyakan apakah saya ini masih normal atau memang ada yang salah. Tapi kalau saya tidak punya jawaban untuk pertanyaan saya sendiri, bagaimana orang lain bukan? Mereka juga pasti sama bingungnya dengan saya, mereka ingin bantu tapi tidak paham juga harus membantu seperti apa. Semoga setidaknya dengan bercerita disini saya bisa mendapatkan sedikit bantuan jawaban atas segala hal yang saya pertanyakan:")<br />Terima kasih</p>', '2025-04-17 03:39:20');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10423, 2751, 25, 'admin', 'Ribby Aura', '<p>Baik kak, terima kasih untuk responnnya. Untuk selanjutnya akan kami hubungi di WhatsApp yaa</p>', '2025-04-17 08:10:41');
