INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10511, 2775, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf untuk jadwal tersebut sudah terisi, berikut beberapa opsi yang dapat Anda pilih:</p> <p>- Selasa, 29 April 2025 pukul 08.30 (online)</p> <p>- Selasa, 29 April 2025 pukul 13.00 (online)</p> <p>Kami tunggu konfirmasinya yaa..</p> <p><br /></p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-04-22 18:07:48');
