INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10570, 2779, 29, 'admin', 'Aisyah Salsa', '<p>Baik, terima kasih atas konfirmasinya ya. Konseling dilaksanakan pada <strong>Kamis, 01 Mei 2025 pukul 11.00 WIB</strong>, secara <strong>online melalui via Google Meet</strong>. Informasi lebih lanjut akan kami sampaikan melalui WhatsApp, ya.</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-04-27 18:47:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10571, 2784, 29, 'admin', 'Aisyah Salsa', '<p>Baik, terima kasih atas konfirmasinya ya. Konseling dilaksanakan pada <strong>Senin, 12 Mei 2025 pukul 08.30 WIB</strong>, bertempat di <strong>Ruang Konseling, Layanan Konseling UB (Gedung Rektorat Lantai 1)</strong>. Informasi lebih lanjut akan kami sampaikan melalui WhatsApp, ya.</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-04-27 18:48:04');
