INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10589, 2790, 102483, 'mahasiswa', 'Nasywa', '<p>Saya merasa semua teman saya tidak suka saya, menganggap saya payah, tidak percaya saya untuk melakukan sesuatu, sampai saya jadi sangat sensitif dengan ucapan orang2. Saya merasa sangat rendah diri dan untuk bicara dengan orang lain sangat sulit. Saya merasa tiba2 tidak bisa bicara depan banyak orang dan napas saya sangat sangat sesak. </p>', '2025-04-29 23:50:43');
