INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10681, 2811, 102103, 'mahasiswa', 'Ramadhan Kusumah', '<p>nama panggilana saya rama atau asta terserah bisa dipanggil yang mana, saya aga takut mengenai kondisi perkuliahan saya sekarang yang aga berantakan pkl belum mulai, skripsi tidak jalan, mata kuliah satu dua tiga berjalan bersamaan. sekarang setiap kali saya membuka laptop bukannya mengerjakan tugas tapi hanya melihat layar. takut untuk memulai dan saya tidak paham dari maan hambatan ini. keluarga juga mulai menanyakan kondisi saya bingung perlu menjawab apa karena tidak seperti teman saya yang kemungkinan bisa lulus semester ini, saya sepertinya hanya bisa lulus semester depan. apakah ada solusi untuk ini?</p>', '2025-05-04 12:20:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10682, 2799, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf untuk yang tanggal 29 Mei sudah terisi juga kak, jadi baru tersedia tanggal 5 Juni pukul 09.00 untuk konseling bersama Bu Bona. Apakah Anda berkenan kami jadwalkan pada tanggal tersebut?</p> <p>Mohon maaf sekali lagi,</p> <p>Kami tunggu konfirmasinya ya..</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-05-04 14:29:57');
