INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10686, 2793, 28, 'admin', 'Ishida Ayumi', '<p>Untuk konselingnya nanti akan melalui gmeet dan untuk tautan gmeet dan nama peer counselor (konselor sebaya) akan kami informasikan melalui WA. Dan ketika konseling dengan peer counselor (konselor sebaya), konseling akan berlangsung selama 40 menit-60 menit. Dan untuk jadwal konselingnya bisa berubah ketika ada kondisi yang tidak memungkinkan, namun setelah kami jadwalkan harapannya Anda bisa melakukan konseling di jadwal yang sudah ditentukan. Jika pada hari senin pukul 13.00, apakah Anda bersedia melakukan konseling dengan peer counselor kami?</p> <p>Kami tunggu ya konfirmasinya..</p> <p>Terima kasih,</p> <p>Salah hangat,</p> <p>Tim Konseling UB.</p>', '2025-05-04 17:46:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10687, 2789, 28, 'admin', 'Ishida Ayumi', '<p>Terima kasih atas respon yang diberikan.</p> <p>Untuk kami jadwalkan konseling dengan peer counselor kami, Anda bisa memilih hari senin-jumat pada pukul 07.00-15.00, beri kami 2 opsi pilihan!</p> <p><br /></p> <p>Kami tunggu konfirmasinya yaa...</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-05-04 17:50:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10688, 2801, 28, 'admin', 'Ishida Ayumi', '<p>Bisa secara offline. </p> <p>Untuk kami jadwalkan konseling dengan peer counselor kami, Anda bisa memilih hari senin-jumat pada pukul 07.00-15.00, beri kami 2 opsi pilihan!</p> <p><br /></p> <p>Kami tunggu konfirmasinya yaa...</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-05-04 18:05:38');
