INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10738, 2769, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Jika dirasa jadwal tersebut terlalu lama bagi Anda, kami juga bisa jadwalkan untuk  konseling dengan peer counselor (konselor sebaya) kami sebelum Anda melakukan konseling dengan psikolog klinis kami. Namun jika dirasa tidak diperlukan, anda bisa memilih hanya di tanggal 26. Akan kami jadwalkan pada tanggal 26 Mei 2025 pukul 08.30, dan untuk informasi selanjutnya akan kami hubungi melalui WA mendekati waktu konseling.</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-05-05 20:34:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10739, 2800, 102493, 'mahasiswa', 'Siti Febrine', '<p>Halo, Terima kasih banyak sebelumnya. </p> <p>sekiranya saya tersedia di hari Jumat, 23 Mei 2025 pukul 12.30 WIB yaa.</p> <p>sekali lagi terima kasih untuk tanggapannya, saya tunggu informasi selanjutnya.</p>', '2025-05-05 23:11:49');
