INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10814, 2826, 102516, 'mahasiswa', 'Maria Pudyanenggar', '<p>Terima kasih, mohon maaf baru membalas. Saya izin mengajukan jadwal di antara:</p> <p>1. Selasa. 13 Mei 2025 pukul 11.00 atau</p> <p>2. Kamis, 16 Mei 2025 pukul 11.00</p> <p>Terima kasih banyak</p>', '2025-05-11 21:31:07');
