INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10821, 2838, 102527, 'mahasiswa', 'Erina', '<p>Berawal dari ibu meninggal, ayah yang menikah lagi, ekonomi, kesehatan menurun, pendidikan, karir, dan gagal percintaan </p>', '2025-05-12 10:23:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10822, 2839, 101636, 'mahasiswa', 'Andini Wijayanti', '<p>Biasanya selalu memendam,  setiap sedih berusaha mengabaikan dan cuek aja</p> <p>Tapi akhir2 ini sering kali tiba2 emosi meledak2 cuman bbrp menit setelah itu menyesal dan sedih kenapa saya seperti itu dan telanjur membuat orang tua kecewa</p> <p>Saya ga percaya diri, banyak hal yg saya lewatkan karena saya malu atas diri saya sendiri, saya obesitas dan selalu diabaikan</p> <p>Merasa diabaikan, tidak didengar, dan lain sebagainya ini saya gasuka dengan perasaan saya sendiri</p> <p>Bingung, ini emang saya yg aneh, masalah ada di saya, saya kurang bersyukur, atas masalah ini saya selalu menyalahkan diri sendiri, saya yg salah, saya kesel sama orang lain, tapi saya yg salah</p> <p>Apapun kejadian gaenak yg saya rasakan, itu kesalahan saya</p> <p>Kecewa dengan diri sendiri, saya capek marah ke diri sendiri</p> <p>Padahal kalau dipikir2 pas lagi biasa aja sebenernya yaa emg salah orang, tapi balik lagi salahnya ada di saya yg gabisa mengelola emosi dengan baik</p> <p>Dulu saya merasa bisa mengelola emosi dengan baik, karena saya sabar, saya gapernah nunjukin kalau saya ga nyaman, hampir selalu saya mengiyakan permintaan orang lain, tapi mungkin ternyata itu memendam dan sekarang sudah overload</p> <p>Saya juga takut gagal, banyak ujian, banyak pelajaran yg harus saya kuasai, saya gak pd dan takut banget gagal</p>', '2025-05-12 11:51:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10823, 2832, 102521, 'mahasiswa', 'Adzka Ibrochim', '<p>1. Saya menjadi cenderung menutup diri ketika mengalami masalah, hal ini membatasi saya untuk berinteraksi tanpa beban-beban pikiran mengenai masalah saya. Dan juga, saya mulai memikirkan cara-cara ataupun hal-hal yang akan saya lakukan kepada diri saya dengan maskdu melukai diri. Untuk saat ini saya mengatasinya dengan mengunci pisau dan benda tajam yg saja miliki di laci meja saya.</p> <p>2  Saya berharap bahwa sesi konseling ini memberikan saya bantuan dalam menghadapi situasi saat ini dan kedepannya jika terjadi kembali.</p> <p>Terimakasih banyak atas bantuannya</p>', '2025-05-12 12:06:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10824, 2802, 102494, 'mahasiswa', 'Dewi Utari', '<p>1. Senin, 12 Mei 2025. Pukul 10.10 WIB</p> <p>2. Iya</p> <p>3. Gemetaran, takut, keringetan, pusing, nangis</p> <p>4. Iya</p> <p>5. Harapan saya agar dapat mengontrol emosi agar lebih stabil</p>', '2025-05-12 13:11:31');
