INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10835, 2828, 29, 'admin', 'Aisyah Salsa', '<p>Baik kak, terima kasih atas konfirmasinya. Akan kami bantu jadwalkan dengan peer counselor pada Kamis, 15 mei 2025 pukul 13.00. Terkait info selanjutnya akan kami hubungi melalui via WhatsApp yaa...</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-05-13 09:10:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10836, 2838, 102527, 'mahasiswa', 'Erina', '<p>1. Merasa bersalah, sendirian, dan tidak diterima </p> <p>2. Kosong</p> <p>3. Kesehatan, kuliah dan percintaan </p> <p>4. Tidak pernah cerita, saya merasa cerita tidak menyelesaikan masalah. Dan saya tidak percaya dengan semua orang.</p> <p>5. Mendapatkan insight dan penanganan. Karena saya sering merasa cemas berlebihan yang membuat saya tidak bisa mengendalikan ritme pernapasan dan membuat tubuh saya kaku tidak bisa bergerak.</p>', '2025-05-13 09:28:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10837, 2826, 102516, 'mahasiswa', 'Maria Pudyanenggar', '<p>Selamat pagi kak izin bertanya, untuk konseling pukul 11.00 nanti apakah akan jadi dilaksanakan? Lalu apakah melalui gmeets/zoom ya? Juga untuk linknya apakah disediakan dari pihak konselor atau dari saya, terima kasih kak</p>', '2025-05-13 10:11:31');
