INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10871, 2845, 29, 'admin', 'Aisyah Salsa', '<p>Selamat pagi, Elvina!</p> <p>Terima kasih sudah berbagi dengan sangat terbuka kepada Layanan Konseling UB. Kami memahami bahwa saat ini kamu sedang menghadapi banyak tantangan dari berbagai sisi baik secara personal, relationship, hingga trauma yang pastinya mengganggu kegiatan akademik. </p> <p>Terkait dengan perasaan dan pengalaman yang Anda alami, kami ingin memastikan bahwa Anda mendapatkan ruang aman untuk membahasnya lebih lanjut bersama tenaga profesional yang dapat membantu Anda. Apakah anda berkenan jika kami jadwalkan pada hari Selasa, 27 Mei 2025 pukul 13.00?</p> <p>Kami tunggu konfirmasinya yaa...</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-05-15 07:21:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10872, 2845, 102531, 'mahasiswa', 'Elvina Fadhilah', '<p>Selamat pagi,</p> <p>Baik, saya bisa yaa hari Selasa, 27 Mei 2025 pukul 13.00</p> <p>Terima kasih </p>', '2025-05-15 08:26:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10873, 2847, 102533, 'mahasiswa', 'Ryan', '<p>Iya, saya sangat butuh sekali untuk konsultasi dan bertatap muka secara langsung </p>', '2025-05-15 12:31:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10874, 2714, 26, 'admin', 'Nadia Aura', '<p>Baik kak, mohon maaf sebelumnya. Apabila di kemudian hari ingin melakukan konseling di layanan konseling UB, dapat menghubungi kami kembali ya kak.</p> <p>Terima kasih dan mohon maaf atas ketidaknyamanannya.</p>', '2025-05-15 14:33:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10875, 2826, 26, 'admin', 'Nadia Aura', '<p>Untuk proses konseling selanjutnya akan kami koordinasikan selalu melalui whatsapp ya kak. terima kasih</p>', '2025-05-15 14:36:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10876, 2840, 26, 'admin', 'Nadia Aura', '<p>Baik terima kasih kak Alisha atas jawabannya. Kami menghargai keterbukaan kakak kepada kami. Untuk selanjutnya apakah kakak berkenan melakukan konseling bersama peer counselor kami? Apabila berkenan, bisakah kakak beritahu kami jadwal kosong kakak di minggu depan? </p> <p>Mohon konfirmasinya ya ^<br /></p> <p>Terima kasih.</p>', '2025-05-15 14:41:29');
