INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10958, 2864, 102549, 'mahasiswa', 'Muhammad', '<p>Hati dan Jiwa saya terguncang karena suatu permasalahan, pada akhirnya saya mulai merasa bahwa "hati" ini mulai mati dan menutup semenjak kejadian tersebut. Saya tidak memiliki semangat lagi untuk melakukan apapun, padahal seharusnya saya harus menyelesaikan seluruh tanggung jawab skripsi di semester ini...</p>', '2025-05-19 09:49:23');
