INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10962, 2865, 102505, 'mahasiswa', 'Farrel Andika', '<p>pekenalkan nama saya Farrel Azarya Zidan Andika jadi penyebab awalnya adalah karena saya masuk jurusan ini bener bener tanpa basic dan otodidak,jadi menghambat ke proses belajar saya,saya ingin sekali seperti temen temen saya yang lain bisa memahami pelajaran dengan mudah,kalau saya karena sulit memahami dan malas belajar jadi ngerjain tugas ketergantungan dengan ai sehingga tidak dapat memahami kemampuan saya sendiri. bagaimana jalan keluar/solusi yang bisa saya lakukan dalam situasi seperti ini?</p>', '2025-05-19 11:37:20');
