INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10979, 2866, 102550, 'mahasiswa', 'Salwa', '<p>Baik Mba. Mungkin awalnya karena saya baru saja mengalami kemalangan, di saat saya masih berkabung saya merasa harus menarik diri dari kehidupan sosial saya, setelah mengalami kemalangan saya juga lebih sering menangis dan sulit mengontrol emosi saya. Berbeda dengan sebelumnya, pada saat ada masalah kecil hal tersebut sama sekali tidak mengganggu pikiran saya dan saya bisa menyelesaikan dengan tepat, tapi sekarang saya merasa hal kecil saja bisa membuat saya terjerumus dalam bayang-bayang ke gagalan. Saya akan mulai membandingkan pencapaian saya pada saat SMA dengan saya yang sekarang ini. Setelah kemalangan, saya juga lebih banyak merenung, meskipun hal ini terjadi hanya saat saya sendirian di kost, pada saat saya bersama teman-teman saya, saya adalah 2 orang yang berbeda. Saya juga belum terlalu memahami diri saya dengan baik. Mungkin diagnosa saya juga masih salah, karena saya hanya terbiasa membaca situasi sosial, sayangnya saya tak bisa membaca dan memahami emosi saya sendiri. Sekian, selanjutnya mungkin akan saya serahkan kepada Mba.</p>', '2025-05-19 21:57:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10980, 2866, 27, 'admin', 'Shafhah Raisha', '<p>Baik, terima kasih atas jawabannya, yaa. Sangat membantu kami untuk memetakan permasalahan lebih lanjut. Mohon maaf sekali sebelumnya dikarenakan jadwal konseling dengan psikolog kami untuk bulan ini sudah full dan tidak tersedia sehingga baru bisa dilakukan di bulan depan. Apakah Anda berkenan jika konseling dilakukan dengan peer counselor kami terlebih dahulu? Jika berkenan, Anda silahkan memilih jadwal dari hari Senin sampai Jumat mulai pukul 09.00 hingga 16.00 WIB, yaa. Mohon konfirmasinya :)<br /></p>', '2025-05-19 22:03:13');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (10981, 2866, 102550, 'mahasiswa', 'Salwa', '<p>Baik Mba. Mungkin awalnya karena saya baru saja mengalami kemalangan, di saat saya masih berkabung saya merasa harus menarik diri dari kehidupan sosial saya, setelah mengalami kemalangan saya juga lebih sering menangis dan sulit mengontrol emosi saya. Berbeda dengan sebelumnya, pada saat ada masalah kecil hal tersebut sama sekali tidak mengganggu pikiran saya dan saya bisa menyelesaikan dengan tepat, tapi sekarang saya merasa hal kecil saja bisa membuat saya terjerumus dalam bayang-bayang ke gagalan. Saya akan mulai membandingkan pencapaian saya pada saat SMA dengan saya yang sekarang ini. Setelah kemalangan, saya juga lebih banyak merenung, meskipun hal ini terjadi hanya saat saya sendirian di kost, pada saat saya bersama teman-teman saya, saya adalah 2 orang yang berbeda. Saya juga belum terlalu memahami diri saya dengan baik. Mungkin diagnosa saya juga masih salah, karena saya hanya terbiasa membaca situasi sosial, sayangnya saya tak bisa membaca dan memahami emosi saya sendiri. Sekian, selanjutnya mungkin akan saya serahkan kepada Mba.</p>', '2025-05-19 22:16:11');
