INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11258, 2918, 102665, 'mahasiswa', 'Tiara Fazilatunnisa', '<p>Selamat pagi. Untuk di tanggal tersebut sebenarnya aku belum tahu bisa atau enggak, karena itu masuk dalam minggu UAS dan dari fakultas belum keluar jadwal ujiannya. Mungkin kalau sudah keluar jadwalnya nanti perlu konfirmasi lagi atau bagaimana ya?? Terima kasih</p>', '2025-06-03 13:27:13');
