INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11281, 2927, 102685, 'mahasiswa', 'Wardah Mufidah', '<p>Saya stres setiap saya sedang penelitian di laboratorium semua langkah yang saya kerjakan selalu gagal, supervisor saya selalu bilang saya gak berpikir ke depan, saya gak paham troubleshooting, saya gabisa decision making, suka ngerusakins esuatu, pasti gagal, gak cerdas dan lain sebagainya. semua kerjaan saya pasti ada kesalahan, gagal, gak sesuai hasil, ngulang terus berkali-kali. saya stres juga soalnya dikasih topik skripsi tapi bingung mau mulai darimana. saya gatau harus gimana soalnya semuanya kaya ketumpuk, kaya gak mampu dikerjain. intinya saya stres, apa jadi saintis bukan jalan hidup saya ya?</p>', '2025-06-04 21:32:33');
