INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11391, 2954, 102708, 'mahasiswa', 'Keisya Zoraya', '<p>Saya kehilangan minat untuk melakukan kewajiban sehari-hari karena beban akademik dan beban non-akademik yang sedang tinggi hingga tidak mampu menyesuaikan</p>', '2025-06-16 08:47:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11392, 2955, 102709, 'mahasiswa', 'Dwi Putri', '<p>akhir" ini saya sering mengalami susah untuk tidur, rasanya saat mau tidur perasaan dan fikiran tidak tenang jadi menyebbakan susah tidur. sudh mencoba memejamkan mata tapi tetep susah untuk tidur, saat sudh bisa tidur saya kebangun" terus kemudian tidur lagi kemdian bangun lagi dalam jangka waktu yang sebentar. lalu saya terbangun karena merasa saya sesek nafas akibat mimpi saya, jadi saya merasa nafas saya terburu buru hingga membuat saya terbangun. setelah terbangun gara" sesek nafas ini saya jadi tidak bisa tidur lg, namun jika saya pun bisa tidur lagi tetap kembali seperti awal (bangun-tidur-bangun-tidur-repeat dengan perasaan yg tidak tenang). kemudian sy selalu merasa sy tidak dianggap oleh orang" tertentu di lingkungan saya, sy merasa sy tidak pernah terlihat dan omongan sy diabaikan, hal tsb karena sy merasa tanggapan atau respon org di sekitar sy yg membuat sy merasa seperti itu, hingga sy merasa sedih dan memikirkan salah sy apa. </p>', '2025-06-16 09:49:58');
