INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11396, 2941, 102697, 'mahasiswa', 'Feti Shaila', '<p>Mohon maaf, Konseling UB untuk tanggal 24 saya masih di Gunung Arjuno karena sudah booking dari jauh jauh hari yang tidak dapat ditinggalkan. </p> <p>Apakah saya dapat mengganti tanggal jadwal konseling menjadi tanggal 25</p>', '2025-06-16 10:41:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11397, 2923, 102255, 'mahasiswa', 'Megi S', '<p>Selamat pagi Bapak/Ibu Dr Tim e Konsuling</p> <p>Sehubungan dari pertanyaan dari Bapak/Ibu, </p> <p>Bahwa ybs dia tidak memiliki hubungan dekat dengan keluarganya .Ybs pernah cerita jika sejak dia menjadi tunadaksa, keluarganya tidak menerima dia dan dianggap tidak bermanfaat dan seprtinya ybs tidak ingin bertemu keluarganya,kenyataanya sehari-hari di malang dia hidup tidak layak. Kami juga sudah nasehati agar bertemu dengan keluarganya, meski tidak punya ortu tapi masih ada kel besar nya namun ybs menolak.</p> <p>Karena selama ini kami melihat bahwa cerita dari ybs murni dari sisi ybs , sehingga Pak Adam menyarankan agar ybs dikaitkan/dikoneksikan dengan keluarganya dan barangkali saja keluarganya tsb sebenarnya sangat ingin bertemu dan membantu ybs</p> <p>DPKA UB</p>', '2025-06-16 10:47:33');
