INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11417, 2952, 26, 'admin', 'Nadia Aura', '<p>Selamat sore, Bagas! Sebelumnya terima kasih telah menghubungi layanan konseling UB. </p> <p>Untuk asesmen awal dan menentukan langkah selanjutnya, bolehkah Anda ceritakan secara lebih detail terkait permasalahan tersebut?</p> <p>Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya.</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-06-16 15:08:16');
