INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11423, 2903, 26, 'admin', 'Nadia Aura', '<p>Selamat pagi, Vanya! Mohon maaf baru membalas pesan kembali. untuk itu, apakah Anda bersedia melakukan konseling di bulan depan? karena psikolog kami di bulan ini sudah penuh. Jika Anda berkenan, kami bisa menjadwalkan di Selasa, 1 Juli 2025 pukul 10.30. </p> <p>Mohon konfirmasinya ya ^^</p> <p>Terima kasih</p>', '2025-06-17 04:30:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11424, 2903, 26, 'admin', 'Nadia Aura', '<p>Selamat pagi, Vanya! Mohon maaf baru membalas pesan kembali. untuk itu, apakah Anda bersedia melakukan konseling di bulan depan? karena psikolog kami di bulan ini sudah penuh. Jika Anda berkenan, kami bisa menjadwalkan di Selasa, 1 Juli 2025 pukul 10.30. </p> <p>Mohon konfirmasinya ya ^^</p> <p>Terima kasih</p>', '2025-06-17 04:30:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11425, 2923, 26, 'admin', 'Nadia Aura', '<p>Selamat pagi. Baik, terima kasih untuk informasi yang telah diberikan kepada kami. Menindaklanjuti hal ini, apakah Megi berkenan untuk melakukan konseling bersama dengan psikolog kami terlebih dahulu agar kami mendapatkan gambaran lebih mendalam terkait permasalahan dan apa yang harus dilakukan kedepannya?</p> <p>Terima kasih</p>', '2025-06-17 04:34:12');
