INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11623, 3057, 102731, 'mahasiswa', 'Moh Darwis', '<p>Tentu, boleh pukul 12.30. Apakah konseling dilakukan melalui pesan teks atau melalui zoom? saya mengharapkan melalui pesan teks, namun jika sulit, tidak apa melalui zoom atau sejenisnya</p>', '2025-06-30 16:12:44');
