INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11680, 3072, 102744, 'mahasiswa', 'Hafizh wahyudi', '<p>1. Keinginan untuk cuti</p> <p>2. ⁠stress dengan kuliah</p> <p>3. ⁠banyak ketertinggalan </p> <p>4. ⁠merasa tertinggal </p> <p>5. ⁠minder dengan teman yang lain karna ketercapaian yang lebih dibanding diri sendiri</p> <p>6. Banyak permasalahan keluarga </p>', '2025-07-08 18:41:54');
