INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11683, 3073, 102745, 'mahasiswa', 'Henny Indarwaty', '<p>Saya mudah marah dan tersinggung. Saya merasa paranoid. Saya merasa orang orang membenci dan memusuhi saya. Saya merasa tidak dihargai hanya karena orang tidak membalasa WA saya dll. Mungkin saya punya inferior complex. Saya pendendam namun juga pencemas. Saya cemas orang orang memusuhi saya. Saya cemas dengan anak-anak saya. Saya cemas Ketika si kecil duduk dekat pintu. Saya cemas jika anak-anak tidka cuci tangan. Saya jadi Lelah memikirkan banyak hal</p>', '2025-07-09 09:45:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11684, 3073, 27, 'admin', 'Shafhah Raisha', '<p>Selamat pagi, Henny! </p> <p>Terima kasih telah menghubungi Layanan Konseling UB. Kami dapat memahami apa yang Anda rasakan tidaklah mudah dan membuat Anda tidak nyaman. Untuk membantu permasalahan Anda, apakah Anda berkenan untuk kami bantu jadwalkan konseling dengan psikolog kami di hari Selasa, 15 Juli 2025 pukul 10.30 WIB? Konseling dapat dilakukan secara online/offline menyesuaikan dengan kebutuhan dan kenyamanan Anda. Mohon konfirmasinya, ya :)</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-07-09 11:22:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11685, 3073, 102745, 'mahasiswa', 'Henny Indarwaty', '<p>Terima kasih responnya</p> <p>Mohon maaf minggu depan ada akreditasi.</p> <p>Apakah saya bisa menjadwal ulang di senin, tgl 21?</p>', '2025-07-09 11:28:25');
