INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11687, 3073, 102745, 'mahasiswa', 'Henny Indarwaty', '<p>Mohon maaf tgl 22 sy workshop di Malaysia.</p> <p>Bgmn jika jumat, 18 Juli? </p> <p>mohon maaf merepotkan </p> <p>Seperti itulah jadwal sy yg terus menerus hingga tak sempat cari bantuan konseling</p>', '2025-07-09 17:58:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11688, 3074, 102746, 'mahasiswa', 'Trian Ferianto', '<p>Seperti ada mental block. Padahal studi reguler berjalan normal dan baik. Seperti ada hambatan perfeksionis yg akhirnya menghambat progress penulisan thesis. </p>', '2025-07-09 20:23:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11689, 2949, 102703, 'mahasiswa', 'Feliza Putri', '<p>jika hanya melalui chat terhadap psikolog apa bisa ya, karena kadang jika meet atau zoom berlangsung kondisi saya suda baik, jadi kdg tida baik kadang baik</p>', '2025-07-09 20:30:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11690, 3073, 29, 'admin', 'Aisyah Salsa', '<p>Baik, terima kasih atas konfirmasinya ya. Konseling akan kami jadwalkan pada <strong>Jum''at, 18 Juni 2025 pukul 12.30 WIB</strong>, bertempat di <strong>Ruang Konseling, Layanan Konseling UB (Gedung Rektorat Lantai 1)</strong>. Informasi lebih lanjut akan kami sampaikan melalui WhatsApp, ya.</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-07-10 09:10:34');
