INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11757, 2892, 102574, 'mahasiswa', 'Novita Elyana', '<p>Selamat siang,</p> <p>Akhirnya saya membuka tiket ini kembali. Saya rasa saya butuh konseling secara offline</p>', '2025-07-15 14:28:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11758, 3082, 102753, 'mahasiswa', 'Hanif Rabbani', '<p>untuk harinya saya bisa setiap hari kak, namun untuk jamnya mungkin saya baru free habis maghrib sekitar 18.30</p>', '2025-07-15 17:09:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11759, 2892, 28, 'admin', 'Ishida Ayumi', '<p>Selamat malam Novita, mohon maaf baru membalas. Untuk waktunya bisa di hari dan jam berapa ya kak? Agar bisa kami jadwalkan dengan peer counselor kami..</p> <p>Kami tunggu konfirmasinya,</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-07-15 21:33:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11760, 3088, 102759, 'mahasiswa', 'Guido Silalahi', '<p>umur saya 22 tahun. selama itu saya lumayan diperlakukan keras selama hidup saya. saya punya kakak perempuan dan adik laki laki, namun hanya saya yang diperlakukan keras oleh ayah saya baik secara verbal ataupun non-verbal. perlakuan demikian juga diberikan oleh mama dan kakak saya walau tidak separah papa saya. pada saat saya masuk sekolah dasar sampai kelas 1 smp saya juga diperlakukan sama karena memang pada saat itu saya mempunyai fisik yang lebih kecil daripada teman teman sebaya yang lain, kalau memang saya boleh berasumsi sendiri mungkin karena saya lebih mudah untuk dijadikan target daripada teman teman yang lain. perlakuan-perlakuan verbal dari berbagai pihak itu membuat saya tumbuh menjadi pribadi yang lebih kasar secara verbal dengan maksud untuk <em>self-defense </em>agar tidak mudah diremehkan oleh orang lain.</p> <p>dari perlakuan non-verbal yang diberikan oleh berbagai manusia kepada saya, saya juga tumbuh menjadi orang yang bingung dalam hal perasaan dan tindakan. saya tidak bingung perasaan apa ketika saya merasakannya, saya tau kapan saya merasa sedih senang dll. yang saya bingungkan mungkin seperti "duh gue boleh ga ya ngerasa kyk gini?" atau "duh gaboleh lah sedih sedih mulu, lemah" atau "kira kira kalo dihadepin masalah kyk gini, gue bener ga ya kalo ngelakuin ini?"</p> <p>karena cenderung tidak diberikan ruang untuk merasakan emosi emosi yang ada secara penuh, atau ruang untuk berpikir sendiri, sampai sekarang saya merasa bingung dengan diri sendiri.</p>', '2025-07-16 07:05:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11761, 3082, 28, 'admin', 'Ishida Ayumi', '<p>Selamat pagi kak, mohon maaf baru membalas. Untuk konfirmasi penjadwalan akan kami hubungi melalui WA. Terima kasih. </p>', '2025-07-16 08:38:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11762, 3088, 28, 'admin', 'Ishida Ayumi', '<p>Selamat pagi, Guido!</p> <p>Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk mendiskusikan lebih lanjut hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal di minggu ini sudah penuh, jadwal dengan psikolog kami baru tersedia di minggu depan. Berikut opsi jadwal yang dapat Anda pilih:</p> <p dir="ltr">- Senin, 21 Juli 2025 pukul 08.30 (daring/luring)</p> <p dir="ltr">- Rabu, 23 Juli 2025 pukul 12.30 (daring/luring)<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-07-16 09:00:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11763, 3089, 102761, 'mahasiswa', 'Anindya Wardhani', '<p>beberapa kali mengalami peristiwa traumatis, seperti kekerasan fisik dan verbal oleh keluarga di waktu kecil, beberapa kali terkena bullying oleh teman semasa SD-SMP. sewaktu SMA, bullying itu berhenti karena saya memilih opsi untuk membuat skenario kehidupan yang menarik sehingga orang orang tidak perlu merundung saya. selanjutnya, proses itu membuat saya memiliki teman yang dimana akhirnya saya amat sangat tergantung dengan kehadiran teman tersebut, ketergantungan ini terus berlanjut pada orang orang yang menunjukkan rasa sayangnya pada saya sehingga saya merasa saya disayang oleh beberapa orang. namun saya belum berdamai dengan semua hal yang menimpa saya di masa lalu, saya terus membohongi diri sendiri bahwa saya bisa lari dari memori tersebut dengan membuat rekayasa cerita kehidupan yang terlihat bahwa saya orang yang memiliki kehidupan normal seperti lainnya. pada akhirnya kebohongan kebohongan tersebut menjadi bumerang untuk saya, saya yang juga seorang people pleaser sering merasa senang apabila dilibatkan pada banyak hal karena saya merasa bermanfaat, tapi hal ini ternyata membebani saya secara tidak langsung. 2 faktor tersebut, kebohongan dan people pleaser membawa saya ada trauma baru, yang mana saya malah merugikan banyak orang, terutama mantan pacar saya (yang waktu itu adalah pacar saya. trauma tersebut ternyata disebarluaskan olehantan saya sendiri ke teman teman saya, sehingga saya sempat cuti 1 semester dan saat ini saya berniat melanjutkan studi saya namun, memori memori traumatis itu sering kali menghantui saya, mulai dari memori saya sewaktu kecil hingga memori terakhir saya. dalam hal ini, saya harus melakukan tindakan apa? karena saya tidak ingin terus terusan menghindari lingkungan fakultas saya sampai saya lulus.</p>', '2025-07-16 12:35:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11764, 3089, 28, 'admin', 'Ishida Ayumi', '<p>Selamat sore, Anindya!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk mendiskusikan lebih lanjut hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal di minggu ini sudah penuh, jadwal dengan psikolog kami baru tersedia di minggu depan. Berikut opsi jadwal yang dapat Anda pilih:</p> <p>- Senin, 21 Juli 2025 pukul 08.30 (daring/luring)</p> <p>- Rabu, 23 Juli 2025 pukul 12.30 (daring/luring)</p> <p>- Jumat, 25 Juli 2025 pukul 12.30 (daring/luring)</p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /><br /></p>', '2025-07-16 15:09:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11765, 3090, 102762, 'mahasiswa', 'Hilma Dhelianti', '<p>belakangan ini saya sering tiba-tiba cemas. dada saya sesak, sulit bernapas, dan selalu ada dorongan untuk memukul kepala. dulu saya pernah seperti ini, tapi tidak sesering dan seintens sekarang. saya juga tiba-tiba merasa akan segera meninggal, membuat saya takut untuk tidur dan bepergian. dulu, “serangan” ini biasanya ada trigger-nya, tapi sekarang tidak. serangannya datang tiba-tiba, tidak tahu kenapa. saya benar benar terganggu karena tidak bisa melakukan aktivitas seperti biasanya ditambah cemas dan sesak yang terus datang</p>', '2025-07-17 07:20:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11766, 3091, 101514, 'mahasiswa', 'Silmy Nafisah', '<p>saya mahasiswa semester akhir yang sebentar lagi akan di drop out. sebenarnya untuk skripsi saya, saya tinggal menyelesaikan revisi seminar hasil dan pemberkasan yudisium. saya baru saja sidang tadi pagi, namun pada saat sidang saya merasa saya bukan diri saya yang dulu, penuh dengan ambisi dan mimpi. bahkan saya tidak pernah mendapatkan nilai C di khs saya. sekarang saya merasa sangat bodoh dan tidak berambisi sama sekali. saya mulai merasa frustasi sejak ayah saya wafat saat saya di semester 7 (ketika baru mulai mengerjakan skripsi). saya merasa kehilangan sebagian dari diri saya dan lelah menjalani hidup, tahun 2022 saya sudah 2 kali mencoba untuk mengakhiri hidup namun gagal. di masa masa tersebut sangat tidak mengenakkan, karena rasanya seperti dimusuhi otak sendiri. saya sering kali berpikir yang buruk terlebih dahulu tentang apapun, terutama diri saya sendiri. saat itu keluarga maupun teman terdekat tidak ada yang tahu mengenai ini, karena saya selalu cenderung berusaha menutupi hal ini. bahkan sampai sekarang pun keluarga saya belum ada yang tau. tahun 2023 saya mencoba membaca buku mengenai cara menghadapi depresi dan itu cukup menyelamatkan saya. tahun tsb saya sempat menjauhi urusan perkuliahan dan berusaha mencari teman dan lingkungan yang supportif terhadap saya. sejauh ini berhasil. namun bulan ini saya banyak berurusan dengan kuliah, karena status saya sekarang adalah mahasiswa kritis. kembali berurusan dengan perkuliahan rasanya seperti membuka luka lama. hari ini saya seperti kembali dimusuhi otak sendiri. saya merasa sangat bodoh saat sidang tadi dan penuh penyesalan. pikiran buruk saya mulai merembet kemana mana. saya ingin menyerah namun saya tidak ingin mengecewakan orang orang yang sudah mendukung saya sejauh ini.</p>', '2025-07-17 17:44:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11767, 3092, 102061, 'mahasiswa', 'Leny Susanto', '<p>Halo admin,,<br /></p> <p>Saat ini saya sedang dalam kondisi mental yang sangat tidak stabil. Saya merasa sangat lelah, tidak termotivasi, dan kewalahan dengan banyak hal. Apakah saya bisa mengajukan sesi konseling lanjutan dengan Bu Ulifa atau counselour lainnya?<br /></p> <p>Saya benar-benar merasa butuh bantuan segera.<br /></p> <p>Terima kasih banyak dan maaf mengganggu waktunya </p>', '2025-07-17 20:18:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11768, 3093, 101183, 'mahasiswa', 'Rima', '<p>Sebagai mahasiswa <strong>fast track S2-S3 Fakultas Pertanian UB</strong>, saya mengajukan konseling psikologis karena menghadapi tantangan signifikan yang menghambat progres studi dan memengaruhi kesejahteraan mental saya. Saya memiliki riwayat <strong>keterlambatan kelulusan</strong> baik di S1 maupun S2, dengan pengalaman hampir menyerah melanjutkan S3 saat lulus 1 bulan lebih lambat dari target. Pola ini diperparah oleh <strong>kecemasan berlebihan terhadap studi</strong>, <strong>trauma dan ketakutan spesifik terhadap dosen tertentu</strong> akibat kejadian tidak menyenangkan di masa lalu, serta adanya <strong>pola prokrastinasi dan perfeksionisme</strong> dalam mengerjakan tugas akademik yang secara signifikan memperburuk stres dan penundaan. Lebih lanjut, kondisi mental saya juga dipengaruhi oleh <strong>tekanan psikologis dari pengalaman personal</strong>, termasuk <strong>pelecehan verbal dari ayah</strong> (saat ini) dan <strong>pelecehan fisik dari keluarga</strong> (dulu), yang saya khawatir berdampak negatif pada kondisi psikologis dan kemampuan saya dalam menjalani studi. Oleh karena itu, saya sangat membutuhkan bantuan profesional untuk memahami akar masalah ini, mengembangkan strategi koping yang efektif, serta memulihkan kondisi mental saya, dengan tujuan utama untuk dapat mengatasi hambatan-hambatan tersebut dan menuntaskan studi <em>fast track</em> ini secara optimal dan tepat waktu.</p>', '2025-07-18 15:38:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11769, 3094, 102367, 'mahasiswa', 'Giannina Aini', '<p>Aku merasa kesepian, seolah nggak ada yang benar-benar ngerti atau ada buat aku. Aku ingin cerita ke seseorang yang bisa bantu aku memahami perasaan ini tanpa menghakimi.</p>', '2025-07-18 20:37:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11770, 3095, 102763, 'mahasiswa', 'Aliyah', '<p>Saya baru saja putus dengan mantan saya dengan alasan saya memasang afinitas dengan teman lelaki saya. Saya mengatakan padanya setelah merenungkan beberapa hari dan saya memutuskan untuk mengatakannya kepadanya. Saya memasang afinitas tersebut sudah cukup lama dari 1 tahun yang lalu di suatu game kita sebut saja "H". Dulu saya pernah bermain dengan teman lelaki saya setahun yang lalu dan memutuskan untuk memasang afinitas sebagai pasangan hanya sebagai simbol saja bukan lebih. Pertemanan kita sudah berjalan hampir 5 tahun. Tapi baru sebulan setelah saya setelah memasang afinitas itu saya tidak lagi memainkan game itu dan menghapus gamenya. Saya juga memiliki beberapa masalah dengan teman saya jadi saya menjaga jarak dengannya. Baru beberapa hari ini saya mendownload game itu lagi dan menyadari bahwa saya pernah memasang afinitas itu ke teman saya. Lalu saya menceritakan ini ke mantan saya dan mantan saya menyuruh saya menghapus afinitas itu tapi saya menolak karena saya merasa saya lebih baik menyudahi hubungan dengan mantan saya karena saya merasa hubungan kita sudah mulai toxic dan tidak bisa dilanjutkan lagi. Sebagai tambahan, sebelum saya bermain game "H" saya sudah putus dengan mantan saya. Lalu setelah putus dengan kurun waktu hampir 2 minggu dimana saya akhirnya memutuskan menghibur diri dan memainkan game itu lagi dan mengajak teman saya itu kembali bermain. Entah di beberapa waktu saya merasa kangen pada mantan saya. Saya sempat mengirimkan buket bunga ke tempatnya dan saya menyuruhnya mengambilnya tapi tidak apa jika dia memutuskan ingin membuang karena kita sudah tidak ada hubungan. Tetapi setelah dia menjawab entah kenapa saya merasa kangen dan mengajak balikan. Itu adalah penyesalan terbesar saya karena dari awal saya memutuskan dia karena saya merasa pacaran sudah menyimpang dari agama saya dan karena dia memiliki sifat yang cukup childish untuk menangani masalah ataupun membuat masalah itu sendiri. Saya kerap kali memberi tahu dia bagaimana seharusnya dia bertindak tapi saya merasa tidak ada perubahan dari dia meskipun dia berjanji akan berubah untuk saya. Singkat cerita mantan saya setelah saya ajak balikan masih menanyai apakah saya benar benar serius akan itu tapi saya tidak menjawabnya karena sebenarnya saya masih ragu. Setelah beberapa waktu dari dia mulai memanggil saya dengan panggilan sayang lagi, saya menyadari bahwa dia menganggap bahwa saya menyutujui pertanyaan dia. Itu sangat membuat saya bingung harus melakukan apa karena saya tidak ingin melanjutkan hubungan dengannya. Saya merenung dan memikirkan alasan apa yang harus saya berikan padanya. Lalu disitulah saya berkata jujur bahwa saya memasang afinitas dengan teman saya. Saya terus meminta maaf dan membiarkan dia menyalahkan saya. Saya tidak masalah jika harus take all the blame. Saya juga mengharapkan dia mendapatkan pasangan yang lebih baik dari saya meskipun tanggapannya adalah "Makasih sudah sadar". Dia terlihat sangat marah dan mengatakan bahwasanya dia sudah lost interest dengan saya di pertengahan masa pacaran pertama kami sebelum putus. Kita pacaran sudah 3 bulan, saya kira dia menyebut bahwa dia sudah mulai lost interest di bulan kedua kami berpacaran. Alasan kenapa dia lost interest adalah karena saya pernah bermain game bersama teman lelaki saya yang lain waktu itu (bukan yang saya sebutkan di awal), saya sudah jujur dan mengatakannya tanpa menutupi apapun. Saya dan teman lelaki saya itu sudah membayar game itu berdua karena kita sangat ingin mencoba game itu dikarenakan game itu yang memiliki rating yang sangat tinggi dan mahal. Saya sadar saya telah membuat kesalahan dan saya meminta maaf. Dan masalah itu sudah selesai karena akhirnya kita kembali seperti pasangan biasanya pada waktu itu.<br /><br />Setelah kami putus yang terakhir ini, saya merasa hubungan kita selesai sampai situ saja. Sampai saya melihat dia menghina saya di sosial media. Dia menghina saya dengan memanggil saya "bajingan" dan dia bilang saya manipulatif karena playing victim(?). Saya bingung kenapa saya dibilang playing victim, apakah karena waktu itu saya pernah mengatakan bahwa dia adalah orang yg childish dan gila perempuan karena dia suka menonton VTUBER dan suka memosting ulang video artis korea dan menjadikannya story maupun profile picturenya. Saya tidak begitu yakin tapi saya tidak sengaja melihat salah satu post dia yang berisi dia sedang memainkan suatu game kompetitif dimana ada salah satu teman yang berkata di comment section, "Coba kamu yang kemarin main pakai hero itu di tournament bukan si victim mentality itu" dengan beberapa likes di komennya. Untuk sedikit tambahan cerita, saya pernah mewakilkan nama angkatan untuk bermain game kompetitif itu dengan salah satu hero yang membawa kita sampai juara 3 saja. Jujur melihat komen itu membuat saya tambah down dan cemas. Sebelumnya saat dia memanggil saya "bajingan" memang saya merasa tertekan sampai saya harus blocked beberapa akun dia untuk memastikan kesehatan mental saya dan ragu untuk cerita kesini tapi setelah melihat postingan dan komen itu saya merasa benar benar terancam dan membutuhkan pertolongan. Saya beberapa kali menangis dan menyalahkan diri saya. Saya merasa saya tidak bisa menghadapi semester depan jika semua orang menghindari saya. Saya hanya punya 1 teman di kampus dan teman saya punya kesibukan sendiri jadi saya kerap sendirian. Dengan dia (mantan saya) yang memiliki banyak koneksi dan teman, saya merasa akan dijauhi semua orang. Saya tidak tahu harus bagaimana lagi, saya tidak bisa tidur semalaman, jam tidur saya kacau dan tidak memiliki motivasi untuk melakukan apapun. Saya merasa saya berlebihan tapi saya sendiri tidak yakin lagi dengan diri saya sendiri.</p>', '2025-07-19 03:19:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11771, 3090, 25, 'admin', 'Ribby Aura', '<p><span style="vertical-align:inherit"><span style="vertical-align:inherit">Halo, Hilma. Terima kasih sudah menghubungi layanan konseling UB dan mempercayakan pada kami. Saya tau bahwa tidak mudah untuk bisa terbuka, oleh karena itu saya sangat mengapresiasi keterbukaan kakak. Mungkin bisa dibantu untuk menjawab pertanyaan kami yaa kak:</span></span></p> <p><br /></p> <p><span style="vertical-align:inherit"><span style="vertical-align:inherit">1. Coba ceritakan sejak kapan kakak merasa cemas dan apa alasan kakak merasa kambuh?</span></span></p> <p><br /></p> <p><span style="vertical-align:inherit"><span style="vertical-align:inherit">2. Coba ceritakan apakah selama kakak merasa cemas, hal tersebut mengganggu kehidupan sosial kakak?</span></span></p> <p><br /></p> <p><span style="vertical-align:inherit"><span style="vertical-align:inherit">3. Apa yang kakak harapkan dari sesi konseling ini?</span></span></p> <p><br /></p> <p><span style="vertical-align:inherit"><span style="vertical-align:inherit">Kami tunggu penjelasannya ya, Kak Hilma! Terima kasih :)</span></span></p>', '2025-07-19 14:34:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11772, 3091, 25, 'admin', 'Ribby Aura', '<p>Terimakasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Saya sangat memahami pasti situasi ini tidak mudah untuk dilalui. Saya mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Saya akan coba bantu jadwalkan sesi dengan psikolog kami. Jika berkenan, apakah Anda ingin melakukan konseling pada hari Jumat, 25 Juli 2025 pukul 14.00 WIB secara online? Terima kasih.</p>', '2025-07-19 14:42:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11773, 3092, 25, 'admin', 'Ribby Aura', '<p>Terimakasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Saya sangat memahami pasti situasi ini tidak mudah untuk dilalui. Saya mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Saya akan coba bantu jadwalkan sesi dengan psikolog kami. Mohon maaf untuk jadwal Bu Ulifa minggu depan sudah full, apakah kakak berkenan jika melakukan konseling offline pada tanggal 30 Juli 2025 pukul 12.30? Terima kasih.</p>', '2025-07-19 14:48:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11774, 3094, 25, 'admin', 'Ribby Aura', '<p>Halo, Giannina. Terima kasih sudah menghubungi layanan konseling UB dan mempercayakan pada kami. Saya tau bahwa tidak mudah untuk bisa terbuka, oleh karena itu saya sangat mengapresiasi keterbukaan kakak. Mungkin bisa dibantu untuk menjawab pertanyaan kami yaa kak:</p> <p><br /></p> <p>1. Coba ceritakan sejak kapan kakak merasa kesepian dan apa alasan kakak merasa kambuh?</p> <p><br /></p> <p>2. Coba ceritakan apakah selama kakak merasa kesepian, hal tersebut mengganggu kehidupan sosial kakak?</p> <p><br /></p> <p>3. Apa yang kakak harapkan dari sesi konseling ini?</p> <p><br /></p> <p>Kami tunggu jawabannya ya, Kak Giannina! Terima kasih :)</p>', '2025-07-19 15:09:28');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11775, 3095, 25, 'admin', 'Ribby Aura', '<p><span style="vertical-align:inherit"><span style="vertical-align:inherit">Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Saya sangat memahami pasti situasi ini tidak mudah untuk dilalui. Saya mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Saya akan mencoba membantu menjadwalkan sesi dengan psikolog kami. Apakah kakak berkenan untuk melakukan konseling dengan konselor kami, Kak Andini, pada Selasa, 22 Juli 2025 08.30. Terima kasih.</span></span></p>', '2025-07-19 15:12:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11776, 3093, 25, 'admin', 'Ribby Aura', '<p>Terimakasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Saya sangat memahami pasti situasi ini tidak mudah untuk dilalui. Saya mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Saya akan coba bantu jadwalkan sesi dengan psikolog kami, Bu Wira, 1 Agustus 2025 pukul 14.00 WIB secara online? Terima kasih.</p>', '2025-07-19 15:49:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11777, 3088, 102759, 'mahasiswa', 'Guido Silalahi', '<p>Selamat sore, maaf baru bisa membalas<br />saya bersedia untuk melakukan konseling pada Rabu, 23 Juli 2025 pukul 12.30 WIB secara luring<br />Terima kasih atas perhatiannya</p>', '2025-07-19 17:58:26');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11778, 3095, 102763, 'mahasiswa', 'Aliyah', '<p>Saya berkenan untuk melakukan konselingnya di hari dan di jam tersebut</p>', '2025-07-19 20:37:13');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11779, 3096, 100665, 'mahasiswa', 'Aulia W', '<p>Saya sering mengalami kecemasan, overthingking, hingga demotivasi atau bahkan menyalahkan diri sendiri akibat trigger dari lingkungan sekitar yang selanjutnya berdampak ke munculnya trigger dari trauma pribadi/hal-hal yg sudah lewat</p>', '2025-07-19 23:21:28');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11780, 3092, 102061, 'mahasiswa', 'Leny Susanto', '<p>Sebelumnya mohon maaf baru balas</p> <p>Terima kasih atas responnya. Iya saya berkenan untuk melakukan konseling offline pada tanggal 30 Juli 2025 pukul 12.30</p>', '2025-07-20 03:27:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11781, 3093, 101183, 'mahasiswa', 'Rima', '<p>Mohon izin ibu, apakah saya bisa meminta Bu Yunita sebagai konselor saya? Kemarin saya sudah meminta izin melalui wa dan Diminta untuk menuliskan di kolom tiket tapi saya terlupa. Mohon informasinya ibu</p>', '2025-07-20 06:56:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11782, 3088, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Untuk informasi selanjutnya akan kami hubungi melalui WA. </p>', '2025-07-20 17:51:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11783, 3095, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf dikarenakan terdapat pergantian jadwal secara tiba-tiba dari konselor kami, sehingga jadwal konseling pada waktu tersebut tidak tersedia. Berikut opsi jadwal yang dapat Anda pilih sebagai pengganti:</p> <p>- Selasa, 22 Juli 2025 pukul 19.00 (daring)</p> <p>- Jumat, 25 Juli 2025 pukul 14.00 (daring)</p> <p><br /></p> <p>Kami tunggu konfirmasinya yaa,</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB. </p>', '2025-07-20 18:01:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11784, 3096, 28, 'admin', 'Ishida Ayumi', '<p>Selamat Malam, Aulia!</p> <p>Mohon maaf baru membalas e-ticket Anda. Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail mengenai kecemasan, overthinking, dan demotivasi yang Anda alami? Menurut Anda apa penyebab hal tersebut terjadi?</p> <p dir="ltr">2. Dari emosi-emosi yang Anda rasakan tersebut, apa efeknya ke kegiatan keseharian Anda? Dan apakah sudah sangat mengganggu?</p> <p dir="ltr">3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /></p>', '2025-07-20 18:04:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11785, 3093, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Untuk jadwal dengan Bu Yunita di minggu ini sudah terisi dan baru tersedia di tanggal 29 Juli 2025 pukul 10.30. Jika kami jadwalkan pada jadwal tersebut apakah Anda bersedia?</p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-07-20 18:06:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11786, 3092, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf sekali lagi kak, terdapat kesalahan pemberian opsi jadwal dari kami, untuk jadwal dengan Bu Ulifa hanya tersedia pada 2 minggu sekali, dan baru tersedia di tanggal 6 Agustus 2025 pukul 12.30. Apakah Anda bersedia untuk menunggu dan kami jadwalkan pada jadwal tersebut? </p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /></p>', '2025-07-20 18:10:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11787, 3096, 100665, 'mahasiswa', 'Aulia Widodo', '<p>Banyak hal yg bisa menjadi trigger, mulai dari pertemanan, akademik, ataupun hanya sekedar melihat update dari sosial media orang lain terutama yg berkaitan dgn masa depan (misal sudah wisuda, sudah mendapat kerja, tampak bahagia mempunyai banyak teman, orang2 tampak baik2 saja dan sy merasa saya sendiri yg terjebak (stuck) atau bahkan tertinggal. Sy cukup sulit untuk menguraikan apa yg ada di pikiran saya terutama ketika triggered, terlalu penuh. Cukup mengganggu ke kegiatan sehari-hari selama beberapa hari seperti kehilangan motivasi utk melakukan apapun bahkan yg harus secepatnya saya selesaikan. Terkadang sy tahu apa yg harus saya lakukan tp rasanya sia-sia atau tidak mempan. Sy merasa butuh org lain utk membantu menguraikan apa yg saya pikirkan dan saya rasakan. Kalau bisa berharap lebih, sy perlu ilmu utk bagaimana meng-handle hal ini dgn baik</p>', '2025-07-20 18:22:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11788, 3095, 102763, 'mahasiswa', 'Aliyah', '<p>Jadwal yang memungkinkan sepertinya tanggal 22 Juli pada pukul 19.00</p>', '2025-07-20 18:26:01');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11789, 3092, 102061, 'mahasiswa', 'Leny Susanto', '<p>Halo admin,, ya boleh saya bersedia untuk ambil sesi konseling pada tanggal tersebut,, terima kasih</p>', '2025-07-20 18:41:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11790, 3097, 102764, 'mahasiswa', 'Vio Prasetyani', '<p>Belakangan ini saya merasa mood saya sering kali berubah ubah, gampang capek, dan sering menarik diri. Sebelumnya saya juga pernah begitu tapi kali ini rasanya sangat intens dan sering membuat saya sesak. Saya sebelumnya ini sedang magang, berangkat pukul 9 pulang pukul 4, karena lingkungan kerja yang kurang mendukung sering kali energi saya terkuras habis dan saya enggan berinteraksi dengan orang, termasuk pacar saya. Pacar saya seringkali meminta untuk bertemu (hampir setiap hari) atau sekadar mengobrol lewat telepon, tapi saya sangat capek dan tidak bisa, namun saya juga tidak enak menolak secara terus menerus. Jika saya memang diberi waktu sendiri saya seringkali merasa overthinking dan takut, tapi disisi lain saya juga seringkali berpikir untuk menyudahi hubungan saya tapi saya tidak bisa. Saya seringkali merasa marah dan kesal (bahkan ke orang lain disekitar saya, terutama diri saya sendiri). Belakangan juga saya tertimpa musibah yang melibatkan uang, saya merasa sangat tertekan, dengan keadaan yang tidak stabil saya harus tetap mencari pekerjaan. Saya sempat berpikir untuk menyakiti diri saya sendiri (frekuensi sering, dalam satu minggu bisa 4-5 kali terpikirkan). Saya merasa saya aneh dan tidak berguna, saya juga merasa semakin jauh dengan teman teman saya (semester akhir). Saya takut sendirian, tapi saya juga overwhelmed apabila seseorang terus berinteraksi dengan saya. </p>', '2025-07-20 19:33:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11791, 3067, 102739, 'mahasiswa', 'Rangga Febrian', '<p><br /></p> <p>Selamat malam, Kakak-kakak tim konseling UB</p> <p>Terima kasih atas sebelumnya mendengar curhatan panjang-lebar masalah finansial saya. Waktu itu saya lagi banyak pikiran. Saat ini saya hanya mau menceritakan sesuatu, sedikit tidak enak jika menghilang tanpa mengabarkan.</p> <p>Saat ini saya sudah tidak ada masalah lagi, seperti masalah finansial. Saya sudah memikirkan berbagai cara halal mendapatkan uang meskipun tanpa modal. Sebelumnya saya pernah membantu suatu project dengan keahlian saya, meskipun saya tidak mengharapkan apapun awalnya, tiba-tiba saya dikontak dan diberikan uang dari kinerja saya. Katanya hasil saya sangat memuaskan, dimana waktu itu project yang harusnya dikerjakan seminggu atau dua minggu, dapat diselesaikan sama saya dalam dua hari. Saya juga mendapatkan surat rekomendasi berkat itu. Di sisi lain, dari uang project itu, akhirnya saya dapat memutar uangnya di saham dimana saya memiliki keahlian. Kebetulan waktu itu ada IPO dan saya berhasil menghasilkan banyak uang dari sana. Mungkin saja ini keajaiban karena setelah saya diberikan uang dari project, tidak lama ada IPO yang sangat menarik. Akhirnya saya dapat membiayai segala kebutuhan hidup saya termasuk bayar kos dan beli baju wisuda. Saya juga coba paylater, tapi jangan berpikir negatif dulu. Saya menemukan celah dari paylater toko oren, dimana kalau saya top up e-walletnya selalu kena biaya admin/transfer, jadi saya menghindari hal itu melalui paylater. Tenang saja, saya beli jika ada uangnya atau artinya saya tidak paylater tanpa uang. Lagi pula saya anak ekonomi jadi sangat mengerti hal-hal ini. Selain itu, saya juga selalu bayar tepat waktu atau bahkan sebelum jatuh tempo karena saya selalu menyiapkan uang sebelum paylater (no money, no paylater), bayar tepat waktu = terhindar dari bunga. Dari hal tersebut juga saya coba bangun kredit skor saya di SLIK OJK. Di sisi lain, kebetulan saya sering main game namanya Mobile Legends (ML), saya cukup mahir di game tersebut sebagai user roamer karena sudah rank IMO atau rank tertinggi dan top global salah satu hero. Waktu saya tidak ada uang untuk beli kuota dan party tim saya ngajak main, teman saya langsung belikan kuota untuk saya sebagai ganti membantu dia karena user roamer sangat sedikit, terutama yang mahir dan memiliki chemistry. Jadi sejak saat itu, teman saya selalu membelikan kuota untuk saya sehingga saya terlepas dari masalah internet. </p> <p>Oleh karena itu, semua masalah finansial saya sudah teratasi dan saya juga kemungkinan lulus cum laude. Tinggal menunggu waktu untuk Wisuda. Saya akan pulang kampung, jadi ini mungkin last saya menghubungi konseling. Oh ya jangan diberitahu siapa-siapa ya terkait ini.</p> <p>Terima kasih banyak lagi atas sebelumnya</p> <p>Salam hangat</p> <p>Saya<br /></p> <p><br /></p>', '2025-07-20 21:00:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11792, 3067, 26, 'admin', 'Nadia Aura', '<p>Selamat pagi, Rangga! Terima kasih telah menghubungi kembali layanan konseling UB.</p> <p>Kami turut berbahagia mengetahui perkembangan kehidupan Anda. Ini membuktikan bahwa Anda memang benar-benar berjuang dan saat ini adalah waktu Anda untuk menikmati hasilnya. Terima kasih karena sudah bertahan dan berjuang sejauh ini. Kami sangat apresiasi atas semangat Anda untuk memperjuangkan ini semua. Semangat selalu untuk setiap tahap dalam kehidupan ini. </p> <p>Kami akan senantiasa merahasiakan cerita ini. Terima kasih telah mempercayakan cerita Anda pada kami. Apabila di kemudian hari membutuhkan kami kembali, hubungi saja melalui e tiket. </p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-07-21 07:09:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11793, 3092, 26, 'admin', 'Nadia Aura', '<p>Baik, terima kasih atas konfirmasinya. Untuk informasi selanjutnya akan kami kabari melalui WhatsApp ya. </p> <p>Terima kasih</p>', '2025-07-21 07:15:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11794, 3095, 26, 'admin', 'Nadia Aura', '<p>Baik, terima kasih atas konfirmasinya. Untuk informasi selanjutnya akan kami kabari melalui WhatsApp ya.</p> <p>Terima kasih.</p>', '2025-07-21 07:21:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11795, 3096, 26, 'admin', 'Nadia Aura', '<p>Selamat pagi, Aulia! </p> <p>Terima kasih atas cerita yang Anda berikan. Kami paham apa yang Anda rasakan saat ini tentu tidak mudah. Untuk itu, kami akan arahkan Anda pada sesi konseling bersama dengan psikolog kami. Silahkan pilih salah satu dari kedua jadwal berikut.</p> <p>1. Jumat, 25 Juli 2025 pukul 14.00 (online)</p> <p>2. Selasa, 29 Juli 2025 pukul 13.00 (offline)</p> <p>Mohon konfirmasinya ya ^^</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB. </p>', '2025-07-21 07:32:05');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11796, 3097, 26, 'admin', 'Nadia Aura', '<p>Selamat pagi, Vio! Terima kasih telah menghubungi layanan konseling UB.</p> <p>Kami paham apa yang Anda rasakan saat ini tentu tidak mudah. Kami apresiasi atas keterbukaan Anda pada kami. Untuk menindaklanjuti hal tersebut, kami tawarkan Anda untuk melakukan konseling bersama psikolog kami di hari Kamis, 31 Juli 2025 pukul 09.00. Apakah Anda berkenan melakukan konseling di waktu tersebut?</p> <p>Mohon konfirmasinya ya ^^</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB. </p>', '2025-07-21 07:38:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11797, 3097, 102764, 'mahasiswa', 'Vio Prasetyani', '<p>Selamat pagi, terima kasih atas responnya.</p> <p>Ya, saya bersedia konseling pada jadwal tersebut.</p> <p>Terima kasih.</p>', '2025-07-21 09:01:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11798, 3093, 101183, 'mahasiswa', 'Rima', '<p>Baik saya bisa pada waktu tersebut. Terimakasih bapak/ibu </p>', '2025-07-21 09:47:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11799, 3098, 102765, 'mahasiswa', 'Vianta Mandhalika', '<p>Saya bermasalah dengan pembimbing disertasi yang perkataan nya selalu berubah-ubah terlebih terkait dengan pendanaan penelitian. Saya juga bermasalah dengan rumitnya pendidikan s3.</p>', '2025-07-21 13:06:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11800, 3093, 26, 'admin', 'Nadia Aura', '<p>Selamat siang, kak Rima!  Sebelumnya terima kasih atas konfirmasinya. </p> <p>Tetapi mohon maaf kak, untuk jadwal Bu Yunita di tanggal 29 Juli ternyata sudah penuh. Apakah kakak berkenan untuk kami alihkan di Selasa, 5 Juli 2025 pukul 10.30? </p> <p>Mohon konfirmasinya ya kak. Mohon maaf atas ketidaknyamanannya. </p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB. </p>', '2025-07-21 13:23:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11801, 3097, 26, 'admin', 'Nadia Aura', '<p>Baik, terima kasih atas konfirmasinya. Informasi selanjutnya akan kami kabari melalui WhatsApp ya. </p>', '2025-07-21 13:25:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11802, 3098, 26, 'admin', 'Nadia Aura', '<p>Selamat siang, Vianta! Terima kasih telah menghubungi layanan konseling UB. </p> <p>Kami paham apa yang Anda rasakan saat ini tentu tidak mudah, dan kami apresiasi atas keterbukaan Anda terhadap kami. Namun, agar kami mengetahui permasalahan Anda lebih dalam, bisakah Anda menceritakan lebih lengkap mengenai rumitnya pendidikan s3 yang Anda alami? </p> <p>Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya.</p> <p>Terima kasih, </p> <p>Salam hangat,</p> <p>Tim Konseling UB. </p>', '2025-07-21 13:33:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11803, 3099, 102758, 'mahasiswa', 'Kholiq Aziz', '<p>Konseling lanjutan terkait penanganan kasus saya yaitu ancaman, penyebaran, dan pencemaran nama baik yang sedang ditangani satgas PPKS. Untuk saat ini saya membutuhkan pendampingan psikologi untuk menjaga kondisi mental saya. Mohon dengan sangat dapat diberikan jadwal segera, karena sudah dari hampir satu bulan yang lalu meminta jadwal konseling lanjutan tetapi tidak segera mendapat jadwal. Mungkin kondisi mental saya tidak separah orang lain, tapi mohon dengan sangat hal ini tidak bisa dianggap sepele dan terus menerus menunda jadwal konseling.</p>', '2025-07-21 14:05:20');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11804, 3099, 26, 'admin', 'Nadia Aura', '<p>Selamat sore, Kholiq! Terima kasih telah menghubungi layanan konseling UB.</p> <p>Mohon maaf sebelumnya dikarenakan e tiket Anda baru masuk di sistem kami sore ini, sehingga kami baru bisa menjawab sekarang. Kami sangat memahami apa yang Anda hadapi saat ini tentu tidak mudah. Namun, untuk dapat memahami permasalahan lebih dalam, bisakah Anda ceritakan apa yang menjadi keluhan atau detail permasalahan Anda sehingga ingin melakukan konseling? </p> <p>Apapun jawaban Anda akan membantu kami menentukan langkah berikutnya.</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB. </p>', '2025-07-21 17:50:13');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11805, 3099, 26, 'admin', 'Nadia Aura', '<p>Selamat sore, Kholiq! Terima kasih telah menghubungi layanan konseling UB.</p> <p>Mohon maaf sebelumnya dikarenakan e tiket Anda baru masuk di sistem kami sore ini, sehingga kami baru bisa menjawab sekarang. Kami sangat memahami apa yang Anda hadapi saat ini tentu tidak mudah. Dan kami sadari dengan penuh bahwa tidak ada kondisi mental yang bisa disepelekan. Namun, untuk dapat memahami permasalahan lebih dalam, bisakah Anda ceritakan apa yang menjadi keluhan atau detail permasalahan Anda sehingga ingin melakukan konseling? </p> <p>Apapun jawaban Anda akan membantu kami menentukan langkah berikutnya.</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB. </p>', '2025-07-21 17:50:13');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11806, 3100, 102766, 'mahasiswa', 'TesAja">', '<p>testing aja"&gt;</p>', '2025-07-21 18:04:05');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11807, 3101, 102253, 'mahasiswa', 'Erich', '<p>Saya sering merasakan rasa cemas yang berlebihan dan hal ini ini mengganggu akademik saya. Gejala yang saya alami mencakup tremor, tidak fokus, panik, dan mual hingga lemas bila parah. Namun, gejala yang paling saya sering alami adalah tremor dan tidak fokus. Bidang studi saya, bioteknologi, berkaitan erat dengan kegiatan laboratorium yang membutuhkan ketelitian yang tinggi. Setiap kali saya bekerja di laboratorium, tangan saya tremor tidak terkontrol dan kaku. Hal ini menyebabkan saya sulit bekerja dan rekan atau supervisor meragukan saya. Saya tahu betul kurangnya pengalaman dapat menyebabkan gugup dan tremor. Namun, saya rasa ini berbeda. </p> <p><br /></p> <p>ketika saya bandingkan dengan rekan-rekan saya, hanya saya yang masih saja merasakan cemas dan tremor yang berlebihan meskipun berangkat dari awal yang sama. Saya juga terus mencoba menghadapi rasa takut atau gugup tersebut. Bahkan, saya senang dan bersemangat mengikuti kegiatan laboratorium dengan 3 kali menjadi asisten prakitkum dan 3 kali kegiatan magang di laboratorium. Akan tetapi, tidak ada gunanya juga. Masih saja tremor tidak terkontrol. Akibatnya, kegiatan yang dapat saya lakukan sangat terbatas, lalu, gimana saya bisa berkembang?</p> <p><br /></p> <p>Rasa cemas dan gemetar ini juga saya alami ketika berkendara motor. Meskipun saya mampu, saya menghindari menggunakan sepeda motor karena sering hampir mencelakai orang lain akibat gugup. Selain itu, ketika saya melakukan presentasi atau bahkan hanya bermain bersama teman-teman saja saya juga menunjukkan gejala tremor. </p> <p><br /></p> <p>Saya memahami yang saya alami ini bukanlah essential tremor atau tremor akibat penyakit saraf karena ketika dalam keadaan tenang saya tidak gemetar. Namun, ketika dihadapkan dengan faktor-faktor pemicu, seperti adanya individu lain, ekspektasi orang, dan pengalaman, respon ini akan muncul. Ketika terdapat orang lain ketika saya bekerja maka tangan saya akan gemetar. Bahkan, saya juga dapat tremor ketika tidak ada orang di sekitar, tetapi saya diharuskan untuk tidak membuat masalah. </p> <p><br /></p> <p>Hal ini membuat saya kesal, stress, overthinking, dan rendah diri. Saya menjadi sulit untuk memahami materi akademik saya. Saat ini saya kehilangan motivasi untuk melanjutkan studi saya karena rasanya saya tertinggal jauh dari teman-teman saya dan tidak ada yang bisa saya lakukan karena semuanya percuma. </p> <p><br /></p>', '2025-07-21 18:46:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11808, 3098, 102765, 'mahasiswa', 'Vianta Mandhalika', '<p>Saya menjalani pendidikan S3 melalui beasiswa PMDSU. Beasiswa ini mencakup pembiayaan S2 dan S3 dengan skema akselerasi. Dalam 4 tahun kami sudah menyelesaikan kedua jenjang pendidikan tersebut. Namun, dengan kondisi saya harus menjalani pendidikan melalui skema by course juga, rasanya sangat berat untuk dapat mengerjakan sesuatu dengan terburu-buru. Terlebih lagi melihat progres progres sejawat yg lebih dulu dari kita, belum lagi setiap kegiatan yang dadakan. Ada beberapa sejawat yg melampaui batas minimal, justru dia yg dijadikan standar atau dengan kata lain dia lah yg merusak standar awal. Saya masih ada rasa perfeksionis dalam mengerjakan sesuatu, harus saya cek berulang namun hal ini membutuhkan waktu lama.</p> <p>Masalah ini semakin bertambah dengan sifat asli promotor yang semakin terlihat akhir akhir ini. Promotor ini memiliki sifat yang cenderung aneh. Perkataannya selalu berubah ubah dan berorientasi pada uang. Perkataannya pun beberapa kali tidak dapat dipertanggungjawabkan. Dan jika tidak sesuai maunya maka akan terus mencari kesalahan kita. Tidak hanya saya yg bilang tetapi banyak orang yang bilang seperti itu. Saya menyimpan ini sendirian takut untuk menceritakan kepada civitas yg lain. Saya takut jika bercerita berimbas pada studi saya. </p> <p>Akhir akhir ini saya sering kali bermimpi, bangun dalam keadaan ngos ngos an. Kejadian ini berulang setiap hari bahkan pada tidur siang yg hanya sebentar. Saya sulit untuk mengingat sesuatu. Saya merasa seperti demam ketika akan mengerjakan disertasi. Merasa jenuh dengan kegiatan seperti ini. Sudah mencoba refreshing namun saat sedang refreshing pun tetap kepikiran dengan beban. Saya lebih suka menyendiri, saya tidak mau melihat progres teman. </p> <p>Saya ingin apa yang saya rasakan ini dapat terekam dengan baik. Sehingga suatu saat apabila,ada hal yang memang perlu dijelaskan mengenai permasalahan ini, ada yg bisa menceritakan kembali. Dalam diri saya saat ini, hanya ada rasa marah, rasa ingin menangis yang gabisa diungkapkan. Ada rasa ingin memaki atau sekedar menjelaskan secara gamblang kepada promotor kepada orang orang yg mencederai saya. Namun, hal itu tidak bisa dilakukan. </p>', '2025-07-21 21:39:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11809, 3098, 102765, 'mahasiswa', 'Vianta Mandhalika', '<p>Saya meminta maaf jika kata kata saya tidak runtut. Emosi saya saat ini sedang tidak stabil sehingga cukup sulit untuk memanajemen apa yang keluar dari pikiran saya. Bahkan saat mengetik ini pun rasanya sudah ingin berkata "pokoknya begitulah ceritanya". Tetapi, saya paham. Tanpa cerita yang runtut orang lain tidak akan mengerti perasaan saya.</p>', '2025-07-21 21:45:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11810, 3099, 102758, 'mahasiswa', 'Kholiq Aziz', '<p>Mohon maaf kak, apa tidak bisa saya langsung melanjutkan konseling saya dengan konselor saya yang kemarin, karena dengan begini saya hanya terus terusan mengulang cerita di orang yang berbeda. Beberapa waktu yang lalu saya sudah ditangani PPKS, dan saat ini saya ingin melanjutkan dengan konselor saya sebelumnya yang mana sudah memahami kondisi saya tanpa saya harus mengulang cerita yang lalu. Saya bingung kak, saya pikir psikolog yang mendampingi kasus saya akan membersamai saya selama proses berlangsung, namun dari PPKS malah menanyakan apakah saya akan konseling terkait kasus atau hal yang lain, sedangkan yang saya alami saat ini sudah pasti berkaitan dengan kasus yang saya laporkan. Mohon maaf ya ka sekali lagi, saya rasa ini sesuatu yg urgent bagi saya dan saya sangat membutuhkan hal ini sejak 3 minggu lalu namun tidak kunjung mendapatkan jadwal.</p>', '2025-07-21 22:03:29');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11811, 3099, 26, 'admin', 'Nadia Aura', '<p>Baik, terima kasih Kholiq atas penjelasannya. Kami paham apa yang menjadi kekhawatiran Anda saat ini dan mohon maaf apabila dirasa alur melakukan konseling jadi memberatkan Anda. </p> <p>Untuk jadwal konseling lanjutan, kami sudah mendapatkannya yaitu di hari Selasa, 29 Juli pukul 10.30 bersama dengan Bu Yunita. Apakah Anda berkenan melakukan konseling di waktu tersebut?</p> <p>Mohon konfirmasinya ya ^^</p> <p>Terima kasih</p>', '2025-07-22 09:27:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11812, 3098, 26, 'admin', 'Nadia Aura', '<p>Baik, terima kasih Vianta atas ceritanya. Kami apresiasi atas keterbukaan Anda pada kami dan kami apresiasi juga atas perjuangan Anda selama ini. </p> <p>Untuk menanggapi hal ini, kami akan coba bantu jadwalkan konseling bersama dengan psikolog kami. Apakah Anda berkenan melakukan konseling di hari Jumat, 25 Juli pukul 14.00 secara online?</p> <p>Mohon konfirmasinya ya ^^</p> <p>Terima kasih</p>', '2025-07-22 09:35:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11813, 3101, 26, 'admin', 'Nadia Aura', '<p>Selamat pagi, Erich! Terima kasih telah menghubungi layanan konseling UB.</p> <p>Kami apresiasi atas keterbukaan Anda pada kami dan kami apresiasi atas perjuangan Anda selama ini. Kami paham apa yang Anda rasakan saat ini tentu tidak mudah. Untuk itu, kami akan coba jadwalkan Anda untuk melakukan sesi konseling bersama psikolog kami. Sayangnya, jadwal psikolog kami baru tersedia kembali di hari Kamis, 7 Agustus 2025 pukul 09.00, apakah Anda berkenan untuk melakukan konseling di waktu tersebut?</p> <p>Mohon konfirmasinya ya ^^</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-07-22 09:40:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11814, 3098, 102765, 'mahasiswa', 'Vianta Mandhalika', '<p>Saya bisa melakukan konseling pada waktu tersebut, namun apakah bisa konseling dilakukan dengan cara offline?</p>', '2025-07-22 10:21:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11815, 3101, 102253, 'mahasiswa', 'Erich', '<p>selamat siang. Terima kasih atas responnya. Iya, saya bersedia untuk mengikuti kegiatan konseling di jam tersebut. <br /></p>', '2025-07-22 11:08:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11816, 3099, 102758, 'mahasiswa', 'Kholiq Aziz', '<p>Baik ka, apakah untuk jadwal minggu ini tidak ada? Apabila bisa diusahakan minggu ini saya akan bersedia juga, tapi kalau memang adanya tanggal 29 tidak apa apa, semoga seminggu kedepan kondisi saya membaik</p>', '2025-07-22 11:59:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11817, 3099, 26, 'admin', 'Nadia Aura', '<p>Jadwal bu yunita dan psikolog klinis lainnya di minggu ini sudah penuh kak, dan hanya tersisa untuk tanggal 29. Untuk itu, kami jadwalkan di tanggal 29 ya kak. Koordinasi selanjutnya akan kami sampaikan melalui WhatsApp. Terima kasih</p>', '2025-07-22 12:23:13');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11818, 3098, 26, 'admin', 'Nadia Aura', '<p>Mohon maaf kak sebelumnya, untuk di hari Jumat, 25 Juli pukul 14.00 psikolog kami baru saja mengabari bahwa terdapat reschedule di hari yang sama pada pukul 08.00 dan pelaksanaannya tetap online. Namun, jika kakak ingin mengganti jadwal secara offline, kami memiliki opsi di Selasa, 29 Juli 2025 pukul 13.00. Apakah kakak ingin tetap mengambil di hari Jumat atau Selasa ya kak?</p> <p>Mohon konfirmasinya ^^</p> <p>Terima kasih</p>', '2025-07-22 12:32:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11819, 3101, 26, 'admin', 'Nadia Aura', '<p>Baik, terima kasih. Untuk informasi selanjutnya akan kami sampaikan melalui WhastApp. </p>', '2025-07-22 12:36:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11820, 3098, 102765, 'mahasiswa', 'Vianta Mandhalika', '<p>Pada hari Selasa 29 Juli tersebut saya ada agenda keluar kota untuk pengambilan data disertasi. Untuk hari Jumat pagi saya bersedia secara online</p>', '2025-07-22 14:30:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11821, 3102, 102767, 'mahasiswa', 'Rachel', '<p>Baru putus 2 bulan dari pacar, belum bisa terlalu ikhlas tapi udah move on tapi masih banyak gak ikhlasnya terus found out kalau dia ternyata udah punya cewe baru dan ada beberapa kebenaran lainnya yang baru aku tau pas putus, kejadian ini bikin aku kurang produktif dan jadi lemes bahkan sampai bengong terus, pengen aku lupain tapi tetep berpengaruh banget ke keseharian aku yang jadinya sekarang lebih banyak tidur sama ngurung diri, masih sering ketemu temen, tapi habis itu udah rasanya hampa, jadi aku gatau harus gimana biar bener2 bisa lupa dan ikhlas</p>', '2025-07-22 16:38:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11822, 3093, 101183, 'mahasiswa', 'Rima', '<p>Baik tidak apa-apa. Insyaallah saya bisa </p>', '2025-07-22 18:30:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11823, 2949, 102703, 'mahasiswa', 'Feliza Putri', '<p>sebelumnya mohon maaf kak baru membalas dan membuka, kira" di jadwal kan kapan kak</p>', '2025-07-22 18:49:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11824, 3103, 102474, 'mahasiswa', 'Nazwa Ichsan', '<p>Saya sedang melaksanaan MMD di Desa Pandansari, Kab. Malang. Semalam ketika saya diajak briefing, saya izin untuk tidak mengikuti karena sedang mengedit video untuk video profil UMKM yang rencana seharusnya deadline nya hari Rabu, 23 Juli 2025. Saya juga sudah bilang bahwa saya nantinya akan ikut keputusan bersama. Namun, saya mendengar teman saya merundung saya seolah memaksa dan berkata bahwa "Orang cuma briefing bentar doang masa ikut bentar aja gabisa" (dengan nada kesal) lalu ada juga yang berkata "Nanti giliran keputusannya apa gabisa ngikut huuuu"  Saya capek sekali selalu membatin dengan teman² kelompok MMD saya. Karena saya terlalu banyak memendam sendirian, akhirnya emosi saya meluap tadi malam, awalnya tangan saya gemetar lalu saya mengalami kejang.</p>', '2025-07-23 06:21:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11825, 2949, 26, 'admin', 'Nadia Aura', '<p>Selamat pagi, Feliza! </p> <p>Untuk konseling berikutnya bersama Bu Bona (psikolog yang sama seperti sebelumnya) di bulan ini sudah penuh dan baru tersedia kembali di tanggal 14 Agustus. Jika Anda berkenan, kami dapat menjadwalkan bersama dengan psikolog lain di waktu yang lebih dekat yaitu pada tanggal 7 Agustus pukul 11.00. Jadi, Anda berkenan untuk melakukan konseling bersama Bu Bona atau dengan psikolog lain?</p> <p>Mohon konfirmasinya ya ^^</p> <p>Terima kasih</p>', '2025-07-23 09:36:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11826, 3093, 26, 'admin', 'Nadia Aura', '<p>Selamat pagi, kak Rima! Mohon maaf sekali lagi harus saya sampaikan bahwa Bu Yunita ternyata sudah diisi klien lain lagi di tanggal 5 Agustus nanti, sehingga baru tersedia kembali di tanggal 12 Agustus pukul 10.30, apakah berkenan? </p> <p>Mohon maaf sebesar-besarnya ya kak karena saat ini sedang pelaksanaan KKN, sehingga beberapa klien harus ditangani langsung dan klien lain jadwalnya menjadi mundur. </p>', '2025-07-23 09:41:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11827, 3098, 26, 'admin', 'Nadia Aura', '<p>Baik kak, kami jadwalkan di hari Jumat, 25 Juli pukul 08.00 secara online ya. Informasi selanjutnya akan kami sampaikan melalui WhatsApp. Terima kasih</p>', '2025-07-23 09:47:20');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11828, 3102, 26, 'admin', 'Nadia Aura', '<p>Selamat pagi, Rachel! Terima kasih telah menghubungi layanan konseling UB. </p> <p>Kami apresiasi atas keterbukaan Anda kepada kami dan kami apresiasi juga atas kemauan Anda untuk tetap bertahan dengan baik selama 2 bulan ini. Kami paham apa yang Anda alami dan rasakan saat ini tentu tidak mudah. Pasti membutuhkan waktu untuk benar-benar pulih dari kondisi ini. Sebelum itu, bisakah Anda jawab pertanyaan kami berikut.</p> <p>1. Sudah berapa lama Anda menjalin hubungan dengan mantan Anda tersebut?</p> <p>2. Adakah kegiatan yang bisa membuat Anda melupakan kesedihan/perasaan tidak ikhlas Anda ini? Misal mengerjakan tugas, main bersama teman, dsb.</p> <p>3. Jika sedang berada dalam situasi hampa, apa yang biasa Anda lakukan?</p> <p>4. Bagaimana Anda menjalani kegiatan sehari-hari selama 2 bulan ini?</p> <p>Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya.</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB. <br /></p>', '2025-07-23 09:57:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11829, 3103, 26, 'admin', 'Nadia Aura', '<p>Selamat pagi, Nazwa! Terima kasih telah menghubungi layanan konseling UB.</p> <p>Kami apresiasi atas keterbukaan Anda kepada kami. Kami paham apa yang Anda rasakan saat ini tentu tidak mudah. Maka dari itu, kami akan bantu untuk menjadwalkan konseling bersama konselor kami di waktu terdekat. Untuk itu, apakah Anda bersedia melakukan konseling secara online di hari Selasa, 29 Juli pukul 19.00?</p> <p>Mohon konfirmasinya ya ^^</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-07-23 10:07:28');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11830, 3103, 102474, 'mahasiswa', 'Nazwa Ichsan', '<p><span><span>Saya bersedia, namun sepertinya untuk tanggal 29 saya bisanya jam siang karena kelompok MMD saya mau mengadakan lokakarya di sore hingga malam</span></span></p>', '2025-07-23 12:31:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11831, 3103, 26, 'admin', 'Nadia Aura', '<p>Baik, untuk itu kami jadwalkan bersama dengan psikolog kami di jam 13.00 ya kak. Apakah berkenan?</p>', '2025-07-23 12:58:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11832, 3096, 100665, 'mahasiswa', 'Aulia Widodo', '<p>Mohon maaf baru merespon dikarenakan tidak ada notifikasi email masuk. Saya pilih di hari Jumat 25 Juli 2025 pukul 14.00 (online), ya bu. Terimakasih sebelumya</p>', '2025-07-23 15:37:28');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11833, 3103, 102474, 'mahasiswa', 'Nazwa Ichsan', '<p>boleh, jam 1 siang saja</p>', '2025-07-23 15:57:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11834, 3104, 102343, 'mahasiswa', 'Cahaya Ningsih', '<p>Akibat berbagai masalah dalam menjalani hubungan pacaran 4 tahun, saya merasa kesehatan mental memburuk, melakukan self-harm dan belum dapat berdamai dengan apa yang telah terjadi. Juga mengalami berbagai jenis kekerasan.</p>', '2025-07-23 19:19:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11835, 3096, 100665, 'mahasiswa', 'Aulia Widodo', '<p>Selamat siang, Bu. Mohon maaf izin bertanya, apakah jadwal konseling hari ini jam 2 jadi dilaksanakan, nggih? Terimakasih</p>', '2025-07-25 12:29:48');
