INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11867, 3113, 102386, 'mahasiswa', 'Annisa Idris', '<p>Mahasiswa tingkat akhir yang sedang mengalami fase demotivasi untuk menyelesaikan skripsi. Saya merasa kehilangan diri saya sendiri, disaat teman-teman saya sudah jauh berjalan sedangkan saya masih stuck di sini. Hal tersebut juga berdampak terhadap produktivitas saya, yang mana berpengaruh terhadap progress skripsi saya sehingga "nambah semester" lagi</p>', '2025-07-28 10:58:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11868, 3104, 27, 'admin', 'Shafhah Raisha', '<p>Mohon maaf sebelumnya dikarenakan jadwal konseling di tanggal 12 Agustus sudah tidak tersedia. Apakah Anda berkenan jika konseling dilakukan di hari Kamis, 14 Agustus pukul 09.00 WIB secara offline? </p>', '2025-07-28 11:24:30');
