INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11879, 3111, 102770, 'mahasiswa', 'Erlinda', '<p>Selamat malam kak Shafhah, mohon maaf izin konfirmasi lagi yang benar Selasa, 5 Agustus kah? Atau Rabu, 6 Agustus ya, Kak? Karena pada saat saya cek 6 Agustus adalah hari Rabu. Terima kasih, Kak.</p>', '2025-07-29 03:14:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11880, 3113, 27, 'admin', 'Shafhah Raisha', '<p>Untuk informasi selanjutnya akan kami sampaikan melalui WhatsApp ya, Kak :)</p>', '2025-07-29 08:13:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11881, 3111, 27, 'admin', 'Shafhah Raisha', '<p>Eh, iya. Mohon maaf atas kekeliruannya. Maksudnya hari Rabu tanggal 6 Agustus yaa, Kak :)</p>', '2025-07-29 11:10:04');
