INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11956, 3129, 102784, 'mahasiswa', 'Daffa Fauzi', '<p>untuk pertanyaan pertama, yang saya butuhkan saat ini adalah saya ingin segera selesai sidang akhir skripsi saya agar saya bisa segera pulang untuk mengurus permasalahan hutang keluarga saya dan saya membutuhkan keringanan UKT selain yang penurunan 50% karena kondisi finansial saya yang tidak memungkinkan untuk membayar UKT tersebut.</p> <p>untuk pertanyaan kedua, saya sudah mengajukan keringanan UKT sebelumnya melalui SIBAKU yang terkait penurunan 50% tetapi setelah saya mengajukan keringanan tersebut saya baru dapat kabar bahwa orang tua saya sedang terjerat permasalahan hutang sehingga keberatan dalam membayar UKT meskipun sudah turun sebesar 50%. </p> <p>untuk pertanyaan ketiga, harapan saya adalah bisa membantu dalam mengurus pengurangan UKT agar saya dapat mampu melanjutkan skripsi saya yang tahapan saat ini yaitu sidang akhir sehingga saya bisa segera lulus kuliah dan segera membantu orang tua saya untuk menyelesaikan permasalahan tersebut. terima kasih atas perhatiannya</p>', '2025-08-04 11:22:06');
