INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11968, 3124, 28, 'admin', 'Ishida Ayumi', '<p>Terima kasih atas respon yang diberikan. Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan konselor profesional kami? Namun karena jadwal di minggu ini sudah penuh, jadwal dengan konselor profesional kami baru tersedia di minggu depan. Berikut opsi jadwal yang dapat Anda pilih:</p> <p dir="ltr">- Selasa, 12 Agustus 2025 pukul 19.00 (daring)</p> <p dir="ltr">- Kamis, 14 Agustus 2025 pukul 13.30 (daring/luring)<br /></p> <p dir="ltr">Atau jika menurut Anda terlalu lama, bisa kami jadwalkan konseling dengan peer counselor kami, jika Anda bersedia melakukan konseling dengan peer counselor kami, berikan kami 2 opsi jadwal antara senin-jumat pukul 08.00-15.00.</p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-08-05 11:37:24');
