INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11970, 3126, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf di tanggal 15 jadwal konseling sudah penuh kak Untuk konseling offline terdekat dengan psikolog kami baru tersedia di tanggal 18 keatas</p>', '2025-08-05 11:41:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11971, 3124, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasi kesediaannya. Untuk informasi selanjutnya akan kami hubungi melalui WA.</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2025-08-05 11:43:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11972, 3132, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat siang, Zlatan!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:<br /></p> <p dir="ltr">1. Bagaimana frekuensi kemunculan pikiran-pikiran negatif Anda? </p> <p dir="ltr">2. Dari pikiran-pikiran negatif yang muncul, apa efeknya ke kegiatan keseharian atau interaksi sosial Anda? </p> <p dir="ltr">3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr">Dan untuk mendiskusikan lebih lanjut hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun jadwal di minggu ini dan minggu depan sudah penuh, jadwal dengan psikolog kami baru tersedia:</p> <p dir="ltr">- Rabu, 20 Agustus 2025 pukul 12.30 (daring/luring)</p> <p dir="ltr">- Jumat, 22 Agustus 2025 pukul 12.30 (daring/luring)</p> <p dir="ltr">Jika Anda merasa jadwal tersebut terlalu lama, kami juga bisa menjadwalkan konseling dengan peer counselor kami yang memiliki jadwal lebih fleksibel. Jika Anda bersedia untuk melakukan konseling dengan peer counselor kami, beri kami 2 opsi jadwal antara senin-jumat pukul 08.00-15.00. <br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-08-05 12:00:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11973, 3133, 102775, 'mahasiswa', 'Firla', '<p dir="ltr">yg saya rasakan:</p> <p dir="ltr">- kata2 dr ibu saya cukup negatif, atau kadang positif tapi bernada "sedih" seperti paling tersakiti</p> <p dir="ltr">- ga bisa berempati kpd ortu karena merasa tersakiti lewat bbrp hal (tidak mendengarkan saat sedang cerita, tidak pernah divalidasi saat merasa kesusahan, merasa mereka yg paling berat hidupnya, ortu selingkuh) </p> <p dir="ltr">- mungkin hidup mereka memang berat, tapi apakah harus mengecilkan masalah2 lain yg saya hadapi?</p> <p dir="ltr">- "baru kuliah aja udh stres2, gimana nanti ngadepin kehidupan yg beneran (kerja/berkeluarga), bisa bunuh diri kali kamu" kata ibu saya</p> <p dir="ltr">- ga dihargai apa yang udah saya coba dilakukan tapi selalu menuntut lebih (menurun ke saya menjadi orang yang seperti itu juga kepada pasangan saya)</p> <p dir="ltr">- ortu ga memberikan perhatian secara emosi selama dari kecil hingga skrg (memang sibuk kerja), saya ga minta itu untuk dipenuhi, cukup hargai saya dengan usaha saya survive dari masalah2 saya sendiri</p> <p dir="ltr">- sedikit interaksi di rumah (kebanyakan hanya untuk marah2 &amp; menuntut) -&gt; saya ga bisa belajar menghadapi mereka seperti yg mereka mau, sampe skrg masih meraba dan masih sering salah menurut mereka), saya juga jadi minim belajar berempati kpd org, sering bingung menghadapi kehidupan bersosial</p> <p dir="ltr">- karena ga merasa nyaman ataupun aman di rumah (tidak ada org lain selain ortu di rumah) selalu mencari hal tsb di luar (orang lain, misal pacar), jadi punya ekspektasi yg terlalu tinggi ke orang lain, ketergantungan dgn keberadaan org lain, kurang nyaman dengan diri sendiri</p> <p dir="ltr">- tambahan lain: selalu diselingkuhi saat punya pacar -&gt; insecure, trust issue</p> <p dir="ltr">- beberapa bulan terakhir merasa pilihan yg lebih baik adalah saat saya tidak menghadapi &amp; memproses emosi saya</p> <p dir="ltr">- saat saya jauh dari ortu dan minim komunikasi, saya merasa lebih baik dan tidak terbebani bahwa akan dimarahi ortu, saya bisa lebih tenang saat menjalani hidup saya</p> <p dir="ltr">yg ingin saya perbaiki:</p> <p dir="ltr">- ingin lebih nyaman dengan diri sendiri, merasa aman dan nyaman dengan diri sendiri, lebih kuat saat menghadapi masalah (baik dari ortu atau kehidupan sendiri spt kuliah/teman/pacar/kerja), tidak ketergantungan dengan org lain</p> <p dir="ltr">- tidak melimpahkan tanggung jawab kepada orang lain untuk menghadapi emosi saya yang tidak terproses dengan baik (output marah2, menuntut, dll)</p> <p dir="ltr">- lebih bisa menerima perlakuan orang tua sehingga tidak terus menerus membenci ortu dan bisa lebih berdamai dengan masalah2 yg di luar kendali saya</p>', '2025-08-05 16:18:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11974, 3134, 102789, 'mahasiswa', 'Ervika Ardhiansyah', '<p>orang tua terlalu strict akan agama dan sempat menganut ajaran yang sesat. keterikatan akan agama dan takut akan neraka mendorong anak²nya untuk di brainwash dan wajib belajar tentang agama dan kehidupan hanya melalui orangtua dan tidak diperkenankan untuk belajar dari orang lain. masalah makin complicated ketika anak²nya mulai ingin memutuskan jalannya sendiri, makin muncul banyak kekangan dan ancaman yang membuat hubungan keluarga jadi tidak harmonis.</p>', '2025-08-05 16:26:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11975, 2949, 102703, 'mahasiswa', 'Feliza Putri', '<p>baik kak apakah di laksankn secara offline?</p> <p><br /></p>', '2025-08-05 17:22:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11976, 3135, 102790, 'mahasiswa', 'Ardi Setiawan', '<p>Permasalahan mengenai masalah relasi perkuliahan hingga keluarga dan pasangan, mengenai isu kesehatan mental saya yang mengindikasikan pengakhiran hidup, hingga kuliah saya terganggu.</p>', '2025-08-05 17:24:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11977, 3136, 101582, 'mahasiswa', 'Nepta Rahma', '<p>‎Assalamualaikum, saya mahasiswi angkatan 2020, saya tidak tahu harus menghubungi siapa saat ini. Saya adalah orang yang gagal berulang kali. Tapi saya masih bertekad untuk menyelesaikan kuliah ini setipis apapun kesempatan yang masih saya miliki. Saya tidak tahu ada apa dengan diri saya, hingga menjadi seperti ini. Keluarga saya miskin, ibu saya menanggung semua biaya hidup saya dari kecil karena ayah saya adalah org dengan gangguan jiwa yang kabur ke luar kota sejak saya umur 3 bulan dan tidak bertemu. Saya kehilangan ayah saya setahun sebelum masuk kuliah (2019) tanpa pernah bertemu, padahal beliau adalah mimpi saya jika sudah dewasa ingin mencarinya dan ingin menjadi orang sukses untuk merawat &amp; mengobatinya. Saya hancur ketika ayah saya pergi, saya belum sempat melakukan apa-apa untuknya. Tetapi saya masih harus tetap hidup, untuk ibu saya. Saya memaksakan diri untuk berkuliah, dengan beasiswa. Meskipun ibu saya melarang karena kami tidak memiliki uang untuk biaya kuliah saya. Tetapi saat kuliah, saya gagal, saya terus terbayang ayah saya, kehilangan tujuan, itu sangat mengganggu pikiran saya, berkali-kali saya mencoba memperbaiki keadaan tetapi malah semakin kacau. Hingga waktu beasiswa saya habis di semester 8, ibu saya tidak memiliki uang untuk melanjutkan kuliah, tetapi saya tetap memaksakan diri, saya berhutang untuk membayar kuliah, dan bekerja untuk menyicil hutang itu &amp; untuk hidup. Tetapi saya terlalu lelah untuk tetap menjalani kuliah seperti teman teman yang lain, waktu saya habis untuk membayar cicilan dan mencari uang untuk hidup, saya gagal menyelesaikan semester kuliah. Semester 9 saya gagal, semester 10 saya mencoba keras untuk memperbaiki kembali, tetapi saya sangat malu, takut, saya datang ke kampus tetapi tidak berani masuk ke kelas karena takut. Saat ini saya benar benar butuh arah, ibu saya sudah sangat kecewa dan menyesal mengirim saya ke sini. Tetapi saya tidak ingin pulang tanpa ijazah saya, saya tidak ingin pulang dengan kegagalan. Beberapa kali sempat berpikir untuk menghilang dari bumi, tetapi saya tidak bisa meninggalkan ibu saya setelah perjuangannya membesarkan dan merawat saya. Saya ingin tetap hidup dan melanjutkan semua ini hingga akhir. Saya benar-benar butuh arah terutama tentang finansial, bagaimana saya harus mengatur keuangan agar cukup untuk kuliah sampai akhir, karena saya mencari uang sendiri, kemudian tentang pendidikan saya, apa yang harus saya lakukan saat ini, mata kuliah apa, dan bagaimana caranya agar saya bisa menyelesaikan kuliah ini dengan cepat, dan tentang pengendalian diri, saya tidak tahu bagaimana harus menghadapi dunia, bagaimana agar saya tetap yakin untuk melewati semuanya, karena saya benar-benar sendiri. Ibu saya sudah melepas saya dari setahun yang lalu karena saya gagal menyelesaikan kuliah 4 tahun, saya tidak punya teman, bahkan untuk mengobrol ataupun bercerita. Saya takut mencapai batas keyakinan saya dan mengakhiri dengan tidak seharusnya. Saya butuh bantuan, tetapi tidak tahu harus meminta bantuan kepada siapa </p>', '2025-08-05 18:46:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11978, 3137, 102791, 'mahasiswa', 'Nuha', '<p>akhir-akhir ini saya ngerasa ga jadi diri saya sendiri, ga hidup buat saya, lupa esensi hidup buat apa selain bertahan buat orang tua, keluarga dan orang-orang yang saya sayangi. saya seringkali overwhelmed dengan keadaan, dan bingung harus mulai darimana. lalu juga ketika saya lagi menghadapi masalah, tiba-tiba sisa post trauma selalu datang. sebelumnya, saya korban bullying di SMA, saya di gaslighting oleh salah satu teman saya yang memiliki jabatan tinggi dan pandai mengendalikan orang lain. mungkin kurang lebih untuk saat ini itu saja, mohon bantuannya, terimakasih.</p>', '2025-08-05 21:01:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11979, 3133, 28, 'admin', 'Ishida Ayumi', '<p>Selamat malam, Firla!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal minggu ini sudah penuh, jadwal dengan psikolog kami baru tersedia pada hari:</p> <p dir="ltr">- Kamis, 14 Agustus 2025 pukul 13.30 (daring/luring)</p> <p dir="ltr">- Rabu, 20 Juni 2025 pukul 12.30 (daring/luring)<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-08-05 21:50:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11980, 3134, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat malam, Ervika!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Menurut Anda, apa yang Anda butuhkan saat ini?<br /></p> <p dir="ltr">2. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">3. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr">Dan untuk mendiskusikan lebih lanjut hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal di minggu ini sudah penuh, jadwal dengan psikolog kami baru tersedia di minggu depan. Berikut opsi jadwal yang dapat Anda pilih:</p> <p dir="ltr">- Kamis, 14 Agustus 2025 pukul 13.30 (daring/luring)</p> <p dir="ltr">- Rabu, 20 Juni 2025 pukul 12.30 (daring/luring)</p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /></p> <p><br /></p>', '2025-08-05 21:56:01');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11981, 3135, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat malam, Ardi!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih mengenai permasalahan yang sedang Anda alami? <br /></p> <p dir="ltr">2. Menurut Anda, apa yang anda butuhkan saat ini?</p> <p dir="ltr">3. Apakah sebelumnya Anda pernah mengunjungi atau didiagnosis oleh tenaga profesional perihal kesehatan mental Anda? </p> <p dir="ltr">4. Apakah pemikiran negatif dan keinginan untuk melakukan tindakan merugikan diri Anda sudah berlangsung lama? Dan apakah pemikiran tersebut sering muncul?</p> <p dir="ltr">5. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi permasalahan yang sedang Anda hadapi?</p> <p dir="ltr">6. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.<br /></p> <p dir="ltr"><br /></p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-08-05 22:04:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11982, 3137, 28, 'admin', 'Ishida Ayumi', '<p>Selamat malam, Nuha!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal di minggu ini sudah penuh, jadwal dengan psikolog kami baru tersedia di minggu depan. Berikut opsi jadwal yang dapat Anda pilih:</p> <p dir="ltr">- Rabu, 18 Juni 2025 pukul 10.30 (daring/luring)</p> <p dir="ltr">- Kamis, 19 Juni 2025 pukul 11.00 (daring/luring)</p> <p dir="ltr">Jika waktu tersebut terlalu lama, kami juga bisa menjadwalkan Anda dengan peer counselor kami yang memiliki jadwal lebih fleksibel. Jika Anda bersedia melakukan konseling dengan peer counselor kami, beri kami 2 opsi jadwal antara hari senin-jumat pukul 08.00-15.00.<br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-08-05 22:07:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11984, 3136, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat malam, Nepta Rahma!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Terima kasih karena telah bekerja keras dan bertahan hingga saat ini, pastilah butuh usaha yang besar baik secara fisik maupun mental. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal minggu ini sudah penuh, jadwal dengan psikolog kami baru tersedia pada hari:</p> <p dir="ltr">- Kamis, 14 Agustus 2025 pukul 13.30 (daring/luring)</p> <p dir="ltr">- Rabu, 20 Juni 2025 pukul 12.30 (daring/luring)</p> <p dir="ltr">Jika waktu tersebut terlalu lama, kami juga bisa menjadwalkan Anda dengan peer counselor kami yang memiliki jadwal lebih fleksibel. Jika Anda bersedia melakukan konseling dengan peer counselor kami, beri kami 2 opsi jadwal antara hari senin-jumat pukul 08.00-15.00.<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-08-05 22:13:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11985, 3138, 102013, 'mahasiswa', 'Raqayya', '<p>Saya mahasiswa yang diambang kebingungan, selepas ayah saya meninggal seperti kehilangan arah</p>', '2025-08-06 04:50:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11986, 3139, 100750, 'mahasiswa', 'Dyaning Widyatna', '<p>Permisi kak/bu/pak, saya kemarin kan baru dapat surat peringatan untuk mengundurkan diri karena masalah sks yang belum tuntas karena saya dapat D dan E di smester sebelumnya karena lingkungan studi yang mencekam karena saya mengulang dan karena saya sangat amat susah dalam menghafal. Saya tidsk bisa menghafalkan kanji dan beberapa tata bahasa lainnya yang berdampak ke UTS UAS ataupun quiz yang mengakibatkan saya tidsk bisa memahami soal karena tidak bisa membaca secara jelas dan saya menjawab apa yg saya bisa. Dan kemarin saya dpt keringanan, untuk bisa mengulang dengan adik kelas yg agak bawah lagi, tetapi jika saya mendapatkan D dan E dalam semester ini dan kedepannya saya akan langsung mengundurkan diri. Saya tadi pagi setelah bangun tdr nangis se jadi jadinya karena kepikiran, gimana kalau saya dpt nilai D walaupun saya udh berusaha mati matian. Saya bingung bagaimana mengubah gaya belajar atau mengubah apapun yg bisa membuat saya mahir dalam hafalan, dan memahami suatu bacaan. Saya sering selfharm dengan menyayat pergelangan disaat saya stres dan suka memukul tembok karena geram kenapa saya tdk bisa menghafal dan memahami semuanya. Saya bingung, saya takut kedepannya walaupun saya udh berusaha sekuat tenaga tapi tetep menghasilkan D :)</p>', '2025-08-06 05:05:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11987, 3139, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat pagi,Dyaning!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal minggu ini sudah penuh dan jadwal di minggu depannya hanya tersisa 1 jadwal dengan psikolog, berikut jadwal konseling yang dapat Anda pilih:</p> <p dir="ltr">- Kamis, 14 Agustus 2025 pukul 13.30 (daring/luring)</p> <p dir="ltr">- Selasa, 19 Agustus 2025 pukul 13.00 (daring/luring)</p> <p dir="ltr">- Rabu, 20 Agustus 2025 pukul 12.30 (daring/luring)</p> <p dir="ltr">Jika waktu tersebut terlalu lama, kami juga bisa menjadwalkan Anda dengan peer counselor kami yang memiliki jadwal lebih fleksibel. Jika Anda bersedia melakukan konseling dengan peer counselor kami, beri kami 2 opsi jadwal antara hari senin-jumat pukul 08.00-15.00.<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-08-06 09:30:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11988, 3136, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat malam, Nepta Rahma!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Terima kasih karena telah bekerja keras dan bertahan hingga saat ini, pastilah butuh usaha yang besar baik secara fisik maupun mental. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal minggu ini sudah penuh, jadwal dengan psikolog kami baru tersedia pada hari:</p> <p dir="ltr">- Kamis, 14 Agustus 2025 pukul 13.30 (daring/luring)</p> <p dir="ltr">- Rabu, 20 Agustus 2025 pukul 12.30 (daring/luring)</p> <p dir="ltr">Jika waktu tersebut terlalu lama, kami juga bisa menjadwalkan Anda dengan peer counselor kami yang memiliki jadwal lebih fleksibel. Jika Anda bersedia melakukan konseling dengan peer counselor kami, beri kami 2 opsi jadwal antara hari senin-jumat pukul 08.00-15.00.<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-08-05 22:13:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11989, 3137, 28, 'admin', 'Ishida Ayumi', '<p>Selamat malam, Nuha!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal di minggu ini sudah penuh, jadwal dengan psikolog kami baru tersedia di minggu depan. Berikut opsi jadwal yang dapat Anda pilih:</p> <p dir="ltr">- Kamis, 14 Agustus 2025 pukul 13.30 (daring/luring)</p> <p dir="ltr">- Rabu, 20 Agustus 2025 pukul 12.30 (daring/luring)</p> <p dir="ltr">Jika waktu tersebut terlalu lama, kami juga bisa menjadwalkan Anda dengan peer counselor kami yang memiliki jadwal lebih fleksibel. Jika Anda bersedia melakukan konseling dengan peer counselor kami, beri kami 2 opsi jadwal antara hari senin-jumat pukul 08.00-15.00.<br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-08-05 22:07:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (11990, 3134, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat malam, Ervika!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Menurut Anda, apa yang Anda butuhkan saat ini?<br /></p> <p dir="ltr">2. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">3. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr">Dan untuk mendiskusikan lebih lanjut hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal di minggu ini sudah penuh, jadwal dengan psikolog kami baru tersedia di minggu depan. Berikut opsi jadwal yang dapat Anda pilih:</p> <p dir="ltr">- Kamis, 14 Agustus 2025 pukul 13.30 (daring/luring)</p> <p dir="ltr">- Rabu, 20 Agustus 2025 pukul 12.30 (daring/luring)</p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /></p> <p><br /></p>', '2025-08-05 21:56:01');
