INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12003, 3140, 28, 'admin', 'Ishida Ayumi', '<p>Selamat malam, Megi Saputro. Mengenai permasalahan yang ingin didiskusikan apakah sama dengan permasalahan sebelumnya? Dan apakah Anda ingin melakukan konseling lanjutan dengan Bu Ulifa? Atau Anda ingin mencoba konseling dengan psikolog lain? </p> <p dir="ltr">Untuk memperdalam pemahaman kami terhadap cerita Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Menurut Anda apa yang Anda butuhkan saat ini?</p> <p dir="ltr">2. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.<br /><br /></p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /><br /></p>', '2025-08-06 18:52:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12004, 3138, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Kami konfirmasikan kepada peer kami terlebih dahulu ya kak. Apakah Anda bisa memberikan kami opsi lain selain besok pada pukul 1?</p>', '2025-08-06 19:10:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12005, 3141, 28, 'admin', 'Ishida Ayumi', '<p>Selamat malam, Susilo!</p> <p>Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog klinis kami? Namun mohon maaf untuk jadwal di minggu ini dan minggu depan sudah penuh, baru tersedia pada hari Jumat, 22 Agustus 2025 pukul 12.30. Apakah Anda berkenan untuk menunggu?</p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /><br /></p>', '2025-08-06 19:15:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12006, 3133, 102775, 'mahasiswa', 'Firla', '<p>Terima kasih, saya bersedia pada hari kamis, 14 agustus 2025 pukul 13.30 secara luring. Untuk informasi tempatnya di mana ya? Terima kasih sebelumnya</p>', '2025-08-06 19:17:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12007, 3133, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Untuk tempatnya di rektorat ya kak, untuk detail tempatnya akan kami informasikan melalui WA. Terima kasih.</p>', '2025-08-06 19:20:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12008, 3142, 101058, 'mahasiswa', 'Hanifah Mumtazah', '<p>Saat ini saya memasuki semester 7. Saya memilih untuk mendaftar program magang skema B sebagai asisten peneliti. Saya mulai mencicil dari bulan juli namun belum ada progresan yg berarti. Selama libur di rumah, saya merasa belum bisa fokus untuk mengerjakannya, saya sempat menjaga adik2 saya selama 1 minggu selama ummi saya mengunjungi nenek saya. Awalnya saya tidak keberatan dan merasa inilah saat yg tepat untuk ummi saya bisa pergi ke luar kota tanpa membawa adik saya. selama liburan ini saya belajar menjadi kakak yg baik dengan menjalani beberapa pelajaran parenting yg pernah saya pelajari. Namun, selama mengimplementasikannya saya menyadari bahwa ada sebagian hal yg ga saya dapatkan dalam pengasuhan orang tua saya selama ini. perlahan2 luka itu saya sadari, bahkan dari tindakan2 kecil, ucapan, dll. Saya terkadang lebih emosional selama di rumah dan berakhir menyesal karena telah menaikkan intonasi suara di depan orang tua saya. Tapi terkadang saya tidak bisa mengontrolnya. Kemudian saya sempat takut berkonsultasi dengan dosbing saya. karena sudah 3 pekan belum konsultasi sama sekali. sebenernya ada maslaah lain yg mengganjal dan membuat saya ovt akhir2 ini. yaitu masalah saya dengan salah satu BPH controling saya di organisasi. sebenarnya masalah kecil, tapi dia silent treatment dan dar sikapnya akhir2 ini saya merasa tidak dihargai, terlebih sebelumnya dia mengatakan kepada saya untuk tidak terlalu banyak ikut campur dalam departemennya. Dan puncak masalahnya malam ini. saat BPH lainnya protes dengan kinerja mereka selama menjalani salah satu proker yg dimana berhubungan dengan departemen lainnya. Dalam hati kecil saya, saya menyalahkan diri saya sendiri karena memilih tetap diam dan tidak menanyakan progresan kepada mereka ditengah masalah internal saya dengan salah satu BPH tersebut. Saya merasa tidak profesional kali ini. Saya bingung harus fokus mengerjakan apa, 1 pekan ini setelah menyelesaikan berkas pendaftaran magang dan pengajuan topik skripsi, saya mengerjakan beberapa keprluan LPJTT dan belum berprogres lagi untuk skripsi saya. saya merasa takut tidak bisa menyelesaikannya. dosbing saya menargetkan awal semester ini anak bimbingannya sudah selesai skripsi semuanya.</p>', '2025-08-06 23:49:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12009, 3143, 102793, 'mahasiswa', 'Ahmad', '<p>saya mudah merasa sedih dan tersinggung dengan perkataan orang dan juga takut jika mendengar hal yang tidak sesuai dengan ekspektasi saya, saya juga mudah merasa lelah, akhir akhir ini saya sering tidur sangat lama, bahkan bisa sampai 12 jam, jika saya cemas saya merasakan hawa dingin/kedinginan yang padahal suhu di sekitar saya tidak sedingin itu, saya juga merasakan gemetar ketika cemas. akhir akhir ini juga detak jantung saya sering berdetak sangat kencang. </p>', '2025-08-07 00:44:01');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12010, 3138, 102013, 'mahasiswa', 'Raqayya', '<p>jumat juga tidak apa-apa, dengan jam yang sama</p>', '2025-08-07 02:42:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12011, 3134, 102789, 'mahasiswa', 'Ervika Ardhiansyah', '<p>1. Saya butuh jawaban tentang apa yang terdampak pada saya, apa yang harus saya lakukan, dan langkah apa yang selanjutnya bisa saya ambil</p> <p>2. saya pernah mencoba untuk mendatangi poli jiwa di rumah sakit, namun orangtua melarang dan mengatakan tidak perlu konseling karena hanya perlu beribadah</p> <p>3. saya bisa mendapat jawaban tentang post trauma, apa yang berdampak kepada saya, harus bersikap bagaimana selanjutnya dalam menghadapi keluarga, dan bisa selesai dengan konflik pada diri sendiri.</p> <p>saya memilih untuk konseling di hari Kamis, 14 Agustus 2025 secara luring.</p> <p>Terima kasih.</p>', '2025-08-07 06:42:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12012, 3140, 102255, 'mahasiswa', 'Megi Saputro', '<p>Izin untuk menjawab bahwa saya bersedia untuk melakukan konsultasi lanjutan dengan Bu Ulifa.</p> <p>Izin untuk menjawab beberapa pertanyaan yang ada sebagai berikut: </p> <p>1. Pekerjaan</p> <p>2. Memperoleh saran yang tepat untuk menyelesaikan masalah hidup utama saya</p> <p>Terimakasih.</p>', '2025-08-07 07:29:51');
