INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12055, 3147, 26, 'admin', 'Nadia Aura', '<p>Baik, terima kasih atas konfirmasinya. Untuk itu, apakah bersedia jika dilakukan sesi konseling di hari Jumat, 22 Agustus pukul 09.00 secara offline?</p>', '2025-08-09 09:28:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12056, 3150, 26, 'admin', 'Nadia Aura', '<p>Baik, terima kasih atas konfirmasinya. Untuk alternatif lain kami bisa menyesuaikan dengan jadwal Anda tetapi pelaksanaan konseling bersama dengan peer counselor, apakah berkenan?</p>', '2025-08-09 09:30:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12057, 3151, 26, 'admin', 'Nadia Aura', '<p>Selamat pagi, Amellia! Terima kasih telah menghubungi layanan konseling UB.</p> <p>Kami paham apa yang Anda rasakan saat ini tentu tidak mudah. Kami apresiasi atas keterbukaan Anda pada kami. Untuk mengatasi hal ini, apakah Anda berkenan kami jadwalkan sesi konseling bersama dengan peer counselor? Apabila berkenan mohon berikan kami preferensi waktunya ya (silahkan tulis hari dan jamnya).</p> <p>Terima kasih,</p> <p>Salam hangat, </p> <p>Tim Konseling UB.</p>', '2025-08-09 09:34:35');
