INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12059, 3149, 26, 'admin', 'Nadia Aura', '<p>Baik, terima kasih atas jawabannya. Kami paham apa yang Anda lalui saat ini tentu tidak mudah, untuk itu kami akan bantu jadwalkan sesi konseling Anda bersama peer counselor kami. Silahkan untuk memberikan preferensi waktunya ya (sebutkan hari, tanggal dan jam).</p>', '2025-08-09 09:47:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12060, 3151, 102799, 'mahasiswa', 'Amellia Madani', '<p> senin 11 agustu di jam 10-15 saya kosong pak/bu</p>', '2025-08-09 10:34:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12061, 3150, 101927, 'mahasiswa', 'Farhan Rosyadi', '<p>Apa bisa jelaskan lebih lanjut lagi menganai peer counselor? Apa bedanya dengan counselor yang umumnya?</p>', '2025-08-09 12:19:00');
