INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12155, 3171, 29, 'admin', 'Aisyah Salsa', '<p>Mohon maaf terjadi perubahan jadwal oleh psikolog kami, sehingga jadwal yang available hanya Rabu, 27 Agustus 2025 pukul 10.30 secara offline apakah berkenan?</p> <p>Kami tunggu konfirmasinya yaa...</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-08-16 09:28:27');
