INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12223, 3190, 25, 'admin', 'Ribby Aura', '<p>Halo, Elya. Terima kasih sudah menghubungi layanan konseling UB dan mempercayakan pada kami. Saya tau bahwa tidak mudah untuk bisa terbuka, oleh karena itu saya sangat mengapresiasi keterbukaan kakak. Mungkin bisa dibantu untuk menjawab pertanyaan kami yaa kak:</p> <p>1. Coba ceritakan sejak kapan kakak merasa trauma dan apa alasan kakak merasa kambuh?</p> <p>2. Coba ceritakan apakah selama kakak merasa kambuh, hal tersebut mengganggu kehidupan sosial kakak?</p> <p>3. Apa yang kakak harapkan dari sesi konseling ini?</p> <p>Kami tunggu jawabannya ya, Kak Elya! Terima kasih :)</p>', '2025-08-20 21:19:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12224, 3190, 102350, 'mahasiswa', 'Elya Pane', '<p>Saya kira dengan saya memilih konseling langsung akan lebih baik dibandingkan mengetik. Apakah saya harus mendeskripsikan terlebih dahulu ya pada laman ini ?</p>', '2025-08-20 21:22:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12225, 3182, 102801, 'mahasiswa', 'Fransiska', '<p>Saya bersedia konseling pada 4 September pukul 13.00 dengan Bu Ratri. Terima kasih.</p>', '2025-08-20 21:25:54');
