INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12228, 3191, 102060, 'mahasiswa', 'Alysa Marizka', '<p>Saya selalu merasa kurang dan jadi stress sekali hingga ngaruh ke fisik</p>', '2025-08-20 22:53:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12229, 3192, 102836, 'mahasiswa', 'Robby Ma''arif', '<p>Saya mempunyai beberapa permasalahan yang saya juga bingung masuk ke dalam kategori mana. Jadi saya pilih masalah topik masalah pribadi. Saya kesulitan menemukan orang untuk tempat bercerita, ada masalah perihal lain di keluarga, bingung menanggapi masalah yang terjadi. Saya sudah lelah sudah mencoba menjalaninya, tapi selalu datang masa kebingungan bagaimana cara saya menanggapi ini semua. Terkadang saya menangis, tapi saya merasa lemah ketika saya menangis. </p>', '2025-08-20 23:20:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12230, 3182, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Untuk informasi selanjutnya akan kami hubungi melalui WA. </p>', '2025-08-21 07:43:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12231, 3188, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf sebelumnya kak, karena hari ini sudah hari kamis, kami perlu berkoordinasi dengan peer counselor kami, bisa beri kami opsi satu hari sebelum jadwal konseling. Jika hari jumat besok, bagaimana kak?</p> <p>Kami tunggu konfirmasinya,</p> <p>Terima kasih,</p> <p>Salam hangat.</p> <p>Tim Konseling UB.</p>', '2025-08-21 07:59:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12232, 3192, 28, 'admin', 'Ishida Ayumi', '<p>Selamat pagi, Robby Ma''arif!</p> <p dir="ltr">Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail mengenai permasalahan yang Anda alami? Menurut Anda apa penyebab hal tersebut terjadi?</p> <p dir="ltr">2. Dari permasalahan-permasalahan tersebut, apa efeknya ke kegiatan keseharian Anda? Dan apakah sudah sangat mengganggu?</p> <p dir="ltr">3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p><br /></p> <p><br /></p>', '2025-08-21 08:03:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12233, 3191, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat pagi, Alysa!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail mengenai rasa kurang yang Anda pikirkan, Anda merasa kurang dalam hal apa? Menurut Anda apa penyebab hal tersebut terjadi?</p> <p dir="ltr">2. Dari rasa kurang yang Anda rasakan, apa efeknya ke kegiatan keseharian dan sosial Anda? Apakah sudah sangat mengganggu?</p> <p dir="ltr">3. Sudah berapa lama Anda memiliki pemikiran tersebut?</p> <p dir="ltr">4. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">5. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p><br /></p>', '2025-08-21 08:07:16');
