INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12236, 3190, 28, 'admin', 'Ishida Ayumi', '<p>Kami berharap Anda bisa mendeskripsikan lebih detail untuk membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan. Dan akan langsung kami bantu jadwalkan dengan psikolog kami.</p> <p>Kami tunggu konfirmasinya,</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-08-21 08:12:17');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12237, 3190, 102350, 'mahasiswa', 'Elya Pane', '<p>Mohon maaf ka, saya belum berkenan melalui online. Mohon dibantu untuk konsultasi secara langsung dengan psikolog. Terima kasih sebelumnya</p>', '2025-08-21 08:52:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12238, 3190, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Berikut opsi jadwal konseling yang dapat Anda pilih:</p> <p>- Senin, 25 September 2025 pukul 10.10 (daring)</p> <p>- Kamis, 28 September 2025 pukul 09.00 (daring)</p> <p>Kami tunggu konfirmasinya,</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-08-21 08:56:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12240, 3190, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Berikut opsi jadwal konseling yang dapat Anda pilih:</p> <p>- Senin, 25 September 2025 pukul 10.10 (daring)</p> <p>- Kamis, 28 September 2025 pukul 09.00 (daring/luring)</p> <p>Untuk konseling secara daring akan dilakukan melalui gmeet ya..</p> <p><br /></p> <p>Kami tunggu konfirmasinya,</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-08-21 08:56:48');
