INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12253, 3193, 102837, 'mahasiswa', 'Indiera Mecca', '<p>Saya merasa ada yang dalah dengan sifat dan karakter saya akibat dari trauma saya di masa lalu yang belum bisa saya maafkan hingga saat ini membuat saya menjadi mudah untuk menyakiti diri saya sendiri</p>', '2025-08-21 19:47:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12254, 3183, 102829, 'mahasiswa', 'Tabina Khairunnisa', '<p>baik ka, saya memilih waktu di hari senin pukul 09.00 </p> <p>opsinya hari rabu pukul 13.00, saya mengharap untuk bisa luring tp jika tdk bisa daringpun tidak masalah:)</p> <p>terima kasih tim konseling UB sudah berkenan mendegar curhat saya:)</p>', '2025-08-21 20:30:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12255, 3191, 102060, 'mahasiswa', 'Alysa Marizka', '<p>1. saya kurang dalam segala hal. syaa tidak terlalu nyaman baha detail</p> <p>2. hmm belum sangat mengganggu tapi lelah terus memikirkannya seperti saya memberi terlalu banyak energi fokus ke kekurangan saya</p> <p>3. dari kecil</p> <p>4. pergi ke psikolog</p> <p>5. belum tau. saya hanya pikir lebih baik saya reach out </p>', '2025-08-21 23:20:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12256, 3193, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat pagi, Indiera!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail mengenai sifat dan karakter yang Anda rasa salah?</p> <p dir="ltr">2. Apa efeknya ke kegiatan keseharian dan sosial Anda? Dan apakah sudah sangat mengganggu?</p> <p dir="ltr">3. Sudah berapa lama Anda melakukan hal yang merugikan diri Anda sendiri? Seberapa banyak frekuensinya dalam suatu waktu?</p> <p dir="ltr">4. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">5. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan dan nantinya akan langsung kami jadwalkan konseling.</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /></p>', '2025-08-22 05:52:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12257, 3191, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas responnya. Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun jadwal konsseling offline hingga 2 minggu kedepan sudah penuh dan hanya tersisa jadwal konseling <em>online. </em>Apakah Anda bersedia melakukan konseling secara online? Berikut opsi jadwal yang dapat Anda pilih:</p> <p dir="ltr">- Senin, 1 September 2025 pukul 10.10 (daring)</p> <p dir="ltr">- Senin, 1 September 2025 pukul 14.00 (daring)<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-08-22 05:53:13');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12258, 3192, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas respon yang diberikan.Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun jadwal di minggu depan hanya tersisa jadwal <em>online</em> pada hari Senin, 25 Agustus 2025 pukul 10.10. Apakah Abda bersedia di waktu tersebut?</p> <p dir="ltr"><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-08-22 05:53:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12259, 3177, 28, 'admin', 'Ishida Ayumi', '<p>Terima kasih atas konfirmasinya. Untuk informasi yang lebih detail akan kami hubungi melalui WA ya kak. </p>', '2025-08-22 05:57:15');
