INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12284, 3198, 102842, 'mahasiswa', 'Teresa tju', '<p>Kadang kalo lagi kuliah atau di rumah kos sendiri , sama temen atau sendiri sering ngerasa jantungnya kaya habis lari maraton tiba tiba , detak jantungnya cepet kaya orang mau serangan jantung dan tangan gemetar sama facial muka ga ke control.</p>', '2025-08-23 12:27:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12285, 3184, 102830, 'mahasiswa', 'Imtiyas Zulfa', '<p>Halo maaf sebelumnya, untuk sekarang saya belum bisa memastikan apakah minggu depan ada waktu untuk sesi dengan peer konselor nya dikarenakan kesibukan dan adaptasi minggu minggu awal perkuliahan. Sebelumnya, mohon maaf saya ingin mengajukan beberapa pertanyaan, untuk durasi persesinya berapa lama ya? Sesi dengan peer konselor dilakukan secara online atau tatap muka? kemudian juga apakah ada additional fee untuk sesi ataupun tahap selanjutnya yang diikuti? Terima kasih banyak<br /></p>', '2025-08-23 13:35:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12286, 3167, 102815, 'mahasiswa', 'inzaghita sutanto', '<p>iya bisa</p>', '2025-08-23 13:42:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12287, 3199, 102843, 'mahasiswa', 'Rafasya Nugroho', '<p>Dari saya kecil, saya sulit mengelola emosi dan sering menghindari masalah. Tidak jarang juga saya mengalami panic attack yang berlebihan. Saya mudah sekali lelah dan terkena burnout. Karena saya sekarang sudah kuliah, saya ingin memperbaiki semua pernasalahan ini.</p>', '2025-08-23 15:57:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12288, 3196, 102840, 'mahasiswa', 'Noor Rahmadani', '<p>Selamat siang,<br />Saya pilih jadwal hari Selasa, 9 September 2025 secara offline.<br /><br />Terima kasihh</p>', '2025-08-23 16:28:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12289, 3167, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Untuk informasi selanjutnya akan kami hubungi melalui WA.</p>', '2025-08-23 18:57:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12290, 3184, 28, 'admin', 'Ishida Ayumi', '<p>Baik tidak apa-apa kak, Anda bisa menghubungi kami kapan saja etika Anda sudah memiliki waktu luang untuk menjadwalkan kembali. Untuk durasi konselingnya 1-1,5 jam, sesi dengan peer counselor dapat dilakukan secara online maupun offline (bergantung pada kesediaan Anda), dan untuk layanan kami gratis ya kak.</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB. </p>', '2025-08-23 19:04:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12291, 3192, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf untuk jadwal tersebut sudah terisi. Apakah Anda berkenan untuk memilih jadwal yang lain? Jika di hari dan jam yang sama baru tersedia di minggu depannya yaitu tanggal 15 September 2025 pukul 10.00.</p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2025-08-23 19:07:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12292, 3196, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Untuk informasi selanjutnya akan kami hubungi melalui WA.</p>', '2025-08-23 19:11:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12293, 3198, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat malam, Teresa!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail mengenai respon fisik yang Anda alami? Menurut Anda apa penyebab hal tersebut terjadi? Apakah Ada peristiwa yang mungkin menyebabkan hal tersebut terjadi?</p> <p dir="ltr">2. Apakah sebelumnya Anda pernah memeriksakan hal tersebut kepada dokter?</p> <p dir="ltr">3. Sebelumnya apakah Anda pernah mengakses layanan psikolog/psikiater?</p> <p dir="ltr">4. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">5. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.<br /></p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-08-23 19:21:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12294, 3199, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat malam, Rafasya!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah akhir-akhir ini Anda juga mengalami panick attack? Seberapa sering Anda mengalami panick attack dan dalam kondisi yang seperti apa? </p> <p dir="ltr">2. Sebelumnya apakah Anda pernah mengakses layanan psikolog/psikiater?</p> <p dir="ltr">3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr">Dan untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog klinis kami? Namun karena jadwal psikolog kami hingga 2 minggu kedepan sudah penuh, jadwal dengan psikolog kinis kami baru tersedia pada hari Rabu, 10 September 2025 ukul 10.00. Apakah Anda berkenan menunggu?</p> <p dir="ltr">Kami tunggu konfirmasinya ya,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2025-08-23 19:30:26');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12295, 3200, 102844, 'mahasiswa', 'Rayya Jannah', '<p>saya tumbuh di keluarga yang mulanya harmonis selayaknya keluarga normal, saya memiliki motivasi kuat untuk terus berkembang dan mencapai berbagai hal demi orang tua saya. Tetapi hingga saat ini, saya merasa semua pencapaian saya tidak pernah cukup untuk membahagiakan mereka. Mereka selalu menuntut lebih kepada saya, sedangkan usaha saya tidak diapresiasi dan terkadang dianggap remeh. Mereka seringkali tidak menghargai batasan-batasan saya, mereka juga seringkali tidak menghargai waktu yang saya luangkan untuk mereka. Saya muak dengan tekanan ini, saya hanya ingin mendapat tempat yang aman dan nyaman di keluarga saya sendiri.</p>', '2025-08-23 19:30:26');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12296, 3200, 28, 'admin', 'Ishida Ayumi', '<p>Selamat malam, Rayya!</p> <p dir="ltr">Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal minggu depan sudah penuh, jadwal dengan psikolog kami baru tersedia pada hari:</p> <p dir="ltr">- Senin, 1 September 2025 pukul 14.00 (daring)</p> <p dir="ltr">- Kamis, 11 September 2025 pukul 09.00 (daring/luring)</p> <p dir="ltr">Jika waktu tersebut terlalu lama, kami juga bisa menjadwalkan Anda dengan peer counselor kami yang memiliki jadwal lebih fleksibel. Jika Anda bersedia melakukan konseling dengan peer counselor kami, beri kami 2 opsi jadwal antara hari senin-jumat pukul 08.00-15.00.<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-08-23 19:35:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12297, 3200, 102844, 'mahasiswa', 'Rayya Jannah', '<p>sepertinya terlalu lama kalau sampai september, saya bersedia konseling dengan peer counselor</p>', '2025-08-23 19:47:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12298, 3201, 102845, 'mahasiswa', 'Safa Sari', '<p>beberapa orang menyebut saya nirempati, tidak bisa merasakan cinta dari orang sekitar saya, tidak pernah merasa benar benar bahagia, tidak pernah merasa benar benar sedih, saya juga terbiasa melakukan hal hal sendiri tapi saya tetap memiliki banyak teman kok, saya good listener tp bad responder, saya bingung penyebab ini apa? apa karna saya terlalu sering menyimpan sedih sendirian? harus selalu terlihat bahagia? bahkan saat saya sakit sebisa mungkin tidak memberitahukan siapa” karna saya rasa orang sekitar saya gapeduli jg sih, ayah saya selingkuh saat saya masih SD hingga sekarang dan mama saya tidak memperbolehkan saya untuk menceritakan hal itu ke siapa siapa karena aib, saya juga merasa sering mendapat treat yang beda dengan kakak laki” saya, yang membuat saya harus lebih mandiri dan tanggung jawab pd diri sendiri, dan saya baru berani cerita ayah selingkuh ke orang pertama yaitu mantan saya saat saya sudah SMA, apakah itu? atau memang bawaan saya seperti ini?</p>', '2025-08-23 20:50:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12299, 3202, 102846, 'mahasiswa', 'Avrillianti', '<p>Saya merasa diri saya terlalu khawatir akan hal-hal yang belum tentu terjadi, cukup banyak hal sekarang ini yang membuat saya ke trigger dengan luka lama saya, dan karena itu tidak jarang membuat aktivitas keseharian saya ikut terganggu, saya jadi sulit fokus dan memengaruhi mood saya. </p>', '2025-08-23 21:21:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12300, 3165, 102812, 'mahasiswa', 'Wafa', '<p>Assalamualaikum warahmatullahi wabarakatuh.</p> <p>Izin menjawab untuk perihal konseling. Untuk itu saya siap mengadakan konseling pada Jumat depan jam 14:00. Namun jikalau ada perubahan jadwal dikarenakan jam mata kuliah, akan saya sampaikan dan akan saya cari jadwal untuk dilakukannya konseling online. Selebihnya terimakasih atas informasinya.</p>', '2025-08-23 21:42:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12301, 3203, 102847, 'mahasiswa', 'DAFFI SAID', '<p>Pada hari kamis tanggal 21 Agustus 2025 saya ada kelas di jam 12.40 namun saya tidak membaca WA kalau dosen memajukan jadwal mata kuliah menjadi jam 12.00, saya tau itu kesalahan saya karena tidak membaca WA beberapa jam sebelum perubahan jadwal itu sehingga saya Alpha, apakah tidak ada cara untuk saya memperbaiki atau menghilangkan Alpha tersebut? Karena menurut saya nilai 100 tidak cukup menutupi 1 alpha. Saya membutuhkan pencerahan karena hal ini selalu menjanggal di fikiran saya, membuat saya tidak fokus karena selalu memikirkan hal ini </p>', '2025-08-23 22:36:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12302, 3204, 102848, 'mahasiswa', 'FAJAR ARRIZKI', '<p>Saya sering mengalami <strong>kecemasan sosial</strong>, baik saat bertemu orang lama maupun orang baru. Hal ini membuat saya mudah <strong>overthinking</strong> dan cenderung memikirkan banyak hal secara berlebihan.</p> <p>Kondisi ini paling terasa ketika saya harus <strong>memperkenalkan diri, berbicara di depan umum, atau melakukan presentasi</strong>. Gejala yang muncul antara lain <strong>sakit perut, keringat berlebihan, pikiran tiba-tiba blank, serta kesulitan menjaga kontak mata</strong> (lebih sering menunduk). Mata saya juga terasa cepat lelah saat situasi itu terjadi.</p> <p>Saat mengikuti <strong>lomba</strong>, saya sempat merasa bisa menekan gejala itu, tetapi yang terjadi justru <strong>otak saya kaget, blank, dan tiba-tiba terasa kosong</strong>, sehingga penampilan saya menjadi kurang baik.</p> <p>Selain itu, saya juga sering mengalami <strong>overthinking yang cukup berat</strong>. Ketika menghadapi <strong>kegagalan demi kegagalan</strong>, sering muncul pikiran negatif yang tidak sehat, bahkan kadang muncul dorongan di kepala saya seperti ingin menyerah total atau merasa hidup tidak ada artinya. Karena saya lebih sering menemui kegagalan dibanding keberhasilan, pikiran seperti ini cukup sering datang dan membuat saya semakin tertekan.</p> <p>Saya merasa masalah ini mungkin juga ada kaitannya dengan pengalaman masa lalu. Saya pernah menjadi <strong>korban bullying dalam waktu yang cukup lama</strong>, mulai dari kelas 1–6 SD hingga kelas 1–3 SMP. Saat masuk ke bangku SMK, meskipun teman sekelas saya sebenarnya baik, saya tetap cenderung <strong>mengurung diri</strong>. Sering kali saya memilih <strong>tidur di kelas setelah pelajaran</strong> agar tidak terjadi hal-hal yang tidak saya inginkan. Saya sendiri bingung kenapa melakukan itu, padahal situasinya sudah lebih baik.</p> <p>Kebiasaan ini ternyata <strong>terbawa hingga ke bangku perkuliahan</strong>. Saat ini, saya masih sering merasa tidak berani memulai interaksi terlebih dahulu. Biasanya saya menunggu orang lain yang memperkenalkan diri atau menghampiri saya, baru setelah itu saya bisa lebih terbuka.</p> <p>Masalah ini membuat saya sulit fokus, menurunkan motivasi, dan memengaruhi kondisi emosional saya dalam menjalani perkuliahan. Saya berharap bisa mendapatkan arahan bagaimana cara memahami dan mengatasi kecemasan, pola pikir negatif, serta dampak pengalaman masa lalu agar tidak mengganggu aktivitas kuliah maupun kehidupan sehari-hari.</p>', '2025-08-23 23:26:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12303, 3165, 28, 'admin', 'Ishida Ayumi', '<p>Selamat pagi, Wafa!</p> <p>Mohon maaf sebelumnya, dikarenakan terdapat pergantian jadwal di semester baru, jadwal konseling pada hari jumat tersebut sudah tidak tersedia karena berpindah ke hari senin. Jika konseling dijadwalkan ulang pada hari Senin, 1 September 2025 pukul 14.00 secara online apakah Anda bersedia?</p>', '2025-08-24 08:24:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12304, 3205, 102849, 'mahasiswa', 'sendy winata', '<p>Perawalmulaan, Teman Satu kost Memesan video yang bertujuan Pemuasaan pribadi, Lalu tidak mau menggunakan data pribadi sehingga menggunakan data pribadi saya,secara tidak langsung kita kena pemerasan dari pihak sebelah. dan data Pribadi saya mau di unggah di karena telah memesan video tersebut, hingga menjadi pencemaran nama baik oleh kesebelah pihak.</p>', '2025-08-24 10:45:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12305, 3165, 102812, 'mahasiswa', 'Wafa', '<p>Izin menjawab. Untuk itu, pergantian jadwal ke Senin 1 September jam 14:00 sepertinya bisa.</p>', '2025-08-24 12:15:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12306, 3194, 102838, 'mahasiswa', 'Balqis Salsabilla', '<p>Jika di jam 10.00 bagaimana kak? karna di hari kamis ada matkul pukul 07.00-09.30</p> <p><br /></p>', '2025-08-24 19:11:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12307, 3194, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf kak, untuk jadwal di jam 10 tidak tersedia ya kak jika di hari Senin, 15 September 2025 pukul 10.00 bagaimana kak? Apakah Anda bisa di wakti tersebut?<br /></p>', '2025-08-24 19:40:23');
