INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12336, 3211, 102855, 'mahasiswa', 'sheyla dewi', '<p>saya merasa belakangan ini cape, berat, ada pressure. kadang menurut saya masalah yg seharusnya ga berat tapi jadi berat, gampang emotional marah sedih. </p>', '2025-08-25 13:34:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12337, 3212, 102769, 'mahasiswa', 'Ayu', '<p>setelah konseling sebelumnya, belum mengalami perubahan, sudah melakukan saran, tetapi masih sering cemas sehingga timbul nyeri di dada, sulit untuk tidur, badan tiba tiba demam dan sangat pusing, ingin konseling lanjutan soal permasalahan yang sama.</p>', '2025-08-25 13:47:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12338, 3213, 102856, 'mahasiswa', 'Aisyah Farhanah', '<p><br /></p> <p>Waktu PKKMB kemarin, saya sempat merasa sumpek dan nggak nyaman di dalam ruangan,jadi saya keluar. Tapi ternyata di luar ruangan saya malah jadi kesemutan dan susah bernapas. Hari itu dengan Kak Cristina saya dibantu oleh Bu Bona.</p> <p>Saya sendiri juga masih bingung, apakah ini masalah fisik atau mental. Tapi saya sadar, kalau saya sedang jenuh, sumpek, atau panik, saya jadi susah fokus, gampang kesemutan, dan nggak bisa diam—harus ada bagian tubuh yang digerakkan, kalau nggak saya merasa risih banget.</p> <p>Saya ingin ikut konseling karena berharap bisa belajar cara mengatasi kondisi seperti ini, terutama saat panik atau ketika pernapasan mulai terasa berat. Saya ingin lebih tahu apa yang sebenarnya terjadi dengan tubuh dan pikiran saya, dan bagaimana cara mengatasinya dengan lebih baik.<br /></p>', '2025-08-25 14:29:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12339, 3208, 26, 'admin', 'Nadia Aura', '<p>Baik, terima kasih konfirmasinya. Akan kami jadwalkan di hari Selasa, 26 Agustus pukul 11.30 secara offline ya. Untuk informasi selanjutnya akan kami sampaikan melalui WhatsApp.</p>', '2025-08-25 16:39:57');
