INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12350, 3215, 102858, 'mahasiswa', 'Norine', '<p>Baru aja putus Pak/Bu, saya bener bener bingung kalau untuk di ketik, udah ga ada tenaga, kalau bisa hari ini saya ketemu sama Ibu konsulnya:( sebenernya malu buat cerita gini pada saat ketemu, tapi saya bener bener udah bingung harus ngapain:( ada pertanyaan yang bener bener ingin saya tanyakan nanti :)</p>', '2025-08-26 07:07:29');
