INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12475, 3239, 29, 'admin', 'Aisyah Salsa', '<p>Baik, Terima kasih sudah berbagi cerita dengan Layanan Konseling UB mengenai pengalamanmu beberapa minggu terakhir. Kami memahami bahwa situasi insidental yang tidak berjalan sesuai rencana, meskipun hal itu kecil, telah memunculkan perasaan sedih dan cemas yang mengganggu aktivitas dan hubungan sosialmu.</p> <p>Terkait dengan perasaan dan pengalaman yang Anda alami, apakah anda berkenan untuk melakukan konseling bersama konselor kami pada hari Rabu, 17 September 2025 pukul 19.00 secara online?</p> <p>Kami tunggu konfirmasinya yaa...</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-08-28 21:35:06');
