INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12546, 3189, 25, 'admin', 'Ribby Aura', '<p>Terimakasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Saya sangat memahami pasti situasi ini tidak mudah untuk dilalui. Saya mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Saya akan coba bantu jadwalkan sesi dengan psikolog kami. Jika berkenan, apakah kakak berkenan untuk melakukan konseling pada Kamis, 18 September 2025 pukul 09.00 dengan psikolog kami, Ibu Santi? Terima kasih kami tunggu konfirmasinya yaa kak :)</p>', '2025-09-02 09:39:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12547, 3223, 25, 'admin', 'Ribby Aura', '<p>benar kak lewat reply. mohon maaf kak apakah kakak berkenan apabila jadwal diajukan menjadi hari Rabu, 10 September pukul 13.00 dengan psikolog kami, Ibu Ika F? dan apakah kakak berkenan apabila konseling dialihkan ke BKM FISIP UB? dikarenakan jadwal psikolog LKM UB sudah penuh namun untuk BKM sendiri tersedia di pekan depan. Kami tunggu konfirmasinya ya kak :)</p>', '2025-09-02 09:49:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12548, 3254, 25, 'admin', 'Ribby Aura', '<p>mohon maaf kak, ada kendala pada jadwal peer counselor kami apabila konseling dilakukan hari ini karena mendadak. Apakah kakak tetap berkenan mengajukan jadwal di hari Kamis 09.00?</p>', '2025-09-02 09:51:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12549, 3258, 102530, 'mahasiswa', 'Melani', '<p>4 bulan yang lalu saya mengalami putus cinta dengan pacar saya, saya dengan dia sama2 satu prodi dan hanya beda kelas saja. saya dan dia juga masuk ke bem fakultas, saya mulai kehilangan profesionalisme diri saya di organisasi karena akar masalahnya juga saya dipaksa oleh pacar saya untuk masuk ke bem fakultas. saya mulai sering tidak hadir pada acara kabinet, rapat besar, dan lain lain. di lain sisi saya juga tidak betah di fakultas saya dan ingin pindah ke kampus impian saya, tetapi takdirnya gagal. saya merasa sudah tidak berenergi lagi untuk berkuliah apalagi teman dekat saya juga sudah pindah fakultas. saya merasa takut, cemas, gemeter tiap mau berangkat kuliah karena sering takut dengan apapun yg terjadi. </p>', '2025-09-02 10:19:11');
