INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12604, 3268, 25, 'admin', 'Ribby Aura', '<p>Terimakasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Saya sangat memahami pasti situasi ini tidak mudah untuk dilalui. Saya mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Apakah kakak berkenan untuk melakukan konseling dengan psikolog kami? Atau apa yang kakak harapkan dari mengirimkan tiket tersebut?<br />Terima kasih kami tunggu responnya :)</p>', '2025-09-03 18:52:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12605, 3268, 102912, 'mahasiswa', 'Anastacia Kanayawati', '<p>Boleh Kak, tapi apakah bisa konseling psikolognya secara online? Dikarenakan jadwal kuliah saya padat sekali dari pagi hingga sore hari. Terima kasih...</p>', '2025-09-03 18:57:13');
