INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12611, 3184, 102830, 'mahasiswa', 'Imtiyas Zulfa', '<p>Halo, apakah hari jumat pagi ada waktu untuk sesi dengan peer counselor secara online?<br /></p>', '2025-09-03 20:36:13');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12612, 3270, 102914, 'mahasiswa', 'Yohanes Soesanto', '<p>saya itu merasa diri saya aneh seperti kalau lg berkomunikasi dengan orang lain saya banyak takut salahnya trus saya merasa harga diri saya kek rendah bgt entah kenapa. trus bawaanya sedih moodswing terus</p>', '2025-09-03 22:20:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12613, 3270, 102914, 'mahasiswa', 'Yohanes Soesanto', '<p>saya sebenernya juga abis putus sebenernya saya tau bahwa masalah cinta itu sebagai penghalang dihidup cuma gatau kenapa saya ga bisa kalo sendiri dan kesepian dan saya ngerasa ada yang harus selalu ada buat saya 24 jam. trus kalok curhat ketemen kadang malahan mereka ga peduli atau bahkan malah crita balik jadinya ngerasa ga didengerin.apakah saya sosialy aneh terlalu memikirkan takut salah dan lain” karna saya ngerasa itu justru menghambat untuk bisa kenalan dan komunikasi sama yang lain</p>', '2025-09-03 22:25:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12614, 3270, 102914, 'mahasiswa', 'Yohanes Soesanto', '<p>saya sebenernya juga abis putus sebenernya saya tau bahwa masalah cinta itu sebagai penghalang dihidup cuma gatau kenapa saya ga bisa kalo sendiri dan kesepian dan saya ngerasa ada yang harus selalu ada buat saya 24 jam. trus kalok curhat ketemen kadang malahan mereka ga peduli atau bahkan malah crita balik jadinya ngerasa ga didengerin.apakah saya sosialy aneh terlalu memikirkan takut salah dan lain” karna saya ngerasa itu justru menghambat untuk bisa kenalan dan komunikasi sama yang lain</p>', '2025-09-03 22:25:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12615, 3262, 102906, 'mahasiswa', 'Ricky Aulia', '<p>Sepertinya saya tidak masalah. Terkait hal itu, apakah untuk yang bertugas adalah peer counselor atau psikolog ya? Terima kasih sebelumnya. </p>', '2025-09-03 23:25:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12616, 3263, 102896, 'mahasiswa', 'Hans Satriady', '<p>Selamat malam, saya mohon maaf karena baru menjawab sekarang. Apakah besok dan Jumat memungkinkan? Kamis setelah pukul 10.00 dan hari Jumat bisa sekitar pukul 10-12 atau 1-2 siang karena kelas saya mulai pukul 15.40 pada hari tsb. Terima kasih </p>', '2025-09-03 23:47:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12617, 3271, 102915, 'mahasiswa', 'Cahaya', '<p>Bagaimana cara mengatur waktu </p>', '2025-09-03 23:55:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12618, 3263, 102896, 'mahasiswa', 'Hans Satriady', '<p>Selamat malam, saya mohon maaf karena baru menjawab sekarang. Apakah besok dan Jumat memungkinkan? Kamis setelah pukul 10.00 dan hari Jumat bisa sekitar pukul 10-12 atau 1-2 siang karena kelas saya mulai pukul 15.40 pada hari tsb. Terima kasih </p>', '2025-09-04 00:08:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12619, 3272, 102916, 'mahasiswa', 'Hilva Fiardillah', '<p>saya tidak tau kenapa saya selalu merasa seperti ini. mungkin ini sudah saya rasakan kurang lebih satu tahun. saya merasa hidup saya tidak ada tujuan, tidak ada artinya. saya merasa tidak ada yang benar benar menginginkan saya di dunia ini. saya merasa sendiri, atau mungkin saya memang sendiri? saya belum memiliki teman di kampus. saya merasa tidak beruntung, saya tidak menginginkan kehidupan seperti ini. awalnya saya kuliah hanya untuk keluar dari rumah, namun rasanya sekarang saya juga ingin keluar dari sini. saya merasa saya tidak pernah berada di tempat yang saya inginkan, atau mungkin tidak ada tempat yang menginginkan saya? saya mulai berpikir apa mati sekarang saja ya? walaupun saya sudah pernah berpikir seperti itu sekitar 4 bulan lalu, tapi waktu itu saya masih takut masuk neraka. karena, katanya bunuh diri itu akan kekal di neraka yaa? sekarang saya kurang perduli perihal neraka atau surga. saya hanya ingin stop merasakan apapun. untuk kalimat "saya merasa tidak beruntung" itu ada di segala aspek. saya tidak memiliki kelebihan seperti yang lain, fisik, otak, bakat, keuangan, apapun itu. saya tahu, dunia memang tidak adil. tapi mengapa harus se-tidak adil ini Tuhan kepada saya? waktu itu saya pernah beberapa hari terus menerus memohon untuk segera mencabut nyawa saya kepada Tuhan, saya bilang kalau Tuhan tidak segera melakukanya saya akan melakukanya sendiri. tapi apa? sampai sekarang Dia masih diam, tidak mengabulkan permintaan saya ataupun melakukan sesuatu yang membuat saya masih ingin hidup. saya sempat marah kepada-Nya, tapi juga sedih. rasanya seperti tidak diperdulikan, oleh sekitar, bahkan Tuhan sekalipun. mati jalan satu satunya yaa? waktu itu saya tidak tahu harus melampiaskan perasaan saya pada siapa, lalu saya membuat akun instagram, private, saya melampiaskanya di kolom komentar. saya juga sempat komentar di aplikasi tiktok pada video yang relate terhadap perasaan saya. </p><figure><img src="cid:tr4vx2dfbp0zdnemfrwoq7aa2v-t249y" data-image="tR4vX2DFbp0zdNEMFRWoQ7aA2v-T249Y" alt="image" /></figure><figure><img src="cid:dkyyrk4oex1reeor41bpdi1qqaiukryy" data-image="dkYyRK4OEx1rEEOr41BPdi1qqaIukRyY" alt="image" /></figure><figure><img src="cid:qcwfnschqeks-a8za17g1t4thn6jegh8" data-image="QCWFnsChqeKs-A8ZA17G1T4tHn6JEGh8" alt="image" /></figure><figure><img src="cid:dbfbvasb1x4jfvpt93fxzihiththad3i" data-image="DBfBVAsB1x4JfVPT93FxZIHIthThaD3I" alt="image" /></figure><figure><img src="cid:mpgt8ii0js7vrm5wjqh6hjkrj6g0wcnc" data-image="MPgT8ii0JS7VrM5WjQH6HJKrJ6G0WCnc" alt="image" /></figure><figure><img src="cid:lx1rbixecxdtibu0jj_y5m-r_lyxxady" data-image="lx1RBIxECxDtIBU0Jj_Y5M-R_LyXXADY" alt="image" /></figure>', '2025-09-04 02:47:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12620, 3253, 102895, 'mahasiswa', 'Satria Yuswanto', '<p>Hai, kak. Maap lama menjawab, saya lupa belum memberikan tanggapan ditambah saya kepikiran buat ''menahan diri'' ngerasain hal-hal buruk itu, tapi karena banyaknya kejadian yang membuat hatiku tidak nyaman. Aku memutuskan untuk melanjutkan sesi konseling secara tatap muka. Saya bisa mengikuti agenda tersebut mulai nanti siang sampai besok Jumat. Kebetulan pagi ini merupakan matkul terakhir saya di minggu ini. Bagaimana dengan Kakak?</p>', '2025-09-04 07:55:06');
