INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12630, 3259, 27, 'admin', 'Shafhah Raisha', '<p>Nanti dari pihak kami yang akan menghubungi ya, Kak. Untuk waktu terdekat ada di hari Senin, 8 September 2025 pukul 14.00 WIB secara online. Apakah sekiranya Anda berkenan? Mohon konfirmasinya yaa. Terima kasih :)</p>', '2025-09-04 17:26:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12631, 3267, 27, 'admin', 'Shafhah Raisha', '<p>Baik, untuk informasi selanjutnya akan kami sampaikan melalui WhatsApp yaa, Kak :)</p>', '2025-09-04 17:28:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12632, 3260, 27, 'admin', 'Shafhah Raisha', '<p>Kak, mohon maaf baru membalas dikarenakan banyaknya antrian yang masuk. Karena waktunya sudah terlewat, apakah sekiranya Anda berkenan jika kami jadwalkan di kamis depan pada waktu yang sama?</p>', '2025-09-04 17:34:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12633, 3269, 27, 'admin', 'Shafhah Raisha', '<p>Selamat sore, Kak. Terima kasih telah menghubungi Layanan Konseling UB dan mohon maaf baru membalas dikarenakan banyaknya antrian yang masuk. Terima kasih karena telah berkenan untuk menceritakan apa yang sedang Anda rasakan dengan sangat detail. Kami sangat menghargai keterbukaan Anda karena kami sepenuhnya memahami bahwa hal tersebut tidaklah mudah. Untuk jadwal konseling terdekat yang kami miliki ada di hari Senin, 8 September 2025 pukul 11.30 WIB. Apakah sekiranya Anda berkenan jika kami bantu jadwalkan di waktu tersebut? Mohon konfirmasinya, yaaa. Terima kasih :)</p> <p>Salam hangat,</p> <p>Tim Konseling UB </p>', '2025-09-04 17:37:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12634, 3270, 27, 'admin', 'Shafhah Raisha', '<p>Selamat sore, Yohanes! <br />Terima kasih telah menghubungi Layanan Konseling UB dan mohon maaf baru memberikan balasan dikarenakan banyaknya antrian yang masuk. Terima kasih telah berkenan untuk menceritakan permasalahan yang sedang Anda rasakan. Apakah Anda berkenan jika kami bantu jadwalkan konseling dengan peer counselor kami? Jika berkenan, silahkan pilih waktu dari hari Senin sampai Jumat mulai pukul 09.00 sampai 15.00 secara offline ataupun online yaa, Kak. Kami tunggu konfirmasinya.</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB<br /></p>', '2025-09-04 17:41:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12635, 3262, 27, 'admin', 'Shafhah Raisha', '<p>Untuk jadwal psikolog kami di waktu tersebut sudah tidak tersedia, Kak. Apakah berkenan jika dijadwalkan dengan peer counselor kami? </p>', '2025-09-04 17:43:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12636, 3271, 27, 'admin', 'Shafhah Raisha', '<p>Selamat malam, Cahaya!</p> <p>Terima kasih telah menghubungi Layanan Konseling UB. Apakah Anda berkenan untuk menceritakan lebih lanjut terkait permasalahan yang sedang Anda rasakan? Seperti, apa yang membuat Anda merasa kesulitan dalam mengatur waktu dan apa saja langkah yang sudah Anda coba untuk mengatasi permasalahan yang Anda rasakan?</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-09-04 17:45:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12637, 3263, 27, 'admin', 'Shafhah Raisha', '<p>Kami akan coba untuk carikan jadwal terlebih dahulu ya, Kak. Nanti akan kami sampaikan mengenai informasi lanjutannya di WhatsApp :)</p>', '2025-09-04 17:46:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12638, 3272, 27, 'admin', 'Shafhah Raisha', '<p>Selamat malam, Hilva!</p> <p>Terima kasih telah menghubungi Layanan Konseling UB dan mohon maaf baru memberikan respon dikarenakan banyaknya antrian yang masuk. Kami sangat memahami bahwa apa yang Anda lalui tidaklah mudah dan kami sangat mengapresiasi keterbukaan Anda. Terima kasih karena telah bertahan sampai sejauh ini, yaa :) Anda hebat dan kami percaya Anda mampu untuk melalui apa yang terjadi. </p> <p>Mohon maaf sebelumnya, namun untuk jadwal dengan psikolog kami dalam waktu dekat ini sudah full dan tidak ada lagi yang tersedia. Jadwal yang tersedia baru ada di hari Rabu, 1 Oktober 2025 pukul 10.00 WIB. Apakah Anda berkenan jika kami bantu jadwalkan di waktu tersebut?</p> <p>Apabila dirasa terlalu lama, Anda dapat melakukan konseling dengan peer counselor kami terlebih dahulu sambil menunggu pelaksanaan konseling di tanggal 1 Oktober. Jika Anda berkenan, silahkan untuk menentukan waktu kesediaan Anda pada hari Senin sampai Jumat mulai pukul 09.00 WIB hingga pukul 16.00 WIB baik secara online ataupun offline yaa, Kak. </p> <p>Apabila Anda ingin dan merasa membutuhkan obat atau bertemu dengan psikiater kami, kami juga dapat merujuk dan mendampingi Anda ke RSSA jika diperlukan. Silahkan untuk memilih salah satu dari ketiga opsi yang membuat Anda lebih nyaman yaa, Kak. Ditunggu konfirmasinya :)</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-09-04 18:01:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12639, 3260, 102904, 'mahasiswa', 'Nadia', '<p>Jika hari Selasa setelah jam ke 2 apakah bisa kaa? </p>', '2025-09-04 18:02:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12640, 3266, 27, 'admin', 'Shafhah Raisha', '<p>Mohon maaf dikarenakan baru memberikan respon kembali, Kak. Apakah Anda berkenan jika kami jadwalkan di besok pukul 12.00? Untuk pelaksanaannya dapat dilakukan secara online ataupun offline yaa, Kak. Mohon konfirmasinya, terima kasih. </p>', '2025-09-04 18:02:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12641, 3273, 27, 'admin', 'Shafhah Raisha', '<p>Selamat malam, Muhammad! </p> <p>Terima kasih telah menghubungi Layanan Konseling UB dan mohon maaf baru memberikan respon dikarenakan banyaknya antrian yang masuk. Untuk membantu kami lebih memahami permasalahan Anda, apakah bisa lebih dijelaskan secara detail terkait masalah pribadi yang Anda alami? seperti sejak kapan dan sudah berapa lama Anda merasakan perasaan sulit fokus tersebut? dan apakah sekiranya ada kejadian atau situasi tertentu yang sekiranya memicu perasaan sulit fokus yang Anda rasakan?</p> <p>Apapun jawaban yang Anda berikan akan membantu kami untuk memetakan permasalahan lebih lanjut. Terima kasih.</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-09-04 18:05:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12642, 3274, 27, 'admin', 'Shafhah Raisha', '<p>Selamat malam, Mohammad!</p> <p>Terima kasih telah menghubungi Layana Konseling UB dan mohon maaf baru memberikan respon dikarenakan banyaknya antrian yang masuk. Terima kasih juga karena telah berkenan untuk menceritakan permasalahan yang Anda rasakan. Apakah Anda berkenan jika kami bantu jadwalkan untuk melakukan konseling dengan peer counselor kami terlebih dahulu? Jika berkenan, silahkan untuk memilih waktu dari hari Senin sampai Jumat mulai pukul 09.00 sampai 16.00 sesuai dengan waktu kesediaan Anda baik secara online ataupun offline ya, Kak. Mohon konfirmasinya :)</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-09-04 18:08:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12643, 3268, 27, 'admin', 'Shafhah Raisha', '<p>Untuk konseling bisa dilakukan secara online dan layanan ini tidak dipungut biaya apapun alias gratis yaa, Kak. Untuk jadwal konseling online tersedia di hari Kamis, 25 September pukul 09.00 WIB. Apakah Anda berkenan jika kami bantu jadwalkan di waktu tersebut? Mohon konfirmasinya, yaa :)</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-09-04 18:10:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12644, 3274, 102918, 'mahasiswa', 'Mohammad Walidaini', '<p><span dir="auto"><span dir="auto">Saya bersedia tetapi mau untuk online dulu dikarenakan belum pd nanti ketika suda berani saya akan bersedia konseling offline</span></span></p>', '2025-09-04 18:13:01');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12645, 3275, 27, 'admin', 'Shafhah Raisha', '<p>Selamat malam, Imaduddin. Mohon maaf  sebelumnya karena layanan kami merupakan layanan konseling. Untuk permasalahan terkait PPKS dapat menghubungi <a href="https://s.ub.ac.id/laporkekerasanseksualub">https://s.ub.ac.id/laporkekerasanseksualub</a> yaa, Kak. Terima kasih.</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-09-04 18:15:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12646, 3223, 27, 'admin', 'Shafhah Raisha', '<p>Kak, mohon maaf apabila di tanggal  17  September apakah Anda berkenan? </p>', '2025-09-04 18:26:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12647, 3260, 27, 'admin', 'Shafhah Raisha', '<p>Akan kami coba carikan dulu jadwal di jam 2 yaa kak. Informasi selanjutnya kami sampaikan melalui WhatsApp :)</p>', '2025-09-04 18:29:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12648, 3274, 27, 'admin', 'Shafhah Raisha', '<p>Baik, tidak apa apa. Silahkan untuk memilih waktu sesuai kesediaan Anda yaa, Kak. </p>', '2025-09-04 18:30:04');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12649, 3276, 102903, 'mahasiswa', 'Najwa', '<p>Saya sudah mengikuti kelas M1A (kelas bahasa Inggris), tetapi saya merasa stres dan berat sekali karena sebenarnya saya belum begitu menguasai bahasa Inggris. Saya juga mengalami kesulitan belajar, bersosialisasi, dan mengendalikan diri.</p> <p>Saya menjadi gelisah setiap saat karena takut tidak bisa menghadapi perkuliahan kedepannya dan tidak bisa bertahan. Saya selalu was-was, cemas berlebihan, tidak bisa tidur dan makan. Saya juga sempat terkena serangan panik di hari Selasa.</p> <p>Saya takut mengecewakan orang tua saya.</p> <p>Saya berharap bisa mendapatkan solusi untuk masalah saya ini, saya takut jika terus seperti ini akan berdampak buruk bagi kesehatan badan dan mental saya.</p>', '2025-09-04 18:31:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12650, 3260, 102904, 'mahasiswa', 'Nadia', '<p>Baik kaa terima kasih banyak </p>', '2025-09-04 18:43:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12651, 3259, 102902, 'mahasiswa', 'DINI USWATUN', '<p>Mohon maaf ka saya hanya tersedia di senin 07.00-10.30 dan selasa-jumat 07.00-09.00 selain itu terdapat kegiatan akademik yang selesai pada jam 17.10, apakah memungkinkan jika dilakukan malam hari</p>', '2025-09-04 19:28:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12652, 3269, 102913, 'mahasiswa', 'Namira', '<p>Terimakasih banyak atas responya, kebetulan saya memiliki kelas siang di hari senin, apakah memungkinkan bila diundur sedikit ke sore hari di hari senin? setelah 15.30 </p>', '2025-09-04 20:46:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12653, 3259, 27, 'admin', 'Shafhah Raisha', '<p>Untuk konseling di malam hari baru tersedia di tanggal 30 September, Kak yaitu di jam 19.00 secara online. Apakah Anda berkenan?</p>', '2025-09-04 20:50:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12654, 3269, 27, 'admin', 'Shafhah Raisha', '<p>Mohon maaf, Kak. Jika di jam segitu apakah berkenan jika bersama peer counselor kami terlebih dahulu?</p>', '2025-09-04 20:54:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12655, 3269, 102913, 'mahasiswa', 'Namira', '<p>saya mengerti, tidak apa kak, akan saya usahakan bisa di jam 11.30 di hari senin, terimakasih kak </p>', '2025-09-04 21:19:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12656, 3263, 102896, 'mahasiswa', 'Hans Satriady', '<p>Baik kak, ditunggu ya infonya :)  Terima kasih lagi</p>', '2025-09-04 21:30:19');
