INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12658, 3241, 102881, 'mahasiswa', 'Dimas Indrawan', '<p>Baik kak, saya bisa jam 10 pada tanggal 29 September </p>', '2025-09-04 21:59:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12659, 3272, 102916, 'mahasiswa', 'Hilva Fiardillah', '<p>Saya rasa 1 Oktober tidak lama, karena saya pikir kemarin malam pikiran saya hanya sedikit kacau makadari itu saya menghubungi konseling UB, saya tidak memiliki opsi lain dan tidak berpikir panjang. Hari ini saya membaik kok. Dan terima kasihh banyak untuk responya</p>', '2025-09-04 22:04:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12660, 3268, 102912, 'mahasiswa', 'Anastacia Kanayawati', '<p>Saya ada kelas kak di jam tersebut...</p> <p>Kalau di jam lain bagaimana?</p>', '2025-09-05 01:58:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12661, 3277, 102606, 'mahasiswa', 'Jovita Ramadhanie', '<p>Sebelumnya, saya sudah melakukan konseling pertama di tanggal 22 Juni 2025 bersama Ibu Yuliezar Perwira Dara (Bu Wira) dan menurut beliau saya memiliki satu sesi konseling lanjutan jika saya membutuhkan. Kemudian saya sudah WA layanan konseling UB untuk dibuatkan jadwal pertemuan dengan beliau juga belum mendapatkan tanggapan/jawaban. Saya butuh sekali bertemu beliau dan kalau bisa dengan tatap muka karena salah satu syarat pergantian dosen dari jurusan saya adalah adanya surat pernyataan dari psikolog yang merekomendasikan pergantian dosen tersebut.</p>', '2025-09-05 08:41:29');
