INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12704, 3281, 102922, 'mahasiswa', 'Monica Ayuningtyas', '<p>Iya, tidak apa-apa dijadwalkan di tanggal 1 Oktober jam 7 malam tersebut dulu sementara waktu ini. Terima kasih. </p>', '2025-09-06 23:54:28');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12705, 3287, 102926, 'mahasiswa', 'Garil Rayhan', '<p>saya sangat sulit untuk menyampaikan atau memaparkan ide, ketika saya berbicara suka tidak singkron dengan apa yang saya pikirkan dan itu sangat mengganggu saya, apalagi saat presentasi itu membuat saya gugup dalam bertanya atau memaparkan ide/gagasan</p>', '2025-09-07 07:52:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12706, 3288, 102927, 'mahasiswa', 'AMELIA AMANDA', '<p>ibu saya meninggal pada tahun 2022, saya merasa kehilangan sampe saat ini. seringkali saya teringat tentang ibu saya dan membuat saya terpuruk lagi dan lagi, hal itu membuat semangat belajar saya berkurang dan mengganggu segala aktifitas saya. banyak hal hal yang saya sesali dalam hidup saya yang membuat saya sering gelisah dan merasa bersalah yang amat dalam.</p>', '2025-09-07 10:26:55');
