INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12710, 3189, 27, 'admin', 'Shafhah Raisha', '<p>Mohon maaf sebelumnya, Kak. Namun, untuk saat ini jadwal tersebut sudah tidak lagi tersedia. Apakah sekiranya Anda berkenan jika melakukan konseling bersama konselor kami terlebih dahulu? Kami memiliki jadwal yang kosong di hari Kamis, 3 Oktober 2025 pukul 19.00 malam secara online. Mohon konfirmasinya, yaa. Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-09-07 13:35:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12711, 3189, 27, 'admin', 'Shafhah Raisha', '<p>Mohon maaf terdapat kesalahan, Kak. Untuk konselor kami di tanggal tersebut juga sudah tidak tersedia.  Namun, di minggu depannya di tanggal 10 Oktober kami memiliki jadwal yang kosong untuk konseling dengan psikolog kami di jam 10.00 pagi. Apakah Anda berkenan jika kami jadwalkan di waktu tersebut?</p>', '2025-09-07 13:37:19');
