INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12714, 3285, 102925, 'mahasiswa', 'Izzatur Wicaksono', '<p>Selamat siang juga, mba/mas. Saya izin konfirmasi ketersediaan, saya bersedia untuk konseling Rabu, 10 September 2025 pukul 13.00. Terima kasih</p>', '2025-09-07 13:46:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12715, 3289, 102928, 'mahasiswa', 'Syahvira', '<p>saya sudah beberapa hari mencoba untuk tidak minum obat depresi saya,tadinya tidak apa apa tapi sekarang saya selalu ngerasa harus ditemani baik secara virtual ataupun langsung.</p>', '2025-09-07 14:12:37');
