INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12726, 3290, 102929, 'mahasiswa', 'Nabilah Prayitno', '<p>Saya memiliki diagnosa gangguan bipolar oleh psikiatri dan sudah menderita depresi selama 8-9 tahun. Saya sering mengalami mood swing sehingga menganggu fokus terhadap akademik. Belakangan ini stres terasa berlebihan.</p>', '2025-09-07 19:56:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12727, 3290, 27, 'admin', 'Shafhah Raisha', '<p>Selamat malam, Nabilah!</p> <p>Terima kasih telah menghubungi Layanan Konseling UB dan berkenan untuk menceritakan permasalahan yang Anda rasakan. Mohon maaf namun untuk jadwal konseling dengan psikolog kami di bulan ini sudah full dan baru tersedia kembali di bulan depan. Apakah berkenan jika kami jadwalkan untuk konseling di hari Rabu, 8 Oktober 2025 pukul 10.00 WIB secara offline? Mohon konfirmasinya, yaa.</p> <p>Terima kasih</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-09-07 21:03:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12728, 3290, 102929, 'mahasiswa', 'Nabilah Prayitno', '<p>Baik, terima kasih atas responnya. Namun mohon maaf sebelumnya, untuk jadwal tersebut sepertinya saya tidak bisa menghadiri. Jika kedepannya saya masih membutuhkan, nanti akan saya hubungi kembali.</p> <p>Terima kasih<br /></p>', '2025-09-07 21:13:28');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12729, 3284, 102924, 'mahasiswa', 'Fitriya Wulandari', '<p>Baik</p>', '2025-09-07 21:38:26');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12730, 3291, 102930, 'mahasiswa', 'Farrah Yantes', '<p>saya lagi dalam masa transisi habis sidang skripsi, orangtua saya udah setuju untuk saya pulang ke kampung halaman dan cari kerja remote dan so far mereka sangat supportif dari segi modal dan material untuk mendukung karir dan rencana lanjutan studi saya. Here is the thing, saya merasa berkomunikasi dnegan mereka itu susah karena somehow kata kata yang keluar itu like sayatan yang tembus through your heart gitu. dan saya gak tau gimana caranya untuk bisa tetap produktif dari rumah, udah gitu saya merasa di rumah itu sayalah yng sellau menjadi pihak yang harus selalu waras, sebagai anak tertua dengan banyak adik, saya mengatur semua nya sendiri tapi sering disalahpahami.</p> <p>Saya juga punya kekhawatiran gak mendasar terhadap jalur karir saya pdahal modal ada dan sebenrya gak ada hal khusus yang perlu dikhawatirkan, tpai gak tau saya sering panic attack yang sampai parah gitu kalau sudah period dan episdoes nya. dan terkadang muncul pikiran untuk melakukan hal hal yang merugikan diri sendiri</p>', '2025-09-07 22:48:17');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12731, 3289, 102928, 'mahasiswa', 'Syahvira', '<p>malam kak, kalau sama yang psikolog klinis apakah bisa ya kak</p>', '2025-09-08 02:54:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12732, 3281, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf baru membalas dikarenakan antrian e-ticket yang cukup panjang. </p> <p><br /></p> <p dir="ltr">Baik, terima kasih atas konfirmasinya. Untuk informasi selanjutnya akan kami hubungi melalui WA.</p> <p><br /></p> <p><br /></p>', '2025-09-08 06:51:08');
