INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12763, 3276, 102903, 'mahasiswa', 'Najwa', '<p>Dengan hormat,</p> <p>Terima kasih atas respon yang telah diberikan terkait permohonan konsultasi saya sebelumnya. Melalui pesan ini, saya ingin mengonfirmasi bahwa saya bersedia dan akan hadir untuk melakukan konsultasi secara offline yang telah saya pilih jadwalnya pada hari Kamis, 11 September 2025, pukul 10.00 WIB.</p> <p>Saya sangat menghargai kesempatan dan waktu untuk pertemuan ini. Semoga konsultasi ini dapat berjalan dengan lancar dan memberikan hasil yang bermanfaat.</p> <p>Demikian konfirmasi ini saya sampaikan. Sekali lagi, saya ucapkan terima kasih atas perhatian dan tanggapan yang diberikan.</p> <p>Hormat saya,</p> <p>Najwa Farha Aulia</p>', '2025-09-09 11:22:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12764, 3297, 102936, 'mahasiswa', 'Reysha Syafitri', '<p>Jadi begini, saya itu bimbang antara ingin lanjut kuliah atau memilih untuk mengundurkan diri karena saya merasa ada di jalan yang salah, saya tidak mau kuliah farmasi namun saya ingin tetap kuliah tahun ini, tapi terkadang saya berpikir untuk mending gapyear aja dan kuliah di jurusan yang memang saya inginkan</p>', '2025-09-09 11:42:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12765, 3298, 102559, 'mahasiswa', 'Iqbal Hidayat', '<p>saya iqbal, saya sering merasa di awal semester ini memiliki stress yang cukup berat. mulai dari masalah finansial keluarga, masalah akademik (banyak tugas) yang membuat performa akademik saya menurun, serta tekanan organisasi yang rapat hingga larut malam, serta menyita waktu istirahat saya. saya ingin berisitirahat untuk memulihkan mental tetapi selalu  kepikiran hal tersebut. masalah finansial juga menjadi hal yang selalu berputar putar dikepala saya. Ibu saya bilang, kalau demi kuliah saya, beliau sampe berhutang sana sini</p>', '2025-09-09 11:42:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12766, 3296, 102935, 'mahasiswa', 'Afra Ramadhana', '<p>di hari jumat jam 15.00 jadwal yang pas buat saya</p>', '2025-09-09 12:52:32');
