INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12768, 3297, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat siang, Reysha!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan peer counselor? Jika Anda bersedia melakukan konseling dengan peer counselor kami, beri kami 2 opsi jadwal antara hari senin-jumat pukul 08.00-15.00.<br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-09-09 13:23:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12769, 3298, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat siang, Iqbal!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun jadwal terdekat yang tersedia adalah jadwal konseling online pada hari Senin, 22 September 2025 pukul 10.10. Apakah Anda berkenan untuk menunggu?</p> <p dir="ltr">Jika waktu tersebut terlalu lama, kami juga bisa menjadwalkan Anda dengan peer counselor kami yang memiliki jadwal lebih fleksibel. Jika Anda bersedia melakukan konseling dengan peer counselor kami, beri kami 2 opsi jadwal antara hari senin-jumat pukul 08.00-15.00 (online/offline).<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-09-09 13:29:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12770, 3293, 102932, 'mahasiswa', 'Hangga Alawi', '<p><br />Terima kasih atas respon dan perhatiannya. Saya bersedia untuk melakukan konseling dengan peer counselor.</p> <p>Saya mengajukan jadwal pada:<br />Senin, 15 September 2025 pukul 08.00 WIB <br /><br /><br /></p> <p><br /></p>', '2025-09-09 13:31:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12771, 3297, 102936, 'mahasiswa', 'Reysha Syafitri', '<p>peer counselor apakah online/offline? untuk jadwal besok, rabu 10 september jam 11.30 </p>', '2025-09-09 15:34:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12772, 3297, 102936, 'mahasiswa', 'Reysha Syafitri', '<p>saya bisanya hari rabu sajaa, sesuai dengan periode pengunduran diri di ub terakhir 10 september</p>', '2025-09-09 15:36:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12773, 3299, 102937, 'mahasiswa', 'Arvin Nabil', '<p>saya maba dan masuk tahun ke 3 setelah kmarin sempet nyoba di kampus swasta, lalu tahun ini saya ambil double degree di UT, dan skarang lagi ngerasa banyak banget pikiran di kepala, tapi susah untuk disalurkan, manajemen waktu saya burukk, kadang begitu dapat motivasi tapi hanya jalan di kepala, terus ngerasa banyak distraksi juga, entah itu dari diri sendiri atau ada dari memikirkan orang yang saya sukai atau gangguan distrac lain seperti kecanduan scroll hp atau game online (catur), saya punya mimpi besar, tapi susah atau malah malas untuk menjalankannya, takut mulai, saya sempat menunda bahkan tidak mengerjakan tugas yang diberikan, semangatnya di awal doang.. takut.. gaberani gatau kenapa, saya gapernah.. saya ngerasa gapernah memberikan 100% ketika memulai sesuatu, saya benar2 butuh bimbingan:(</p>', '2025-09-09 15:39:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12774, 3300, 100360, 'mahasiswa', 'Zuhrotul', '<p>Saya sedang menunggu pendaftaran wisuda. Saat ini kegiatan saya sedang berusaha membangun usaha freelance translating &amp; menjadi volunteer mahasiswa disabilitas. Saya setiap saat selalu merasa bingung dengan diri sendiri, sakit hati, sedih, terlebih melihat adik saya gajinya lebih stabil &amp; lebih tinggi serta magang di perusahaan yang jelas. Saya sering merasa diri saya tertinggal &amp; ga berguna, terlebih perlahan2 teman2 saya menikah &amp; udah sampai goals masing2. Saya gaenak mau ngeluh ke banyak orang &amp; sangat tertutup mengenai ini ke ortu, karena ortu saya lihat lebih condong ke adik ketimbang ke saya. Saya dianggap hanya ketika saya bikin achievement yg gede aja. Apalagi keinget dulu saya banyak di abuse &amp; tumbuh di masa2 terburuk ortu saya menjadikan saya semakin kesulitan terbuka ke ortu. Saya capek nganggur lama2, ya saya sebenarnya ngerasa kalo mungkin Tuhan membuat saya begini (menganggur) supaya saya bisa evaluasi diri dulu dan mungkin mempelajari skill lain, atau mungkin menyiapkan diri bisa saja suatu saat nanti saya menghadapi kesibukan di pekerjaan yang luar biasa. Saya berusaha berpikir positif demikian, tapi rasanya sulit dgn kondisi sosial seperti ini bahkan utl sekedar berpikir positif dgn keadaan saya saat ini</p>', '2025-09-09 16:09:05');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12775, 3301, 102938, 'mahasiswa', 'Darmawansyah Abror', '<p>Saya mengalami kesulitan dalam memperbaiki pola pikir dalam pengambilan keputusan dan penguatan mental dalam menghadapi permasalahan. Mindset yang terbentuk akibat mengalami perundungan pada masa sekolah mulai muncul kembali. Saya juga mulai kehilangan tujuan dalam kehidupan. Saya mohon bantuan kepada tim konseling, dalam hal ini, saya ingin tidak bergantung pada ekspektasi berlebih dan tidak ingin kehilangan rasa percaya diri saya, saya juga tidak ingin kesalahan berpikir mengakibatkan saya terjerumus ke dalam pola yang sama seperti dahulu.</p>', '2025-09-09 16:56:14');
