INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12819, 3302, 102941, 'mahasiswa', 'nesa fatean', '<p>Terimakasih bu Ishda atas tanggapannya, mungkin saya bisa ketika hari jumat, untuk jam nya karena saya kosong dari pagi sampai sore mungkin, jadi masih flexibel. </p>', '2025-09-11 08:23:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12820, 3294, 102933, 'mahasiswa', 'Muhammad', '<p><span dir="auto"><span dir="auto">Maaf ka sebelumnya saya ada kendala untuk login kesini</span></span></p> <p><span dir="auto"><span dir="auto"><span dir="auto"><span dir="auto"><span dir="auto"><span dir="auto">Saya sudah konfirmasi lewat email bahwasanya saya setuju untuk datang dihari ini hari kamis jam 9</span></span></span></span></span></span></p> <p><span dir="auto"><span dir="auto"><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit">dan saya sekarang sudah didepan ruangan layanan konseling ka</span></span></span></span></p> <p><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit">untuk selanjutnya bagaimana ya ka</span></span><br /><span dir="auto"><span dir="auto"><br /></span></span></p>', '2025-09-11 09:03:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12821, 3294, 26, 'admin', 'Nadia Aura', '<p>Selamat pagi Muhammad! Mohon maaf sebelumnya, dikarenakan tidak ada konfirmasi sebelumnya, maka mohon maaf kami belum bisa menjadwalkan Anda untuk sesi konseling pagi ini. Sebelum klien datang, kami juga perlu untuk memberi tahu psikolog kami terkait permasalahan yang akan ditangani. Jadi jika tidak ada konfirmasi maka kami tidak dapat memberitahukan pihak psikolog untuk mengambil sesi konseling pada pagi hari ini. Dan sayangnya jadwal psikolog untuk menangani permasalahan Anda sudah penuh di bulan ini, jika berkenan akan kami jadwalkan di bulan depan untuk waktu yang sama (Kamis pukul 09.00).</p> <p>Terima kasih atas pengertiannya.</p>', '2025-09-11 09:27:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12822, 3294, 102933, 'mahasiswa', 'Muhammad', '<p><span dir="auto"><span dir="auto"><span dir="auto"><span dir="auto"><span dir="auto"><span dir="auto">Baik ka berarti saya menunggu informasi selanjutnya di bulan depan?</span></span></span></span></span></span><br /></p>', '2025-09-11 09:32:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12823, 3308, 102946, 'mahasiswa', 'Muhammad Parchan', '<p>Ga tahu masalahnya apa, ga bisa menspesifikkan, rasanya frustasi tiap hari. Masalahnya juga terkait kuliah. Ga tahu, mgkn karena baru masuk, belum adaptasi, dengan tugas banyak ini rasanya capek, ga happy. Sama itu, rasanya kurang motivasi, males banget, ngapa-ngapain aja tuh males. Sama aku juga social anxiety, rasanya tuh tiap hari ga nyaman berinteraksi sosial. Bingung cara ngatesinnya.</p>', '2025-09-11 09:37:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12824, 3303, 26, 'admin', 'Nadia Aura', '<p>Selamat pagi, Ahmad! Dari peer counselor kami ada yang bisa di hari ini namun pukul 16.00 apakah berkenan? atau ingin di hari Jumat saja?</p>', '2025-09-11 10:02:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12825, 3309, 102947, 'mahasiswa', 'Nadhira Salsabila', '<p>Saya merasa belakangan ini menjadi pribadi yang lebih mudah merespon informasi dengan emosi tanpa bisa mencernanya lebih lanjut, terkadang emosi berlebihan yang tidak semestinya hanya karena masalah yang ringan, setelah merasakan emosi yang tidak dapat terkontrol saya mengalami kecemasan dan perasaan bersalah akibat dari emosi tersebut sehingga membuat hidup saya tidak nyaman </p>', '2025-09-11 10:15:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12826, 3276, 102903, 'mahasiswa', 'Najwa', '<p>Selamat pagi, mohon izin bertanya bu</p> <p>Apakah jadwal saya sudah di ACC?</p> <p>Saat ini saya sudah berada di depan ruangan konseling, Gedung Rektorat tetapi ruangan sepi, tidak ada orang sama sekali</p>', '2025-09-11 10:29:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12827, 3303, 102942, 'mahasiswa', 'Ahmad Kemal', '<p><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit">Boleh untuk nanti jam 16.00</span></span></p>', '2025-09-11 11:28:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12828, 3276, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf sebelumnya, dikarenakan terdapat error dari web kami sehingga eticket Anda baru muncul. Mohon maaf sebelumnya jadwal yang Anda ajukan belum kami jadwalkan dengan peer counselor kami ya. Sehingga saat ini anda tidak bisa melakukan konseling. Dan mohon untuk selanjutnya dipastikan mendapatkan konfirmasi dari kami terlebih dahulu, mengenai penjadwalan yang Anda ajukan. Dikarenakan kami juga harus koordinasi dengan peer counselor kami. Apakah Anda berkenan memberikan kami opsi dibhari lain?</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-09-11 11:36:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12829, 3276, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf sebelumnya, dikarenakan terdapat error dari web kami sehingga eticket Anda baru muncul. Mohon maaf sebelumnya jadwal yang Anda ajukan belum kami jadwalkan dengan peer counselor kami ya. Sehingga saat ini anda tidak bisa melakukan konseling. Dan mohon untuk selanjutnya dipastikan mendapatkan konfirmasi dari kami terlebih dahulu, mengenai penjadwalan yang Anda ajukan. Dikarenakan kami juga harus koordinasi dengan peer counselor kami. Apakah Anda berkenan memberikan kami opsi di hari lain?</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-09-11 11:36:47');
