INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12864, 3232, 102873, 'mahasiswa', 'Akbar Saputra', '<p>maaf kak saya juga slow respond karena kemarin saya coba cek jg bermasalah e-counselingnya, kalau untuk kamis saya fre dari pagi sampai sore kak kelas saya cuma di pukul 15.30, untuk hari rabu saya cuma bisa di jam 11-15.</p>', '2025-09-11 15:01:08');
