INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12923, 3326, 102961, 'mahasiswa', 'Nafisa Anandini', '<p>saya susah fokus dalam kelas, seringkali memikirkan hal lain, rasa capek yg nggak berhenti, susah mengendalikan emosi, saya sering tiba” pengen marah, sedih, tapi nggak tau kenapa, saya udah nggak ngerasa hidup lagi </p>', '2025-09-16 13:38:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12924, 3313, 102951, 'mahasiswa', 'Hilma Azmina', '<p>Apakah bisa di minggu depan hari Selasa pukul 8.00 (daring) atau Selasa pukul 9.30 (daring)? </p>', '2025-09-16 17:18:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12925, 3327, 102801, 'mahasiswa', 'Fransiska', '<ul><li>Saya masih kesulitan fokus mengerjakan skripsi karena pikiran sering teralihkan. Saya sudah berusaha membuka laptop setiap hari meski tidak selalu bisa menulis. Saya jadi merasa tertekan karena dikejar target waktu.</li><li>Saya sudah coba mengerjakan di luar rumah untuk mengganti suasana, tapi rasanya hampir sama seperti saat di rumah.</li><li>Saya belum membuat rencana setelah lulus karena masih belum menemukan tujuan yang ingin saya capai ke depannya.</li><li>Saya merasa sangat berat tapi sulit menjelaskan rasanya seperti apa. Rasanya lelah tapi saya tetap berusaha menjalani tanggung jawab yang belum selesai.</li><li>Saya merasa tidak bisa sepenuhnya menikmati aktivitas sehari-hari dan merasa bosan terhadap hal-hal yang dulu saya sukai. Saya sering merasa bersalah setiap kali merasa bahagia.</li><li>Saat berinteraksi dengan orang lain, saya merasa ragu dan setelahnya pasti merasa telah melakukan kesalahan.</li><li>Saya ingin memahami dan mengelola perasaan ini agar mampu menjalani proses akademik maupun kehidupan sehari-hari dengan lebih fokus dan tenang.</li></ul>', '2025-09-16 18:25:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12926, 3328, 102962, 'mahasiswa', 'Nesya Rahmadhani', '<p>1. tidak bisa mengikuti mata kuliah dengan baik, karena bukan minat dan skill yang saya miliki</p> <p>2. merasa bahwa salah jurusan, serta saya merasa tidak bisa mengikuti kegiatan organisasi karena terhalang tugas praktikum yang memberatkan </p> <p>3. tidak tahu tujuan kedepannya di jurusan ini</p> <p><br /></p>', '2025-09-17 07:41:17');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (12927, 3329, 102963, 'mahasiswa', 'Medina Irawan', '<p>Saya bingung, jurusan agroekoteknologi ini ga ada di list jurusan saya. Saya ingin pindah, saya ingin kembali di kota saya, dan lanjutkan mengejar jurusan impian saya. Waktu pemilihan snbp, saya milih jurusan ini karena peluang besar dan udah buntu sama semuanya. Saya ketakutan, saya merasa bersalah dengan orang tua, kalau udh di fasilitasi dengan baik malah gagal masuk ptn, jadi saya bener bener ga tahu lagi mau gimana lagi. </p>', '2025-09-17 07:44:35');
