INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13039, 3344, 102980, 'mahasiswa', 'Nadhifah Qhadriyah', '<p>akhir akhir ini sering nangis tapi gatau alasannya apa. Nangisnya udah 3 malem berturut turut tapi masih gatau alasannya (sebelum"nya kalau nangis tiap malam berturut turut tapi bisa ngebreak down masalahnya). biasanya nangis masalah pertemanan dan ideal self yg gabisa dicapai. Tapi kali ini beneran gatau alasannya apa :'') terus juga ngerasa sangat ga bertenaga kaya lelah terus dan cuma mau baring di kasur (ga ada minat buat melakukan kewajiban, kya nugas contohnya)</p>', '2025-09-21 16:49:18');
