INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13067, 3302, 102941, 'mahasiswa', 'nesa fatean', '<p>mohon maaf bu baru bisa menjawab, boleh tidak apa apa saya berkenan</p>', '2025-09-23 16:54:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13068, 3350, 102985, 'mahasiswa', 'Sheila Ikhsan', '<p>1. trauma saya sebetulnya ngga cuma satu, ada dari trauma keluarga yg berlangsung lama dan trauma hubugan masa lalu yang sebenernya udah 5 tahun. saya kira saya udah sembuh dari hal2 ini tapi ternyata saya sadar kalo saya gapernah damai sama masa lalu tersebut. saya belum bisa maafin diri saya padahal trauma itu bukan sepenuhnya salah saya. saya udah coba berbagai cara untuk damai tapi ngga pernah bener2 bisa buat damai. 2 minggu ini saya cape fisik karna lagi sibuk2nya kampus dan ditambah banyak pikiran juga jadi semuanya numpuk. mungkin triggernya adalah waktu seminggu yg lalu saya ceritain tentang masa lalu saya ke temen tapi posisinya saya juga lagi cape jadi ke trigger dan ngalamin relapse. setiap hari saya nangis dna pernah terpikir untuk menyakiti diri sendiri lagi</p> <p><br /></p> <p>2. cukup menganggu karna saya ngga nafsu makan (saya makan sehari sekali atau 2 hari sekali) dan males banget rasanya melakukan apapun, biasanya saya slalu makeupan dan pake outfit proper kalo ke kampus tapi 2 minggu ini bareface yg bahkan kadang kemeja saya ngga di setrika. saya jadi lebih menutup diri ke temen saya dan rasanya hampa, questioning my worth, ngerasa ngga good enough</p> <p>3. saya mau berdamai sama semua hal yang udah nyakitin saya. saya mau bisa belajar maafin diri saya. saya sadar kalo saya deserve untuk menjalani kehidupan yang lebih baik, tapi saya ngga tau gimana caranya....</p>', '2025-09-23 21:58:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13069, 3350, 102985, 'mahasiswa', 'Sheila Ikhsan', '<p>1. trauma saya sebetulnya ngga cuma satu, ada dari trauma keluarga yg berlangsung lama dan trauma hubugan masa lalu yang sebenernya udah 5 tahun. saya kira saya udah sembuh dari hal2 ini tapi ternyata saya sadar kalo saya gapernah damai sama masa lalu tersebut. saya belum bisa maafin diri saya padahal trauma itu bukan sepenuhnya salah saya. saya udah coba berbagai cara untuk damai tapi ngga pernah bener2 bisa buat damai. 2 minggu ini saya cape fisik karna lagi sibuk2nya kampus dan ditambah banyak pikiran juga jadi semuanya numpuk. mungkin triggernya adalah waktu seminggu yg lalu saya ceritain tentang masa lalu saya ke temen tapi posisinya saya juga lagi cape jadi ke trigger dan ngalamin relapse. setiap hari saya nangis dna pernah terpikir untuk menyakiti diri sendiri lagi</p> <p><br /></p> <p>2. cukup menganggu karna saya ngga nafsu makan (saya makan sehari sekali atau 2 hari sekali) dan males banget rasanya melakukan apapun, biasanya saya slalu makeupan dan pake outfit proper kalo ke kampus tapi 2 minggu ini bareface yg bahkan kadang kemeja saya ngga di setrika. saya jadi lebih menutup diri ke temen saya dan rasanya hampa, questioning my worth, ngerasa ngga good enough</p> <p>3. saya mau berdamai sama semua hal yang udah nyakitin saya. saya mau bisa belajar maafin diri saya. saya sadar kalo saya deserve untuk menjalani kehidupan yang lebih baik, tapi saya ngga tau gimana caranya....</p>', '2025-09-23 22:11:04');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13070, 3326, 102961, 'mahasiswa', 'Nafisa Anandini', '<p>sebelumnya mohon maaf karena baru sempat membalas, minggu kemarin sampai minggu ini saya sedang banyak ujian jadi tidak bisa mengecheck email…… kalau minggu ini kiranya apakah bisa ya? hari jumat? pagi saya kosong tidak ada jadwal kelas</p>', '2025-09-23 22:43:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13071, 3302, 25, 'admin', 'Ribby Aura', '<p>Baik, saya akan coba bantu jadwalkan sesi dengan peer konselor kami. Jika berkenan, silahkan ajukan 2 jadwal diantara hari senin-jumat pukul 08.00-15.00 WIB. Terima kasih.</p>', '2025-09-24 09:58:48');
