INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13146, 3357, 28, 'admin', 'Ishida Ayumi', '<p>Akan kami tawarkan terlebih dahulu ya kak, kepada peer counselor kami. Akan kami hubungi ketika mendapatkan peer counselor yang bersedia. Jika di hari senin, apakah di jam 10 juga ya kak?</p>', '2025-09-25 18:16:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13147, 3357, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf kak, sepertinya jika besok, tidak memungkinkan. Jika di hari senin apakah di jam 10 juga kak?</p>', '2025-09-25 18:16:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13148, 3360, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat malam, Muhammad!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail mengenai kebingungan yang Anda rasakan?</p> <p dir="ltr">2. Dari kelelahan yang Anda rasakan, apa efeknya ke kegiatan keseharian Anda? Apakah Anda merasa kehilangan motivasi?</p> <p dir="ltr">3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr">Dan untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan peer counselor kami? Jika bersedia, beri kami 2 opsi jadwal antara hari senin-jumat pukul 08.00-15.00 (daring/luring).<br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-09-25 18:22:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13149, 3359, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat malam, aashgsd.<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Untuk mengetahui permasalahan yang sedang Anda lalui, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail mengenai permasalahan yang Anda alami? Menurut Anda apa penyebab hal tersebut terjadi?</p> <p dir="ltr">2. Dari hal tersebut, apa efeknya ke kegiatan keseharian Anda? Dan apakah sudah sangat mengganggu?</p> <p dir="ltr">3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">5. Apakah Anda ingin melakukan konseling? Dan apakah Anda berkenan menyertakan identitas Anda untuk kami jadwalkan dengan peer counselor atau psikolog kami? Anda tidak perlu khawatir mengenai kerahasiaan identitas Anda, karena akan kami jamin mengenai kerahasiaannya.</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.<br /></p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-09-25 18:28:04');
