INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13169, 3356, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Akan kami koordinasikan dengan peer counselor kami terlebih dahulu. Untuk informasi selanjutnya akan kami hubungi melalui WA.</p> <p>Namun mohon maaf untuk jadwal dengan psikolog di tanggal 27 sudah terisi, apakah Anda berkenan memilih di opsi tanggal yang lain?</p>', '2025-09-27 10:10:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13170, 3356, 102994, 'mahasiswa', 'Nazwa', '<p>Baik</p> <p> Diganti pada tgl 29 oktober saja pukul 10</p>', '2025-09-27 10:14:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13171, 3356, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Akan kami jadwalkan pada tanggal tersebut.</p>', '2025-09-27 10:17:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13172, 3364, 103001, 'mahasiswa', 'Rheina Clarence', '<p>kepala terasa berat penuh dan berisik anxiety overthinking dan ngerasa ada yang salah dengan diri ini, ngerasa kehilangan arah, kehilangan diri sendiri (ngerasa berubah), kehilangan semangat hidup, sulit kontrol emosi jadi bawaannya selalu ingin menangis, selalu jadi pendengar yang baik buat orang lain tapi kalau mau nyeritain diri sendiri lebih memilih dipendam, apa yang aku rasain sekarang kerasa berat dan sulit untuk aku ceritakan ke teman atau keluarga, tapi aku aware kalau ada yang salah sama diri aku makanya butuh penanganan profesional</p>', '2025-09-27 13:32:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13173, 3365, 101450, 'mahasiswa', 'Mutiara Alafini', '<p>Saya merasa sering cemas dan selalu merasa itu terjadi karena masalah dimasa lalu, awalnya saya merasa bisa untuk mengontrol respon dengan mencoba mengubah respon terhadap hal tersebut ke arah yang lebih positif. Namun tenyata saya merasa gagal karena dampak di masa lalu itu masih terasa hingga sekarang. Alhasil saya menjadi tidak pede, selalu merasa tidak cukup, tidak bisa diterima dan akhirnya saya merasa stuck dan saya merasa ini sangat menggangu untuk saya disaat ini dan kedepannya.</p>', '2025-09-27 15:17:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13174, 3366, 102768, 'mahasiswa', 'Muhammad', '<p>Aku ngerasa hari” ku gk ada tenaga dan menarik diri dari aktivitas sosial seperti kuliah, pkkmb, dll</p>', '2025-09-27 15:58:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13175, 3367, 103003, 'mahasiswa', 'fania felichia', '<p>saya dilecehkan pacar saya berulang kali, saya juga diminta secara paksa. saya tidak mau saya selalu menolak tapi dia tetap memaksa. dia slalu mengancam akan menyebarkan, saya sangat ketakutan</p>', '2025-09-27 17:57:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13176, 3368, 103005, 'mahasiswa', 'Muhammad Mujadid', '<p>Mental saya memang lemah sejak dulu jadi sangat mudah untuk mengalami <em>pressure</em> ketika sudah dipaksa berkali kali dalam keadaan yg mengharuskan saya untuk berpikir keras dalam keadaan di tekan banyak org. Ini mulai membuat saya stress khususnya karena saya capim dan harus memikirkan kondisi teman teman saya. Permasalahan inilah yg menurut saya yg memicu lagi stress, insecure, dan depresi karena dulunya saya juga pasien dan harus selalu minum obat dari psikiater. Saya merasa hal ini mulai mengganggu kegiatan akademik saya karena di kelas saya tidak sulit aktif, tidak percaya diri, dan selalu bernegatif thinking. saya butuh sedikit saran dan konseling agar bisa melanjutkan aktivitas dengan nyaman.</p>', '2025-09-28 03:09:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13177, 3360, 102997, 'mahasiswa', 'Muhammad', '<p>saya bingung mau lanjut atau enggak di prodi ini, saya punya mimpi untuk kuliah s2 di luar negri tapi ada hal mengganjal seperti ada hal yang gak sesuai minat, entah terasa salah aja gitu. Saya hilang motivasi dan semangat untuk kuliah, ospek ini membuat saya merasa menuntut ilmu di kampus indonesia gak worth it banget, saya merasa menyesal tidak mencari informasi beasiswa kuliah ke luar negeri saat saya sma, saya merasa kenapa kita di ginikan sih bikin tidak betah untuk kuliah. Saya juga bingung harus gimana untuk mengatasi. entah lah apa yang saya harapkan. jika bisa saya ingin konsultasi dengan psikolog, tapi jika memang tidak bisa maka tidak masalah dengan peer counselar, untuk jadwal saya bisa di hari senin pukul 8.00-13.00 dan jumat pukul 13.00-15.00</p>', '2025-09-28 08:34:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13178, 3360, 102997, 'mahasiswa', 'Muhammad', '<p>untuk konsultasi saya lenih nyaman jika dilakukan dengan luring</p>', '2025-09-28 08:41:50');
