INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13235, 3379, 103014, 'mahasiswa', 'Fiona Candra', '<p>Saya maba s2, dan sejak awal saya disni, bulan september ini saya sering sekali mengalami anxiety, terutama saat saya tidak lagi minum obat dr psikiater, anxiety ini benar benar sangat menganggu saya setiap kali kuliah</p> <p>Tolong saya</p>', '2025-09-30 07:50:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13236, 3380, 103015, 'mahasiswa', 'Nakeysha Putri', '<p>saya sering merasa sedih setiap hari &amp; merasa sendirian walaupun setiap hari dikelilingi oleh teman-teman yang asik. saya gatau saya sedihin apa, apa mungkin blm sadar atau masih denial saya juga gatau, tapi sepertinya saya merasa sedih krn ortu saya gd yang nanyain kabar saya, trkdg waktu saya bangun tidur jam 7.50 untuk berangkat kuliah saya merasa sangat malas untuk bangun dari tempat tidur &amp; tidak ada motivasi untuk serius kuliah</p>', '2025-09-30 10:34:01');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13237, 3381, 103015, 'mahasiswa', 'Nakeysha Putri', '<p>saya merasa mental saya ngedrop, saya jadi malas kuliah, sedih setiap malam, dan juga malas untuk beraktivitas sehari hari, saya gatau pasti penyebabnya saya begini krn apa, tapi mungkin krn ortu saya gapernah nanyain kabar saya, dan itu agak ngelukain hati saya, krn ub ke tempat asal saya lumayan jauh, dan juga mungkin krn lingkungan baru, saya butuh waktu lebih lama untuk adaptasi krn saya gabisa langsung adaptasi secepat itu. tapi jjur keadaan kaya gini bikin akademik saya hancur, alpha udh 3 padahal saya maba</p>', '2025-09-30 10:44:57');
