INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13274, 3390, 102471, 'mahasiswa', 'Andi', '<p>kenapa diri saya sering ngerasain kosong padahal jelas-jelas didepan mata lagi mengerjakan sesuatu..</p> <p>kenapa suatu keputusan saya saat marah (diem) selalu salah? dan giliran marah yang bersuara malah dikira nyari pembelaan kenapa??? saya cape nurutin kemauan orang cape.. saya dulu dibilang terlalu lurus banget hidupnya tapi nyatanya hanya bakalan tegas di saat tertentu bukan harus tiap waktu dibawa ketawa padahal itu harus tegas</p> <p>dan kenapa diri saya suka kena badmood an teman padahal saya baru aja memulai obrolan dengan nanya baik-baik tapi kenapa saya di kena nada tinggi dia</p>', '2025-10-01 12:55:30');
