INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13309, 3394, 29, 'admin', 'Aisyah Salsa', '<p>Baik, terima kasih atas konfirmasinya akan kami alihkan ke Badan Konseling Mahasiswa FISIP UB dan akan dihubungi oleh admin Badan Konseling Mahasiswa FISIP UB.</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-10-03 11:36:32');
