INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13311, 3394, 103026, 'mahasiswa', 'Anindita Rahma', '<p>Kakak permisi. Aku sudah dapat email dari BKM FISIP UB, tapi penetapan jadwalnya gak sesuai sama jadwal yang kakak tadi sarankan.</p> <p>Dari BKM setting di jam 11.30 - 12.30, tapi kalau di jam tersebut saya masih ada kelas dan mereka juga setting sesinya jadi online. Gak sesuai dengan yang kakak bilang<br /></p>', '2025-10-03 12:10:16');
