INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13355, 3405, 103038, 'mahasiswa', 'Falisha Zahra', '<p>Saya merasa sulit menyeimbangkan waktu untuk mengerjakan laprak dan belajar untuk mata kuliah sehingga membuat saya sangat keteteran, saya sudah mengusahakan tidak menjadi deadliner dalam mengerjakan laprak namun tetap saja saya mengerjakannya h-5 jam</p>', '2025-10-05 07:11:16');
