INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13360, 3407, 103040, 'mahasiswa', 'KEYSYA', '<p>saya beberapa akhir ini susah tidur, dan aktifitas juga terganggu. tiga kali saya kehilangan, pertama saya kehilangan teman dekat saya pada kelas 11 dulu, dan saya rasa merasa ini awal dari semua trauma saya. lalu bulan mei saya kehilangan om saya, karena sakit. dan yang terakhir saya kehilangan kakek saya, yang paling dekat dengan saya sebulan yang lalu. saya trauma, takut ditinggal dan takut mati. kadang tubuh saya tiba tiba kaku dan kadang gemetar panik kalo ada orang membahas kematian, saya takutt sekali. saya sudah mencoba segala meditasi, saya sudah mencoba bercerita ke orang terdekat dan saya rasa mereka tidak akan mengerti posisi saya yang selalu dihantui kematian ini. kira kira saya harus apa? </p>', '2025-10-05 16:19:56');
