INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13421, 3427, 103054, 'mahasiswa', 'Daffa', '<p>Belakangan ini dada terasa agak sesak, mau nafas tapi ngga bisa lega. Entah karena asam lambung, pola makan atau bahkan pola istirahat. Selain itu, aku dihantui mimpi-mimpi yang berulang. Awalnya terasa menyenangkan, tapi lama kelamaan merasa dihantui. Satu hal yg aku sadari sekarang, aku butuh bantuan. </p>', '2025-10-10 08:44:33');
