INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13437, 3421, 25, 'admin', 'Ribby Aura', '<p>Mohon maaf untuk konseling dengan psikolog sesuai bidangnya tersedia  secara online saja. Apabila offline apakah mungkin kakak bersedia konseling dengan peer counselor kami? </p>', '2025-10-10 11:55:27');
