INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13452, 3406, 25, 'admin', 'Ribby Aura', '<p>Untuk konsultasi kembali bisa dilakukan melalui jadwal yang sudah dikonfirmasi antara klien dengan psikolog oleh kami kak. Untuk biaya sendiri tidak ada asalkan klien termasuk mahasiswa atau civitas Universitas Brawijaya. Apakah menjawab kak? </p>', '2025-10-11 09:57:18');
