INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13467, 3427, 25, 'admin', 'Ribby Aura', '<p>Halo, Kak Daffa. Terima kasih sudah menghubungi layanan konseling UB dan mempercayakan pada kami. Saya sangat memahami bahwa tidak mudah untuk bisa terbuka, oleh karena itu saya sangat mengapresiasi keterbukaan kakak. Mungkin bisa dibantu untuk menjawab pertanyaan kami yaa kak:</p> <p>1. Coba ceritakan sejak kapan kakak merasakan hal tersebut dan apa alasan kakak merasa kambuh? </p> <p>2. Coba ceritakan apakah selama kakak merasa kambuh, hal tersebut mengganggu kehidupan sosial kakak?</p> <p>3. Apa yang kakak harapkan dari sesi konseling ini?</p> <p>Kami tunggu jawabannya ya, Kak Daffa! Terima kasih :)</p>', '2025-10-12 07:16:19');
