INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13479, 3438, 25, 'admin', 'Ribby Aura', '<p>Terimakasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Sebelumnya mohon maaf karena baru membalas dikarenakan panjang nya antrian tiket konseling. Saya sangat memahami pasti situasi ini tidak mudah untuk dilalui. Saya mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Saya akan coba bantu jadwalkan sesi dengan peer konselor kami. Jika berkenan, silahkan ajukan 2 jadwal diantara hari senin-jumat pukul 08.00-15.00 WIB. Terima kasih.</p>', '2025-10-12 07:39:46');
