INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13485, 3423, 102598, 'mahasiswa', 'Jihan Mufidah', '<p>Karena yg ingin dikonsultasikan masalah pendidikannya di UB</p>', '2025-10-12 12:10:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13486, 3317, 102957, 'mahasiswa', 'Mochammad Syahreza', '<p>Untuk mekanisme konselingnya nanti berarti akan diberikan link meet atau zoom begitu ya, Kak?</p>', '2025-10-12 13:26:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13487, 3430, 25, 'admin', 'Ribby Aura', '<p>Halo, Kak Hanum. Terima kasih sudah menghubungi layanan konseling UB dan mempercayakan pada kami. Saya sangat memahami bahwa tidak mudah untuk bisa terbuka, oleh karena itu saya sangat mengapresiasi keterbukaan kakak. Mungkin bisa dibantu untuk menjawab pertanyaan kami yaa kak:</p> <p>1. Coba ceritakan sejak kapan kakak merasakan hal tersebut dan apa alasan kakak merasa kambuh?</p> <p>2. Coba ceritakan apakah selama kakak merasa kambuh, hal tersebut mengganggu kehidupan sosial kakak?</p> <p>3. Apa yang kakak harapkan dari sesi konseling ini?</p> <p>Kami tunggu jawabannya ya, Kak Hanum! Terima kasih :)</p>', '2025-10-12 13:42:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13488, 3434, 103060, 'mahasiswa', 'Rahma Dania', '<p>Kamis 10.00 &amp; jumat 09.00</p>', '2025-10-12 16:25:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13489, 3439, 103064, 'mahasiswa', 'Feyruz Althafunnisa', '<p>Ketika SMA saya itu mengambil kelas kesehatan dan saya tidak memiliki ketertarikan pada dunia teknik. Namun singkat cerita ketika kuliah saya mengambil jurusan teknik industri. Sebenarnya saya enjoy dengan perkuliahan saya. Namun, saya merasa kesulitan pada mata kuliah seperti MTK, Fisika, dan hitung²an lainnya. Karena ketika saya SMA itu tidak mendapatkan pembelajaran yang optimal pada mata pelajaran tersebut. Sehingga saya merasa tertinggal di perkuliahan ini, saya ingin pindah jurusan di rumpun kesehatan karena memang sebenarnya saya tertariknya disitu dan saya berfikir bahwasannya saya akan lebih menguasai disana. Tetapi jika saya harus melanjutkan kuliah di teknik juga saya hanya keberatan di mata kuliah hitung hitungan itu. Yang membuat saya sampai ingin pindah jurusan itu karena saya bisa sampai overthinking memikirkan nilai saya jika tetap lanjut di jurusan teknik ini. Jadi baiknya gimana ya? </p>', '2025-10-12 19:49:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13490, 3440, 102771, 'mahasiswa', 'Asri Nurazizah', '<p>saya selalu merasa cemas, tiap kejadian menyakitkan terus berulang (terputar) di kepala seolah itu baru terjadi kemarin, perasaan bersalah yang terus salahin diri sendiri, bisa sangat mengganggu karna membuat saya sulit fokus, susah tidur (bisa seharian gatidur), tremor, sesak, detak jantung yg lebih kencang drpd normalnya membuat saya sulit bernafas? gak nafsu makan meanwhile saya punya masalah asam lambung dan gerd. dan hal ini makin membuat parah. tanpa saya sadari saya sering self sabotage diri saya sendiri, saya menghindari semua orang (hanya orang2 yg ingin saya hub) bahkan keluarga saya sendiri. salahkah kalau saya merasa sendirian? gaada satupun yang akan bisa mengerti saya kecuali diri saya sendiri? orang lain atau bahkan keluarga sendiri hanya bisa terus2 menghakimi. saya kehilangan diri saya sendiri bahkan kata2 motivasi sudah tidak berpengaruh apapun. saya merasa gapantas ngerasain bahagia? ngerasa gagal dalam hal apapun. tiap ada kebahagiaan saya lebih baik menghindarinya. semakin saya merasa tertekan semakin saya diam dan menutup rapat2 diri saya dari siapapun. bahkan dari kedua orang tua saya. saya bingung harus apa? telfon dari orang rumah berasa ancaman buat saya? saya cuma mau ngerasain tenang yang gapernah benar benar stay lama. saya selalu diepenuhi ketakutan kecewa dan rasa beraalah saya. </p>', '2025-10-12 22:15:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13491, 3317, 25, 'admin', 'Ribby Aura', '<p>Benar kak, untuk konseling online nantinya akan dikirimkan link yaa</p>', '2025-10-12 22:37:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13492, 3439, 25, 'admin', 'Ribby Aura', '<p>Terimakasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Sebelumnya mohon maaf karena baru membalas dikarenakan panjang nya antrian tiket konseling. Saya sangat memahami pasti situasi ini tidak mudah untuk dilalui. Saya mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Saya akan coba bantu jadwalkan sesi dengan peer konselor kami. Jika berkenan, silahkan ajukan 2 jadwal diantara hari senin-jumat pukul 08.00-15.00 WIB. Terima kasih.</p>', '2025-10-12 22:38:20');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13493, 3440, 25, 'admin', 'Ribby Aura', '<p>Terimakasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Sebelumnya mohon maaf karena baru membalas dikarenakan panjang nya antrian tiket konseling. Saya sangat memahami pasti situasi ini tidak mudah untuk dilalui.  Kami memberikan opsi jika ingin mendapatkan jadwal lebih cepat, apakah anda berkenan untuk melakukan konseling bersama tenaga profesional/psikolog yang ada di Badan Konseling Mahasiswa FISIP UB dikarenakan jadwal konseling kami sudah penuh hingga akhir oktober. Untuk tenaga profesional/psikolog kami sama ya dengan Badan Konseling Mahasiswa FISIP UB.</p>', '2025-10-12 22:42:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13494, 3423, 25, 'admin', 'Ribby Aura', '<p><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit">Baik kak, apakah kakak masih memiliki SIAM dan untuk status mahasiswa kakak sendiri di SIAM apakah mahasiswa aktif kak? </span></span></p> <p><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit">Kami tunggu responnya kak... </span></span></p>', '2025-10-12 22:45:01');
