INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13578, 3452, 28, 'admin', 'Ishida Ayumi', '<p>Selamat pagi Ahmad. Terima kasih telah menghubungi layanan kami. Untuk jadwal dengan Bu Yunita baru tersedia di bulan depan pada hari Rabu, 12 November 2025 pukul 09.00. Apakah Anda bersedia untuk menunggu?</p> <p dir="ltr"><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-10-15 09:20:25');
