INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (13584, 3387, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Akan kami koordinasikan terlebih dahulu dengan peer counselor kami. Untuk informasi selanjutnya akan kami informasikan melalui WA.</p>', '2025-10-15 10:13:54');
