INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14014, 3539, 103094, 'mahasiswa', 'Muhammad', '<p>Saya merasa sedih berkelanjutan, karena diputuskan hubungan 3 tahun, lalu ia sudah memiliki yang baru dalam jangka waktu kurang dari sebulan, saya merasa seperti 3 tahun itu tidak ada artinya untuknya, sekarang setiap kali saya melihat barang yang ia kasih, atau tempat yang sering kami tujui, rasanya sakit dan membuat saya tidak mood melakukan apapun.</p>', '2025-11-07 23:46:49');
