INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14020, 3541, 103147, 'mahasiswa', 'Arnando', '<p>saya gatau mau mengarahkan diri kemana, tuntutan dmna mna yang mengharuskan saya buat terus ada di sini dimna ini bukan minat saya dmna saya juga ngerasa mulai kehilangan minat dalam berbagai hal dari hobi hingga hal hal baru berberapa tahun ini, saya selalu ngerasa selalu ngebebanin orn lain dengan keadaan saya, saya selalu ingin ngga ada aja di dunia tiap saya ngerasa gabisa mecahin masalah saya, ngerasa bersalah, selalu menjadi beban, saya ngerasa kehilangan jati diri </p>', '2025-11-08 17:52:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14021, 3542, 103147, 'mahasiswa', 'Arnando', '<p>sulit sekali rasanya bertahan hidup di tuntutan untuk mempertahankan diri sendiri disini, dmna seharusnya ini bukan passion saya, saya mempelajari hal yang bukan passion saya, saya ngerasa banyak beban tiap hari saya membunuh diri saya sendiri di pikiran saya</p>', '2025-11-08 18:03:46');
