INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14072, 3518, 27, 'admin', 'Shafhah Raisha', '<p>Jika di tanggal 18 November pukul 09.00 secara offline apakah berkenan, Kak?</p>', '2025-11-10 20:34:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14073, 3309, 27, 'admin', 'Shafhah Raisha', '<p>Baik, terima kasih konfirmasinya ya, Kak. Informasi selanjutnya akan disampaikan melalui WhatsApp :)</p>', '2025-11-10 20:36:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14074, 3514, 27, 'admin', 'Shafhah Raisha', '<p>Mohon maaf sebelumnya, namun di waktu tersebut tidak ada jadwal konseling yang tersedia. Apakah berkenan jika melakukan konseling dengan psikolog kami di hari Kamis, 27 November pukul 09.00?</p>', '2025-11-10 20:39:51');
