INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14076, 3529, 27, 'admin', 'Shafhah Raisha', '<p>Bisa secara online, Kak. Baik, akan kami carikan jadwal dengan peer counselor kami terlebih dahulu ya, kak. Informasi selanjutnya akan disampaikan melalui WhatsApp. Terima kasih :)</p>', '2025-11-10 20:43:02');
