INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14117, 3553, 27, 'admin', 'Shafhah Raisha', '<p>Baik, terima kasih konfirmasinya ya, Kak. Informasi selanjutnya akan disampaikan melalui WhatsApp :))</p>', '2025-11-12 17:21:44');
