INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14120, 3447, 27, 'admin', 'Shafhah Raisha', '<p>Mohon maaf, Kak. Untuk konseling secara online, jadwal kami baru tersedia di hari Senin, 1 Desember pukul 14.00. Apakah sekiranya berkenan dijadwalkan di waktu tersebut?</p>', '2025-11-12 17:33:07');
