INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14122, 3540, 103146, 'mahasiswa', 'Gilang Faqih', '<p>Saya ingin konseling pada hari Jumat jam 8 pagi yaa terima kasiih </p>', '2025-11-12 19:50:13');
