INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14197, 3566, 26, 'admin', 'Nadia Aura', '<p>Mohon maaf kak sebelumnya, jika di hari Jumat apakah berkenan online?</p>', '2025-11-18 03:22:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14198, 3561, 103166, 'mahasiswa', 'Joice Manik', '<p>Baik ka, saya bisa pada :</p><ol><li>Hari Kamis pada pukul 12.00 secara daring</li><li>Hari Jumat pada pukul 13.00 secara daring</li></ol> <p>Terima kasih ka. </p>', '2025-11-18 05:17:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14199, 3561, 26, 'admin', 'Nadia Aura', '<p>Baik kak, terima kasih responnya. Kami coba carikan jadwal di waktu tersebut ya, apabila sudah menemukan jadwal akan kami hubungi kembali melalui whatsapp.</p>', '2025-11-18 08:17:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14200, 3562, 26, 'admin', 'Nadia Aura', '<p>Baik, terima kasih atas responnya. tetapi mohon maaf kak, jika di hari rabu secara offline terakhir jadwal ada di jam 15.00 ya, kemudian untuk hari jumat apakah berkenan jika secara online?</p>', '2025-11-18 08:22:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14201, 3570, 26, 'admin', 'Nadia Aura', '<p>Baik Rizki, terima kasih sudah menghubungi layanan konseling UB. Jika suatu saat dirasa membutuhkan lagi, silakan untuk menghubungi kami yaa.</p>', '2025-11-18 08:23:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14202, 3571, 103176, 'mahasiswa', 'Hanif Swastika', '<p>Saya mengalami masalah keluarga, dan permasalahan ini sudah 2-3 tahun tidak menuai jalan keluar dan menghambat saya menulis tesis, jadi tidak termotivasi. </p>', '2025-11-18 08:40:24');
