INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14250, 3579, 103184, 'mahasiswa', 'Jacobus', '<p>Baik terima kasih </p>', '2025-11-20 15:09:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14251, 3532, 28, 'admin', 'Ishida Ayumi', '<p>Tidak apa-apa kak, Anda tidak perlu meminta maaf. Terima kasih telah merespon balasan dari kami. Mohon maaf untuk jadwal dengan psikolog maupun konselor profesional sudah penuh di bulan ini dan baru tersedia pada:</p> <p>- Selasa, 2 Desember 2025 pukul 19.00 (online)</p> <p>- Rabu, 3 Desember 2025 pukul 19.00 (online)</p> <p>- Jumat, 5 Desember 2025 pukul 19.00 (online)</p> <p>Apakah Anda berkenan untuk menunggu?</p> <p><br /></p> <p>Kami tunggu konfirmasinya,</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-11-20 15:16:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14252, 3581, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat sore, Hanif!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, kami menyarankan Anda melakukan konseling dengan psikolog klinis kami. Namun, mohon maaf jadwal psikolog kami sudah penuh hingga minggu pertama Desember, dan baru tersedia pada:</p> <p dir="ltr">- Rabu, 10 Desember 2025 pukul 09.00 (Daring/Luring)</p> <p dir="ltr">- Rabu, 10 Desember 2025 pukul 10.00 (Daring/Luring)</p> <p dir="ltr">- Kamis, 11 Desember 2025 pukul 13.00 (Daring/Luring)</p> <p dir="ltr">Apakah Anda bersedia untuk menunggu? Jika bersedia, pilih salah satu dari opsi jadwal yang diberikan.<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-11-20 15:23:26');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14253, 3578, 28, 'admin', 'Ishida Ayumi', '<p><br /></p> <p dir="ltr">Baik, terima kasih atas konfirmasinya. Untuk informasi selanjutnya akan kami hubungi melalui WA.</p> <p><br /></p> <p><br /></p>', '2025-11-20 15:24:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14255, 3578, 28, 'admin', 'Ishida Ayumi', '<p><br />Baik, terima kasih atas konfirmasinya. Akan kami koordinasikan dengan peer counselor kami terlebih dahulu. Untuk informasi selanjutnya akan kami hubungi melalui WA.<br /><br /></p>', '2025-11-20 15:24:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14256, 3578, 28, 'admin', 'Ishida Ayumi', '<p>Untuk nomor hpnya berapa ya kak? Karena akan kami hubungi melalui WA. Berdasarkan profil Anda isi no hpnya berisi NIM .</p>', '2025-11-20 15:28:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14257, 3580, 28, 'admin', 'Ishida Ayumi', '<p>Untuk pelayanannya bisa berdasarkan kebutuhan Anda ya kak, jika Anda merasa tidak perlu bisa disampaikan saja pada form pengaduan yang Anda ajukan. Bisa langsung mendaftar ke satgas PPKS saja ya kak. Terima kasih.</p>', '2025-11-20 15:30:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14259, 3580, 28, 'admin', 'Ishida Ayumi', '<p>Untuk pelayanannya bisa berdasarkan kebutuhan Anda ya kak, jika Anda merasa tidak perlu bisa disampaikan saja pada form pengaduan yang Anda ajukan. Dan untuk kerahasiaannya pasti dijamin juga oleh satgas PPKS ya kak. Bisa langsung mendaftar ke satgas PPKS saja ya kak. Terima kasih.</p>', '2025-11-20 15:30:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14260, 3582, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat sore, Rizky!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:<br /></p> <p dir="ltr">1. Dari hal yang Anda rasakan, apa efeknya ke kegiatan keseharian Anda? Dan apakah sudah sangat mengganggu?</p> <p dir="ltr">2. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">3. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr">Dan untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami pada tanggal 25 November 2025 pukul 09.00 (<em>online/offline</em>)?</p> <p dir="ltr"><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p> <p><br /></p>', '2025-11-20 15:34:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14261, 3583, 28, 'admin', 'Ishida Ayumi', '<p>Sudah dijawab pada e-ticket yang lain.</p>', '2025-11-20 15:34:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14262, 3584, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat sore, Tasya!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Beberapa diagnosis tersebut Anda dapatkan kapan?</p> <p dir="ltr">2. Dari hal-hal yang Anda rasakan, apa efeknya ke kegiatan keseharian Anda? Dan apakah sudah sangat mengganggu?</p> <p dir="ltr">3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.<br /></p> <p dir="ltr">Kami menyarankan Anda melakukan konseling dengan psikolog klinis kami. Namun, mohon maaf jadwal psikolog kami sudah penuh hingga minggu pertama Desember, dan baru tersedia pada:</p> <p dir="ltr">- Rabu, 10 Desember 2025 pukul 09.00 (Daring/Luring)</p> <p dir="ltr">- Rabu, 10 Desember 2025 pukul 10.00 (Daring/Luring)</p> <p dir="ltr">- Kamis, 11 Desember 2025 pukul 13.00 (Daring/Luring)</p> <p dir="ltr">Apakah Anda bersedia untuk menunggu? Jika bersedia, pilih salah satu dari opsi jadwal yang diberikan.<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2025-11-20 15:38:04');
