INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14293, 3589, 103191, 'mahasiswa', 'Giska Maulidya', '<p>self esteem rendah gara gara keluarga, banyak hal buruk yang baru saya tahu akhir akhir ini dari keluarga saya.</p>', '2025-11-22 19:51:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14294, 3574, 103181, 'mahasiswa', 'Glenda Dien', '<p>Halo kak, maaf aku baru balas. Karena baru ada waktu untuk cek email lagi, baik kak aku berkenan kok. Untuk tempatnya nanti dimana ya?</p>', '2025-11-23 04:54:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14295, 3589, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat pagi, Giska!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail mengenai penyebab self esteem Anda menjadi rendah? </p> <p dir="ltr">2. Dari hal yang Anda alami, apa efeknya ke kegiatan keseharian Anda? Dan apakah sudah sangat mengganggu?</p> <p dir="ltr">3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr"><br /></p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-11-23 08:08:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14296, 3574, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf kak, untuk jadwal tersebut sudah tidak tersedia. Jadwal baru tersedia kembali pada tanggal 2 Desember 2025. Untuk jadwal terdekat yang tersedia yaitu pada hari Selasa/Rabu/Jumat pukul 19.00 dilakukan secara online bersama konselor profesional kami kak bukan dengan psikolog. </p> <p>Kami tunggu konfirmasinya,</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-11-23 10:02:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14297, 3590, 103192, 'mahasiswa', 'Gea', '<p>Assalamualaikum, saya gea okta, mahasiswa dari Fakultas Teknologi Pertanian, Prodi Teknik Lingkungan. Bapak/Ibu saya habis terkena musibah penipuan, dan itu semua adalah dana saya untuk satu tahun kedepan, semua dana tersebut adalah tabungan dari uang beasiswa saya. Saya sudah mencari pinjaman ke sanak saudara tapi tidak ada yang mau membantu saya. Saya harus gimana pak/bu, orang tua saya hanya petani dan buruh serabutan, uang terakhir yang di kirim orangtua saya juga raib di jarah penipu. Rasanya saya bingung dan ga tau mau gimana lagi. Saya jadi males kuliah juga karena hopeles bisa melewati semester besok, apalagi butuh laptop. uang tersebut juga untuk tambahan beli laptop di semester 2. Saya udah di tahap pasrah, yang di pikiran saya solusinya juma pinjol. Akademik saya juga tergangu, karena masalah ini. Saya ga bisa keluar kost karena menghemat energi saya, karena saya makan cuma sehari sekali. </p> <p>Kasus ini juga sudah saya laporkan ke polresta malang kota, namun yang pasti juga dana saya tidak akan bisa kembali. Saya takut bilang orang tua saya, karena ini kesalahan saya yang kurang aware sedari awal. Saya harus gimana bapak/ibu. Sedangkan besok sudah bulan desember dan saya juga butuh uang buat tiket balik atau bertahan hidup di rantauan ini.</p>', '2025-11-23 14:10:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14298, 3591, 103180, 'mahasiswa', 'Wafa Aulia', '<p>Sebelumnya, saya adalah orang yang dianggap berani menegur orang, atau sekedar mengingatkan kesalahan orang lain (teman), beberapa teman yg tidak menyukai saya menganggap omongan saya terlalu membuat sakit hati. lambat laun, saya semakin berfikir dan berusaha memperbaiki diri dan memikirkan setiap perkataan yang keluar dari mulut saya. saat kuliah, saya bertemu teman dengan berbagai macam watak dan sifat. karena komitmen diri saya untuk menjaga setiap ucapan saya agar tidak ada masalah yang timbul, saya justru semakin merasa bahwa saya terlalu memikirkan perasaan orang lain tanpa mementingkan perasaan saya sendiri. beberapa watu terakhir juga terdapat masalah terkait rencana PKL saya yang hingga saat ini belum ada kepastian dan membuat saya sedikit tertekan. seharusnya, bulan desember nanti saya sudah sempro untuk PKL namun karena beberapa masalah ini, akademik saya terhambat, saya jadi semakin mengisolasi diri, menutup diri dari orang lain. saya hanya ingin konsultasi atau bercerita, karena saya merasa akhir" ini hidup terlalu berat untuk saya. </p>', '2025-11-23 18:04:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14299, 3591, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat malam, Wafa!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan peer counselor kami? Jika Anda bersedia melakukan konseling dengan peer counselor kami, beri kami 2 opsi jadwal antara hari senin-jumat pukul 08.00-15.00 (daring/luring).</p> <p dir="ltr"><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-11-23 19:42:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14300, 3590, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat malam, Gea!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan konselor profesional kami? Berikut opsi jadwal yang dapat Anda pilih:</p> <p dir="ltr">- Selasa, 25 November 2025 pukul 19.00</p> <p dir="ltr">- Rabu, 26 November 2025 pukul 19.00</p> <p dir="ltr">- Jumat, 28 November 2025 pukul 19.00<br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-11-23 19:47:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14301, 3591, 103180, 'mahasiswa', 'Wafa Aulia', '<p>Apakah saya bisa menjadwalkan besok senin tanggal 24 november antara jam 11.00-15.00, untuk konsultasi luring</p>', '2025-11-23 19:48:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14302, 3591, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf kak, minimal penjadwalan H-2 sebelum waktu yang diajukan. Apakah bisa beri kami opsi di hari lain?</p>', '2025-11-23 21:03:25');
