INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14304, 3573, 101414, 'mahasiswa', 'Maura Septianingtias', '<p>Halo maaf malam", dijawab besok saja gapapa, beberapa kali saya membatalkan konseling, sebenarnya saya mau tp saya takut kenal dengan konselornya  </p>', '2025-11-23 22:31:28');
