INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14323, 3584, 27, 'admin', 'Shafhah Raisha', '<p>Mengenai pelaksanaan konseling sudah disampaikan melalui WhatsApp ya, Kak. Mungkin bisa dicoba untuk dialihkan perhatiannya ke hal hal yang menyenangkan, Kak, agar keinginan untuk menyakiti diri sendirinya bisa berkurang. </p>', '2025-11-25 10:53:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14324, 3594, 27, 'admin', 'Shafhah Raisha', '<p dir="ltr">Selamat pagi, Gabriella!</p> <p dir="ltr">Terima kasih karena telah menghubungi Layanan Konseling UB. Mohon maaf baru membalas. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan peer counselor kami? Jika Anda bersedia melakukan konseling dengan peer counselor kami, beri kami 2 opsi jadwal antara hari senin-jumat pukul 08.00-15.00 (daring/luring).</p> <p dir="ltr"><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2025-11-25 10:54:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14325, 3574, 27, 'admin', 'Shafhah Raisha', '<p>Mohon maaf untuk jadwal hari Jumat pukul 19.00 secara online baru tersedia lagi di tanggal 12 Desember, Kak. Apakah berkenan di waktu tersebut?</p>', '2025-11-25 10:56:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14326, 3595, 27, 'admin', 'Shafhah Raisha', '<p dir="ltr">Selamat pagi, Iqbal!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Mohon maaf baru membalas. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan peer counselor kami? Jika Anda bersedia melakukan konseling dengan peer counselor kami, beri kami 2 opsi jadwal antara hari senin-jumat pukul 08.00-15.00 (daring/luring).</p> <p dir="ltr"><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2025-11-25 10:57:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14327, 3600, 103199, 'mahasiswa', 'Hudaea', '<p>Saya ingin melakukan konseling karena akhir-akhir ini saya merasa mudah tertekan secara emosional, terutama ketika berhubungan dengan orang terdekat yang sering memendam perasaan dan tidak mengungkapkan apa yang sedang ia rasakan. Kondisi tersebut membuat saya sering merasa cemas, bingung, dan overthinking, sampai berdampak pada fokus dan kegiatan harian saya. Saya sadar bahwa saya mulai terbebani oleh pola komunikasi yang tidak jelas, dan saya ingin belajar cara mengelola emosi, menenangkan pikiran, serta membangun batasan yang sehat agar saya tidak terus merasa tertekan oleh ketidakpastian. Saya tidak sedang merasa depresi, tetapi saya merasa stres dan butuh bantuan profesional untuk memahami perasaan saya dan menemukan cara yang lebih sehat dalam menghadapi situasi ini.</p> <p><br /></p>', '2025-11-25 12:49:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14328, 3562, 102550, 'mahasiswa', 'Salwa', '<p>Di hari Kamis kak, jam 9 sama Jumat di jam 1 siang</p>', '2025-11-25 14:23:34');
