INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14345, 3476, 27, 'admin', 'Shafhah Raisha', '<p>Mohon maaf, Kak. Namun, untuk saat ini jadwal di tanggal 26 November sudah tidak lagi tersedia. Kami baru memiliki jadwal yang available lagi di tanggal 17 Desember. Apakah berkenan jika dijadwalkan di waktu tersebut? </p>', '2025-11-25 18:43:24');
