INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14427, 3427, 29, 'admin', 'Aisyah Salsa', '<p>Baik, terima kasih atas konfirmasinya ya. Konseling dilaksanakan pada <strong>Rabu, 17 Desember 2025 pukul 10.00 WIB</strong>, bertempat di <strong>Ruang Konseling, Layanan Konseling UB (Gedung Rektorat Lantai 1)</strong>. Informasi lebih lanjut akan kami sampaikan melalui WhatsApp, ya.</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-11-30 15:16:25');
