INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14429, 3611, 29, 'admin', 'Aisyah Salsa', '<p>Baik, terima kasih atas konfirmasinya ya. Konseling dilaksanakan pada <strong>Senin, 01 Desember 2025 pukul 13.00 WIB</strong>, bertempat di <strong>Ruang Konseling, Layanan Konseling UB (Gedung Rektorat Lantai 1)</strong>. Informasi lebih lanjut akan kami sampaikan melalui WhatsApp, ya.</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-11-30 15:21:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14430, 3601, 29, 'admin', 'Aisyah Salsa', '<p>Baik, terima kasih atas konfirmasinya ya. Konseling dilaksanakan pada <strong>Kamis, 11 Desember</strong><strong> 2025 pukul 09.00 WIB</strong>, bertempat di <strong>Ruang Konseling, Layanan Konseling UB (Gedung Rektorat Lantai 1)</strong>. Informasi lebih lanjut akan kami sampaikan melalui WhatsApp, ya.</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-11-30 15:25:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14431, 3569, 29, 'admin', 'Aisyah Salsa', '<p>Mohon maaf kak untuk jadwal tersebut dengan psikolog kami sudah terisi. Apakah berkenan jika kami jadwalkan dengan psikolog kami pada Kamis, 18 Desember 2025 pukul 09.00?</p> <p dir="ltr">Jika waktu tersebut terlalu lama, kami juga bisa menjadwalkan Anda dengan peer counselor kami yang memiliki jadwal lebih fleksibel. Apakah Anda bersedia melakukan konseling dengan peer kami terlebih dahulu? Jika Anda bersedia melakukan konseling dengan peer counselor kami, beri kami 2 opsi jadwal antara hari senin-jumat pukul 08.00-15.00.<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2025-11-30 15:28:13');
