INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14434, 3621, 103212, 'mahasiswa', 'Ammara Ghaisan', '<p>duh malu sbnrnya, cmn ini real sakit bgt kak. sy br pacaran pertama kali, DAN SAKIT BGT??? jujur aja dia ga macem2, cmn kadang pgn gt bisa lebih. lebih disayang, lebih diperhatiin. kyk, sy sadar hubungan emg ga sempurna, tp kok rasanya ga ikhlas ya. sy jg ngerasa dia ga worth it2 amat buat dipikirin sebegininya. saya punya kesibukan, punya hal lain yg disukain, tp kok mikirinnya dia mulu anjir capek bgt. gimana biar ga kyk gini...alay....sy bs nangis 2 minggu nonstop. hrs komunikasi, iya bener, tp gatau gabisa aja. kyk aku selalu milih buat nahan. krn takut. gt dulu deh tkt makin alay.</p>', '2025-11-30 22:27:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14435, 3622, 103213, 'mahasiswa', 'PIPING PARDIANNANTI', '<p>Orangtua kurang memahami betapa sulitnya pendidikan profesi dokter gigi (mencari pasien, pasien tbtb tidak kooperatif, keterbatasan sarana prasarana dll), pasien menganggap requirement koas 2-3x datang selesai, ketika saya menjawab secara yg benar selalu dijawab “kamu jangan ngebantah dulu” padahal saya sudah jelaskan bagaimana faktanya dan ini terjadi sering. Disisi lain kami juga sedikit kesulitan dalam membayar biaya UKT. Saya sudha berusaha untuk mengejar lulus cepat tapi banyak faktor X yang berperan.</p>', '2025-11-30 22:37:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14436, 3623, 103214, 'mahasiswa', 'Muhammad Ranjana', '<p>Beberapa hari yang lalu, saya terkejut melihat Orang yang saya anggap spesial melakukan Foto bareng bersama teman dekat saya sendiri. Itu membuat saya shock berat. Dan ketika saya meminta penjelasan terhadap orang yang anggap spesial ini, dia bilang, selama ini dia tidak bisa menganggap saya lebih dari sekedar teman. Dan itu membuat saya benar2 hancur. Saya merasa selama ini memiliki ikatan yang lebih spesial dari teman dan semua ini membuat saya kecewa. Saya memutuskan untuk cut off teman dekat saya yang tadi.</p>', '2025-12-01 06:27:56');
