INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14466, 3613, 27, 'admin', 'Shafhah Raisha', '<p>Baik, kami akan jadwalkan Anda di hari Selasa, 9 Desember pukul 19.00 secara online ya, Kak. Informasi selanjutnya akan disampaikan melalui WhatsApp. Terima kasih</p>', '2025-12-02 18:51:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14467, 3628, 27, 'admin', 'Shafhah Raisha', '<p>Selamat malam, Amrina!</p> <p><br /></p> <p>Terima kasih sudah berbagi cerita kepada Layanan Konseling UB mengenai perasaan tidak enak yang sedang kamu alami. Kami memahami kondisi ini tentu menimbulkan kebingungan dan perasaan tidak nyaman bagi kamu.</p> <p><br /></p> <p>Terkait dengan perasaan dan pengalaman yang Anda alami, apakah anda berkenan untuk melakukan konseling bersama peer counselor kami. Jika berkenan dapat memilih jadwal yang kosong diantara hari Senin-Jum''at pukul 09.00-14.00.</p> <p><br /></p> <p>Kami tunggu konfirmasinya yaa...</p> <p><br /></p> <p>Terima kasih</p> <p><br /></p> <p>Salam hangat,</p> <p><br /></p> <p>Tim Konseling UB</p>', '2025-12-02 18:52:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14468, 3618, 27, 'admin', 'Shafhah Raisha', '<p>Untuk jadwal Bu Bona baru tersedia di tanggal 24 Desember ya, Kak. Apakah berkenan?</p>', '2025-12-02 18:53:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14469, 3629, 27, 'admin', 'Shafhah Raisha', '<p>Selamat malam, Almira. Mohon maaf baru memberikan balasan. Untuk jadwal Bu Bona baru tersedia lagi di tanggal 24 Desember, Kak. Apakah Anda berkenan dijadwalkan pada waktu tersebut?</p>', '2025-12-02 18:54:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14470, 3184, 27, 'admin', 'Shafhah Raisha', '<p>Kami carikan jadwal yang tersedia terlebih dahulu ya, Kak. Nanti akan disampaikan melalui WhatsApp</p>', '2025-12-02 18:55:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14471, 3631, 27, 'admin', 'Shafhah Raisha', '<p>Selamat malam Syahvira! </p> <p>Terima kasih telah menghubungi Layanan Konseling UB dan mohon maaf baru memberikan respon. Mengenai jadwal dengan psikolpg profesional kami baru tersedia di tanggal 22 Desember pukul 14.00 secara online, Kak. Apakah berkenan?</p>', '2025-12-02 18:58:20');
