INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14488, 3427, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf kak, karena ada klien lain yang resched, jadwal antara jam tersebut sudah terisi. Jika diantara jam 08.00-10.30, apakah Anda bisa diantara jam tersebut? Dan apakah Anda bisa memberikan nomor WA Anda kepada kami? karena kami tidak bisa menemukan nomor Anda di WA. Konfirmasi lanjutannya akan kami berikan melalui WA. </p>', '2025-12-03 12:47:40');
