INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14507, 3641, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat pagi, Erich!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan psikolog kami? Kami cek sebelumnya Anda sudah pernah melakukan konseling dengan Bu Bona. Apakah Anda ingin dijadwalkan dengan Bu Bona kembali atau dengan psikolog lain? Untuk jadwal Bu Bona baru tersedia pada tanggal 17 Desember 2025 pukul 10.00. Untuk jadwal dengan psikolog lain yang terdekat ada di hari Senin, 8 Desember 2025 antara pukul 12.00-14.30.</p> <p dir="ltr"><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-12-04 09:13:22');
