INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14516, 2801, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf baru membalas. Website kami error dalam beberapa hari kebelakang. Baik, terima kasih atas konfirmasinya. Bisa hubungi kami kapan saja ya kak jika Anda merasa membutuhkan konseling.</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB. </p>', '2025-12-04 09:22:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14517, 3427, 28, 'admin', 'Ishida Ayumi', '<p>Selamat pagi kak, saya izin mengonfirmasi kembali. Bagaimana jika diantara jam 08.00-10.30, apakah Anda bisa diantara jam tersebut? </p> <p>Dan apakah Anda bisa memberikan nomor WA Anda kepada kami? karena kami tidak bisa menemukan nomor Anda di WA. Konfirmasi lanjutannya akan kami berikan melalui WA. </p>', '2025-12-04 09:42:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14518, 3595, 28, 'admin', 'Ishida Ayumi', '<p>Selamat pagi Iqbal. Mohon maaf baru membalas dikarenakan beberapa hari kemarin website kami error, sehingga jawaban Anda baru muncul di website kami. Dikarenakan psikolog baru kami sudah mulai bertugas di minggu dpean, untuk jadwal terdekat ada di hari Selasa, 9 Desember 2025 antara pukul 08.00-14.30.</p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2025-12-04 09:44:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14519, 3620, 28, 'admin', 'Ishida Ayumi', '<p>Sudah dibalas di e-ticket lainnya.</p>', '2025-12-04 09:46:29');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14520, 3618, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf baru membalas dikarenakan website kami sempat error beberapa hari yang lalu. Setelah kami cek kembali, tanggal terdekat ada di tanggal 17 Desember 2025 pukul 09.00 untuk jadwal dengan Bu Bona kak. Apakah Anda bersedia kami jadwalkan pada tanggal tersebut?</p> <p>Kami tunggu konfirmasinya yaa.<br />Terima kasih,<br />Salam hangat,<br />Tim Konseling UB.</p>', '2025-12-04 09:48:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14521, 3624, 28, 'admin', 'Ishida Ayumi', '<p>Sudah dijawab pada e-ticket yang lain.</p>', '2025-12-04 09:50:57');
