INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14546, 3648, 103129, 'mahasiswa', 'Quisha Putri', '<p>Saya dapat tindakan pelecehan seksual yang dilakukan teman saya ketika semester 2, skrg saya sudah semester 3 namun saya masih trauma hingga sering ke trigger. Bahkan ketika ke trigger, saya selalu nangis berlarut-larut, ketika sudah selesai nangis, saya pasti setres yang berkelanjutan. Saya gatau harus gimana lagi, saya kira bisa melalui nya sendiri, tpi saya sudah lelah</p>', '2025-12-04 16:40:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14547, 3635, 103219, 'mahasiswa', 'Fauza Zahrani', '<p>Selamat malam kak,<br />Terima kasih atas balasannya. Sehubungan dengan pengambilan jadwal konseling, Saya hendak mengonfirmasi bahwa Saya akan mengambil jadwal pada hari Jum''at, 5 Desember 2025 pada pukul 08.00 WIB. <br />Terima kasih.<br /></p> <p>Salam hangat<br /></p> <p>Fauza Zahrani.</p>', '2025-12-04 18:25:04');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14548, 3635, 103219, 'mahasiswa', 'Fauza Zahrani', '<p>Selamat malam kak,<br />Terima kasih atas balasannya. Sehubungan dengan pengambilan jadwal konseling, Saya hendak mengonfirmasi bahwa Saya akan mengambil jadwal pada hari Jum''at, 5 Desember 2025 pada pukul 08.00 WIB. <br />Terima kasih.<br /></p> <p>Salam hangat<br /></p> <p>Fauza Zahrani.</p>', '2025-12-04 18:25:12');
