INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14554, 3639, 28, 'admin', 'Ishida Ayumi', '<p>Selamat malam Zuhrotul.<br />Terima kasih karena telah mengubungi Layanan Konseling UB. Mohon maaf karena website kami error dalam beberapa hari terakhir sehingga e-ticket Anda baru muncul di kami.</p> <p>Apa yang Anda butuhkan saat ini, apakah Anda perlu kami jadwalkan konseling lanjutan dengan Bu Yunita. Untuk jadwal terdekat dengan Bu Yunita baru tersedia pada tanggal 17 Desember 2025 pukul 09.00.</p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p> <p><br /></p>', '2025-12-04 19:53:46');
