INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14556, 3637, 28, 'admin', 'Ishida Ayumi', '<p>Selamat malam, Azzahrah!</p> <p>Terima kasih karena telah mengubungi Layanan Konseling UB. Mohon maaf karena website kami error dalam beberapa hari terakhir sehingga e-ticket Anda baru muncul di kami. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan psikolog kami pada minggu depan antara hari senin-jumat pukul 08.00-14.30. Beri kami 2 opsi dengan waktu yang spesifik.</p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-12-04 20:05:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14557, 3614, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Untuk informasi selanjutnya akan kami hubungi melalui WA.</p>', '2025-12-04 20:06:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14558, 3640, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat malam, Titis!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Mohon maaf dikarenakan website kami error dalam beberapa hari terakhir e-ticket Anda baru muncul di website kami. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail ha yang sedang Anda alami? Menurut Anda apa penyebab hal tersebut terjadi?</p> <p dir="ltr">2. Dari yang Anda rasakan, apa efeknya ke kegiatan keseharian Anda? Dan apakah sudah sangat mengganggu?</p> <p dir="ltr">3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.<br /></p> <p dir="ltr"><br /></p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-12-04 20:14:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14559, 3476, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Dikarenakan psikolog baru kami sudah mulai bertugas di minggu depan, untuk jadwal terdekat sudah tersedia di antara hari senin-jumat pukul 09.00-14.30. Jika Anda bersedia, beri kami 2 opsi dengan waktu yang spesifik ya. <br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-12-04 20:20:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14560, 3637, 103222, 'mahasiswa', 'Azzahrah Shabrina', '<p>saya bisa dari hari senin-jumat di jam 11.00-14.00 selain hari kamis diminggu depan,  terima kasih.</p>', '2025-12-04 20:26:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14561, 3627, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Akan kami jadwalkan pada hari Rabu, 10 Desember 2025 pukul 08.00 ya kak. </p>', '2025-12-04 20:28:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14562, 3633, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">aik, terima kasih atas jawaban yang diberikan. Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Jika Anda bersedia, beri kami 2 opsi jadwal antara hari senin/kamis/jumat pukul 08.00-14.30 (beri kami waktu yang spesifik).</p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p> <p><br /></p>', '2025-12-04 20:39:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14563, 3633, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Baik, terima kasih atas jawaban yang diberikan. Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Jika Anda bersedia, beri kami 2 opsi jadwal antara hari senin/kamis/jumat pukul 08.00-14.30 (beri kami waktu yang spesifik).</p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p> <p><br /></p>', '2025-12-04 20:39:52');
