INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14565, 3646, 28, 'admin', 'Ishida Ayumi', '<p>Kamu tidak perlu malu Ayu kepada kami. Kami disini sudah aware mengenai keadaan yang sudah kamu alami. kamu tidak memilih ingin berada di posisi kamu yang sekarang, orang lain pun akan memilih seperti itu juga. Untuk informasi konseling lanjutan akan kami konfirmasi melalui WA.</p>', '2025-12-04 21:18:51');
