INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14603, 3650, 28, 'admin', 'Ishida Ayumi', '<p>Untuk jadwal bersama psikolog yang tersedia secara luring di minggu depan sudah penuh kak. Baru tersedia pada tanggal 18 Desember 2025 pukul 09.00. Apakah Anda bersedia untuk menunggu?</p> <p> Jika waktu tersebut terlalu lama, kami juga bisa menjadwalkan Anda dengan peer counselor kami yang memiliki jadwal lebih fleksibel. Jika Anda bersedia melakukan konseling dengan peer counselor kami, beri kami 2 opsi jadwal antara hari senin-jumat pukul 08.00-15.00 (luring).</p> <p><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-12-06 10:00:42');
