INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14607, 3650, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf kak, untuk jadwalnya baru tersedia di tanggal 15 kak sesuai dengan yang kami tawarkan di awal. Untuk tanggal 8 sudah terisi oleh klien lain.</p> <p>Kami tunggu konfirmasinya,</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-12-06 12:18:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14608, 3652, 103227, 'mahasiswa', 'Amore', '<p>Setelah memasuki semester 7 ini, tepatnya setelah melaksanakan magang kerja saya merasa bahwa terkadang saya merasa saya merasa mati rasa, terkadang saya merasa bingung dengan diri saya sendiri, dan juga merasa bahwa saya tidak seperti diri saya saat semester 1-7 awal. Saat bersama teman dekat saya, saya biasanya akan merasa senang namun akhir-akhir ini saya enggak bisa merasakan apa-apa. Selain itu, saya juga terkadang merasa bahwa saya tidak bisa berbaur dengan teman satu tim saya untuk tugas akhir ini, saya terus berusaha untuk menghiraukan tetapi saya juga merasa ada hal yang aneh dengan diri saya, karena saya merasa bahwa saya tidak biasanya begini </p>', '2025-12-06 16:48:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14609, 3652, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat malam, Amore !<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Menurut Anda, apa penyebab hal tersebut terjadi? Apakah sebelumnya Anda memiliki beban yang sangat berat atau kelelahan yang berkelanjutan?<br />2. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">3. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr">Dan untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal di minggu depan  sudah penuh, jadwal dengan psikolog kami baru tersedia pada:</p> <p dir="ltr">- Senin, 15 Desember 2025 pukul 10.10 (daring)</p> <p dir="ltr">- Kamis, 18 Desember 2025 pukul 09.00 (daring/luring)</p> <p dir="ltr">Jika waktu tersebut terlalu lama, kami juga bisa menjadwalkan Anda dengan peer counselor kami yang memiliki jadwal lebih fleksibel. Jika Anda bersedia melakukan konseling dengan peer counselor kami, beri kami 2 opsi jadwal antara hari senin-jumat pukul 08.00-15.00 (daring/luring).<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2025-12-06 18:11:28');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14610, 3633, 102933, 'mahasiswa', 'Muhammad', '<p>maaf ka telat membalas, karna dari kemaren saya coba login ini eror terus, baru bisa skrng balasnya</p> <p>baik ka tidak apa, jikalau memang belum ada jadwal dengan psikolog nya</p> <p>mungkin saya ambil jadwal yg dihari Senin ka di jam 11</p> <p>untuk peer nya itu cowo atau cewe ka?</p> <p><br /></p> <p>kalo yang konseling nya dengan konselor (s1) , itu apakah secara online saja ka? atau bisa juga tatap muka?</p>', '2025-12-06 19:35:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14611, 3650, 103225, 'mahasiswa', 'Gilang Pamungkas', '<p>Mohon maaf, saya kurang teliti. Baik kalau begitu hari kamis saja tanggal 18 desember 2025 secara luring</p> <p><br /></p>', '2025-12-07 05:40:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14612, 3653, 103228, 'mahasiswa', 'Firda Az-Zahra', '<p>Sebelumnya izin menjelaskan sedikit,  terkait permasalahan yang ingin saya konsulkan sebenarnya saya juga kurang tau ini masuk ke dalam kategori apa. Secara singkat, saya hanya merasa membutuhkan pertolongan seseorang untuk bisa mendengarkan dan mungkin juga bisa mengarahkan saya baiknya kedepan bagaimana. Terkait hal yang sekarang saya alami adalah saya merasa salah jurusan, tapi untuk alasannya bagi saya tidak sesimpel itu dan tidak semudah itu kalau saya memutuskan pindah jurusan bahkan univ. Sedikit cerita, saya merasa kesepian selama kuliah ini, saya tidak punya teman di kelas, dan bagi saya punya teman itu penting karena bisa jadi support sistem saya yang kebetulan juga perantau. Intinya saya ngerasa down banget, mungkin karena faktor kesepian juga ga punya siapa-siapa disini, saya bener-bener bingung harus melanjutkan kehidupan(terutama perkuliahan)ini bagaimana. Sebenarnya hal penting yang pengen saya dapetin jawabannya adalah, saya bisa lanjut tidak ya untuk kuliah ini di jurusan ini, melihat nilai saya dari semester 1 dan semester 2 (saya sedang semester 3) sudah jelek dan turun, bahkan harus ada yg ngulang matkul. Mungkin banyak faktor juga yang memengaruhi nilai jelek saya ini, tapi hal yang ngebuat saya "ovt" adalah tentang kesepiannya ini.</p>', '2025-12-07 06:37:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14613, 3654, 102621, 'mahasiswa', 'Cyrilla Argyanti', '<p>terkadang saya suka merasakan emosi secara tiba tiba hanya karena masalah sepele sampai saya bertengkar dengan pasangan saya, saya merasa pasangan saya adalah tempat saya bergantung untuk kebahagiaan saya. jadi ketika saya bermasalah dengam pasangan saya, hidup saya rasanya runtuh, tp kalo saya bahagia dengan pasangan saya, hidup saya seakan akan paling bahagia. saya sadar mungkin banyak trauma yg saya rasakan dari saya kecil mulai dari tekanan keluarga dan ekonomi sehingga itu mempengaruhi kondisi mental saya . saya cuma takut ditinggalkan pasangan saya karena sikap saya yang emosional</p>', '2025-12-07 09:35:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14614, 3650, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Baik, terima kasih atas konfirmasinya. Untuk informasi selanjutnya akan kami hubungi melalui WA.<br /></p>', '2025-12-07 10:29:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14615, 3633, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih atas konfirmasinya. Akan kami hubungi melalui WA ya kak untuk konfirmasi lanjutannya karena memang website kami error dalam beberapa hari terakhir.</p> <p><br /></p>', '2025-12-07 10:36:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14616, 3655, 101210, 'mahasiswa', 'Daniel Nugrahantyo', '<p>Ini kali ke-6 saya mengalami blackout (entah blackout, space out, atau disosiasi) ketika berkendara. Sudah lama saya tidak mengalami peristiwa serupa, biasanya saya sudah jaga-jaga dengan tidak membiarkan suasana ''kosong'' entah dengan menyalakan radio/musik atau mengenakan satu earphone bila mengendarai motor. Kejadiannya begitu cepat dan tidak ditandai dengan gejala tertentu, namun begitu sadar dari ''blackout'', saya sudah melewati atau sudah menghadapi kondisi bahaya di lalu lintas, entah menerobos lampu merah, tikungan/persimpangan, hampir menabrak kendaraan orang lain di kondisi lalu lintas lancar, dan terakhir saya menabrak mobil (yang entah rem mendadak, atau sudah berhenti cukup lama, saya tidak ingat) dan mencelakai ibu saya dan diri saya sendiri. Saya yakin saya tidak mengantuk saat berangkat, dan tidak dengan kondisi terburu-buru/mengebut. Saya takut kejadian serupa berulang lagi, maka dari itu saya ingin menyelesaikan ''masalah'' yang ada di pikiran saya dengan mencari bantuan konseling dengan Psikiater.</p> <p>Sebelumnya saya ada riwayat pengobatan ringan dibantu psikiater untuk kondisi GAD saya (terakhir sekitar 7 atau 8 tahun lalu). Singkat cerita saya mencari bantuan lagi sekitar tahun 2023 dan dibantu bu Selly psikolog e-counseling UB, namun saya enggan follow-up lagi meskipun beliau sangat membantu dalam penggalian masalah saya. Solusi yang diberikan sudah saya coba lakukan namun kurang maksimal saya lakukan sendiri. Puncaknya, selama menjalani perawatan di RS pasca kecelakaan kemarin saya memutuskan untuk mencoba cari bantuan psikiater.<br /><br /></p>', '2025-12-07 11:12:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14617, 3655, 28, 'admin', 'Ishida Ayumi', '<p>Baik, terima kasih. Kami akan menghubungi psikiater pada hari kerja dan akan mengonfirmasi kepada Anda melalui WA.</p>', '2025-12-07 14:01:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14618, 3653, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat siang, Firda!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan peer counselor kami? Jika Anda bersedia melakukan konseling dengan peer counselor kami, beri kami 2 opsi jadwal (hari yang dipilih minimal 2 hari sebelum pengajuan jadwal) antara hari senin-jumat pukul 08.00-15.00 (daring/luring).</p> <p dir="ltr"><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-12-07 14:12:14');
