INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14624, 3654, 28, 'admin', 'Ishida Ayumi', '<p>Untuk konseling dengan psikolog bisa kak. Namun baru tersedia pada tanggal 17, jamnya antara 08.00-10.30/12.00-14.30 (Pilih waktu yang spesifik).</p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2025-12-07 15:32:55');
