INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14674, 3651, 25, 'admin', 'Ribby Aura', '<p>Baik kak, mohon maaf baru membalas, akan kami jadwalkan antara selasa atau jumat yaa kak, terima kasih kak, untuk selanjutnya akan kami hubungi melalui WhatsApp yaa kak</p>', '2025-12-14 07:06:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14675, 3656, 25, 'admin', 'Ribby Aura', '<p>Halo, Kak Raja. Terima kasih sudah menghubungi layanan konseling UB dan mempercayakan pada kami. Saya sangat memahami bahwa tidak mudah untuk bisa terbuka, oleh karena itu saya sangat mengapresiasi keterbukaan kakak. Mungkin bisa dibantu untuk menjawab pertanyaan kami yaa kak:</p> <p>1. Coba ceritakan sejak kapan kakak merasakan hal tersebut dan apa alasan kakak merasa kambuh?</p> <p>2. Coba ceritakan apakah selama kakak merasa kambuh, hal tersebut mengganggu kehidupan sosial kakak?</p> <p>3. Apa yang kakak harapkan dari sesi konseling ini?</p> <p>Kami tunggu jawabannya ya, Kak Raja! Terima kasih :)</p>', '2025-12-14 07:08:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14676, 3654, 25, 'admin', 'Ribby Aura', '<p>Baik kak, terima kasih atas konfirmasinya, untuk selanjutnya akan kami hubungi melalui WhatsApp yaa kak</p>', '2025-12-14 07:13:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14677, 3657, 25, 'admin', 'Ribby Aura', '<p>Terimakasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Sebelumnya mohon maaf karena baru membalas dikarenakan panjang nya antrian tiket konseling. Saya sangat memahami pasti situasi ini tidak mudah untuk dilalui. Saya mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Saya akan coba bantu jadwalkan sesi dengan psikolog kami. Apakah kakak berkenan untuk melakukan konseling online pada Selasa, 16 Desember 2025 pukul 19.00 WIB secara online? Terima kasih.</p>', '2025-12-14 07:17:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14678, 3658, 25, 'admin', 'Ribby Aura', '<p>Halo, Kak Rindrayana. Terima kasih sudah menghubungi layanan konseling UB dan mempercayakan pada kami. Saya sangat memahami bahwa tidak mudah untuk bisa terbuka, oleh karena itu saya sangat mengapresiasi keterbukaan kakak. Mungkin bisa dibantu untuk menjawab pertanyaan kami yaa kak:</p> <p>1. Coba ceritakan sejak kapan kakak merasakan hal tersebut dan apa alasan kakak merasa kambuh?</p> <p>2. Coba ceritakan apakah selama kakak merasa kambuh, hal tersebut mengganggu kehidupan sosial kakak?</p> <p>3. Apa yang kakak harapkan dari sesi konseling ini?</p> <p>Kami tunggu jawabannya ya, Kak Rindrayana! Terima kasih :)</p>', '2025-12-14 07:18:13');
