INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14718, 3691, 103250, 'mahasiswa', 'Putu Claudya', '<p>Saya punya kepanikan bahwa semua orang tidak menyukai saya dan saya tidak pantas dicintai. Saya tidak tahu apakah ini delusi saja atau tidak. Rasa anxious ini sudah berjalan selama bertahun-tahun tapi saya baru pertama kali mencoba ke psikolog karena saya tidak yakin bahwa ini adalah gangguan psikologis.</p>', '2025-12-14 23:59:01');
