INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14742, 3692, 103247, 'mahasiswa', 'Alberta Widiyanta', '<p>saya belakangan ini selalu berfikiran untuk akhiri hidup dan saya ga makan dan minum selama hampir 2 hari karena saya pikir dihari ke 3 saya akan meninggal. saya juga berfikir untuk lompat dan pikiran ini selalu menggangu saya. saya juga menghadapi banyak masalah pertemanan, susah bergaul dg teman sekelas dan hanya bisa bergaul dg beberapa orang hinggga orang tersebut hilang dari saya, saya juga merasa tidak pantas hidup karena saya merasa saya pembawa sial, dan juga tekanan dsri omongan keluarga yang selalu blg "jangan malu maluin, om kamu lulusan terbaik loh dijurusanmu sampe sekarang ada di jerman" saya juga bingung mendeskripsikan perasaan ini karena saya juga merasa seperti orang bodoh</p>', '2025-12-15 10:54:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14743, 3692, 28, 'admin', 'Ishida Ayumi', '<p>Sudah dibalas pada e-ticket sebelumnya. Bisa dicek di e-ticket lainnya ya kak. Terima kasih.</p>', '2025-12-15 10:58:01');
