INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14747, 3689, 103247, 'mahasiswa', 'Alberta', '<p>Baik terimakasih banyak atas apresiasinya, saya izin bertanya untuk pengajuan jadwal dapat dilakukan dimana bu ? Apabila disini secata langsung, saya izin mengajukan 2 jadwal</p> <p><br /></p> <p>1. Senin,15 desember dijam 13.00<br /></p>', '2025-12-15 11:39:17');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14748, 3656, 26, 'admin', 'Nadia Aura', '<p>Mohon maaf kak sebelumnya, untuk jadwal psikolog besok belum tersedia. jika berkenan, akan kami carikan jadwal bersama peer counselor. namun, jika ingin bersama psikolog bisa di hari jumat pagi. bagaimana ya?</p>', '2025-12-15 11:44:11');
