INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14750, 3656, 26, 'admin', 'Nadia Aura', '<p>Baik, mohon ditunggu ya kak. informasi mengenai jadwal akan kami sampaikan segera. jika besok tidak ada peer counselor yang tersedia, kami jadwalkan di hari jumat bersama psikolog ya. Mohon ditunggu, terima kasih</p> <p><br /></p>', '2025-12-15 12:19:25');
