INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14779, 3657, 26, 'admin', 'Nadia Aura', '<p>Selamat pagi, Anugerah! Mohon maaf sebelumnya, setelah kami konfirmasi kembali pada psikolog kami, jadwal di hari ini jam 19.00 sudah terisi. Untuk itu, kami akan membantu Anda menjadwalkan ulang di Selasa, 23 Desember 09.00 secara offline, apakah berkenan?</p>', '2025-12-16 05:24:35');
