INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14781, 3680, 26, 'admin', 'Nadia Aura', '<p>Mohon maaf sebelumnya kak, untuk saat ini jadwal sudah terisi hingga hari rabu. jika berkenan, silakan berikan opsi di hari Kamis-Jumat untuk minggu ini atau Senin-Jumat untuk minggu depan ya. Terima kasih</p>', '2025-12-16 05:27:11');
