INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14802, 3657, 103230, 'mahasiswa', 'Anugrah Erlangga', '<p>Selamat Pagi, Baik Ibu. Saya berkenan untuk melakukan konseling pada Selasa, 23 Desember 2025, pagi jam 09:00. Saya akan hadir pada jadwal yang ditentukan. Saya mohon untuk informasi lengkap terkait prosedur kedatangan, tempat dan lokasi konseling offline nya mungkin bisa disampaikan melalui balasan di tiket ini atau melalui nomor WhatsApp saya di 082298881422. Atas perhatiannya saya ucapkan Terima Kasih.</p>', '2025-12-16 10:34:38');
