INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14812, 3703, 103256, 'mahasiswa', 'Masyaila Rumawan', '<p>saya merasa kehilangan motivasi untuk kuliah karena merasa terpaksa, karena jurusan hukum bukan jurusan yang saya inginkan.</p>', '2025-12-16 17:52:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14813, 3704, 103256, 'mahasiswa', 'Masyaila Rumawan', '<p>Saya merasa hilang motivasi kuliah di jurusan ini, karena saya merasa sangat terpaksa. Jurusan hukum bukan jurusan yang saya inginkan. saya izin sudah 2 bulan karena usus buntu dan infeksi pada luka usus buntu tersebut, lalu sekarang apa yang saya bisa lakukan untuk memperbaiki absen? apakah harus chat dosen? atau saya datang ke malang untuk memperbaiki absen tsb?? i have 0 hope to live anymore, rasanya seperti di neraka kuliah di jurusan yang sama sekali tidak diinginkan. saya harap dengan berkonsultasi, saya bisa mendapatkan solusi</p>', '2025-12-16 17:56:16');
