INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14833, 3707, 103258, 'mahasiswa', 'Mutiara Lestari', '<p>Lagi di tahap bingung stresss tapi gak tau apa yang dibingungin dan ini terus terjadi di setiap harinya, sudah berusaha untuk men distract kayak beresin kamar, keluar kos bertemu temen, main game tapi kadang masih ada kayak ngerasa overwhelmed dan jujur ini bikin saya gak fokus dalam mengerjakan tugas tugas</p>', '2025-12-17 14:45:09');
