INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14843, 3707, 26, 'admin', 'Nadia Aura', '<p>Selamat malam, Mutiara! Terima kasih telah menghubungi layanan konseling UB. </p> <p>Kami paham apa yang Anda rasakan saat ini tentu tidak mudah. Untuk memahami cerita Anda lebih dalam, bisakah Anda menjawab beberapa pertanyaan berikut ini.</p> <p>1. Sejak kapan Anda merasakan hal ini? Apakah ada situasi tertentu yang pada akhirnya membuat Anda menjadi mengalami hal ini?</p> <p>2. Bagaimana keseharian Anda akhir-akhir ini? Mungkin bisa dijelaskan jadwal keseharian Anda seperti apa?\</p> <p>Apapun jawaban Anda akan membantu kami menentukan langkah selanjutnya.</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p> <p><br /></p>', '2025-12-17 22:09:06');
