INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14894, 3674, 103237, 'mahasiswa', 'Fachrul Ilmi', '<p>Rabu ini apakah bisa min? Aku tidak tau smpai berapa lama lagi aku bisa nahan. Soalnya Intrusive thought ku makin kuat klau lagi di tempat yang agak tinggi. Asal lewat jembatan suhat itu sering kali ngebayangin gimana yah jatuhnya yang bisa langsung de4d, beberapa temanku juga yang suicidal nyaranin tempat tempat yang mungkin g bakal banyak yang tontonin seperti di jembatan Suhat, waktu sholat jumat kemarin juga di lantai 2 kebayang pengen lompat terus. </p>', '2025-12-22 10:14:20');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14895, 3674, 36, 'admin', 'Aura Ratu', '<p>Baik, Bisa kak. terima kasih atas konfirmasinya ya. Konseling dilaksanakan pada Rabu<strong>,</strong> <strong>24 Desember 2025 pukul 09.00 WIB</strong>, bertempat di <strong>Ruang Konseling, Layanan Konseling UB (Gedung Rektorat Lantai 1)</strong>. Informasi lebih lanjut akan kami sampaikan melalui WhatsApp, ya.</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB.</p>', '2025-12-22 10:49:22');
