INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14908, 3707, 33, 'admin', 'Nafa Tsaniya', '<p>Saya sangat memahami pasti situasi ini tidak mudah untuk dilalui. Saya mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Saya akan coba bantu jadwalkan sesi dengan psikolog kami. Jika berkenan, silahkan ajukan 2 jadwal diantara 29-31 Desember atau setelah 2 Januari 2026 pukul 08.00-15.00 WIB. Kami tunggu konfirmasinya. Terima kasih.</p>', '2025-12-22 16:08:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14909, 3723, 103267, 'mahasiswa', 'Nina Putri', '<p>Saya ingin konsultasi untuk mengurangi overthinking saya dan bagaimana saya bisa menghandle emosi saya ketika di dalam ruang Semhas dan Ujian Skripsi.</p>', '2025-12-22 16:33:36');
