INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14963, 3731, 103271, 'mahasiswa', 'Danisya ''Adni', '<p>Akhir-akhir ini saya lagi ngerasa stres banget karena masalah internal keluarga, terutama soal trauma sama Ayah yang bikin saya jadi gampang cemas dan kepikiran terus.</p> <p>Karena emosi yang lagi nggak stabil, saya jadi sering ngerasa nggak aman dan sempat ada dorongan buat melukai diri sendiri (self-harm). Hubungan sama orang terdekat juga jadi agak terganggu karena kondisi saya ini.</p> <p>Saya pengen bisa cerita ke profesional supaya pikiran saya lebih tenang dan nggak makin parah</p>', '2025-12-25 09:14:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14964, 3710, 103219, 'mahasiswa', 'Fauza Zahrani', '<p>Maaf atas respon yang baru saya kirim, </p> <p>Mengenai jadwal yang dipilih, saya ambil tanggal 31 desember, untuk waktu apakah ada usulan?</p> <p>Terimakasih.</p>', '2025-12-26 09:50:45');
