INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14967, 3729, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat malam, Rif''atul!<br />Mohon maaf baru membelas e-ticket yang Anda ajukan. Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Anda telah berjuang dengan sangat keras untuk diri Anda sendiri, terima kasih karena sudah bertahan hingga saat ini. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal minggu depan sudah penuh dan terdapat beberapa tanggal merah, jadwal dengan psikolog kami baru tersedia pada hari:</p> <p dir="ltr">- Selasa, 6 Januari 2026 pukul 09.00 (daring/luring)</p> <p dir="ltr">- Kamis, 8 Januari 2026 pukul 09.00 (daring/luring)<br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-12-26 18:25:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14968, 3708, 28, 'admin', 'Ishida Ayumi', '<p>Selamat malam Bintang. Mohon maaf baru membalas.</p> <p>Mohon maaf untuk jadwal minggu depan sudah penuh dan baru tersedia pada:</p> <p>- Senin, 5 Januari 2025 pukul 10.10 (online)<br /></p> <p>- Kamis, 8 Januari 2025 pukul 09.00 (Online/Offline)</p> <p>- Kamis, 8 Januari 2025 pukul 13.00 (Online/Offline)</p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr"><br /></p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /></p> <p><br /></p>', '2025-12-26 18:29:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14969, 3708, 28, 'admin', 'Ishida Ayumi', '<p>Selamat malam Bintang. Mohon maaf baru membalas.</p> <p>Mohon maaf untuk jadwal minggu depan sudah penuh dikarenakan terdapat beberapa tanggal merah dan sudah terisi penuh juga kak, sehingga baru tersedia pada:</p> <p>- Senin, 5 Januari 2025 pukul 10.10 (online)<br /></p> <p>- Kamis, 8 Januari 2025 pukul 09.00 (Online/Offline)</p> <p>- Kamis, 8 Januari 2025 pukul 13.00 (Online/Offline)</p> <p dir="ltr"><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,<br /></p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /></p> <p><br /></p>', '2025-12-26 18:29:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14970, 3494, 28, 'admin', 'Ishida Ayumi', '<p>Bisa kak, jika secara online. Namun dikarenakan minggu depan terdapat beberapa tanggal merah dan jadwal konseling kami sudah penuh. Layanan kami baru tersedia kembali ada tanggal 5 kak. Jika kami jadwalkan pada hari Senin, 5 Januari 2025 pukul 10.10 secara online dengan psikolog pendidikan kami, apakah Anda bersedia?</p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /></p>', '2025-12-26 18:35:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14971, 3710, 28, 'admin', 'Ishida Ayumi', '<p>Mohon maaf kak, untuk jadwal minggu depan sudah penuh dan untuk konseling lanjutan dengan Pak Yafi baru tersedia dari tanggal 6 Januari 2026. Apakah Anda bersedia untuk menunggu? Jika bersedia untuk menunggu mengenai opsi jam konselingnya baru bisa kami berikan pada hari senin besok tanggal 29 ya kak. </p> <p><br /></p> <p>Kami tunggu konfirmasinya,</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB. </p>', '2025-12-26 18:39:13');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14972, 3729, 101808, 'mahasiswa', 'Rif''atul Ilmi', '<p>Tanggal 6 Januari saja, mohon maaf izin bertanya ini nanti konsultasinya dengan psikolog langsung atau sama peer counselor yaa?</p>', '2025-12-26 18:43:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14973, 3731, 28, 'admin', 'Ishida Ayumi', '<p dir="ltr">Selamat malam Danisya!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Mohom maaf baru membalas e-ticket Anda. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Rasa cemas yang Anda rasakan biasanya muncul ketika Anda berada di situasi yang seperti apa?</p> <p dir="ltr">2. Sudah berapa lama Anda memiliki dorongan untuk melakukan hal yang dapat merugikan diri Anda Sendiri? Bagaimana frekuensi kemunculannya?<br /></p> <p dir="ltr">3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut? Jika Anda sudah mencoba melakukan suatu hal, apakah hal tersebut efektif?<br /></p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr">Dan untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal di minggu depan sudah penuh, jadwal dengan psikolog kami baru tersedia pada:</p> <p dir="ltr">- Rabu, 7 Januari 2025 pukul 09.00 (daring/luring)</p> <p dir="ltr">- Rabu, 7 Januari 2025 pukul 10.00 (daring/luring)<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2025-12-26 18:46:13');
