INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14983, 3732, 103272, 'mahasiswa', 'Naruto Nugroho', '<p>Saya sebenarnya bingung hidup ini buat apa? Melihat orang lain berkembang dengan segala caranya. Sedangkan saya sibuk memikirkan hidup saya ini buat apa? Tujuan saya hidup bagaimana ? Mengapa kita hidup hanya untuk memenuhi keinginan lingkungan saja. Contoh kuliah karena sudah waktunya kuliah. Setelah kuliah bekerja untuk apa ? Lagi lagi untuk memenuhi tuntutan dari lingkungan. Setelah kuliah disuruh bekerja, untuk memenuhi kebutuhan hidup dan membahagiakan orang tua lagi lagi soal tuntutan masyarakat dan lingkungan. Dimana letak kebahagiaan yang bisa didapatkan? Setelah bekerja menikah dan bekeluarga menyambung hidup saja. Apakah hidup hanya untuk menunggu kematian saja ? Jujur semua hal itu terpikir di kepala saya. Terkait bakat saya rasa saya tak memiliki bakat apapun, soal pertemanan apa lagi saya sampai sekarang belum menemukan teman yang bisa mengerti keadaan saya. Seringkali di lingkugan yang saya temui adalah kita harus selalu mengerti kondisi sekitar? tanpa mengerti kondisi kita bagaimana? Akhir akhir ini saya berpikir demikian hidup rasanya hampa saja tanpa menemukan solusi. Solusi datang dari masyarakat mungkin adalah kurangnya rasa bersyukur dan tujuan hidup didapat ketika melakukan sesuatu. Menurut saya, kondisi saya seperti orang yang ingin bunuh diri dimana solusi dari masyarakat hanya kurang bersyukur. Bayangkan saja orang hilang arah malah dibilang kurang bersyukur, seharusnya diberikan jalan atau petunjuk harus bersyukur bagaimana malah ini harus berpikir dimana letak syukurnya. Soal agama sebenarnya, saja jujur tidak tertarik jika semua masalah di hadapkan terhadap agama. Kurang bersyukur blablabla. Orang hidup ini disuruh sabar tuhan pasti memberikan yang terbaik bagi kita. Tapi saya belum menemukannya hingga sekarang. Tujuan saya konseling untuk menjawab seluruh pertanyaan yang saya punya. Makasih </p>', '2025-12-27 20:24:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14984, 3733, 103272, 'mahasiswa', 'Naruto Nugroho', '<p>Saya sebenarnya bingung hidup ini buat apa? Melihat orang lain berkembang dengan segala caranya. Sedangkan saya sibuk memikirkan hidup saya ini buat apa? Tujuan saya hidup bagaimana? Mengapa kita hidup hanya untuk memenuhi keinginan lingkungan saja. Contoh kuliah karena sudah waktunya kuliah. Setelah kuliah bekerja untuk apa? Lagi lagi untuk memenuhi tuntutan dari lingkungan. Setelah kuliah disuruh bekerja, untuk memenuhi kebutuhan hidup dan membahagiakan orang tua lagi lagi soal tuntutan masyarakat dan lingkungan. Dimana letak kebahagiaan yang bisa didapatkan? Setelah bekerja menikah dan bekeluarga menyambung hidup saja. Apakah hidup hanya untuk menunggu kematian saja? Jujur semua hal itu terpikir di kepala saya. Terkait bakat saya rasa saya tak memiliki bakat apapun, soal pertemanan apa lagi saya sampai sekarang belum menemukan teman yang bisa mengerti keadaan saya. Seringkali di lingkugan yang saya temui adalah kita harus selalu mengerti kondisi sekitar? tanpa mengerti kondisi kita bagaimana? Akhir akhir ini saya berpikir demikian hidup rasanya hampa saja tanpa menemukan solusi. Solusi datang dari masyarakat mungkin adalah kurangnya rasa bersyukur dan tujuan hidup didapat ketika melakukan sesuatu. Menurut saya, kondisi saya seperti orang yang ingin bunuh diri dimana solusi dari masyarakat hanya kurang bersyukur. Bayangkan saja orang hilang arah malah dibilang kurang bersyukur, seharusnya diberikan jalan atau petunjuk harus bersyukur bagaimana malah ini harus berpikir dimana letak syukurnya. Soal agama sebenarnya, saja jujur tidak tertarik jika semua masalah di hadapkan terhadap agama. Kurang bersyukur blablabla. Orang hidup ini disuruh sabar tuhan pasti memberikan yang terbaik bagi kita. Tapi saya belum menemukannya hingga sekarang. Tujuan saya konseling untuk menjawab seluruh pertanyaan yang saya punya. Makasih </p>', '2025-12-27 20:28:25');
