INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14986, 3710, 25, 'admin', 'Ribby Aura', '<p>Baik kak, terimakasih atas konfirmasinya. Untuk selanjutnya akan kami hubungi melalui Whatsapp yaa kak</p>', '2025-12-28 08:06:31');
