INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14998, 3726, 32, 'admin', 'Almira Jessenia', '<p>Baik, terima kasih atas konfirmasinya kak Melinda. Jika berhalangan datang offline apakah berkenan untuk melakukan sesi konseling secara online? jika berkenan, berikut jadwal konselor yang tersedia:<br />1. 30 Desember 2025 (19.00 WIB)<br />2. 2 Januari 2025 (19.00 WIB) <br /><br />Silakan memilih salah satu jadwal yang kiranya sesuai dengan ketersediaan kakak. Kami tunggu konfirmasinya yaa :)<br /><br />Terima Kasih<br />Salam Hangat,<br />Tim Konseling UB</p>', '2025-12-29 09:49:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (14999, 3713, 32, 'admin', 'Almira Jessenia', '<p>Sudah terjawab pada e-ticket #003725 yaa :)</p>', '2025-12-29 09:49:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15000, 3735, 32, 'admin', 'Almira Jessenia', '<p>Selamat pagi kak Windy :) Terima kasih telah menghubungi Layanan Konseling UB dan telah berkenan untuk menceritakan permasalahan kakak dan apa yang kakak rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah.<br /></p> <p>Kami ingin memastikan kakak mendapatkan dukungan yang tepat dan aman. Oleh karena itu, kami menyarankan untuk melakukan sesi konseling bersama dengan tenaga profesional kami.</p> <p>Apabila kakak berkenan, kami bisa menjadwalkan sesi konseling secepatnya.<br /> Apakah kakak bersedia mengikuti sesi konseling dalam waktu dekat <strong>(online/offline)? </strong>kami tunggu konfirmasinya yaa..<br /><br />Terima Kasih<br />Salam Hangat,<br />Tim Konseling UB</p>', '2025-12-29 10:08:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15001, 3720, 35, 'admin', 'Melsy Nemasari', '<p>Baik, kalau begitu apakah Kakak bersedia jika konseling dilaksanakan secara online? Jika bersedia mohon dibalas ya Kak agar kami carikan jadwal yang sesuai dengan psikolog kami. Terima kasih.</p>', '2025-12-29 10:12:11');
