INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15003, 3737, 103273, 'mahasiswa', 'Ahmad Luthfulloh', '<p>Saya gatau sebenernya ada problem apa, cuman ngerasa ga produktif yg menghambat akademik saya</p>', '2025-12-30 00:33:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15004, 3738, 101355, 'mahasiswa', 'Citra Prameswari', '<p>Saya tiba-tiba dijauhi oleh teman-teman saya namun saya tidak tau apa salah saya.</p>', '2025-12-30 01:33:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15005, 3737, 35, 'admin', 'Melsy Nemasari', '<p>Selamat Pagi, Ahmad!<br />Terima kasih telah menghubungi layanan konseling UB dan berbagi mengenai kebingungan yang Anda rasakan. Kami paham apa yang Anda rasakan saat ini tentu tidak mudah.</p> <p>Sebelum kami menjadwalkan layanan lanjutan, kami ingin memastikan bentuk pendampingan yang paling sesuai. Mohon bantuan Anda untuk menginformasikan beberapa hal berikut:</p><ol><li>Sejak kapan kamu mulai merasa tidak produktif, dan apakah kondisi tersebut muncul secara konsisten atau hanya di waktu-waktu tertentu?</li><li>Apakah rasa tidak produktif ini disertai dengan perubahan suasana hati, seperti merasa sedih berkepanjangan, cemas, atau kehilangan motivasi?</li><li>Apakah kondisi ini juga memengaruhi pola tidur, nafsu makan, atau aktivitas harianmu secara umum?</li><li>Saat menghadapi hambatan akademik, apa yang paling sering kamu rasakan: sulit fokus, kelelahan mental, atau justru kehilangan minat?</li></ol> <p>Kami tunggu jawabannya ya, Ahmad! :)</p> <p>Terima kasih, </p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-12-30 08:22:17');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15006, 3736, 35, 'admin', 'Melsy Nemasari', '<p>Selamat pagi, Ahmad! </p> <p>Terima kasih ya telah menghubungi Layanan Konseling UB. Untuk membantu kami memetakan permasalahan dengan lebih lanjut, mungkin boleh coba dijelaskan dengan lebih detail yaa mengenai permasalahan yang Anda sebutkan. Gambaran umumnya aja tidak papa jika tidak nyaman untuk menceritakan keseluruhan permasalahan agar kami dapat menentukan pendampingan yang tepat. Kami tunggu balasannya ya, Ahmad! :)<br /><br />Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2025-12-30 08:26:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15007, 3738, 32, 'admin', 'Almira Jessenia', '<p><br /></p> <p dir="ltr">Selamat pagi kak Citra :) Terima kasih telah menghubungi Layanan Konseling UB dan telah berkenan untuk menceritakan permasalahan Anda dan apa yang Anda rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk membantu kami lebih memahami permasalahan Anda, silakan untuk menjawab pertanyaan berikut, yaa:</p> <p><br /></p> <ol><li dir="ltr"><p dir="ltr">Sejak kapan kakak mulai merasa dijauhi?</p></li><li dir="ltr"><p dir="ltr">Apakah kejadian ini memengaruhi kepercayaan diri, mood, atau aktivitas harian kakak?</p></li><li dir="ltr"><p dir="ltr">Apa harapan Anda untuk melakukan konseling bersama Layanan Konseling UB?</p></li></ol> <p dir="ltr">Apapun jawaban yang Anda berikan akan sangat membantu kami untuk memetakan permasalahan lebih lanjut. <br />Terima kasih. <br />Salam hangat, <br />Tim Konseling UB.<br /></p>', '2025-12-30 08:28:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15008, 3738, 32, 'admin', 'Almira Jessenia', '<p>Selamat pagi kak Citra :) Terima kasih telah menghubungi Layanan Konseling UB dan telah berkenan untuk menceritakan permasalahan Anda dan apa yang Anda rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk membantu kami lebih memahami permasalahan Anda, silakan untuk menjawab pertanyaan berikut, yaa:<br /></p> <ol><li dir="ltr"><p dir="ltr">Sejak kapan kakak mulai merasa dijauhi?</p></li><li dir="ltr"><p dir="ltr">Apakah kejadian ini memengaruhi kepercayaan diri, mood, atau aktivitas harian kakak?</p></li><li dir="ltr"><p dir="ltr">Apa harapan Anda untuk melakukan konseling bersama Layanan Konseling UB?</p></li></ol> <p dir="ltr">Apapun jawaban yang Anda berikan akan sangat membantu kami untuk memetakan permasalahan lebih lanjut. <br />Terima kasih. <br />Salam hangat, <br />Tim Konseling UB.<br /></p>', '2025-12-30 08:28:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15009, 3737, 103273, 'mahasiswa', 'Ahmad Luthfulloh', '<p>1. 3 bulan terakhir, hampir setiap hari demotivasi</p> <p>2. Iya</p> <p>3. Iya cukup mempengaruhi </p> <p>4. Progres thesis terhambat, sulit fokus</p>', '2025-12-30 08:37:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15010, 3737, 35, 'admin', 'Melsy Nemasari', '<p>Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Saya sangat memahami pasti situasi ini tidak mudah untuk dilalui. Saya mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Terkait dengan perasaan dan pengalaman yang Anda alami, apakah Anda berkenan melakukan sesi konseling dengan psikolog kami pada tanggal 5 Januari 2026 pukul 10.10 WIB secara online? Jika berkenan mohon untuk membalas yaa. Kami tunggu konfirmasinya.<br /></p> <p>Terima Kasih.</p> <p>Salam hangat,<br />Tim Konseling UB</p>', '2025-12-30 10:59:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15011, 3738, 101355, 'mahasiswa', 'Citra Prameswari', '<p>Selamat pagi Kak Almira! Terima kasih sudah membalas pesan saya. Saya izin untuk menjawab satu persatu yaa.<br /><br />1. Saya merasa mulai dijauhi sekitar 7 bulan yang lalu. Saya mulai merasa dijauhi pada saat teman saya ini tiba-tiba main bersama teman saya yg lain yg notabene satu circle dengan saya. Dari situ muncul perasaan seperti "eh kok gini sih? perasaan dulu kalo mau main pasti ngajak aku kok ini nggak ya?". Dan untuk tambahan, teman saya ini teman sejak day 1 saya di SMP dan sudah sedekat itu baik kami maupun orang tua kami, dia dulu selalu ada dikala titik terendah saya, menjadi rumah dikala saya kabur dari keluarga saya.<br />2. Jujur memengaruhi banget kak, dari mulai kepercayaan diri saya gak pede untuk menunjukkan eksistensi saya di kota asal saya karena takut jika dia tau saya di kota itu namun dia main dengan teman saya yang lain, saya makin sakit hati dan kepikiran. Mood saya jadi berubah-ubah karena kadang kalau kepikiran saya jd murung sendiri dan ini memengaruhi ke aktivitas harian saya, padahal saya sedang di tahap mengerjakan skripsi.<br />3. Saya berharap Layanan Konseling UB dapat membantu menenangkan hati saya. Saya ingin pikiran-pikiran di dalam otak saya ini berubah menjadi hal yang positive lagi.<br /><br />Cukup sekian dahulu jawaban saya, semoga Layanan Konseling UB dapat membantu saya. Terima kasih!<br /></p>', '2025-12-31 07:55:28');
