INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15031, 3740, 36, 'admin', 'Aura Ratu', '<p dir="ltr">Selamat malam Aulia!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Mohom maaf baru membalas e-ticket Anda. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah rasa cemas, takut, menyalahkan diri sendiri, dan panik mengganggu aktivitas keseharian anda? Dan apa yang anda lakukan ketika hal tersebut muncul?<br /></p> <p dir="ltr">3. Apa hal yang sudah Anda lakukan atau rencanakan untuk menyelesaikan permasalahan tersebut? Jika Anda sudah mencoba melakukan suatu hal, apakah hal tersebut efektif?<br /></p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr">Dan untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal di minggu depan sudah penuh, jadwal dengan psikolog kami baru tersedia pada:</p> <p dir="ltr">- Kamis, 8 Januari 2026 pukul 08.00 (daring/luring)</p> <p dir="ltr">- Kamis, 8 Januari 2026 pukul 12.00 (daring/luring)<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2026-01-05 18:22:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15032, 3740, 103276, 'mahasiswa', 'Aulia', '<p>1. iya saya merasakan seperti itu, ketika rasa itu muncul saya hanya bisa menangis.</p> <p>3.  saya sudah melakukan laporan online kepada pihak berwajib, OJK, IASC, cek rekening, polisi cyber namun semuanya masih nihil. saya kepikiran untuk pinjol saja sementara waktu namun sebenernya saya takut pinjol </p>', '2026-01-05 18:32:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15033, 3740, 36, 'admin', 'Aura Ratu', '<p>Baik Kak Aulia, terimakasih atas jawabannya. Kami izin untuk memberikan pertanyaan lanjutan, jika berkenan silahkan untuk menjawab yaa!<br /><br />1. Berapa Frekuensi dan durasi ketika menangis? dan apakah sampai mengganggu mood dan produktivitas anda?<br />2. Apa yang anda harapkan untuk anda dapatkan dari sesi konseling nanti? <br /><br /></p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr">Dan untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal di minggu depan sudah penuh, jadwal dengan psikolog kami baru tersedia pada:</p> <p dir="ltr">- Kamis, 8 Januari 2026 pukul 08.00 (daring/luring)</p> <p dir="ltr">- Kamis, 8 Januari 2026 pukul 12.00 (daring/luring)<br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2026-01-05 18:56:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15034, 3740, 103276, 'mahasiswa', 'Aulia', '<p>1. iya sampai mengganggu waktu tidur, makan, dll.</p> <p>2. solusi terbaik bagaimana, bagaimana cara saya dapat mencari uang untuk mengganti dan apakah caranya dengan ikut pinjol</p>', '2026-01-05 18:59:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15035, 3740, 36, 'admin', 'Aura Ratu', '<p>Baik Kak Aulia, terimakasih atas jawabannya. Kami izin untuk memberikan pertanyaan lanjutan, jika berkenan silahkan untuk menjawab yaa!<br /><br />1. Berapa Frekuensi dan durasi ketika menangis? dan apakah sampai mengganggu mood dan produktivitas anda?<br />2. Apakah anda sudah memetakan positif dan negatif yang akan anda dapatkan ketika memilih penyelesaian tersebut?<br />3. Apa yang anda harapkan untuk anda dapatkan dari sesi konseling nanti? <br /><br /></p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr">Dan untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal di minggu depan sudah penuh, jadwal dengan psikolog kami baru tersedia pada:</p> <p dir="ltr">- Kamis, 8 Januari 2026 pukul 08.00 (daring/luring)</p> <p dir="ltr">- Kamis, 8 Januari 2026 pukul 12.00 (daring/luring)<br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2026-01-05 18:56:37');
