INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15038, 3740, 36, 'admin', 'Aura Ratu', '<p>Baik, terimakasih atas jawabannya yaa!  Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Boleh kami memberikan saran, silahkan anda menuliskan di kertas atau notes dampak positif dan negatif yang akan anda dapatkan ketika anda mengambil salah satu penyelesaian tersebut. Semoga bisa membantu anda untuk mengatasi kebingungan dalam mengambil langkah.<br />Dan jika kami boleh bertanya, apakah kejadian ini sudah anda ceritakan kepada keluarga terdekat anda? <br /><br />Saat ini anda tidak sendiri. Setiap permasalahan pasti ada pembelajaran dan jalan keluar. Melalui konseling, Anda dapat memperoleh ruang aman untuk bercerita, memahami kondisi diri, serta dibantu dalam mengelola emosi dan mengambil langkah ke depan dengan lebih tenang.</p> <p dir="ltr">Dan untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? silahkan untuk memilih salah satu jadwal konseling yang tersedia di bawah ini :</p> <p dir="ltr">- Kamis, 8 Januari 2026 pukul 08.00 (daring/luring)</p> <p dir="ltr">- Kamis, 8 Januari 2026 pukul 12.00 (daring/luring)<br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2026-01-05 20:11:41');
