INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15058, 3738, 33, 'admin', 'Nafa Tsaniya', '<p>Sebelumnya mohon maaf atas ketidaknyamanannya, untuk jadwal konselor kami terbatas untuk setiap minggu nya, dan jadwal untuk di minggu ini sudah terisi, apakah kakak berkenan untuk dialihkan tanggal ke <strong>13 Januari 2026 pukul 19.00 </strong>secara <strong>online?</strong></p>', '2026-01-07 20:00:19');
