INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15066, 3744, 102765, 'mahasiswa', 'Vianta Mandhalika', '<p>Saya merupakan mahasiswa doktoral melalui beasiswa PMDSU dimana saya harus menempuh pendidikan s2 hingga s3 hanya dalam waktu 4 tahun. Saat ini pendidikan S2 saya telah selesai dan pendidikan S3 saya tinggal 1,5 tahun lagi. Saya memiliki perasaan takut yang berlebihan ketika akan memulai menulis artikel ilmiah. Setiap pagi saya takut karena harus menghadapi deadline disertasi, bahkan ketika saya sedang berlibur pun saya tetap kepikiran. Saya terlalu memikirkan hal-hal kecil sehingga merasa memiliki beban berlebih. Karena perasaan takut tersebut, produktivitas saya menurun. Menjalankan kegiatan yang tidak seberapa besar membuat saya merasa sangat kelelahan. Saya merasa tidak bahagia dan tidak bersemangat dalam menghadapi pendidikan ini.</p>', '2026-01-08 18:21:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15067, 3745, 102765, 'mahasiswa', 'Vianta Mandhalika', '<p>Saya merupakan mahasiswa doktoral melalui beasiswa PMDSU dimana saya harus menempuh pendidikan s2 hingga s3 hanya dalam waktu 4 tahun. Saat ini pendidikan S2 saya telah selesai dan pendidikan S3 saya tinggal 1,5 tahun lagi. Saya memiliki perasaan takut yang berlebihan ketika akan memulai menulis artikel ilmiah. Setiap pagi saya takut karena harus menghadapi deadline disertasi, bahkan ketika saya sedang berlibur pun saya tetap kepikiran. Saya terlalu memikirkan hal-hal kecil sehingga merasa memiliki beban berlebih. Karena perasaan takut tersebut, produktivitas saya menurun. Menjalankan kegiatan yang tidak seberapa besar membuat saya merasa sangat kelelahan. Saya merasa tidak bahagia dan tidak bersemangat dalam menghadapi pendidikan ini.</p>', '2026-01-08 18:21:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15068, 3745, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat malam, Vianta!<br />Terima kasih telah menghubungi layanan konseling UB dan berbagi mengenai kondisi yang Anda rasakan. Kami paham apa yang Anda rasakan saat ini tentu tidak mudah. Sebelum kami menjadwalkan layanan lanjutan, kami ingin memastikan bentuk pendampingan yang paling sesuai. Mohon bantuan Anda untuk menginformasikan hal berikut: </p> <p>1. Sejak <strong>kapan</strong> perasaan takut berlebihan ini mulai muncul?</p> <p>2. Seberapa <strong>sering dan intens</strong> rasa takut ini muncul dalam keseharianmu (misalnya setiap hari, terutama di pagi hari, atau menjelang tenggat waktu)?</p> <p>3. Ketika produktivitas menurun dan kamu merasa sangat kelelahan, <strong>apa yang biasanya kamu lakukan untuk mengatasinya</strong>? Apakah ada strategi yang pernah membantu?</p> <p>Kami tunggu jawabannya ya, Vianta! :)</p> <p>Terima kasih,</p> <p>Salam hangat,</p> <p>Tim Konseling UB</p>', '2026-01-08 19:25:30');
