INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15084, 3745, 33, 'admin', 'Nafa Tsaniya', '<p dir="ltr">Anda telah berjuang dengan sangat keras untuk diri Anda sendiri, terima kasih karena sudah bertahan hingga saat ini, ya Vianta. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan psikolog kami? Jadwal dengan psikolog kami tersedia pada hari:</p> <p dir="ltr">- Senin, 12 Januari 2026 pukul 10.10 (daring)</p> <p dir="ltr">- Kamis, 15 Januari 2026 pukul 09.00 (luring)<br /></p> <p dir="ltr">Silahkan pilih 1 tanggal untuk melakukan sesi konseling ya, kami tunggu konfirmasinya.</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p>', '2026-01-09 21:15:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15085, 3745, 102765, 'mahasiswa', 'Vianta Mandhalika', '<p>Saya memilih pada Kamis 15 Januari 2026 secara luring. Apakah boleh diinfokan untuk tempat konselingnya?</p>', '2026-01-10 09:18:20');
