INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15140, 3765, 34, 'admin', 'Heidemarie Gunarso', '<p dir="ltr">Selamat siang, Kak Jeastamika!</p> <p dir="ltr">Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail gelisah yang Anda alami? <br />2. Dari gelisah yang Anda rasakan, apa efeknya ke kegiatan keseharian Anda? Dan apakah sudah sangat mengganggu?<br />3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?<br />4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.<br /><br />Kami tunggu konfirmasinya ya... :) </p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /></p>', '2026-01-16 12:53:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15141, 3766, 34, 'admin', 'Heidemarie Gunarso', '<p>Selamat siang, Kak Jeastamika!<br /><br />Sudah dijawab pada ticket nomor ticket #003764 yaa :) <br /><br />Terima kasih, </p> <p>Salam hangat,<br /></p> <p>Tim Konseling UB.</p>', '2026-01-16 12:57:26');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15142, 3760, 34, 'admin', 'Heidemarie Gunarso', '<p>Selamat siang, Kak Naomi!<br /><br />Terima kasih karena telah menghubungi Layanan Konseling UB. Untuk memperdalam pemahaman kami, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda masih dalam status mahasiswa aktif Universitas Brawijaya?<br />2. Apakah sesi konseling yang Anda lakukan sebelumnya sudah menghubungi Layanan Konseling UB terlebih dahulu?<br />3. Apakah Anda berkenan mendeskripsikan lebih detail permasalahan yang Anda alami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami untuk menentukan langkah selanjutnya. <br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /></p>', '2026-01-16 14:16:48');
