INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15339, 3807, 37, 'admin', 'Allysa Dewantari', '<p>Selamat sore, Kak Vania!<br />Baik, terima kasih konfirmasinya kak. Apakah Kak Vania berkenan kami jadwalkan sesi konseling bersama <strong>peer counselor </strong>pada <strong>Kamis, 05 Februari 2026 pukul 09.00 </strong>secara <strong>offline</strong>?<br />Kami tunggu konfirmasinya ya kak... :)<br /><br />Terima kasih. <br />Salam hangat, <br />Tim Konseling UB.</p>', '2026-02-02 16:20:56');
