INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15341, 3807, 101370, 'mahasiswa', 'Vania razani', '<p>Halo, untuk hari dan jam nya aku bersedia. Tapi kalau mau request sesi konselingnya dengan konselor bisa ga ya?? Karena kayaknya aku akan lebih nyaman dengan konselor untuk lebih terbuka</p>', '2026-02-02 17:23:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15342, 3807, 37, 'admin', 'Allysa Dewantari', '<p>Baik, terima kasih konfirmasinya kak. Untuk sesi konseling dengan konselor tersedia pada <strong>Rabu, 04 Februari 2026</strong> pukul <strong>19.00</strong> secara <strong>online</strong>, apakah Kak Vania berkenan terkait jadwal tersebut? </p> <p>Terima kasih. </p> <p>Salam hangat, </p> <p>Tim konseling UB.</p>', '2026-02-02 17:29:20');
