INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15344, 3807, 37, 'admin', 'Allysa Dewantari', '<p>Baik kak, terima kasih konfirmasinya. Untuk informasi selanjutnya akan kami infokan lewat WA ya kak :) </p> <p>Terima kasih. </p> <p>Salam hangat, </p> <p>Tim Konseling UB. </p>', '2026-02-02 17:35:05');
