INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15346, 3799, 103307, 'mahasiswa', 'Atha Nisa', '<p>Baik, kalau konseling offline pada Selasa 3 Februari pukul 13.00, apakah bisa?</p>', '2026-02-02 23:22:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15347, 3808, 101475, 'mahasiswa', 'Nadia Nisa', '<p>Bismillah. </p> <p>Saya alumni diksasindo, alhamdulillah sudah bekerja. Awalnya belum ditemukan hambatan tetapi lama kelamaan saya menyadari bahwa ada yang salah. Ketika saya menjelaskan ke murid di bimbel, saya kesusahan merangkai kata padahal sebelumnya sudah dicatat. Selain itu energi saya mudah habis dan berakhir tidak bisa menngontrol kelas. Selain itu saya menyadari jika saya menerima informasi baru, maka informasi lama akan menghilang. Seperti mempri yang tiba tiba mengjilang dan menyebabkan saya blank sejenak. </p> <p>Waktu saya kecil, dokter bilang perkembangan otak saya lambat. Namun, saya tidak tau apakah itu masih relevan dengan keadaan saya yang sekarang atau ada faktor lain yang memengaruhi kinerja otak saya. </p>', '2026-02-02 23:23:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15348, 3809, 103276, 'mahasiswa', 'Aulia', '<p>Saya terkena penipuan online melalui aplikasi telegram tadinya rencana saya mau membelikan hp untuk orangtua dikarenakan hp mama yang di rumah sudah rusak jadi semisal saya balik ke malang ngga bisa menghubungi orang tua yang di rumah, namun ternyata saya terkena penipuan saya menggunakan uang kipk yang baru saya dapatkan bulan Desember kemarin, saya sudah berusaha ikhlas namun kejadian tersebut terus berputar di pikiran saya yang membuat saya sedih, nangis, menyalahkan diri sendiri</p>', '2026-02-03 01:43:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15349, 3799, 37, 'admin', 'Allysa Dewantari', '<p>Selamat pagi, Kak Atha! <br />Baik kak, akan kami jadwalkan konseling hari ini <strong>Selasa, 03 Februari 2026 pukul 13.00 secara offline</strong> dengan peer counselor ya kak. Informasi selanjutnya akan kami hubungi lewat WA <br /></p> <p>Terima kasih.</p> <p>Salam hangat, </p> <p>Layanan Konseling UB.</p>', '2026-02-03 08:01:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15350, 3808, 34, 'admin', 'Heidemarie Gunarso', '<p dir="ltr">Selamat pagi, Kak Nadia Nisa!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Mohon maaf sebelumnya, Layanan Konseling Mahasiswa UB hanya bisa melayani Mahasiswa Aktif Universitas Brawijaya sehingga mohon maaf kami belum bisa membantu untuk konseling untuk Anda. Akan tetapi, jika Anda membutuhan biro konseling Malang, kami memiliki rekomendasi yang bisa dilihat dari foto yang kami berikan: <br /></p><figure><img src="cid:p3ohqvlewwsqdwcymipmlfuow_gzidye" data-image="p3oHQvLewwsqDWcYMipmlfuOw_gzidyE" alt="image" /></figure> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.</p> <p><br /></p>', '2026-02-03 08:46:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15351, 3809, 34, 'admin', 'Heidemarie Gunarso', '<p dir="ltr">Selamat pagi, Kak Aulia!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Dapatkah Anda menceritakan secara singkat bagaimana kronologi terjadinya penipuan online yang Anda alami?</p> <p dir="ltr">2. Seberapa sering pikiran tentang kejadian ini muncul dalam keseharian Anda? Dan apakah kejadian ini memengaruhi aktivitas harian Anda? </p> <p dir="ltr">3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.<br /><br />Kami tunggu konfirmasinya yaa,</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB</p> <p><br /></p>', '2026-02-03 09:22:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15352, 3809, 103276, 'mahasiswa', 'Aulia', '<p>1. Mohon maaf saya tidak berkenan untuk menjawab pertanyaan yang kalian tanyakan </p> <p>2. Sering setiap malam maupun disaat saya tidak ada kegiatan lain, iya saya sering menangis sampai saya ketiduran nafsu makan saya menurun</p> <p>3. Saya sudah berusaha untuk mengikhlaskan hal tersebut terjadi di kehidupan saya namun itu masih terbayang-bayang dan terus berputar di pikiran saya</p> <p>4. Saya berharap untuk bisa konsultasi dengan konseling UB dikarenakan saya ngga bisa kalau cerita masalah tersebut kepada orang lain saya tidak mau dihakimi </p>', '2026-02-03 09:38:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15353, 3809, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik, terima kasih atas jawabannya Kak Aulia. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda dan kami sangat mengerti dengan perasaan Anda. Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Berikut opsi jadwal yang dapat Anda pilih:</p> <p dir="ltr">- Kamis, 5 Februari 2026 pukul 08.00 (daring/luring)</p> <p dir="ltr">- Kamis, 5 Februari 2026 pukul 12.00 (daring/luring)</p> <p dir="ltr">- Jumat, 6 Februari 2026 pukul 08.00 (daring/luring)</p> <p dir="ltr">- Jumat, 6 Februari 2026 pukul 12.00 (daring/luring)<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa :)</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /></p>', '2026-02-03 10:01:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15354, 3809, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik, terima kasih atas jawabannya Kak Aulia. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda dan kami sangat mengerti dengan perasaan Anda. Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan peer counselor kami pada <strong>Kamis, 05 februari 2026 </strong><strong>pukul 10.00 secara offline</strong>?<br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa :)</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /></p>', '2026-02-03 10:01:00');
