INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15409, 3823, 37, 'admin', 'Allysa Dewantari', '<p>Selamat siang, Kak Diska!<br /><br />Sudah kami jawab pada ticket nomor ticket #003821 yaa :) <br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-02-07 08:59:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15410, 3825, 103318, 'mahasiswa', 'Augusta Ferdiansyah', '<p>Banyak masalah yang terjadi ketika saat berkuliah, trauma akan masalalu, dan luka lama yang masih belum sembuh </p>', '2026-02-07 12:10:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15411, 3825, 34, 'admin', 'Heidemarie Gunarso', '<p dir="ltr">Selamat siang, Kak Augusta!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail masalah yang Anda alami? Menurut Anda apa penyebab hal tersebut terjadi?</p> <p dir="ltr">2. Dari masalah yang Anda alami, apa efeknya ke kegiatan keseharian Anda? Dan apakah sudah sangat mengganggu?</p> <p dir="ltr">3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p dir="ltr">4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa :)</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /></p>', '2026-02-07 14:33:37');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15412, 3826, 102801, 'mahasiswa', 'Fransiska', '<li>Sedang menjalani pengobatan psikiatri<br />Sebelum pengobatan: keluhan utama sedih, cemas, rasa bersalah, disertai mimpi buruk yang sudah berlangsung sekitar 1 tahun.<br />Setelah pengobatan:<br />+ Sedih dan cemas berkurang<br />+ Mampu menjalani aktivitas sehari-hari dengan normal<br />- Perasaan bersalah masih sering muncul<br />- Mudah lupa dan mudah terdistraksi<br />- Sensasi aneh (benda terasa membesar meskipun disadari ukurannya sebenarnya normal)<br />- Masih mengalami mimpi buruk. Kadang sulit membedakan mimpi dan kenyataan.<br /></li><li>Riwayat self-harm: sudah berhenti selama ±2 bulan terakhir, tapi saat ini muncul kembali dorongannya (masih sebatas pikiran dan belum diwujudkan dalam tindakan)</li><li><p>Saya ingin memahami perasaan sendiri, termasuk rasa bersalah dan kebingungan yang kadang muncul.</p></li>', '2026-02-07 15:39:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15413, 3825, 103318, 'mahasiswa', 'Augusta Ferdiansyah', '<p>1. Gimana ya kak ceritanya kalo di ketik bakal panjang. Sebenernya banyak sesuatu hal yang diluar dugaan dan banyak hal yang tidak sesuai dengan ekspetasi. Saya bakal cerita lebih lengkap pada saat sudah di ruangan kak</p> <p>2. Bisa dibilang saya tipe orang yang gampang cemas akan hal yang terjadi, untuk menganggu mungkin lebih ke susah fokus karena memikirkan hal tersebut</p> <p>3. Kemarin sempat ke psikiater tapi mungkin kurang cocok belum sepenuhnya lega dan respon dari psikiater tersebut kurang baik. Maka dari itu saya mencoba ke psikolog</p> <p>4. Semoga bisa menemukan titik terang dan kondisi mental saya segera membaik</p>', '2026-02-07 15:47:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15414, 3827, 101757, 'mahasiswa', 'Alifah Anggrainy', '<p>masalah ini cukup sensitif, sehingga saya cuman perlu membahas secara keeluruhan saja. saya sedang mengalami trauma dari sebuah hubunganb, ditambah dengan struggle biaya kuliah mengharuskan saya beekrja sambil berkuliah. daya merasa burnout, dan mati rasa. saya bingung bagaimana meminta bantuan ke orang lain, bahkan saya sudah mencoba konsultasi dengan psikolog lain. tapi, saya maish belum menemukan solusi atas masalah saya, atau setidaknya ada perubahan besar dalam kondisi mental saya.</p>', '2026-02-07 16:07:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15415, 3826, 34, 'admin', 'Heidemarie Gunarso', '<p dir="ltr">Selamat sore, Kak Fransiska!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Berikut opsi jadwal yang dapat Anda pilih:</p> <p dir="ltr">- Selasa, 10 Februari 2026 pukul 08.00 (daring/luring)<br />- Selasa, 10 Februari 2026 pukul 13.00 (daring/luring)<br />- Rabu, 11 Februari 2026 pukul 08.00 (daring/luring)<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa :)</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /></p>', '2026-02-07 16:14:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15416, 3825, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak, terima kasih atas jawabannya. Terima kasih karena telah berkenan untuk menceritakan permasalahan Anda dan apa yang Anda rasakan. Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Berikut opsi jadwal yang dapat Anda pilih:</p> <p dir="ltr">- Senin, 9 Februari 2026 pukul 11.00 (daring/luring)<br />- Senin, 9 Februari 2026 pukul 13.00 (daring/luring) <br />- Kamis, 12 Februari 2026 pukul 13.00 (daring/luring)<br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa :)</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /></p>', '2026-02-07 16:25:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15417, 3827, 37, 'admin', 'Allysa Dewantari', '<p>Selamat sore, Kak Alifah! <br />Terima kasih karena telah menghubungi Layanan Konseling UB. Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Kami sangat memahami pasti situasi ini tidak mudah untuk dilalui. Kami mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah berkenan jika kami jadwalkan konseling bersama psikolog/tenaga profesional kami atas nama Bu Yunita pada <strong>Rabu, 18 Februari 2026 pukul 11.00 secara offline</strong>? </p> <p>Kami tunggu konfirmasinya yaa… :)</p> <p dir="ltr">Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-02-07 16:29:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15418, 3825, 103318, 'mahasiswa', 'Augusta Ferdiansyah', '<p>-kamis 12 februari 2026 pukul 13.00 luring</p> <p>Izin bertanya kak jika nantinya saya ingin mengubah jam di hari kamis tersebut apakah bisa? Soalnya masih mau menyocokkan jadwal </p>', '2026-02-07 16:58:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15419, 3828, 103319, 'mahasiswa', 'Cut Aqila', '<p>Semenjak pasca covid kehidupan sosialku memburuk karena tidak ada satupun kelompok pertemanan yang awet dan bertahan lama, paling lama satu semester lalu hilang begitu saja. I tried being myself, I tried being someone I''m not just to fit in but it never works. Mungkin untuk beberapa orang itu sebuah permasalahan yang sepele karena ujung2nya mereka punya kelompoknya masing-masing, tapi aku selalu berujung sendirian. Hal yang paling baru terjadi adalah disini. Aku ditinggalkan karena aku mendekati seseorang yang ternyata sedang mereka hindari, tapi aku juga tidak tahu permasalahannya sebelumnya, but the damage has been done. Bedasarkan pengalamanku bertahun2 sebelumnya aku takut, aku takut kehidupanku akan terulang seperti dulu. Senang dan enjoy di awal, tapi ujung-ujungnya sendirian. I just want a friend group, but it never works on me and it hurts a lot. Aku gatau kedepannya bakal gimana, tapi aku beneran takut banget hal itu terulang lagi dan lagi </p>', '2026-02-07 17:00:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15420, 3825, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik, terima kasih konfirmasinya, Kak. <br /><br />Jika ingin mengubah jam, kami harus konfirmasi terlebih dahulu ketersediaannya psikolognya. Namun, untuk jadwal pukul 13.00 itu psikolognya sudah bersedia, Kak. Untuk sementara waktu, saya jadwalkan pukul 13.00 terlebih dahulu ya, Kak. Jika Kakak ada perubahan, silakan untuk menghubung WhatsApp Layanan Konseling. <br /><br />Terima kasih, <br />Salam hangat, <br />Tim Konseling UB. <br /></p>', '2026-02-07 17:22:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15421, 3828, 37, 'admin', 'Allysa Dewantari', '<p>Selamat sore, Kak Fayyaza!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Kami sangat memahami pasti situasi ini tidak mudah untuk dilalui. Kami mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p>1. Apakah Anda berkenan mendeskripsikan lebih detail masalah yang Anda alami? Menurut Anda apa penyebab hal tersebut terjadi?</p> <p>2. Dari yang Anda rasakan, sudah berapa lama masalah tersebut berdampak ke kegiatan keseharian Anda?</p> <p>3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p>4. Apa harapan Anda menghubungi layanan kami?</p> <p>Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p>Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-02-07 17:30:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15422, 3828, 34, 'admin', 'Heidemarie Gunarso', '<p dir="ltr">Selamat sore, Kak Cut Aqila!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail masalah yang Anda alami? Menurut Anda apa penyebab hal tersebut terjadi?</p> <p dir="ltr">2. Dari masalah yang Anda alami, apa efeknya ke kegiatan keseharian Anda? Dan apakah sudah sangat mengganggu?<br /></p> <p dir="ltr">3. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.<br /><br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa :)</p> <p dir="ltr">Terima kasih,</p> <p dir="ltr">Salam hangat,</p> <p dir="ltr">Tim Konseling UB.<br /></p>', '2026-02-07 17:33:55');
