INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15435, 3805, 37, 'admin', 'Allysa Dewantari', '<p>Mohon maaf kak, kami baru cek kembali jadwal yg sudah terupdate untuk hari kamis minggu depan sudah full kak. Sekiranya kami bantu jadwalkan ulang pada hari berikut:<br />- Selasa,10 februari pukul 08.00 (daring/luring) <br />- Rabu, 11 februari pukul 09.00 (daring/luring)<br />Mohon konfirmasinya kembali diantara 2 jadwal berikut ya kak… :)<br /></p> <p>Terima kasih. <br />Salam hangat, <br />Layanan Konseling UB.<br /></p>', '2026-02-07 19:34:27');
