INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15446, 3818, 37, 'admin', 'Allysa Dewantari', '<p>Baik, terima kasih atas konfirmasinya Kak Raihan. Apakah berkenan jika kami jadwalkan konseling bersama peer counselor laki-laki pada:<br />- <strong>Selasa, 10 Februari pukul 10.00 secara (offline)</strong><br />- <strong>Rabu, 11 Februari pukul 10.00 secara (offline)</strong></p> <p>Silakan memilih salah satu jadwal yang tersedia ya kak..</p> <p>Kami tunggu konfirmasinya yaa… :)</p> <p dir="ltr">Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-02-07 21:29:47');
