INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15470, 3833, 37, 'admin', 'Allysa Dewantari', '<p>Baik, Kak Febian. Terima kasih konfirmasinya, akan kami jadwalkan ya kak. <br />Untuk informasi lebih lanjut akan kami hubungi lewat WA yaa kak.. :)</p> <p>Terima kasih. <br />Salam hangat, <br />Layanan Komseling UB.</p>', '2026-02-08 16:59:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15471, 3836, 103324, 'mahasiswa', 'Alya Nabila', '<p>saya merasa terlalu banyak menerima sesuatu yang buruk sedari dulu tapi saya selalu menahan sendiri sehingga saya saya seperti mau meledak ketika ketrigger banyak hal. saya rasa ini semua gabungan trauma sedari kecil. dari keluarga saya yang seringkali hampir bubar. saya yang selalu mau pergi dari rumah. saya lahir dari keluarga yang keras. keuangan juga hal yang bikin hidup berantakan. ketimpangan antara keluarga ibu dan keluarga ayah. saya jadi merasa sendiri, harus selalu bisa sendiri, kehilangan arah, jd people pleaser, mengganggu konsentrasi, kehilangan dan meninggalkan banyak teman. setiap kali ketrigger sesuatu saya secara otomatis menangis bahkan berlarut, nangis sampai tremor.</p>', '2026-02-08 17:30:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15472, 3832, 102370, 'mahasiswa', 'Kayla', '<p>1. Saya itu mood swing dan seringkali penyebabnya tidak jelas, apalagi kalau sedang mood buruk, saya sulit mengendalikannya. Saya rasa penyebabnya karena akhir-akhir ini saya merasa mudah sakit hati ataupun tersinggung, padahal kalau dipikir-pikir itu sebenarnya bukan masalah yang besar. </p> <p>2. Lumayan berefek karena emosi saya jadi naik turun dan membuat saya stress. Rasanya di kepala seperti ada benang kusut. Selain itu, itu juga berdampak bagi saya dalam bersosialisasi.</p> <p>3. Saya sejujurnya bingung harus mulai dari mana karena masalah dalam diri saya cukup banyak sehingga saya tidak tahu harus mengurai yang mana dulu. Terkadang saya berhasil mengendalikan emosi saya, tapi di lain hari saya tidak bisa.</p> <p>4. Setidaknya beban dalam pikiran saya berkurang. </p> <p><br /></p> <p>Sebenarnya saya bingung gimana bilangnya </p>', '2026-02-08 17:36:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15473, 3836, 37, 'admin', 'Allysa Dewantari', '<p>Selamat sore, Kak Alya!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Kami sangat memahami pasti situasi ini tidak mudah untuk dilalui. Kami mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p>1. Apakah Anda berkenan mendeskripsikan lebih detail masalah yang Anda alami? Menurut Anda apa penyebab hal tersebut terjadi?</p> <p>2. Dari yang Anda rasakan, sudah berapa lama masalah tersebut berdampak ke kegiatan keseharian Anda?</p> <p>3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p>4. Apa harapan Anda menghubungi layanan kami?</p> <p>Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-02-08 18:19:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15474, 3832, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik, terima kasih atas jawabannya. Untuk mendiskusikan lebih lanjut mengenai permasalahan yang Anda alami, kami menyarankan untuk melakukan konseling dengan psikolog kami. Apakah Anda berkenan untuk melakukan konseling dengan psikolog kami? Jadwal sesi konseling ada pada hari <strong>Rabu, 11 Februari 2026 pukul 09.00 WIB.</strong> </p> <p>Kami tunggu konfirmasinya yaa :) </p> <p>Terima kasih, </p> <p>Salam hangat, </p> <p>Tim Konseling UB. </p>', '2026-02-08 19:34:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15475, 3832, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik, terima kasih atas jawabannya. Untuk mendiskusikan lebih lanjut mengenai permasalahan yang Anda alami, kami menyarankan untuk melakukan konseling dengan psikolog kami. Apakah Anda berkenan untuk melakukan konseling dengan psikolog kami? Jadwal sesi konseling ada pada hari <strong>Rabu, 11 Februari 2026 pukul 09.00 WIB secara luring/daring. </strong></p> <p>Kami tunggu konfirmasinya yaa :) </p> <p>Terima kasih, </p> <p>Salam hangat, </p> <p>Tim Konseling UB. </p>', '2026-02-08 19:34:42');
