INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15484, 3820, 103316, 'mahasiswa', 'Nabila Anandira', '<p>Mohon maaf karena keterlambatan dalam menjawab, saya baru melihat pesannya. Apabila pertemuan jadi dijadwalkan besok, saya bersedia. Namun, kalau pertemuan dimundurkan saya juga tidak masalah. Terima kasih</p>', '2026-02-08 22:23:27');
