INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15501, 3841, 103100, 'mahasiswa', 'Dorothea Larasati', '<p>Saya memiliki masalah keuangan yang menghambat saya untuk berkembang. Saya sudah melakukan rencana bunuh diri dengan meminum Paracetamol tidak sesuai dosis namun tidak berhasil. Kendala lain adalah saya merasa buruk karena mendapatkan dosen dan peminatan jurusan tidak sesuai harapan saya  karena terlambat mengisi KRS. Saya berencana untuk melakukan bunuh diri karena kasus ini sudah ada sejak SMA namun belum terselesaikan. </p>', '2026-02-09 13:04:38');
