INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15511, 3842, 102288, 'mahasiswa', 'Rizky Simbolon', 'Tahun lalu saya di diagnosa bipolar 1, akan tetapi tidak ada pengisian kuesioner dari pihak rumah sakit, kemudian juga saya ingin tanyakan beberapa hal bersifat pribadi', '2026-02-09 17:16:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15512, 3840, 32, 'admin', 'Almira Jessenia', '<p>Halo Kak Elionora, untuk tempat pelaksanaan konseling adalah di Gedung Rektorat Universitas Brawijaya lantai 1, yaa. Kakak bisa segera konfirmasi ke kami jika di jam tersebut kakak berhalangan hadir agar kami bantu carikan jadwal lain :)<br /><br />Salam hangat,<br />Tim Konseling UB</p>', '2026-02-09 17:29:39');
