INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15589, 3856, 101756, 'mahasiswa', 'Verdian Putra', '<p>Halo.. jadi ahkir ahkir ini sering berdebar gelisah jantung... punya masalah peeut dan asam lambung aetahun terahkir. Dimulai dari banyak luka di masa lalu, kehilangan teman, sempet menarik diri dan gaberani kuliah, ptsd ketemu orang, fear of judgement, bingung menentukan pilihan karir</p>', '2026-02-11 16:55:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15590, 3845, 102559, 'mahasiswa', 'Iqbal Hidayat', '<p>halo kak maaf baru respon, untuk detailnya itu saya ngerasa menjadi beban bagi ortu, karrna mereka selalu berhutang untuk biaya kuliah saya diawal , meskipun saya sudah pakai kipk,</p> <p>sangat memgganggu, dan sering kepikiran</p> <p>menjadi lebih baik kak, dan menemukan solusi</p> <p>izin tanya kak, untuk jadwal dengan psikolog kira kira kapan ya? terima kasih</p>', '2026-02-11 17:01:35');
