INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15626, 3861, 32, 'admin', 'Almira Jessenia', '<p>Halo, selamat sore Kak Fathina :) <br />Terima kasih yaa karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk membantu kami lebih memahami permasalahan Anda, silakan untuk menjawab pertanyaan berikut, yaa:</p> <ol><li dir="ltr"><p dir="ltr">Bisa diceritakan sedikit, terkait topik permasalahan kakak? apakah berfokus pada akademik, hubungan sosial, atau lainnya?</p></li><li dir="ltr"><p dir="ltr">Apakah permasalahan ini mengganggu aktivitas sehari-hari Anda?</p></li><li dir="ltr"><p dir="ltr">Apa harapan Anda untuk melakukan konseling bersama Layanan Konseling UB?</p></li></ol> <p dir="ltr">Apapun jawaban yang Anda berikan akan sangat membantu kami untuk memetakan permasalahan lebih lanjut dan menjadwalkan sesi dengan tepat. Tetapi, jika kakak tidak nyaman untuk menjawab beberapa pertanyaan, maka bisa disampaikan bahwa kakak tidak berkenan menjawab.<br /><br />Terima kasih<br />Salam hangat, <br />Tim Konseling UB.</p> <p><br /></p>', '2026-02-12 17:29:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15627, 3860, 35, 'admin', 'Melsy Nemasari', '<p>Baik, terima kasih atas jawabannya Kak. Kami memahami pasti sangatlah tidak mudah dalam menjalaninya. Oleh karena itu kami menyediakan layanan konseling bersama <strong><em>peer counselor/</em>konselor sebaya</strong> kami, Kak. Sebelumnya saya izin bertanya apakah Kakak berkenan jika melakukan konseling secara <em><strong>online </strong></em>melalui <em><strong>google meet? <br /><br /></strong></em>Kami tunggu konfirmasinya ya, Kak :)<em><strong><strong><br /></strong></strong></em>Terima kasih.</p> <p>Salam hangat,<br />Layanan Konseling UB.</p>', '2026-02-12 17:30:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15628, 3861, 32, 'admin', 'Almira Jessenia', '<p>Halo, selamat sore Kak Fathina :) <br />Terima kasih yaa karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk membantu kami lebih memahami permasalahan Anda, silakan untuk menjawab pertanyaan berikut, yaa:</p> <ol><li dir="ltr"><p dir="ltr">Bisa diceritakan sedikit, terkait topik permasalahan kakak? apakah berfokus pada akademik, hubungan sosial, atau lainnya?</p></li><li dir="ltr"><p dir="ltr">Apakah permasalahan ini mengganggu aktivitas sehari-hari Anda?</p></li><li dir="ltr"><p dir="ltr">Apa harapan Anda untuk melakukan konseling bersama Layanan Konseling UB?</p></li></ol> <p dir="ltr">Apapun jawaban yang Anda berikan akan sangat membantu kami untuk memetakan permasalahan lebih lanjut dan menjadwalkan sesi dengan tepat. Tetapi, jika kakak tidak nyaman untuk menjawab beberapa pertanyaan, maka bisa disampaikan bahwa kakak tidak berkenan menjawab.<br /><br />Terima kasih<br />Salam hangat, <br />Layanan Konseling UB.</p> <p><br /></p>', '2026-02-12 17:29:02');
