INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15639, 3863, 103338, 'mahasiswa', 'YENNI GINTING', '<p>Saya adalah seorang mahasiswi yang akan lulus kuliah dan memiliki target pekerjaan tertentu tetapi belum memiliki pengalaman kerja pada posisi yang diinginkan serta belum mengetahui arah dan motivasi untuk ke depannya.</p>', '2026-02-13 01:28:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15640, 3864, 103339, 'mahasiswa', 'Muhammad Haq', '<p>Jadi, saya sendiri bingung kenapa orang lain bisa akrab dengan orang lain dengan mudah sementara saya sangat susah sekali mengabrakan diri dengan orang lain, saya lihat sifat orang padahal kalem dan pendiem tetap dapat teman yang bisa akrab sementara saya kalau menjadi kalem dan pendiam malah orang orang mengucilkan saya, maka dari itu saya coba dengan sifat rame dan tetap saja orang tidak suka dan malah tambah membenci saya, jadi syaa bingung apa yang harus saya lakukan</p>', '2026-02-13 01:46:34');
