INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15815, 3896, 33, 'admin', 'Nafa Tsaniya', '<p>Halo, selamat pagi Kak Aprilia:)<br />Terima kasih karena telah berkenan menjelaskan lebih detail permasalahan yang sedang Kakak alami. Untuk membantu mencari jalan keluar dari permasalahan Kakak, kami menyarankan untuk bertemu dengan konselor kami pada hari Selasa<strong>, 24 Februari 2026 pukul 12.00 WIB secara online</strong>. Apakah kiranya kakak berkenan dijadwalkan pada hari dan jam tersebut? Kami tunggu konfirmasinya, yaa...<br /><br />Terima kasih<br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-02-22 02:56:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15816, 3896, 103363, 'mahasiswa', 'Aprilia', '<p>kalau online via apa kalo boleh tau? soalnya aku nyaman ngomong langsung, terus apakah harus lewat konselor dulu? apa bisa langsung psikolog?</p>', '2026-02-22 11:14:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15817, 3889, 33, 'admin', 'Nafa Tsaniya', '<p>Halo, selamat siang Kak Maulana :)<br />Terima kasih karena telah berkenan menjelaskan lebih detail permasalahan yang sedang Kakak alami. Untuk membantu mencari jalan keluar dari permasalahan Kakak, kami menyarankan untuk bertemu dengan Psikolog kami pada hari Kamis<strong>, 26 Februari 2026 pukul 09.00 WIB secara offline</strong>. Apakah kiranya kakak berkenan dijadwalkan pada hari dan jam tersebut? Kami tunggu konfirmasinya, yaa...<br /><br />Terima kasih<br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-02-22 12:13:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15818, 3896, 33, 'admin', 'Nafa Tsaniya', '<p>Jika via online melalui gmeet ya ka:) Baik ka, jika kakak lebih nyaman untuk bertemu langsung, kami tersedia jadwal Psikolog pada Selasa, 24 Februari 2026 pukul 10.00 secara offline, apakah kakak berkenan kami jadwalkan pada waktu tersebut?</p>', '2026-02-22 12:29:24');
