INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15823, 3879, 33, 'admin', 'Nafa Tsaniya', '<p>Baik ka, kami menyarankan untuk kakak bertemu dengan <em>peer conselour </em>kami, jadwal yang tersedia ada pada hari <strong>Kamis, 26 Februari 2026 pukul 11.00</strong> atau pada hari <strong>Jumat, 27 Februari 2026 pukul 10.00 </strong>secara <strong>offline. </strong>Apakah kiranya kakak berkenan dijadwalkan diantara kedua jadwal tersebut? Kami tunggu konfirmasinya, yaa...<br /></p>', '2026-02-22 15:12:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15824, 3881, 103286, 'mahasiswa', 'Tsaquila Miolo', '<p>Selamat sore, untuk hari Senin, 23 Februari saya belum bersedia secara offline, dikarenakan keadaan yg saat ini masih kurang fit. Kira-kira kalau dijadwalkan secara online pada hari yang sama apakah bisa? dan kira-kira di pukul berapa? Terima kasih dan maaf sebelumnya.</p>', '2026-02-22 16:17:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15825, 3897, 103364, 'mahasiswa', 'Evelyn', '<p>Saya ingin menghilangkan sifat prokrastinasi yang sangat menganggu ini. Kesulitan untuk melawan rasa malas. Akhir akhir ini lebih sering main hp. Rasa bersalah selalu ada tetapi tidak berubah dan tidak berusaha lebih baik. Sulit untuk termotivasi. Bukannya termotivasi melihat org lain, tetapi semakin inferior, frustrasi, dan tidak percaya diri. Akhir-akhir ini juga tidur tidak nyenyak. Sering ngantuk tapi tidak bisa tidur. Sulit mengerjakan tugas kalau tidak ada deadline. Baru dikerjain kalo udah ditagih. Selalu cemas tapi gak pernah melakukan sesuatu untuk memperbaikinya karena saya selalu takut salah.</p>', '2026-02-22 16:24:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15826, 3898, 103365, 'mahasiswa', 'Galih Maharani', '<p>saya akhir” ini sering mendapat trigger dari pasangan saya karna dia melontarkan ancaman setiap ada masalah, sudah terjadi 2 kali ini dan setiap dia mengancam saya merasa badan saya tremor dan kesemutan sebadan” saya menangis tidak karuan, jantung saya berdebar, dan saya merasa pusing hanya bisa duduk tidak bisa berdiri karna lutut saya bergetar, sekarang saya jadi terbayang” dengan ancaman itu sampai cemas setiap hari dan takut dengan orang</p>', '2026-02-22 17:18:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15827, 3899, 103365, 'mahasiswa', 'Galih Maharani', '<p>saya akhir” ini sering mendapat trigger dari pasangan saya karna dia melontarkan ancaman setiap ada masalah, sudah terjadi 2 kali ini dan setiap dia mengancam saya merasa badan saya tremor dan kesemutan sebadan” saya menangis tidak karuan, jantung saya berdebar, dan saya merasa pusing hanya bisa duduk tidak bisa berdiri karna lutut saya bergetar, sekarang saya jadi terbayang” dengan ancaman itu sampai cemas setiap hari dan takut dengan orang</p>', '2026-02-22 17:18:44');
