INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15829, 3900, 103365, 'mahasiswa', 'Galih Maharani', '<p>saya mendapat ancaman dari pasangan dan saya 2 kali ini saya tremor ketika mendapat trigger sampai tremor sebadan dan kesemutan jantung detak lebih kencang badan dingin tapi panas takut dengan orang cemass dan lutut tidak bisa jalan karna tremor berlebih saya sudah berusaha mengakhiri hubungan tetapi dia menggunakan suatu hal untuk mengancam saya</p>', '2026-02-22 17:39:37');
