INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15862, 3897, 34, 'admin', 'Heidemarie Gunarso', '<p>Selamat siang, Kak Evelyn! <br /><br />Baik Kak, terima kasih atas jawabannya. Terima kasih karena telah berkenan untuk menceritakan permasalahan Anda dan apa yang Anda rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk membantu mencari jalan keluar dari permasalahan Anda, kami menyarankan Anda untuk bertemu dengan konselor kami. Kami memiliki jadwal yang tersedia pada hari <strong>Selasa, 24 Februari 2026 pukul 12.00</strong>. Apakah Anda berkenan kami jadwalkan pada waktu tersebut? <br /><br />Mohon konfirmasinya, yaa :)<br /><br />Terima kasih,<br />Salam hangat, <br />Layanan Konseling UB.</p>', '2026-02-23 13:01:09');
