INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15879, 3883, 34, 'admin', 'Heidemarie Gunarso', '<p>Selamat sore, Kak Bima! <br /><br />Baik Kak, terima kasih atas konfirmasinya. Mohon maaf sebelumnya, pada minggu ini jadwal konseling sudah penuh, jadwal dengan psikolog kami baru tersedia di minggu depan. Berikut opsi jadwal yang dapat Anda pilih: </p> <p>- Rabu, 4 Maret 2026 pukul 09.00 (daring/luring) <br />- Rabu, 4 Maret 2026 pukul 13.00 (daring/luring) <br />- Kamis, 5 Maret 2026 pukul 09.00 (daring/luring) <br /><br />Kami tunggu konfirmasinya, yaa :) </p> <p>Terima kasih, <br />Salam hangat, <br />Layanan Konseling UB. </p>', '2026-02-23 16:35:56');
