INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15914, 3901, 103366, 'mahasiswa', 'Nisrina Shobah', '<p>1. saya biasa berpikir saya harusnya tidak melakukan hal tersebut dan lebih baik melakukan hal lain, biasanya saya akan mengulanga kata" itu berkali-kali</p> <p>2. saya dari sma sering merasa hak tersebut tapi biasanya memang hanya diwaktu-waktu tertentu dan saat ini 2 minggu terkahir saya sering merasa tidak bisa tidur atau kadang bisa tidur lebih lama (8 jam ++)</p> <p>3. saya lebih berkenan jika itu dibicarakab secara offline</p> <p>4. saya sering berdiam diri dan lebih banyak menstabilkan emosi saya, saya juga sering untuk mengeluarkan rmosi saya keyika sendiri seperti menangis</p>', '2026-02-24 21:57:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15915, 3902, 103367, 'mahasiswa', 'Muhammad F', '<p>Selamat malam, terimakasih atas konfirmasinya. Kalau masih kososng saya mau untuk melakukan sesi konseling dihari sealasa minggu depan sesuai jadwal yang telah diberikan.<br />Terimakasih banyak sebelumnya</p> <p><br /></p>', '2026-02-24 23:17:45');
