INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15921, 3901, 37, 'admin', 'Allysa Dewantari', '<p>Baik, Kak Nisrina. Terima kasih konfirmasinya. <br />Akan kami bantu jadwalkan konseling bersama<strong><em>peer counselor</em></strong> pada <strong>Selasa, 3 Maret 2026</strong> <strong>pukul 14.00 </strong>secara <strong>daring </strong>ya kak. Informasi selanjutnya akan kami hubungi lewat WhatsApp ya kak. <br /><br />Terima kasih. <br />Salam hangat, <br />Layanan Konseling UB. </p>', '2026-02-25 11:31:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15922, 3907, 103371, 'mahasiswa', 'DAVA PS', '<p>Assalamualaikum wr. wb, perkenalkan saya Dava Ridho mahasiswa Universitas Brawijaya fakultas Pertanian angkatan 2023. Saya berniat secara mental ingin mengajukan konsultasi kepada pihak konseling ub demi kebaikan kedepannya. awal mula, saya kenal seorang perempuan di hidup saya di tahun 2018 sejak sma, seiring berjalannya waktu kami mulai saling mengenal dan di tahap hubungan terikat. kami berstatus pacaran sejak 2018, dia sangat baik, tulus, dan sabar sejak kenal, hal ini yang bikin saya makin tertarik dengan dia. dia selalu tulus dan ikhlas nemenin saya untuk membantu dan merawat ibu saya yang sakit dari awal hingga akhir. Pada tahun 2019, saya kehilangan ibu saya dikarenakan sakit kanker dan dia selalu jadi pelarian saya jika ada masalah ataupun penenang bagi saya selain keluarga lainnya. saya daftar dan masuk kampus bareng2 pada tahun 2022 dan 2023 sampe di tahap puncak hubungan. hubungan yang awalnya baik baik jadi makin memburuk akibat perilaku yang tidak dibenarkan yaitu micro cheating dan perselingkuhan, sejak saat itu hubungan kami makin ga terarah akibat trust issue dari pihak cewe. seiring waktu, hubungan mulai diperbaiki dan membaik selama ber bulan-bulan sampai di tahap terulang. pihak cewe juga melakukan hal yang sama yaitu melakukan kebohongan micro cheating dan perselingkuhan dengan mantan pihak cewe. perselingkuhan ini mungkin tidak bisa dibenarkan, saya berusaha dan menyakini kalah masih bisa diperjuangkan soal hubungan ini demi kedepannya, karena saya sendiri masih sayang dan berharap hubungan ini terakhir karena sudah menemukan yang saya cari soal perempuan,  tetapi seiring waktu hubungan kita membaik dan terulang lagi siklus yang sama dengan masalah sama tidak jauh dari perselingkuhan. hingga kami memutuskan mengakhiri hubungan baik" pada tahun awal 2026 dengan syarat tidak asing dan musuhan. kami masih menjaga komunikasi dan hubungan baik karena masih satu kota, hal yang membedakan mungkin rasa cinta di hubungannya udah mulai berbeda. sebulan kemudian, pihak cewe menemukan orang yang dia mau karena bayak faktor, mulai umur, mapan dan sifat yang dia inginkan. saya disini berusaha buat membantu, menyakini dan mencari solusi jika cowo yang dia mau adalah cowo yang benar. dia selalu bercerita, selalu memuji dari sifat, tindakan dan treat pihak cewe tetapi tetap ada keraguan dikarenakan beda kota. makin lama dengan kebiasaan masih suka bareng di Malang, tiap keluar suka cerita cowo barunya dengan excited, bahkan saya selalu berusaha ikhlas dan tulus dengerin deritanya. mungkin saya salah, meskipun hubungan berakhir masih ada rasa sayang dan sedikit cemburu dikarenakan dipuncak hubungan sebelum berakhir saya masih tidak menyangka masih bisa berakhir, dan bagi dia terasa hampa. ternyata, sebelum mengakhiri hubungan pihak cewe sudah kenal cowo baru dan masih keluar sama mantannya dengan alasan tidak make sense, awalnya bertemu temen cewe tetapi pindah tempat dan di support lingkungan pihak cewe untuk melakukan ini tanpa se pengetahuan saya di hubungan. saya tau semua akibat pihak cewe ke toilet waktu nugas bareng dan saya sengaja buka hp nya dan masih trauma sampe sekarang, saya dari awal hubungan tidak diperbolehkan membuka dan saya open buat dia buka hp saya. hal yang saya permasalahkan disini, bagaimana bisa  pelan-pelan menjalani terapi dan menyembuhkan dengan masalah seperti ini. saya berusaha buat menyembuhkan diri sediri mulai berolahraga, tidur teratur, menyibukan diri melalui organisasi dan kepanitiaan tetapi tetap masih kambuh karena hal ini juga berdampak ke akademik saya dikarenakan menggangu akal dan kesehatan memikirkan hal aneh ini, saya tetap mejaga komunikasi atau mengakhiri pelan pelan dan asing demi mental saya, saya belom siap dengan tetap berkomunikasi karena ada cerita tentang hal baru yang belom saya siap dengarkan, mungkin lebih detailnya saya bisa ceritakan secara langsung. terima kasih<br /></p>', '2026-02-25 12:44:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15923, 3907, 34, 'admin', 'Heidemarie Gunarso', '<p>Selamat siang, Kak Dava! <br /><br />Terima kasih telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p><br /></p> <p dir="ltr">1. Dari permasalahan yang Anda rasakan, apa efeknya ke kegiatan keseharian Anda? Dan apakah sudah sangat mengganggu?<br />2. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?<br />3. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr">Kami tunggu konfirmasinya, yaa :)</p> <p dir="ltr">Terima kasih,<br />Salam hangat,<br />Layanan Konseling UB. <br /></p> <p><br /></p>', '2026-02-25 14:12:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15924, 3907, 103371, 'mahasiswa', 'DAVA PS', '<p>1. untuk efeknya keseharian tentunya iya, karena setiap saya melakukan kegiatan positif mulai kuliah, organisasi, olahraga itu pasti terlupakan sejenak berbeda halnya ketika dikos atau di tempat mana pun saat saya melakukan me time terkadang mengganggu saya atau sakit aja kak, trust issue atau masi belom ikhlas pasti ada</p> <p>2. Saya meluapkan hal ini ke olahraga, organisasi, kumpul dengan teman meskipun jarang karena saya dari awal masuk kuliah selalu bareng terus bahkan megurangi komunikasi dengan teman se perlunya saja, ini kesalahan saya terlalu bergantung pada orang jadi di akhir kekurangan teman</p> <p>3. harapannya saya bisa mendapatkan arahan atau konsultasi setelah bercerita dan bukan hanya dipendam sendiri tanpa ada teman satu pun yg mendengarkan, saya konsultasi dengan pelan" ingin menyembuhkan trauma kaya gini setelah kehilangan Ibu saya</p>', '2026-02-25 14:20:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15925, 3907, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak Dava, terima kasih atas jawabannya. Terima kasih karena telah berkenan untuk menceritakan permasalahan Anda dan apa yang Anda rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk membantu mencari jalan keluar dari permasalahan Anda, kami menyarankan Anda untuk bertemu dengan peer counselor kami. Jika Anda berkenan, silahkan untuk memilih dari beberapa opsi jadwal berikut: </p> <p>- Selasa, 3 Maret 2026 pukul 13.00 WIB (daring/luring) <br />- Rabu, 4 Maret 2026 pukul 15.00 WIB (daring/luring) <br />- Jumat, 6 Maret 2026 pukul 11.00 WIB (daring) </p> <p>Kami tunggu konfirmasinya, yaa :) <br /><br />Terima kasih, <br />Salam hangat, <br />Layanan Konseling UB. </p>', '2026-02-25 15:17:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15926, 3895, 103362, 'mahasiswa', 'Ni Putri', '<p>Selamat sore, kak. Izin mengonfirmasi ulang bahwa pada hari Selasa, 3 Maret 2026 saya tidak bisa untuk mengikuti konseling karena adanya perubahan jadwal praktikum pada jam tersebut. Apakah memungkinkan untuk konseling pada minggu kedua bulan Maret?</p>', '2026-02-25 19:03:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15927, 3895, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak Ni Putri, terima kasih atas konfirmasinya. <br />Untuk jadwal konseling terbaru, akan kami atur terlebih dahulu ya, Kak. Jika kami sudah mengaturnya, akan kami hubungi melalui WhatsApp ya, Kak :) <br /><br />Terima kasih, <br />Salam hangat, <br />Layanan Konseling UB. </p>', '2026-02-25 19:28:45');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15928, 3895, 103362, 'mahasiswa', 'Ni Putri', '<p>Selamat sore, kak. Izin mengonfirmasi ulang bahwa pada hari Selasa, 3 Maret 2026 saya tidak bisa untuk mengikuti konseling karena adanya perubahan jadwal praktikum pada jam tersebut. Apakah memungkinkan untuk konseling pada minggu kedua bulan Maret?</p>', '2026-02-25 19:37:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15929, 3895, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak Ni Putri, terima kasih atas konfirmasinya. <br />Untuk jadwal konseling terbaru, akan kami atur terlebih dahulu ya, Kak. Jika kami sudah mengaturnya, akan kami hubungi melalui WhatsApp ya, Kak :) <br /><br />Terima kasih, <br />Salam hangat, <br />Layanan Konseling UB.</p>', '2026-02-25 19:38:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15930, 3908, 103256, 'mahasiswa', 'Masyaila Rumawan', '<p>saya akhir akhir ini merasa selalu cemas, merasa ada yang mengawasi saya. saya merasa ketakutan yang berlebih, hingga saya sering mimpi buruk. saya seperti dihantui kesalahan masa lalu. saya ingin merasa tenang lagi.</p>', '2026-02-25 21:56:26');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15931, 3908, 37, 'admin', 'Allysa Dewantari', '<p>Selamat malam, Kak Masyaila!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Kami sangat memahami pasti situasi ini tidak mudah untuk dilalui. Kami mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p>1. Apakah Anda berkenan mendeskripsikan lebih detail masalah yang Anda alami? Menurut Anda apa penyebab hal tersebut terjadi?</p> <p>2. Dari yang Anda rasakan, sudah berapa lama masalah tersebut berdampak ke kegiatan keseharian Anda?</p> <p>3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p>4. Apa harapan Anda menghubungi layanan kami?</p> <p>Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-02-25 22:32:22');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15932, 3908, 103256, 'mahasiswa', 'Masyaila Rumawan', '<p>1. yang saya rasakan adalah rasa cemas dan takut yang sangat berlebihan. saya merasa diawasi, saya merasa ada yang mengejar saya. jadi semua hal yang saya lakukan selaku dengan rasa terburu-buru dan tidak tenang. bahkan baju baju bersih saya, baju yang sudah saya laundry, saya cuci ulang sendiri karena rasa cemas dan takut ini. saya juga merasa cemas ketika hendak tidur walaupun itu tidur siang. meskipun saya sudah merasa mengantuk sekali, saya tetap kesulitan untuk tidur. untuk penyebabnya, saya sendiri kurang tau dan bingung sendiri mencari penyebab dari permasalahan ini.</p> <p>2. dari sekitar 4 hari sekitar kuliah pertama. dan ini sangat mengganggu kegiatan saya sehari hari. </p> <p>3. saya sudah melakukan olahraga sebelum berbuka puasa, atau sekedar jalan santai ketika selesai berkuliah, tapi rasanya masih belum teratasi. saya juga sudah melakukan teknik pernapasan sebelum tidur, tapi entah kenapa malah menambah rasa cemas saya seperti "ini kenapa sih aku tidak tidur tidur padahal udah melakukan teknik ini." </p> <p>4. aaya berharap bisa berkonsultasi langsung dengan psikolog yang disediakan secara offline dan saya berharap bisa mendapatkan solusi. karena tidak jarang terlintas dipikiran saya untuk mengakhiri hidup saya sendiri</p>', '2026-02-26 18:36:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15933, 3908, 37, 'admin', 'Allysa Dewantari', '<p>Baik, terima kasih konfirmasinya ya kak. Kami memahami hal tersebut tidak mudah untuk dilalui. Terima kasih telah berkenan membagikan apa yang kakak rasakan yaa.. :) </p> <p>Kami izin follow up terlebih dahulu ya kak. Berdasarkan riwayat rekam konseling yg kami miliki, sebelumnya kakak sudah pernah konseling dengan psikolog kami ya kak. Kalo boleh tau tanggal berapa kakak konseling terakhir dan dengan siapa psikolognya ya kak? Lalu apa yang kakak dapatkan dari sesi konseling terakhir kali? <br />Kami tunggu konfirmasinya ya kak.. :) </p> <p><br />Terima kasih. <br />Salam hangat, <br />Layanan Konseling UB.</p>', '2026-02-26 18:43:17');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15934, 3908, 103256, 'mahasiswa', 'Masyaila Rumawan', '<p>terakhir saya konseling adalah tanggal 23 desember 2025 dengan bapak yafi kak. mohon maaf dengan jujur saya kurang mendapatkan banyak hal dari konseling pertama saya. pada saat itu saya mengkonsultasikan masalah akademik dengan bapak yafi, iya saya sedikit ada rasa lega, tapi overall, saya kurang mendapat manfaatnya kak. justru saya malah bingung dengan apa yang sudah beliau sampaikan. dulu ketika saya berkonsultasi, saya merasa bingung karena merasa tidak cocok dengan jurusan saya, tapi beliau malah bilang "take it or leave it." kurang lebihnya jadi saya merasa bingung kak. maaf kalau apa yang saya sampaikan terlalu bertele-tele</p>', '2026-02-26 18:49:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15935, 3909, 103373, 'mahasiswa', 'Marjorie Firdaus', '<p>Saya suka merasa memikirikan hal yang tidak perlu secara berlebihan menjadikan kepala saya merasa sakit dan akhirnya tidak melakukan hal yang produktif. Dan juga gampang lelah dan tidak gampang puas dengan pencapaian karena sibuk menyari validasi dari orang lain</p>', '2026-02-26 18:53:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (15936, 3908, 103256, 'mahasiswa', 'Masyaila Rumawan', '<p>terakhir saya konseling adalah tanggal 23 desember 2025 dengan bapak yafi kak. mohon maaf dengan jujur saya kurang mendapatkan banyak hal dari konseling pertama saya. pada saat itu saya mengkonsultasikan masalah akademik dengan bapak yafi, iya saya sedikit ada rasa lega, tapi overall, saya kurang mendapat manfaatnya kak. justru saya malah bingung dengan apa yang sudah beliau sampaikan. dulu ketika saya berkonsultasi, saya merasa bingung karena merasa tidak cocok dengan jurusan saya, tapi beliau malah bilang "take it or leave it." kurang lebihnya jadi saya merasa bingung kak. maaf kalau apa yang saya sampaikan terlalu bertele-tele</p>', '2026-02-26 19:20:44');
