INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16080, 3931, 103390, 'mahasiswa', 'Elsa Soraya', '<p>1. sebelumnya saya sudah pernah merasakan ini ketika awal masuk perkuliahan di masa ospek. lalu kemarin setelah liburan semester ada gejala yg timbul lagi tapi masih bisa saya atasi. kondisi ini jadi memburuk ketika banyaknya berita yang beredar mengenai terjadinya perang dan keluarnya tanda tanya kiamat itu. tidak tau kenapa respon tubuh saya sangat parah saat itu, banyak pemikiran buruk yang muncul di gambaran pikiran saya, sampai saya mual, ga tenang, pengen nangis terus, dan banyak hal yg saya rasakan sampe saya ga berani menatap anggota kelurga saya karena alasan tersebut, saya takut gitu. jantung saya berdebar tidak karuan, gemetar dan merasa tidak nyaman. kata psikiater kenalan saya, saya mengalami anxiety attack</p> <p>2. mungkin sudah hampir seminggu </p> <p>3. saya konsultasi ke psikiater kenalan saya, tapi ada hambatan respon jadi saya bingung harus gimana. dan apa yg saya rencanakan itu, mungkin saya butuh bantuan yg lebih ahli untuk menangani permasalahan saya ini</p> <p>4. semoga ada jalan keluar dan saya bisa kembali ke aktivitas seperti biasa tanpa adanya rasa ketakutan</p>', '2026-03-04 09:59:27');
