INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16102, 3712, 32, 'admin', 'Almira Jessenia', '<p>Selamat sore Kak Guido :)<br /><br />Baik Kak terima kasih konfirmasinya, untuk informasi lebih lanjut terkait sesi konseling besok akan kami sampaikan melalui WhatsApp yaa. Apabila Kakak berhalangan hadir, mohon dapat menginformasikan kepada kami minimal 30 menit sebelum sesi dimulai agar dapat kami bantu untuk reschedule. Proses reschedule juga akan kami koordinasikan melalui WhatsApp.<br /></p> <p>Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.<br /></p>', '2026-03-04 16:45:07');
