INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16109, 3935, 32, 'admin', 'Almira Jessenia', '<p>Selamat pagi Kak Nur Hamida :)<br />Terima kasih konfirmasinya yaa.. Jika di hari yang sama pukul 09.00 apa berkenan? dengan Psikolog kami atas nama Bu Yunita. Kami tunggu konfirmasinya yaa :)<br /><br />Salam hangat, <br />Layanan Konseling UB</p>', '2026-03-05 08:54:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16110, 3933, 32, 'admin', 'Almira Jessenia', '<p>Selamat pagi Kak Ahmad! <br /><br />Terima kasih telah berkenan untuk menceritakan lebih detail terkait permasalahan Anda. Untuk membantu mencari jalan keluar dari permasalahan Anda, kami menyarankan Anda untuk bertemu dengan Psikolog kami. Kami memiliki jadwal yang tersedia pada <strong>Hari Senin, 9 Maret 2026 pukul 10.00 WIB (luring) </strong>dengan <strong>Ibu Naila</strong>. Apakah Anda berkenan kami jadwalkan pada waktu tersebut? Mohon konfirmasinya, yaa. <br /><br />Terima kasih.<br />Salam hangat, <br />Layanan Konseling UB.</p>', '2026-03-05 09:01:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16111, 3925, 35, 'admin', 'Melsy Nemasari', '<p>Selamat malam, Kak Johanes!<br /><br />Baik, terima kasih atas konfirmasinya. Apabila konseling dilakukan pada Jumat, 6 Maret 2026 pukul 13.00 secara offline apakah berkenan, Kak? Kami tunggu konfirmasinya yaa :)<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-03-03 19:12:42');
