INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16129, 3938, 32, 'admin', 'Almira Jessenia', '<p>Selamat siang, Kak Khansa :)<br />Untuk membantu mencari jalan keluar dari permasalahan Anda, kami menyarankan Anda untuk bertemu dengan peer counselor / konselor kami. Kami memiliki jadwal yang tersedia pada:<br />1. <strong>Senin, 9 Maret 2026 pukul 09.00 WIB (luring)</strong> dengan <strong>Peer Counselor / Konselor Sebaya perempuan </strong>atas nama <strong>Kak Aura</strong><br />2. <strong>Selasa, 10 Maret 2026 pukul 12.00 WIB (daring) </strong>dengan <strong>Konselor perempuan </strong>atas nama <strong>Kak Andini<br /></strong><br />Silakan memilih salah satu jadwal yang kiranya Kakak berkenan, yaa. Kami tunggu konfirmasinya :)<br />Terima kasih.<br />Salam hangat, <br />Layanan Konseling UB.</p>', '2026-03-06 14:10:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16130, 3929, 32, 'admin', 'Almira Jessenia', '<p>Untuk jadwal dengan Ibu Ikaf tersedia lagi di Hari Senin tanggal 16 Maret 2026 pukul 10.00 WIB. Apakah kiranya berkenan dijadwalkan pada tanggal tersebut, atau setelah lebaran saja? Kami mohon maaf atas ketidaknyamanannya yaa Kak, dikarenakan banyaknya permintaan konseling yang masuk.<br /><br />Kami tunggu konfirmasinya, yaa..<br /><br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-03-06 14:13:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16131, 3929, 103389, 'mahasiswa', 'Hilma Laily', '<p>Setelah lebaran saja, Kak. Saya tidak masalah dengan hal itu. Terima kasih banyak atas bantuannya ya, Kak.</p>', '2026-03-06 14:21:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16132, 3929, 35, 'admin', 'Melsy Nemasari', '<p>Baik, apabila konseling dengan <strong>Bu Ika pada Senin, 30 Maret 2026 pukul 10.00 WIB</strong> apakah berkenan, Kak? <br />Kami tunggu konfirmasinya, yaa..<br /><br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-03-06 14:28:44');
