INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16134, 3929, 35, 'admin', 'Melsy Nemasari', '<p>Baik, terima kasih atas konfirmasinya. Selanjutnya akan kami hubungi melalui WhatsApp yaa :)<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-03-06 14:33:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16135, 3910, 103372, 'mahasiswa', 'Farras Hanun', '<p>Halo terimakasih sudah memberikan opsi lain, tetapi mohon maaf untuk hari rabu dan kamis di minggu itu saya masuk magang</p>', '2026-03-06 16:52:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16136, 3934, 103395, 'mahasiswa', 'Gerardo Suwantono', '<p>Hai, terima kasih atas responsnya, maaf atas keterlambatan membalas. Berkenaan hal tersebut, sebenernya saya dari lama ingin konsultasi dengan ahli secara tatap muka 1-on-1 untuk berbicara tentang kesehatan mental saya. Saya merasa tidak memiliki kapabilitas untuk selfclaim apakah apa yang bertahun2 saya alami ini termasuk stres ringan, mengingat masalah yang saya alami juga bukan terlalu hebat dan mungkin terkesan dilebih-lebihkan. </p> <p>1. saya berkenan menceritakannya, saya sulit punya teman, saya sering memikirkan kesalahan atau kejadian di masa lalu yang tidak mengenakan, saya sulit untuk bahagia (bahkan kebahagiaan2 kecil), saya sangat takut mengecewakan orang, saya merasa kurang apresiasi, saya merasa selama ini saya sering membandingkan diri dengan orang lain dengan cara menyombongkan diri dengan alasan menutup kekurangan saya, saya suka judge orang lain, saya rasa hal tersebut terjadi karena lingkungan membentuk saya dari hari ke hari, mulai dari masa kecil</p> <p>2. sebenarnya dari zaman smp (terutama covid) saya merasa sangat stres, saya berkali2 ingin ke psikolog sampai bicara ke orang tua, tapi tidak pernah mendapat titik temu, hanya "iya nanti ya" "iya nanti ya"</p> <p>3. kebetulan saya punya pasangan, saya sering cerita ke beliau terkait masalah ini. namun, menjawab pertanyaan itu, sebenernya saya juga kurang tau apa yang selama ini saya lakukan selain berpura-pura "aman". saya merasa bingung mau cerita ke siapa selain ke pasangan saya.</p> <p>4. sesuai dengan poin nomor 1, apakah saya dapat konsultasi secara langsung? jika iya, bagaimana caranya? saya sama sekali buta tentang layanan ini, harus ke mana, dengan siapa, jam berapa. jika boleh, apakah hari kamis 12 maret 2026 sekitar sore menjelang malam saya bisa berkonsultasi?</p> <p>terima kasih banyak kak/pak/bu, semoga berkenan</p> <p>Gerardo Reuben Arsenio Suwantono</p> <p><br /></p>', '2026-03-06 18:39:14');
