INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16158, 3943, 100534, 'mahasiswa', 'Fahreza', '<p>1. anxious attachment dalam hubungan</p> <p>2. constantly need reassurance, presence</p> <p>3. anxiety berlebihan ketika pasangan absence</p> <p>4. saya rasa ini karena inconsistent affection dari org tua semasa kecil</p> <p>5. hubungan terasa seperti PR yg begitu berat dan tidak bisa diselesaikan</p>', '2026-03-08 12:26:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16159, 3943, 35, 'admin', 'Melsy Nemasari', '<p>Selamat siang, Kak Fahreza:)<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Terima kasih telah berkenan berbagi perasaan dan cerita yang Kakak miliki. Kami sangat memahami pasti situasi ini tidak mudah untuk dilalui. Untuk memperdalam pemahaman kami terhadap permasalahan Kakak, berkenankah untuk menjawab beberapa pertanyaan berikut:</p> <p>1. Apakah Kakak berkenan mendeskripsikan lebih detail masalah yang sedang dialami? </p> <p>2. Dari yang Kakak rasakan, sudah berapa lama masalah tersebut berdampak ke kegiatan keseharian Kakak?</p> <p>3. Apa hal yang sudah Kakak lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p>4. Apa harapan Kakak menghubungi layanan kami?</p> <p>Apapun jawaban Kakak akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Kakak tidak berkenan menjawab, Kakak juga bisa menyampaikan bahwa tidak berkenan menjawab pertanyaan yang kami tanyakan.<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-03-08 12:39:05');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16160, 3943, 100534, 'mahasiswa', 'Fahreza', '<p>1. hubungan saya tidak pernah berjalan mulus atau berlanjut karena anxious attachment saya. saya selalu merasa membutuhkan reassurance atau presence dari pasangan. sekalipun saya sibuk, saya constantly mengecek telepon genggam untuk melihat apakah mereka sudah membalas pesan dan sebagainya. hubungan romantis tidak pernah memberi rasa damai bagi saya. constant anxiety.</p> <p>2. sudah bertahun tahun dan berdampak ke hubungan saya dengan significant other.</p> <p>3. saya tidak tahu cara mengatasinya. sekalipun saya sibuk, masih ada sisa anxiety tersisa.</p> <p>4. saya ingin tahu bagaimana cara meredakan ini.</p> <p><br /></p>', '2026-03-08 13:10:33');
