INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16239, 3956, 103412, 'mahasiswa', 'Susan Firdausi', '<p>Oiya ada lagi uneg-uneg yang belum saya sampaikan yaitu saat ini saya mahasiswa semester 12 yang sedang skripsian. Saya sering tidak bersemangat ketika mengerjakan skripsi, merasa sangat lelah emosional, merasa gampak capek, mood jelek. </p>', '2026-03-13 10:16:59');
