INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16244, 3950, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat siang, Kak Vina! <br />Untuk membantu mencari jalan keluar dari permasalahan Kakak, kami menyarankan Anda untuk bertemu dengan Psikolog kami pada hari <strong>Rabu, 1 April 2026 pukul 11.00 </strong>secara <strong>offline </strong>apakah Kakak berkenan? Kami tunggu konfirmasinya, ya:)<br /><br />Terima Kasih<br />Salam Hangat,<br />Layanan Konseling UB</p>', '2026-03-13 10:29:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16245, 3834, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat siang, Kak Anak Hapsari!<br /><br />Jika kami jadwalkan untuk melakukan konseling pada <strong>Jumat, 3 April 2026 pukul 13.00  </strong>secara <strong>offline </strong>dengan Ibu Ulifa apakah Kakak berkenan? Kami tunggu konfirmasinya, ya!<br /><br />Terima Kasih<br />Salam Hangat,<br />Layanan Konseling UB</p>', '2026-03-13 10:43:04');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16246, 3956, 36, 'admin', 'Aura Ratu', '<p>Baik kakak, Terimakasih karena telah  menceritakan kepada kami tentang apa yang Anda rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah.  Untuk membantu mencari jalan keluar dari permasalahan Anda, kami menyarankan Anda untuk bertemu dengan Psikolog kami yaitu Ibu Santi.<br /><br /> Untuk jadwal konseling secara offline tersedia pada tanggal 31 Maret 2026 pada pukul 10.00 WIB. Apakah kakak berkenan untuk melaksanakan sesi konseling pada pukul tersebut? Kami tunggu konfirmasinya, yaa.<br /><br /></p> <p>Terima kasih :)<br /></p> <p>Salam hangat,<br /></p> <p>Layanan Konseling UB.</p>', '2026-03-13 10:43:39');
