INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16258, 3960, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak Rivaldi, terima kasih sudah menjawab pertanyaan kami. Mohon maaf baru memberikan respon dikarenakan banyaknya antrian yang masuk. Terima kasih karena telah berkenan untuk menceritakan permasalahan Anda dan apa yang Anda rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal libur lebaran, jadwal dengan psikolog kami baru tersedia di tanggal 26 Maret 2026 dan seterusnya. Berikut opsi jadwal yang dapat Anda pilih:</p> <p dir="ltr">- Kamis, 26 Maret 2026 pukul 10.00 WIB (daring) <br />- Jumat, 27 Maret 2026 pukul 13.00 WIB (daring) <br />- Senin, 30 Maret 2026 pukul 08.00 WIB (luring/daring)<br /></p> <p dir="ltr"><br />Kami tunggu konfirmasinya yaa :)</p> <p dir="ltr">Terima kasih,<br />Salam hangat,<br />Layanan Konseling UB. </p>', '2026-03-15 00:25:15');
