INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16260, 3960, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak Rivaldi, terima atas konfirmasinya. <br />Untuk informasi selanjutnya, akan kami beritahu melalui WhatsApp ya, Kak :) <br /><br />Terima kasih, <br />Salam hangat, <br />Layanan Konseling UB. </p>', '2026-03-15 14:35:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16261, 3956, 33, 'admin', 'Nafa Tsaniya', '<p>Baik ka, terima kasih atas konfirmasinya. Akan kami jadwalkan pada Senin, 30 Maret 2026 pukul 10.00 ya! Untuk informasi selanjutnya akan kami sampaikan melalui WhatsApp saat akan mendekati sesi konseling. <br /><br />Terima kasih<br />Salam Hangat, <br />Layanan Konseling UB</p>', '2026-03-15 18:29:49');
