INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16303, 3968, 103420, 'mahasiswa', 'Stevenson Pratama', '<p>Saya belum bisa menjadi pribadi yang dapat pede dalam membuat suatu keputusan baru, masih ada rasa takut dalam memutuskan sesuatu. Saya masih ada banyak keraguan-raguan dalam menentukan suatu langkah yang tepat. Setiap langkah yang saya ambil juga rasanya selalu salah dan berakhir buruk.</p>', '2026-03-22 13:11:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16304, 3904, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat sore, Kak Thesa!</p> <p>Mohon maaf atas keterlambatan menjawabnya. Untuk konselor nya sendiri bukan dari dosen ataupun peer ya, Kak. Tapi dengan konselor kita atas nama Ka Andini.</p>', '2026-03-22 16:57:20');
