INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16352, 3978, 35, 'admin', 'Melsy Nemasari', '<p>Selamat pagi Kak Verdyansyah :)<br /><br />Mohon maaf jadwal psikolog PIO kami hanya tesedia pada hari Selasa Kak. Jika Kakak bersedia dapat kami jadwalkan pada Selasa, 31 Maret 2026 pukul 08.30 (online/offline) dengan Bu Fatiya. Kami tunggu konfirmasinya ya :)<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-03-27 08:49:37');
