INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16354, 3956, 103412, 'mahasiswa', 'Susan Firdausi', '<p><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit">Mohon maaf admin karena tanggal 18 maret 2026 di website saya ada tulisan error ketika saya sudah mengirim pesan dan pesan yang saya kirim juga pada tanggal 18 tersebut tampak tidak muncul di percakapan. Oleh karena itu saya mengira bahwa chat saya tidak terkirim di tanggal tsb mangkanya saya kirim chat beberapa kali dengan harapan chat dari saya bisa masuk (terbaca di percakapan). </span></span></p> <p><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit"><br /></span></span></p> <p><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit">Baru hari ini saya lihat terdapat 5 chat di tanggal 18 maret 2026.</span></span></span></span></p>', '2026-03-27 10:50:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16355, 3985, 35, 'admin', 'Melsy Nemasari', '<p>Halo selamat siang Kak Christine :)<br /> Terima kasih sudah berani menceritakan kondisi yang Kakak alami. Kami memahami bahwa apa yang Kakak rasakan saat ini cukup berat dan pasti tidak mudah dalam menjalaninya.</p> <p>Agar kami bisa memahami kondisi Kakak dengan lebih menyeluruh, kami ingin bertanya beberapa hal berikut:</p> <ol><li>Sejak kapan Kakak mulai merasakan ketakutan terkait perbuatan masa lalu dan tekanan dari keluarga? Apakah dapat diceritakan sedikit mengenai ketakutan akan perbuatan masa lalu?</li> <li>Terkait kondisi fisik seperti asam lambung yang kambuh saat stres, seberapa sering hal ini terjadi dan bagaimana dampaknya terhadap aktivitas harian Kakak?</li><li>Apa harapan Kakak menghubungi layanan kami?</li></ol> <p>Apapun jawaban Kakak akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Kakak tidak berkenan menjawab, Kakak juga bisa menyampaikan bahwa Kakak tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p>Terima kasih.</p> <p>Salam hangat,<br /> Layanan Konseling UB.</p>', '2026-03-27 11:24:07');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16356, 3985, 103428, 'mahasiswa', 'Christine Sihombing', '<p>1. sejak setahun terakhir namun saya tidak berkenan menjawab detail sekarang :(</p> <p>2. sangat sering, saat di ub pun riwayat saya check ke klinik juga ada beberapa kali. terkadang saya paksakan makan saja namun tetap tidak enak badan, dampaknya dipembelajaran sehari hari tidak dapat fokus dan selalu merasa tertinggal, seminggu terakhir juga sulit tidur (tidur di jam 3 pagi akibat sulit tidur dan menangis)</p> <p>3. saya harap saya bisa mendapatkan setidaknya solusi untuk tidur nyenyak </p>', '2026-03-27 12:05:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16357, 3956, 35, 'admin', 'Melsy Nemasari', '<p>Selamat siang Kak Susan :)<br /><br />Tidak apa-apa Kak, tidak perlu untuk meminta maaf :)<br />Apakah ada yang bisa kami bantu? <br /><br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-03-27 12:15:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16358, 3904, 33, 'admin', 'Nafa Tsaniya', '<p>Baik kak, sudah kami jadwalkan pada waktu tersebut, ya. Untuk informasi selanjutnya akan kami sampaikan melalu WhatsApp!<br /><br />Terima Kasih<br />Salam Hangat, <br />Layanan Konseling UB</p>', '2026-03-27 12:53:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16359, 3985, 35, 'admin', 'Melsy Nemasari', '<p>Selamat sore Kak Christine :)<br /><br />Terima kasih karena telah berkenan untuk menceritakan hal tersebut kepada kami. Kami memahami bahwa pasti sangatlah tidak mudah dalam menjalaninya. Oleh karena itu, kami menawarkan untuk melakukan sesi konseling bersama psikolog kami atas nama Bu Dian pada Selasa, 31 Maret 2026 pukul 12.00 secara offline. Apakah Kakak berkenan untuk melakukan konseling pada jadwal tersebut? Kami tunggu konfirmasinya yaa :)<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-03-27 15:01:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16360, 3986, 35, 'admin', 'Melsy Nemasari', '<p>Selamat sore Kak Marcell:)<br /><br />Terima kasih karena Kakak telah berani dan berkenan untuk menceritakan hal tersebut kepada kami. Kami memahami bahwa pasti sangatlah tidak mudah dalam menjalaninya. Oleh karena itu, kami menawarkan untuk melakukan sesi konseling bersama psikolog kami atas nama Pak Yafi pada Selasa, 31 Maret 2026 pukul 10.30 secara offline. Apakah Kakak berkenan untuk melakukan konseling pada jadwal tersebut? Kami tunggu konfirmasinya yaa :)<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-03-27 15:23:20');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16361, 3956, 103412, 'mahasiswa', 'Susan Firdausi', '<p><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit">Terimakasih banyak kak Melet Nemasari. Tadi saya tidur karena tidur merupakan healing yang menurut saya paling murah dan efisien.</span></span></p>', '2026-03-27 15:56:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16362, 3956, 103412, 'mahasiswa', 'Susan Firdausi', '<p>Mohon maaf kak Melsy Nemasari karena keyboard saya tadi berubah otomatis yaitu awalnya saya sudah ketik Melsy tapi berubah otomatis menjadi melet. Saya tadi juga lupa mengecek tulisan sebelum dikirim. Maaf kak Melsy. </p>', '2026-03-27 16:01:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16363, 3956, 103412, 'mahasiswa', 'Susan Firdausi', '<p>Saya merasa ketakutan (merasa trauma) untuk menuliskan di notes HP terkait seluruh masa lalu saya agar bisa dibahas ketika konsultasi. Saya sadar seharusnya memang saya tulis dengan runtut, detail, dan rinci agar tidak ada yang terlewat. Tapi saya takut dan sangat capek ketika memulai untuk menuliskan seluruh masa lalu saya. Saya sebaiknya harus apa ? </p>', '2026-03-27 16:03:20');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16364, 3956, 103412, 'mahasiswa', 'Susan Firdausi', '<p><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit">Selain itu, saya tidak mood beraktivitas yaitu mandi, gosok gigi, mengerjakan skripsi, keluar rumah untuk makan di warung nasi favorit saya, membersihkan rumah, dan lain-lain. Saya merasa berat dalam melakukan aktivasi sehari-hari yang sudah saya sebutkan tsb. Bagaimana ini ? </span></span></p>', '2026-03-27 16:08:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16365, 3956, 103412, 'mahasiswa', 'Susan Firdausi', '<p>Tapi 3 hari lalu saya sudah mandi dan gosok gigi yaitu di 24 Maret 2026.</p> <p>Selama 3 hari (sejak tanggal 24 Maret 2026) saya berasa di rumah saja saya merasa berat untuk mandi dan gosok gigi. Padahal 2 tahun lalu saya masih rajin mandi yaitu minimal mandi 1x sehari. </p> <p>Sebenarnya saya memang sudah disuruh mandi oleh mama saya minimal 1x sehari tapi saya merasa capek aja gitu. </p>', '2026-03-27 16:12:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16366, 3956, 103412, 'mahasiswa', 'Susan Firdausi', '<p><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit">Tapi selama 2 tahun belakangan ini saya tetap mandi sebelum saya pergi ke kampus, ke dokter behel, dan tempat-tempat lain. </span></span></p> <p><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit"><br /></span></span></p> <p><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit"><br /></span></span></p>', '2026-03-27 16:15:29');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16367, 3956, 103412, 'mahasiswa', 'Susan Firdausi', '<p>1 bulan lalu saya sebenarnya disuruh ke apotek oleh dokter behel saya untuk membeli obat kumur. Tapi sudah hampir 1 bulan saya belum beli obat kumur karena tidak mood, lelah, capek, dan tidak bersemangat meskipun saya paham bahwa wajib untuk membeli obat kumur tsb. </p>', '2026-03-27 16:26:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16369, 3985, 103428, 'mahasiswa', 'Christine Sihombing', '<p>selamat sore, terkait di hari dan jam tersebut saya masih ada kelas hingga jam 1 siang, jikalau di jam 2 siang apakah diperbolehkan? dan lokasi nya dimana yaa? terimakasih atas bantuannya :)</p>', '2026-03-27 16:35:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16371, 3985, 35, 'admin', 'Melsy Nemasari', '<p>Selamat sore, Kak Christine :)<br /><br />Terima kasih atas konfirmasinya, Kak. Konseling dapat dilakukan pada pukul 2 siang yaa, Kak. Untuk lokasinya berada di Lantai 1 Gedung Rektorat Universitas Brawijaya. Informasi selanjutnya akan kami sampaikan melalui WhatsApp yaa :)<br /><br />Terima kasih.<br />Salam hangat, <br />Layanan Konseling UB. <br /></p>', '2026-03-27 17:05:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16372, 3956, 103412, 'mahasiswa', 'Susan Firdausi', '<p>Bahkan sekarang otw malam. Sudah seharusnya pintu kamar (pintu yang membatasi kamar saya dan halaman belakang) saya tutup. Tapi rasanya saya seperti menanggung seluruh beban yang ada di dunia hanya karena memulai menutup pintu. </p>', '2026-03-27 17:23:47');
