INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16407, 3987, 32, 'admin', 'Almira Jessenia', '<p>Baik, terima kasih konfirmasinya Kak Husnul.. untuk info lanjutan dan reminder akan kami sampaikan melalui WhatsApp, ya :)<br /><br />Salam hangat,<br />Layanan Konseling UB,</p>', '2026-03-29 08:37:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16408, 3990, 32, 'admin', 'Almira Jessenia', '<p>Halo, selamat pagi Kak Justin :)<br /></p> <p dir="ltr">Terima kasih telah menghubungi Layanan Konseling UB dan telah berkenan untuk menceritakan permasalahan Kakak. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Wajar jika Kakak mencoba untuk memahami kondisi diri sendiri, termasuk dengan mencari tahu tentang ADHD. Namun, untuk memastikan apakah itu benar sesuai dengan yang Kakak alami, tetap perlu dilakukan asesmen lebih lanjut dengan tenaga profesional. <br /><br />Untuk membantu mencari jalan keluar dari permasalahan Kakak, kami menyarankan untuk bertemu dengan Psikolog kami. Kami memiliki jadwal terdekat yang tersedia pada Hari <strong>Kamis, tanggal 2 April 2026 </strong><strong>pukul 13.00</strong> secara <strong>luring</strong> dengan <strong>Ibu Dian</strong>. Apakah di jam dan hari tersebut kiranya kakak berkenan? Kami tunggu konfirmasinya, ya..<br /><br />Terima kasih<br />Salam hangat,<br />Tim Konseling UB.</p>', '2026-03-29 08:46:17');
