INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16430, 3978, 102821, 'mahasiswa', 'Verdyansyah Pratama', '<p>mungkin bisa di antara tanggal 20-29 april kan pada saat itu semua online kak mungkin bisa meninggalkan jadwal saya untuk ketemu. saya UTS mulai tanggal 6 soalnya. Terimakasih</p>', '2026-03-30 06:29:30');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16431, 3995, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat pagi, Ka Aminah! <br /></p> <p dir="ltr">Terima kasih telah menghubungi Layanan Konseling UB. Terima kasih karena telah berkenan untuk menceritakan permasalahan Anda dan apa yang Anda rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk membantu kami lebih memahami permasalahan Anda, silahkan untuk menjawab pertanyaan berikut, yaa:</p> <p dir="ltr">1. Sudah berapa lama Anda merasakan keadaaan ini? Dan apakah hal tersebut berdampak pada keseharian Anda seperti pola tidur dan pola makan?<br />2. Ketika muncul gejala panik (seperti jantung berdebar, gemetar, sesak), apa yang biasanya Anda lakukan untuk meredakannya, dan apakah cara tersebut membantu?<br />3. Apa harapan Anda untuk melakukan konseling bersama Layanan Konseling UB?</p> <p dir="ltr">Apapun jawaban yang Anda berikan akan sangat membantu kami untuk memetakan permasalahan lebih lanjut. <br /></p> <p dir="ltr">Terima kasih<br />Salam hangat, <br />Layanan Konseling UB<br /></p> <p><br /></p>', '2026-03-30 07:52:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16432, 3969, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat pagi, Kak Bagus!<br /></p> <p dir="ltr">Terima kasih telah berkenan untuk menceritakan permasalahan Kakak. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk membantu mencari jalan keluar dari permasalahan Kakak, kami menyarankan untuk bertemu dengan Psikolog kami pada hari <strong>Senin, 6 April 2026 pukul 10.00</strong> secara <strong>offline. </strong>Apakah Kakak berkenan jika kami jadwalkan pada waktu tersebut? Kami tunggu konfirmasinya, ya..<br /><br />Terima kasih<br />Salam hangat,<br />Tim Konseling UB.</p>', '2026-03-30 08:03:29');
