INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16472, 3995, 103437, 'mahasiswa', 'Aminah', '<p><span dir="auto"><span dir="auto"><span dir="auto"><span dir="auto">1. </span></span><span dir="auto"><span dir="auto">Saya merasa keadaan ini sejak saya SMA, dan hal tersebut sangat berdampak karena saya jadii tidak bisa tidur dan saya juga sering demam karna hal itu.</span></span></span></span></p> <p><span dir="auto"><span dir="auto">2. Biasanya saya diem aja terus nyendiri aja ngejauhin keramaian, dan cara tersebutt ga begitu membantu juga sih karna sering ga ngaruh dan tetep buat saya sesek nafas,gemeteran gitu</span></span><span dir="auto"><span dir="auto"><br /></span></span></p> <p><span dir="auto"><span dir="auto"><span dir="auto"><span dir="auto">3. Saya berharap dengan saya berani konsul seperti ini saya jadi bisa tau kalau saya ini kenapa dan saya juga ingin tau cara yg tepat untuk mengatasi hal tersebutt bagaimana soalnya saya pribadi ga tau sama sekali bagaimana cara nya supaya saya tidak seperti itu lgi. Saya sudah cape, terimakasih:)</span></span></span></span></p>', '2026-03-30 17:50:05');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16473, 4008, 103443, 'mahasiswa', 'Mirza', '<p>Saya mendapatkan pengalaman buruk dalam kurun waktu satu bulan ini, saya sempat dituduh dan diviralkan menjadi selingkuhan cowo (seorang teman di kelompok KKN). Padahal aslinya saya tidak tahu kalau cowo ini punya pacar karena si cowo ga pernah disclaimer di lingkungan KKN saya. Saya juga tidak membenarkan perilaku saya karena berkomunikasi intens dengan dia tapi saya juga tidak menyangka akan dianggap sebagai selingkuhan karena saya berkomunikasi juga karena saya menganggapnya teman yang baik dan peduli ke saya. Kondisi viral yang dilihat oleh ±4 juta viewers membuat saya terpuruk, ada saatnya saya merasa takut dihakimi, ketika ada di tempat umum saya merasa pusing, mual, dan merasa takut dijudge. Ditambah lagi selang beberapa hari setelah masalah viral itu terselesaikan dan saya terbukti bukan selingkuhan dan tidak bersalah, saya putus dengan pacar yang jadi satu-satunya orang terdekat saya. Saya coba menyapa dia ketika di kampus dan ternyata diabaikan, sejujurnya saya merasa sakit hati dan kecewa, saya merasa saat ini saya sendirian dan saya merasa ga sebegitunya mampu bertahan kalau sendirian (i think i need someone to talk, even one people). Jadi, dua kondisi yang menurut saya saling berkaitan mengganggu pikiran dan hari-hari saya, saya jadi sering dan mudah menangis, dada saya sesak, pusing, sulit tidur, nafsu makan saya menurun, dan kondisi sendiri membuat saya merasa tidak bersemangat di bidang akademik. Saya kesulitan mencari jalan keluar agar tidak setres seperti ini. </p>', '2026-03-30 18:11:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16474, 3995, 103437, 'mahasiswa', 'Aminah', '<p><span dir="auto"><span dir="auto"><span dir="auto"><span dir="auto">1. </span></span><span dir="auto"><span dir="auto">Saya merasa keadaan ini sejak saya SMA, dan hal tersebut sangat berdampak karena saya jadii tidak bisa tidur dan saya juga sering demam karna hal itu.</span></span></span></span></p> <p><span dir="auto"><span dir="auto">2. Biasanya saya diem aja terus nyendiri aja ngejauhin keramaian, dan cara tersebutt ga begitu membantu juga sih karna sering ga ngaruh dan tetep buat saya sesek nafas,gemeteran gitu</span></span><span dir="auto"><span dir="auto"><br /></span></span></p> <p><span dir="auto"><span dir="auto"><span dir="auto"><span dir="auto">3. Saya berharap dengan saya berani konsul seperti ini saya jadi bisa tau kalau saya ini kenapa dan saya juga ingin tau cara yg tepat untuk mengatasi hal tersebutt bagaimana soalnya saya pribadi ga tau sama sekali bagaimana cara nya supaya saya tidak seperti itu lgi. Saya sudah cape, terimakasih:)</span></span></span></span></p>', '2026-03-30 18:34:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16475, 4009, 103444, 'mahasiswa', 'Silmi Sholehah', '<p>saya adalah individu yang suka mencoba hal baru, punya banyak plan kedepan dan berambisi beberapa tahun belakang, ambisi saya untuk menjadi berprestasi semakin besar ketika ibu saya meninggal, keluarga kami mengalami perubahan yahg sangat berat, terutama di bidang fiinansial, hingga fokus saya sangat ingin membahagiakan abi saya. di kelas 11 SMA saya berhasil mendapatkan BIM persiapan LN, saat itu membuka kembali harapan saya untuk tetap kuliah dengan target yang saya miliki. bisa dibilang semua orang bangga terhadap saya, dari satu sekolah hanya saya yang diterima dan membuat orang krang memiliki harapan terhadap saya. Saya memiliki tekanan sendiri agar berhasil mendapatkan kuliah di luar negeri dengan beasiswa itu. Karena orang orang mengira saya sudh pasti akan mendapatkan kuliah di luar negeri dengan beasiswa itu, saya berusaha keras, namun singkat cerita saya berhasil diterima di kampus luar negeri namun gagal mendapatkan beasiswa itu. selama satu tahun proses dari program itu, saya seringkli  menghadapi kesulitan, seperti teman yang iri dengan saya, kata kata hinaan (underestimated) yang menjatuhkan saya, namun tidak semua nya bersikap jahat kepada saya ada juga beberapa guru yang mengerti dan mendukung saya apapun hasilnya. maka kesulitan ini sebelumnya tidak saya ambil pusing karena peristiwa ini yang memotivasi saya kepada mereka bahwa saya akan berhasil dan bisa lebih dari mereka, nyatanya saya gagal, saya malah satu sekolah dengan orang yang mengejek saya. Saya berusaha bangkit, setahun saya menghabiskan waktu saya untuk mencari semangat baru, saya hidup slow living, saya mencoba organisasi namun semua berantakan. saat ini saya keluar dari organisasi yang saya ikuti menjadi mahasiswa kupu-kupu dan ingin lebih mengenal diri saya dan menata kembali hidup saya. sekarang saya tidak tau tujuan saya kedepannya, apa yang saya inginkan, saya takut gagal, takut tidak sukses, takut akan segalanya. selama di fh saya merasa kecil, tidak percaya dengan kemampuan diri saya. entah sampai kapan ini akan terjadi <br /><br /><br /></p>', '2026-03-30 18:53:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16476, 4010, 103445, 'mahasiswa', 'Mochamad Fanani', '<p>Tidak adanya tempat cerita yang dapat dipercaya karena tidak ada yang bisa dipercaya, dan banyak yang harus diselesaikan tapi diri sendiri belum selesai, dalam hal ini saya kurang memliki tempat yang menurut saya pas didalamnya apalagi dihadapkan dengan circle yang ada disetiap tempat bertumbuh dan merasa circle tersebut menjadi musuh dalam emosional </p>', '2026-03-30 20:15:02');
