INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16519, 4016, 37, 'admin', 'Allysa Dewantari', '<p>Selamat sore, Kak Citra!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Mohon maaf sebelumnya, Kak, untuk layanan kami sendiri hanya ditujukan kepada mahasiswa aktif UB yaa, Kak. Dan disebabkan saat ini status kakak adalah alumni, mohon maaf tapi kami belum bisa memberikan pelayanan dari layanan kami, Kak. Kami sarankan Anda untuk mendatangi biro psikologi terdekat ya, Kak. Berikut kami lampirkan rekomendasi biro psikologi di Malang yang dapat Anda akses pada foto dibawah ini. Mohon maaf sekali lagi atas ketidaknyamanannya, Kak.</p> <p>Terima kasih. <br />Salam hangat, <br />Layanan Konseling UB.</p>', '2026-03-31 17:32:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16520, 4017, 103449, 'mahasiswa', 'Muamar', '<p>Pagi, siang, sore kakak kakak LKM. Perkenalkan saya Amar, saya merasa mengalami kemunduran diri yang sangat sangat mundur dan selalu diiringi kegagalan sehingga saya kehilangan produktivitas</p>', '2026-03-31 17:52:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16521, 4018, 103364, 'mahasiswa', 'Evelyn', '<p>Sering saya tu udh tau ini salah dan harus diperbaiki tapi sulit untuk ngelakuinnya. Rasanya kyk udh learned helplesness gitu. Gimana cara mencari motivasi internal biar saya tu tetap bisa melakukan sesuatu meskipun gk ada stimulus eksternalnya.</p>', '2026-03-31 17:53:26');
