INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16655, 3996, 103436, 'mahasiswa', 'Isfya Amin', '<p>Haloo, terima kasih Aura sudah menyalin pesannya. Sayang sekali, karena saya tidak bisa mencari nomor tiket tsb, saya jadi terlewati jadwal yg memungkinkan saya untuk konseling di hari kemarin.</p> <p>Adakah ketersediaan jadwal di minggu depan? Terima kasih</p>', '2026-04-05 12:12:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16656, 4044, 103463, 'mahasiswa', 'Zhalfa Raudila', '<p>Mungkin saya lebih membutuhkan konseling karena saya ingin menyembuhkan trauma saya lebih cepat. Jika memungkinkan, saya juga ingin mendapatkan pendampingan lebih lanjut terkait kondisi saya</p>', '2026-04-05 12:52:16');
