INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16681, 3995, 34, 'admin', 'Heidemarie Gunarso', '<p>Selamat pagi, Kak Aminah! <br /><br />Terima kasih telah menghubungi Layanan Konseling UB. Mohon maaf atas keterlambatannya dalam menjawab karena antrean yang sangat banyak. Baik Kak, terima kasih atas konfirmasinya. Apakah Anda berkenan jika kami jadwalkan konseling pada <strong>hari Rabu, 8 April 2026 pukul 10.00 WIB </strong>atau <strong>hari Kamis, 9 April 2026 pukul 11.00 WIB</strong>?<br /><br />Kami tunggu konfirmasinya yaa Kak :) <br /><br />Terima kasih. <br />Salam hangat, <br />Layanan Konseling UB.</p>', '2026-04-06 08:16:17');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16682, 4048, 34, 'admin', 'Heidemarie Gunarso', '<p>Selamat pagi, Kak Andini Sucahyawati! <br /><br />Terima kasih telah menghubungi Layanan Konseling UB. Mohon maaf atas keterlambatannya dalam menjawab karena antrean yang sangat banyak. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda.<br /></p> <p>Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan konselor kami? Berikut opsi jadwal yang dapat Anda pilih:</p> <p>- Selasa, 7 April 2026 pukul 19.00 WIB (daring)<br />- Rabu, 8 April 2026 pukul 19.00 WIB (daring)<br /><br />Kami tunggu konfirmasinya yaa :)</p> <p>Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-06 08:35:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16683, 4046, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak, terima kasih atas konfirmasinya.<br /></p> <p>Untuk informasi selanjutnya, akan kami hubungi melalui WhatsApp ya Kak :)<br /></p> <p>Terima kasih.<br /></p> <p>Salam hangat, <br />Layanan Konseling UB. </p>', '2026-04-06 08:39:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16684, 3996, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak Isfya, terima kasih atas konfirmasinya. </p> <p>Karena jadwal di minggu ini sudah penuh, jadwal dengan psikolog kami baru tersedia di minggu depan. Berikut opsi jadwal yang dapat Anda pilih:</p> <p>- Senin, 13 April 2026 pukul 08.00 WIB (daring/luring)<br />- Selasa, 14 April 2026 pukul 13.00 WIB (daring/luring)<br /><br />Kami tunggu konfirmasinya yaa :) </p> <p>Terima kasih.</p> <p>Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-06 08:48:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16685, 4044, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak, terima kasih atas jawabannya. Terima kasih karena telah berkenan untuk menceritakan permasalahan Anda dan apa yang Anda rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Terima kasih karena Anda sudah mau dan mampu terus bertahan sampai sejauh ini, yaa :)</p> <p>Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami dan didampingi dengan Satgas kami? Namun karena jadwal di minggu ini sudah penuh, jadwal dengan psikolog kami baru tersedia di minggu depan. Berikut opsi jadwal yang dapat Anda pilih:</p> <p dir="ltr">- Senin, 13 April 2026 pukul 13.00 WIB (daring/luring)<br />- Selasa, 14 April 2026 pukul 08.00 WIB (daring/luring)<br /></p> <p dir="ltr">Kami tunggu konfirmasinya yaa :)</p> <p dir="ltr">Terima kasih.</p> <p dir="ltr">Salam hangat,<br />Layanan Konseling UB.<br /></p>', '2026-04-06 09:04:56');
