INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16721, 4058, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak, terima kasih atas jawabannya. Terima kasih karena telah berkenan untuk menceritakan permasalahan Anda dan apa yang Anda rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah.</p> <p dir="ltr">Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan peer counselor kami?  Berikut opsi jadwal yang dapat Anda pilih:</p> <p dir="ltr">- Kamis, 9 April 2026 pukul 09.00 WIB (daring/luring)<br />- Kamis, 9 April 2026 pukul 11.00 WIB (daring/luring)<br /><br />Kami tunggu konfirmasinya yaa :)</p> <p dir="ltr">Terima kasih.</p> <p dir="ltr">Salam hangat,<br />Layanan Konseling UB.<br /></p>', '2026-04-06 11:23:22');
