INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16754, 4068, 103474, 'mahasiswa', 'Marsabella Pramidya', '<p>saya merasa perlu bercerita dengan orang yang sedikit mengerti tentang permasalahan mental dan ingin bercerita untuk lega tanpa takut di judge dan bisa menyampaikan semua perasaan dengan diarahkan juga. Jadi saya merasa sering kali bingung terhadap diri saya sendiri, terutama perasaan saya sendiri, saya sering kali merasa bersalah dengan hal yang saya lakukan sendiri padahal tujuannya untuk melindungi perasaan saya sendiri dan saya selalu takut untuk menolak orang yang datang ke kehidupan saya karna saya selalu merasa tidak enak terhadap semua hal. saya kira perasaan ini sepele saja tetapi terkadang saya merasa terganggu dengan perasaan saya sendiri, seperti sering kali jadi takut melakukan hal yang seharusnya saya lakukan tetapi bisa berisiko saya kehilangan hal atau orang tersebut dan sering kali saya merasa susah untuk melupakan kejadian di masa lalu, dan selalu merasa bahwa yang saya lakukan itu salah dan saya tidak tau sebenarnya yang baik untuk saya lakukan itu seperti apa. saya merasa butuh untuk cerita dan mencari validasi tentang apa yang saya rasakan dan harusnya bagaimana saya menanggapi perasaan tersebut, karena saya takut bahwa sebenernya saya memiliki tanda tanda sakit mental tetapi saya tidak mengetahui itu dan tidak bisa mencegah untuk sembuh dan ingin bisa berubah menjadi yang lebih baik lagi yang dimulai dengan memiliki mental dan perasaan yang stabil</p>', '2026-04-06 22:36:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16755, 4042, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak, terima kasih kembalii :) <br /><br />Salam hangat, <br />Layanan Konseling UB.</p>', '2026-04-06 22:57:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16756, 4068, 34, 'admin', 'Heidemarie Gunarso', '<p dir="ltr">Selamat malam, Kak Marsabella!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail permasalahan yang Anda alami? Menurut Anda apa penyebab hal tersebut terjadi?<br />2. Dari permasalahan yang Anda rasakan, apa efeknya ke kegiatan keseharian Anda? Dan apakah sudah sangat mengganggu?<br />3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?<br />4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr">Kami tunggu konfirmasinya yaa :)</p> <p dir="ltr">Terima kasih. </p> <p dir="ltr">Salam hangat,<br />Layanan Konseling UB.<br /></p>', '2026-04-06 23:00:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16757, 4045, 37, 'admin', 'Allysa Dewantari', '<p>Baik, terima kasih kembali yaa kak.. :)<br /></p> <p>Salam hangat, <br />Layanan Konseling UB.</p>', '2026-04-06 23:31:04');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16758, 4069, 103475, 'mahasiswa', 'Glory Cecillia', '<p>saya merasa kesepian sekali. saya rasa teman-teman saya sudah mulai sibuk dengan dirinya masing2 sedangkan saya butuh teman main. sebelumnya saya sering banget main dan tbtb masuk semester genap kami mulai pisah arah. ini terjadi ke hampir semua friend group saya. saya takut sendirian.</p>', '2026-04-07 00:39:45');
