INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16815, 4074, 102544, 'mahasiswa', 'Lasalina Rahadian', '<p>Selamat siang kak, terima kasih atas konfirmasinya. Untuk jadwal saya memilih di hari Jumat, 17 April 2026 pukul 13.00 WIB (luring) ya kak</p>', '2026-04-08 11:23:56');
