INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16838, 4080, 37, 'admin', 'Allysa Dewantari', '<p>Baik, Kak. Terima kasih konfirmasinya. Untuk informasi lebih lanjut akan kami hubungi melalui WhatsApp ya kak.. :)</p> <p>Terima kasih. <br />Salam hangat, <br />Layanan Konseling UB. </p>', '2026-04-08 14:33:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16839, 4081, 103480, 'mahasiswa', 'Gavin Raditya', '<p>maaf saya kemarin sempat membuat tiket, namun saya lupa dengan gmail dan password yang saya gunakan karena kondisi mental saya sangat tidak baik, ingin mencari solusinya </p>', '2026-04-08 14:57:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16840, 4076, 103477, 'mahasiswa', 'Gavin Raditya', '<p>1. Apakah Anda berkenan mendeskripsikan lebih detail permasalahan yang Anda alami? Menurut Anda apa penyebab hal tersebut terjadi?</p> <p>Ya<br />2. Dari permasalahan yang Anda rasakan, apa efeknya ke kegiatan keseharian Anda? Dan apakah sudah sangat mengganggu?</p> <p>sangat mengganggu, ada berberapa masalah yang menganggu perkuliahan serta menggangu hubungan hubungan saya </p> <p><br /></p> <p>3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?</p> <p>ingin solusinya, bagaimana pun caranya, entah dengan obat atau semacamnya, saya hanya ingin menjadi lebih baik<br />4. Apa harapan Anda menghubungi layanan kami?</p> <p>penyembuhan hanyalah yang saya harapkan sekarang, saya tidak tau harus bagaimana lagi</p>', '2026-04-08 15:02:13');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16841, 4082, 103481, 'mahasiswa', 'Jodie Ekasinta', '<p>Saya punya latar belakang keluarga yang bercerai. Sejak kecil saya memiliki gangguan tidur: sulit tidur dan cenderung melakukan banyak hal agar tidak memikirkan hal negatif dan supaya gampang lelah (ketiduran). Belakangan ini saya merasa sulit tidur yang ekstrim hingga tidak tidur lebih dari 20 jam. Saya juga mengonsumsi obat tidur namun saya merasa itu tidak membantu.</p>', '2026-04-08 15:41:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16842, 4041, 103462, 'mahasiswa', 'Evan Nugraha', '<p>Sebelumnya mohon maaf baru dapat merespon sekarang.</p> <p>1. saya merasa tertinggal dan tidak dapat mengikuti perkuliahan.</p> <p>2. Sudah sekitar 1 bulan, ada hari di mana saya sangat tidak ingin melakukan apapun.</p> <p>3. Saya menata ulang porsi belajar saya, lebih ringkas.</p> <p>4. Yang utama saya ingin dapat mencurahkan apa yang saya rasa, yang lainnya saya ingin mengembalikan semangat saya.</p>', '2026-04-08 16:41:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16843, 4083, 103482, 'mahasiswa', 'Hanna Adibah', '<p>Saya berasal dari keluarga broken home, ayah tidak pernah hadir sejak saya kecil. Saya sering merasa tidak layak dan selalu membandingkan diri dengan orang lain, terutama ketika ingin terkoneksi dengan seseorang. Saya ingin memahami pola ini dan belajar menerima diri sendiri dengan lebih baik.</p>', '2026-04-08 18:01:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16844, 4076, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak, terima kasih atas jawabannya. Terima kasih karena telah berkenan untuk menceritakan permasalahan Anda dan apa yang Anda rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan peer counselor kami? Namun karena jadwal di minggu ini sudah penuh, jadwal dengan peer counselor kami baru tersedia di minggu depan. Berikut opsi jadwal yang dapat Anda pilih:</p> <p>- Senin, 13 April 2026 pukul 14.00 WIB (daring/luring) dengan peer counselor perempuan<br />- Rabu, 15 April 2026 pukul 15.00 WIB (daring/luring) dengan peer counselor laki-laki<br /><br />Kami tunggu konfirmasinya yaa :)</p> <p>Terima kasih. </p> <p>Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-08 18:25:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16845, 4081, 34, 'admin', 'Heidemarie Gunarso', '<p>Selamat malam Kak, Baik terima kasih atas konfirmasinya. </p> <p>Sudah kami balas melalui e-ticket #004075 yaa Kak, silakan dicek kembali :) </p> <p>Terima kasih. </p> <p>Salam hangat,<br />Layanan Konseling UB</p>', '2026-04-08 18:27:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16846, 4082, 34, 'admin', 'Heidemarie Gunarso', '<p dir="ltr">Selamat pagi, Kak Jodie Ekasinta!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Kami sangat memahami pasti situasi ini tidak mudah untuk dilalui. Kami mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Sudah berapa lama pola "tidak tidur ekstrim" ini terjadi secara beruntun? Obat tidur apa yang Anda konsumsi saat ini (nama obat atau jenisnya), dan berapa dosisnya?<br />2. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr">Terima kasih.<br /></p> <p dir="ltr">Salam hangat,<br />Layanan Konseling UB.</p> <p><br /></p>', '2026-04-08 18:31:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16847, 4083, 37, 'admin', 'Allysa Dewantari', '<p>Selamat malam, Kak Hanna!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Kami sangat memahami pasti situasi ini tidak mudah untuk dilalui. Kami mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p>1. Apakah Anda berkenan mendeskripsikan lebih detail masalah yang Anda alami? Menurut Anda apa penyebab hal tersebut terjadi?<br />2. Dari yang Anda rasakan, sudah berapa lama masalah tersebut berdampak ke kegiatan keseharian Anda?<br />3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?<br />4. Apa harapan Anda menghubungi layanan kami?</p> <p>Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-08 18:37:23');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16848, 4041, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak, terima kasih atas jawabannya. Terima kasih karena telah berkenan untuk menceritakan permasalahan Anda dan apa yang Anda rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan peer counselor kami? Namun karena jadwal di minggu ini sudah penuh, jadwal dengan peer counselor kami baru tersedia di minggu depan. Jadwal tersebut ada pada hari Senin, 13 April 2026 pukul 09.00 WIB (daring/luring) dengan peer counselor perempuan. </p> <p>Kami tunggu konfirmasinya yaa :)<br />Terima kasih. </p> <p>Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-08 18:39:08');
