INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16851, 4084, 103483, 'mahasiswa', 'Siti Rahmadani', '<p>saya suka merasa lemas dan cape tetapi sudah serasa mati rasa tidak bisa nangis dan coping dengan cara sehat. Saya cenderung memendam dan sebenarnya sudah ada unresolved trauma hertahun-tahun tapi saya masih takut untuk berkonsultasi konseling/psikolog sehingga sekarang lebih mudah tertrigger dan meledak-ledak</p>', '2026-04-08 18:46:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16852, 4085, 101953, 'mahasiswa', 'Ali Akbar', '<p>saya memiliki permasalahan pada masa depan, orientasi seksual, dan permasalahan keluarga dan teman sebaya</p>', '2026-04-08 18:53:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16853, 4086, 103130, 'mahasiswa', 'MARIA RUMBIAK', '<p>Aku tumbuh dengan dipaksa jadi yaa bisa dibilang “orang dewasa” sama ibuku, harus tau dan ngikutin ngurusin masalah emosinya dan jadi perantara antara dia sama ayahku. Aku disuru untuk menelan bulat2 rasa sakitnya, bisa dibilang memanipulasi lah dan konflik keluarga serta masalah yang terjadi pas aku kecil sampai aku ngerasa bertanggung jawab atas perasaannya. Hal ini telah terjadi dari aku masih SD. Oleh Karena itu, aku nggak bener-bener punya ruang buat jadi diri sendiri, dan sekarang aku ngerasa capek dan kewalahan.</p>', '2026-04-08 19:01:42');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16854, 4056, 102938, 'mahasiswa', 'Darmawansyah Abror', '<p>selamat malam kak</p> <p>saya mengajukan perubahan dari daring ke luring bisa kak? saya merasa tidak nyaman kalau daring.</p> <p><br /></p>', '2026-04-08 20:32:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16855, 4077, 103478, 'mahasiswa', 'IZAH NURWIDAYATI', '1. Beberapa waktu lalu saya mengalami fase down karena banyak kegiatan, saya sudah berusa menjelaskan tentang keadaan saya pada rekan organisasi saya namun tetap tenyata masih tidak sesuai dengan apa yang dia harapkan 2. Saya sudah bercerita ke orang2 terdekat saya seperti ibu dan ketua keputran tentang kondisi yang saya alami namun perasaan cemas nya masih tetap ada 3. Harapan saya, saya ingin memastikan bahwasannya kecemasan yang saya rasakan benar/valid karena beberapa sebab... Khawatir nya itu hanya prasangka2 yang membuat saya down. Saya ingin membuktikan bahwa kecemasan saya adalah hal yang yang wajar karena faktor yang ada Dan saya juga ingin mendapatkan pencerahan bagaimana saya harus mengatasi kecemasan dan konflik yang saya rasakan', '2026-04-08 20:37:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16856, 4087, 103486, 'mahasiswa', 'KHANSA USMIRA', '<p>Ingin mengetahui permasalahan pribadi seperti apa yang menjadi sumber kenapa saya sering tidak fokus dalam 2 bulan ini</p>', '2026-04-08 20:42:17');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16857, 4087, 37, 'admin', 'Allysa Dewantari', '<p>Selamat malam, Kak Khansa!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Kami sangat memahami pasti situasi ini tidak mudah untuk dilalui. Kami mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p>1. Apakah Anda berkenan mendeskripsikan lebih detail masalah yang Anda alami? Menurut Anda apa penyebab hal tersebut terjadi?<br />2. Dari yang Anda rasakan, sudah berapa lama masalah tersebut berdampak ke kegiatan keseharian Anda?<br />3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?<br />4. Apa harapan Anda menghubungi layanan kami?</p> <p>Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-08 21:10:21');
