INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16898, 4093, 103491, 'mahasiswa', 'Bintang Akbar', '<p>pembelajaran awal masih aktf kuliah, setelh itu ada bbrp mata kuliah ga masuk kami sempat tanyakan ke anak , katanya krn blm dapat teman dn belum dimasukan ke Group jadi Bintang ga tau info tugas dll , krn anak nya pendiam jd blm inisiatif mennyakan ke teman, kami sebagai ortu mau mencari solusi apa yg terjadi sm anak , krn anak skrg menurut info tmn kost lebih murung dan berbicara seperlu nya,.. Mohon bantuan nya, dan terima kasih banyak</p>', '2026-04-09 12:18:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16899, 4088, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak, terima kasih atas jawabannya. Terima kasih karena telah berkenan untuk menceritakan permasalahan Anda dan apa yang Anda rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk mendiskusikan lebih lanjut mengenai hal yang Anda ceritakan, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal di minggu ini sudah penuh, jadwal dengan psikolog kami baru tersedia di minggu depan. Jadwal psikolog kami pada hari <strong>Selasa, 14 April 2026 pukul 08.00 secara offline. </strong></p> <p>Kami tunggu konfirmasinya yaa :)</p> <p>Terima kasih. <br /><br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-09 13:00:24');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16900, 4092, 37, 'admin', 'Allysa Dewantari', '<p>Baik, Kak. Terima kasih konfirmasinya, Kak. <br />Apakah berkenan jika kami jadwalkan besok <strong>Jumat, 10 April 2026 pukul 14.00 secara offline dengan <em>peer counselor</em></strong> (perempuan) kami atas nama Kak Anna? </p> <p>Kami tunggu konfirmasi nya ya kak... :)</p> <p>Terima kasih. <br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-09 13:02:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16901, 4091, 34, 'admin', 'Heidemarie Gunarso', '<p dir="ltr">Selamat siang, Kak Roicha!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Kami sangat memahami pasti situasi ini tidak mudah untuk dilalui. Kami mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail masalah akademik yang Anda alami? <br />2. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?<br />3. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr">Terima kasih.</p> <p dir="ltr">Salam hangat,<br />Layanan Konseling UB.<br /></p>', '2026-04-09 13:03:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (16902, 4088, 103487, 'mahasiswa', 'IVANA PUTRI', '<p>Baikk, terima kasih sebelumnya. Saya bersedia untuk melakukan konseling dengan psikolog. Untuk jadwal hari Selasa, 14 April 2026 pukul 08.00 secara offline, saya konfirmasi bisa hadir.</p>', '2026-04-09 13:07:23');
