INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17005, 4103, 103498, 'mahasiswa', 'Vieny Vania', '<p>Selamat malam,<br /></p> <p>Maaf sebelumnya, saya baru lihat jadwal yang tersedia telah diperbarui dan terdapat pilihan jadwal pada hari Jumat, 17 April 2026 15.00 WIB bersama psikolog perempuan atas nama Bu Dian. Jika pada tanggal tersebut, saya bersedia...  Apakah terdapat hal yang harus saya persiapkan sebelum sesi konsultasi tersebut?<br /></p> <p>Terima kasih sebelumnya <br /></p>', '2026-04-11 23:34:09');
