INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17059, 4108, 35, 'admin', 'Melsy Nemasari', '<p>Halo, Kak Arikha.<br /><br />Baik, terima kasih atas konfirmasinya. Apabila konseling dilakukan pada hari Rabu, 15 April 2026  pukul 13.00 secara offline apakah berkenan Kak? Kami tunggu konfirmasinya yaa :)<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.<br /></p>', '2026-04-13 12:52:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17060, 4126, 103336, 'mahasiswa', 'Fathina Arifa', '<p>Sudah 2 minggu ini saya merasa sedih dan selalu merasa bersalah karena tidak dapat mengerjakan tugas akhir, saya selalu merasa tidak berguna karena saya merasa tidak pernah memahami atau mengetahui mjnat saya ada dimana, saya tidak memiliki arah hiduo saya rasa. saya selalu merasa takut karena sering melihat seminar yang menurut saya menegangkan, hal ini saya rasa membuat saya was was dan takut dengan thgas akhir saya yang dapar dinilaj terlalu biasa atau malah lebib pantas sebagai tugas kuliah. saat datang berkonsultasi dengan dosen pembimbjng saya merasa malu padahal beliau orang yang baik</p>', '2026-04-13 13:38:21');
