INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17200, 4156, 32, 'admin', 'Almira Jessenia', '<p>Jika kiranya jadwal yang ditawarkan terlalu lama, kami tersedia jadwal konseling di minggu depan hari Senin 20 April 2026 dengan peer counselor / konselor sebaya kami Kak. Boleh memberi preferensi yaa apakah ingin konseling dengan peer counselor terlebih dahulu atau mau dengan psikolog pendidikan di bulan Mei :)<br /><br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-16 11:51:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17201, 4156, 32, 'admin', 'Almira Jessenia', '<p>Jika kiranya jadwal yang ditawarkan terlalu lama, kami tersedia jadwal konseling di minggu depan hari Senin 20 April 2026 dengan peer counselor / konselor sebaya kami Kak di pukul 13.00. Boleh memberi preferensi yaa apakah ingin konseling dengan peer counselor terlebih dahulu atau mau dengan psikolog pendidikan di bulan Mei :)<br /><br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-16 11:51:39');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17202, 4144, 32, 'admin', 'Almira Jessenia', '<p>Untuk durasi konseling menyesuaikan kebutuhan Kak, kami sarankan untuk tetap di tanggal 21 April agar konselingnya bisa lebih lega :) Kebetulan karena tadi kakak meminta untuk reschedule, jadwal yang besok sudah terisi dengan klien yang lain. Apa tetap ingin konseling di tanggal 21 Kak? Kami tunggu konfirmasinya yaa.. <br /><br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-16 11:56:16');
