INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17214, 4157, 103534, 'mahasiswa', 'Estella Mahendra', '<p>Saya menjadi objek fantasi seksual orang lain yang saya percaya, padahal yang bersangkutan mengetahui bahwa saya juga korban pelecehan seksual tetapi yang bersangkutan tidak menanggapinya dengan serius dan ikut melecehkan</p>', '2026-04-16 13:25:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17215, 4157, 32, 'admin', 'Almira Jessenia', '<p>Halo, selamat siang Kak Estella!<br />Terima kasih telah menghubungi Layanan Konseling UB dan telah berkenan menceritakan permasalahan Kakak. Kami dapat memahami bahwa tentu hal ini tidak mudah dilalui. <br /><br />Sebelumnya apa sudah pernah melapor ke ULTKSP / SATGAS? Jika Kakak berkenan, Kakak bisa melapor ke Satgas PPKPT UB melalui link berikut: <a data-start="886" data-end="908" rel="noopener" target="_blank" href="https://ppks.ub.ac.id/">https://ppks.ub.ac.id/</a> <br />Kakak dapat pilih menu “Laporkan” dan mengisi form yang tersedia. Kami memahami bahwa melapor mungkin terasa berat atau menakutkan, tapi Kakak berhak untuk mendapatkan perlindungan dan pendampingan.</p> <p>Kakak tidak perlu menghadapi ini sendirian. Jika Kakak butuh ruang untuk cerita lebih lanjut atau ingin didampingi secara emosional, kami sangat terbuka untuk mendampingi Kakak melalui layanan konseling. Kami tunggu konfirmasinya, yaa..<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-16 14:03:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17216, 4158, 103535, 'mahasiswa', 'Arvinna sugiharto', '<p>Saya dari sma memiliki trauma, anxiety dan panik attack saya merasa gara gara mental saya yang hancur di masa lalu  mengaruh ke masa kuliah saya saya merasa saya orang yang sering mendapatkan lingkungan yang belum bahagia saya merasa negatif, saya sudah mencoba untuk menjadi diri sendiri dan berbahagia dengan lingkungan saya yang kuliah tapi saya selalu di hantuin dengan panik attack dan anxiety saya sendiri. Saya mencoba mengobrol dengan teman saya tapi mereka tetap kontra dengan saya dan akhirnya di kasih semangat tapi saya rasakan  masih kurang dan masih ragu takut dan gemetar, saya butuh tips untuk menghilangkan rasa itu terima kasih.</p>', '2026-04-16 16:09:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17217, 3834, 102113, 'mahasiswa', 'Anak Hapsari', '<p>Baik saya berkenan </p> <p><br />terimakasih</p>', '2026-04-16 16:15:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17218, 4157, 103534, 'mahasiswa', 'Estella Mahendra', '<p>Halo kak, terima kasih sebelumnya</p> <p>sebelum saya merespon untuk melaporkan saya ingin fokus terlebih dahulu untuk pemulihan secara emosional kak, saya secara pribadi lebih membutuhkan pendampingan secara emosional</p>', '2026-04-16 18:54:47');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17219, 3834, 32, 'admin', 'Almira Jessenia', '<p>Baik terima kasih konfirmasinya, akan kami jadwalkan yaa.. untuk informasi lanjutan dan reminder akan kami hubungi melalui WhatsApp :)<br /><br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-16 19:56:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17220, 4159, 103374, 'mahasiswa', 'zhazha putri', '<p>demotivasi, gaada gairah buat ngerjain tugas, udah nyoba refreshing, keluar sama temen, nugas diluar, nugas sm temen, tetep ga ngaruh, pusing sampe ngeganggu jam tidur, mudah ke distract hal kecil, lebih mau ngelakuin hal yang ga perlu</p>', '2026-04-16 21:04:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17221, 4160, 103536, 'mahasiswa', 'Nadia Susilo', '<p>Self harm dari SMA tapi ngga tau penyebab pastinya, sekarang udah ngga terlalu sering. Ngiranya udah sembuh sendiri, tapi sering demot dan pas nyoba menjalin relationship terlalu banyak kekhawatiran dan lebih sering nethink, takutnya belum sembuh beneran dan bakal mempengaruhi relationship ke depannya.</p>', '2026-04-16 22:14:24');
