INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17255, 4162, 32, 'admin', 'Almira Jessenia', '<p>Halo, selamat malam Kak Winaya :)<br /></p> <p dir="ltr">Terima kasih telah menghubungi Layanan Konseling UB dan telah berkenan untuk menceritakan permasalahan Kakak. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah, terlebih menyangkut permasalahan penentuan karier.<br /><br />Untuk membantu mencari jalan keluar dari permasalahan Kakak, kami menyarankan untuk bertemu dengan Psikolog Industri dan Organisasi kami. Kami memiliki jadwal terdekat yang tersedia pada Hari <strong>Selasa</strong><strong>, tanggal 28 April 2026 </strong><strong>pukul 08.30</strong> secara <strong>offline</strong> dengan <strong>Ibu Fatiya. </strong>Apakah di jam dan hari tersebut kiranya kakak berkenan? Kami tunggu konfirmasinya, ya..<br /><br />Terima kasih<br />Salam hangat,<br />Tim Konseling UB.</p>', '2026-04-17 21:27:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17256, 4143, 32, 'admin', 'Almira Jessenia', '<p>Untuk tanggal nya di hari <strong>Kamis, 23 April 2026 </strong>pukul <strong>15.00</strong> secara <strong>offline </strong>yaa Kak. Untuk detail ruangan dan reminder akan kami hubungi nantinya melalui WhatsApp :)<br /><br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-17 21:30:05');
