INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17348, 4173, 103372, 'mahasiswa', 'Farras Hanun', '<p>Terimakasih sudah membalas, mohon maaf sebelumnya apakah ada opsi psikolog lain? Dikarenakan sebelumnya saya juga sudah konsultasi dengan Ibu Dian mengenai topik berbeda</p>', '2026-04-20 16:05:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17349, 4180, 103546, 'mahasiswa', 'Tantry Purba', '<p dir="ltr">Mahasiswa atas nama Tantry Purba datang dengan menangis dan wajah sembab penuh dengan beban. Yang bersangkutan setelah dipersilahkan masuk ruang konseling blm perkenalan apapun sudah menangis tersedu-sedu, konselor berusaha menenangkan dan membiarkan konseli menyelesaikan nangis nya sampai selesai. Beberapa menit kemudian konseli baru mulai tenang saya sebagai Konselor mulai membuka pembicaraan dg saling berkenalan dan ngobrol tentang hari ini seperti apa, apa yg sdg drasakan dan ingin dbagikan kepada saya sbg konselor. Dia mulai menceritakan bahwa dia ini bs dibilang living together dengan pacarnya bahkan sering berhubungan badan layaknya suami istri sah, free sex. Dan itu berjalan selama 1 tahun lebih. Dan sama-sama orangtua masing-masing tau. Namun Orangtua dari Tantry menolak hubungan ini begitu juga orang tua dari pacarnya juga menolak hubungan tsb padahal kondisi konseli saat itu hamil sehingga konseli depresi dan berobat di psikiater. Sempat rutin mintum obat tp karena merasa tidak ada efek sampai pernah minum obat tersebut sampai overdosis yang mengakibatkan keguguran dan kondisi tersebut diketahui oleh kedua orangtua mereka. Semua berjalan biasa dan baik. Akan tetapi si laki-laki ini dalam akhir-akhir ini mulai berubah cuek dan tdk mmperhatikan konseli seperti biasanya, cuma maunya senidiri aja : minta uang, mnt dbeliin makan, mnt dbayarin bensin dll tp jika laki-laki tersebut butuh menyalurkan nafsu birahi nya si konseli ini dibaik-baikin. Laki-laki pacarnya ini banyak dekat dengan perempuan lain juga akhir-akhir ini tdk bisa diingatkan berbuat semauanya dan memutuskan hidup sendiri-sendiri. Merasa tidak nyaman lagi, konseli memutuskan untuk meninggalkan laki-laki ini tapi disisi lain konseli takut tidak ada pria untuk menemani masa depannya kelak krn merasa keperawanannnya sdh hilang mana ada yg mau sama aku, merasa takut tidak ada teman untuk berbagi lagi dll</p> <p><br /></p>', '2026-04-20 16:07:29');
