INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17352, 4179, 33, 'admin', 'Nafa Tsaniya', '<p>Baik kak, kami bantu jadwalkan pada waktu tersebut ya. Untuk Informasi selanjutnya akan kami sampaikan melalu Whatsapp saat akan mendekati sesi konseling.<br /><br />Terima Kasih.<br />Salam Hangat,<br />Layanan Konseling UB</p>', '2026-04-20 18:00:29');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17353, 4172, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat malam, Kak Shafiqa!<br /><br />Terima kasih telah berkenan untuk menceritakan permasalahan Kakak lebih detail. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk mendiskusikan lebih lanjut mengenai hal yang Kakak alami, apakah kiranya bersedia melakukan konseling dengan <strong>peer counselor / konselor sebaya </strong> kami pada <strong>Hari Kamis, tanggal 23 April 2026 pukul 11.00 WIB dengan Kak Nafis secara offline. </strong>Apakah berkenan kami jadwalkan pada waktu tersebut? Kami tunggu konfirmasinya yaa :)</p> <p>Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-04-20 19:23:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17354, 4139, 33, 'admin', 'Nafa Tsaniya', '<p>Jika kami jadwalkan pada hari <strong>Rabu, 22 April 2026 pukul 09.00</strong> secara online/offline apakah kakak berkenan?</p>', '2026-04-20 19:55:13');
