INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17356, 4180, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat malam, Kak Tantry! :)<br /><br />Terima kasih telah menghubungi Layanan Konseling UB dan telah berkenan untuk menceritakan permasalahan Kakak. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk membantu mencari jalan keluar dari permasalahan Kakak, kami menyarankan untuk bertemu dengan <strong>Psikolog</strong> kami yaitu Ibu Dian<strong>.</strong> jadwal terdekat tersedia pada hari <strong>Selasa, 28 April 2026 pukul 10.00 WIB secara offline. </strong>Apakah kiranya berkenan jika dijadwalkan pada hari dan jam tersebut?<br /><br />Kami tunggu konfirmasinya, yaa..<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-20 20:05:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17357, 4155, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat malam, Kak Putri!<br /><br />Mohon maaf sebelumnya, jadwal psikolog kami pada tanggal 27 April 2026 sudah terisi, kak. Jika kami bantu jadwalkan pada <strong>Rabu, 29 April 2026 pukul 10.00</strong> secara <strong>offline </strong>dengan Psikolog kami atas nama Pak Yafi apakah kakak berkenan?<br /><br /><strong>Kami tunggu konfirmasinya, ya...</strong><br /><br /><strong>Terima Kasih.</strong><br /><strong>Salam Hangat, </strong><br /><strong>Layanan Konseling UB</strong></p>', '2026-04-20 20:20:24');
