INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17417, 4192, 103557, 'mahasiswa', 'Aveline Evania', '<p>Mohon maaf kak, dua jadwal tersebut juga bertabrakan..kalau di hari Kamis atau Jumat apakah ada? Kalau tidak mungkin yang Senin tadi pukul 9 tidak apa apa kak, nanti saya izin</p>', '2026-04-22 10:31:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17418, 4195, 103560, 'mahasiswa', 'Difa', '<p>Saya ngga pernah ke psikolog jadi saya ngga tau gejala apa yang sedang saya alami. Saya sering merasa kosong tapi pikiran dan hati terasa penuh , sering emosi ngga stabil dan susah untuk mengendalikan diri ketika saya sedang marah dan ngga ada yang bisa menenangkan saya kecuali diri saya sendiri. Dari kecil Saya selalu memiliki masalah dengan keluarga. Saya pernah memiliki masalah berat yang semua wanita ngga mau merasakannya disaat itu saya merasa setres atau depresi , setiap hari saya menjadi pribadi saya yang lain yang pura-pura baik ke orang lain tapi diri saya yang asli susah untuk diajak ngobrol karena emosi yang ngga stabil saya selalu menahan diri saya , hingga saya ngga tau udah 1 tahun saya kuliah ini ngerasain kayak bisa mendengar materi yang disampaikan dosen tapi saya ngga bisa nyimpen dimemori saya jadi kayak ngeblank tapi emang ngga bisa di inget lagi semakin syaa inget kepala saya semakin sakit walaupun saya sudah fokus tapi tetap ngga bisa keinget , jadi setiap kuliah saya hanya bisa mencatat yang penting dan merekam suara yang dijelaskan dosen hingga dirumah saya mencoba memahami dan mengerti dikit demi sedikit, apalagi ketika ujian saya ngga bisa mengingat banyak yang saya pelajari saya hanya bisa pasrah. Jadi apa yang terjadi sama diri saya? Kalo saya tanya di AI saya ngalamin ptsd tapi yang jelas itu ngga valid kalo ngga tanya dengan yang jelas, terimakasih.</p>', '2026-04-22 10:34:55');
