INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17420, 4188, 33, 'admin', 'Nafa Tsaniya', '<p>Untuk saat ini jadwal Bu Dian masih belum tersedia, kak. Jika jadwal beliau sudah ada akan kami kabari kembali melalui WhatsApp untuk penjadwalannya, ya. </p> <p>Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-04-22 10:40:35');
