INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17456, 4194, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat malam, Kak Rahma!<br /><br />Terima kasih karena telah menghubungi Layanan Konseling UB. Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Kami sangat memahami pasti situasi ini tidak mudah untuk dilalui. Untuk saat ini jadwal Psikolog kami di minggu depan sudah penuh, dan di minggu selanjutnya masih belum tersedia. Akan kami kabari lagi terkait penjadwalannya nanti melalui WhatsApp jika jadwalnya sudah tersedia ya, Kak.<br /><br />Terima Kasih.<br />Salam Hangat,<br />Layanan Konseling UB</p>', '2026-04-22 20:14:57');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17457, 4197, 33, 'admin', 'Nafa Tsaniya', '<p>Kebetulan untuk jadwal konseling dengan Bu Ika untuk 2 minggu kedepan sudah terisi, Kak. Karena jadwal beliau hanya 1 kali setiap minggunya. Jadwal beliau tersedia lagi di hari Senin, 11 Mei 2026 pukul 10.30. Apakah Kakak mau menunggu sampai tanggal 11 Mei atau berkenan untuk kami alihkan ke psikolog  lain? <br /><br />Kami tunggu konfirmasinya, yaa...<br /><br />Terima Kasih.<br />Salam Hangat, <br />Layanan Konseling UB</p>', '2026-04-22 20:21:17');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17458, 3955, 101887, 'mahasiswa', 'Susan Firdausi', '<p><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit">Mohon maaf baru membalas kak Melsy Nemasari karena energi saya sudah kesedot untuk hal lain. </span></span></p> <p><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit"><span dir="auto" style="vertical-align:inherit">Untuk kemarin malam saya sudah bisa tidur kak jadi saat ini belum ada yang saya ceritakan. Terimakasih Kak Melsy :) </span></span></span></span></p>', '2026-04-22 20:46:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17459, 4198, 103562, 'mahasiswa', 'Lintang Nurdianly', '<p>Halo, saya mahasiswi akhir dari prodi ilmu perpustakaan fia. Saya ingin melakukan konseling karena dari awal nyusun skripsi sudah sering merasa cemas dan tertekan ketika memikirkan progres yang melambat, yang justru membuat saya semakin menghindari pengerjaan skripsi sudah setahun, sekarang lagi berobat juga ke psikiater karena sempat relapse dan self destruct berkali-kali. Semoga dari konseling nanti saya bisa balik nyusun skripsi tanpa harus merasa cemas atau tertekan. Terima kasih.</p>', '2026-04-22 21:15:52');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17460, 4199, 103562, 'mahasiswa', 'Lintang Nurdianly', '<p>Halo, saya mahasiswi tingkat akhir dari fia. Dari awal nyusun skripsi saya sudah merasa cemas dan tertekan ketika memikirkan progres yang melambat, yang justru membuat saya semakin menghindari pengerjaan skripsi sudah hampir setahun. Sudah berobat juga ke psikiater karena sempat self destruct berkali-kali. Saya harap konseling nanti bisa membantu saya dalam penyusunan skripsi ini, terima kasih.<br /><br /></p>', '2026-04-22 21:19:04');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17461, 4196, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat malam, Kak Nadia! :)<br /><br />Terima kasih telah menghubungi Layanan Konseling UB dan telah berkenan untuk menceritakan permasalahan Kakak. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk membantu mencari jalan keluar dari permasalahan Kakak, kami menyarankan untuk bertemu dengan Psikolog kami pada hari <strong>Senin, 4 Mei 2026 pukul 10.00 WIB secara offline. </strong>Apakah kiranya berkenan jika dijadwalkan pada hari dan jam tersebut?<br /><br />Kami tunggu konfirmasinya, yaa..<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-22 22:11:16');
