INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17510, 4206, 103566, 'mahasiswa', 'Intan', '<p>Anak pertama yang mulai dibebankan dengan ekonomi keluarga, bingung harus bagaimana? gabisa fokus kuliah saja karena pikiran jadi terpecah antara ekonomi keluarga dan akademik. Sempat beberapa kali berpikir apa mati aja? biar tidak membebankan orang tua? </p>', '2026-04-24 17:39:11');
