INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17512, 4205, 103565, 'mahasiswa', 'Kezya Anabila', '<p>Halo, sebelumnya saya izin konfirmasi, tadinya saya memilih untuk layanan online, mungkin ada kesalahan? Sebenarnya tidak masalah untuk saya, hanya memastikan.</p>', '2026-04-24 17:59:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17513, 4155, 100949, 'mahasiswa', 'Putri Kamila', '<p>Hai kak, maaf menganggu waktunya. Saya sebelumnya mohon maaf sebesar-besarnya, tp untuk jadwal konselingnya apakah bisa direarrange yaa kak? Karena saya ada keperluan keluarga mendadak di jam tersebut kak, dan saya baru dikabari, saya mohon maaf kak </p>', '2026-04-24 19:34:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17514, 4207, 103567, 'mahasiswa', 'Rahmadilla Nastiti', '<p>saya habis ditipu habis habisan oleh seseorang yang saya kenal, intinya saya belum bisa melupakan dan belum mendapatkan solusi atas permasalahan tersebut. akhirnya sekarang saya merasa sering ke trigger apabila ada sesuatu yang meningatkan pada permasalahan itu, kadang juga tiba tiba teringat sendiri. saya jadi sangat sering menangis saat sendirian, saya juga sulit untuk meluapkan emosi saya dan juga kesulitan untuk tidur. apabila trigger itu sudah muncul saya merasakan rasa yang tidak enak di tubuh dan pikiran saya seperti gemetar, panas dingin dan tekadang mual</p>', '2026-04-24 22:19:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17515, 4208, 102028, 'mahasiswa', 'Nadya Azizah', '<p>akhir akhir ini sering keinget kejadian-kejadian jelek yg bikin trauma alhasil ngaruh ke keseharian, beberapa kali sering ke trigger dan makin gampang buat ke trigger/keinget even itu hal kecil.. aku juga jadi mimpi tentang kejadiannya terus, selalu bikin tidur jadi gak tenang, aku juga takut bahkan terakhir kali aku gemeteran di tempat umum karena keinget lagi dan entah kenapa akhir-akhir ini pikiranku penuh banget, semua jadi satu, capek cuma aku gatau harus gimana dan kepikiran buat akhirin hidup sering munculakhir-akhir ini saking capeknya</p>', '2026-04-24 22:21:51');
