INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17517, 4210, 103567, 'mahasiswa', 'Rahmadilla Nastiti', '<p>saya habis ditipu habis habisan oleh seseorang yang saya kenal, intinya saya belum bisa melupakan dan belum mendapatkan solusi atas permasalahan tersebut. akhirnya sekarang saya merasa sering ke trigger apabila ada sesuatu yang meningatkan pada permasalahan itu, kadang juga tiba tiba teringat sendiri. saya jadi sangat sering menangis saat sendirian, saya juga sulit untuk meluapkan emosi saya dan juga kesulitan untuk tidur. apabila trigger itu sudah muncul saya merasakan rasa yang tidak enak di tubuh dan pikiran saya seperti gemetar, panas dingin dan tekadang mual</p>', '2026-04-24 22:23:07');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17518, 4211, 103567, 'mahasiswa', 'Rahmadilla Nastiti', '<p>saya habis ditipu habis habisan oleh seseorang yang saya kenal, intinya saya belum bisa melupakan dan belum mendapatkan solusi atas permasalahan tersebut. akhirnya sekarang saya merasa sering ke trigger apabila ada sesuatu yang meningatkan pada permasalahan itu, kadang juga tiba tiba teringat sendiri. saya jadi sangat sering menangis saat sendirian, saya juga sulit untuk meluapkan emosi saya dan juga kesulitan untuk tidur. apabila trigger itu sudah muncul saya merasakan rasa yang tidak enak di tubuh dan pikiran saya seperti gemetar, panas dingin dan tekadang mual</p>', '2026-04-24 22:23:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17519, 4212, 103567, 'mahasiswa', 'Rahmadilla Nastiti', '<p>saya habis ditipu habis habisan oleh seseorang yang saya kenal, intinya saya belum bisa melupakan dan belum mendapatkan solusi atas permasalahan tersebut. akhirnya sekarang saya merasa sering ke trigger apabila ada sesuatu yang meningatkan pada permasalahan itu, kadang juga tiba tiba teringat sendiri. saya jadi sangat sering menangis saat sendirian, saya juga sulit untuk meluapkan emosi saya dan juga kesulitan untuk tidur. apabila trigger itu sudah muncul saya merasakan rasa yang tidak enak di tubuh dan pikiran saya seperti gemetar, panas dingin dan tekadang mual</p>', '2026-04-24 22:23:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17520, 4213, 102028, 'mahasiswa', 'Nadya Azizah', '<p>akhir akhir ini pikirannya kaya berisik banget dan penuh, kaya ada yg ngomong di dalem kepala dan rasanya kaya di keramaian.. kejadian kejadian traumatis juga sering keinget lagi dan bikin ke-trigger, terakhir kali muncul pas di tempat umum dan alhasil gemeteran. cuma aku ngerasa perubahan mood aku cepet, kalau hari ini aku sedih dan mikir untuk selesai, besoknya aku bisa full energy bahkan aku mood untuk ngobrol dengan orang terus, kaya gini juga ngaruh ke tidurku dan makanku, berulang kali aku mimpi buruk &amp; sering kebangun di pertengahan malam</p>', '2026-04-24 22:29:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17521, 4214, 103567, 'mahasiswa', 'Rahmadilla Nastiti', '<p>saya habis di tipu oleh seseorang yang saya kenal dan belum sepenuhnya menemukan solusi dan belum bisa mengikhlaskan musibah yang menimpa saya. akibatnya saya sampai saat ini masih sering ke trigger apabila mengingat hal yang membuat saya trauma itu saya sering menyalahkan diri saya sendiri, dan apabila trigger itu muncul saya merasakan hal yang tidak enak ada di dalam diri saya seperti gemetar seluruh tubuh, dada terasa sesak dan terkadang sampai mual. saya juga merasa kesulitan untuk meluapkan emosi saya serta kesulitan tidur akibat overthingking yang berlebihan. ketika saya sedang sendirian biasanya saya suka menangis sendiri di dalam kamar ataupun ketika di jalan</p>', '2026-04-24 22:31:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17522, 4215, 102028, 'mahasiswa', 'Nadya Azizah', '<p>akhir akhir ini pikirannya kaya berisik banget dan penuh, kaya ada yg ngomong di dalem kepala dan rasanya kaya di keramaian.. kejadian kejadian traumatis juga sering keinget lagi dan bikin ke-trigger, terakhir kali muncul pas di tempat umum dan alhasil gemeteran. cuma aku ngerasa perubahan mood aku cepet, kalau hari ini aku sedih dan mikir untuk selesai, besoknya aku bisa full energy bahkan aku mood untuk ngobrol dengan orang terus, kaya gini juga ngaruh ke tidurku dan makanku, berulang kali aku mimpi buruk &amp; sering kebangun di pertengahan malam</p>', '2026-04-24 22:32:43');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17523, 4216, 103567, 'mahasiswa', 'Rahmadilla Nastiti', '<p>saya habis di tipu oleh seseorang yang saya kenal dan belum sepenuhnya menemukan solusi dan belum bisa mengikhlaskan musibah yang menimpa saya. akibatnya saya sampai saat ini masih sering ke trigger apabila mengingat hal yang membuat saya trauma itu saya sering menyalahkan diri saya sendiri, dan apabila trigger itu muncul saya merasakan hal yang tidak enak ada di dalam diri saya seperti gemetar seluruh tubuh, dada terasa sesak dan terkadang sampai mual. saya juga merasa kesulitan untuk meluapkan emosi saya serta kesulitan tidur akibat overthingking yang berlebihan. ketika saya sedang sendirian biasanya saya suka menangis sendiri di dalam kamar ataupun ketika di jalan</p>', '2026-04-24 23:01:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17524, 4217, 103569, 'mahasiswa', 'Farhah syahidah', '<p>Belakangan ini saya selalu merasa kesulitan untuk meredakan tangisan ketika sendiri di malam hari dan merasa sesak napas, detak jantung terasa begitu cepat dan pusing. Ini terjadi ketika saya mengingat atau merasa trauma yang saya tutupi dari kecil mulai muncul di lingkungan sekitar saya dan saya akan meluapkan ketika malam hari. </p>', '2026-04-25 00:03:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17525, 4218, 103570, 'mahasiswa', 'Khulna', '<p>saya sering mempertanyakan apakah saya cukup penting bagi teman-teman saya, saya juga sering merasa takut mengganggu atau menjadi beban.</p> <p>Selain itu, saya juga merasa takut menjadi terlalu attached dalam pertemanan dan saya merasa seperti tidak benar-benar punya seseorang untuk diajak bicara saat sedang merasa sedih. <br />saya hal ini cukup mengganggu dan lelah<br /></p>', '2026-04-25 00:58:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17526, 4204, 33, 'admin', 'Nafa Tsaniya', '<p>Baik kak, terima kasih atas konfirmasinya akan kami jadwalkan pada waktu tersebut, ya. Untuk informasi selanjutnya akan kami sampaikan melalui WhatsApp saat akan mendekati sesi konseling.<br /><br />Terima Kasih.<br />Salam Hangat,<br />Layanan Konseling UB</p>', '2026-04-25 09:31:17');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17527, 4203, 36, 'admin', 'Aura Ratu', '<p>Baik kak Odie, terimakasih atas konfirmasinyaa! untuk informasi selanjutnya akan kami informasikan melalui whatsapp mendekati hari pelaksanaan konseling yaa! </p> <p>Terimakasih,<br />Salam Hangat<br />Tim Konseling UB<br /></p>', '2026-04-25 09:32:01');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17528, 4155, 36, 'admin', 'Aura Ratu', '<p>Halo kak Putri, Selamat Pagi!</p> <p>Terimakasih yaa atas konfirmasinyaa ! Baik, untuk penjadwalan ulang apakah kakak berkenan untuk kami jadwalkan pada <strong>Kamis, 10 Mei 2026 pukul 10.00 WIB. </strong>Apakah kakak berkenan untuk kami jadwalkan pada sesi tersebut?</p> <p>Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-04-25 09:35:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17529, 4188, 36, 'admin', 'Aura Ratu', '<p>baik kak, terimakasih atas konfirmasinya! untuk informasi selanjutnya akan kami hubungi segera ya kaak!</p>', '2026-04-25 09:37:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17530, 4206, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat pagi, Kak Intan! :)</p> <p>Terima kasih karena telah menghubungi Layanan Konseling UB. Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Kami sangat memahami pasti situasi ini tidak mudah untuk dilalui. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p>1. Apakah Anda berkenan mendeskripsikan lebih detail masalah yang Anda alami?<br />2. Apakah masalah tersebut berdampak ke kegiatan keseharian Anda? (Seperti pola makan, pola tidur, aktivitas sosial, dll)<br />3. Apa ada hal yang sudah Anda lakukan untuk mengatasi hal tersebut? Dan apakah hal tersebut membantu?<br />4. Apa harapan Anda menghubungi layanan kami?</p> <p>Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-25 09:38:36');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17531, 4205, 36, 'admin', 'Aura Ratu', '<p>baik kak, kakak berkenan untuk konseling secara online yaa.. akan kami jadwalkan pada hari Rabu<strong>, 6 Mei 2026 pukul 10.00 WIB secara online </strong>yaa!</p> <p>Kami tunggu konfirmasinya, yaa..<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-04-25 09:39:12');
