INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17585, 4221, 103517, 'mahasiswa', 'ANDINI RAHMAH', '<p>Selamat sore kak, maaf sebelumnya untuk jam konselingnya apakah bisa diganti di hari yang sama yaa kak? Apabila tidak bisa saya bersedia di minggu depan kak. Terima kasih.</p>', '2026-04-27 17:07:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17586, 4227, 103575, 'mahasiswa', 'BIMA PANDUNATA', '<p>Burn out, cemas, pikiran negatif, perasaan tertekan yang membuat diri susah untuk bangun dan produktif, berujung ke mual, pusing dan sakit kepala saat, gangguan tidur dan sesak, serta pikiran untuk menyakiti dan mengakhiri diri</p>', '2026-04-27 17:55:04');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17587, 4228, 103576, 'mahasiswa', 'Nasela Aurelia', '<p>5 tahun lalu mama sama ayah meninggal dunia dengan jarak 2 hari pada tahun yang sama juga nenek dari ayah meninggal 3 bulan sebelumnya, sekarang harus tinggal sama kakek nenek dengan semua permasalahan keuangan yang aku harus ngerti di umur yang masih 15 waktu itu juga tekanan dan tanggung jawab sebagai anak pertama, tahun kemarin  nenek dari mama meninggal dunia karena sakit dan 1 bulan setelahnya disusul kakek dari ayah juga meninggal dunia. Kuliah semester 3 berantakan, tapi lagi-lagi hidup harus tetap berjalan dengan semua permasalahan tanggung jawab dan kewajiban yang ada. Harus jadi anak pertama yang nurut diatur a b c oleh keluarga mama tapi hidup gada pilihan lain, kalo salah atu ada yang ga sesuai selalu ditanya "kok bisa? Kenapa  gitu?" Sekarang cuma tinggal bertiga bareng kakek dan adik, tanggung jawab masak dan rumah tangga jadi tanggung jawab baru yang berat buat aku yang belum genap 20 tahun, oiya selain kuliah senin-jumat aku juga kerja sabtu minggunya 8-10 jam </p>', '2026-04-27 19:01:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17588, 4227, 34, 'admin', 'Heidemarie Gunarso', '<p dir="ltr">Selamat malam, Kak Bima Pandunata!</p> <p dir="ltr">Terima kasih karena telah menghubungi Layanan Konseling UB. Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Kami sangat memahami pasti situasi ini tidak mudah untuk dilalui. Kami mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail masalah yang Anda alami? Menurut Anda apa penyebab hal tersebut terjadi?<br />2. Dari yang Anda rasakan, sudah berapa lama masalah tersebut berdampak ke kegiatan keseharian Anda?<br />3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?<br />4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-27 20:22:55');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17589, 4228, 34, 'admin', 'Heidemarie Gunarso', '<p dir="ltr">Selamat malam, Kak Nasela Aurelia!<br />Terima kasih karena telah menghubungi Layanan Konseling UB. Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Kami sangat memahami pasti situasi ini tidak mudah untuk dilalui. Kami mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Dari permasalahan yang Anda alami, apa yang Anda rasakan sekarang? <br />2. Dari yang Anda rasakan, sudah berapa lama masalah tersebut berdampak ke kegiatan keseharian Anda? Apakah sudah mengganggu aktivitas sehari Anda?<br />2. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?<br />3. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-04-27 20:35:13');
