INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17599, 4231, 103580, 'mahasiswa', 'Handaru Nanda', '<p>saya seorang porn addict dari sekolah dasar, dan sampai saat ini belum menemukan cara untuk sembuh. Belakangan ini hal tersebut sedikit banyak mempengaruhi cara saya mengambil keputusan terlebih keputusan yang krusial bagi hidup saya. Saya juga sering mengalami overthinking, anxious, dan insecurity.</p>', '2026-04-28 14:41:18');
