INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17657, 4252, 101680, 'mahasiswa', 'Haura Arikah', '<p>akhir-akhir ini saya semakin khawatir stress berlebihan bikin saya gampang terdistraksi dan susah fokus, saya juga merasa cepat lupa suatu hal, ini cukup menghambat keseharian saya apalagi smt 6 ini mulai menyiapkan skripsi, saya juga takut self-diagnose klo saya ADHD jd saya ingin coba konsultasikan kecemasan saya yg berlebihan ini yg mulai mempengaruhi produktivitas sehari-hari</p>', '2026-04-29 20:15:20');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17658, 4178, 103545, 'mahasiswa', 'NOVIANA NURASIKIN', '<p>Haloo! Maaf sebelumnya saya baru membuka dan membaca pesannya, jika boleh apakah bisa di reschedule ulang? karena berhubung minggu lalu pun jadwal saya padat sehingga saya melupakan sesi konselingnya</p>', '2026-04-29 20:37:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17659, 4253, 103593, 'mahasiswa', 'Adwinda Amalia', '<p>merasa memiliki masalah dari beberapa faktor mulai dari keluarga, keuangan, pendidikan, pertemanan dan organisasi yang kurang sehat yang menjadi domino effect dan berakibat pada diri sendiri. </p> <p>mayoritas yang menjadi benang kusut saat ini adalah pernah berada di organisasi yang kurang sehat dan masalah pertemanan. </p>', '2026-04-29 21:18:19');
