INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17670, 4254, 103594, 'mahasiswa', 'DEBORA WAHYUDI', '<p>jujur saya tidak tahu ini masuknya ke jenis konseling apa, tapi ini mengganggu saya sebagai pelajar. saya juga merasa bahwa saya tidak pantas berada di jurusan ini karena satu dan lain hal.</p>', '2026-04-30 14:35:04');
