INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17724, 4273, 103414, 'mahasiswa', 'Raihan', '<p>aku biasanya dipanggil ian. ian disini mau pelajarin tentang diri ian, apa yg nyebabin ian sampe di titik itu, apa akar dari ian bisa melakukan itu, dan gimana cara nyelesain dan menutup hal-hal itu semua. ian juga pengen tau gimana cara nyalurin emosi ian dengan baik disaat dimanapun ian berada. ian juga mau tau gimana cara menghadapi orang2 yg pernah dan nnti terlibat dengan ian di masa lalu dan yg akan dtg nnti. terima kasih.</p>', '2026-05-02 22:13:56');
