INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17729, 4274, 103603, 'mahasiswa', 'fitri syamsuddin', '<p>(kemarin saya sudah mengisi untuk online tapi saya rasa saya lebih membutuhkan offline)<br />saya benar benar sedang merasa full, saya sangat merasakan lelah, saya rasa saya ga sanggup tapi sebenernya saya tau saya bisa ntah karna saya tipekal yang semuanya bisa saya handle padahal aslinya saya merasa kewalahan, saya gamau ngerepotin orang, saya mau keliatan baik- baik saja di depan orang lain.<br /><br />jam tidur saya terbalik, saya susah tidur, saya baru bisa tidur di jam 3 atau 4 shubuh baru bisa tidur walaupun seharian beraktivitas, kadang mium panadol atau antimo atau keduanya biar bisa tidur. lalu setelah bangunpun saya ga merasakan fresh tapi malah pegal sebadan.<br /><br />saya gatau apakah valid atau tidak saya mencoba untuk test tingkat stress saya di 3 web hasilnya sama semua ada di tingkat stress tinggi dengan skor 27.<br /><br />apakah saya menyakiti diri? sejauh ini belum karena alasan sesimple saya ga suka ada bekas luka di badan saya karena ga aesthetic.<br /><br />akhir-akhir ini saya ngerasa mellow sedih tapi saya susah mengekspresikannya, kadang nonton film sedihpun yauda sedih tapi susah nangis.<br /><br />saya juga gampang ke pecah fokusnya dan gampang lupa tapi itu udah dari lama, tipekal yang gampang ke distract kalau omongannya dipotong terus jadi lupa mau ngomong apa lanjutannya.<br /><br />jadi saya ngerasa capek awalnya saya kira karena mau sidang, rasanya tuh penuh ga ngapa2inpun capek kayak burnout terus bawaannya mellow, tapi ternyata after sidang juga sama aja, bahkan after sidangpun ga ngerasa lega kayak yauda lewat aja. (saya sidang tgl 29 april) mungkin karena skripsi belum selesai karena masih ada revisian. lalu yudis tinggal sebentar lagi, belum revisian skripsi sama sekali karena belum bimbingan dan belum ada jadwal bimbingan, cuman punya waktu 5 hari buat ngejar yudis dengan revisi mayor. lalu belum test toefl + tes TI. kost sampai bulan juni dan belum tau wisuda kapan?.<br /><br />ditambah ⁠interview kerja tadi baru interview tahap 1, lalu baru dikabarin lagi lolos ke tahap selanjutnya +- 1 minggu lagi, dan kalau lolos ada tahap 2 interview lagi baru habis itu final keterima atau engga.<br /><br />jadi pembanding ujian nyiapin materi cuman punya waktu sehari.<br /><br />⁠interview volunteer + ketua judge volunteer judge tipekal ngomongin dan maki maki dibelakang ke semua orang.<br /><br />⁠belum latian fisik buat hiking , jd stress mikirin doang tanpa dilakuin. mungkin karena stress jadi gamau ngapa-ngapain bawaanya mau dikasur terus tapi ga bisa tidur juga pas dikasur.<br /><br />BENCI BGT DIA MASIH ADA, dengan dia liat story &amp; like itu juga mengganggu aku tapi disisi lain aku mau dia liat emang tanpa dia aku gacor dari dluu, jahat memang tp better dia ada sisi tuhan aja.<br /><br /><br /></p>', '2026-05-03 03:22:14');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17730, 4275, 101723, 'mahasiswa', 'YULISTA YST', '<p>saya merasa sangat di rugikan, dijadikan social cover, saya mengetahui hal besar dan diam, saya tidak pernah cerita ke siapa2 tentang hal ini, dan sudah di tahap mengganggu ketenangan saya, ingin menyelesaikan dan ingin fokus ke hal yang lebih penting, hal yang sangat sensitive dan rahasia</p>', '2026-05-03 07:59:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17731, 4275, 34, 'admin', 'Heidemarie Gunarso', '<p dir="ltr">Selamat pagi, Kak Yulista YST!</p> <p dir="ltr">Terima kasih karena telah menghubungi Layanan Konseling UB. Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Kami sangat memahami pasti situasi ini tidak mudah untuk dilalui. Kami mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail masalah yang Anda alami? Menurut Anda apa penyebab hal tersebut terjadi?<br />2. Dari yang Anda rasakan, sudah berapa lama masalah tersebut berdampak ke kegiatan keseharian Anda?<br />3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?<br />4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr"><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.<br /></p>', '2026-05-03 10:18:41');
