INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17860, 4294, 32, 'admin', 'Almira Jessenia', '<p>Halo, selamat malam Kak Rauf :)<br /><br />Baik, terima kasih telah berkenan menceritakan lebih detail permasalahan Kakak yaa.. Untuk jadwal setelah 20 Mei tersedia di 21 dan 22 Mei (untuk jam nya masih belum tersedia, sehingga kami harus konfirmasi ke Ibu Dian terlebih dahulu). Serta untuk melaksanakan konseling dengan teman, apakah sebelumnya sudah ada arahan dari Ibu Dian terkait hal tersebut? jika belum ada, kami bisa bantu sampaikan kepada Ibu Dian.<br /><br />Kiranya di tanggal 21 dan 22 Mei, kakak berkenan dijadwalkan di tanggal berapa? Kami tunggu konfirmasinya, yaa...<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-05-05 20:33:18');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17861, 4308, 32, 'admin', 'Almira Jessenia', '<p>Selamat malam Kak Fadil:)<br /><br />Terima kasih telah menghubungi Layanan Konseling UB dan telah berkenan untuk menceritakan terkait permasalahan Kakak dan apa yang Kakak rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk mendiskusikan lebih lanjut mengenai hal yang Kakak ceritakan, apakah kiranya bersedia melakukan konseling dengan <strong>psikolog</strong> <strong>klinis </strong>kami aas nama <strong>Ibu Yunita</strong>? Namun karena jadwal di minggu ini dan minggu depan sudah penuh, jadwal dengan psikolog kami baru tersedia di akhir bulan. Jadwal yang terdekat ada pada <strong>Hari Rabu, 20 Mei 2026 pukul 11.00 WIB secara offline.</strong><br />Kami tunggu konfirmasinya yaa :)</p> <p>Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-05-05 20:38:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17862, 4307, 32, 'admin', 'Almira Jessenia', '<p>Selamat malam Kak Verdian :)<br /><br />Terima kasih telah menghubungi Layanan Konseling UB dan telah berkenan untuk menceritakan terkait permasalahan Kakak dan apa yang Kakak rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk mendiskusikan lebih lanjut mengenai hal yang Kakak ceritakan, apakah kiranya bersedia melakukan konseling dengan <strong>psikolog</strong> kami? Karena sebelumnya kakak melaksanakan konseling dengan Ibu Dian, apa berkenan dijadwalkan kembali dengan Ibu Dian? Jadwal yang terdekat ada di sekitar tanggal 18-22 Mei. Kami juga memiliki opsi psikolog pendidikan jika memang fokus yang ingin dibahas perihal pilihan arah karier.<br /><br />Kami tunggu konfirmasinya yaa :)</p> <p>Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-05-05 20:49:30');
