INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17903, 4294, 35, 'admin', 'Melsy Nemasari', '<p>Baik, karena untuk saat ini jadwal Bu Dian belum keluar, nanti jika jadwal Bu Dian sudah keluar nanti akan kami hubungi kembali yaa, Kak. Untuk informasi selanjutnya akan kami hubungi melalui WhatsApp yaa :)<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-05-06 18:24:28');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17904, 4311, 35, 'admin', 'Melsy Nemasari', '<p>Halo, selamat malam Kak Darmawansyah! :)<br /><br />Apakah berkenan jika mendeskripsikan lebih detail kiranya permasalahan seperti apa yang akan dibahas dengan Bu Ikaf? Kami tunggu konfirmasinya yaa :)<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.<br /></p>', '2026-05-06 18:27:48');
