INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17933, 4316, 101756, 'mahasiswa', 'Verdian Putra', '<p>sebenernya saya ingin mendapatkan insight baru sih ka...  jujur oke kok apa yg disampaikan ibu dian tapi kekhawatjran saya ini lumayan menganggu ya ahkir ahkir ini sekaligus saya juga mo nanya klo emg psikologi pendidikan jni nti apa ya spessialnya dan alasan kenapa kaka menawarkan saya psikolog pendidikan ya soalnya klo yg saya lihat dari apa yg saya rasakan sebenernya kepingan karir ini juga bagian dari kepingan kepingan dari keseluruhan masalah yg saya alami jadi apa sebenernya yg saya butuhkan saja saya bingung kasih alasan saya dong ka terkait masalah saya ini apakah saya harus menggunakan psikolog yg barh atau stay saja sama ibu dian<br /></p>', '2026-05-07 13:12:38');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (17934, 4259, 103597, 'mahasiswa', 'MUHAMMAD NURROHMAN', '<p>Selamat siang, sebelumnya saya memohon maaf baru bisa membalas hari ini, 7 Mei, karena sebelumnya saya sempat mengalami kendala teknis saat mengakses web ini. </p> <p>Saya ingin menginformasikan bahwa saat ini saya sudah merasa jauh lebih baik dan sudah menemukan cara untuk mengelola situasi saya secara mandiri. Oleh karena itu, saya izin untuk membatalkan rencana konseling selanjutnya. Sekali lagi terima kasih atas bantuannya.</p>', '2026-05-07 15:40:58');
