INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18022, 4339, 102949, 'mahasiswa', 'Najla Jannati', '<p>Selamat Siang,</p> <p>Apakah memungkinkan jika dilakukan Selasa, 12 May besok setelah pukul 12.00? Apabila tidak memungkinkan, apakah jika online memungkinkan di hari rabu itu? Karena di hari Rabu saya ada agenda lainnya. </p> <p>Sebelumnya mohon maaf dan terima kasih banyak </p>', '2026-05-11 14:46:32');
