INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18038, 4340, 33, 'admin', 'Nafa Tsaniya', '<p>Baik kak, akan kami jadwalkan pada waktu tersebut ya. Untuk informasi selanjutnya akan kami sampaikan melalui Whatsapp saat akan mendekati sesi konseling.<br /><br />Terima Kasih.<br />Salam Hangat, <br />Layanan Konseling UB</p>', '2026-05-12 08:26:31');
