INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18041, 4179, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat pagi, Kak Zahwa!<br /><br />Mohon maaf atas keterlambatan membalas karena banyaknya antrian yang masuk. Untuk saat ini jadwal di minggu depan dengan Psikolog kami sudah penuh, Kak. Apakah berkenan jika kami jadwalkan pada minggu selanjutnya pada tanggal 25/26 Mei?<br /><br />Kami tunggu konfirmasi nya, ya...</p> <p>Terima Kasih.<br />Salam Hangat,<br />Layanan Konseling UB<br /></p>', '2026-05-12 08:38:48');
