INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18043, 4343, 103653, 'mahasiswa', 'Ghaida', '<p>Hari ini saya baru selesai konseling dengan pak yafi. Beliau mewajibkan saya untuk hadir konseling lagi minggu depan untuk melakukan empty chair. Untuk itu, mohon kakak admin untuk menjadwalkan saya kembali dengan pak yafi nggih.</p>', '2026-05-12 09:48:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18044, 4344, 103658, 'mahasiswa', 'Bintang Widjaya', '<p>Note: klo ngetik nya belibet mon maap. jadi gini kayak apa ya susah buat tidur malam kayak bnyk yg kepikiran di otak pas mau tidur trs mimpi gue tuh kayak di suatu tempat hitam gelap bgt dimana" nya gada cahaya n lgsg bangun kadang. gue gabisa tidur klo blm nyentuh jam 2 atau 3 pagi. gue jg kehilangan sebagian memori gue kecuali memori yg paling bahagia buat gue atau memori yg paling buat trauma. gue juga kehilangan hampir 70% memori gue sblm SMA. hal ini sebenr nya dah dari udah dari kuliah smt 3 si... trs klo soal hal baru kadang masuk kadang ngga tapi klo mau bener" nancep di otak terutama isi mata kuliah jadi kyk harus ngorbanin memori yg ada waktu dulu biasanya ga sadar begitu sadar pas ada orang yg ngmng soal sesuatu tapi gue ga connect n ngerasa ga pernah, pas ditunjukkin bukti baru ngeh klo lupa bnyk hal. trs klo pas mau tidur lbh ke bengong aja gitu, terus ntah kadang tiba" nangis sendiri, kadang tangan tremor sendiri. sering si bahkan hampir tiap hari kecuali gue ada sesuatu yg bnr" cape bgt baik fisik atau otak yaa lgsg tidur. pernah gue anggep biasa kek nyoba nulis sesuatu tiap kepikiran sesuatu tapi pas gue tulis selalu berhenti di satu hal abis tuh kek ati tu nyess banget klo parah ya sampe nangis. trs biasanya klo lagi ga tenang atau mau tidur kan gue dengerin instrumen musik kan... nah akhir" ni tiap denger musik itu selalu nangis gatau kenapa padahal biasanya biasa aja lbh ke nenangin gue. </p>', '2026-05-12 11:00:19');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18045, 4345, 103659, 'mahasiswa', 'Firania', '<p>selama kuliah walaupun ada teman banyak, tapi selalu merasa sendirian dan selalu merasa tertinggal karena dari diri sendiri tidak punya keahlian secara khusus, sehingga ada tekanan sendiri untuk menjalankan perkuliahan dan ada efek ke akademik yang sering remed dan selalu performa akademik sangat menurun</p>', '2026-05-12 11:15:25');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18046, 4346, 103660, 'mahasiswa', 'Malika Sihite', '<p>Saya lelah</p>', '2026-05-12 11:34:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18047, 4346, 36, 'admin', 'Aura Ratu', '<p dir="ltr">Selamat Siang, Kak Malika ! :)</p> <p dir="ltr">Terima kasih karena telah menghubungi Layanan Konseling UB. Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Kami sangat memahami pasti situasi ini tidak mudah untuk dilalui. Kami mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail rasa lelah yang Anda alami?<br />2. Dari yang Anda rasakan, sudah berapa lama masalah tersebut berdampak ke kegiatan keseharian Anda? Dan apakah dampak yang muncul akibat permasalahan tersebut?<br />3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?<br />4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr"><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-05-12 12:00:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18048, 4345, 36, 'admin', 'Aura Ratu', '<p dir="ltr">Selamat Siang, Kak Firania ! :)</p> <p dir="ltr">Terima kasih karena telah menghubungi Layanan Konseling UB. Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Kami sangat memahami pasti situasi ini tidak mudah untuk dilalui. Kami mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail masalah yang Anda alami? Ketika dalam kondisi apa hal tersebut muncul?<br />2. Dari yang Anda rasakan, sudah berapa lama masalah tersebut berdampak ke kegiatan keseharian Anda?<br />3. Apa hal yang sudah Anda lakukan atau rencanakan untuk mengatasi hal tersebut?<br />4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr"><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-05-12 12:02:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18049, 4345, 103659, 'mahasiswa', 'Firania', '<p>1. Saat buka ig sering muncul apresiasi prestasi dari fakultas ke mahasiswa tentang lomba essay, poster, olimpiade membuat syaa merasa ada tekanan sendiri, karena saya ngerasa lomba lomba yang bisa diikuti sebagai anak fkg pasti lonba akademik, sedangkan saya sendiri tidak pernah sama sekali mengikuti lomba akademik, saya dulu saat sma lebih sering ikut lomba non akademik seperti marching band dan saat kuliah tidak mungkin saya ikutin karena tidak ada waktu. saya berusaha alihkan semua pikiran saya ikutin banyak kepanitiaan tapi masih belum efektif karena saya merasa panitia aja masih belum cukup untuk memenuhi pikiran saya yang selama ini saya pikirin untuk berprestasi. terutama saat semester 1 saya tidak pernah menang dalam lomba business proposal dan proposal pkm di tingkat fakultas. dengan hal ini semua membuat saya merasa tidak cukup, dan tidak pintar sehingga saat kerja kelompok dll saya takut berpendapat karena saya merasa pola pikir saya masih tidak cukup pintar dan kritis dibanding mereka mereka yang sepantaran saya.</p> <p>2. semenjak bilan november 2025 syaa sudah mulai merasakannya hingga berefek saya merasa tidak pantas berteman dengan teman saya yang selalu juara pada tiap lomba dan mikir kok dia bisa ya aku kok engga. sehingga saat libur semester tidak ada kepikiran lagi. tapi belakangan ini mulai bulan maret sampai sekarang pikiran saya sering muncul lagi yang membuat saya setiap hari ovt, dan bahakan sering tidak fokus saat kuliah ditambah ada beberapa masalah pribadi terkait masalah sosial saya di kuliah sehingga sering tidak fokus pas menjalankan kuliah dan sering ke distract.</p> <p>3. Saya berusaha untuk ikut hampir semua panitia setiap dari pihak bem ada oprec kepanitiaan, akan tetapi menurut saya masih tidka efektig untuk mengalihkan pikiran saya yang sangat ribut ini. saya uyga berusaha mengubah pola belajar saya tapi masih kurang efektif. dengan semua hal yang membuat saya tertekan saya sering kabur dari semua hal untuk tidur atau makan lebih banyak dari jumlah porsi yang biasanya saya makan.</p> <p>4. saya berharap bisa mendengarkan isi pikiran dan isi hati syaa yang selalu saya simpan, dan tidak pernah saya bicarakan kepada orang lain terutama saya tidak pernah memberi tau orang tua saya terkait tekanan saya selama perkuliahan ini. walaupun emang saya memilih fkg bukan dari tekanan orang tua, keluarga dll, saya berharap bisa membuat saya lebih yakin lagi untuk menjalankan dunia perkuliahan yang tidak mudah. serta membuat pikiran saya menjadi lebih terbuka dan memikirkan ketenangan saya dan tidak hanya memikirkan orang lain.</p>', '2026-05-12 12:25:54');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18050, 4346, 103660, 'mahasiswa', 'Malika Sihite', '<p>Terima kasih kak. </p> <p>1. Saya lelah dengan keadaan orang-orang yang selalu menekan dan menyalah pahami perilaku saya. Saya juga lelah dengan seluruh kegiatan kepanitiaan yang sedang saya jalani. Saya juga lelah sebagai seorang teman dimana saya harus memahami tanpa dipahami kembali. Saya dianggap tidak menghiraukan capek mereka, sementara saya disini selalu berusaha untuk memahami dan tidak mengganggu mereka. Mereka bilang saya terlalu banyak mengeluh, padahal kenyataannya saya memang tidak punya sandaran untuk berkeluh kesah, hanya kata-kata keluhan singkat yang dapat saya ucapkan. Saya pikir, tidak ada lagi yang akan menemani saya. Saya sendirian. </p> <p>2. Sudah 1-2 bulan. Namun akhir-akhir ini menjadi jauh lebih parah. Saya berhenti melakukan kegiatan yang saya sukai. Saya hanya melakukan kegiatan kepanitiaan sebagai formalitas, Saya masuk ke kelas dengan lesu dan minum berbicara. </p> <p>3. Saya hanya ingin punya harapan hidup kembali. </p> <p>4. Supaya saya tidak melakukannya. </p> <p><br /></p>', '2026-05-12 12:51:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18051, 4347, 103661, 'mahasiswa', 'Monika Labibah', '<p>Saya orang yang pelupa, entah sejak kapan karena saya sudah lupa. Banyak hal dalam kehidupan yang bagi saya adalah pengalaman tidak mengenakkan, jadi sebenarnya mudah lupa dapat dipercayai sebagai "kekuatan". Tapi tidak semua pengalaman bisa dilupakan, terkadang ada yang sangat diingat dan ketika kepikiran bakal bikin gelisah. Walaupun ingatannya tidak utuh, perasaan pada pengalamn itu bisa begitu melekat. Pada suatu titik, saya merasa kekuatan untuk melupakan ini tidak terkontrol, rasanya seperti saya tidak menghidupi hidup saya sendiri. Saya bingung saya ini apa dan siapa. Kadang ketika ada teman lama mengenang masa lalu seperti "eh km inget gak waktu itu kita blabla", cuma saya yang ga ingat. Bahkan saking parahnya saya ga bisa ingat teman saya itu siapa, kita pernah berbuat apa, bagaimana hubungan di antara dia dengan saya. Akibatnya saya tidak pernah punya teman yang sangat dekat, karena mau bagaiamanapun suatu hari yang tidak ada apa apa, saya tiba tiba ga ingat sesuatu tentang mereka. Saya bisa minta diingatkan berkali kali, tapi tidak semua orang bisa menoleransi itu, apalagi di lingkungan kerja apabila suatu hari nanti mungkin saya diijinkan takdir untuk bekerja. Pengalaman itu membuat saya cemas, namun cemas tersebut tidak hanya berasal dari satu sumber. <br /></p> <p>Saya orang yang introvert. Energi mudah habis tapi memulihkannya lama. Saya bisa tidak keluar rumah sama sekali berbulan bulan dan tidak mengobrol dengan siapapun kecuali diperlukan (spt diajak bicara keluarga satu rumah). Tetapi keluarga saya menganggap itu aneh, jadi dari dulu saya sering "dipaksa" berinteraksi dengan orang lain. Di sekolah, saya pendiam dan hampir ga punya teman. Tapi karena pendiam itu, alhasil sering ditunjuk oleh guru untuk menjawab/praktek. Masalahnya, saya lelet karena pelupa, jadi sering panik sendiri dan tidak bisa bicara. Dahulu, ketika bicara, baik dengan teman, keluarga, atau saudara, seringkali tidak didengar atau tidak dipedulikan, sehingga pengalaman tersebut tertanam dan lama kelamaan saya tidak ambil repot untuk berpikir. Dengan begitu saya sering diam dan ga punya opini serta sulit menyampaikan diri. Banyak pengalaman "tidak bisa menjawab" yang membuat malu, merasa bodoh, dihakimi, takut dicap aneh, dan berekspektasi akan dimarahi orang. Di rumah, saya dimarahi karena malas malasan mengerjakan pekerjaan rumah (menunda), tidak bisa disuruh beli sesuatu (takut bertemu orang), tidak mau ikut les dan sekolah (takut bertemu orang (2)), susah dibangunin (sering mimpi, ga mau bangun) karena jenuh hidup. Makanya sering dibandingin sama temen/sodara sendiri. Saya makin takut sama orang lain (krn merekalah penyebab kenapa saya dimarahi, bukan?), dan benci orang. Kepala saya sering tanpa disadari berprasangka buruk, berpikir orang lain akan mengakibatkan hal buruk, seperti jadi bahan perbandingan. Oleh karena itu, saya menarik diri. </p> <p>Tempat publik adalah neraka bagi saya. Saat presentasi, tangan saya kadang bergetar, jantung berdegup kencang, keringat dingin, pandangan kabur, dan akan jadi lebih parah jika berusaha melihat audiens. Gejala tersebut variatif dalam berbagai situasi, paling parah rasanya hingga ingin pingsan (walau tidak pernah pingsan sungguhan). Di tempat publik, kalau terlalu lama berada di luar, saya akan merasa pusing ringan, mata berat. Jika melakukan suatu kebodohan atau kesalahan, ada beberapa pengalaman yang tidak dapat saya lupakan dan menjadi sumber kegelisahan. Kalaupun lupa, terkadang muncul kembali dalam bentuk "mimpi buruk" saat tidur. </p> <p>Bagi saya, mimpi adalah pengalaman realistis yang memengaruhi ingatan dan kondisi saya di hari ketika terbangun. Mimpi yang dialami sering merupakan pengalaman sehari hari, acak, namun sering merupakan bentuk kecemasan. Contohnya, di mimpi sudah mengerjakan pr, ternyata di kehidupan nyata belum. Sehingga bangun tidur bukannya segar, malah panik. Dengan setting sehari-hari, ingatan saya terdistorsi berpikir bahwa situasi tertentu harusnya sudah terjadi, padahal ternyata itu hanyalah ingatan mimpi dan tidak terjadi di kenyataan. Selain itu, ketika bermimpi, tidur saya jadi lebih lama dan sulit dibangunkan. Maka dari itu, saya menghindari tidur karena saya terlalu sering bermimpi. Malam hari jadi pelarian, saya memutuskan untuk beraktivitas selagi mengambil jarak jauh dari orang orang. Alhasil, tidur berantakan dan mengganggu semua aktivitas sehari-hari. Bangun, tidur lagi, bangun, tidur lagi, merasa masih capek. Kadang saya berharap suatu hari saya tidak perlu membuka mata lagi. Ada hari di mana capek karena mimpi "buruk", ada juga karena berusaha memenuhi ekspektasi untuk jadi orang "normal". Anehnya, saya jauh lebih sering bermimpi (bisa sampai berturut turut seminggu) ketika ada di rumah. Saat di kos, kuantitas mimpi jauh menurun, bisa tidur nyenyak. Setiap balik ke rumah saat liburan, saya bermimpi lagi dan alhasil tidur terlalu panjang dan jadi begadang. Rasanya seperti jadi versi yang berbeda, masuk ke dunia yang berbeda </p> <p>Sekarang, saya semester 10, masih skrispi :) menunda nunda mengerjakan demi menghindari situasi yang membuat cemas: <strong>presentasi dan sidang. </strong>tidak ditunda pun memang ga mampu sih, ngerjain skripsi bikin stres.</p>', '2026-05-12 13:39:53');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18052, 4179, 103467, 'mahasiswa', 'Zahwa sholihatunnisa', '<p>boleh kak, kira2 kalo tanggal 25 di jam berapa dan kalo tanggal 26 di jam berapa ya kak</p>', '2026-05-12 13:59:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18053, 4348, 103563, 'mahasiswa', 'Muhammad Iswandoko', '<p>Aku cukup bingung dengan kondisi sekarang, karena sebelumnya permasalahan Saya adalah mungkin percintaan, keluarga dan lingkungan. Sebelumnya telah membaik dengan selesainya permasalahan percintaan. Tetapi sekarang Saya kembali terbawa dengan kondisi keluarga, finansial, dan lingkungan, kondisi keluarga cukup memprihatinkan dengan tidak adanya aset diam maupun berjalan, ditambah lingkungan telah sangat membantu Saya, Saya tidak mau ingin menjadi beban ke mereka dengan kondisi Saya saat ini.<br /><br />Saya telah jauh berkembang dari sebelumnya dalam akademik, sekarang sudah cukup mengerti dengan materi perkuliahan, bahkan Saya juga tertarik dan sedang mengikuti volunteer SLDPI untuk perkembangan karakter diri Saya, dengan melihat kondisi tiap individu dari sisi mereka juga, Saya sangat bersyukur dengan apa yang sudah Tuhan berikan kepada Saya.<br /><br />Saya terbantu, sangat terbantu oleh Dosen-dosen, Teman-teman Saya, bahkan orang yang belum Saya kenal. bantuan tersebut Saya fokuskan untuk perkembangan akademik Saya yang memang terbukti jauh membaik, Saya belum bisa memberikan kepada orang tua Saya karena Saya prioritaskan perkuliahan Saya di sini. Saya tidak ingin merepotkan permasalahan keluarga kepada orang sekitar Saya, karena hal tersebut tidak terlalu memiliki hubungan dengan orang lain, termasuk orang sekitar Saya di malang ini.<br /><br />Sejauh Saya bisa membantu orang tua Saya adalah dengan mengorbankan beberapa fasilitas yang sudah diberikan kepada Saya oleh orang tua seperti kendaraan pun sudah dijual untuk membantu kondisi ini, beasiswa sudah Saya tempuh, bahkan dengan kondisi yang sebenarnya tidak memungkinkan untuk mendapatkannya. Sebagai konteks, Saya mendaftar Universitas Brawijaya melalui jalur mandiri, dan IPK Saya juga cukup memprihatinkan sebelumnya, sehingga Saya sangat bersyukur dapat memperoleh beasiswa tersebut untuk membantu kondisi ini. Namun, tidak kunjung membaik.<br /><br />Dengan segala rasionalitas. terlebih sebelumnya Saya kurang paham dalam meregulasi perasaan serta emosional Saya sendiri, keadaan ini sangat membuat Saya bingung akan bagaimana dan harus apa, Saya tidak ingin untuk kembali merepotkan sekeliling Saya, Saya sudah cukup terbantu untuk Saya sendiri.<br /><br /><br /></p>', '2026-05-12 14:09:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18054, 4343, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat siang, Kak Ghaida!<br /><br />Mohon maaf untuk jadwal minggu depan dengan Pak Yafi sudah penuh. Tersedia kembali berkisar pada tanggal 25 Mei-5 Juni 2026. Apakah kakak berkenan kami jadwalkan pada tanggal tersebut? Kami tunggu konfirmasinya ya...<br /><br />Terima Kasih. <br />Salam Hangat, <br />Layanan Konseling UB</p>', '2026-05-12 14:16:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18055, 4346, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat sore, Kak Malika! <br /><br />Terima kasih telah menghubungi Layanan Konseling UB. Terima kasih karena telah berkenan untuk menceritakan permasalahan Anda dan apa yang Anda rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Terima kasih karena Anda sudah mau dan mampu terus bertahan sampai sejauh ini, yaa. Untuk membantu mencari jalan keluar dari permasalahan Anda, kami menyarankan Anda untuk bertemu dengan peer counselor kami. Kami memiliki jadwal yang tersedia pada <strong>Senin, 18 Mei 2026 pukul 13.00</strong> secara <strong>offline</strong>. Apakah Anda berkenan kami jadwalkan pada waktu tersebut? Kami tunggu konfirmasinya, yaa. <br /><br />Terima kasih :) <br />Salam hangat, <br />Layanan Konseling UB.</p>', '2026-05-12 15:14:28');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18056, 4179, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat malam, Kak Zahwa!<br /><br />Kami memiliki jadwal tersedia di minggu depan pada hari <strong>Jumat, 22 Mei 2026 pukul 08.00 </strong>secara <strong>offline</strong>. Apakah Kakak berkenan kami jadwalkan pada waktu tersebut? Dan untuk jadwal di tanggal 25 dan 26 belum keluar untuk saat ini, jika Kakak berkenan pada tanggal tersebut akan kami infokan kembali nanti, ya Kak.<br /><br />Kami tunggu konfirmasinya:)<br /><br />Terima Kasih.<br />Salam Hangat, <br />Layanan Konseling UB</p>', '2026-05-12 17:33:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18057, 4349, 103663, 'mahasiswa', 'Giana Widiasih', '<p>Saya orang yang memang overthinking, hanya saja, saya tidak pernah bisa mengendalikan overthinking tersebut hingga akhirnya saya merasa terbebani sekarang. Saya mudah takut, dan trauma (adanya rasa malu) ketika saya melakukan hal salah bahkan sekecil pun dan tidak orang yang mengomentari hal tersebut. Saya juga memiliki rasa mudah tersinggung dengan orang lain, entah dari tindakan mereka yang menurut saya berlebihan, saya mudah menyalahartikan tindakan seseorang ke saya hingga menimbulkan perspektif negatif. Saya cukup sudah menanggulangi itu, tetapi rasanya masih ada rasa tersinggung ke beberapa orang. Kemudian, semenjak kuliah sebenarnya saya merasa sulit fokus, mudah teralihkan, dan terkadang suka bengong. Selama perkuliahan, pemahaman saya ke materi berdasarkan semangat atau mood saya saja, motivasi saya untuk memahami materi semakin menurun. Saya merasa terganggu, dan beberapa waktu IPK saya tidak naik secara signifikan. Kondisi ini juga menghambat saya untuk mengerjakan dan memahami tugas akhir saya sendiri.</p>', '2026-05-12 17:46:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18058, 4344, 36, 'admin', 'Aura Ratu', '<p>Selamat malam, Kak Bintang! <br /><br />Terima kasih telah menghubungi Layanan Konseling UB. Terima kasih karena telah berkenan untuk menceritakan permasalahan Anda dan apa yang Anda rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Terima kasih karena Anda sudah mau dan mampu terus bertahan sampai sejauh ini, yaa. Untuk membantu mencari jalan keluar dari permasalahan Anda, kami menyarankan Anda untuk bertemu dengan psikolog kami yaitu Ibu Dian. Kami memiliki jadwal yang tersedia pada <strong>Kamis, 21 Mei 2026 pukul 14.00</strong> secara <strong>offline</strong>. Apakah Anda berkenan kami jadwalkan pada waktu tersebut? Kami tunggu konfirmasinya, yaa. <br /><br />Terima kasih :) <br />Salam hangat, <br />Layanan Konseling UB.</p>', '2026-05-12 19:21:13');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18059, 4350, 103664, 'mahasiswa', 'Kriston Manurung', '<p>Pasangan saya orangtuanya hanya tinggal ibunya saja, kebetulan ibunya merupakan penyandang disabilitas dan tidak bekerja, pacar saya baru baru saja lulus dari UB, nah selama kuliah pacar saya itu dibiayain oleh saudara dan saudari ibunya atau bisa disebut paman dan Tante nya, selepas yudisium pacar saya itu pulang ke daerah asalnya dan tinggal di rumah nenek nya pacar saya, selama dia tinggal disana pacar saya itu selalu apply lowongan kerja yang ada, kebetulan dia keterima dan sampai tahap interview di kota malang, nah keluarga nya tidak setuju pacar saya pergi wawancara keluar kota selain di daerahnya, alhasil pacar saya mengalah untuk pertama kalinya, setelah dia mengalah pacar saya itu dikata katain sama keluarga nya karena dia ga bekerja atau masih nganggur setelah dengar perkataan itu pacar saya daftar lowongan kerja lagi, dan  keterima dan sampe interview di malang lagi, alhasil untuk kedua kalinya pacar saya disuruh keluarganya untuk tidak keluar kota melamar kerja dan menyuruh pacar saya mencari kerja sekitar daerah tempat tinggal nya di kabupaten Tangerang, nah setelah hal itu pacar saya mengalah dan kembali beraktifitas seperti biasanya, lalu selang beberapa lama, pacar saya disuruh ga usah melamar kerja lagi dan disuruh di rumah aja, sedangkan pacar saya ingin bebas mau keluar, karena kalau dirumah pacar saya selalu dibatasi dan jarang keluar rumah bahkan sekedar ingin belanja harian saja ada batas waktunya..hasilnya pacar saya merasa muak dan tersiksa akhir nya dia coba melamar kerja lagi dan dapat interview dimalang kemudian keluarga nya mengetahui nya dan cerita nya masih panjang lagi dipertemuan akan saya jelaskan detailnya </p> <p>Hal ini penting karena beberapa kali pacar saya sering bilang "kalo aku ga ada, kamu sedih gak" selain itu pacar saya pernah sayat dibagian pergelangan tangan atau selfharm, kejadian ini bikin saya ga tenang dan jelas ini mengganggu konsentrasi saya</p> <p>Mohon bantuannya </p>', '2026-05-12 20:33:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18060, 4345, 36, 'admin', 'Aura Ratu', '<p>Selamat Malam, Kak Firania! :)<br /><br />Terima kasih telah menjawab pertanyaan dari Layanan Konseling UB dan telah berkenan untuk menceritakan terkait permasalahan Kakak dan apa yang Kakak rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk mendiskusikan lebih lanjut mengenai hal yang Kakak ceritakan, apakah kiranya bersedia melakukan konseling secara offline dengan <strong>peer counselor perempuan</strong> kami? Untuk jadwal yang terdekat ada di hari <strong>Senin</strong>, <strong>18 Mei 2026 pukul 09.00 WIB secara offline dengan Kak Alya.</strong><br /><br />Kami tunggu konfirmasinya yaa :)</p> <p>Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-05-12 21:31:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18061, 4347, 36, 'admin', 'Aura Ratu', '<p>Selamat Malam, Kak Monika! :)<br /><br />Terima kasih telah menghubungi Layanan Konseling UB dan telah berkenan untuk menceritakan terkait permasalahan Kakak dan apa yang Kakak rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk mendiskusikan lebih lanjut mengenai hal yang Kakak ceritakan, apakah kiranya bersedia melakukan konseling dengan <strong>Psikolog perempuan</strong> kami, Yaitu Bu Naila. Untuk jadwal yang terdekat ada di hari <strong>Senin</strong>, <strong>25 Mei 2026 pukul 10.00 WIB secara online. </strong>Apakah kakak berkenan kami jadwalkan konseling pada jadwal tersebut?<br /><br />Kami tunggu konfirmasinya yaa :)</p> <p>Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-05-12 21:36:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18062, 4349, 36, 'admin', 'Aura Ratu', '<p>Selamat Malam, Kak Giana! :)<br /><br />Terima kasih telah menghubungi Layanan Konseling UB dan telah berkenan untuk menceritakan terkait permasalahan Kakak dan apa yang Kakak rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk mendiskusikan lebih lanjut mengenai hal yang Kakak ceritakan, apakah kiranya bersedia melakukan konseling secara offline dengan <strong>peer counselor perempuan</strong> kami? Untuk jadwal yang terdekat ada di hari <strong>Rabu</strong>, <strong>20 Mei 2026 pukul 11.00 WIB secara offline dengan Kak Raisya.</strong><br /><br />Kami tunggu konfirmasinya yaa :)</p> <p>Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-05-12 21:48:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18063, 4351, 102899, 'mahasiswa', 'Aditya Ramadhan', '<p>dimana saya memiliki beberapa permasalahan, salah satunya adalah saya memiliki hubungan yang cukup toxic yang dimana pasangan saya kurang memahami saya sebagai anak organisasi kampus yang kurang mempunyai waktu luang, dan juga orang tua saya yang sering mengambil jatah uang kipk saya hingga meminta ttd dan ktp saya untuk meminjam utang kepada koperasi</p>', '2026-05-12 21:51:18');
