INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18099, 3588, 33, 'admin', 'Nafa Tsaniya', '<p>Baik kak, terima kasih atas konfirmasinya. Akan kami jadwalkan pada <strong>Senin, 18 Mei 2026 pukul 12.00</strong> secara <strong>offline</strong>. Untuk informasi selanjutnya akan kami sampaikan melalui WhatsApp saat akan mendekati sesi konseling.<br /><br />Terima Kasih.<br />Salam Hangat,<br />Layanan Konseling UB</p>', '2026-05-13 15:41:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18100, 4356, 103668, 'mahasiswa', 'Mahayu Rainy', '<p>Ayah aku kan selingkuh hampir 10 tahun terus aku merasa pressure aja gitu kadang suka cape sendiri, bunda sering cerita ke aku jadi ke akunya jadi ikut bingung sebenernya aku tidak mempersalahkan bunda, cuman aku harus gmn ya, kadang aku juga suka nangis hampir sering kalo lagi cape atau gmn nanti mikirin keluarga ku terus, ga tau nyambung apa engga tapi aku suka banget nunda kerjaan</p>', '2026-05-13 23:37:40');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18101, 4179, 103467, 'mahasiswa', 'Zahwa sholihatunnisa', '<p>ohh iya kak saya salah kira tanggal, sebenernya saya ada jadwal kuliah kak jam segitu, kira2 kalau diganti jam 11 apakah bisa</p>', '2026-05-14 00:25:44');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18102, 4357, 103669, 'mahasiswa', 'Naira Nafizha', '<p>merasa ingin mati, menghilang, kabur dari semuanya. capek, muak. cemas berlebihan, ovt, emosi yang sering membeludak entah itu senang atau sedih selalu dialami secara membeludak. keinginan untuk melukai diri sendiri. merasa sangat takut untuk dibuang, di replace. merasa sendiri like i got no one, i dont have anyone to call my own person or to depend on, not even myself. merasa tidak percaya diri, sulit mengontrol emosi. mau pergi, mau menghilang, mau kabur, tapi takut mati tapi aku mau pergi. aku ini kenapa ya begini? i feel too much that i dont know what to explain anymore.</p>', '2026-05-14 02:34:21');
