INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18183, 4349, 103663, 'mahasiswa', 'Giana Widiasih', '<p>Selamat malam, Kak. Mohon maaf mengganggu waktunya, dan mohon maaf sekali karena saya baru saja mendapatkan jadwal reschedule mata kuliah yang bertabrakan dengan jadwal konseling yang sudah ditetapkan kemarin. Apakah masih diperbolehkan untuk direschedule kembali ya, Kak? Mohon maaf sekali dikarenakan untuk mata kuliah yang direschedule besok merupakan mata kuliah wajib. Terima kasih dan mohon maaf sebelumnya </p>', '2026-05-18 19:01:05');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18184, 4379, 103550, 'mahasiswa', 'Najwa rahman', '<p>permasalahan banyak,saya ingin didengar,karena sebenrnya masalah saya ga cuma pribadi tapi banyak sekali dan bercabang suka sekali kepala saya berisik dan sering memiliki keinginan untuk mengakhiri diri sendiri,akhir ini saya sering selfharm lagi</p>', '2026-05-18 19:23:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18185, 4375, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak, terima kasih atas konfirmasinya. </p> <p>Untuk informasi selanjutnya akan kami hubungi melalui WhatsApp yaa, Kak :)</p> <p>Terima kasih.</p> <p>Salam hangat,<br />Layanan Konseling UB. </p>', '2026-05-18 19:29:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18186, 4349, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak Giana, terima kasih atas konfirmasinya. Diperbolehkan yaa Kak, tetapi mohon maaf untuk jadwal yang tersedia hanya ada pada minggu depan (25, 26, dan 29), apakah Anda berkenan? </p> <p>Kami tunggu konfirmasinya yaa, Kak :) </p> <p>Terima kasih.</p> <p>Salam hangat,<br />Layanan Konseling UB. </p>', '2026-05-18 19:32:13');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18187, 4379, 34, 'admin', 'Heidemarie Gunarso', '<p dir="ltr">Selamat malam, Kak Najwa Rahman!</p> <p dir="ltr">Terima kasih karena telah menghubungi Layanan Konseling UB. Terima kasih telah berkenan berbagi perasaan dan cerita yang Anda miliki. Kami sangat memahami pasti situasi ini tidak mudah untuk dilalui. Kami mengapresiasi keberanian Anda untuk pada akhirnya bisa membawa diri Anda perlahan lahan memahami kondisi ini. Untuk memperdalam pemahaman kami terhadap permasalahan Anda, berkenankah Anda menjawab beberapa pertanyaan berikut:</p> <p dir="ltr">1. Apakah Anda berkenan mendeskripsikan lebih detail masalah yang Anda alami? Menurut Anda apa penyebab hal tersebut terjadi?<br />2. Dari yang Anda rasakan, sudah berapa lama masalah tersebut berdampak ke kegiatan keseharian Anda?<br />3. Dari yang Anda sampaikan sebelumnya, selfharm yang dilakukan dalam bentuk apa? <br />4. Apa harapan Anda menghubungi layanan kami?</p> <p dir="ltr">Apapun jawaban Anda akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Anda tidak berkenan menjawab, Anda juga bisa menyampaikan bahwa Anda tidak berkenan menjawab pertanyaan yang kami tanyakan.</p> <p dir="ltr"><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.<br /></p>', '2026-05-18 19:33:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18188, 4378, 34, 'admin', 'Heidemarie Gunarso', '<p>Selamat malam, Kak Tiara! </p> <p>Terima kasih telah menghubungi Layanan Konseling UB. Terima kasih karena telah berkenan untuk menceritakan permasalahan Anda dan apa yang Anda rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Terima kasih karena Anda sudah mau dan mampu terus bertahan sampai sejauh ini, yaa :)</p> <p>Untuk membantu mencari jalan keluar dari permasalahan Anda, kami menyarankan Anda untuk bertemu dengan peer counselor kami terlebih dahulu. Kami memiliki jadwal yang tersedia pada hari <strong>Rabu, 20 Mei 2026 pukul 14.00 WIB </strong>dengan <strong>peer counselor perempuan</strong>. Apakah Anda berkenan kami jadwalkan pada waktu tersebut? </p> <p>Kami tunggu konfirmasinya yaa, Kak :)</p> <p>Terima kasih.</p> <p>Salam hangat,<br />Layanan Konseling UB. </p>', '2026-05-18 19:40:31');
