INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18220, 4387, 34, 'admin', 'Heidemarie Gunarso', '<p>Selamat siang, Kak Ajeng N!</p> <p dir="ltr">Baik Kak, terima kasih atas jawabannya. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan peer counselor kami terlebih dahulu? Namun karena jadwal minggu ini sudah penuh, jadwal dengan peer counselor kami baru tersedia pada hari <strong>Selasa, 26 Mei 2026 pukul 11.00 WIB dengan peer counselor perempuan.</strong> </p> <p dir="ltr">Kami tunggu konfirmasinya yaa, Kak :)</p> <p dir="ltr">Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB<br /></p>', '2026-05-20 13:08:08');
