INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18338, 4408, 35, 'admin', 'Melsy Nemasari', '<p>Selamat siang Kak Aliyah :)<br /><br />Mohon maaf sebelumnya Kak, terdapat perubahan pada jadwal konseling menjadi hari Jumat, 29 Mei 2026 pukul 11.00 dengan psikolog perempuan kami apakah berkenan Kak? Mohon maaf atas ketidaknyamanannya ya. Kami tunggu konfirmasinya :)</p>', '2026-05-25 11:25:03');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18339, 4414, 35, 'admin', 'Melsy Nemasari', '<p>Selamat siang Kak Rido! :)<br /><br />Jika konseling dengan peer counselor laki-laki kami pada hari Jumat, 29 Mei 2026 pukul 08.00 secara offline apakah berkenan Kak? Kami tunggu konfirmasinya yaa :)<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.<br /></p>', '2026-05-25 11:42:32');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18340, 4420, 35, 'admin', 'Melsy Nemasari', '<p>Selamat siang Kak Fauza! :)<br /><br />Terkait hal itu, jika menemukan 404 page not found dapat menekan ''home page'' kemudian bisa melakukan check ticket status dengan memasukkan email serta nomor tiket ya, Kak. Seperti yang tertera di highlight instagram kami: <a href="https://www.instagram.com/s/aGlnaGxpZ2h0OjE4MDQ2MDA4NjUwNzY1NTk1?story_media_id=3890913539322466344&amp;igsh=MWhhZ3E1a2I2MHVwNg==">https://www.instagram.com/s/aGlnaGxpZ2h0OjE4MDQ2MDA4NjUwNzY1NTk1?story_media_id=3890913539322466344&amp;igsh=MWhhZ3E1a2I2MHVwNg==</a><br /><br />Terima kasih.<br />Salam hangat, <br />Layanan Konseling UB.</p>', '2026-05-25 11:49:11');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18341, 4401, 35, 'admin', 'Melsy Nemasari', '<p>Selamat siang, Kak Adwinda :)<br /><br />Terima kasih atas konfirmasinya. Untuk jadwal Bu Ikaf pada minggu ini dan minggu depan sudah penuh, Kak. Apakah berkenan jika konseling dilakukan pada <strong>8 Juni 2026 pukul 10.30 secara offline</strong>? Kami tunggu konfirmasinya yaa :)<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.<br /></p>', '2026-05-25 12:05:14');
