INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18352, 4401, 35, 'admin', 'Melsy Nemasari', '<p>Selamat malam, Kak Adwinda :)<br /><br />Untuk jadwal psikolog kami di minggu ini sudah penuh semua Kak. Untuk jadwal minggu depan terdapat Bu Yunita pada 3 Juni pukul 11.00 dan terdapat Bu Dian serta Pak Yafi yang untuk jamnya masih belum tersedia Kak :)<br /><br />Salam hangat,<br />Layanan Konseling UB.<br /></p>', '2026-05-25 19:20:05');
