INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18354, 4422, 35, 'admin', 'Melsy Nemasari', '<p>Halo, selamat malam Kak Nafidza :)<br /><br />Terima kasih karena telah menghubungi layanan kami dan terima kasih karena telah berkenan untuk menceritakan hal tersebut kepada kami. Terima kasih karena telah bertahan hingga sekarang ya Kak. Kami memahami bahwa pasti sangatlah tidak mudah dalam menjalaninya. Oleh karena itu, kami merekomendasikan untuk melakukan sesi konseling dengan <strong>psikolog perempuan kami pada hari Selasa, 26 Mei 2026 pukul 13.00 secara offline/online? </strong>Mohon konfirmasinya ya Kak :)<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-05-25 19:34:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18355, 4403, 35, 'admin', 'Melsy Nemasari', '<p>Baik, terima kasih atas konfirmasinya ya Kak. Untuk informasi selanjutnya akan kami sampaikan melalui WhatsApp ya Kak :)<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-05-25 19:39:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18356, 4422, 101735, 'mahasiswa', 'Nafidza Aulia', '<p>Halo Layanan Konseling UB,</p> <p>Terima kasih telah merespon tiket saya. Saya bersedia untuk melakukan konseling pada tanggal 26 Mei 2026 pada pukul 13.00 secara online. Terima Kasih Banyak</p> <p>Salam hangat,</p> <p>Nafidza<br /><br /></p>', '2026-05-25 19:42:48');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18357, 4423, 103727, 'mahasiswa', 'Abraham denggan', '<p>Merasa berat menjalani jurusan farmasi,merasa ternyata tidak sanggup menjalaninya,merasa jurusannya ini berat tapi tidak worth it dengan masa depan</p>', '2026-05-25 19:46:56');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18358, 4422, 35, 'admin', 'Melsy Nemasari', '<p>Baik, terima kasih atas konfirmasinya. Izin bertanya Kak. Apabila konseling dilakukan secara offline apakah berkenan Kak? :)</p>', '2026-05-25 20:00:55');
