INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18423, 4367, 103678, 'mahasiswa', 'Nayla', '<p>1. sampai sekarang saya masih was was jika berada di kamar mandi, dan akhir akhir ini saya sering mimpi kejadian tersebut bahkan orangnya bisa saudara saya sendiri. saya paling tidak suka jika mimpi kejadian itu lagi karena pasti akan teringat setelah bangun. kalau saya vc dengan keluarga dan ada dia sebenarnya saya malu, tapi karna orang orang di rumah dan dia sudah lupa dengan kejadian tersebut, saya tidak pernah mengatakan bahwa saya tidak nyaman.</p> <p>2. tidak ada, saya kira bisa hilang sendiri.</p> <p>3. saya berharap bisa melupakan kejadian tersebut atau jika hal tersebut tidak mungkin, semoga nanti bisa sedikit mengurangi rasa takut dan malu saya</p>', '2026-05-30 00:12:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18424, 4427, 32, 'admin', 'Almira Jessenia', '<p>Baik terima kasih konfirmasinya kak, akan kami jadwalkan yaa pada tanggal tersebut..<br />Untuk lokasi nanti berada di Gedung Rektorat Universitas Brawijaya Lantai 1, untuk alur lebih lengkap dan reminder akan kami hubungi langsung melalui WhatsApp nantinya saat h-1 pelaksanaan konseling :) <br /><br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-05-30 00:16:05');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18425, 4431, 32, 'admin', 'Almira Jessenia', '<p>Selamat malam Kak Vieny :)<br />Untuk hari Jumat tanggal 5 Juni 2026 perkiraan kakak bisa di pukul berapa? agar kami sesuaikan dengan kesediaan peer counselor kami pada hari tersebut. Kami tunggu konfirmasinya yaa..<br /><br />Salam hangat,<br />Layanan Konseling UB<br /></p>', '2026-05-30 00:18:55');
