INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18427, 4434, 103736, 'mahasiswa', 'Alya Kumala', '<p>awalnya mungkin krn capek burnout tugas, tp krn capek itu kdg ak jd refleksi diri gtu tapi ke arah negatif, aku kmrn mnegesampingkan apa yg ak rasain krn org lain jg merasa hal yg sama, aku merasa ak gapantes buat ngerasa terpuruk krn temenku juga ada lah gt. tp grgr it ak bnrn jd down bgt, akhirny ak menarik diri dr temen temen aku, aku cmn muncul kl bahas tugas dan tanggung jwb aku, aku jg gak main medsos krn bnyk topik yg bikin ak kepikiran walau ujungny ak ttp kelikiran, ak ngerasa gabisa ngerasain ssuatu hingga ak nyakitin diri walaupun gak seberapa dan gak ngebekas, smua itu jg ngimbas ke bagaimana kluarga ak ngeliat aku, aku jd kliatan suka marah, aku kliatan diem terus, aku jg tdr terus krn ak gamau dealing reality, ak jg smpet tengkar sm ortu krn ak ngerasa ak kurang dihargai walaupun aku paham kenapa mereka punya pemikiran sprti itu. aku gabisa bilang apa apa ke org tuaku krn pun merka gamau paham. kayak kadang ak capek aja, aku capek merasa gak dihargai, aku pun capek jd org yg terlalu mengerti, dari kecil selalu begitu. dan tiap episode down gini ak sllu ngerasa aku pengen udahan, secara ak gamau idup lg tp ak gamau mati jg.</p>', '2026-05-30 11:08:21');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18428, 4431, 32, 'admin', 'Almira Jessenia', '<p>Baik, terima kasih konfirmasinya kak. Untuk itu, kami memiliki jadwal tersedia dengan peer counselor perempuan kami di hari Jumat, 5 Juni 2026 pukul 11.00 WIB secara offline, apakah kiranya berkenan jika dijadwalkan pada tanggal tersebut? Kami tunggu konfirmasinya yaa..<br /><br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-05-30 11:37:48');
