INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18460, 4440, 103741, 'mahasiswa', 'Krisma Sansa', '<p>Rasanya lelah sekali ketika harus hidup dalam kepura-puraan di tengah lingkungan yang menuntut konformitas, sementara di dalam diri, aku mengalami krisis spiritual dan identitas yang mendalam. Aku merasa terasing dari keyakinan masa kecilku yang terasa hampa dan meninggalkan trauma sosial, namun di saat yang sama, aku merasa sangat tertarik dengan jalan spiritualitas lain yang benar-benar menyentuh hatiku. Ironisnya, ruang aman yang ingin kutuju itu justru terasa menutup pintunya rapat-rapat karena orientasi seksualku yang dianggap tidak selaras dengan ajaran yang ada.<br /></p>', '2026-05-31 12:01:50');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18461, 4441, 101002, 'mahasiswa', 'Mohammad', '<p>Assalamualaikum, saya Mohammad Avil Abianto dari fakultas ilmu budaya dengan prodi pendidikan bahasa Jepang dan NIM sebagai berikut: NIM 215110607111010<br /></p> <p>Berhubungan dengan konseling sebelumnya dan arahan Pak Yafi. Saya ingin melakukan konseling lanjutan dengan beliau jika memang beliau ada jadwal yang tersedia di bulan Juni. <br /><br />Sekian atas perhatiannya terima kasih~</p>', '2026-05-31 13:24:36');
