INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18464, 4441, 35, 'admin', 'Melsy Nemasari', '<p>Waalaikumussalam Kak Avil, untuk jadwal Pak Yafi minggu depan sudah penuh Kak. Lalu, untuk tanggal 8-12 Pak Yafi terdapat acara sehingga tidak dapat melaksanakan konseling. Jadwal terdekat Pak Yafi saat ini yaitu pada 15-19 Juni Kak. Apakah berkenan jika kami jadwalkan pada tanggal tersebut? Mungkin dari Kak Avil bersedia konseling pada tanggal berapa kah? Kami tunggu konfirmasinya yaa :)<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-05-31 15:40:39');
