INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18471, 4442, 103742, 'mahasiswa', 'Nouvi Nabila', '<p>saya sangat sibuk organisasi dan kepanitiaan. sedangkan bingung ini sebenernya ayahnya mau kemana. apa yang dikejar.. trs aku mulai ngerasa organisasi ini kurang worthit. aku sangat ketinggalan di bidang akademik. tapi jujur aku udah usahain yg terbaik buat keduanya. tpi ketika ga sesuai ekspetasi akuu,,, aku terlalu pressure diri aku bangettt. aku butuh nasehat dan saran dari orang yg lebih berpengalaman dan bisa memahami aku.aku ovt in semua bangett. bukan tekanan dari akademik dan organisasi saja  juga.</p> <p>banyak banget yg pengen saya konsulin. soalnya kalo ke temen ituu pasti ada rasa ga lega nya. masih ada yg aku tutup2in ketika cerita</p>', '2026-05-31 22:09:13');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18472, 4442, 103742, 'mahasiswa', 'Nouvi Nabila', '<p>saya selalu dihantui rasa cemas. kaya aku ngerasa semua yg aku kerjain ini banyak banget. dan aku takut ga maksimal. dann apakah ini semua worth it? aku merasa berkomperisi dgn orang lain. sumpah rasa ini mengganggu banget</p>', '2026-05-31 22:21:16');
