INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18485, 4441, 101002, 'mahasiswa', 'Mohammad', '<p>Selamat malam, mohon maaf atas keterlambatan konfirmasinya dikarenakan tidak bisa log in. Untuk tanggalnya saya bisa di tanggal 15 Juni. Namun jika ada perubahan jadwal atau penuh atau hal lainnya. Maka bisa otomatis di ubah oleh pihak konseling UB di rentang tanggal 16 dan 18-19 Juni. Sebab hanya pada tanggal 17 saya menjalani UAS di minggu tersebut.<br /><br />Terima kasih dan mohon maaf atas keterlambatannya.</p>', '2026-06-01 18:06:00');
