INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18505, 4449, 103749, 'mahasiswa', 'Fariza Riskyana', '<p>Daya ingat saya menurun drastis bahkan bisa dengan mudah melupakan suatu hal dalam hitungan menit/jam, sehingga mempengaruhi proses belajar dan akademik saya, serta mengganggu keseharian saya</p>', '2026-06-02 12:35:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18506, 4447, 103747, 'mahasiswa', 'Binsar Panggabean', '<p>1. Kalau untuk mendeskripsikan saya masih belum bisa, sebenarnya bukan masalah besar tetapi saya selalu kepikiran dengan hal tersebut.</p> <p>2.hampir 3 minggu, dan saya lebih nyaman tetap di kost, tidak ada gangguan pola makan dan tidur</p> <p>3. rencananya sudah banyak tetapi saya tidak tahu apakah rencana saya sudah tepat atau tidak</p> <p>4. memberikan solusi semisal nantinya saya sudah berkenan untuk menceritakannya</p>', '2026-06-02 12:53:42');
