INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18515, 4453, 103753, 'mahasiswa', 'Riveira Gunawan', '<p>Keluargaku ditipu dan hilang ratusan juta, masih punya aset berharga tapi sekarang ayahku pengangguran dan aku bingung sama biaya akademik ku yang bener2 tinggi. Ditambah sampe skrg aku belum ada beasiswa yang nyantol satupun. Terus aku juga ngerasa kalo im not good enough for everyone. Kayak, akutuh udah berusaha semaksimal mungkin tp aku ttp merasa ga cukup. Terus aku ngerasa kalau aku ga dapetin kasih sayang dari org yang aku cinta sebagaimana aku pengen dicintai. </p>', '2026-06-02 22:31:49');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18516, 4454, 103517, 'mahasiswa', 'Andini Rahmah', '<p>pada konsleing sebelumnya (20 mei 2026), saya diarahkan untuk membuat tiket konseling lanjutan untuk 2 minggu setelahtanggal 20 mei lalu.</p>', '2026-06-03 00:02:12');
