INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18555, 4466, 103765, 'mahasiswa', 'Nashwa Aneira', '<p>adanya masalah pribadi yakni hutang menyebabkan akademik saya downfall dan hari hari saya tidak berjalan sesuai dengan yang saya inginkan. Padahal awalnya hutang itu tidak untuk gaya hidup atau foya foya melainkan memang kebutuhan karna tidak ingin membebani orang tua, ternyata sekarang malah itu membuat saya semakin down dan bingung ini arahnya akan bagaimana </p>', '2026-06-05 09:11:14');
