INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18696, 4490, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak, terima kasih atas konfirmasinya. Mohon maaf Kak, hari Selasa kami tidak ada konseling karna tanggal merah. Jika kami jadwalkan konseling pada hari <strong>Rabu, 17 Juni 2026 pukul 09.00 WIB dengan peer counselor perempuan secara offline/online, </strong>apakah berkenan?</p> <p>Kami tunggu konfirmasinya yaa, Kak :)</p> <p>Terima kasih. <br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-06-10 21:37:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18697, 4490, 103101, 'mahasiswa', 'Janet', '<p>Baik kak, saya berkenan untuk offline. Mohon untuk informasi lebih lanjut mengenai konselingnya ya kak. Terimakasih sebelumnya.</p>', '2026-06-10 22:10:27');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18698, 4492, 102080, 'mahasiswa', 'Muhammad Ardiansyah', '<p>Eh tanggal 3 Juni, Kak. Jadi saya mau konseling lanjutan dari konseling yang sudah dilakukan dengan Pak Yafi pada tanggal 3 Juni, Kak. Maaf tadi kalimatnya rancu</p>', '2026-06-10 22:32:09');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18699, 4490, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak, terima kasih atas konfirmasinya. </p> <p>Untuk informasi selanjutnya, akan kami hubungi melalui WhatsApp yaa, Kak :)</p> <p>Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB. </p>', '2026-06-11 09:40:15');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18700, 4492, 34, 'admin', 'Heidemarie Gunarso', '<p>Baik Kak, untuk jadwal konseling dengan Pak Yafi hanya tersedia pada tanggal 22-26 Juni 2026, apakah Kakak berkenan pada tanggal tersebut?</p> <p>Kami tunggu konfirmasinya yaa, Kak :)</p> <p>Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB. </p>', '2026-06-11 09:43:41');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18701, 4486, 103774, 'mahasiswa', 'Felisita Setiawati', '<p>Selamat pagi, </p> <p>Mohon maaf sebelumnya baru membalas, izin menjawab pertanyaan yang diberikan ya. Sebenarnya saya bingung harus ngapain. Karena sejujurnya saya lagi takut juga buat keluar dan bertemu banyak orang karena ketrigered dan jadi overthinking sendiri. Saya mungkin sekarang cukup konseling emosional saja dulu. Karena memang saya memiliki permasalahan yang cukup serius mengenai anxiety dan depresi. Sudah pernah ke psikolog cuman saya masih belom bisa mengelola stres saya. Dan yang saya harapkan dari konseling ini saya bisa mengatur pikiran saya agar tidak begitu cemas dan kalau memang dosen saya masih tetap seperti itu ingin minta bantuan untuk diskusi dengan dosen saya tersebut. Terimakasih sebelumnya</p>', '2026-06-11 10:02:34');
