INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18717, 4493, 33, 'admin', 'Nafa Tsaniya', '<p>Baik Kak, akan kami jadwalkan pada waktu tersebut. Untuk waktu konselingnya kira-kira sekitar 1 jam, namun bisa kurang atau lebih menyesuaikan dengan situasi dan kondisi. Untuk informasi selanjutnya akan kami sampaikan melalui WhatsApp saat akan mendekati sesi konseling.<br /><br />Terima Kasih.<br />Salam Hangat,<br />Layanan Konseling UB<br /></p>', '2026-06-12 08:01:58');
