INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18879, 4541, 103826, 'mahasiswa', 'Rifdah Marindra', '<p>Akhir- akhir ini saya mengalami insomnia (sebenarnya sejak dulu). Kadang saya baru bisa tidur di jam 3 pagi dan bahkan tidak bisa tidur sama sekali. Hal ini terus terjadi antara sering tidur dalam jangka yang lama atau kurang tidur. Saya kadi suka menunda- nunda pekerjaan. Dulu saya masih bisa belajar untuk ujian semester, tapi sekarang untuk fokus membaca materi saja sulit. Selain itu kadang saya secara sengaja mengabaikan tugas saya. Contoh, anggota tim mengirim pesan kepada saya dan hanya saya baca lewat pesan bar, baru 1 bulan kemudian saya punya kemauan untuk membuka dan membalas pesan tersebut. Fokus saya juga kacau (sering doom scrolling internet). Semua hal itu lama- lama mengganggu produktivitas saya.  </p>', '2026-06-21 14:59:28');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18880, 4529, 32, 'admin', 'Almira Jessenia', '<p>Baik terima kasih konfirmasinya Kak, jika sesi konseling lanjutan di jadwalkan pada hari <strong>Senin, 29 Juni 2026 pukul 10.00 secara online</strong> dengan <strong>Ibu Naila</strong> apakah berkenan? Kami tunggu konfirmasinya yaa..<br /><br />Salam hangat,<br />Layanan Konseling UB</p>', '2026-06-21 15:06:08');
