INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18913, 4546, 103208, 'mahasiswa', 'Karinda Shahira', '<p>Konseling terkait keperluan Tugas Akhir dengan judul:</p> <p dir="ltr"><strong>PERANCANGAN BUKU ILUSTRASI INTERAKTIF DENGAN PENDEKATAN </strong><strong><em>SELF-ESTEEM AWARENESS</em></strong> <strong>DALAM PENGELOLAAN STRES PADA MAHASISWA USIA 20–24 TAHUN</strong></p> <p><br /></p>', '2026-06-22 16:24:26');
