INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18937, 4550, 33, 'admin', 'Nafa Tsaniya', '<p>Mohon maaf Kak, terkait permasalahan  yang sedang Kakak alami kami belum bisa membantu karena di LKM ini berfokus pada layanan konseling terkait kesehatan mental mahasiswa. Untuk membantu mencari jalan keluar dari permasalahan Kakak, Kakak bisa menghubungi pihak advokesma dari BEM Fakultas, atau langsung menemui pihak kemahasiswaan Fakultas Kakak. <br /><br />Terima Kasih.<br />Salam Hangat,<br />Layanan Konseling UB</p>', '2026-06-24 12:59:06');
