INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18943, 4549, 33, 'admin', 'Nafa Tsaniya', '<p>Baik Kak, akan kami masukan antrian  terlebih dahulu ya karena kebetulan jadwal minggu depan masih belum tersedia. Jika jadwalnya sudah tersedia akan kami hubungi melalui WhatsApp ya, Kak. <br /><br />Terima Kasih. <br />Salam Hangat,<br />Layanan Konseling UB</p>', '2026-06-24 18:31:12');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18944, 4553, 102895, 'mahasiswa', 'Satria Yuswanto', '<p>Sebentar lagi KKN fakultas akan berjalan dan saya merasa sangat takut untuk melakukannya apalagi selama 1 bulan penuh. Mungkin jika aku mengikuti KKN fakultas yang biasa dan bukan KKN fakultas pulang kampung, aku tidak akan merasa setakut ini, mungkin karena "teman-temanku" yang secara akademik sudah berjalan jauh sehingga aku merasa insecure ketika bersama mereka. Bahkan ketika survey kemarin aku tetap merasa tidak bisa dekat dengan mereka secara baik, hubungan mereka dengan satu sama lain sudah terlalu kental sehingga aku merasa sulit untuk berteman dengan orang-orang yang sudah berteman sejak lama. Aku butuh bantuan, aku butuh bantuan untuk setidaknya merasa kuat selama 1 bulan kedepan menghadapi KKN dengan orang-orang yang tidak sefrekuensi denganku.</p>', '2026-06-24 18:36:08');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18945, 4552, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat malam, Kak  Aveline!<br /><br />Sudah kami jawab pada e-ticket #004548 yaa. Bisa di cek disana<br /><br />Terima Kasih.<br />Salam Hangat,<br />Layanan Konseling UB</p>', '2026-06-24 18:43:02');
