INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18974, 4558, 103843, 'mahasiswa', 'Laudya Priyanto', '<p>Akhir-akhir ini saya sering bingung sama diri sendiri, ada masalah dengan pasangan dan keluarga, dan saya merasa kehilangan arah.</p>', '2026-06-27 13:48:35');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18975, 4529, 33, 'admin', 'Nafa Tsaniya', '<p>Apakak Kakak tetap berkenan untuk kami jadwalkan di hari Senin seperti jadwal sebelumnya?</p>', '2026-06-27 16:30:58');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18976, 4556, 33, 'admin', 'Nafa Tsaniya', '<p>Baik kak, jika Kakak memang lebih nyaman untuk berkonsultasi dengan psikolog perempuan, kami memiliki jadwal tersedia dengan psikolog perempuan kami yaitu Bu Dian pada <strong>Selasa, 30 Juni 2026 pukul 14.00</strong>, apakah Kakak berkenan kami jadwalkan pada waktu tersebut? Dan terkait konseling online, untuk teknisnya itu melalui Google Meet ya ka:)</p>', '2026-06-27 16:33:34');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18977, 4548, 33, 'admin', 'Nafa Tsaniya', '<p>Baik kak, jika Kakak memang lebih nyaman untuk berkonsultasi dengan psikolog perempuan, kami memiliki jadwal tersedia dengan psikolog perempuan kami yaitu Bu Dian pada <strong>Kamis, 2 Juli 2026 pukul 14.00</strong>, apakah Kakak berkenan kami jadwalkan pada waktu tersebut?</p>', '2026-06-27 16:36:59');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18978, 4555, 33, 'admin', 'Nafa Tsaniya', '<p>Untuk saat ini, jam operasional layanan kami hanya sampai pukul 16.00 Kak, jadi untuk berkonsultasi dengan psikolog di malam hari mohon maaf masih belum bisa. Namun kami memiliki jadwal tersedia di hari Selasa, 30 Juni 2026 pukul 19.00 dengan konselor umum kami, apakah Kakak berkenan jika kami jadwalkan dengan konselor kami pada waktu tersebut?</p>', '2026-06-27 16:41:33');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18979, 4556, 103840, 'mahasiswa', 'Bening Hati', '<p>Baik kak, saya berkenan untuk konsultasi dengan Bu Dian di hari Selasa pukul 14.00 WIB. Terima kasih atas informasinya kak  Konsultasi ini berarti secara offline di gedung rektorat UB ya kak? </p>', '2026-06-27 16:46:10');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18980, 4559, 103844, 'mahasiswa', 'Taura', '<p>haloo permisi pak/bu, perkenalkan saya taura maba fh 2026</p> <p>maaf sebelumnya pak/bu,saya izin tanya.. </p> <p>sebelumnya saya sudah daftar kipk, tapi non eligible alhasil tidak lolos seleksi.. apakah di ub ini ada kuota kipk tambahan/susulan? jika ada mohon saya dibantu agar dapat mengikuti tahapan kipk susulan tersebut.</p> <p>saya sangat amat berharap jika bisa mendapatkan kipk susulan ini dikarenakan keadaan ekonomi keluarga sedang menurun, desil juga tidak sesuai dengan kenyataan yang ada. sudah pernah mengusulkan penurunan desil namun sampai sekarang belum ada pihak yang verifikasi.<br /></p> <p>terimakasih </p>', '2026-06-27 18:33:46');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18981, 4555, 103839, 'mahasiswa', 'Aulia Alfida', '<p>Baik kak, terima kasih atas informasinya. Namun mohon maaf, apa boleh di hari Kamis/Jumat saja ya? </p>', '2026-06-27 19:39:02');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18982, 4560, 103844, 'mahasiswa', 'Taura', '<p>permisi bapak/ibu,perkenalkan saya taura maba fh 2026</p> <p>maaf sebelumnya pak/bu,saya izin tanya.. </p> <p>sebelumnya saya sudah daftar kipk, tapi status non eligible alhasil tidak lolos seleksi.. apakah di ub ini ada kuota kipk tambahan/susulan tidak yaa?? mohon dibantu bapak/ibu. </p> <p>karena saya sangat amat membutuhkan bantuan kipk ini dikarenakan keadaan ekonomi sedang menurun, desil saya 6-10 namun juga tidak sesuai dengan keadaan asli. sudah sempat mengajukan perubahan status desil tapi hingga sekarang pun tidak ada tindakan lanjutan. maka dari itu apabila ada kuota susulan untuk kipk mohon saya dibantu agar dapat mengikuti tahapan yang ada.</p> <p>terimakasih </p>', '2026-06-27 20:30:16');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18983, 4557, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat siang, Kak Nazifa! <br /><br />Terima kasih telah menghubungi Layanan Konseling UB dan mohon maaf baru memberikan respon dikarenakan banyaknya antrian yang masuk. Terima kasih karena telah berkenan untuk menceritakan permasalahan Anda dan apa yang Anda rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk membantu kami lebih memahami permasalahan Anda, silahkan untuk menjawab pertanyaan berikut, yaa:<br />1. Sejak kapan Kakak melakukan self harm dan berapa kali hal tersebut terjadi?</p> <p dir="ltr">2. Dari apa yang Kakak rasakan, apakah hal tersebut berpengaruh ke keseharian Kakak (seperti pola makan, pola tidur, aktivitas sosial dll)?<br />3. Apakah ada hal yang pernah Kakak coba untuk mengatasa hal tersebut? Jika ada, apakah itu membantu?<br />4. Apa harapan Kakak untuk melakukan konseling bersama Layanan Konseling UB?</p> <p><br /></p> <p dir="ltr">Apapun jawaban yang Kakak berikan akan sangat membantu kami untuk memetakan permasalahan lebih lanjut. <br /><br />Terima kasih. <br />Salam hangat, <br />Layanan Konseling UB.</p>', '2026-06-28 11:23:00');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18984, 4554, 33, 'admin', 'Nafa Tsaniya', '<p>Baik ka, akan kami jadwalkan pada waktu tersebut ya. Untuk informasi selanjutnya akan kami sampaikan  melalui WhatsApp saat akan mendekati sesi konseling.<br /><br />Terima Kasih.<br />Salam Hangat,<br />Layanan Konseling UB<br /></p>', '2026-06-28 11:24:29');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18985, 4558, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat siang, Kak Laudya!<br /><br />Terima kasih telah menghubungi Layanan Konseling UB dan mohon maaf baru memberikan respon dikarenakan banyaknya antrian yang masuk. Terima kasih karena telah berkenan untuk menceritakan permasalahan Anda dan apa yang Anda rasakan. Kami dapat memahami bahwa hal tersebut tentunya tidaklah mudah. Untuk membantu kami lebih memahami permasalahan Anda, silahkan untuk menjawab pertanyaan berikut, yaa:</p> <p>1. Apakah Kakak berkenan untuk mendeskripsikan permasalahan tersebut lebih detail? Bagaimana hal tersebut terjadi?</p> <p>2. Apakah hal ini berdampak ke kegiatan keseharian Kakak (mood, pola tidur, pola tidur, akademik, dll)?</p> <p>3. Apa hal yang sudah Kakak lakukan untuk mengatasi hal tersebut, dan apakah cara tersebut sudah efektif?</p> <p>4. Apa harapan Kakak menghubungi layanan kami?</p> <p>Apapun jawaban Kakak akan membantu kami memetakan permasalahan dan menentukan langkah selanjutnya. Jika Kakak tidak berkenan menjawab, Kakak juga bisa menyampaikan bahwa tidak berkenan menjawab pertanyaan yang kami tanyakan. Kami tunggu jawabannya yaa..<br /><br />Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB.</p>', '2026-06-28 11:29:51');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18986, 4556, 33, 'admin', 'Nafa Tsaniya', '<p>Baik ka, akan kami jadwalkan pada waktu tersebut ya. Betul ka konseling nya dilaksanakan di gedung rektorat lantai 1 ya. Untuk informasi selanjutnya akan kami sampaikan melalu WhatsApp saat akan mendekati sesi konseling.<br /><br />Terima Kasih.<br />Salam Hangat,<br />Layanan Konseling UB <br /><br /></p>', '2026-06-28 11:33:06');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18987, 4559, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat siang, Kak Taura!<br /><br />Terima kasih telah menghubungi Layanan Konseling UB dan mohon maaf baru memberikan respon dikarenakan banyaknya antrian yang masuk. Mohon maaf Kak, terkait permasalahan yang sedang Kakak alami kami belum bisa membantu karena di LKM ini berfokus pada layanan konseling terkait kesehatan mental mahasiswa. Untuk mencari jalan keluar dari permasalahan Kakak, Kakak bisa menghubungi pihak advokesma dari BEM Fakultas, atau langsung menemui pihak kemahasiswaan Fakultas Kakak ya. Karena biasanya untuk mengurus mengenai KIPK, uang kuliah dan hal-hal terkait itu dari pihak fakultas nya masing masing. <br /><br />Terima Kasih.<br />Salam Hangat,<br />Layanan Konseling UB<br /></p>', '2026-06-28 11:41:13');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18988, 4560, 33, 'admin', 'Nafa Tsaniya', '<p>Selamat siang, Kak Taura!<br /><br />Pesan Kakak sudah kami balas pada e-ticket #004558 ya. <br /><br />Terima Kasih.<br />Salam Hangat,<br />Layanan Konseling UB</p>', '2026-06-28 11:42:31');
INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (18989, 4555, 33, 'admin', 'Nafa Tsaniya', '<p>Mohon maaf, Kak. Untuk jadwal konselor kami di malam hari hanya tersedia di hari Selasa dan Rabu. Kira-kira Kakak memiliki waktu kosong di tanggal berapa dan pukul berapa? Agar kami bantu carikan jadwal yang sesuai:)</p>', '2026-06-28 11:46:18');
