INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (19001, 4548, 34, 'admin', 'Heidemarie Gunarso', '<p>Selamat siang, Kak Naswa! <br /><br />Kami izin bertanya untuk nomor yang bisa kami hubungi berapa yaa, Kak? Karena nomor WhatsApp yang ada di eticket ada kesalahan sehingga tidak bisa kami hubungi. Kami mohon bantuannya yaa, Kak :)</p> <p>Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB. </p>', '2026-06-29 11:04:12');
