INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (19033, 4565, 103247, 'mahasiswa', 'Alberta', '<p><span dir="auto"><span dir="auto"><span dir="auto"><span dir="auto">1. Penyebab masalah ini biasanya dipicu oleh masalah pribadi seperti mendapatkan hate komen tanpa sebab, kecelakaan, dan beberapa masalah lainnya</span></span></span></span></p> <p><span dir="auto"><span dir="auto">2. masalah ini sudah terjadi cukup lama (tidak terhitung) ketika selalu muncul masalah kecil maka muncul halusinasi dan skenario yang ada dikepala dan bahkan saya bisa ga makan beberapa hari hanya mengandalkan segelas kecil air putih </span></span><br /></p> <p><span dir="auto"><span dir="auto"><span dir="auto"><span dir="auto">3. Saya hanya diam dan menangis karena saya bingung harus melampiaskan bagaimana jika saya berbicara saya selalu disalahkan. </span></span></span></span></p> <p><span dir="auto"><span dir="auto"><span dir="auto"><span dir="auto"><span dir="auto"><span dir="auto">4. Harapan saya ketika menghubungi layanan ini saya merasa bisa mengatasi ini dan menemukan solusi untuk mengatasi hal ini ketika terjadi lagi</span></span></span></span></span></span></p>', '2026-06-30 19:03:48');
