INSERT INTO ticket_messages (id, ticket_id, sender_id, sender_role, sender_name, body, created_at) VALUES (19035, 4565, 34, 'admin', 'Heidemarie Gunarso', '<p>Selamat malam, Kak Alberta! </p> <p>Mohon maaf atas keterlambatannya dalam membalas yaa, Kak. Baik Kak, terima kasih atas jawabannya. Kami dapat memahami bahwa hal tersebut pastilah tidak mudah bagi Anda. Untuk memproses apa yang Anda rasakan dan alami dengan cara yang paling adaptif, apakah Anda bersedia melakukan konseling dengan psikolog kami? Namun karena jadwal minggu ini sudah penuh, jadwal dengan psikolog kami baru tersedia pada <strong>minggu depan tanggal 6-10 Juli 2026</strong>. </p> <p>Kami tunggu konfirmasinya yaa, Kak :)</p> <p>Terima kasih.<br />Salam hangat,<br />Layanan Konseling UB. <br /></p>', '2026-06-30 23:33:37');
